const C: Record<string, string[]> = {"Mishneh Torah, Admission into the Sanctuary 1":["כָּל כֹּהֵן הַכָּשֵׁר לַעֲבוֹדָה אִם שָׁתָה יַיִן אָסוּר לוֹ לְהִכָּנֵס מִן הַמִּזְבֵּחַ וּלְפָנִים. וְאִם נִכְנַס וְעָבַד עֲבוֹדָתוֹ פְּסוּלָה וְחַיָּב מִיתָה בִּידֵי שָׁמַיִם שֶׁנֶּאֱמַר (ויקרא י ט) \"וְלֹא תָמֻתוּ\". וְהוּא שֶׁשָּׁתָה רְבִיעִית יַיִן חַי בְּבַת אַחַת מִיַּיִן שֶׁעָבְרוּ עָלָיו אַרְבָּעִים יוֹם. אֲבָל אִם שָׁתָה פָּחוֹת מֵרְבִיעִית יַיִן. אוֹ שָׁתָה רְבִיעִית וְהִפְסִיק בָּהּ. אוֹ מְזָגָהּ בְּמַיִם. אוֹ שֶׁשָּׁתָה יַיִן מִגִּתּוֹ בְּתוֹךְ אַרְבָּעִים אֲפִלּוּ יֶתֶר מֵרְבִיעִית. פָּטוּר וְאֵינוֹ מְחַלֵּל עֲבוֹדָה. שָׁתָה יֶתֶר מֵרְבִיעִית מִן הַיַּיִן אַף עַל פִּי שֶׁהָיָה מָזוּג וְאַף עַל פִּי שֶׁהִפְסִיק וְשָׁהָה מְעַט מְעַט חַיָּב מִיתָה וּפוֹסֵל הָעֲבוֹדָה:","הָיָה שִׁכּוֹר מִשְּׁאָר מַשְׁקִין הַמְשַׁכְּרִין אָסוּר לְהִכָּנֵס לַמִּקְדָּשׁ וְאִם נִכְנַס וְעָבַד וְהוּא שִׁכּוֹר מִשְּׁאָר מַשְׁקִין הַמְשַׁכְּרִין אֲפִלּוּ מִן הֶחָלָב אוֹ מִן הַדְּבֵלָה הֲרֵי זֶה לוֹקֶה וַעֲבוֹדָתוֹ כְּשֵׁרָה. שֶׁאֵין חַיָּבִין מִיתָה אֶלָּא עַל הַיַּיִן בִּשְׁעַת עֲבוֹדָה. וְאֵין מְחַלֵּל עֲבוֹדָה אֶלָּא שִׁכּוֹר מִן הַיַּיִן:","וּכְשֵׁם שֶׁאָסוּר לַכֹּהֵן לְהִכָּנֵס לַמִּקְדָּשׁ מִפְּנֵי הַשִּׁכְרוּת כָּךְ אָסוּר לְכָל אָדָם בֵּין כֹּהֵן בֵּין יִשְׂרָאֵל לְהוֹרוֹת כְּשֶׁהוּא שָׁתוּי. אֲפִלּוּ אָכַל תְּמָרִים אוֹ שָׁתָה חָלָב וְנִשְׁתַּבְּשָׁה דַּעְתּוֹ מְעַט אַל יוֹרֶה שֶׁנֶּאֱמַר (ויקרא י יא) \"וּלְהוֹרֹת אֶת בְּנֵי יִשְׂרָאֵל\". וְאִם הוֹרָה בְּדָבָר שֶׁהוּא מְפֹרָשׁ בַּתּוֹרָה עַד שֶׁיְּדָעוּהוּ הַצְּדוֹקִים מֻתָּר כְּגוֹן שֶׁהוֹרָה שֶׁהַשֶּׁרֶץ טָמֵא וְהַצְּפַרְדֵּעַ טָהוֹר וְהַדָּם אָסוּר וְכַיּוֹצֵא בָּזֶה:","וּמֻתָּר לְשִׁכּוֹר לְלַמֵּד תּוֹרָה וַאֲפִלּוּ הֲלָכוֹת וּמִדְרָשׁוֹת וְהוּא שֶׁלֹּא יוֹרֶה. וְאִם הָיָה חָכָם קָבוּעַ לְהוֹרָאָה לֹא יְלַמֵּד שֶׁלִּמּוּדוֹ הוֹרָאָה הִיא:","שָׁתָה כְּדֵי רְבִיעִית בִּלְבַד וְהָיָה בָּהּ מַיִם כָּל שֶׁהוּא. אוֹ יָשַׁן מְעַט אוֹ הָלַךְ כְּדֵי מִיל. כְּבָר עָבַר הַיַּיִן וּמֻתָּר לַעֲבֹד. אֲבָל אִם שָׁתָה יוֹתֵר מֵרְבִיעִית אֲפִלּוּ מָזוּג. שֵׁינַת מְעַט אוֹ הַדֶּרֶךְ מוֹסִיפִין בְּשִׁכְרוּתוֹ. אֶלָּא יִשְׁהֵא לְפִי הַשִּׁכְרוּת עַד שֶׁלֹּא יִשָּׁאֵר מִשִּׁכְרוּתוֹ שׁוּם דָּבָר שֶׁבָּעוֹלָם:","אַנְשֵׁי מִשְׁמָר מֻתָּרִין לִשְׁתּוֹת יַיִן בַּלֵּילוֹת אֲבָל לֹא בִּימֵי שַׁבָּתָן. וַאֲפִלּוּ שְׁאָר בָּתֵּי אָבוֹת שֶׁל מִשְׁמָר שֶׁאֵין עֲבוֹדָתָן הַיּוֹם. שֶׁמָּא תִּכְבַּד הָעֲבוֹדָה עַל אַנְשֵׁי בֵּית אָב שֶׁל יוֹם וְיִצְטָרְכוּ לַאֲחֵרִים מֵאַנְשֵׁי מִשְׁמַרְתָּן לְסַיְּעָן. וְאַנְשֵׁי בֵּית אָב שֶׁל אוֹתוֹ הַיּוֹם אֲסוּרִים לִשְׁתּוֹת בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה. שֶׁמָּא יִשְׁתֶּה בַּלַּיְלָה וְיַשְׁכִּים לַעֲבוֹדָתוֹ וַעֲדַיִן לֹא סָר יֵינוֹ מֵעָלָיו:","כָּל כֹּהֵן שֶׁיּוֹדֵעַ מֵאֵי זֶה מִשְׁמָר הוּא וּמֵאֵי זֶה בֵּית אָב הוּא וְיוֹדֵעַ שֶׁבָּתֵּי אֲבוֹתָיו קְבוּעִים בַּעֲבוֹדָה [הַיּוֹם] אָסוּר לוֹ לִשְׁתּוֹת יַיִן כָּל אוֹתוֹ הַיּוֹם. הָיָה יוֹדֵעַ מֵאֵי זֶה מִשְׁמָר הוּא וְאֵינוֹ מַכִּיר בֵּית אָב שֶׁלּוֹ אָסוּר לוֹ לִשְׁתּוֹת כָּל אוֹתָהּ שַׁבָּת שֶׁמִּשְׁמַרְתּוֹ עוֹבְדִין בָּהּ. לֹא הָיָה מַכִּיר מִשְׁמַרְתּוֹ וְלֹא בֵּית אֲבוֹתָיו הַדִּין נוֹתֵן שֶׁאָסוּר לִשְׁתּוֹת יַיִן לְעוֹלָם. אֲבָל תַּקָּנָתוֹ קַלְקָלָתוֹ וַהֲרֵי הוּא מֻתָּר לִשְׁתּוֹת תָּמִיד שֶׁאֵינוֹ יָכוֹל לַעֲבֹד עַד שֶׁיִּקָּבַע בְּבֵית אָב שֶׁלּוֹ וּבְמִשְׁמַרְתּוֹ:","כֹּהֵן שֶׁגָּדַל שְׂעָרוֹ אָסוּר לוֹ לְהִכָּנֵס מִן הַמִּזְבֵּחַ וְלִפְנִים וְאִם נִכְנַס וְעָבַד חַיָּב מִיתָה בִּידֵי שָׁמַיִם כְּשִׁכּוֹר שֶׁעָבַד. שֶׁנֶּאֱמַר (יחזקאל מד כא) \"וְיַיִן לֹא יִשְׁתּוּ כָּל כֹּהֵן\" (יחזקאל מד כ) \"וְרֹאשָׁם לֹא יְגַלֵּחוּ וּפֶרַע לֹא יְשַׁלֵּחוּ\". מַה שְּׁתוּיֵי יַיִן בְּמִיתָה אַף מְגֻדְּלֵי פֶּרַע בְּמִיתָה:","וְאֵין פְּרוּעֵי הָרֹאשׁ מְחַלְּלִין עֲבוֹדָה אַף עַל פִּי שֶׁהוּא בְּמִיתָה עֲבוֹדָתוֹ כְּשֵׁרָה:","כְּשֵׁם שֶׁאֵין הַכֹּהֲנִים מֻזְהָרִין עַל הַיַּיִן אֶלָּא בִּשְׁעַת בִּיאָה לַמִּקְדָּשׁ כָּךְ אֵין אֲסוּרִין לְגַדֵּל פֶּרַע אֶלָּא בִּשְׁעַת בִּיאָה לַמִּקְדָּשׁ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּכֹהֵן הֶדְיוֹט. אֲבָל כֹּהֵן גָּדוֹל אָסוּר לְגַדֵּל פֶּרַע וְלִקְרֹעַ בְּגָדָיו לְעוֹלָם. שֶׁהֲרֵי תָּמִיד הוּא בַּמִּקְדָּשׁ. וּלְכָךְ נֶאֱמַר בּוֹ (ויקרא כא י) \"אֶת רֹאשׁוֹ לֹא יִפְרָע וּבְגָדָיו לֹא יִפְרֹם\":","כַּמָּה הוּא גִּדּוּל פֶּרַע. שְׁלֹשִׁים יוֹם כְּנָזִיר שֶׁנֶּאֱמַר בּוֹ (במדבר ו ה) \"גַּדֵּל פֶּרַע שְׂעַר רֹאשׁוֹ\" וְאֵין נְזִירוּת פְּחוּתָה מִשְּׁלֹשִׁים יוֹם. לְפִיכָךְ כֹּהֵן הֶדְיוֹט הָעוֹבֵד מְגַלֵּחַ מִשְּׁלֹשִׁים יוֹם לִשְׁלֹשִׁים יוֹם:","וְאַנְשֵׁי מִשְׁמָר אֲסוּרִין לְסַפֵּר וּלְכַבֵּס בְּשַׁבַּתָּן כְּדֵי שֶׁלֹּא יַעֲלוּ לְמִשְׁמַרְתָּן כְּשֶׁהֵן מְנֻוָּלִין אֶלָּא מְגַלְּחִין וְרוֹחֲצִין וּמְכַבְּסִין קֹדֶם שֶׁיַּעֲלוּ:","מִי שֶׁשָּׁלְמָה מִשְׁמַרְתּוֹ בְּתוֹךְ הָרֶגֶל מֻתָּר לְגַלֵּחַ בָּרֶגֶל. אֲבָל אִם שָׁלְמָה בְּעֶרֶב הָרֶגֶל אֵינוֹ מְגַלֵּחַ אֶלָּא בְּעֶרֶב הָרֶגֶל:","דִּין קְרוּעֵי בְּגָדִים וְדִין פְּרוּעֵי רֹאשׁ אֶחָד הוּא שֶׁנֶּאֱמַר (ויקרא י ו) \"רָאשֵׁיכֶם לֹא תִּפְרָעוּ וּבִגְדֵיכֶם לֹא תִפְרֹמוּ וְלֹא תָמֻתוּ\" הָא אִם עָבַד וְהוּא קְרוּעַ בְּגָדִים חַיָּב מִיתָה בִּידֵי שָׁמַיִם אַף עַל פִּי שֶׁעֲבוֹדָתוֹ כְּשֵׁרָה וְלֹא חִלְּלָהּ:","יֵרָאֶה לִי שֶׁכָּל כֹּהֵן הַכָּשֵׁר לַעֲבוֹדָה אִם נִכְנַס מִן הַמִּזְבֵּחַ וְלִפְנִים וְהוּא שְׁתוּי יַיִן אוֹ שִׁכּוֹר מִשְּׁאָר הַמְשַׁכְּרִין אוֹ פְּרוּעַ רֹאשׁ אוֹ קְרוּעַ בְּגָדִים כְּדֶרֶךְ שֶׁקּוֹרְעִין עַל הַמֵּתִים אַף עַל פִּי שֶׁלֹּא עָבַד עֲבוֹדָה הֲרֵי זֶה לוֹקֶה. הוֹאִיל וְהוּא רָאוּי לַעֲבוֹדָה וְנִכְנָס בִּשְׁעַת הָעֲבוֹדָה מְנֻוָּל כָּכָה וַהֲרֵי הוּא מֻזְהָר שֶׁלֹּא יִכָּנֵס:","וְדִין הַנִּכְנָס כָּכָה מִן הַמִּזְבֵּחַ וְלִפְנִים וְדִין הַיּוֹצֵא מִשָּׁם אֶחָד הוּא. כֵּיצַד. כְּגוֹן שֶׁשָּׁתָה רְבִיעִית יַיִן בֵּין הָאוּלָם וְלַמִּזְבֵּחַ אוֹ קָרַע בְּגָדָיו שָׁם וְיָצָא לוֹקֶה. וְכֵן אִם עָבַד בִּיצִיאָתוֹ חַיָּב מִיתָה:","וְכֵן אָסוּר לְכָל אָדָם בֵּין כֹּהֵן בֵּין יִשְׂרָאֵל לְהִכָּנֵס לַמִּקְדָּשׁ כֻּלּוֹ מִתְּחִלַּת עֶזְרַת יִשְׂרָאֵל וְלִפְנִים כְּשֶׁהוּא שְׁתוּי יַיִן אוֹ שִׁכּוֹר אוֹ פְּרוּעַ רֹאשׁ דֶּרֶךְ נִוּוּל אוֹ קְרוּעַ בְּגָדִים אַף עַל פִּי שֶׁאֵינוֹ בְּאַזְהָרָה. שֶׁאֵין זֶה כָּבוֹד וּמוֹרָא לַבַּיִת הַגָּדוֹל וְהַקָּדוֹשׁ שֶׁיִּכָּנֵס בּוֹ מְנֻוָּל. אֲבָל יִשְׂרָאֵל שֶׁגִּדֵּל שְׂעָרוֹ עַד שֶׁנַּעֲשָׂה מַחְלֶפֶת וְלֹא הָיָה דֶּרֶךְ נִוּוּל הֲרֵי זֶה מֻתָּר לְהִכָּנֵס לְעֶזְרַת יִשְׂרָאֵל:"],"Mishneh Torah, Agents and Partners 3":["מִי שֶׁהָיְתָה לוֹ קַרְקַע תַּחַת יַד אֶחָד אוֹ שֶׁהָיוּ לוֹ מִטַּלְטְלִין פִּקָּדוֹן וְרָצָה לַעֲשׂוֹת שָׁלִיחַ לָדוּן עִם זֶה וּלְהוֹצִיא הַקַּרְקַע אוֹ הַפִּקָּדוֹן מִתַּחַת יָדוֹ הֲרֵי זֶה כּוֹתֵב לוֹ הַרְשָׁאָה וְצָרִיךְ לִקְנוֹת מִיָּדוֹ שֶׁהִרְשָׁהוּ וְאוֹמֵר לוֹ דּוּן וּזְכֵה וְהוֹצֵא לְעַצְמְךָ וְכַיּוֹצֵא בְּעִנְיָנִים אֵלּוּ. וְאִם לֹא כָּתַב לוֹ אֵינוֹ יָכוֹל לָדוּן עִמּוֹ מִפְּנֵי שֶׁהוּא אוֹמֵר לוֹ אֵין אַתָּה בַּעַל דִּינִי. וְאַף עַל פִּי שֶׁכָּתַב לוֹ כֵן אֵינוֹ אֶלָּא שָׁלִיחַ וְכָל מַה שֶּׁיִּזְכֶּה בּוֹ הֲרֵי הוּא שֶׁל מְשַׁלְּחוֹ. וְכָל הַהוֹצָאוֹת שֶׁיּוֹצִיא הַשָּׁלִיחַ עַל דִּין זֶה שֶׁהֻרְשָׁה הֲרֵי הַמְשַׁלֵּחַ חַיָּב בָּהֶן. שֶׁכָּךְ כּוֹתְבִין בָּהַרְשָׁאָה כָּל שֶׁתּוֹצִיא בְּדִין זֶה עָלַי לְשַׁלְּמוֹ:","הִקְנָה לָזֶה שֶׁהִרְשָׁה שְׁלִישׁ אוֹ רְבִיעַ מַה שֶּׁיֵּשׁ לוֹ בְּיַד חֲבֵרוֹ הֲרֵי זֶה עוֹשֶׂה דִּין עַל הַכּל הוֹאִיל וְדָן עַל חֶלְקוֹ וַהֲרֵי הוּא בַּעַל דִּינוֹ בְּחֶלְקוֹ דָּן עַל הַכּל:","אֶחָד מִן הָאַחִים שֶׁלֹּא חָלְקוּ אוֹ מִן הַשֻּׁתָּפִין שֶׁבָּא לִתְבֹּעַ תּוֹבֵעַ עַל הַכּל. הוֹאִיל וְיֵשׁ לוֹ חֵלֶק בְּזֶה הַמָּמוֹן אֵין צָרִיךְ הַרְשָׁאָה מִשְּׁאָר שֻׁתָּפִין. וְאֵין הַשֻׁתָּף הָאַחֵר יָכוֹל לוֹמַר לְשֻׁתָּפוֹ שֶׁדָּן אִלּוּ הָיִיתִי אֲנִי שָׁם הָיִיתִי תּוֹבֵעַ טְעָנוֹת אֲחֵרוֹת וּמְחַיֵּב בַּעַל דִּינִי. שֶׁהֲרֵי אוֹמֵר לוֹ לָמָּה לֹא בָּאתָ לִתְבֹּעַ גַּם אַתָּה. לְפִיכָךְ אִם הָיָה בִּמְדִינָה אַחֶרֶת יֵשׁ לוֹ לַחְזֹר עַל בַּעַל הַדִּין וְלָדוּן עִמּוֹ וְלוֹמַר לוֹ אֲנִי אֵינִי מוֹדֶה בְּכָל מַה שֶּׁטָּעַן שֻׁתָּף שֶׁלִּי. לְפִיכָךְ יֵשׁ לַנִּתְבָּע לְעַכֵּב וְלוֹמַר לָזֶה אוֹ דּוּן עִמִּי בְּחֶלְקְךָ אוֹ הָבֵא הַרְשָׁאָה שֶׁהֲרֵי מָמוֹן שְׁנֵיכֶם בְּיָדִי וּשְׁנֵיכֶם בַּעֲלֵי דִּינִי וּלְמָחָר יָבוֹא אָחִיךָ אוֹ שֻׁתָּפְךָ וְיִתְבַּע גַּם הוּא:","הַבַּעַל בְּנִכְסֵי אִשְׁתּוֹ צָרִיךְ הַרְשָׁאָה. וְאִם יֵשׁ פֵּרוֹת בַּקַּרְקַע מִתּוֹךְ שֶׁיֵּשׁ לָדוּן עַל הַפֵּרוֹת שֶׁהֲרֵי הֵן שֶׁלּוֹ דָּן עַל הָעִקָּר וְאֵין צָרִיךְ הַרְשָׁאָה מֵאִשְׁתּוֹ שֶׁאִם אֵין לוֹ קַרְקַע אֵין לוֹ פֵּרוֹת:","מִי שֶׁהָיָה לוֹ בְּיַד חֲבֵרוֹ פִּקָּדוֹן אוֹ מִלְוֶה בֵּין בְּמִטַּלְטְלִין בֵּין מָעוֹת וְעָשָׂה שָׁלִיחַ בְּעֵדִים לַהֲבִיאָן לוֹ הָרְשׁוּת בְּיַד זֶה שֶׁהֵם אֶצְלוֹ אִם רָצָה לִתֵּן נִפְטָר וְאֵינוֹ חַיָּב בְּאַחֲרָיוּתָן שֶׁהֲרֵי נָתַן לִשְׁלוּחוֹ. וְאִם לֹא רָצָה לִתֵּן אֵינוֹ נוֹתֵן שֶׁאֵין זֶה בַּעַל דִּינוֹ עַד שֶׁיָּבוֹא בְּהַרְשָׁאָה עַל הַפִּקָּדוֹן. וְכָל הַבָּא בְּהַרְשָׁאָה הֲרֵי הוּא בִּכְלַל הַנֶּאֱמָר בָּהֶן (יחזקאל יח יח) \"וַאֲשֶׁר לֹא טוֹב עָשָׂה בְּתוֹךְ עַמָּיו\":","הַתּוֹבֵעַ חֲבֵרוֹ בְּדִין בְּמִטַּלְטְלִין אוֹ בְּמָעוֹת שֶׁהִפְקִיד אֶצְלוֹ וְכָפַר בּוֹ אֵינוֹ יָכוֹל לִכְתֹּב הַרְשָׁאָה עָלָיו שֶׁנִּמְצָא זֶה כִּמְשַׁקֵּר שֶׁהוּא אוֹמֵר לוֹ הִרְשֵׁיתִיךְ לִטּל מַה שֶּׁיֵּשׁ לִי בְּיַד פְּלוֹנִי וּכְבָר אָמַר פְּלוֹנִי שֶׁאֵין לוֹ אֶצְלוֹ כְּלוּם. וְכֵן מִי שֶׁנִּתְחַיֵּב לוֹ חֲבֵרוֹ שְׁבוּעָה אֵינוֹ יָכוֹל לְהַרְשׁוֹת אַחֵר עָלָיו לְהַשְׁבִּיעוֹ שֶׁאֵין שָׁם דָּבָר שֶׁיַּקְנֶה לוֹ וְאֵין אָדָם מַרְשֶׁה עַל תְּבִיעַת דְּבָרִים שֶׁאֵין הַדְּבָרִים נִקְנִין אֶלָּא עַל תְּבִיעַת הַמָּמוֹן:","מִי שֶׁהָיוּ לוֹ מְעוֹת פִּקָּדוֹן בְּיַד אַחֵר וְרָצָה לְהַרְשׁוֹת שָׁלִיחַ לַהֲבִיאָן אֵין הַקִּנְיָן מִיָּדוֹ מוֹעִיל בָּזֶה שֶׁאֵין הַמַּטְבֵּעַ נִקְנֶה בַּחֲלִיפִין. אֶלָּא כֵּיצַד עוֹשֶׂה. נוֹתֵן לוֹ קַרְקַע כָּל שֶׁהוּ וּמַקְנֶה לוֹ הַמָּעוֹת עַל גַּבָּהּ כְּדֵי לְהוֹצִיאָן בְּהַרְשָׁאָה זוֹ וְהוֹלֵךְ וְדָן עִמּוֹ וּמוֹצִיאָן. הָיְתָה לוֹ מִלְוֶה בְּיַד אַחֵר אֵינוֹ יָכוֹל לִכְתֹּב הַרְשָׁאָה עָלֶיהָ וַאֲפִלּוּ הָיָה הַחוֹב בִּשְׁטָר מִפְּנֵי שֶׁהַמִּלְוֶה לְהוֹצָאָה נִתְּנָה וְאֵין אָדָם מַקְנֶה לַחֲבֵרוֹ דָּבָר שֶׁאֵינוֹ בָּעוֹלָם. וְאֵין לוֹ דֶּרֶךְ שֶׁיַּקְנֶה אָדָם חוֹב בָּהּ אֶלָּא בְּמַעֲמַד שְׁלָשְׁתָּן וְהוּא דָּבָר שֶׁאֵין לוֹ טַעַם כְּמוֹ שֶׁבֵּאַרְנוּ. אוֹ בְּהַקְנָיַת שְׁטַר הַחוֹב עַצְמוֹ בִּכְתִיבָה וּמְסִירָה מִפְּנֵי שֶׁהוּא מַקְנֶה הַשִּׁעְבּוּד שֶׁבּוֹ. זֶהוּ הַדִּין שֶׁיֵּרָאֶה לִי מִן הַגְּמָרָא. אֲבָל הַגְּאוֹנִים תִּקְּנוּ שֶׁכּוֹתְבִין הַרְשָׁאָה אַף עַל הַמִּלְוֶה כְּדֵי שֶׁלֹּא יִטּל כָּל אֶחָד מָמוֹן חֲבֵרוֹ וְיֵלֵךְ לוֹ לִמְדִינָה אַחֶרֶת. וְעוֹד תִּקְּנוּ שֶׁאִם הִרְשָׁהוּ לִטּל מָעוֹת שֶׁיֵּשׁ לוֹ בְּיַד חֲבֵרוֹ אוֹ לִתְבֹּעַ מִמֶּנּוּ הַלְוָאָה וְלֹא הָיְתָה לַמַּקְנֶה קַרְקַע מַקְנֵהוּ אַרְבַּע אַמּוֹת מֵחֶלְקוֹ שֶׁבְּאֶרֶץ יִשְׂרָאֵל וּמַקְנֶה לוֹ הַמָּעוֹת עַל גַּבָּן. וּדְבָרִים אֵלּוּ דְּבָרִים קַלִּים הֵן עַד מְאֹד וּרְעוּעִים שֶׁזֶּה מִי יֹאמַר שֶׁיֵּשׁ לוֹ חֵלֶק בְּאֶרֶץ יִשְׂרָאֵל וַאֲפִלּוּ הוּא רָאוּי אֵינוֹ בִּרְשׁוּתוֹ. וְהַגְּאוֹנִים עַצְמָן שֶׁתִּקְּנוּ תַּקָּנָה זוֹ אָמְרוּ שֶׁאֵין אוֹמְרִין יִקֹּב הַדִּין אֶת הָהָר וְאֵינָהּ אֶלָּא כְּדֵי לְאַיֵּם עַל הַנִּתְבָּע. אִם רָצָה לָדוּן וְלִתֵּן בְּהַרְשָׁאָה זוֹ נִפְטָר. וְלָמָּה יִפָּטֵר שֶׁאֵין זֶה הַבָּא בְּהַרְשָׁאָה זוֹ הָרְעוּעָה פָּחוֹת מִשָּׁלִיחַ שֶׁעָשָׂהוּ בְּעֵדִים. אֲבָל אִם לֹא יִרְצֶה הַנִּתְבָּע לָדוּן עִמּוֹ אֵין כּוֹפִין לִתֵּן לוֹ וְלֹא לְהַשְׁבִּיעַ עַד שֶׁיָּבוֹא בַּעַל דִּינוֹ. וְכֵן הוֹרוּ שֶׁאִם הָיְתָה לוֹ מִלְוֶה אֵצֶל חֲבֵרוֹ בֵּין בִּשְׁטָר בֵּין בְּעֵדֵי קִנְיָן אַף עַל פִּי שֶׁכָּפַר בָּהּ בְּבֵית דִּין כּוֹתְבִין עָלָיו הַרְשָׁאָה מִפְּנֵי שֶׁהוּא כְּפִירַת שִׁעְבּוּד קַרְקַע. אֲבָל אִם מִלְוֶה עַל פֶּה הִיא שֶׁכָּפַר בָּהּ לֹא תִּקְּנוּ שֶׁיִּכְתְּבוּ עָלֶיהָ הַרְשָׁאָה:","מִי שֶׁהִרְשָׁה לְאֶחָד וְרָצָה לְבַטֵּל הַשְּׁלִיחוּת וּלְהַרְשׁוֹת לְאַחֵר הֲרֵי זֶה מְבַטֵּל. וְאֵין לַמֻּרְשֶׁה לִכְתֹּב הַרְשָׁאָה לְאַחֵר שֶׁזֶּה אוֹמֵר אֵין רְצוֹנִי שֶׁיִּהְיֶה פִּקְדוֹנִי בְּיַד אַחֵר. לְפִיכָךְ אִם הִתְנָה עָלָיו שֶׁיַּרְשֶׁה הוּא לְאַחֵר וְאַחֵר לְאַחֵר הֲרֵי הַשָּׁלִיחַ כּוֹתֵב הַרְשָׁאָה לַשֵּׁנִי וְשֵׁנִי לַשְּׁלִישִׁי הַכּל לְפִי תְּנָאוֹ:","הַבָּא בְּהַרְשָׁאָה שֶׁמָּחַל לְזֶה הַנִּתְבָּע אוֹ שֶׁמָּכַר לוֹ אוֹ שֶׁמָּחַל לוֹ עַל הַשְּׁבוּעָה אוֹ שֶׁעָשָׂה עִמּוֹ פְּשָׁרָה לֹא עָשָׂה כְּלוּם שֶׁהֲרֵי אוֹמֵר לוֹ לְתַקֵּן שְׁלַחְתִּיךָ וְלֹא לְעַוֵּת. לְפִיכָךְ אִם הִתְנָה עִמּוֹ בֵּין לְתַקֵּן בֵּין לְעַוֵּת אֲפִלּוּ מָחַל לוֹ עַל הַכּל הֲרֵי זֶה מָחוּל:","רְאוּבֵן שֶׁבָּא בְּהַרְשָׁאָה וְתָבַע שִׁמְעוֹן אֵין שִׁמְעוֹן יָכוֹל לִדְחוֹתוֹ וְלוֹמַר לוֹ שֶׁמָּא הַמְשַׁלֵּחַ אוֹתְךָ הִרְשָׁה אַחֵר וּבִטֵּל שְׁלִיחוּתְךָ שֶׁהֲרֵי רְאוּבֵן אוֹמֵר לוֹ תֵּן לִי הַפִּקָּדוֹן שֶׁיֵּשׁ לִי בְּיָדְךָ וְזוֹ הַרְשָׁאָתִי תְּהִי אֶצְלְךָ. וְאִם הַמַּפְקִיד הִרְשָׁה אַחֵר הוּא הִפְסִיד עַל עַצְמוֹ וְשִׁמְעוֹן פָּטוּר שֶׁהֲרֵי בְּהַרְשָׁאָתוֹ נָתַן:","רְאוּבֵן שֶׁבָּא בְּהַרְשָׁאַת שִׁמְעוֹן וְתָבַע לֵוִי וְאָמַר לֵוִי לֹא הָיוּ דְּבָרִים מֵעוֹלָם אֲבָל יִשָּׁבַע שִׁמְעוֹן וְיִטּל מוֹצִיאִין הַמָּמוֹן מִיַּד לֵוִי וְיִהְיֶה מֻנָּח בְּבֵית דִּין עַד שֶׁיָּבוֹא שִׁמְעוֹן וְיִשָּׁבַע וְיִטּל. וְכֵן כָּל הַדְּבָרִים שֶׁתּוֹלֶה לֵוִי בְּשִׁמְעוֹן יָדוּן רְאוּבֵן וְיִהְיֶה הַמָּמוֹן מֻנָּח בְּבֵית דִּין עַד שֶׁיָּבוֹא שִׁמְעוֹן וְיִשָּׁאֵל. וְיֵשׁ לִרְאוּבֵן לְהַחֲרִים עַל מִי שֶׁטּוֹעֵן טַעֲנַת שֶׁקֶר כְּדֵי לְעַכֵּב הַמָּמוֹן וּלְאַחֲרוֹ. נִתְחַיֵּב לֵוִי שְׁבוּעָה אֵינוֹ יָכוֹל לְעַכֵּב וְלוֹמַר לוֹ אֵינִי נִשְׁבָּע עַד שֶׁאַחֲרִים בִּפְנֵי שִׁמְעוֹן עַל מִי שֶׁטּוֹעֵן עָלַי שֶׁקֶר שֶׁאֵין זֶה הַחֵרֶם אֶלָּא תַּקָּנָה קַלָּה שֶׁתִּקְּנוּ הַגְּאוֹנִים הָאַחֲרוֹנִים כְּדֵי שֶׁיְּכַוְּנוּ בַּעֲלֵי דִּינִין טַעֲנוֹתֵיהֶן וְאֵין מְעַכְּבִין שְׁבוּעָתוֹ שֶׁל זֶה מִפְּנֵי תַּקָּנָה זוֹ הַקַּלָּה:"],"Mishneh Torah, Appraisals and Devoted Property 6":["אֶחָד הָאוֹמֵר הֲרֵי זֶה הֶקְדֵּשׁ לְבֶדֶק הַבַּיִת אוֹ חֵרֶם לְבֶדֶק הַבַּיִת אוֹ חֵרֶם לַשָּׁמַיִם. וְכֵן בְּכָל נְכָסָיו אִם אָמַר כָּל נְכָסָיו הֶקְדֵּשׁ אוֹ חֵרֶם לְבֶדֶק הַבַּיִת אוֹ חֵרֶם לַשָּׁמָיִם הֲרֵי אֵלּוּ יִפְּלוּ לְבֶדֶק הַבַּיִת. אֲבָל אִם אָמַר חֵרֶם סְתָם הֲרֵי אֵלּוּ לַכֹּהֲנִים. שֶׁסְּתָם חֲרָמִים לַכֹּהֲנִים. שֶׁנֶּאֱמַר (במדבר יח יד) \"כָּל חֵרֶם בְּיִשְׂרָאֵל לְךָ יִהְיֶה\":","מַחְרִים אָדָם מִן בְּקָרוֹ וּמִצֹּאנוֹ וּמֵעֲבָדָיו וּמִשִּׁפְחוֹתָיו הַכְּנַעֲנִים וּמִשְּׂדֵה אֲחֻזָּתוֹ. אֲבָל לֹא יַחֲרִים כָּל בְּהֶמְתּוֹ וְלֹא כָּל עֲבָדָיו וְלֹא כָּל שְׂדוֹתָיו וְלֹא כָּל מִין שֶׁיֵּשׁ לוֹ מִשְּׁאָר הַמִּטַּלְטְלִין שֶׁנֶּאֱמַר (ויקרא כז כח) \"מִכָּל אֲשֶׁר לוֹ\". וְאִם הֶחֱרִים אֶת הַכּל אֲפִלּוּ הֶחֱרִים כָּל נְכָסָיו הֲרֵי אֵלּוּ מֻחְרָמִין בֵּין שֶׁהֶחְרִים לַכֹּהֲנִים בֵּין שֶׁהֶחֱרִים לְבֶדֶק הַבַּיִת:","וְכָל מִי שֶׁהֶחֱרִים אוֹ הִקְדִּישׁ כָּל נְכָסָיו לוֹקְחִין כָּל מַה שֶּׁיֵּשׁ לוֹ וַאֲפִילוּ תְּפִלִּין שֶׁבְּרֹאשׁוֹ. וְאֵין צָרִיךְ לוֹמַר כְּלֵי אֻמְּנוּתוֹ וּבְגָדָיו שֶׁהַכּל הֶקְדֵּשׁ אוֹ חֵרֶם:","מַה בֵּין חֶרְמֵי כֹּהֲנִים לְחֶרְמֵי שָׁמַיִם. שֶׁחֶרְמֵי שָׁמַיִם הֶקְדֵּשׁ וְנִפְדִּין בְּשָׁוְיֵיהֶן וְיִפְּלוּ הַדָּמִים לְבֶדֶק הַבַּיִת וְיֵצְאוּ הַנְּכָסִים לְחֻלִּין. וְחֶרְמֵי כֹּהֲנִים אֵין לָהֶן פִּדְיוֹן לְעוֹלָם אֶלָּא נִתָּנִין לַכֹּהֲנִים כִּתְרוּמָה. וְעַל חֵרֶם כֹּהֲנִים הוּא אוֹמֵר (ויקרא כז כח) \"לֹא יִמָּכֵר וְלֹא יִגָּאֵל\". לֹא יִמָּכֵר לְאַחֵר וְלֹא יִגָּאֵל לַבְּעָלִים:","וְאֶחָד הַמַּחֲרִים קַרְקַע אוֹ מִטַּלְטְלִין הֲרֵי אֵלּוּ נִתָּנִין לַכֹּהֵן שֶׁבְּאוֹתוֹ מִשְׁמָר. בְּשָׁעָה שֶׁהֶחֱרִים חֶרְמֵי כֹּהֲנִים כָּל זְמַן שֶׁהֵן בְּבֵית הַבְּעָלִים הֲרֵי הֵן הֶקְדֵּשׁ לְכָל דִּבְרֵיהֶם. שֶׁנֶּאֱמַר (ויקרא כז כח) \"כָּל חֵרֶם קֹדֶשׁ קָדָשִׁים הוּא לַה'\". נְתָנוֹ לַכֹּהֵן הֲרֵי הֵן כְּחֻלִּין לְכָל דִּבְרֵיהֶם. שֶׁנֶּאֱמַר (במדבר יח יד) \"כָּל חֵרֶם בְּיִשְׂרָאֵל לְךָ יִהְיֶה\":","כֹּהֵן שֶׁהָיְתָה לוֹ שְׂדֵה חֵרֶם שֶׁזָּכָה בָּהּ אַחַר הַיּוֹבֵל וְהֶחֱרִימָהּ הֲרֵי זוֹ מֻחְרֶמֶת וְיוֹצְאָה לְאֶחָיו הַכֹּהֲנִים. שֶׁנֶּאֱמַר (ויקרא כז כא) \"לַכֹּהֵן תִּהְיֶה אֲחֻזָּתוֹ\" מְלַמֵּד שֶׁשְּׂדֵה חֶרְמוֹ לוֹ כִּשְׂדֵה אֲחֻזָּה לְיִשְׂרָאֵל שֶׁאִם הֶחֱרִימָהּ הִיא מֻחְרֶמֶת מִיָּד:","מָכַר הַכֹּהֵן שְׂדֵה חֶרְמוֹ וְהִקְדִּישָׁהּ לוֹקֵחַ אֲפִלּוּ הָיָה הַלּוֹקֵחַ הַבְּעָלִים הָרִאשׁוֹנִים שֶׁהֶחֱרִימוּהָ הֲרֵי זוֹ כִּשְׂדֵה מִקְנָה וְחוֹזֶרֶת לַכֹּהֵן שֶׁמְּכָרָהּ בַּיּוֹבֵל. אֲבָל קַרְקַע אוֹ מִטַּלְטְלִין שֶׁל כֹּהֲנִים וּלְוִיִּם אֵינָם מַחְרִימִין אוֹתָן שֶׁהֲרֵי אוֹמֵר בְּשָׂדֶה (ויקרא כה לד) \"כִּי אֲחֻזַּת עוֹלָם הוּא לָכֶם\". וּמִטַּלְטְלִין הֻקְּשׁוּ לְקַרְקָעוֹת בַּחֲרָמִין שֶׁנֶּאֱמַר (גמרא ערכין כח א) \"מִכָּל אֲשֶׁר לוֹ וּמִשְּׂדֵה אֲחֻזָּתוֹ\":","הַמַּקְדִּישׁ קָדְשֵׁי מִזְבֵּחַ לְבֶדֶק הַבַּיִת הֲרֵי הַהֶקְדֵּשׁ חָל עֲלֵיהֶן וְתֵעָרֵךְ הַבְּהֵמָה וְתִפָּדֶה וְיִפְּלוּ דָּמֶיהָ לְבֶדֶק הַבַּיִת וְהַבְּהֵמָה תִּקָּרֵב לְמַה שֶּׁהָיְתָה בַּתְּחִלָּה. אֲבָל הַמַּקְדִּישׁ קָדְשֵׁי בֶּדֶק הַבַּיִת לַמִּזְבֵּחַ וְאָמַר הֲרֵי זֶה עוֹלָה אוֹ שְׁלָמִים אוֹ הֶחֱרִימָם לַכֹּהֲנִים לֹא עָשָׂה כְּלוּם וְאֵין הֶקְדֵּשׁ מִזְבֵּחַ וְלֹא הַחֵרֶם חָל עַל קָדְשֵׁי בֶּדֶק הַבַּיִת שֶׁאֵין אָדָם מַקְדִּישׁ דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ:","הָאוֹמֵר שׁוֹר זֶה הֶקְדֵּשׁ לְאַחַר שְׁלֹשִׁים יוֹם וּשְׁחָטוֹ בְּתוֹךְ שְׁלֹשִׁים יוֹם הֲרֵי זֶה מֻתָּר בַּהֲנָאָה. הִקְדִּישׁוֹ לַמִּזְבֵּחַ הֲרֵי זֶה הֶקְדֵּשׁ לַמִּזְבֵּחַ. אֲבָל אִם אָמַר הֲרֵי זֶה הֶקְדֵּשׁ מֵעַכְשָׁו לְאַחַר שְׁלֹשִׁים יוֹם וּשְׁחָטוֹ בְּתוֹךְ שְׁלֹשִׁים יוֹם הֲרֵי זֶה אָסוּר בַּהֲנָאָה. וְאִם הִקְדִּישׁוֹ בְּתוֹךְ הַשְּׁלֹשִׁים לַמִּזְבֵּחַ אֵינוֹ מֻקְדָּשׁ:","הַמַּקְדִּישׁ עוֹלָה לְבֶדֶק הַבַּיִת אֵין בָּהּ אֶלָּא עִכּוּב גִּזְבָּרִין בִּלְבַד. וּמִדִּבְרֵי סוֹפְרִים שֶׁלֹּא תִּשָּׁחֵט עַד שֶׁתִּפָּדֶה. לְפִיכָךְ אִם עָבַר וּשְׁחָטָהּ הֲרֵי זוֹ כְּשֵׁרָה:","מַחֲרִים אָדָם בֵּין קָדְשֵׁי קָדָשִׁים בֵּין קָדָשִׁים קַלִּים בֵּין חֶרְמֵי כֹּהֲנִים בֵּין חֶרְמֵי בֶּדֶק הַבַּיִת. וְאִם הָיוּ קָדָשִׁים שֶׁהוּא חַיָּב בְּאַחֲרָיוּתָן נוֹתֵן אֶת דְּמֵיהֶן בֵּין לַכֹּהֲנִים בֵּין לְבֶדֶק הַבַּיִת וְיִקָּרְבוּ אוֹתָן הַקָּדָשִׁים אַחַר שֶׁיִּפָּדוּ לְמַה שֶּׁהֵן:","הָיוּ נְדָבָה וְהֶחֱרִימָן כֵּיצַד פּוֹדִין אוֹתָן. אוֹמְדִים כַּמָּה אָדָם רוֹצֶה לִתֵּן בִּבְהֵמָה זוֹ לְהַעֲלוֹתָהּ עוֹלָה שֶׁאֵינוֹ חַיָּב בָּהּ. וְכָל הַנּוֹתֵן אוֹתוֹ שִׁעוּר יַקְרִיב בְּהֵמָה זוֹ נְדָבָה כְּמוֹ שֶׁהָיְתָה:","יִשְׂרָאֵל שֶׁהֶחְרִים אֶת בְּכוֹר בְּהֵמָה לַשָּׁמַיִם בֵּין שֶׁהָיָה תָמִים בֵּין שֶׁהָיָה בַּעַל מוּם הֲרֵי זֶה מֻחְרָם. וְאֵין צָרִיךְ לוֹמַר שֶׁהֶחְרִימוֹ הַכֹּהֵן לַשָּׁמַיִם אַחַר שֶׁבָּא לְיָדוֹ:","וְכֵיצַד פּוֹדִין אוֹתָן. אוֹמְדִין כַּמָּה אָדָם רוֹצֶה לִתֵּן בִּבְכוֹר זֶה כְּדֵי שֶׁיִּהְיֶה לוֹ וְתִהְיֶה הָרְשׁוּת בְּיָדוֹ לִתְּנוֹ לְכָל כֹּהֵן שֶׁיִּרְצֶה לִקְרוֹבוֹ אוֹ לְרֵעוֹ. וְכָל הַנּוֹתֵן אוֹתוֹ שִׁעוּר יִקַּח הַבְּכוֹר וְיִתְּנֶנּוּ לְכָל כֹּהֵן שֶׁיִּרְצֶה וְיִפְּלוּ הַדָּמִים לְבֶדֶק הַבַּיִת:","הַמַּחֲרִים אֶת הַמַּעֲשֵׂר הֲרֵי זֶה כְּמַחֲרִים שַׁלְמֵי נְדָבָה לְפִי שֶׁאֵינוֹ חַיָּב בְּאַחֲרָיוּתוֹ:","הַמַּקְדִּישׁ שִׁקְלוֹ לְבֶדֶק הַבַּיִת הֲרֵי זֶה קֹדֶשׁ. הִקְדִּישׁ בִּכּוּרִים לְבֶדֶק הַבַּיִת אֵינָן קֹדֶשׁ. אֲבָל אִם הִקְדִּישָׁן הַכֹּהֵן אַחַר שֶׁבָּאוּ לְיָדוֹ הֲרֵי אֵלּוּ קֹדֶשׁ:","הַמַּחֲרִים חֲצִי עַבְדּוֹ וְשִׁפְחָתוֹ הוּא וְהַכֹּהֲנִים שֻׁתָּפִין בּוֹ. אֲבָל אִם הִקְדִּישׁ אוֹ הֶחֱרִים לַשָּׁמַיִם חֲצִי עַבְדּוֹ כֻּלּוֹ קֹדֶשׁ כְּמוֹ שֶׁבֵּאַרְנוּ. וְכָל הַמַּקְדִּישׁ עַבְדּוֹ וְשִׁפְחָתוֹ הַכְּנַעֲנִים אוֹ הַמַּקְדִּישׁ כָּל נְכָסָיו וְהָיוּ בָּהֶן עֲבָדִים הֲרֵי גּוּפָן קֹדֶשׁ לְפִיכָךְ אֲסוּרִים לֵהָנוֹת בָּהֶן עַד שֶׁיִּפָּדוּ:","וְאֵין הַגִּזְבָּרִין רַשָּׁאִין לִקַּח דְּמֵיהֶן מֵאֲחֵרִים וּלְהוֹצִיא אוֹתָן לְחֵרוּת אֶלָּא מוֹכְרִין אוֹתָן לַאֲחֵרִים וַאֲחֵרִים מוֹצִיאִין אוֹתָן לְחֵרוּת אִם רָצוּ:","הַמַּקְדִּישׁ יְדֵי עַבְדּוֹ כָּל הַיֶּתֶר עַל פַּרְנָסָתוֹ קֹדֶשׁ. וְכֵיצַד הוּא מִתְפַּרְנֵס עֶבֶד זֶה. לוֹוֶה וְאוֹכֵל וְעוֹשֶׂה וּפוֹרֵעַ. וְהוּא שֶׁיַּעֲשֶׂה פָּחוֹת פָּחוֹת מִשְּׁוֵה פְּרוּטָה וְיִפְרַע. שֶׁאִם עָשָׂה בִּפְרוּטָה רִאשׁוֹן רִאשׁוֹן קָנָה הֶקְדֵּשׁ:","הַמַּקְדִּישׁ אֶת עַצְמוֹ לֹא הִקְדִּישׁ אֶלָּא דָּמָיו וַהֲרֵי הוּא חַיָּב בִּדְמֵי עַצְמוֹ. וּמֻתָּר לוֹ לַעֲשׂוֹת וְלֶאֱכל שֶׁהֲרֵי לֹא נִתְקַדֵּשׁ גּוּפוֹ כְּעֶבֶד:","אֵין אָדָם מַקְדִּישׁ דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ. כֵּיצַד. כְּגוֹן שֶׁהֶחְרִים בְּנוֹ וּבִתּוֹ וְעַבְדּוֹ וְשִׁפְחָתוֹ הָעִבְרִים אוֹ שְׂדֵה מִקְנָתוֹ הֲרֵי אֵלּוּ אֵינָן מֻחְרָמִין. שֶׁאֵין אָדָם מַקְדִּישׁ דָּבָר שֶׁאֵין גּוּפוֹ שֶׁלּוֹ:","אֵין אָדָם מַקְדִּישׁ דָּבָר שֶׁאֵינוֹ בִּרְשׁוּתוֹ. כֵּיצַד. הָיָה לוֹ פִּקָּדוֹן בְּיַד אַחֵר וְכָפַר בּוֹ זֶה שֶׁהוּא אֶצְלוֹ אֵין הַבְּעָלִים יְכוֹלִין לְהַקְדִּישׁוֹ. אֲבָל אִם לֹא כָּפַר בּוֹ הֲרֵי הוּא בִּרְשׁוּת בְּעָלָיו בְּכָל מָקוֹם שֶׁהוּא:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּמִטַּלְטְלִין. אֲבָל קַרְקַע שֶׁגְּזָלָהּ אַחֵר וְכָפַר בָּהּ אִם יָכוֹל לְהוֹצִיאָהּ בְּדַיָּנִין הֲרֵי זֶה יָכוֹל לְהַקְדִּישָׁהּ וְאַף עַל פִּי שֶׁעֲדַיִן לֹא הוֹצִיאָהּ שֶׁהַקַּרְקַע עַצְמָהּ הֲרֵי הִיא בִּרְשׁוּת בְּעָלֶיהָ:","הַגּוֹזֵל אֶת חֲבֵרוֹ וְלֹא נִתְיָאֲשׁוּ הַבְּעָלִים שְׁנֵיהֶם אֵינָן יְכוֹלִין לְהַקְדִּישׁ. זֶה לְפִי שֶׁאֵינוֹ שֶׁלּוֹ וְזֶה לְפִי שֶׁאֵינוֹ בִּרְשׁוּתוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁהָיָה מוֹכֵר דְּלוּעִין אוֹ בֵּיצִים וְכַיּוֹצֵא בָּהֶן וּבָא לוֹקֵחַ וְנָטַל אַחַת וְהָלַךְ לוֹ. אִם הָיוּ דְּמֵי כָּל אַחַת וְאַחַת קְצוּבִין הֲרֵי זֶה כְּמִי שֶׁפָּסַק. וְאֵין הַמּוֹכֵר יָכוֹל לְהַקְדִּישׁ דְּלַעַת זוֹ שֶׁהֲרֵי אֵינָהּ בִּרְשׁוּתוֹ. וְאִם אֵין הַדָּמִים קְצוּבִין וְהִקְדִּישָׁהּ מְקֻדֶּשֶׁת שֶׁעֲדַיִן בִּרְשׁוּתוֹ הִיא שֶׁזֶּה שֶׁלְּקָחָהּ לֹא לְקָחָהּ דֶּרֶךְ גְּזֵלָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֵין אָדָם מַקְדִּישׁ דָּבָר שֶׁלֹּא בָּא לָעוֹלָם. כֵּיצַד. מַה שֶּׁתַּעֲלֶה מְצוּדָתִי מִן הַיָּם קֹדֶשׁ. מַה שֶּׁתּוֹצִיא שָׂדֶה זוֹ מִן הַפֵּרוֹת חֵרֶם. לֹא אָמַר כְּלוּם:","הָאוֹמֵר לַחֲבֵרוֹ שָׂדֶה זוֹ שֶׁמָּכַרְתִּי לְךָ לִכְשֶׁאֶקָּחֶנָּה מִמְּךָ מְקֻדֶּשֶׁת וּלְקָחָהּ אֵינָהּ מְקֻדֶּשֶׁת. לְפִי שֶׁכְּשֶׁהִקְדִּישָׁהּ לֹא בָּאָה בִּרְשׁוּתוֹ:","וְכֵן הַמַּקְדִּישׁ מַעֲשֵׂה יְדֵי אִשְׁתּוֹ הֲרֵי זוֹ עוֹשָׂה וְאוֹכֶלֶת וְהַמּוֹתָר חֻלִּין. אָמַר לָהּ יִקְדְּשׁוּ יָדַיִךְ לְעוֹשֵׂיהֶן הוֹאִיל וְהֵן מְשֻׁעְבָּדִין לוֹ הֲרֵי כָּל מַעֲשֵׂה יָדֶיהָ קֹדֶשׁ. הָא לְמָה זֶה דּוֹמֶה לְאוֹמֵר אִילָן זֶה קֹדֶשׁ שֶׁכָּל פֵּרוֹת שֶׁיַּעֲשֶׂה לְהַבָּא קֹדֶשׁ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָאוֹמֵר לַחֲבֵרוֹ שָׂדֶה זוֹ שֶׁאֲנִי מוֹכֵר לְךָ לִכְשֶׁאֶקָּחֶנָּה מִמְּךָ תִּתְקַדֵּשׁ הֲרֵי זוֹ מְקֻדֶּשֶׁת כְּשֶׁיִּקָּחֶנָּה שֶׁהֲרֵי עַתָּה (בָּא) בְּיָדוֹ לְהַקְדִּישָׁהּ. שָׂדֶה זוֹ שֶׁמִּשְׁכַּנְתִּי לְךָ לִכְשֶׁאֶפְדֶּנָּה מִמְּךָ תְּהִי קֹדֶשׁ. מִשֶּׁיִּפְדֶּה אוֹתָהּ תִּתְקַדֵּשׁ שֶׁהֲרֵי בְּיָדוֹ לִפְדּוֹתָהּ. וַאֲפִלּוּ הָיְתָה מְמֻשְׁכֶּנֶת לִזְמַן קָצוּב שֶׁהֲרֵי בְּיָדוֹ לִפְדּוֹתָהּ אַחַר הַזְּמַן:","הַמַּשְׂכִּיר בַּיִת לַחֲבֵרוֹ וְחָזַר וְהִקְדִּישׁוֹ הֲרֵי זֶה קֹדֶשׁ וּפָקְעָה הַשְּׂכִירוּת. וְאִם דָּר בּוֹ הַשּׂוֹכֵר מָעַל:","יֵרָאֶה לִי שֶׁאַף עַל פִּי שֶׁאֵין אָדָם מַקְדִּישׁ דָּבָר שֶׁלֹּא בָּא לָעוֹלָם אִם אָמַר הֲרֵי עָלַי לְהַקְדִּישׁוֹ הֲרֵי זֶה חַיָּב לְהַקְדִּישׁוֹ כְּשֶׁיָּבוֹא לָעוֹלָם מִשּׁוּם נִדְרוֹ. וְאִם לֹא הִקְדִּישׁ הֲרֵי זֶה עוֹבֵר מִשּׁוּם (דברים כג כב) \"בַּל תְּאַחֵר\" וְ(במדבר ל ג) \"לֹא יַחֵל דְּבָרוֹ\" וּמִשּׁוּם (במדבר ל ג) \"כְּכָל הַיֹּצֵא מִפִּיו יַעֲשֶׂה\" כִּשְׁאָר הַנְּדָרִים:","כֵּיצַד. הָאוֹמֵר הֲרֵי עָלַי לְהַקְדִּישׁ כָּל שֶׁתַּעֲלֶה מְצוּדָתִי מִן הַיָּם. הֲרֵי עָלַי לִתֵּן לַעֲנִיִּים פֵּרוֹת שֶׁתּוֹצִיא שָׂדֶה זוֹ. הֲרֵי עָלַי לְהַחֲרִים אוֹ לִתֵּן לִשְׁבוּיִם כָּל שֶׁאֶשְׂתַּכֵּר בְּשָׁנָה זוֹ. וְכָל כַּיּוֹצֵא בְּמַאֲמָרִים אֵלּוּ הֲרֵי זֶה חַיָּב לִתֵּן וְלַעֲשׂוֹת בָּהֶן מַה שֶּׁאָמַר כְּשֶׁיָּבוֹאוּ לְיָדוֹ. וְזֶה וְכַיּוֹצֵא בּוֹ בִּכְלַל נְדָרִים הוּא לֹא בִּכְלַל הֶקְדֵּשׁוֹת:","רְאָיָה לְדָבָר זֶה מַה שֶּׁאָמַר יַעֲקֹב אָבִינוּ (בראשית כח כב) \"וְכל אֲשֶׁר תִּתֶּן לִי עַשֵּׂר אֲעַשְּׂרֶנּוּ לָךְ\" וְנֶאֱמַר (בראשית לא יג) \"אֲשֶׁר נָדַרְתָּ לִּי שָׁם נֶדֶר\". וַהֲרֵי הָאוֹמֵר לֹא אֶפָּטֵר מִן הָעוֹלָם עַד שֶׁאֶהֱיֶה נָזִיר חַיָּב לִנְהֹג בִּנְזִירוּת וְאַף עַל פִּי שֶׁעֲדַיִן לֹא נָדַר בְּנָזִיר. הוֹאִיל וְאָמַר שֶׁיִּדֹּר בְּנָזִיר חַיָּב לְהִנָּזֵר. וְזֶה כַּיּוֹצֵא בּוֹ וְכָזֶה רָאוּי לָדוּן:","הֶקְדֵּשׁ טָעוּת אֵינוֹ הֶקְדֵּשׁ. כֵּיצַד. הָאוֹמֵר שׁוֹר שָׁחוֹר שֶׁיֵּצֵא מִבַּיִת רִאשׁוֹן הֲרֵי הוּא הֶקְדֵּשׁ וְיָצָא לָבָן אֵינוֹ הֶקְדֵּשׁ. דִּינָר זָהָב שֶׁיַּעֲלֶה בְּיָדִי רִאשׁוֹן הֲרֵי הוּא הֶקְדֵּשׁ וְעָלָה שֶׁל כֶּסֶף אֵינוֹ הֶקְדֵּשׁ. חָבִית שֶׁל יַיִן שֶׁתַּעֲלֶה בְּיָדִי רִאשׁוֹנָה הֶקְדֵּשׁ וְעָלָה שֶׁל שֶׁמֶן בֵּין שֶׁהַיַּיִן יָקָר מִן הַשֶּׁמֶן בְּאוֹתוֹ מָקוֹם אוֹ הַשֶּׁמֶן יָקָר מִן הַיַּיִן אֵינוֹ הֶקְדֵּשׁ. הִתְפִּיס בָּהּ אַחֶרֶת וְאָמַר זוֹ כָּזוֹ הֲרֵי הַשְּׁנִיָּה הֶקְדֵּשׁ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Blessings 8":["כָּל פֵּרוֹת הָאִילָן מְבָרְכִין עֲלֵיהֶן בַּתְּחִלָּה בּוֹרֵא פְּרִי הָעֵץ וּלְבַסּוֹף בּוֹרֵא נְפָשׁוֹת רַבּוֹת חוּץ מֵחֲמֵשֶׁת הַמִּינִין הַכְּתוּבִין בַּתּוֹרָה. וְהֵם עֲנָבִים וְרִמּוֹנִים וּתְאֵנִים וְזֵיתִים וּתְמָרִים שֶׁהוּא מְבָרֵךְ עֲלֵיהֶן בַּסּוֹף בְּרָכָה אַחַת מֵעֵין שָׁלֹשׁ. וְעַל פֵּרוֹת הָאָרֶץ וְהַיְרָקוֹת מְבָרְכִין עֲלֵיהֶן בַּתְּחִלָּה בּוֹרֵא פְּרִי הָאֲדָמָה וּלְבַסּוֹף בּוֹרֵא נְפָשׁוֹת רַבּוֹת. דְּבָרִים שֶׁאֵין גִּדּוּלָן מִן הָאָרֶץ כְּגוֹן בָּשָׂר וּגְבִינָה וְדָגִים וּבֵיצִים וּמַיִם וְחָלָב וּדְבַשׁ וְכַיּוֹצֵא בָּהֶן בַּתְּחִלָּה מְבָרֵךְ שֶׁהַכֹּל וּלְבַסּוֹף בּוֹרֵא נְפָשׁוֹת רַבּוֹת. וְהַשּׁוֹתֶה מַיִם שֶׁלֹּא לְרַוּוֹת צָמְאוֹ אֵינוֹ טָעוּן בְּרָכָה לֹא לְפָנָיו וְלֹא לְאַחֲרָיו:","הַסּוֹחֵט פֵּרוֹת וְהוֹצִיא מֵהֶן מַשְׁקִין מְבָרֵךְ עֲלֵיהֶן בַּתְּחִלָּה שֶׁהַכֹּל וּלְבַסּוֹף בּוֹרֵא נְפָשׁוֹת. חוּץ מִן הָעֲנָבִים וְהַזֵּיתִים. שֶׁעַל הַיַּיִן הוּא מְבָרֵךְ בּוֹרֵא פְּרִי הַגָּפֶן וּלְבַסּוֹף בְּרָכָה אַחַת מֵעֵין שָׁלֹשׁ. וְעַל הַשֶּׁמֶן בַּתְּחִלָּה הוּא מְבָרֵךְ בּוֹרֵא פְּרִי הָעֵץ. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהָיָה חוֹשֵׁשׁ בִּגְרוֹנוֹ וְשָׁתָה מִן הַשֶּׁמֶן עִם מֵי הַשְּׁלָקוֹת וְכַיּוֹצֵא בָּהֶן שֶׁהֲרֵי נֶהֱנֶה בִּשְׁתִיָּתוֹ. אֲבָל אִם שָׁתָה הַשֶּׁמֶן לְבַדּוֹ אוֹ שֶׁלֹּא הָיָה חוֹשֵׁשׁ בִּגְרוֹנוֹ מְבָרֵךְ עָלָיו שֶׁהַכֹּל. שֶׁהֲרֵי לֹא נֶהֱנָה בְּטַעַם הַשֶּׁמֶן:","פֵּרוֹת אוֹ יְרָקוֹת שֶׁדַּרְכָּן לְהֵאָכֵל חַיִּים אִם בִּשְׁלָן אוֹ שְׁלָקָן מְבָרֵךְ עֲלֵיהֶן בַּתְּחִלָּה שֶׁהַכֹּל וּלְבַסּוֹף בּוֹרֵא נְפָשׁוֹת. וִירָקוֹת שֶׁדַּרְכָּן לְהֵאָכֵל שְׁלוּקִין כְּגוֹן כְּרוּב וְלֶפֶת אִם אֲכָלָן חַיִּין מְבָרֵךְ עֲלֵיהֶן בַּתְּחִלָּה שֶׁהַכֹּל וּלְבַסּוֹף בּוֹרֵא נְפָשׁוֹת רַבּוֹת. וְאִם בִּשְׁלָן אוֹ שְׁלָקָן מְבָרֵךְ עֲלֵיהֶן בּוֹרֵא פְּרִי הָאֲדָמָה וּלְבַסּוֹף בּוֹרֵא נְפָשׁוֹת רַבּוֹת. דְּבָרִים שֶׁדַּרְכָּן לְהֵאָכֵל חַיִּין וּמְבֻשָּׁלִין אֲכָלָן בֵּין חַיִּין בֵּין מְבֻשָּׁלִין מְבָרֵךְ עֲלֵיהֶן בַּתְּחִלָּה בְּרָכָה הָרְאוּיָה לָהֶן. אִם הָיוּ פֵּרוֹת עֵץ מְבָרֵךְ בּוֹרֵא פְּרִי הָעֵץ וְאִם הָיוּ פֵּרוֹת הָאֲדָמָה אוֹ יְרָקוֹת מְבָרֵךְ בּוֹרֵא פְּרִי הָאֲדָמָה:","יְרָקוֹת שֶׁדַּרְכָּן לְהִשָּׁלֵק שְׁלָקָן מְבָרֵךְ עַל מֵי שֶׁלֶק שֶׁלָּהֶן בּוֹרֵא פְּרִי הָאֲדָמָה. וְהוּא שֶׁשְּׁלָקָן לִשְׁתּוֹת מֵימֵיהֶן שֶׁמֵּימֵי הַשְּׁלָקוֹת כִּשְׁלָקוֹת בְּמָקוֹם שֶׁדַּרְכָּן לִשְׁתּוֹתָן. דְּבַשׁ תְּמָרִים מְבָרְכִין עָלָיו תְּחִלָּה שֶׁהַכֹּל. אֲבָל תְּמָרִים שֶׁמְּעָכָן בַּיָּד וְהוֹצִיא גַּרְעִינִין שֶׁלָּהֶן וַעֲשָׂאָן כְּמוֹ עִסָּה מְבָרֵךְ עֲלֵיהֶן תְּחִלָּה בּוֹרֵא פְּרִי הָעֵץ וּלְבַסּוֹף בְּרָכָה אַחַת מֵעֵין שָׁלֹשׁ:","הַקָּנִים הַמְּתוּקִים שֶׁסּוֹחֲטִין אוֹתָן וּמְבַשְּׁלִין מֵימֵיהֶן עַד שֶׁיִּקְפָּא וְיִדְמֶה לְמֶלַח. כָּל הַגְּאוֹנִים אוֹמְרִים שֶׁמְּבָרְכִין עָלָיו בּוֹרֵא פְּרִי הָאֲדָמָה. וּמִקְצָתָם אָמְרוּ בּוֹרֵא פְּרִי הָעֵץ. וְכֵן אָמְרוּ שֶׁהַמּוֹצֵץ אוֹתָם קָנִים מְבָרֵךְ בּוֹרֵא פְּרִי הָאֲדָמָה. וַאֲנִי אוֹמֵר שֶׁאֵין זֶה פְּרִי וְאֵין מְבָרְכִין עָלָיו אֶלָּא שֶׁהַכֹּל. שֶׁלֹּא יִהְיֶה דְּבַשׁ אֵלּוּ הַקָּנִים שֶׁנִּשְׁתַּנָּה עַל יְדֵי אוּר גָּדוֹל מִדְּבַשׁ תְּמָרִים שֶׁלֹּא נִשְׁתַּנָּה עַל יְדֵי הָאוּר וּמְבָרְכִין עָלָיו שֶׁהַכֹּל:","הַקּוֹר וְהוּא רֹאשׁ הַדֶּקֶל שֶׁהוּא כְּמוֹ עֵץ לָבָן מְבָרֵךְ עָלָיו בַּתְּחִלָּה שֶׁהַכֹּל. קַפְרָס שֶׁל צָלָף מְבָרֵךְ עָלָיו בּוֹרֵא פְּרִי הָאֲדָמָה מִפְּנֵי שֶׁאֵינוֹ פְּרִי. וְהָאֶבְיוֹנוֹת שֶׁל צָלָף הֵן הַפְּרִי שֶׁהֵן כְּצוּרוֹת תְּמָרִים דַּקִּים קְטַנִּים מְבָרֵךְ עֲלֵיהֶן בּוֹרֵא פְּרִי הָעֵץ:","הַפִּלְפְּלִין וְהַזַּנְגְּבִיל בִּזְמַן שֶׁהֵן רְטֻבִּין מְבָרֵךְ עֲלֵיהֶן בּוֹרֵא פְּרִי הָאֲדָמָה. אֲבָל יְבֵשִׁין אֵין טְעוּנִין בְּרָכָה לֹא לִפְנֵיהֶם וְלֹא לְאַחֲרֵיהֶם מִפְּנֵי שֶׁהֵן תַּבְלִין וְאֵינוֹ אֹכֶל. וְכֵן אֳכָלִין שֶׁאֵין רְאוּיִין לַאֲכִילָה וּמַשְׁקִין שֶׁאֵינָן רְאוּיִין לִשְׁתִיָּה אֵינָן טְעוּנִין בְּרָכָה לֹא לִפְנֵיהֶן וְלֹא לְאַחֲרֵיהֶן:","הַפַּת שֶׁעִפְּשָׁה וְהַיַּיִן שֶׁהִקְרִים וְתַבְשִׁיל שֶׁעָבְרָה צוּרָתוֹ וְהַנּוֹבְלוֹת שֶׁהֵן פַּגִּין וְהַשֵּׁכָר וְהַחֹמֶץ וְהַגּוֹבַאי וְהַמֶּלַח וְהַכְּמֵהִין וְהַפִּטְרִיּוֹת עַל כֻּלָּן מְבָרֵךְ תְּחִלָּה שֶׁהַכֹּל. וְכָל הַמְבָרְכִין לְפָנָיו שֶׁהַכֹּל לָאַחֲרוֹנָה מְבָרֵךְ בּוֹרֵא נְפָשׁוֹת. וְכָל הַטָּעוּן בְּרָכָה לְאַחֲרָיו טָעוּן בְּרָכָה לְפָנָיו:","שְׁמָרִים שֶׁנָּתַן עֲלֵיהֶם שְׁלֹשָׁה וְהוֹצִיא מֵהֶן אַרְבָּעָה מְבָרֵךְ עֲלֵיהֶן בּוֹרֵא פְּרִי הַגָּפֶן שֶׁזֶּה יַיִן מָזוּג הוּא. הוֹצִיא פָּחוֹת מֵאַרְבָּעָה אַף עַל פִּי שֶׁיֵּשׁ בָּהֶם טַעַם יַיִן מְבָרֵךְ עֲלֵיהֶן שֶׁהַכֹּל תְּחִלָּה:","בֵּרֵךְ עַל פֵּרוֹת הָאִילָן בּוֹרֵא פְּרִי הָאֲדָמָה יָצָא. וְעַל פֵּרוֹת הָאֲדָמָה בּוֹרֵא פְּרִי הָעֵץ לֹא יָצָא. וְעַל כֻּלָּם אִם בֵּרֵךְ שֶׁהַכֹּל יָצָא. וַאֲפִלּוּ עַל הַפַּת וְעַל הַיַּיִן:","לָקַח כּוֹס שֶׁל שֵׁכָר בְּיָדוֹ וְהִתְחִיל הַבְּרָכָה עַל מְנָת לוֹמַר שֶׁהַכֹּל וְטָעָה וְאָמַר בּוֹרֵא פְּרִי הַגָּפֶן אֵין מַחְזִירִין אוֹתוֹ. וְכֵן אִם הָיוּ לְפָנָיו פֵּרוֹת הָאָרֶץ וְהִתְחִיל הַבְּרָכָה עַל מְנָת לוֹמַר בּוֹרֵא פְּרִי הָאֲדָמָה וְטָעָה וְאָמַר בּוֹרֵא פְּרִי הָעֵץ אֵין מַחְזִירִין אוֹתוֹ. וְכֵן אִם הָיָה לְפָנָיו תַּבְשִׁיל שֶׁל דָּגָן וּפָתַח עַל מְנָת לוֹמַר בּוֹרֵא מִינֵי מְזוֹנוֹת וְטָעָה וְאָמַר הַמּוֹצִיא יָצָא. מִפְּנֵי שֶׁבְּשָׁעָה שֶׁהִזְכִּיר אֶת הַשֵּׁם וְהַמַּלְכוּת שֶׁהֵן עִקַּר הַבְּרָכָה לֹא נִתְכַּוֵּן אֶלָּא לִבְרָכָה הָרְאוּיָה לְאוֹתוֹ הַמִּין. וְהוֹאִיל וְלֹא הָיָה בְּעִקַּר הַבְּרָכָה טָעוּת אַף עַל פִּי שֶׁטָּעָה בְּסוֹפָהּ יָצָא וְאֵין מַחְזִירִין אוֹתוֹ:","כָּל הַבְּרָכוֹת הָאֵלּוּ אִם נִסְתַּפֵּק לוֹ בָּהֶם אִם בֵּרֵךְ אוֹ לֹא בֵּרֵךְ אֵינוֹ חוֹזֵר וּמְבָרֵךְ לֹא בַּתְּחִלָּה וְלֹא בַּסּוֹף. מִפְּנֵי שֶׁהֵן מִדִּבְרֵי סוֹפְרִים. שָׁכַח וְהִכְנִיס אֳכָלִין לְתוֹךְ פִּיו בְּלֹא בְּרָכָה. אִם הָיוּ מַשְׁקִין בּוֹלְעָן וּמְבָרֵךְ עֲלֵיהֶן בַּסּוֹף. וְאִם הָיוּ פֵּרוֹת שֶׁאִם זְרָקָן יִמָּאֲסוּ כְּגוֹן תּוּתִים וַעֲנָבִים מְסַלְּקָן לְצַד אֶחָד וּמְבָרֵךְ וְאַחַר כָּךְ בּוֹלְעָן. וְאִם אֵינָן נִמְאָסִין כְּגוֹן פּוֹלִים וַאֲפוּנִים פּוֹלְטָן מִפִּיו עַד שֶׁיְּבָרֵךְ וּפִיו פָּנוּי וְאַחַר כָּךְ אוֹכֵל:","הָיוּ לְפָנָיו מִינִין הַרְבֵּה אִם הָיוּ בִּרְכוֹתֵיהֶן שָׁווֹת מְבָרֵךְ עַל אַחַת מֵהֶם וּפוֹטֵר אֶת הַשְּׁאָר. וְאִם אֵין בִּרְכוֹתֵיהֶם שָׁווֹת מְבָרֵךְ עַל כָּל אַחַת מֵהֶן בְּרָכָה הָרְאוּיָה לוֹ. וְאֵי זֶה מֵהֶם שֶׁיִּרְצֶה לְהַקְדִּים מַקְדִּים. וְאִם אֵינוֹ רוֹצֶה בְּזֶה יוֹתֵר מִזֶּה אִם יֵשׁ בֵּינֵיהֶם אֶחָד מִשִּׁבְעַת הַמִּינִים עָלָיו הוּא מְבָרֵךְ תְּחִלָּה. וְכָל הַקּוֹדֵם בַּפָּסוּק קוֹדֵם בַּבְּרָכָה. וְהַשִּׁבְעָה הֵן הָאֲמוּרִים בְּפָסוּק זֶה (דברים ח ח) ״אֶרֶץ חִטָּה וּשְׂעוֹרָה וְגֶפֶן וּתְאֵנָה וְרִמּוֹן אֶרֶץ זֵית שֶׁמֶן וּדְבַשׁ״. וּדְבַשׁ זֶה הוּא דְּבַשׁ תְּמָרִים. וְהַתְּמָרִים קוֹדְמִין לַעֲנָבִים. שֶׁהַתְּמָרִים שֵׁנִי לְאֶרֶץ וְהָעֲנָבִים שְׁלִישִׁי לְאֶרֶץ:","בְּרָכָה אַחַת שֶׁהִיא מֵעֵין שָׁלֹשׁ שֶׁל חֲמֵשֶׁת הַמִּינִין שֶׁל פֵּרוֹת וְשֶׁל יַיִן הִיא שֶׁל מִינֵי הַדָּגָן. אֶלָּא שֶׁעַל הַפֵּרוֹת הוּא אוֹמֵר עַל הָעֵץ וְעַל פְּרִי הָעֵץ וְעַל תְּנוּבַת הַשָּׂדֶה וְעַל אֶרֶץ חֶמְדָּה וְכוּ׳‎. וְעַל הַיַּיִן הוּא אוֹמֵר עַל הַגֶּפֶן וְעַל פְּרִי הַגֶּפֶן. וְחוֹתֵם בִּשְׁתֵּיהֶן עַל הָאָרֶץ וְעַל הַפֵּרוֹת. וְאִם הָיָה בְּאֶרֶץ יִשְׂרָאֵל חוֹתֵם עַל הָאָרֶץ וְעַל פֵּרוֹתֶיהָ. וְיֵשׁ מִי שֶּׁמּוֹסִיף בַּבְּרָכָה שֶׁמֵּעֵין שָׁלֹשׁ קֹדֶם חֲתִימָה כִּי אֵל טוֹב וּמֵטִיב אַתָּה שֶׁהוּא מֵעֵין בְּרָכָה רְבִיעִית. וְיֵשׁ מִי שֶׁאָמַר שֶׁלֹּא תִּקְּנוּ בְּרָכָה רְבִיעִית אֶלָּא בְּבִרְכַּת הַמָּזוֹן בִּלְבַד:","שָׁתָה יַיִן וְאָכַל תְּמָרִים וְאָכַל תַּבְשִׁיל שֶׁל חֲמֵשֶׁת מִינֵי דָּגָן מְבָרֵךְ בָּאַחֲרוֹנָה. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם עַל הַמִּחְיָה וְעַל הַכַּלְכָּלָה וְעַל הַגֶּפֶן וְעַל פְּרִי הַגֶּפֶן וְעַל הָעֵץ וְעַל פְּרִי הָעֵץ וְעַל תְּנוּבַת הַשָּׂדֶה וְעַל אֶרֶץ חֶמְדָּה וְכוּ׳‎ וְחוֹתֵם בָּרוּךְ אַתָּה יְיָ׳‎ עַל הָאָרֶץ וְעַל הַמִּחְיָה וְעַל הַפֵּרוֹת:","אֲבָל אִם אָכַל בָּשָׂר וְשָׁתָה יַיִן מְבָרֵךְ בַּסּוֹף עַל זֶה בִּפְנֵי עַצְמוֹ וְעַל זֶה בִּפְנֵי עַצְמוֹ. אָכַל תְּאֵנִים אוֹ עֲנָבִים וְתַפּוּחִים וַאֲגַסִּים וְכַיּוֹצֵא בָּהֶן מְבָרֵךְ בַּסּוֹף בְּרָכָה אַחַת מֵעֵין שָׁלֹשׁ וְהִיא כּוֹלֶלֶת הַכּל מִפְּנֵי שֶׁכֻּלָּן פֵּרוֹת הָעֵץ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Circumcision 3":["הַמָּל מְבָרֵךְ קֹדֶם שֶׁיָּמוּל אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל הַמִּילָה, אִם מָל בֶּן חֲבֵרוֹ. וְאִם מָל אֶת בְּנוֹ מְבָרֵךְ וְצִוָּנוּ לָמוּל אֶת הַבֵּן. וַאֲבִי הַבֵּן מְבָרֵךְ בְּרָכָה אַחֶרֶת. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהַכְנִיסוֹ בִּבְרִיתוֹ שֶׁל אַבְרָהָם אָבִינוּ. מִצְוָה עַל הָאָב לָמוּל אֶת בְּנוֹ יָתֵר עַל מִצְוָה שֶׁמְּצֻוִּין יִשְׂרָאֵל שֶׁיָּמוּלוּ כָּל עָרֵל שֶׁבֵּינֵיהֶן. לְפִיכָךְ אִם אֵין שָׁם אָבִיו אֵין מְבָרְכִין אַחֲרֶיהָ בְּרָכָה זוֹ. וְיֵשׁ מִי שֶׁהוֹרָה שֶׁיְּבָרְכוּ אוֹתָהּ בֵּית דִּין אוֹ אֶחָד מִן הָעָם. וְאֵין רָאוּי לַעֲשׂוֹת כֵּן:","וְאִם הָיוּ שָׁם עוֹמְדִין אוֹמְרִים כְּשֵׁם שֶׁהִכְנַסְתּוֹ לַבְּרִית כֵּן תַּכְנִיסֵהוּ לְתוֹרָה וּלְחֻפָּה וּלְמַעֲשִׂים טוֹבִים:","וְאַחַר כָּךְ מְבָרֵךְ אֲבִי הַבֵּן אוֹ הַמָּל אוֹ אֶחָד מִן הָעוֹמְדִין שָׁם. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדַּשׁ יְדִיד מִבֶּטֶן וְחֹק בִּשְׁאֵרוֹ שָׂם וְצֶאֱצָאָיו חָתַם בְּאוֹת בְּרִית קֹדֶשׁ עַל כֵּן בִּשְׂכַר זֹאת אֵל חַי חֶלְקֵנוּ צוּרֵנוּ צַוֵּה לְהַצִּיל יְדִידוּת שְׁאֵרֵנוּ מִשַּׁחַת לְמַעַן בְּרִיתוֹ אֲשֶׁר שָׂם בִּבְשָׂרֵנוּ. בָּרוּךְ אַתָּה יְיָ׳‎ כּוֹרֵת הַבְּרִית. וַאֲבִי הַבֵּן מְבָרֵךְ שֶׁהֶחֱיָנוּ:","הַמָּל אֶת הַגֵּרִים מְבָרֵךְ. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לָמוּל אֶת הַגֵּרִים וּלְהַטִּיף מִמֶּנּוּ דַּם בְּרִית שֶׁאִלְמָלֵא דַּם הַבְּרִית לֹא נִתְקַיְּמוּ שָׁמַיִם וָאָרֶץ שֶׁנֶּאֱמַר (ירמיה לג כה) ״אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי״:","הַמָּל אֶת עַבְדּוֹ מְבָרֵךְ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לָמוּל אֶת הָעֲבָדִים וּלְהַטִּיף מֵהֶן דַּם בְּרִית שֶׁאִלְמָלֵא דַּם בְּרִית לֹא נִתְקַיְּמוּ שָׁמַיִם וָאָרֶץ. וְאִם מָל עֶבֶד שֶׁל אֲחֵרִים מְבָרֵךְ עַל מִילַת הָעֲבָדִים. וְהַמָּל אָדָם גָּדוֹל צָרִיךְ לְכַסּוֹת עֶרְוָתוֹ עַד שֶׁיְּבָרֵךְ וְאַחַר כָּךְ מְגַלֵּהוּ וּמָל אוֹתוֹ:","גֵּר שֶׁמָּל קֹדֶם שֶׁנִּתְגַּיֵּר וְקָטָן שֶׁנּוֹלַד כְּשֶׁהוּא מָהוּל כְּשֶׁמַּטִּיפִין מִמֶּנּוּ דַּם בְּרִית אֵינָן צְרִיכִין בְּרָכָה. וְכֵן אַנְדְּרוֹגִינוּס אֵין מְבָרְכִין עַל מִלָּתוֹ מִפְּנֵי שֶׁהוּא אֵינוֹ זָכָר וַדַּאי:","עַכּוּ״ם שֶׁצָּרִיךְ לַחְתֹּךְ עָרְלָתוֹ מִפְּנֵי מַכָּה אוֹ מִפְּנֵי שְׁחִין שֶׁנּוֹלַד בּוֹ הָיָה אָסוּר לְיִשְׂרָאֵל לַחְתֹּךְ לוֹ אוֹתָהּ, שֶׁהָעַכּוּ״ם אֵין מַעֲלִים אוֹתָם מִידֵי מִיתָה וְלֹא מוֹרִידִין אוֹתָן אֵלֶיהָ, אַף עַל פִּי שֶׁנַּעֲשֵׂית מִצְוָה בִּרְפוּאָה זוֹ, שֶׁהֲרֵי לֹא נִתְכַּוֵּן לְמִצְוָה. לְפִיכָךְ אִם נִתְכַּוֵּן הָעַכּוּ״ם לְמִילָה מֻתָּר לְיִשְׂרָאֵל לָמוּל אוֹתוֹ:","מְאוּסָה הִיא הָעָרְלָה שֶׁנִּתְגַּנּוּ בָּהּ הַגּוֹיִם שֶׁנֶּאֱמַר (ירמיה ט כה) ״כִּי כָּל הַגּוֹיִם עֲרֵלִים״. וּגְדוֹלָה הִיא הַמִּילָה שֶׁלֹּא נִקְרָא אַבְרָהָם אָבִינוּ שָׁלֵם עַד שֶׁמָּל שֶׁנֶּאֱמַר (בראשית יז א) ״הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים״ (בראשית יז ב) ״וְאֶתְּנָה בְרִיתִי בֵּינִי וּבֵינֶךָ״ וְגוֹ׳‎. וְכָל הַמֵּפֵר בְּרִיתוֹ שֶׁל אַבְרָהָם אָבִינוּ וְהִנִּיחַ עָרְלָתוֹ אוֹ מְשָׁכָהּ אַף עַל פִּי שֶׁיֵּשׁ בּוֹ תּוֹרָה וּמַעֲשִׂים טוֹבִים אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא:","בּוֹא וּרְאֵה כַּמָּה חֲמוּרָה מִילָה שֶׁלֹּא נִתְלָה לְמשֶׁה רַבֵּנוּ עָלֶיהָ אֲפִלּוּ שָׁעָה אַחַת אַף עַל פִּי שֶׁהָיָה בַּדֶּרֶךְ. וְכָל מִצְוֹת הַתּוֹרָה נִכְרְתוּ עֲלֵיהֶן שָׁלֹשׁ בְּרִיתוֹת. שֶׁנֶּאֱמַר (דברים כח סט) ״אֵלֶּה דִבְרֵי הַבְּרִית אֲשֶׁר צִוָּה יְיָ׳‎״, (דברים כח סט) ״מִלְּבַד הַבְּרִית אֲשֶׁר כָּרַת אִתָּם בְּחֹרֵב״. וְשָׁם הוּא אוֹמֵר (דברים כט ט) ״אַתֶּם נִצָּבִים הַיּוֹם כֻּלְּכֶם״ (דברים כט יא) ״לְעָבְרְךָ בִּבְרִית יְיָ׳‎ אֱלֹהֶיךָ״, הֲרֵי שָׁלֹשׁ בְּרִיתוֹת. וְעַל הַמִּילָה נִכְרְתוּ שְׁלֹשׁ עֶשְׂרֵה בְּרִיתוֹת עִם אַבְרָהָם אָבִינוּ. (בראשית יז ב) ״וְאֶתְּנָה בְרִיתִי בֵּינִי וּבֵינֶךָ״. (בראשית יז ד) ״אֲנִי הִנֵּה בְרִיתִי אִתָּךְ״. וַהֲקִמֹתִי אֶת בְּרִיתִי בֵּינִי וּבֵינֶךָ. לִבְרִית עוֹלָם. (בראשית יז ט) ״וְאַתָּה אֶת בְּרִיתִי תִשְׁמֹר״. (בראשית יז י) ״זֹאת בְּרִיתִי אֲשֶׁר תִּשְׁמְרוּ״. (בראשית יז יא) ״וְהָיָה לְאוֹת בְּרִית״. (בראשית יז יג) ״וְהָיְתָה בְרִיתִי בִּבְשַׂרְכֶם״. לִבְרִית עוֹלָם. (בראשית יז יד) ״אֶת בְּרִיתִי הֵפַר״. (בראשית יז יט) ״וַהֲקִמֹתִי אֶת בְּרִיתִי אִתּוֹ. לִבְרִית עוֹלָם״. (בראשית יז כא) ״וְאֶת בְּרִיתִי אָקִים אֶת יִצְחָק״: בְּרִיךְ רַחֲמָנָא דְּסַיְּעָן"],"Mishneh Torah, Creditor and Debtor 2":["דִּין תּוֹרָה שֶׁבִּזְמַן שֶׁיִּתְבַּע הַמַּלְוֶה אֶת חוֹבוֹ אִם נִמְצְאוּ לַלּוֶֹה נְכָסִים מְסַדְּרִין לוֹ וְנוֹתְנִין לְבַעַל חוֹבוֹ אֶת הַשְּׁאָר כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם לֹא נִמְצָא לַלּוֶֹה כְּלוּם אוֹ נִמְצְאוּ לוֹ דְּבָרִים שֶׁמְּסַדְּרִין לוֹ בִּלְבַד יֵלֵךְ הַלּוֶֹה לְדַרְכּוֹ וְאֵין אוֹסְרִין אוֹתוֹ וְאֵין אוֹמְרִים לוֹ הָבֵא רְאָיָה שֶׁאַתָּה עָנִי וְלֹא מַשְׁבִּיעִין אוֹתוֹ כְּדֶרֶךְ שֶׁדָּנִין הָעַכּוּ\"ם שֶׁנֶּאֱמַר (שמות כב כד) \"לֹא תִהְיֶה לוֹ כְּנשֶׁה\". אֶלָּא אוֹמְרִים לַמַּלְוֶה אִם אַתָּה יוֹדֵעַ נְכָסִים לְזֶה הַמְחֻיָּב לְךָ לֵךְ וּתְפֹס אוֹתָן:","טָעַן שֶׁיֵּשׁ לוֹ וְהֶחְבִּיא אוֹתָן וַהֲרֵי הֵן בְּתוֹךְ בֵּיתוֹ אֵין מִן הַדִּין שֶׁיִּכָּנֵס לְבֵיתוֹ לֹא הוּא וְלֹא שְׁלִיחַ בֵּית דִּין שֶׁהַתּוֹרָה הִקְפִּידָה עַל זֶה שֶׁנֶּאֱמַר (דברים כד יא) \"בַּחוּץ תַּעֲמֹד\". אֲבָל מַחְרִימִין עַל מִי שֶׁיֵּשׁ לוֹ וְלֹא יִתֵּן לְבַעַל חוֹבוֹ. כְּשֶׁרָאוּ הַגְּאוֹנִים הָרִאשׁוֹנִים שֶׁעָמְדוּ אַחַר חִבּוּר הַגְּמָרָא שֶׁרַבּוּ הָרַמָּאִים וְנִנְעֲלָה דֶּלֶת בִּפְנֵי לוִֹין הִתְקִינוּ שֶׁמַּשְׁבִּיעִין אֶת הַלּוֶֹה שְׁבוּעָה חֲמוּרָה כְּעֵין שֶׁל תּוֹרָה בִּנְקִיטַת חֵפֶץ שֶׁאֵין לוֹ כְּלוּם יֶתֶר עַל דְּבָרִים שֶׁמְּסַדְּרִין לוֹ. וְשֶׁלֹּא הֶחְבִּיאָן בְּיַד אֲחֵרִים וְשֶׁלֹּא נָתַן מַתָּנָה עַל מְנָת לְהַחְזִיר. וְכוֹלֵל בִּשְׁבוּעָה זוֹ שֶׁכָּל שֶׁיַּרְוִיחַ וְכָל שֶׁיָּבוֹא לְיָדוֹ אוֹ לִרְשׁוּתוֹ מֵאֲשֶׁר תַּשִּׂיג יָדוֹ לֹא יַאֲכִיל מִמֶּנּוּ כְּלוּם לֹא לְאִשְׁתּוֹ וְלֹא לְבָנָיו וְלֹא יַלְבִּישׁ אוֹתָן וְלֹא יְטַפֵּל בָּהֶן וְלֹא יִתֵּן מַתָּנָה לְאָדָם בָּעוֹלָם. אֶלָּא יוֹצִיא מִכָּל אֲשֶׁר תַּשִּׂיג יָדוֹ מְזוֹן שְׁלֹשִׁים יוֹם וּכְסוּת שְׁנֵים עָשָׂר חֹדֶשׁ מָזוֹן הָרָאוּי לוֹ וּכְסוּת הָרָאוּי לוֹ. לֹא אֲכִילַת הַזּוֹלְלִים וְהַסּוֹבְאִין אוֹ בְּנֵי מְלָכִים וְלֹא מַלְבּוּשֵׁי הַפָּחוֹת וְהַסְּגָנִים אֶלָּא כְּדַרְכּוֹ. וְכָל הַיֶּתֶר עַל צָרְכּוֹ יִתֵּן לְבַעַל חוֹבוֹ רִאשׁוֹן רִאשׁוֹן עַד שֶׁיַּגְבֶּנּוּ כָּל חוֹבוֹ. וּמַחְרִימִין תְּחִלָּה עַל מִי שֶׁיֵּדַע לִפְלוֹנִי נְכָסִים גְּלוּיִין אוֹ טְמוּנִין וְלֹא יוֹדִיעַ לְבֵית דִּין. גַּם אַחַר הַתַּקָּנָה הַזֹּאת אֵין בַּעַל חוֹב יָכוֹל לְהִכָּנֵס לְתוֹךְ בֵּיתוֹ שֶׁל לוֶֹה לֹא הוּא וְלֹא שְׁלִיחַ בֵּית דִּין שֶׁלֹּא תִּקְּנוּ לַעֲקֹר גּוּף הַתּוֹרָה אֶלָּא הַלּוֶֹה עַצְמוֹ יוֹצִיא כֵּלָיו אוֹ יֹאמַר כָּךְ וְכָךְ הוּא שֶׁיֵּשׁ לִי מַנִּיחִין הָרָאוּי לוֹ וְיוֹצִיא הַשְּׁאָר וְיִשָּׁבַע בְּתַקָּנָה זוֹ וְכָזֶה דָּנִין יִשְׂרָאֵל בְּכָל מְקוֹמוֹתָן. נִרְאֶה לוֹ מָמוֹן אַחַר שֶׁנִּשְׁבַּע שְׁבוּעָה זוֹ וְאָמַר שֶׁל אֲחֵרִים הוּא אוֹ עֵסֶק הוּא בְּיָדִי אֵין שׁוֹמְעִין לוֹ עַד שֶׁיָּבִיא רְאָיָה. וְכֵן הוֹרוּ רַבּוֹתַי:","מִי שֶׁנִּשְׁבַּע שְׁבוּעָה זוֹ שֶׁאֵין לוֹ כְּלוּם וְכָל מַה שֶּׁיַּרְוִיחַ יִתֵּן לְבַעַל חוֹב אֵין כָּל אֶחָד מִבַּעֲלֵי חוֹבוֹת בָּא וּמַשְׁבִּיעוֹ שֶׁשְּׁבוּעָה אַחַת כּוֹלֶלֶת כָּל בַּעֲלֵי חוֹבוֹת. וְתַקָּנַת אַחֲרוֹנִים הִיא וְאֵין מְדַקְדְּקִין בָּהּ לְהַחְמִיר אֶלָּא לְהָקֵל:","מִי שֶׁהֻחְזַק שֶׁהוּא עָנִי וְכָשֵׁר וְהוֹלֵךְ בְּתֹם וְהַדָּבָר גָּלוּי וְיָדוּעַ לַדַּיָּן וּלְרֹב הָעָם וּבָא בַּעַל חוֹבוֹ לְהַשְׁבִּיעוֹ בְּתַקָּנָה זוֹ וְהֻחְזַק הַתּוֹבֵעַ שֶׁאֵינוֹ מִסְתַּפֵּק בַּעֲנִיּוּת זֶה אֶלָּא רוֹצֶה לְצַעֲרוֹ בִּשְׁבוּעָה זוֹ לְהָצֵר לוֹ וּלְבַיְּשׁוֹ בָּרַבִּים כְּדֵי לְהִנָּקֵם מִמֶּנּוּ אוֹ כְּדֵי שֶׁיֵּלֵךְ וְיִלְוֶה מִן הָעַכּוּ\"ם אוֹ יִקַּח נִכְסֵי אִשְׁתּוֹ וְיִתֵּן לָזֶה עַד שֶׁיִּנָּצֵל מִשְּׁבוּעָה זוֹ. יֵרָאֶה לִי שֶׁאָסוּר לְדַיָּן יְרֵא שָׁמַיִם לְהַשְׁבִּיעוֹ שְׁבוּעָה זוֹ וְאִם הִשְׁבִּיעוֹ בִּטֵּל לֹא תַּעֲשֶׂה שֶׁל תּוֹרָה לֹא תִהְיֶה לוֹ כְּנשֶׁה. וְלֹא עוֹד אֶלָּא רָאוּי לַדַּיָּן לִגְעֹר בַּתּוֹבֵעַ וּלְטָרְדוֹ מִפְּנֵי שֶׁהוּא נוֹטֵר וְהוֹלֵךְ בִּשְׁרִירוּת לִבּוֹ. שֶׁלֹּא תִּקְּנוּ הַגְּאוֹנִים תַּקָּנָה זוֹ אֶלָּא מִפְּנֵי הָרַמָּאִין וַהֲרֵי נֶאֱמַר (דברים כב ב) \"עַד דְּרשׁ אָחִיךָ אֹתוֹ\" דָּרְשֵׁהוּ אִם רַמַּאי הוּא אוֹ אֵינוֹ רַמַּאי וּמֵאַחַר שֶׁהֻחְזַק זֶה שֶׁהוּא עָנִי וְשֶׁאֵינוֹ רַמַּאי אָסוּר לְהַשְׁבִּיעוֹ. וְכֵן אֲנִי אוֹמֵר שֶׁמִּי שֶׁהֻחְזַק רַמַּאי וּדְרָכָיו מְקֻלְקָלִין בְּמַשָּׂאוֹ וּמַתָּנוֹ וַהֲרֵי הוּא אָמוּד שֶׁיֵּשׁ לוֹ מָמוֹן וְטָעַן שֶׁאֵין לוֹ כְּלוּם וַהֲרֵי הוּא רָץ לְהִשָּׁבַע בְּתַקָּנָה זוֹ שֶׁאֵין רָאוּי לְהַשְׁבִּיעוֹ אֶלָּא אִם יֵשׁ כֹּחַ בַּדַּיָּן לַעֲשׂוֹתוֹ עַד שֶׁיִּפְרַע בַּעַל חוֹבוֹ אוֹ לְנַדּוֹתוֹ עַד שֶׁיִּתֵּן יַעֲשֶׂה מֵאַחַר שֶׁהוּא אָמוּד. שֶׁפְּרִיעַת בַּעַל חוֹב מִצְוָה. כְּלָלוֹ שֶׁל דָּבָר כָּל שֶׁיַּעֲשֶׂה הַדַּיָּן מִדְּבָרִים אֵלּוּ וְכַוָּנָתוֹ לִרְדֹּף הַצֶּדֶק בִּלְבַד שֶׁנִּצְטַוֵּינוּ לְרָדְפוֹ וְלֹא לַעֲבֹר הַדִּין עַל אֶחָד מִבַּעֲלֵי דִּינִין הֲרֵי זֶה מֻרְשֶׁה לַעֲשׂוֹת וּמְקַבֵּל שָׂכָר. וְהוּא שֶׁיִּהְיוּ מַעֲשָׂיו לְשֵׁם שָׁמַיִם:","מִי שֶׁנִּתְחַיֵּב בִּשְׁבוּעָה זוֹ מִפְּנֵי שְׁטַר חוֹב שֶׁעָלָיו וְהוֹדָה לַאֲחֵרִים בְּחוֹבוֹת אֲחֵרִים וְהִשִּׂיגָה יָדוֹ יֶתֶר עַל הָרָאוּי לוֹ לֹא יִטּל הַיֶּתֶר אֶלָּא בַּעֲלֵי שְׁטָרוֹת בִּלְבַד. שֶׁמָּא קְנוּנְיָא עוֹשֶׂה בְּהוֹדָאָתוֹ עַל נְכָסָיו שֶׁל זֶה:","רְאוּבֵן שֶׁהָיָה חַיָּב לְשִׁמְעוֹן מֵאָה וְלֵוִי חַיָּב לִרְאוּבֵן מֵאָה מוֹצִיאִין מִלֵּוִי וְנוֹתְנִין לְשִׁמְעוֹן. לְפִיכָךְ אִם אֵין לִרְאוּבֵן נְכָסִים וְהָיוּ לוֹ שִׁטְרֵי חוֹב עַל לֵוִי וְאָמַר לֵוִי שְׁטַר אֲמָנָה הוּא פָּרוּעַ הוּא וְהוֹדָה לוֹ רְאוּבֵן אֵין מַשְׁגִּיחִין עַל הוֹדָאָתוֹ שֶׁמָּא קְנוּנְיָא הֵם עוֹשִׂין לְאַבֵּד זְכוּתוֹ שֶׁל שִׁמְעוֹן אֶלָּא יִשָּׁבַע שִׁמְעוֹן וְיִטּל מִלֵּוִי כְּדִין כָּל טוֹרֵף שֶׁאֵינוֹ נִפְרָע אֶלָּא בִּשְׁבוּעָה. וְכֵן כָּל מִי שֶׁיֵּשׁ עָלָיו שְׁטַר חוֹב וְהוֹדָה לְאַחֵר מֵעַצְמוֹ בְּחוֹב אַחֵר אִם אֵין לוֹ נְכָסִים כְּדֵי שֶׁיִּגְבּוּ שְׁנֵיהֶם גּוֹבֶה בַּעַל הַשְּׁטָר בִּלְבַד שֶׁלֹּא יַעֲשׂוּ קְנוּנְיָא עַל שְׁטָרוֹ שֶׁל זֶה:","אָסוּר לָאָדָם לְהַלְווֹת מְעוֹתָיו בְּלֹא עֵדִים וַאֲפִלּוּ לְתַלְמִיד חָכָם אֶלָּא אִם כֵּן הִלְוָהוּ עַל הַמַּשְׁכּוֹן. וְהַמַּלְוֶה בִּשְׁטָר מְשֻׁבָּח יָתֵר. וְכָל הַמַּלְוֶה בְּלֹא עֵדִים עוֹבֵר מִשּׁוּם (ויקרא יט יד) \"וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁל\" וְגוֹרֵם קְלָלָה לְעַצְמוֹ:","הָרַב שֶׁלָּוָה מֵעַבְדּוֹ וְאַחַר כָּךְ שִׁחְרְרוֹ אוֹ לָוָה מֵאִשְׁתּוֹ וְאַחַר כָּךְ גֵּרְשָׁהּ אֵין לָהֶן עָלָיו כְּלוּם שֶׁכָּל מַה שֶּׁקָּנָה עֶבֶד קָנָה רַבּוֹ וְכָל הַמָּעוֹת שֶׁבְּיַד הָאִשָּׁה בְּחֶזְקַת בַּעְלָהּ אֶלָּא אִם הֵבִיאָה רְאָיָה שֶׁהֵן מִנְּדֻנְיָתָהּ:"],"Mishneh Torah, Creditor and Debtor 6":["הַמַּלְוֶה אֶת חֲבֵרוֹ סֶלַע בַּחֲמִשָּׁה דִּינָרִים אוֹ סָאתַיִם חִטִּים בְּשָׁלֹשׁ אוֹ סֶלַע בְּסֶלַע וּסְאָה אוֹ שָׁלֹשׁ סְאִין בְּשָׁלֹשׁ סְאִין וְדִינָר כְּלָלוֹ שֶׁל דָּבָר כָּל הַלְוָאָה בְּתוֹסֶפֶת כָּל שֶׁהוּא הֲרֵי זוֹ רִבִּית שֶׁל תּוֹרָה וְיוֹצְאָה בְּדַיָּנִין. וְכֵן הַמַּלְוֶה אֶת חֲבֵרוֹ וְהִתְנָה עִמּוֹ שֶׁיָּדוּר בַּחֲצֵרוֹ חִנָּם עַד שֶׁיַּחְזִיר לוֹ הַלְוָאָתוֹ. אוֹ שֶׁשָּׂכַר מִמֶּנּוּ בְּפָחוֹת וְקָצַב הַדָּבָר שֶׁפּוֹחֵת לוֹ מִן הַשָּׂכָר עַד שֶׁיַּחְזִיר לוֹ הַלְוָאָתוֹ. אוֹ שֶׁמִּשְׁכֵּן בְּיָדוֹ מָקוֹם שֶׁפֵּרוֹתָיו מְצוּיִין בְּעֵת הַהַלְוָאָה כְּגוֹן שֶׁמִּשְׁכֵּן חֲצֵרוֹ עַל מְנָת שֶׁיָּדוּר בּוֹ בְּחִנָּם. הֲרֵי זוֹ רִבִּית שֶׁל תּוֹרָה וְיוֹצְאָה בְּדַיָּנִין. וְכֵן הַמּוֹכֵר שָׂדֶה אוֹ חָצֵר בְּאַסְמַכְתָּא הוֹאִיל וְלֹא קָנָה הַגּוּף הֲרֵי כָּל הַפֵּרוֹת שֶׁאָכַל רִבִּית וּמַחֲזִיר אוֹתָן. וְהוּא הַדִּין לְכָל מִי [שֶׁלֹּא] קָנָה קִנְיָן גָּמוּר מִתְּחִלָּה שֶׁהוּא מַחְזִיר אֶת הַפֵּרוֹת מִפְּנֵי שֶׁאִם אָכַל אֶת הַפֵּרוֹת הֲרֵי זוֹ רִבִּית שֶׁל תּוֹרָה. וְכָל דָּבָר שֶׁהוּא אָסוּר מִשּׁוּם רִבִּית חוּץ מֵאֵלּוּ הֲרֵי הוּא אָסוּר מִדִּבְרֵיהֶם גְּזֵרָה שֶׁמָּא יָבֹא לְרִבִּית שֶׁל תּוֹרָה. וְהוּא הַנִּקְרָא אֲבַק רִבִּית וְאֵינוֹ יוֹצֵא בְּדַיָּנִין:","הַמַּלְוֶה אֶת חֲבֵרוֹ לֹא יִמְשֹׁךְ אֶת עַבְדּוֹ כְּדֵי שֶׁיַּעֲשֶׂה בּוֹ מְלָאכָה אַף עַל פִּי שֶׁהָעֶבֶד יוֹשֵׁב וּבָטֵל. וְלֹא יָדוּר בַּחֲצֵרוֹ בְּחִנָּם אַף עַל פִּי שֶׁאֵין הֶחָצֵר עֲשׂוּיָה לְשָׂכָר וְאֵין דֶּרֶךְ בַּעַל הֶחָצֵר לְהַשְׂכִּיר. וְאִם דָּר צָרִיךְ לְהַעֲלוֹת לוֹ שָׂכָר. וְאִם לֹא הֶעֱלָה לוֹ הֲרֵי זֶה אֲבַק רִבִּית לְפִי שֶׁלֹּא הִתְנָה עִמּוֹ שֶׁיַּלְוֵהוּ וְיָדוּר בַּחֲצֵרוֹ. לְפִיכָךְ אִם עֲדַיִן לֹא הֶחְזִיר לוֹ חוֹבוֹ וּבָא לְנַכּוֹת שְׂכַר הֶחָצֵר שֶׁדָּר בָּהּ מִן הַחוֹב אִם הָיָה הַשָּׂכָר כְּנֶגֶד הַחוֹב אֵינוֹ מְנַכֶּה לוֹ הַכּל אֶלָּא כְּמוֹ שֶׁיִּרְאוּ הַדַּיָּנִים. שֶׁאִם תְּסַלֵּק אוֹתוֹ בְּלֹא כְּלוּם הֲרֵי זֶה כְּמוֹ שֶׁהוֹצִיא אוֹתוֹ בְּדַיָּנִין וַאֲבַק רִבִּית אֵינָהּ יוֹצְאָה בְּדַיָּנִין:","הוֹרוּ רַבּוֹתַי שֶׁהַמַּלְוֶה אֶת חֲבֵרוֹ וּלְאַחַר זְמַן תָּבַע חוֹבוֹ וְאָמַר לוֹ הַלּוֶֹה דּוּר בַּחֲצֵרִי עַד שֶׁאַחְזִיר לְךָ חוֹבְךָ הֲרֵי זֶה אֲבַק רִבִּית לְפִי שֶׁלֹּא קָצַץ בִּשְׁעַת הַלְוָאָה שֶׁנֶּאֱמַר (ויקרא כה לז) \"לֹא תִתֵּן לוֹ בְּנֶשֶׁךְ\":","הַמַּלְוֶה אֶת חֲבֵרוֹ עַל הַשָּׂדֶה וְאָמַר לוֹ אִם לֹא תַּחְזִיר לִי מִכָּאן עַד שָׁלֹשׁ שָׁנִים הֲרֵי הִיא שֶׁלִּי הֲרֵי זֶה לֹא קָנָה מִפְּנֵי שֶׁהִיא אַסְמַכְתָּא. לְפִיכָךְ מְנַכֶּה כָּל הַפֵּרוֹת שֶׁאָכַל מִפְּנֵי שֶׁהוּא רִבִּית שֶׁל תּוֹרָה. אֲבָל אִם אָמַר לוֹ הַמּוֹכֵר אִם לֹא אַחְזִיר לְךָ עַד שָׁלֹשׁ שָׁנִים קְנֵה אוֹתָהּ מֵעַכְשָׁו וְהֵבִיא לוֹ בְּתוֹךְ שָׁלֹשׁ אֵין לוֹ פֵּרוֹת. הֵבִיא לוֹ לְאַחַר שָׁלֹשׁ הֲרֵי כָּל הַפֵּרוֹת לַלּוֹקֵחַ:","הַמּוֹכֵר בַּיִת אוֹ שָׂדֶה וְאָמַר הַמּוֹכֵר לַלּוֹקֵחַ לִכְשֶׁיִּהְיוּ לִי מָעוֹת תַּחְזִיר לִי קַרְקָעִי לֹא קָנָה וְכָל הַפֵּרוֹת שֶׁאָכַל רִבִּית קְצוּצָה וּמוֹצִיאִין אוֹתָם בְּדַיָּנִין. אֲבָל אִם אָמַר לוֹ הַלּוֹקֵחַ מִדַּעְתּוֹ כְּשֶׁיִּהְיוּ לְךָ מָעוֹת אֲנִי אַחְזִיר לְךָ קַרְקַע זֶה מֻתָּר וְהַלּוֹקֵחַ אוֹכֵל פֵּרוֹת עַד שֶׁיַּחְזִיר לוֹ מְעוֹתָיו:","מָכַר לוֹ אֶת הַשָּׂדֶה וְנָתַן לוֹ מִקְצָת הַדָּמִים אִם אָמַר לוֹ הַמּוֹכֵר לַלּוֹקֵחַ קְנֵה כְּשִׁעוּר מְעוֹתֶיךָ כָּל אֶחָד מִשְּׁנֵיהֶם אוֹכֵל פֵּרוֹת כְּשִׁעוּר מְעוֹתָיו. אָמַר הַמּוֹכֵר לַלּוֹקֵחַ לִכְשֶׁתָּבִיא שְׁאָר הַמָּעוֹת תִּקְנֶה מֵעַכְשָׁו שְׁנֵיהֶם אֲסוּרִים לֶאֱכל הַפֵּרוֹת מִיָּד. הַמּוֹכֵר אָסוּר שֶׁמָּא יָבִיא הַלּוֹקֵחַ שְׁאָר הַמָּעוֹת וְנִמְצֵאת הַשָּׂדֶה שֶׁלּוֹ וְנִמְצָא הַמּוֹכֵר אוֹכֵל פֵּרוֹת בִּשְׁבִיל הַמָּעוֹת שֶׁנִּשְׁאֲרוּ לוֹ אֵצֶל הַלּוֹקֵחַ וְכֵן הַלּוֹקֵחַ אָסוּר שֶׁמָּא לֹא יָבִיא וְנִמְצָא שֶׁאָכַל בִּשְׁבִיל מִקְצָת הַמָּעוֹת שֶׁיֵּשׁ לוֹ אֵצֶל הַמּוֹכֵר. לְפִיכָךְ מַנִּיחִין אֶת הַפֵּרוֹת עַל יְדֵי שָׁלִישׁ עַד שֶׁיִּנָּתְנוּ לְאֶחָד מֵהֶן. אָמַר לוֹ הַמּוֹכֵר לִכְשֶׁתָּבִיא שְׁאָר הַמָּעוֹת תִּקְנֶה הֲרֵי הַמּוֹכֵר אוֹכֵל פֵּרוֹת עַד שֶׁיָּבִיא הַלּוֹקֵחַ וְאִם אָכַל הַלּוֹקֵחַ מוֹצִיאִין מִמֶּנּוּ. אָמַר לוֹ הַמּוֹכֵר קְנֵה מֵעַכְשָׁו וּשְׁאָר הַמָּעוֹת הֲרֵי הֵן חוֹב אֶצְלְךָ הֲרֵי הַלּוֹקֵחַ אוֹכֵל פֵּרוֹת וְאִם אָכַל הַמּוֹכֵר מוֹצִיאִין מִמֶּנּוּ כָּל מַה שֶּׁאָכַל:","הוֹרוּ רַבּוֹתַי שֶׁהַמַּלְוֶה אֶת חֲבֵרוֹ וּמִשְׁכֵּן לוֹ שָׂדֵהוּ עַל מְנָת שֶׁיֹּאכַל פֵּרוֹתֶיהָ כָּל יְמֵי הַמַּשְׁכּוֹנָא אַף עַל פִּי שֶׁאֵינוֹ מְנַכֶּה לוֹ כְּלוּם הֲרֵי זוֹ אֲבַק רִבִּית וְאֵינָהּ יוֹצְאָה בְּדַיָּנִין שֶׁאֵין הַמְמַשְׁכֵּן אֶת הַשָּׂדֶה דּוֹמֶה לִמְמַשְׁכֵּן בַּיִת שֶׁהֲרֵי אֵין בַּשָּׂדֶה פֵּרוֹת מְצוּיִין בְּעֵת הַהַלְוָאָה וְאֶפְשָׁר שֶׁיַּרְוִיחַ וְיִהְיוּ שָׁם פֵּרוֹת וְאֶפְשָׁר שֶׁיַּפְסִיד בִּזְרִיעָתָהּ וַעֲבוֹדָתָהּ וּלְפִיכָךְ הִיא אֲבַק רִבִּית. וְכֵן אֵין הַמַּשְׁכּוֹנָא דּוֹמָה לְמִי שֶׁמָּכַר בְּאַסְמַכְתָּא שֶׁהַמּוֹכֵר בְּאַסְמַכְתָּא לֹא גָּמַר וְהִקְנָהוּ וְהַמְמַשְׁכֵּן גָּמַר וְהִקְנָהוּ גּוּף זֶה לְפֵרוֹתָיו. וְכָזֶה יֵרָאֶה מִן הַגְּמָרָא. שֶׁהַמַּשְׁכּוֹנָא אֲבַק רִבִּית וְאֵין לְךָ לְהַעֲמִידָהּ אֶלָּא בִּמְמַשְׁכֵּן שָׂדֵהוּ כְּמוֹ שֶׁהוֹרוּ רַבּוֹתַי. נִמְצֵאתָ לָמֵד שֶׁשָּׁלֹשׁ מַשְׁכּוֹנוֹת הֵן. מַשְׁכּוֹנָא שֶׁהִיא רִבִּית קְצוּצָה. וּמַשְׁכּוֹנָא שֶׁהִיא אֲבַק רִבִּית. וּמַשְׁכּוֹנָא שֶׁהִיא מֻתֶּרֶת. כֵּיצַד. מִשְׁכֵּן לוֹ מָקוֹם שֶׁפֵּרוֹתָיו מְצוּיִין תָּדִיר כְּגוֹן חָצֵר אוֹ מֶרְחָץ אוֹ חֲנוּת וְאָכַל פֵּרוֹתֵיהֶן הֲרֵי זוֹ רִבִּית קְצוּצָה. מִשְׁכֵּן לוֹ שָׂדֶה וְכַיּוֹצֵא בָּהּ וּבָאוּ שָׁם פֵּרוֹת וַאֲכָלָן הֲרֵי זוֹ אֲבַק רִבִּית. וְכֵן אִם מִשְׁכֵּן חֲצֵרוֹ וְכַיּוֹצֵא בָּהּ בְּנִכּוּי הֲרֵי זֶה אֲבַק רִבִּית. מִשְׁכֵּן שָׂדֵהוּ בְּנִכּוּי הֲרֵי זֶה מֻתָּר. כֵּיצַד הוּא הַנִּכּוּי. כְּגוֹן שֶׁהִלְוָהוּ מֵאָה דִּינָרִין וּמִשְׁכֵּן לוֹ בָּהֶן חֲצֵרוֹ אוֹ שָׂדֵהוּ וְאָמַר לוֹ הַמַּלְוֶה הֲרֵינִי מְנַכֶּה לְךָ מָעָה כֶּסֶף בְּכָל שָׁנָה בִּשְׂכַר קַרְקַע זוֹ כְּדֵי שֶׁיִּהְיוּ כָּל פֵּרוֹתָיו שֶׁלִּי בְּחָצֵר וְכַיּוֹצֵא בָּהּ אָסוּר וּבְשָׂדֶה וְכַיּוֹצֵא בָּהּ מֻתָּר:","הוֹרוּ מִקְצָת גְּאוֹנִים שֶׁכָּל מַשְׁכּוֹנָא שֶׁאֵין בָּהּ נִכּוּי כְּלָל הֲרֵי הִיא רִבִּית קְצוּצָה. וְלֹא יָרְדוּ לְעֹמֶק הַדָּבָר לְהַפְרִישׁ בֵּין שָׂדֶה לְחָצֵר וּלְפִיכָךְ נִתְקַשּׁוּ לָהֶן דִּבְרֵי חַכְמֵי הַגְּמָרָא. וְכֵן הוֹרוּ שֶׁכָּל מַשְׁכּוֹנָא אֲפִלּוּ בְּנִכּוּי אָסוּר בֵּין בְּחָצֵר בֵּין בְּשָׂדֶה וְאֵין לָהֶם מַשְׁכּוֹנָא מֻתֶּרֶת אֶלָּא בַּדֶּרֶךְ הַזֹּאת. כֵּיצַד. כְּגוֹן שֶׁהִלְוָהוּ מֵאָה דִּינָרִין וּמִשְׁכֵּן לוֹ בָּהֶן בַּיִת אוֹ שָׂדֶה וְהִתְנָה עִמּוֹ שֶׁאַחַר עֶשֶׂר שָׁנִים תַּחְזֹר קַרְקַע זוֹ לִבְעָלֶיהָ חִנָּם הֲרֵי זֶה מֻתָּר לֶאֱכל פֵּרוֹתֶיהָ כָּל עֶשֶׂר שָׁנִים אֲפִלּוּ הָיָה שְׂכָרָהּ שָׁוֶה אֶלֶף דִּינָרִים בְּכָל שָׁנָה שֶׁאֵין זֶה אֶלָּא כְּמִי שֶׁשָּׂכַר בְּפָחוֹת. וְכֵן אִם הִתְנָה בַּעַל הַשָּׂדֶה עִמּוֹ כָּל זְמַן שֶׁיָּבִיא לוֹ מָעוֹת יֵחָשֵׁב לוֹ עֶשֶׂר בְּכָל שָׁנָה וִיסַלְּקוֹ מִמֶּנָּה הֲרֵי זֶה מֻתָּר. וְכֵן אִם הִתְנָה הַלּוֶֹה שֶׁכָּל זְמַן שֶׁיִּרְצֶה מְחַשֵּׁב לוֹ מַה שֶּׁדָּר בּוֹ וְיַחְזִיר לוֹ שְׁאָר הַדָּמִים וְיִסְתַּלֵּק הֲרֵי זֶה מֻתָּר שֶׁאֵין זֶה אֶלָּא כִּשְׂכִירוּת וְכָל תְּנַאי שֶׁבִּשְׂכִירוּת מֻתָּר כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Daily Offerings and Additional Offerings 8":["בְּיוֹם חֲמִשִּׁים מִסְּפִירַת הָעֹמֶר. הוּא חַג הַשָּׁבוּעוֹת. וְהוּא עֲצֶרֶת. וּבַיּוֹם הַזֶּה מַקְרִיבִין מוּסָף כְּמוֹ מוּסַף רֹאשׁ חֹדֶשׁ שְׁנֵי פָּרִים וְאַיִל וְשִׁבְעָה כְּבָשִׂים כֻּלָּם עוֹלוֹת וּשְׂעִיר חַטָּאת. וְאֵלּוּ הֵן הַקָּרְבָּנוֹת הָאֲמוּרוֹת בְּחֻמַּשׁ הַפְּקוּדִים וְהֵם מוּסַף הַיּוֹם. וְעוֹד מְבִיאִין יֶתֶר עַל הַמּוּסָף בַּיּוֹם הַזֶּה מִנְחָה חֲדָשָׁה שְׁתֵּי הַלֶּחֶם וּמַקְרִיבִין עִם הַלֶּחֶם פַּר וּשְׁנֵי אֵילִים וְשִׁבְעָה כְּבָשִׂים. הַכּל עוֹלוֹת. וּשְׂעִיר חַטָּאת. וּשְׁנֵי כְּבָשִׂים זֶבַח שְׁלָמִים. וְאֵלּוּ הֵן הַקָּרְבָּנוֹת הָאֲמוּרוֹת בְּחֻמַּשׁ וַיִּקְרָא. נִמְצָא הַקָּרֵב בְּיוֹם זֶה יֶתֶר עַל שְׁנֵי הַתְּמִידִין שְׁלֹשָׁה פָּרִים וּשְׁלֹשָׁה אֵילִים וְאַרְבָּעָה עָשָׂר כְּבָשִׂים. הַכּל עֶשְׂרִים בְּהֵמָה עוֹלוֹת. וּשְׁנֵי שְׂעִירֵי חַטָּאוֹת נֶאֱכָלִים. וּשְׁנֵי כְּבָשִׂים שְׁלָמִים נֶאֱכָלִים:","שְׁתֵּי הַלֶּחֶם אֵינָן בָּאִין אֶלָּא מִן הָאָרֶץ וּמִן הֶחָדָשׁ שֶׁנֶּאֱמַר (ויקרא כג יז) \"מִמּוֹשְׁבֹתֵיכֶם תָּבִיאוּ לֶחֶם תְּנוּפָה\" וְגוֹ'. לֹא מָצְאוּ חָדָשׁ יָבִיאוּ מִן הָעֲלִיָּה:","חִטִּים שֶׁיָּרְדוּ בְּעָבִים יֵשׁ בָּהֶם סָפֵק אִם אֲנִי קוֹרֵא בָּהֶם (ויקרא כג יז) \"מִמּוֹשְׁבֹתֵיכֶם\" אוֹ אֵינָם מִמּוֹשְׁבֹתֵיכֶם לְפִיכָךְ לֹא יָבִיא וְאִם הֵבִיא כָּשֵׁר. וְכֵיצַד הָיוּ עוֹשִׂין. מְבִיאִין שָׁלֹשׁ סְאִין חִטִּין חֲדָשׁוֹת וְשָׁפִין אוֹתָן וּבוֹעֲטִין בָּהֶם כְּדֶרֶךְ כָּל הַמְּנָחוֹת וְטוֹחֲנִין אוֹתָן סֹלֶת וּמְנַפִּין מֵהֶן שְׁנֵי עֶשְׂרוֹנוֹת מְנֻפֶּה בִּשְׁתֵּים עֶשְׂרֵה נָפָה וְהַשְּׁאָר נִפְדֶּה וְנֶאֱכָל לְכָל אָדָם. וְחַיָּב בְּחַלָּה וּפָטוּר מִן הַמַּעַשְׂרוֹת כְּמוֹ שֶׁבֵּאַרְנוּ:","שְׁתֵּי הַלֶּחֶם שֶׁהֵן מִן הֶחָדָשׁ צְרִיכִין לָבוֹא עִשָּׂרוֹן מִכָּל סְאָה וּמֶחֱצָה וּמְנַפִּין אוֹתָן בִּשְׁתֵּים עֶשְׂרֵה נָפָה. וְלֶחֶם הַפָּנִים שֶׁהוּא בָּא מִן הַיָּשָׁן דַּי לוֹ בְּאַחַת עֶשְׂרֵה נָפָה וְהוּא בָּא עִשָּׂרוֹן מִכָּל סְאָה. אֲבָל הָעֹמֶר שֶׁהוּא בָּא מִן הַשְּׂעוֹרִים חֲדָשׁוֹת אֵינוֹ בָּא מִן הַמֻּבְחָר אֶלָּא מִשָּׁלֹשׁ סְאִין וּבִשְׁלֹשׁ עֲשָׂרָה נָפָה:","וְכֻלָּם אִם רִבָּה בְּמִדַּת הַסְּאִין שֶׁבָּאִין מֵהֶן אוֹ מִעֵט כָּשֵׁר:","וְלוֹקְחִין שְׁנֵי הָעֶשְׂרוֹנוֹת וְלָשִׁין אוֹתָן אַחַת אַחַת וְאוֹפִין אוֹתָן אַחַת אַחַת:","וְלִישָׁתָן וַעֲרִיכָתָן בַּחוּץ וַאֲפִיָּתָן בִּפְנִים כְּכָל הַמְּנָחוֹת:","וְאֵין עֲשִׂיָּתָן דּוֹחָה יוֹם טוֹב וְאֵין צָרִיךְ לוֹמַר שַׁבָּת אֶלָּא אוֹפִין אוֹתָן מֵעֶרֶב יוֹם טוֹב שֶׁנֶּאֱמַר (שמות יב טז) \"הוּא לְבַדּוֹ יֵעָשֶׂה לָכֶם\" לָכֶם וְלֹא לְגָבוֹהַּ:","הָיָה עֶרֶב יוֹם טוֹב שַׁבָּת אוֹפִין אוֹתָן מֵעֶרֶב שַׁבָּת וְנֶאֱכָלוֹת בַּשְּׁלִישִׁי לַאֲפִיָּתָן שֶׁהוּא יוֹם טוֹב. וַהֲרֵי מְפֹרָשׁ בַּתּוֹרָה שֶׁהֵם חָמֵץ. וְכֵיצַד עוֹשֶׂה. מֵבִיא שְׂאוֹר מִמָּקוֹם אַחֵר וְנוֹתְנוֹ לְתוֹךְ הָעִשָּׂרוֹן וּמְמַלֵּא הָעִשָּׂרוֹן סֹלֶת וּמְחַמְּצוֹ בְּאוֹתוֹ הַשְּׂאוֹר:","וּמְרֻבָּעוֹת הֵן. אֹרֶךְ כָּל חַלָּה שִׁבְעָה טְפָחִים וְרָחְבָּהּ אַרְבָּעָה טְפָחִים וְגָבְהָהּ אַרְבַּע אֶצְבָּעוֹת:","כֵּיצַד הֲנָפַת הַלֶּחֶם עִם שְׁנֵי כִּבְשֵׂי הַשְּׁלָמִים. מֵבִיא שְׁנֵי הַכְּבָשִׂים וּמְנִיפָם בְּעוֹדָן חַיִּים שֶׁנֶּאֱמַר (ויקרא יד יב) \"וְהֵנִיף אֹתָם תְּנוּפָה\". וְאִם הֵנִיף זֶה בִּפְנֵי עַצְמוֹ וְזֶה בִּפְנֵי עַצְמוֹ יָצָא. וְאַחַר כָּךְ שׁוֹחֲטִין אוֹתָן וּמַפְשִׁיט. וְלוֹקֵחַ חָזֶה וְשׁוֹק מִכָּל אֶחָד מִשְּׁנֵיהֶם וּמַנִּיחָן בְּצַד שְׁתֵּי הַלֶּחֶם וּמֵנִיחַ שְׁתֵּי יָדָיו מִלְּמַטָּן וּמֵנִיף הַכּל כְּאֶחָד בַּמִּזְרָח בִּמְקוֹם כָּל הַתְּנוּפוֹת. מוֹלִיךְ וּמֵבִיא. מַעֲלֶה וּמוֹרִיד. וְאִם הֱנִיפָן אֶחָד אֶחָד יָצָא. וְאַחַר כָּךְ מַקְטִיר אֵימוּרֵי שְׁנֵי הַכְּבָשִׂים וּשְׁאָר הַבָּשָׂר נֶאֱכָל לַכֹּהֲנִים. וְכֵן שְׁתֵּי הַחַלּוֹת נוֹטֵל כֹּהֵן גָּדוֹל אַחַת מֵהֶן. וְהַשְּׁנִיָּה מִתְחַלֶּקֶת לְכָל הַמִּשְׁמָרוֹת. וּשְׁתֵּיהֶן נֶאֱכָלוֹת אוֹתוֹ הַיּוֹם וַחֲצִי הַלַּיְלָה כִּבְשַׂר קָדְשֵׁי קָדָשִׁים:","שָׁחַט שְׁנֵי כְּבָשִׂים עַל אַרְבַּע חַלּוֹת. אִם אָמַר יִקָּדְשׁוּ שְׁתַּיִם מִתּוֹךְ אַרְבַּע מוֹשֵׁךְ שְׁתַּיִם מֵהֶן וּמְנִיפָן. וְהַשְּׁאָר פּוֹדִין אוֹתָן בִּפְנִים וְנֶאֱכָלִין בַּחוּץ כִּשְׁאָר הַחֻלִּין. וְאִם לֹא הִתְנָה לֹא קָדַשׁ הַלֶּחֶם:","שָׁחַט אַרְבָּעָה כְּבָשִׂים עַל שְׁתֵּי חַלּוֹת. מוֹשֵׁךְ שְׁנַיִם מֵהֶם וְזוֹרֵק דָּמָן שֶׁלֹּא לִשְׁמָן. וּמֵנִיף הַשְּׁנַיִם הַנִּשְׁאָרִים הַכְּשֵׁרִים עִם שְׁתֵּי הַלֶּחֶם:","שְׁתֵּי הַחַלּוֹת מְעַכְּבוֹת זוֹ אֶת זוֹ. וּשְׁנֵי הַכְּבָשִׂים מְעַכְּבִין זֶה אֶת זֶה. מֵת אֶחָד מִשְּׁנֵיהֶם אוֹ בָּרַח אוֹ נַעֲשָׂה טְרֵפָה. יִקַּח זוּג לְשֵׁנִי. שָׁחַט אֶחָד לִשְׁמוֹ. יִקַּח לוֹ זוּג:","שְׁתֵּי הַלֶּחֶם מְעַכְּבִים אֶת הַכְּבָשִׂים. וּשְׁנֵי הַכְּבָשִׂים אֵינָן מְעַכְּבִים אֶת הַלֶּחֶם. וְאִם הוּנְפוּ עִם הַכְּבָשִׂים מְעַכְּבִין זֶה אֶת זֶה. וְאִם אָבַד הַלֶּחֶם יֹאבְדוּ הַכְּבָשִׂים וְאִם אָבְדוּ הַכְּבָשִׂים יֹאבְדוּ הַלֶּחֶם וְיָבִיאוּ לֶחֶם אַחֵר וּכְבָשִׂים אֲחֵרִים:","שְׁתֵּי הַלֶּחֶם הַבָּאוֹת בִּפְנֵי עַצְמָן בְּלֹא כְּבָשִׂים כֵּיצַד עוֹשִׂין בָּהֶן. יוּנְפוּ וּתְעֻבַּר צוּרָתָן וְיֵצְאוּ לְבֵית הַשְּׂרֵפָה גְּזֵרָה שֶׁמָּא יִמְצְאוּ כְּבָשִׂים לְשָׁנָה הַבָּאָה וְיָבִיאוּ לֶחֶם בְּלֹא כְּבָשִׂים. הַפָּר וּשְׁנֵי הָאֵילִים וְשִׁבְעַת הַכְּבָשִׂים וְהַשָּׂעִיר הַבָּאִים בְּיוֹם זֶה בִּגְלַל הַלֶּחֶם אֵינָן מְעַכְּבִין אֶת הַלֶּחֶם וְלֹא הַלֶּחֶם מְעַכְּבָן:","שְׁנֵי פָּרִים שֶׁל מוּסַף הַיּוֹם וּפַר הַבָּא בִּגְלַל הַלֶּחֶם אֵינָן מְעַכְּבִין זֶה אֶת זֶה:","אַיִל שֶׁל מוּסַף הַיּוֹם וּשְׁנֵי אֵילִים הַבָּאִין בִּגְלַל הַלֶּחֶם אֵינָן מְעַכְּבִין (זֶה אֶת זֶה):","שִׁבְעָה כְּבָשִׂים שֶׁל מוּסַף הַיּוֹם וְשִׁבְעָה כְּבָשִׂים הַבָּאִים בִּגְלַל הַלֶּחֶם אֵינָן מְעַכְּבִין זֶה אֶת זֶה. וְאִם נִשְׁחֲטוּ כֻּלָּן מְעַכְּבִין זֶה אֶת זֶה:","הַתְּמִידִין אֵינָם מְעַכְּבִין אֶת הַמּוּסָפִין וְלֹא הַמּוּסָפִין מְעַכְּבִין אֶת הַתְּמִידִין וְלֹא הַמּוּסָפִין מְעַכְּבִין זֶה אֶת זֶה וְלֹא מִנְיַן הָעוֹלוֹת כֻּלָּן מְעַכֵּב. כֵּיצַד. הֲרֵי שֶׁלֹּא מָצְאוּ אֶלָּא שִׁשָּׁה כְּבָשִׂים מַקְרִיבִין שִׁשָּׁה אֲפִלּוּ לֹא מָצְאוּ אֶלָּא אֶחָד מַקְרִיבִין אוֹתוֹ בֵּין בְּרָאשֵׁי חֳדָשִׁים בֵּין בִּימֵי הַמּוֹעֲדוֹת וְהַשַּׁבָּתוֹת. וְאֵינָן חַיָּבִין לְהַקְרִיב הַשְּׁאָר לְמָחָר אוֹ לְמוֹעֵד אַחֵר אֶלָּא כָּל קָרְבַּן צִבּוּר שֶׁעָבַר זְמַנּוֹ בָּטֵל קָרְבָּנוֹ. לֹא מָצְאוּ אֶלָּא שְׁנֵי כְּבָשִׂים אִם יַקְרִיבוּ אוֹתָן לְמוּסַף הַיּוֹם אֵין לָהֶן תְּמִידִין לְמָחָר. הֲרֵי הַדָּבָר שָׁקוּל אִם הִקְרִיבוּם לְמוּסַף הַיּוֹם הִקְרִיבוּ וְאִם רָצוּ לְהַנִּיחָם לְמָחָר לִתְמִידִין יַנִּיחוּ:"],"Mishneh Torah, Damages to Property 6":["אֵיזֶהוּ מוּעָד כָּל שֶׁהֵעִידוּ בּוֹ שְׁלֹשָׁה יָמִים. אֲבָל אִם נָגַח בְּיוֹם אֶחָד אוֹ נָשַׁךְ אוֹ רָבַץ אוֹ בָּעַט אוֹ נָגַף אֲפִלּוּ מֵאָה פְּעָמִים אֵין זֶה מוּעָד. הֵעִידוּ בּוֹ שְׁלֹשָׁה כִּתֵּי עֵדִים בְּיוֹם אֶחָד הֲרֵי זֶה סָפֵק אִם הוּעַד אוֹ לֹא הוּעַד:","אֵין הֶעָדָה אֶלָּא בִּפְנֵי הַבְּעָלִים וּבִפְנֵי בֵּית דִּין שֶׁנֶּאֱמַר (שמות כא כט) \"וְהוּעַד בִּבְעָלָיו\". וְאֵין הֶעָדָה אֶלָּא בְּבֵית דִּין:","שׁוֹר שֶׁל חֵרֵשׁ שׁוֹטֶה וְקָטָן וּמִי שֶׁהוּא בִּמְדִינַת הַיָּם שֶׁנָּגְחוּ פְּטוּרִין. אֲבָל בֵּית דִּין מַעֲמִידִין לָהֶם אַפּוֹטְרוֹפְּסִין וּמְעִידִין בָּהֶן בִּפְנֵי הָאַפּוֹטְרוֹפְּסִין:","הִזִּיקוּ אַחַר שֶׁהוּעֲדוּ בִּפְנֵי אַפּוֹטְרוֹפְּסִין אִם עֲדַיִן הוּא תָּם מְשַׁלֵּם חֲצִי נֵזֶק מִגּוּפוֹ וְאִם הוּעַד בּוֹ שְׁלֹשָׁה יָמִים וְאַחַר כָּךְ הִזִּיק מְשַׁלֵּם נֵזֶק שָׁלֵם מִן הַיָּפֶה שֶׁבְּנִכְסֵי אַפּוֹטְרוֹפְּסִין. וְלִכְשֶׁיִּגְדְּלוּ הַיְתוֹמִים יַעֲשׂוּ דִּין עִם הָאַפּוֹטְרוֹפְּסִין וִישַׁלְּמוּ לָהֶן:","שְׁוָרִים שֶׁמְּשַׂחֲקִין בָּהֶן וּמְלַמְּדִין אוֹתָן לִגַּח זֶה אֶת זֶה אֵינָם מוּעָדִים זֶה לָזֶה. וַאֲפִלּוּ הֵמִיתוּ אֶת הָאָדָם אֵינָן חַיָּבִין מִיתָה שֶׁנֶּאֱמַר (שמות כא כח) \"כִי יִגַּח\" לֹא שֶׁיַּגִּיחוּהוּ:","שׁוֹר שֶׁהוּעַד וְנִמְכַּר אוֹ נִתַּן בְּמַתָּנָה חָזַר לְתַמּוּתוֹ שֶׁהָרְשׁוּת שֶׁנִּשְׁתַּנֵּית מְשַׁנָּה דִּינוֹ. אֲבָל אִם הִשְׁאִילוֹ אוֹ מְסָרוֹ לְשׁוֹמֵר הֲרֵי הוּא בְּחֶזְקָתוֹ. וְכֵן שׁוֹר שֶׁהוּעַד בִּפְנֵי אַפּוֹטְרוֹפְּסִין וְנִתְפַּקֵּחַ הַחֵרֵשׁ וְנִשְׁתַּפָּה הַשּׁוֹטָה וְהִגְדִּיל הַקָּטָן אַף עַל פִּי שֶׁבָּטְלוּ הָאַפּוֹטְרוֹפְּסִין הֲרֵי הֵן מוּעָדִין בְּחֶזְקָתָן שֶׁהֲרֵי בִּרְשׁוּת בְּעָלִים הֵן:","בְּהֵמָה שֶׁהוּעֲדָה וְחָזְרָה בָּהּ מִדָּבָר שֶׁהוּעֲדָה לוֹ חָזְרָה לְתַמּוּתָהּ. כֵּיצַד. שׁוֹר שֶׁהוּעַד לִגַּח וְחָזַר שֶׁלֹּא לִגַּח אַף עַל פִּי שֶׁהוּא נוֹגֵף הֲרֵי זֶה תָּם לִנְגִיחָה. וּמֵאֵימָתַי הוּא חֲזָרָתוֹ עַד שֶׁיִּהְיוּ הַתִּינוֹקוֹת מְמַשְׁמְשִׁין בּוֹ וְאֵינוֹ נוֹגֵחַ. וְכֵן בִּשְׁאָר הַדְּבָרִים שֶׁהוּעַד לָהֶן עַד שֶׁיְּמַשְׁמְשׁוּ בּוֹ וְלֹא יִהְיֶה עוֹשֶׂה אוֹתָן:","שׁוֹר שֶׁהוּא מוּעָד לְמִינוֹ הֲרֵי זֶה אֵינוֹ מוּעָד לְשֶׁאֵינוֹ מִינוֹ. הוּעַד לְאָדָם אֵינוֹ מוֹעֵד לִבְהֵמָה. הוּעַד לִקְטַנִּים אֵינוֹ מוּעָד לִגְדוֹלִים. לְפִיכָךְ אִם הִזִּיק אֶת מִין שֶׁהוּא מוּעָד לוֹ מְשַׁלֵּם נֵזֶק שָׁלֵם וְאִם הִזִּיק לִשְׁאָר הַמִּינִין מְשַׁלֵּם חֲצִי נֵזֶק. הָיָה מוּעָד לְשַׁבָּתוֹת אֵינוֹ מוּעָד לִימוֹת הַחל וְאִם הִזִּיק בְּשַׁבָּתוֹת מְשַׁלֵּם נֵזֶק שָׁלֵם וּבִימוֹת הַחל מְשַׁלֵּם חֲצִי נֵזֶק. וּמֵאֵימָתַי הִיא חֲזָרָתוֹ מִשֶּׁיְּמַשְׁמְשׁוּ הַתִּינוֹקוֹת בּוֹ בַּיּוֹם שֶׁהוּא מוּעָד לוֹ וְלֹא יִהְיֶה מַזִּיק נֵזֶק שֶׁהוּעַד לוֹ:","נָגַח שׁוֹר הַיּוֹם וַחֲמוֹר לְמָחָר וְגָמָל בְּיוֹם שְׁלִישִׁי נַעֲשָׂה מוּעָד לַכּל. רָאָה שׁוֹר הַיּוֹם וּנְגָחוֹ. וּלְמָחָר רָאָה שׁוֹר וְלֹא נְגָחוֹ. וּבַיּוֹם הַשְּׁלִישִׁי רָאָה שׁוֹר וּנְגָחוֹ. וּבָרְבִיעִי רָאָה שׁוֹר וְלֹא נְגָחוֹ. וּבַחֲמִישִׁי רָאָה שׁוֹר וּנְגָחוֹ. וּבַשִּׁשִּׁי רָאָה שׁוֹר וְלֹא נְגָחוֹ. נַעֲשָׂה מוּעָד לְסֵרוּגִין לִשְׁוָרִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","רָאָה שׁוֹר הַיּוֹם וּנְגָחוֹ. וּלְמָחָר רָאָה חֲמוֹר וְלֹא נְגָחוֹ. וּבַשְּׁלִישִׁי רָאָה סוּס וּנְגָחוֹ. וּבָרְבִיעִי רָאָה גָּמָל וְלֹא נְגָחוֹ. וּבַחֲמִישִׁי רָאָה פֶּרֶד וּנְגָחוֹ. וּבַשִּׁשִּׁי רָאָה עָרוֹד וְלֹא נְגָחוֹ. נַעֲשָׂה מוּעָד לְסֵרוּגִין לַכּל וְאִם נָגַח בַּיּוֹם שֶׁהוּא מוּעָד לוֹ אֶחָד מִשְּׁלֹשֶׁת הַמִּינִין שֶׁנָּגַח בְּסֵרוּגִין הֲרֵי זֶה מוּעָד:","נָגַח בַּחֲמִשָּׁה עָשָׂר לְחֹדֶשׁ זֶה. וּבְשִׁשָּׁה עָשָׂר לְחֹדֶשׁ שֵׁנִי. וּבְשִׁבְעָה עָשָׂר לְחֹדֶשׁ שְׁלִישִׁי. אֵינוֹ מוּעָד עַד שֶׁיְּשַׁלֵּשׁ בַּדִּלּוּג. שָׁמַע קוֹל שׁוֹפָר וְנָגַח קוֹל שׁוֹפָר וְנָגַח קוֹל שׁוֹפָר וְנָגַח נַעֲשָׂה מוּעָד לְשׁוֹפָרוֹת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","נָגַח שְׁלֹשָׁה שְׁוָרִים בִּשְׁלֹשָׁה יָמִים זֶה אַחַר זֶה וּבָרְבִיעִי נָגַח חֲמוֹר וּבַחֲמִישִׁי נָגַח גָּמָל אוֹ שֶׁנָּגַח חֲמוֹר וְגָמָל בַּתְּחִלָּה בִּשְׁנֵי יָמִים זֶה אַחַר זֶה וְאַחַר כָּךְ נָגַח שְׁלֹשָׁה שְׁוָרִים זֶה אַחַר זֶה הֲרֵי זֶה סָפֵק אִם הוּא מוּעָד לִשְׁוָרִים בִּלְבַד אוֹ לִשְׁלֹשֶׁת הַמִּינִין הוּא מוּעָד. וְכֵן אִם נָגַח בְּשָׁלֹשׁ שַׁבָּתוֹת זוֹ אַחַר זוֹ וּבְאֶחָד בְּשַׁבָּת וּבְשֵׁנִי בְּשַׁבָּת אוֹ שֶׁנָּגַח בַּחֲמִישִׁי בְּשַׁבָּת וּבְעֶרֶב שַׁבָּת וּבְיוֹם הַשַּׁבָּת וּבִשְׁתֵּי שַׁבָּתוֹת הַבָּאוֹת אַחֲרֶיהָ הֲרֵי זֶה סָפֵק אִם הוּא מוּעָד לְשַׁבָּתוֹת בִּלְבַד אוֹ לִשְׁלֹשֶׁת הַיָּמִים שֶׁשְּׁנַיִם מֵהֶן חל:","וְכָל אֵלּוּ הַסְּפֵקוֹת וְכַיּוֹצֵא בָּהֶן אֵין מְחַיְּבִין בָּהֶן אֶת הַמַּזִּיק אֶלָּא חֲצִי נֵזֶק. וְאִם תָּפַשׂ הַנִּזָּק נֵזֶק שָׁלֵם אֵין מוֹצִיאִין מִיָּדוֹ:"],"Mishneh Torah, Defilement by Leprosy 2":["שֵׂעָר לָבָן שֶׁהוּא סִימַן טֻמְאָה בְּצָרַעַת אֵין פָּחוֹת מִשְּׁתֵּי שְׂעָרוֹת. וְכַמָּה יִהְיֶה אָרְכָּן כְּדֵי שֶׁיִּהְיוּ נִטָּלוֹת בְּזוּג. הָיְתָה אַחַת אֲרֻכָּה וְאַחַת קְצָרָה מִשִּׁעוּר זֶה. אוֹ אַחַת שְׁחוֹרָה וְאַחַת לְבָנָה. אוֹ אַחַת מִלְּמַטָּה וְנֶחְלְקָה מִלְּמַעְלָה וְנִרְאֵית כִּשְׁתַּיִם. אוֹ שֶׁהָיָה עִקָּרָן מַשְׁחִיר וְרֹאשָׁן מַלְבִּין. הֲרֵי זֶה טָהוֹר. הָיָה עִקָּרָן מַלְבִּין וְרֹאשָׁן מַשְׁחִיר אַף עַל פִּי שֶׁהַלָּבָן כָּל שֶׁהוּא טָמֵא:","שְׁתֵּי שְׂעָרוֹת לְבָנוֹת שֶׁהֵן בְּתוֹךְ הַנֶּגַע אַף עַל פִּי שֶׁיֵּשׁ שֵׂעָר שָׁחוֹר בֵּינֵיהֶן וְהֵן מְפֻזָּרוֹת אַחַת כָּאן וְאַחַת כָּאן הֲרֵי אֵלּוּ סִימַן טֻמְאָה. אֲפִלּוּ הָיָה הַנֶּגַע כִּגְרִיס מְצֻמְצָם אֵין מְקוֹם שֵׂעָר הַשָּׁחוֹר מְמַעֲטוֹ. וּבֵין שֶׁהָיוּ שְׁתֵּי הַשְּׂעָרוֹת בְּתוֹךְ הַבַּהֶרֶת וְהִיא מַקַּפְתָּן וּבֵין שֶׁהָיוּ בְּסוֹפָהּ הֲרֵי זֶה טָמֵא. אֲבָל אִם הָיוּ בְּצִדָּהּ מִבַּחוּץ הֲרֵי זֶה טָהוֹר עַד שֶׁיִּהְיֶה הָעוֹר שֶׁצּוֹמְחוֹת שְׁתֵּי הַשְּׂעָרוֹת הַלְּבָנוֹת לָבָן. הָיוּ שְׁתֵּי שְׂעָרוֹת בְּתוֹךְ הַנֶּגַע וְשׁוֹכְבוֹת חוּצָה לוֹ טָמֵא. הָיוּ חוּצָה לוֹ וְשׁוֹכְבוֹת בְּתוֹכוֹ אֵינָן סִימַן טֻמְאָה:","לֹבֶן הַשְּׂעָרוֹת מְטַמֵּא בְּכָל מַרְאֶה בֵּין שֶׁהָיוּ לְבָנוֹת כַּשֶּׁלֶג בֵּין שֶׁהָיוּ לְבָנוֹת לֹבֶן דָּהֶה בְּיוֹתֵר הוֹאִיל וּמַרְאֵיהֶן לָבָן טָמֵא:","אֵין שֵׂעָר לָבָן סִימַן טֻמְאָה עַד שֶׁיִּהְיֶה בְּגוּף הַבַּהֶרֶת. כֵּיצַד. בַּהֶרֶת וּבְתוֹכָהּ שְׁחִין אוֹ מִכְוָה אוֹ בֹּהַק אוֹ מִחְיַת הַשְּׁחִין אוֹ מִחְיַת הַמִּכְוָה וּשְׁתֵּי שְׂעָרוֹת לְבָנוֹת בְּתוֹךְ הַשְּׁחִין אוֹ הַמִּכְוָה אוֹ הַבֹּהַק שֶׁבְּתוֹךְ הַנֶּגַע אֵינָן סִימַן טֻמְאָה וַהֲרֵי זוֹ כְּבַהֶרֶת שֶׁאֵין בָּהּ שֵׂעָר לָבָן וְיַסְגִּיר אַף עַל פִּי שֶׁהַבַּהֶרֶת מַקֶּפֶת אֶת הַשְּׁחִין אוֹ אֶת הַמִּכְוָה אוֹ אֶת מִחְיָתָן אוֹ אֶת הַבֹּהַק שֶׁיֵּשׁ בָּהֶן שְׁתֵּי הַשְּׂעָרוֹת. וְכֵן אִם הָיָה שְׁחִין אוֹ מִכְוָה אוֹ מִחְיָתָן אוֹ בֹּהַק מַקִּיף אֶת שְׁתֵּי הַשְּׂעָרוֹת הֲרֵי אֵלּוּ אֵינָן סִימַן טֻמְאָה וַהֲרֵי הַבַּהֶרֶת כְּבַהֶרֶת שֶׁאֵין בָּהּ שֵׂעָר לָבָן וְיַסְגִּיר:","הָלְכוּ לָהֶן הַשְּׁחִין וְהַבֹּהַק וְהַמִּכְוָה שֶׁהִקִּיפוּ אֶת הַשְּׂעָרוֹת הַלְּבָנוֹת אוֹ נִסְמָכִין לָהֶן אוֹ חוֹלְקִין אוֹתָן. וְנִמְצְאוּ שְׁתֵּי הַשְּׂעָרוֹת בְּתוֹךְ הַבַּהֶרֶת בְּגוּפָהּ בְּסוֹף הַשָּׁבוּעַ הָרִאשׁוֹן אוֹ בְּסוֹף הַשָּׁבוּעַ הַשֵּׁנִי הֲרֵי זֶה מֻחְלָט. וְאִם לֹא הָלְכוּ לָהֶן יִפְטְרֶנּוּ:","אֵין שֵׂעָר לָבָן סִימַן טֻמְאָה עַד שֶׁתַּקְדִּים הַבַּהֶרֶת אֶת הַשֵּׂעָר הַלָּבָן שֶׁנֶּאֱמַר (ויקרא יג י) \"וְהִיא הָפְכָה שֵׂעָר לָבָן\" שֶׁתַּהֲפֹךְ אוֹתוֹ הַבַּהֶרֶת. אֲבָל אִם קָדַם שֵׂעָר לָבָן אֶת הַבַּהֶרֶת הֲרֵי הִיא כְּבַהֶרֶת שֶׁאֵין בָּהּ סִימַן טֻמְאָה וְיַסְגִּיר:","הָיְתָה בּוֹ בַּהֶרֶת וּבָהּ שֵׂעָר לָבָן וְהֻחְלַט בּוֹ וְאַחַר כָּךְ הָלְכָה הַבַּהֶרֶת וְהִנִּיחָה שֵׂעָר לָבָן בִּמְקוֹמוֹ וְטִהֵר וְאַחַר כָּךְ חָזְרָה בַּהֶרֶת אַחֶרֶת בִּמְקוֹם הַבַּהֶרֶת הָרִאשׁוֹנָה וַהֲרֵי הַשֵּׂעָר לָבָן בְּתוֹכָהּ זֶהוּ הַנִּקְרָא שְׂעַר פְּקֻדָּה. אֵינוֹ סִימַן טֻמְאָה שֶׁנֶּאֱמַר (ויקרא יג י) \"וְהִיא הָפְכָה שֵׂעָר לָבָן\" שֶׁהֲפָכַתּוּ הִיא לֹא שֶׁהֲפָכַתּוּ חֲבֵרְתָהּ:","הָיָה בּוֹ בַּהֶרֶת כִּגְרִיס וּבָהּ שְׁתֵּי שְׂעָרוֹת וְהֻחְלַט וְהָלַךְ מִמֶּנָּה כַּחֲצִי גְּרִיס וְטִהֵר וְנִשְׁאֲרוּ שְׁתֵּי הַשְּׂעָרוֹת בַּחֲצִי גְּרִיס הַנִּשְׁאָר וְחָזַר כַּחֲצִי גְּרִיס בִּמְקוֹם זֶה שֶׁהָלַךְ וַהֲרֵי שְׁתֵּי שְׂעָרוֹת לְבָנוֹת בַּבַּהֶרֶת כִּגְרִיס אֵינָן סִימַן טֻמְאָה עַד שֶׁיַּהֲפֹךְ שְׁתֵּי הַשְּׂעָרוֹת בַּהֶרֶת אַחַת:","בַּהֶרֶת כַּחֲצִי גְּרִיס וְאֵין בָּהּ כְּלוּם וְנוֹלְדָה בְּצִדָּהּ בַּהֶרֶת כַּחֲצִי גְּרִיס וּבָהּ שֵׂעָר אַחַת הֲרֵי זוֹ לְהַסְגִּיר. בַּהֶרֶת כַּחֲצִי גְּרִיס וּבָהּ שֵׂעָר אַחַת וְנוֹלְדָה לָהּ בַּהֶרֶת כַּחֲצִי גְּרִיס וּבָהּ שֵׂעָר אַחַת הֲרֵי זוֹ לְהַסְגִּיר. בַּהֶרֶת כַּחֲצִי גְּרִיס וּבָהּ שְׁתֵּי שְׂעָרוֹת וְנוֹלְדָה לָהּ בַּהֶרֶת כַּחֲצִי גְּרִיס וּבָהּ שַׂעֲרָה אַחַת הֲרֵי זוֹ לְהַסְגִּיר. בַּהֶרֶת כַּחֲצִי גְּרִיס וְאֵין בָּהּ כְּלוּם וְנוֹלְדָה לָהּ בַּהֶרֶת כַּחֲצִי גְּרִיס וּבָהּ שְׁתֵּי שְׂעָרוֹת הֲרֵי זוֹ לְהַחְלִיט שֶׁהֲרֵי קָדְמָה בַּהֶרֶת לִשְׁתֵּי הַשְּׂעָרוֹת הַלְּבָנוֹת. סָפֵק שֵׂעָר לָבָן קָדַם סְפֵק הַבַּהֶרֶת קָדְמָה הֲרֵי זוֹ טָמֵא. וְיֵרָאֶה לִי שֶׁטֻּמְאָתוֹ בְּסָפֵק:"],"Mishneh Torah, Defilement by a Corpse 13":["כָּל טֶפַח עַל טֶפַח בְּרוּם טֶפַח קָרוּי אֹהֶל כְּמוֹ שֶׁבֵּאַרְנוּ. וְחוֹצֵץ בִּפְנֵי הַטֻּמְאָה וּמֵבִיא אֶת הַטֻּמְאָה בֵּין שֶׁעֲשָׂאָהוּ לְהַאֲהִיל בֵּין שֶׁנַּעֲשָׂה מֵאֵלָיו אֲפִלּוּ הָיָה שֶׁלֹּא בִּידֵי אָדָם הֲרֵי זֶה מֵבִיא וְחוֹצֵץ. כֵּיצַד. אֶחָד חוֹר שֶׁחָרְרוּהוּ מַיִם אוֹ שְׁרָצִים אוֹ שֶׁאֲכָלַתּוּ מְלַחַת אוֹ שֶׁצָּבַר אֲבָנִים אוֹ קוֹרוֹת וְנַעֲשָׂה בָּהֶן חֲלַל טֶפַח הֲרֵי זֶה אֹהֶל וּמֵבִיא וְחוֹצֵץ:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה הָאֹהֶל חָזָק וּבָרִיא. אֲבָל אֹהֶל רָעוּעַ אֵינוֹ מֵבִיא אֶת הַטֻּמְאָה וְאֵינוֹ חוֹצֵץ בִּפְנֵי הַטֻּמְאָה מִן הַתּוֹרָה. אֲבָל מִדִּבְרֵי סוֹפְרִים מֵבִיא אֶת הַטֻּמְאָה וְאֵינוֹ חוֹצֵץ. כֵּיצַד. שָׂרִיגֵי הָאִילָנוֹת הַסּוֹכְכִים עַל הָאָרֶץ וְהֵן הַנִּקְרָאִים סְכָכוֹת. וַאֲבָנִים הַיּוֹצְאוֹת מִן הַגָּדֵר הַסּוֹכְכוֹת עַל הָאָרֶץ וְהֵן הַנִּקְרָאִין פְּרָעוֹת אִם יְכוֹלִין לְקַבֵּל מַעֲזִיבָה בֵּינוֹנִית וְהֵן עוֹמְדִין הֲרֵי אֵלּוּ מְבִיאִין וְחוֹצְצִין מִן הַתּוֹרָה. וְאִם אֵינָן רְאוּיִין לְקַבֵּל מַעֲזִיבָה בֵּינוֹנִית אֶלָּא הֵן נוֹפְלִים הֲרֵי אֵלּוּ מְבִיאִין מִדִּבְרֵיהֶם וְאֵינָן חוֹצְצִין. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן:","אֵלּוּ מְבִיאִין וְחוֹצְצִין. כְּלִי עֵץ הַבָּא בְּמִדָּה. וְכֵן כְּלֵי אֲבָנִים כְּלֵי גְּלָלִים כְּלֵי אֲדָמָה הַבָּאִין בְּמִדָּה. וּפְשׁוּטֵי כְּלֵי עוֹר וִירִיעָה וְסָדִין וּמַפָּץ וּמַחְצֶלֶת שֶׁהֵן עֲשׂוּיִין אֹהָלִים. וּבְהֵמוֹת אוֹ חַיּוֹת בֵּין טְמֵאוֹת בֵּין טְהוֹרוֹת וְהוּא שֶׁיִּהְיֶה רֹאשׁ זוֹ בֵּין רַגְלֵי זוֹ וְהָיוּ כֻּלָּן דְּבוּקוֹת. וְהָעוֹף שֶׁשָּׁכַן. וְהַחוֹטֵט בַּשִּׁבֳּלִים מָקוֹם לְקָטָן לְהַצִּילוֹ מִן הַשֶּׁמֶשׁ. וָאֳכָלִין שֶׁאֵינָן מֻכְשָׁרִין כְּדֵי שֶׁלֹּא יִטַּמְּאוּ. יְרָקוֹת הַמִּתְקַיְּמִין בִּימוֹת הַחַמָּה וְהַגְּשָׁמִים הֲרֵי הֵן כְּאִילָנוֹת וּמְבִיאִין וְחוֹצְצִין. וְאֵלּוּ הֵן. הָאִרוּס וְהַקִּיסוֹם וִירָקוֹת חֲמוֹר וּדְלַעַת יְוָנִית. וְכֵן הַסְּכָכוֹת וְהַפְּרָעוֹת וְהַזִּיזִין וְהַגְּזוּרוֹת וְהַשּׁוֹבָכוֹת וְהַשְּׁקִיפִין וְהַסְּלָעִים וְהַנְּחִירִים וְהַשְּׁנִינִין. כָּל אֵלּוּ מְבִיאִין וְחוֹצְצִין:","וְאֵלּוּ מְבִיאִין וְלֹא חוֹצְצִין. הָאָדָם. וּכְלֵי עֵץ שֶׁאֵינָן בָּאִין בְּמִדָּה מִפְּנֵי שֶׁהֵן כְּכָל הַכֵּלִים וּמִתְטַמְּאִין. וּפְשׁוּטֵי כְּלֵי עוֹר וִירִיעָה וְסָדִין וּמַפָּץ וּמַחְצֶלֶת שֶׁאֵין עֲשׂוּיִין אֹהָלִים אֶלָּא מְתוּחִין בִּלְבַד וְאֵין לָהֶן שִׁפּוּעַ וְאֵין שָׁם כְּתָלִים. וּבְהֵמָה וְחַיָּה שֶׁמֵּתוּ. וָאֳכָלִין טְמֵאִין אוֹ מֻכְשָׁרִין. שֶׁדָּבָר טָמֵא אֵינוֹ חוֹצֵץ. וְרֵחַיִם שֶׁל יָד שֶׁהֲרֵי הִיא בִּכְלַל כְּלֵי אֲבָנִים. כָּל אֵלּוּ מְבִיאִין וְאֵינָן חוֹצְצִין:","וְאֵלּוּ לֹא מְבִיאִין וְלֹא חוֹצְצִין. הַזְּרָעִים וְהַיְרָקוֹת הַמְחֻבָּרִין לַקַּרְקַע. חוּץ מִן הָאַרְבַּע יְרָקוֹת שֶׁמָּנִינוּ. וְכִפַּת הַבָּרָד וְהַשֶּׁלֶג וְהַכְּפוֹר וְהַגְּלִיד וְהַמֶּלַח. וְהַדּוֹלֵג מִמָּקוֹם לְמָקוֹם. וְהַקּוֹפֵץ מִמָּקוֹם לְמָקוֹם. וְהָעוֹף הַפּוֹרֵחַ. וְטַלִּית הַמְנַפְנֶפֶת. וּסְפִינָה שֶׁהִיא שָׁטָה עַל פְּנֵי הַמַּיִם. כָּל אֵלּוּ לֹא מְבִיאִין וְלֹא חוֹצְצִין שֶׁאַף עַל פִּי שֶׁהֶאֱהִילוּ אֵינוֹ אֹהֶל הַמִּתְקַיֵּם:","קָשַׁר אֶת הַסְּפִינָה בְּדָבָר שֶׁהוּא יָכוֹל לְהַעֲמִידָהּ. כָּבַשׁ כְּנַף הַטַּלִּית בְּאֶבֶן הֲרֵי זוֹ מְבִיאָה אֶת הַטֻּמְאָה:","נֶסֶר שֶׁהוּא צָף עַל פְּנֵי הַמַּיִם וְטֻמְאָה תַּחַת צִדּוֹ הָאֶחָד. הֲרֵי הַכֵּלִים שֶׁתַּחַת צִדּוֹ הַשֵּׁנִי טְהוֹרִים. שֶׁהֲרֵי כְּבָר בֵּאַרְנוּ שֶׁהַסְּפִינָה הַשָּׁטָה אֵינָהּ מְבִיאָה הַטֻּמְאָה:","אֵלּוּ חוֹצְצִין וְלֹא מְבִיאִין. מַסֶּכֶת פְּרוּסָה. וַחֲבִילֵי מִטָּה. וְהַמִּשְׁפָּלוֹת. וְהַסְּרִיגוֹת שֶׁבַּחַלּוֹנוֹת. כֵּיצַד הֵן חוֹצְצִין. שֶׁאִם הָיָה חַלּוֹן בֵּין שְׁנֵי בָּתִּים וְהַטֻּמְאָה בְּבַיִת אֶחָד וְהָיָה אֶחָד מֵאֵלּוּ מָתוּחַ בְּחַלּוֹן זֶה וּסְתָמוֹ אַף עַל פִּי שֶׁיֵּשׁ בֵּינֵיהֶן אֲוִיר הֲרֵי אֵלּוּ חוֹצְצִין וְלֹא תִּכָּנֵס טֻמְאָה לְבַיִת שֵׁנִי. וְהוּא שֶׁלֹּא יִהְיֶה שָׁם בִּסְרִיגוֹת אֵלּוּ אוֹ בְּעֵינֵי הַמִּשְׁפָּלוֹת אוֹ בֵּין חֶבֶל לְחֶבֶל פּוֹתֵחַ טֶפַח שֶׁאִם הָיָה שָׁם פּוֹתֵחַ טֶפַח תִּכָּנֵס בּוֹ הַטֻּמְאָה כְּמוֹ שֶׁיִּתְבָּאֵר:"],"Mishneh Torah, Defilement by a Corpse 24":["בַּיִת שֶׁחִלְּקוֹ בְּקַנְקַנִּים טְהוֹרוֹת מִן הָאָרֶץ וְעַד הַקּוֹרָה וְטֻמְאָה בְּחֶצְיוֹ הָאֶחָד אִם הָיָה פִּי הַקַּנְקַנִּים כְּלַפֵּי הַטְּהוֹרָה הֲרֵי אֵלּוּ מַצִּילוֹת. וְאִם הָיוּ כְּלַפֵּי הַטֻּמְאָה אֵינָם מַצִּילוֹת. טַחָן בְּטִיט בֵּין מִבִּפְנִים בֵּין מִבַּחוּץ רוֹאִין אִם יָכוֹל הַטִּיט לַעֲמֹד בִּפְנֵי עַצְמוֹ מַצִּיל וְאִם לָאו אֵינוֹ מַצִּיל וַהֲרֵי הַכּל אֹהֶל אֶחָד:","בַּיִת שֶׁחִלְּקוֹ בִּנְסָרִים אוֹ בִּירִיעוֹת אִם חִלְּקוֹ מִן הַצְּדָדִין אוֹ מִכְּלַפֵּי הַקּוֹרוֹת וְהָיְתָה הַטֻּמְאָה בַּבַּיִת. כֵּלִים שֶׁבֵּין הַמְּחִצָּה וּבֵין הַכֹּתֶל אוֹ שֶׁבֵּין הַמְּחִצָּה וְהַקּוֹרוֹת טְהוֹרִין. הָיְתָה הַטֻּמְאָה בֵּין מְחִצָּה לַכֹּתֶל אוֹ בֵּין מְחִצָּה לַקּוֹרוֹת כֵּלִים שֶׁבַּבַּיִת טְמֵאִין. שֶׁאֵין הַמְּחִצָּה מוֹנַעַת הַטֻּמְאָה שֶׁלֹּא תֵּצֵא וּתְטַמֵּא כְּמוֹ שֶׁבֵּאַרְנוּ בְּאֹהֶל שֶׁבְּתוֹךְ הַבַּיִת. הָיוּ הַכֵּלִים בְּתוֹךְ עֳבִי הַמְּחִצָּה עַצְמָהּ בֵּין שֶׁהָיְתָה הַטֻּמְאָה לְפָנִים מִן הַמְּחִצָּה אוֹ שֶׁהָיְתָה בְּתוֹךְ הַבַּיִת אִם הָיָה מְקוֹם הַכֵּלִים טֶפַח עַל טֶפַח טְמֵאִים וְאִם לָאו טְהוֹרִין. וּכְבָר בֵּאַרְנוּ כֵּיצַד דִּין הַבַּיִת אִם חִלְּקוֹ מִכְּלַפֵּי אַרְצוֹ:","בַּיִת שֶׁהוּא מָלֵא תֶּבֶן וְאֵין בֵּינוֹ לְבֵין הַקּוֹרוֹת פּוֹתֵחַ טֶפַח. טֻמְאָה בִּפְנִים בֵּין בְּתוֹךְ הַתֶּבֶן בֵּין שֶׁהָיְתָה בֵּין תֶּבֶן לְקוֹרוֹת כָּל הַכֵּלִים שֶׁכְּנֶגֶד יְצִיאַת הַטֻּמְאָה בִּמְלוֹאוֹ שֶׁל פֶּתַח טְמֵאִים. הָיְתָה טֻמְאָה חוּץ לַתֶּבֶן בְּמִלּוּאוֹ שֶׁל פֶּתַח כֵּלִים שֶׁבִּפְנִים אִם יֵשׁ בִּמְקוֹמָן טֶפַח עַל טֶפַח עַל רוּם טֶפַח טְהוֹרִין וְאִם לָאו טְמֵאִין. וְאִם יֵשׁ בֵּין תֶּבֶן לַקּוֹרוֹת פּוֹתֵחַ טֶפַח בֵּין כָּךְ וּבֵין כָּךְ טְמֵאִין שֶׁאֵין הַתֶּבֶן חוֹצֵץ מִפְּנֵי שֶׁסְּתָם תֶּבֶן דַּעְתּוֹ לְפַנּוֹתוֹ:","כֹּתֶל שֶׁבֵּין שְׁנֵי בָּתִּים וְטֻמְאָה בְּתוֹךְ הַכֹּתֶל. בַּיִת הַקָּרוֹב לַטֻּמְאָה טָמֵא וְהַקָּרוֹב לַטָּהֳרָה טָהוֹר. הָיְתָה מֶחֱצָה לְמֶחֱצָה שְׁנֵיהֶן טְמֵאִין. הָיְתָה הַטֻּמְאָה בְּאֶחָד מִשְּׁנֵי הַבָּתִּים וְהַכֵּלִים בְּתוֹךְ הַכֹּתֶל מֵחֶצְיוֹ וּכְלַפֵּי טֻמְאָה טְמֵאִים מֵחֶצְיוֹ וּכְלַפֵּי טָהֳרָה טְהוֹרִין מֶחֱצָה לְמֶחֱצָה טְמֵאִין. וְכֵן מַעֲזִיבָה שֶׁבֵּין הַבַּיִת וְהָעֲלִיָּה וְהַטֻּמְאָה בְּתוֹךְ מַעֲזִיבָה. מֵחֶצְיוֹ וּלְמַטָּה הַבַּיִת טָמֵא וְהָעֲלִיָּה טְהוֹרָה מֵחֶצְיָהּ וּלְמַעְלָה הָעֲלִיָּה טְמֵאָה וְהַבַּיִת טָהוֹר מֶחֱצָה לְמֶחֱצָה שְׁנֵיהֶן טְמֵאִין. הָיְתָה טֻמְאָה בְּאֶחָד מֵהֶן וְכֵלִים בְּתוֹךְ הַמַּעֲזִיבָה מֵחֶצְיָהּ וּכְלַפֵּי טֻמְאָה טְמֵאִין מֵחֶצְיָהּ וּכְלַפֵּי טָהֳרָה טְהוֹרִין מֶחֱצָה לְמֶחֱצָה שְׁנֵיהֶן טְמֵאִין. הָיְתָה הַמַּעֲזִיבָה לַאֲוִיר וְטֻמְאָה בְּתוֹכָהּ מֵחֶצְיָהּ וּלְמַטָּה הַבַּיִת טָמֵא וְהָעוֹמֵד מִלְּמַעְלָה אֲפִלּוּ כְּנֶגֶד הַטֻּמְאָה טָהוֹר שֶׁהֲרֵי פָּשְׁטָה הַטֻּמְאָה בְּכָל הַבַּיִת. הָיְתָה הַטֻּמְאָה מֵחֶצְיָהּ וּלְמַעְלָה הַבַּיִת טָהוֹר וְהָעוֹמֵד מִלְּמַעְלָה כְּנֶגֶד הַטֻּמְאָה טָמֵא. מֶחֱצָה לְמֶחֱצָה הַבַּיִת טָמֵא וְהָעוֹמֵד מִלְּמַעְלָה כְּנֶגֶד הַטֻּמְאָה טָמֵא שֶׁהֲרֵי אִי אֶפְשָׁר לְצַמְצֵם:","וְכֵן כֹּתֶל הַמְשַׁמֵּשׁ אֶת הַבַּיִת יִדּוֹן מֶחֱצָה לְמֶחֱצָה. כֵּיצַד. כֹּתֶל שֶׁהוּא לַאֲוִיר וְגַג הַבַּיִת סָמוּךְ לַכֹּתֶל וְאֵינוֹ מֻרְכָּב עַל הַכֹּתֶל וְטֻמְאָה רְצוּצָה בְּתוֹךְ הַכֹּתֶל הָיְתָה מֵחֶצְיוֹ וּלְפָנִים הַבַּיִת טָמֵא וְהָעוֹמֵד מִלְּמַעְלָה עַל רֹאשׁ הַכֹּתֶל טָהוֹר כְּעוֹמֵד עַל גַּג הַבַּיִת. הָיְתָה מֵחֶצְיוֹ וְלַחוּץ הַבַּיִת טָהוֹר וְהָעוֹמֵד מִלְּמַעְלָה כְּנֶגֶד הַטֻּמְאָה טָמֵא שֶׁהֲרֵי לֹא פָּשְׁטָה הַטֻּמְאָה בְּתוֹךְ הַבַּיִת. הָיְתָה הַטֻּמְאָה מֶחֱצָה לְמֶחֱצָה הַבַּיִת טָמֵא וְהָעוֹמֵד מִלְּמַעְלָה טָהוֹר שֶׁהֲרֵי פָּשְׁטָה הַטֻּמְאָה בַּבַּיִת. נָטַל מֵהַכֹּתֶל מִבִּפְנִים אוֹ שֶׁהוֹסִיף בַּכֹּתֶל מִבַּחוּץ עַד שֶׁנִּמְצֵאת הַטֻּמְאָה מֵחֲצִי כֹּתֶל וּלְפָנִים הַבַּיִת טָמֵא. נָטַל מִבַּחוּץ אוֹ שֶׁהוֹסִיף בָּעֳבִי הַכֹּתֶל מִבִּפְנִים עַד שֶׁנִּמְצֵאת הַטֻּמְאָה מֵחֲצִי כֹּתֶל וְלַחוּץ הַבַּיִת טָהוֹר. הָיְתָה הַטֻּמְאָה נְתוּנָה עַל גַּבֵּי הַכֹּתֶל אֲפִלּוּ מֵחֶצְיוֹ וּלְפָנִים הַבַּיִת טָהוֹר:","בַּיִת הַמְשַׁמֵּשׁ אֶת הַכֹּתֶל יִדּוֹן כִּקְלִפַּת הַשּׁוּם. כֵּיצַד. הַחוֹפֵר שְׁנֵי כּוּכִים אוֹ שְׁתֵּי מְעָרוֹת זוֹ בְּצַד זוֹ עַד שֶׁנִּמְצְאוּ שְׁנֵי בָּתִּים חֲפוּרִים בַּקַּרְקַע וְנַעֲשָׂה בֵּינֵיהֶן כֹּתֶל הַמַּבְדִּיל בֵּין שְׁנֵיהֶן וְהָיְתָה טֻמְאָה בַּבָּתִּים וְכֵלִים בַּכֹּתֶל אִם יֵשׁ עֲלֵיהֶן כִּקְלִפַּת הַשּׁוּם טְהוֹרִין. הָיְתָה טֻמְאָה בְּכֹתֶל זֶה וְכֵלִים בַּבָּתִּים אִם יֵשׁ עֲלֵיהֶן כִּקְלִפַּת הַשּׁוּם טְהוֹרִים. הִנֵּה לָמַדְתָּ שֶׁכֹּתֶל בִּנְיָן נִדּוֹן מֶחֱצָה לְמֶחֱצָה וְכֹתֶל הַסֶּלַע אוֹ שֶׁנַּעֲשָׂה מִגּוּשׁ הָאָרֶץ כְּשֶׁיַּחְפֹּר מִכָּאן וּמִכָּאן נִדּוֹן כִּקְלִפַּת הַשּׁוּם:","כֹּתֶל שֶׁחֲצִי עָבְיוֹ בִּנְיָן וְחֶצְיוֹ סֶלַע נִדּוֹן מֶחֱצָה לְמֶחֱצָה:","טֻמְאָה שֶׁהָיְתָה בֵּין קוֹרוֹת הַבַּיִת אֲפִלּוּ אֵין תַּחְתֶּיהָ אֶלָּא כִּקְלִפַּת הַשּׁוּם הַבַּיִת טָהוֹר וְרוֹאִין אֶת הַטֻּמְאָה כְּאִלּוּ הִיא רְצוּצָה בָּאָרֶץ וּמְטַמְּאָה כְּנֶגְדָּהּ בִּלְבַד. וְאִם יֵשׁ בִּמְקוֹמָהּ טֶפַח עַל טֶפַח הַכּל טָמֵא. וְכֵן אִם הָיְתָה נִרְאֵית בְּתוֹךְ הַבַּיִת בֵּין כָּךְ וּבֵין כָּךְ הַבַּיִת טָמֵא. שְׁנֵי פְּתָחִים זֶה עַל גַּבֵּי זֶה וְטֻמְאָה בַּכֹּתֶל שֶׁבֵּינֵיהֶן אִם נִרְאֵית שֶׁהִיא לְתוֹךְ אַחַת מֵהֶן הוּא טָמֵא וַחֲבֵרוֹ טָהוֹר וְאִם לָאו נִדּוֹנִין מֶחֱצָה לְמֶחֱצָה:"],"Mishneh Torah, Defilement of Foods 12":["כָּל דִּבְרֵי הֶכְשֵׁר אֳכָלִין דִּבְרֵי קַבָּלָה הֵן מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה שֶׁנֶּאֱמַר (ויקרא יא לח) \"וְכִי יֻתַּן מַיִם עַל זֶרַע\" אֶחָד הַמַּיִם וְאֶחָד שְׁאָר שִׁבְעָה מַשְׁקִין. וְהוּא שֶׁיִּנָּתֵן עֲלֵיהֶם בִּרְצוֹן בְּעָלִים וְאַחַר שֶׁנֶּעֶקְרוּ מִן הַקַּרְקַע. שֶׁדָּבָר יָדוּעַ הוּא שֶׁאֵין לְךָ זֶרַע שֶׁלֹּא בָּא עָלָיו מַיִם כְּשֶׁהוּא מְחֻבָּר. לֹא נֶאֱמַר וְכִי יֻתַּן מַיִם אֶלָּא לְאַחַר שֶׁנֶּעֶקְרוּ הָאֳכָלִין וְנִתְלְשׁוּ הַמַּשְׁקִין:","כָּל מַשְׁקֶה שֶׁנָּפַל עַל הָאֹכֶל בַּתְּחִלָּה בִּרְצוֹן בְּעָלִים אַף עַל פִּי שֶׁאֵין סוֹפוֹ בְּרָצוֹן אוֹ שֶׁהָיָה סוֹפוֹ בְּרָצוֹן וְאֵין תְּחִלָּתוֹ בְּרָצוֹן הִכְשִׁיר. נָפַל שֶׁלֹּא בִּרְצוֹנוֹ אֵינוֹ מַכְשִׁיר אֲפִלּוּ בָּלַל הוּא פֵּרוֹתָיו מִפְּנֵי הַסַּכָּנָה אוֹ מִפְּנֵי הַצֹּרֶךְ וְהוּא אֵין רְצוֹנוֹ שֶׁיִּהְיוּ בְּלוּלִין הֲרֵי אֵלּוּ לֹא הֻכְשְׁרוּ. כֵּיצַד. הַטּוֹמֵן פֵּרוֹתָיו בְּמַיִם מִפְּנֵי הַגַּנָּבִים אוֹ הַנּוֹתֵן פֵּרוֹתָיו לְשִׁבּלֶת הַנָּהָר לַהֲבִיאָן עִמּוֹ אֵינָן מֻכְשָׁרִים:","מַשְׁקִין שֶׁנִּתְלְשׁוּ מִן הַקַּרְקַע שֶׁלֹּא בְּרָצוֹן אֵינָן מַכְשִׁירִין. לְפִיכָךְ אָדָם אוֹ כֵּלִים אוֹ פֵּרוֹת שֶׁנִּבְלְלוּ בְּמַשְׁקִין שֶׁנִּתְלְשׁוּ שֶׁלֹּא בְּרָצוֹן אַף עַל פִּי שֶׁנָּגְעוּ אֳכָלִין בְּאוֹתָן מַשְׁקִין בְּרָצוֹן לֹא הֻכְשְׁרוּ שֶׁהֲרֵי אוֹתָן הַמַּיִם שֶׁלֹּא לְרָצוֹן נִתְלְשׁוּ וּכְאִלּוּ הֵן עֲדַיִן בַּקַּרְקַע שֶׁאֵינָן מַכְשִׁירִין. הָיוּ הַמַּיִם שֶׁעַל הָאָדָם וְעַל הַכֵּלִים וְעַל הַפֵּרוֹת תְּלוּשִׁין בְּרָצוֹן וְנָגְעוּ בָּהֶן אֳכָלִין בְּרָצוֹן הֻכְשְׁרוּ. כֵּיצַד. הַכּוֹפֶה קְעָרָה עַל הַכֹּתֶל בִּשְׁבִיל שֶׁתּוּדַח הַמַּיִם שֶׁבָּהּ מַכְשִׁירִין. וְאִם הִנִּיחַ בָּהֶן פֵּרוֹת הֻכְשְׁרוּ מִפְּנֵי שֶׁהֵן תְּלוּשִׁין בַּכְּלִי לְדַעַת. כְּפָאָהּ בִּשְׁבִיל שֶׁלֹּא יִלְקֶה הַכֹּתֶל הַמַּיִם שֶׁבָּהּ אֵינָן כִּתְלוּשִׁין וּלְפִיכָךְ אִם נָתַן בָּהּ אֳכָלִין לֹא הֻכְשְׁרוּ. נִתְכַּוֵּן שֶׁיּוּדַח הַכֹּתֶל אִם הָיָה כֹּתֶל בַּיִת הֲרֵי אֵלּוּ מַכְשִׁירִין שֶׁהַתָּלוּשׁ שֶׁחִבְּרוֹ לְעִנְיַן הֶכְשֵׁר הֲרֵי הוּא כְּתָלוּשׁ וְנִמְצְאוּ מַיִם שֶׁעַל כֹּתֶל בַּיִת זֶה כַּמַּיִם שֶׁבַּכֵּלִים. וְאִם הָיָה כֹּתֶל מְעָרָה שֶׁאֵינוֹ בִּנְיָן אֶלָּא עַצְמָהּ שֶׁל קַרְקַע הַמַּיִם שֶׁעָלֶיהָ אֵינָן כִּתְלוּשִׁין מִן הַקַּרְקַע:","הַשּׁוֹחֶה לִשְׁתּוֹת הֲרֵי הַמַּיִם הָעוֹלִים בִּשְׂפָמוֹ וּבְפִיו תְּלוּשִׁין בִּרְצוֹנוֹ. שֶׁדָּבָר יָדוּעַ הוּא שֶׁהַשּׁוֹתֶה יַעֲלֶה הַמַּיִם בְּפִיו וּבִשְׂפָתָיו וְהוֹאִיל וְשָׁתָה בִּרְצוֹנוֹ הֲרֵי אֵלּוּ נִתְלְשׁוּ בְּרָצוֹן. אֲבָל הַמַּיִם הָעוֹלִים בְּחָטְמוֹ וּבִזְקָנוֹ וּבְרֹאשׁוֹ אֵינָן תְּלוּשִׁין בְּרָצוֹן:","הַמְמַלֵּא אֶת הֶחָבִית הַמַּיִם הָעוֹלִים אַחֲרֶיהָ וּבַחֶבֶל שֶׁהוּא מְכוֹנֵן עַל צַוָּארָהּ וּבַחֶבֶל שֶׁהוּא לְצָרְכָּהּ הֲרֵי הֵן תְּלוּשִׁין בְּרָצוֹן. וְהַמַּיִם שֶׁבַּחֶבֶל הַיָּתֵר עַל צָרְכָּהּ אֵינָן תְּלוּשִׁין בְּרָצוֹן. נְתָנָהּ תַּחַת הַצִּנּוֹר כָּל הַמַּיִם שֶׁעַל גַּבָּהּ וּבַחֶבֶל אֵינָן תְּלוּשִׁין בְּרָצוֹן לְפִיכָךְ אֵין מַכְשִׁירִין:","מִי שֶׁיָּרְדוּ עָלָיו גְּשָׁמִים אֲפִלּוּ הָיָה אַב הַטֻּמְאָה. הַמַּיִם שֶׁעָלָיו אַף עַל פִּי שֶׁיָּרְדוּ מִצַּד הָעֶלְיוֹן לַתַּחְתּוֹן טְהוֹרִין וְהוּא שֶׁיְּנַתְּקֵם מֵעָלָיו בְּכָל כֹּחוֹ. אֲבָל אִם הָיוּ שׁוֹתְתִין וְיוֹרְדִים בִּשְׁעַת פְּרִישָׁתָם מִתְטַמְּאִין. וּבִזְמַן שֶׁהֵן טְהוֹרִין אֵינָן מַכְשִׁירִין שֶׁהֲרֵי אֵינָן תְּלוּשִׁין עָלָיו לִרְצוֹנוֹ. וְאִם נִעֵר הֲרֵי אֵלּוּ לְרָצוֹן. עָמַד תַּחַת הַצִּנּוֹר לְהָקֵר אוֹ לִידוֹחַ הֲרֵי זֶה לְרָצוֹן. וְאִם הָיָה טָמֵא הַמַּיִם שֶׁעָלָיו טְמֵאִין:","חָבִית שֶׁהָיְתָה מְלֵאָה פֵּרוֹת וְיָרַד הַדֶּלֶף לְתוֹכָהּ הֲרֵי זֶה יְעָרֶה הַמַּיִם מֵעֲלֵיהֶן וְאֵינָן מַכְשִׁירִין וְאַף עַל פִּי שֶׁרְצוֹנוֹ שֶׁיִּהְיוּ בְּתוֹכָהּ עַד שֶׁיְּעָרֶה הַמַּיִם מֵעֲלֵיהֶן:","עֲרֵבָה שֶׁיָּרַד הַדֶּלֶף לְתוֹכָהּ הַמַּיִם הַנִּתָּזִין וְהַצָּפִין מֵעָלֶיהָ אֵינָן תְּלוּשִׁין בְּרָצוֹן. נְטָלָהּ לְשָׁפְכָהּ הַמַּיִם שֶׁבְּתוֹכָהּ אֵינָן בְּרָצוֹן. הִנִּיחָהּ שֶׁיֵּרֵד הַדֶּלֶף לְתוֹכָהּ הַנִּתָּזִין וְהַצָּפִין שֶׁבְּתוֹכָהּ אֵינָן תְּלוּשִׁין בְּרָצוֹן. וְאִם נְטָלָהּ לְשָׁפְכָהּ הֲרֵי אֵלּוּ מַכְשִׁירִין שֶׁכֵּיוָן שֶׁלֹּא שְׁפָכָהּ בִּמְקוֹמָהּ הֲרֵי תְּלָשָׁן בִּרְצוֹנוֹ:","הַמַּטְבִּיל אֶת כֵּלָיו וְהַמְכַבֵּס אֶת כְּסוּתוֹ בִּמְעָרָה הַמַּיִם הָעוֹלִין בְּיָדָיו בְּרָצוֹן וּבְרַגְלָיו אֵינָן כִּתְלוּשִׁין בְּרָצוֹן:","פֵּרוֹת שֶׁנָּפְלוּ לְתוֹךְ הַמַּיִם וּפָשַׁט יָדָיו וּנְטָלָן לֹא הֻכְשְׁרוּ. וְאִם חִשֵּׁב שֶׁיּוּדְחוּ יָדָיו הֻכְשְׁרוּ בַּמַּיִם שֶׁבְּיָדָיו שֶׁהַמַּיִם שֶׁבְּיָדָיו וְשֶׁעַל הַפֵּרוֹת הֲרֵי הֵן כִּתְלוּשִׁין בְּרָצוֹן:","הַנּוֹתֵן פֵּרוֹתָיו לְתוֹךְ הַמַּיִם בִּרְצוֹנוֹ אִם הָיוּ מַיִם שֶׁבַּקַּרְקָעוֹת אֵינָן מֻכְשָׁרִין כָּל זְמַן שֶׁהֵן בַּמַּיִם. הוֹצִיאָן הֻכְשְׁרוּ בַּמַּיִם שֶׁעֲלֵיהֶן אוֹ שֶׁעַל יָדָיו שֶׁהֲרֵי נִתְלְשׁוּ בְּרָצוֹן. כֵּיצַד. צְנוֹן אוֹ לֶפֶת שֶׁהוּא בְּתוֹךְ הַמְּעָרָה נִדָּה מְדִיחַתּוּ שָׁם וְהוּא טָהוֹר. הֶעֱלַתְהוּ כָּל שֶׁהוּא מִן הַמַּיִם נִטְמָא בְּמַגָּעָהּ:","קֻפָּה שֶׁהִיא מְלֵאָה תּוּרְמוּסִין וּנְתוּנָה לְתוֹךְ הַמִּקְוֶה מוֹשִׁיט יָדוֹ הַטָּמֵא וְנוֹטֵל תּוּרְמוּסִין מִתּוֹכָהּ וְהֵן טְהוֹרִין מִפְּנֵי שֶׁלֹּא הֻכְשְׁרוּ שֶׁהֲרֵי מִתּוֹכָהּ נָטַל וְאֵין רְצוֹנוֹ בַּמַּיִם שֶׁעֲלֵיהֶן. הֶעֱלָם מִן הַמַּיִם הַנּוֹגְעִין בַּקֻּפָּה טְמֵאִין שֶׁהֲרֵי הֻכְשְׁרוּ בַּמַּיִם שֶׁבַּקֻּפָּה שֶׁנִּתְלְשׁוּ בִּרְצוֹנוֹ. וּשְׁאָר כָּל הַתּוּרְמוּסִין שֶׁבְּתוֹךְ הַקֻּפָּה טְהוֹרִין:"],"Mishneh Torah, Defilement of Foods 9":["הַשֶׁמֶן אוֹ הַדְּבַשׁ שֶׁנִּטְמְאוּ וְאַחַר כָּךְ קָרְשׁוּ וְאַחַר כָּךְ נִמּוֹחוּ הֲרֵי הֵן רִאשׁוֹן לְטֻמְאָה לְעוֹלָם מִפְּנֵי שֶׁהֵן כְּמַשְׁקִין וְאַף עַל פִּי שֶׁקָּפְאוּ אַחַר שֶׁנִּטְמְאוּ:","הָרֹטֶב וְהַגְּרִיסִין וְהֶחָלָב שֶׁקָּרְשׁוּ הֲרֵי הֵן כָּאֳכָלִין וּצְרִיכִין מַחֲשָׁבָה. וְאִם נָגַע בָּהֶן אֹכֶל רִאשׁוֹן אוֹ מַשְׁקֶה נַעֲשׂוּ שְׁנִיִּים. הָיָה בָּהֶן מַשְׁקֶה טוֹפֵחַ הֲרֵי הֵן כְּמַשְׁקִין וְהֵן תְּחִלָּה לְטֻמְאָה. נִטְמְאוּ כְּשֶׁהֵן מַשְׁקִין וְקָפְאוּ אַחַר כֵּן וְקָרְשׁוּ הֲרֵי הֵן שְׁנִיִּים כְּמוֹ אֹכֶל שֶׁנִּטְמָא מִמַּשְׁקִין טְמֵאִין. נִטְמְאוּ כְּשֶׁהֵן קְפוּיִים וְנִמּוֹחוּ וְנַעֲשׂוּ מַשְׁקִין אִם הָיוּ כְּבֵיצָה מְכֻוָּן הֲרֵי הַמַּשְׁקִין טְהוֹרִין. הָיוּ יוֹתֵר מִכְּבֵיצָה הַמַּשְׁקִין טְמֵאִין שֶׁכְּשֶׁנִּמּוֹחָה טִפָּה רִאשׁוֹנָה נִטְמֵאת בִּכְבֵיצָה אֹכֶל טָמֵא שֶׁנִּמּוֹחָה מִמֶּנּוּ וְאוֹתָהּ הַטִּפָּה תְּטַמֵּא כָּל הַמַּשְׁקִין שֶׁנִּמּוֹחוּ אַחֲרֶיהָ. וְכֵן טְמֵא מֵת שֶׁסָּחַט זֵיתִים וַעֲנָבִים שֶׁהֻכְשְׁרוּ אִם הָיוּ כְּבֵיצָה הֲרֵי הַמַּשְׁקִין הַיּוֹצְאִין מֵהֶן טְהוֹרִין. וּבִלְבַד שֶׁלֹּא יִגַּע בִּמְקוֹם הַמַּשְׁקֶה שֶׁהַמַּשְׁקֶה כְּמֻפְקָד בָּאֹכֶל וּכְאִלּוּ הִיא גּוּף אַחֵר. הָיוּ אוֹתָן זֵיתִים וַעֲנָבִים יֶתֶר מִכְּבֵיצָה הֲרֵי הַמַּשְׁקִין הַיּוֹצְאִין מֵהֶן טְמֵאִין שֶׁכֵּיוָן שֶׁיָּצָאת טִפָּה רִאשׁוֹנָה נִטְמֵאת בִּכְבֵיצָה וְטִמְּאָה כָּל הַמַּשְׁקִין. וְאִם הָיָה הַסּוֹחֵט זָב וְזָבָה וְכַיּוֹצֵא בָּהֶן אֲפִלּוּ סָחַט גַּרְגֵּר אֶחָד יְחִידִי שֶׁלֹּא הֻכְשַׁר וְלֹא נָגַע בַּמַּשְׁקֶה הַמַּשְׁקֶה טָמֵא שֶׁכֵּיוָן שֶׁיָּצָאת טִפָּה רִאשׁוֹנָה נִטְמֵאת בְּמַשָּׂא הַזָּב שֶׁהַזָּב שֶׁנָּשָׂא אֳכָלִין אוֹ מַשְׁקִין טְמֵאִין כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן זָב שֶׁחָלַב אֶת הָעֵז הֶחָלָב טָמֵא שֶׁכֵּיוָן שֶׁיָּצָאת טִפָּה הָרִאשׁוֹנָה נִטְמֵאת בְּמַשָּׂא הַזָּב:","קְדֵרָה שֶׁמְּלֵאָה כְּבָשִׁין שֶׁל חֻלִּין וְיָצְאוּ עֲלֵיהֶם חוּץ לַקְּדֵרָה וְנָגַע אַב הַטֻּמְאָה אוֹ רִאשׁוֹן בֶּעָלֶה שֶׁחוּץ לַקְּדֵרָה בִּמְקוֹם הַנָּגוּב אַף עַל פִּי שֶׁיֵּשׁ בֶּעָלֶה כְּבֵיצָה הוּא טָמֵא וְהַכּל טָהוֹר. חָזַר לַקְּדֵרָה טִמֵּא אֶת הַמַּשְׁקִין שֶׁבָּהּ וְנִטְמֵאת הַקְּדֵרָה וְכָל הַכְּבָשִׁין. נָגַע בֶּעָלֶה שֶׁחוּץ לַקְּדֵרָה וְהָיָה בּוֹ מַשְׁקֶה אִם יֵשׁ בֶּעָלֶה כְּבֵיצָה הַכּל טָמֵא שֶׁהֶעָלֶה מְטַמֵּא מַשְׁקֶה שֶׁעָלָיו וְהַמַּשְׁקֶה מְטַמֵּא כָּל הַמַּשְׁקִין שֶׁבַּקְּדֵרָה וּמְטַמֵּא אֶת הַקְּדֵרָה. הָיְתָה הַקְּדֵרָה מְלֵאָה כְּבָשִׁים שֶׁל תְּרוּמָה וְנִעֵר אוֹתָהּ טְבוּל יוֹם וְרָאָה מַשְׁקִין עַל יָדוֹ סָפֵק מִן הַקְּדֵרָה נִתְּזוּ סָפֵק שֶׁהַקֶּלַח נָגַע בְּיָדוֹ הַיָּרָק פָּסוּל וְהַקְּדֵרָה טְהוֹרָה:","טָמֵא שֶׁהָיָה אוֹכֵל עֲנָבִים מֻכְשָׁרִים וְנָפַל מִמֶּנּוּ גַּרְגֵּר יְחִידִי לַגַּת אִם הָיָה שָׁלֵם וְלֹא נִשְׁמַט מִמֶּנּוּ עֵקְצוֹ הַגַּת טָהוֹר. וְאִם נִטַּל עֵקְצוֹ וְהָיוּ עֲנָבִים מוּכָנִים בַּעֲבִיט וְכַיּוֹצֵא בּוֹ לְדָרְכָן שֶׁהֲרֵי רוֹצֶה בַּמַּשְׁקֶה הַיּוֹצֵא מֵהֶן נִטְמָא הַגַּת בְּטִפַּת מַשְׁקֶה שֶׁבְּרֹאשׁ הַגַּרְגֵּר בִּמְקוֹם הָעֹקֶץ. נָפְלוּ מִמֶּנּוּ עֲנָבִים וּדְרָכָן בְּמָקוֹם מוּפְנֶה אִם הָיוּ כְּבֵיצָה מְכֻוָּן הֲרֵי הַמַּשְׁקִין הַיּוֹצְאִין מֵהֶן טְהוֹרִין כְּמוֹ שֶׁבֵּאַרְנוּ. הָיוּ יֶתֶר מִכְּבֵיצָה הַיּוֹצֵא מֵהֶן טָמֵא שֶׁכֵּיוָן שֶׁיָּצָאת טִפָּה רִאשׁוֹנָה נִטְמֵאת בִּכְבֵיצָה וּמְטַמֵּאת אֶת כָּל הַמַּשְׁקֶה הַיּוֹצֵא אַחֲרֶיהָ:","גּוּשׁ שֶׁל זֵיתִים טְמֵאִין שֶׁהָיָה מְקֻבָּץ וּמְחֻבָּר וְהִשְׁלִיכוֹ לְתוֹךְ תַּנּוּר וְהֻסַּק אִם הָיָה כְּבֵיצָה מְכֻוָּן הַתַּנּוּר טָהוֹר שֶׁאֵין הָאֳכָלִין מְטַמְּאִין כֵּלִים וְהַמַּשְׁקֶה הַיּוֹצֵא מֵהֶן טָהוֹר כְּמוֹ שֶׁבֵּאַרְנוּ. הָיָה הַגּוּשׁ יֶתֶר מִכְּבֵיצָה נִטְמָא הַתַּנּוּר שֶׁכְּשֶׁיָּצְאָה טִפָּה אַחַת נִטְמֵאת בִּכְבֵיצָה וְטִמְּאָה אֶת הַתַּנּוּר. לְפִיכָךְ אִם הַזֵּיתִים הַטְּמֵאִין פֵּרוּרִין וְאֵינָן גּוּשׁ אֲפִלּוּ הֵן מֵאָה הַתַּנּוּר טָהוֹר:","עֵצִים שֶׁנִּבְלְעוּ בָּהֶם מַשְׁקִין טְמֵאִין וְהִסִּיקָן הַתַּנּוּר טָהוֹר שֶׁהֲרֵי בָּטְלוּ בָּעֵצִים. וַאֲפִלּוּ הוֹצִיא הָעֵצִים שֶׁנָּפְלוּ עֲלֵיהֶן גְּשָׁמִים וְנָפְלוּ לִרְצוֹנוֹ וְהִסִּיקָן הַתַּנּוּר טָהוֹר וְאֵין הַמַּיִם שֶׁעֲלֵיהֶן מִתְטַמְּאִין מִן הַמַּשְׁקִין הַבְּלוּעִין בָּהֶם. וְלֹא יַסִּיקֵם אֶלָּא בְּיָדַיִם טְהוֹרוֹת גְּזֵרָה שֶׁלֹּא יַסִּיקֵם הַטָּמֵא וְנִמְצְאוּ הַמַּשְׁקִין שֶׁעֲלֵיהֶם מְטַמְּאִין אֶת הַתַּנּוּר:","שֶׁרֶץ שֶׁנִּמְצָא בְּרֵחַיִם שֶׁל זֵיתִים אֵין טָמֵא אֶלָּא מְקוֹם מַגָּעוֹ. אִם הָיָה מַשְׁקֶה מְהַלֵּךְ הַכּל טָמֵא. שֶׁכֵּיוָן שֶׁנִּטְמָא מִקְצָת הַמַּשְׁקֶה נִטְמָא כֻּלּוֹ וְהַשֶּׁמֶן מְטַמֵּא אֶת כָּל הַזֵּיתִים. נִמְצָא עַל גַּבֵּי הֶעָלִין לְמַעְלָה מִן הַזֵּיתִים יִשְׁאֲלוּ מִן הַבַּדָּדִין אִם אָמְרוּ לֹא נָגַעְנוּ נֶאֱמָנִין. נִמְצָא עַל אוֹם שֶׁל זֵיתִים נִטְמָא כָּל הַגּוּשׁ כְּמוֹ שֶׁבֵּאַרְנוּ. נִמְצָא עַל גַּבֵּי זֵיתִים פֵּרוּרִין וְהוּא נוֹגֵעַ בִּכְבֵיצָה הַכּל טָמֵא שֶׁהָאוֹכֵל שֶׁהוּא כְּבֵיצָה מְטַמֵּא הַמַּשְׁקֶה הַמְעֹרָב בָּהֶן וְהַמַּשְׁקֶה מְטַמֵּא שְׁאָר הַזֵּיתִים. הָיוּ פֵּרוּרִין עַל גַּבֵּי פֵּרוּרִין וְהַמַּשְׁקֶה מִלְּמַטָּה אַף עַל פִּי שֶׁנָּגַע בִּכְבֵיצָה אֵין טָמֵא אֶלָּא מְקוֹם מַגָּעוֹ:","עַם הָאָרֶץ שֶׁהוֹשִׁיט יָדָיו לַגַּת וְנָגַע בְּאֶשְׁכּוֹלוֹת אֶשְׁכּוֹל וְכָל סְבִיבוֹתָיו טְמֵאִין וְהַגַּת כֻּלָּהּ טְהוֹרָה מִפְּנֵי שֶׁמַּפְסִיקִין הָאֶשְׁכּוֹלוֹת שֶׁסְּבִיבוֹת זֶה הָאֶשְׁכּוֹל בֵּינוֹ וּבֵין שְׁאָר הַגַּת:","הַגֶּפֶת וְהַזַּגִּים שֶׁנַּעֲשׂוּ בְּטָהֳרָה וְהָלְכוּ עֲלֵיהֶן טְמֵאִין וְאַחַר כָּךְ יָצְאוּ מֵהֶן מַשְׁקִין הֲרֵי אֵלּוּ טְהוֹרִין שֶׁמִּתְחִלָּה נַעֲשׂוּ בְּטָהֳרָה. וְאִם נַעֲשׂוּ מִתְּחִלָּה בְּטֻמְאָה וְיָצְאוּ מֵהֶן מַשְׁקִין טְמֵאִין:","הַבַּדָּדִין שֶׁנִּכְנָסִין וְיוֹצְאִין וּמַשְׁקִין טְמֵאִין בְּתוֹךְ בֵּית הַבַּד אִם יֵשׁ בֵּין מַשְׁקִין לַזֵּיתִים כְּדֵי שֶׁיְּנַגְּבוּ אֶת רַגְלֵיהֶן בָּאָרֶץ הֲרֵי הַזֵּיתִים טְהוֹרִין שֶׁהַנּוֹגֵעַ בְּמַשְׁקִין טְמֵאִים שֶׁלֹּא בְּיָדָיו טָהוֹר וַאֲפִלּוּ לְקֹדֶשׁ. כִּכְּרוֹת הֶקְדֵּשׁ שֶׁהָיוּ בָּהֶן גּוּמוֹת וּבְתוֹךְ הַגּוּמוֹת הָיוּ מַשְׁקִין שֶׁל קֹדֶשׁ וְנָגַע הַשֶּׁרֶץ בְּאַחַת מֵהֶן וְנָגְעָה רִאשׁוֹנָה בַּשְּׁנִיָּה וּשְׁנִיָּה בַּשְּׁלִישִׁית אֲפִלּוּ מֵאָה כֻּלָּן רִאשׁוֹן לְטֻמְאָה. מִפְּנֵי הַמַּשְׁקֶה שֶׁבַּגֻּמּוֹת וְחִבַּת הַקֹּדֶשׁ הֲרֵי הֵן כֻּלָּן כְּמַשְׁקִין שֶׁאֵין מוֹנִין בָּהֶן. אֲבָל אִם הָיוּ כִּכְּרוֹת תְּרוּמָה הֲרֵי הַכִּכָּר הַשְּׁלִישִׁית בִּלְבַד פְּסוּלָה וּמִשְּׁלִישִׁית וָהָלְאָה טָהוֹר. וְאִם הָיָה מַשְׁקֶה טוֹפֵחַ עַל כָּל הַכִּכָּרוֹת אַף בִּתְרוּמָה הַכּל טְמֵאוֹת וְכֻלָּן שְׁנִיּוֹת חוּץ מִן הָרִאשׁוֹנָה שֶׁנָּגַע בָּהּ הַשֶּׁרֶץ שֶׁהִיא רִאשׁוֹן:","אֲבַעְבּוּעַ הַנַּעֲשֶׂה בָּעֳבִי הֶחָבִית וַהֲרֵי הוּא כְּמוֹ כְּלִי אַחֵר בְּצִדָּהּ אִם נִקַּב הָאֲבַעְבּוּעַ לַאֲוִיר הֶחָבִית וְנִקַּב נֶקֶב אַחֵר לַחוּץ זֶה כְּנֶגֶד זֶה. אוֹ שֶׁהָיָה הַנֶּקֶב הַפְּנִימִי מִלְּמַטָּה וְהַחִיצוֹן מִלְּמַעְלָה וְהָיָה הָאֲבַעְבּוּעַ וְהֶחָבִית מְלֵאִים מַשְׁקִין. אִם נָגַע אַב הַטֻּמְאָה בַּמַּשְׁקֶה שֶׁבָּאֲבַעְבּוּעוֹת נִטְמְאוּ כָּל הַמַּשְׁקִין שֶׁבֶּחָבִית. הָיְתָה הֶחָבִית מֻקֶּפֶת צָמִיד פָּתִיל וּנְתוּנָה בְּאֹהֶל הַמֵּת נִטְמֵאת מִפְּנֵי הַנֶּקֶב שֶׁבָּאֲבַעְבּוּעַ זֶה שֶׁהֲרֵי הוּא מְפֻלָּשׁ לַאֲוִירָהּ. וְכֵן אִם הָיָה הַנֶּקֶב שֶׁבָּאֲבַעְבּוּעַ שֶׁבִּפְנִים מִלְּמַעְלָה וְהַחִיצוֹן מִלְּמַטָּה הֲרֵי זוֹ אֵינָהּ נִצֶּלֶת בְּצָמִיד פָּתִיל. אֲבָל אִם נָגַע אַב הַטֻּמְאָה בָּאֲבַעְבּוּעַ לֹא נִטְמְאוּ מַשְׁקִין שֶׁבֶּחָבִית וְהִנָּם כְּמֻבְדָּלִין מֵהֶן:"],"Mishneh Torah, Divorce 10":["כָּל מָקוֹם שֶׁאָמַרְנוּ בְּחִבּוּר זֶה שֶׁהַגֵּט בָּטֵל אוֹ אֵינוֹ גֵּט אוֹ אֵינָהּ מְגֹרֶשֶׁת הֲרֵי זֶה גֵּט בָּטֵל מִן הַתּוֹרָה וַעֲדַיִן הִיא אֵשֶׁת אִישׁ גְּמוּרָה. וְאִם נִשֵּׂאת תֵּצֵא וְהַוָּלָד מַמְזֵר. וְאִם הָיָה בַּעְלָהּ כֹּהֵן לֹא נֶאֶסְרָה עָלָיו מִשּׁוּם גְּרוּשָׁה. חוּץ מִן הַמְגָרֵשׁ אֶת אִשְׁתּוֹ וְאָמַר לָהּ הֲרֵי אַתְּ מְגֹרֶשֶׁת מִמֶּנִּי וְאֵין אַתְּ מֻתֶּרֶת לַכּל שֶׁאַף עַל פִּי שֶׁאֵין זֶה גֵּט הֲרֵי זוֹ פְּסוּלָה לִכְהֻנָּה מִדִּבְרֵיהֶן שֶׁנֶּאֱמַר (ויקרא כא ז) ״‎וְאִשָּׁה גְּרוּשָׁה מֵאִישָׁהּ״‎ אָמְרוּ חֲכָמִים אֲפִלּוּ לֹא נִתְגָּרְשָׁה אֶלָּא מֵאִישָׁהּ וְלֹא הֻתְּרָה לַכּל נֶאֶסְרָה לִכְהֻנָּה וְזֶהוּ רֵיחַ הַגֵּט שֶּׁפּוֹסֵל בִּכְהֻנָּה מִדִּבְרֵיהֶם:","וְכָל מָקוֹם שֶׁאָמַרְנוּ בְּחִבּוּר זֶה שֶׁהַגֵּט פָּסוּל הֲרֵי זֶה פָּסוּל מִדִּבְרֵי סוֹפְרִים בִּלְבַד וְנִפְסְלָה בּוֹ מִן הַכְּהֻנָּה מִדִּבְרֵי תּוֹרָה. וְלֹא תִּנָּשֵׂא לְכַתְּחִלָּה וְאִם נִשֵּׂאת לֹא תֵּצֵא וְהַוָּלָד כָּשֵׁר. וְכוֹתְבִין לָהּ גֵּט אַחֵר כָּשֵׁר וְנוֹתְנִין לָהּ וְהִיא תַּחַת בַּעְלָהּ. וְאִם אִי אֶפְשָׁר לִכְתֹּב אַחֵר וְהָיָה הַבַּעַל וָתִיק וְגֵרֵשׁ מֵעַצְמוֹ הֲרֵי זֶה מְשֻׁבָּח אִם אֵין לָהּ בָּנִים. אֲבָל אִם יֵשׁ לָהּ בָּנִים לֹא יוֹצִיא מִפְּנֵי פְּסוּל הַגֵּט שֶׁמָּא יוֹצִיא לַעַז עַל בָּנָיו:","וְכָל מָקוֹם שֶׁאָמַרְנוּ בְּחִבּוּר זוֹ הֲרֵי זֶה סְפֵק גֵּרוּשִׁין אוֹ שֶׁהִיא סָפֵק מְגֹרֶשֶׁת לֹא תִּנָּשֵׂא וְאִם נִשֵּׂאת תֵּצֵא וְהַוָּלָד סְפֵק מַמְזֵר מִפְּנֵי שֶׁהִיא סְפֵק עֶרְוָה. וְכֵן אִם גֵּרֵשׁ אֶת אִשְׁתּוֹ בְּגֵט פָּסוּל אוֹ שֶׁהָיְתָה סָפֵק מְגֹרֶשֶׁת וְרָצָה לְהַחֲזִירָהּ הֲרֵי זוֹ מֻתֶּרֶת לְבַעְלָהּ. וְאֵינוֹ צָרִיךְ לְחַדֵּשׁ הַנִּשּׂוּאִין וּלְבָרֵךְ שֶׁבַע בְּרָכוֹת וְלִכְתֹּב כְּתֻבָּה עַד שֶׁתִּתְגָּרֵשׁ גֵּרוּשִׁין גְּמוּרִין:","כָּל מִי שֶׁנִּשֵּׂאת בְּגֵט בָּטֵל הֲרֵי זוֹ צְרִיכָה גֵּט מִבַּעַל שֵׁנִי מִדִּבְרֵיהֶן כְּדֵי שֶׁלֹּא יֹאמְרוּ אֵשֶׁת אִישׁ יוֹצְאָה בְּלֹא גֵּט. וּצְרִיכָה גֵּט מִן הָרִאשׁוֹן לְהַתִּירָהּ לִשְׁאָר הָעָם. וְנֶאֶסְרָה עַל שְׁנֵיהֶם לְעוֹלָם אַף עַל פִּי שֶׁנִּבְעֲלָה בִּשְׁגָגָה. כְּדֵי שֶׁלֹּא יֹאמְרוּ הֶחֱזִיר זֶה גְּרוּשָׁתוֹ אַחַר שֶׁנִּשֵּׂאת. וְאִם עָבַר אֶחָד מִשְּׁנֵיהֶן וְהֶחֱזִירָהּ יוֹצִיא:","וְכֵן הַדִּין בְּאִשָּׁה שֶׁבָּאוּ עֵדִים שֶׁמֵּת בַּעְלָהּ וְנִשֵּׂאת וְאַחַר כָּךְ בָּא בַּעְלָהּ בֵּין שֶׁהָיָה בַּעְלָהּ פִּקֵּחַ בֵּין שֶׁהָיָה חֵרֵשׁ בֵּין שֶׁנִּשֵּׂאת לְפִקֵּחַ בֵּין שֶׁנִּשֵּׂאת לְחֵרֵשׁ שֶׁאֵין קִדּוּשָׁיו קִדּוּשִׁין גְּמוּרִים תֵּצֵא מִשְּׁנֵיהֶם וּצְרִיכָה גֵּט מִזֶּה וּמִזֶּה וְנֶאֶסְרָה עַל שְׁנֵיהֶם עוֹלָמִית:","הֲרֵי שֶׁנִּתְקַדְּשָׁה וְאַחַר כָּךְ בָּא בַּעְלָהּ אוֹ נִמְצָא הַגֵּט בָּטֵל הֲרֵי זוֹ מֻתֶּרֶת לְבַעְלָהּ וְאֵינָהּ צְרִיכָה גֵּט מִשֵּׁנִי שֶׁאֵין קִדּוּשִׁין תּוֹפְסִין בַּעֲרָיוֹת. וְאֵין חוֹשְׁשִׁין שֶׁמָּא יֹאמְרוּ אֵשֶׁת אִישׁ יוֹצְאָה בְּלֹא גֵּט כֵּיוָן שֶׁלֹּא נִשֵּׂאת יֹאמְרוּ תְּנַאי הָיָה בַּקִּדּוּשִׁין וְלֹא נִתְקַיֵּם:","הָאִשָּׁה שֶׁנִּשֵּׂאת וְנִמְצָא הַגֵּט בָּטֵל. אוֹ בָּא בַּעְלָהּ אַחַר שֶׁשָּׁמְעָה שֶׁמֵּת. אֵין הַבַּעַל הָרִאשׁוֹן וְהַשֵּׁנִי זַכָּאִין לֹא בִּמְצִיאָתָהּ וְלֹא בְּמַעֲשֵׂי יָדֶיהָ וְלֹא בַּהֲפָרַת נְדָרֶיהָ. וְכָל פֵּרוֹת שֶׁאָכְלוּ שְׁנֵיהֶן אַחַר שֶׁנִּשֵּׂאת אֵין מוֹצִיאִין מֵהֶן. וְאֵין לָהּ כְּתֻבָּה וְלֹא תְּנַאי מִתְּנָאֵי כְּתֻבָּה וְלֹא מְזוֹנוֹת לֹא עַל זֶה וְלֹא עַל זֶה. וְאִם נָטְלָה מִזֶּה אוֹ מִזֶּה תַּחֲזִיר. וְכָל מַה שֶּׁבָּלָה אוֹ אָבַד מִנְּכָסֶיהָ וַאֲפִלּוּ מִנִּכְסֵי צֹאן בַּרְזֶל אֵין מוֹצִיאִין אוֹתָן לֹא מִזֶּה וְלֹא מִזֶּה. וְהַוָּלָד מִן הַשֵּׁנִי מַמְזֵר. וְאִם בָּא עָלֶיהָ הָרִאשׁוֹן קֹדֶם שֶׁגֵּרֵשׁ הַשֵּׁנִי הֲרֵי הַוָּלָד מַמְזֵר מִדִּבְרֵיהֶם. גֵּרְשָׁהּ הַשֵּׁנִי וְנָטְלָה מִמֶּנּוּ כְּתֻבָּה וְאַחַר כָּךְ בָּא בַּעְלָהּ אוֹ נִמְצָא הַגֵּט בָּטֵל אֵין מוֹצִיאִין מִיָּדָהּ מַה שֶּׁנָּטְלָה לֹא מִן הַמְּזוֹנוֹת וְלֹא מִן הַכְּתֻבָּה:","וְכֵן הַדִּין בְּאַחִין שֶׁקִּדֵּשׁ אֶחָד אִשָּׁה וְהָלַךְ אָחִיו וְשָׁמַע בּוֹ שֶׁמֵּת וְיִבֵּם אֶת אִשְׁתּוֹ וְאַחַר כָּךְ בָּא תֵּצֵא מִזֶּה וּמִזֶּה וּצְרִיכָה גֵּט מִזֶּה וּמִזֶּה וְכָל הַדְּבָרִים הָאֵלּוּ בָּהּ. וְכֵן אִם קִדֵּשׁ אִשָּׁה וְהָלְכָה לִמְדִינָה אַחֶרֶת וְשָׁמַע שֶׁמֵּתָה וְנָשָׂא אֲחוֹתָהּ וְאַחַר כָּךְ נוֹדַע שֶׁלֹּא מֵתָה צְרִיכוֹת שְׁתֵּיהֶן מִמֶּנּוּ גֵּט וְכָל הַדְּרָכִים הָאֵלּוּ בָּהֶן:","אֲבָל אִם הָלְכָה אִשְׁתּוֹ הַנְּשׂוּאָה לִמְדִינָה אַחֶרֶת וְשָׁמַע בָּהּ שֶׁמֵּתָה וְנָשָׂא אֲחוֹתָהּ וְנִמְצֵאת אִשְׁתּוֹ קַיֶּמֶת אֵין אֲחוֹתָהּ צְרִיכָה מִמֶּנּוּ גֵּט וְאִשְׁתּוֹ מֻתֶּרֶת. וְכֵן שְׁאָר הָעֲרָיוֹת שֶׁנְּשָׂאָן בְּחֶזְקַת הֶתֵּר וְנִמְצְאוּ עֶרְוָה אֵינָן צְרִיכוֹת גֵּט שֶׁאֵין קִדּוּשִׁין תּוֹפְסִין בַּעֲרָיוֹת:","וּמִפְּנֵי מָה הִצְרִיכוּ אֲחוֹת אֲרוּסָתוֹ גֵּט. שֶׁמָּא יֹאמְרוּ תְּנַאי הָיָה בָּאֵרוּסִין וְכַדָּת נָשָׂא אֲחוֹתָהּ. וְהוֹאִיל וְיָצְאָה אֲחוֹתָהּ בְּגֵט, אֲחוֹתָהּ שֶׁהִיא אֲרוּסָתוֹ הָרִאשׁוֹנָה אֲסוּרָה, כְּדֵי שֶׁלֹּא יֹאמְרוּ נָשָׂא אֲחוֹת גְּרוּשָׁתוֹ:","כָּתַב הַסּוֹפֵר וְטָעָה וְנָתַן גֵּט לָאִישׁ וְשׁוֹבֵר לָאִשָּׁה. אוֹ שֶׁטָּעוּ הֵן וְנָטַל הַבַּעַל הַגֵּט וְנָטְלָה הִיא הַשּׁוֹבֵר וְכִמְדֻמֶּה לָהֶן שֶׁנִּתְגָּרְשָׁה וּלְאַחַר זְמַן הֲרֵי הַגֵּט יוֹצֵא מִתַּחַת יְדֵי הָאִישׁ. אִם לֹא נִשֵּׂאת הֲרֵי זוֹ אֵינָהּ מְגֹרֶשֶׁת וְנִתְגַּלָּה הַדָּבָר שֶׁעֲדַיִן לֹא נִתְגָּרְשָׁה וְיִתֵּן לָהּ הַגֵּט בְּפָנֵינוּ וְתִהְיֶה מְגֹרֶשֶׁת מִשְּׁעַת נְתִינָתוֹ. וְאִם נִשֵּׂאת וְאַחַר כָּךְ הוֹצִיא הַבַּעַל אֶת הַגֵּט וְאָמַר עֲדַיִן לֹא נִתְגָּרְשָׁה שֶׁהֲרֵי הַגֵּט בְּיָדִי וְלֹא הִגִּיעַ לְיָדָהּ אֵין שׁוֹמְעִין לוֹ לְאָסְרָהּ עַל בַּעְלָהּ. אֶלָּא הֲרֵי זוֹ בְּחֶזְקַת גְּרוּשָׁה וְנָפַל הַגֵּט מִיָּדָהּ וּמְצָאוֹ זֶה וַהֲרֵי בָּא לְאָסְרָהּ עַל הַבַּעַל הַשֵּׁנִי:","הַמּוֹצִיא אֶת אִשְׁתּוֹ מִשּׁוּם שֵׁם רַע אוֹ מִשּׁוּם שֶׁהִיא פְּרוּצָה בִּנְדָרִים אוֹמְרִין לוֹ הוֹדִיעָהּ שֶׁמִּפְּנֵי זֶה אַתָּה מוֹצִיאָהּ כְּדֵי לְיַסְּרָהּ וְדַע שֶׁאֵין אַתָּה מַחֲזִירָהּ לְעוֹלָם. וּמִפְּנֵי מָה הַמּוֹצִיא אֶת זוֹ לֹא יַחֲזִירָהּ לְעוֹלָם. גְּזֵרָה שֶׁמָּא תִּנָּשֵׂא לְאַחֵר וְתַעֲשֶׂה תְּשׁוּבָה וְתִהְיֶה צְנוּעָה תַּחְתָּיו וְיֹאמַר הָרִאשׁוֹן אִלּוּ הָיִיתִי יוֹדֵעַ שֶׁכֵּן הוּא לֹא הָיִיתִי מְגָרְשָׁהּ וְנִמְצָא כִּמְגָרֵשׁ עַל תְּנַאי וְלֹא נִתְקַיֵּם שֶׁנִּמְצָא הַגֵּט בָּטֵל לְמַפְרֵעַ. לְפִיכָךְ אוֹמְרִים לוֹ גְּמֹר בְּלִבְּךָ לְגָרְשָׁהּ שֶׁאֵין זוֹ חוֹזֶרֶת לְךָ לְעוֹלָם. וְאִם עָבַר וְהֶחֱזִיר קֹדֶם שֶׁנִּתְקַדְּשָׁה לְאַחֵר לֹא יוֹצִיא:","וְכֵן הַמּוֹצִיא אֶת אִשְׁתּוֹ מִשּׁוּם אַיְלוֹנִית אוֹ מִשּׁוּם שֶׁרוֹאָה דָּם בְּכָל עֵת תַּשְׁמִישׁ הֲרֵי זֶה לֹא יַחֲזִיר לְעוֹלָם. שֶׁמָּא תִּנָּשֵׂא לְאַחֵר וְתֵלֵד הָאַיְלוֹנִית וְתִתְרַפֵּא הַנִּדָּה וְיֹאמַר אִלּוּ הָיִיתִי יוֹדֵעַ שֶׁכֵּן הוּא לֹא הָיִיתִי מְגָרְשָׁהּ וְנִמְצָא הַגֵּט בָּטֵל וְהַבָּנִים מַמְזֵרִים. וְאִם עָבַר וְהֶחֱזִיר לֹא יוֹצִיא:","שָׁלִיחַ שֶׁהֵבִיא גֵּט חוּצָה לָאָרֶץ וְאָמַר בְּפָנַי נִכְתַּב וּבְפָנַי נֶחְתַּם הֲרֵי זֶה לֹא יִשָּׂאֶנָּה. שֶׁאָנוּ חוֹשְׁשִׁין שֶׁמָּא עֵינָיו נָתַן בָּהּ וּלְפִיכָךְ הֵעִיד לָהּ. וְכֵן הָעֵד הָאֶחָד שֶׁהֵעִיד לְאִשָּׁה שֶׁמֵּת בַּעְלָהּ וְנִשֵּׂאת עַל פִּיו הֲרֵי זֶה לֹא יִשָּׂאֶנָּה. וְכֵן הֶחָכָם שֶׁאָסַר אֶת הָאִשָּׁה עַל בַּעְלָהּ בְּנֶדֶר הֲרֵי זֶה לֹא יִשָּׂאֶנָּה. וְכֵן הַנִּטְעָן עַל הַשִּׁפְחָה וְנִשְׁתַּחְרְרָה עַל הַנָּכְרִית וְנִתְגַּיְּרָה הֲרֵי זֶה לֹא יִשָּׂאֶנָּה. וְכֵן עַכּוּ״‎ם וְעֶבֶד הַבָּא עַל בַּת יִשְׂרָאֵל אַף עַל פִּי שֶׁחָזַר הָעַכּוּ״‎ם וְנִתְגַּיֵּר הָעֶבֶד וְנִשְׁתַּחְרֵר הֲרֵי זֶה לֹא יִשָּׂאֶנָּה. וְכֻלָּן אִם עָבְרוּ וְנָשְׂאוּ אֵין מוֹצִיאִין מִיָּדָם:","וְכֻלָּן שֶׁהָיוּ לָהֶם נָשִׁים וּמֵתוּ נְשׁוֹתֵיהֶן אוֹ שֶׁנִּתְגָּרְשׁוּ וְהָיוּ הַנָּשִׁים הֵן שֶׁהִרְגִּילוּ אֶת בַּעֲלֵיהֶן לְגָרְשָׁם הֲרֵי אֵלּוּ מֻתָּרוֹת לְהִנָּשֵׂא לָהֶן לְכַתְּחִלָּה. וְכֵן אִם הָלְכוּ נָשִׁים אֵלּוּ וְנִשְּׂאוּ לַאֲחֵרִים וְנִתְאַלְמְנוּ אוֹ נִתְגָּרְשׁוּ הֲרֵי אֵלּוּ מֻתָּרוֹת לְהִנָּשֵׂא לָהֶן לְכַתְּחִלָּה:","וְכָל אַחַת מֵהֶן מֻתֶּרֶת לְהִנָּשֵׂא לְבֶן הָעֵד שֶׁהֵעִיד לָהּ. אוֹ לְבֶן הֶחָכָם שֶׁאֲסָרָהּ עַל בַּעְלָהּ. אוֹ לְבֶן הַנִּטְעָן עָלֶיהָ אוֹ לִשְׁאָר קְרוֹבִין. שֶׁאֵין אָדָם חוֹטֵא כְּדֵי שֶׁיֵּהָנֶה אַחֵר. וּמֻתֶּרֶת הָאִשָּׁה לְהִנָּשֵׂא לְאֶחָד מֵעֵדֵי גֵּרוּשֶׁיהָ אוֹ מֵעֵדֵי מֵאוּנֶיהָ. אוֹ לְאֶחָד מִן הַדַּיָּנִים שֶׁחָלְצָה בִּפְנֵיהֶם. שֶׁאֵין חוֹשְׁשִׁין אֶלָּא לְעֵדוּת אֶחָד. וּלְעוֹלָם יִתְרַחֵק אָדָם מֵעֵדוּת מֵאוּן וְיִתְקָרֵב לַחֲלִיצָה:","הַמְגָרֵשׁ אֶת אִשְׁתּוֹ וְחָזַר וּבְעָלָהּ בִּפְנֵי עֵדִים קֹדֶם שֶׁתִּנָּשֵׂא לְאַחֵר בֵּין שֶׁגֵּרְשָׁהּ מִן הַנִּשּׂוּאִין בֵּין מִן הָאֵרוּסִין הוֹאִיל וְאִשְׁתּוֹ הָיְתָה הֲרֵי זוֹ בְּחֶזְקַת שֶׁהֶחֱזִירָהּ וּלְשֵׁם קִדּוּשִׁין בָּעַל וְלֹא לְשֵׁם זְנוּת. וַאֲפִלּוּ רָאוּ אוֹתוֹ שֶׁנָּתַן לָהּ מָעוֹת. שֶׁחֲזָקָה הִיא שֶׁאֵין אָדָם עוֹשֶׂה בְּעִילָתוֹ בְּאִשְׁתּוֹ בְּעִילַת זְנוּת וַהֲרֵי בְּיָדוֹ לַעֲשׂוֹתָהּ בְּעִילַת מִצְוָה. לְפִיכָךְ הֲרֵי זוֹ בְּחֶזְקַת מְקֻדֶּשֶׁת קִדּוּשֵׁי וַדַּאי וּצְרִיכָה מִמֶּנּוּ גֵּט שֵׁנִי:","נִתְיַחֵד עִמָּהּ בִּפְנֵי עֵדִים וְהוּא שֶׁיִּהְיוּ שְׁנֵי הָעֵדִים כְּאֶחָד. אִם הָיְתָה מְגֹרֶשֶׁת מִן הַנִּשּׂוּאִין חוֹשְׁשִׁין לָהּ שֶׁמָּא נִבְעֲלָה וְהֵן הֵן עֵדֵי יִחוּד הֵן הֵן עֵדֵי בִּיאָה. שֶׁכָּל הַמְקַדֵּשׁ בְּבִיאָה אֵינוֹ צָרִיךְ לִבְעל בִּפְנֵי עֵדִים אֶלָּא יִתְיַחֵד בִּפְנֵיהֶן וְיִבְעל כְּמוֹ שֶׁבֵּאַרְנוּ. לְפִיכָךְ צְרִיכָה גֵּט מִסָּפֵק וַהֲרֵי הִיא סָפֵק מְקֻדֶּשֶׁת. וְאִם הָיְתָה מְגֹרֶשֶׁת מִן הָאֵרוּסִין אֵין חוֹשְׁשִׁין לָהּ שֶׁהֲרֵי אֵין לִבּוֹ גַּס בָּהּ:","הוֹרוּ מִקְצָת הַגְּאוֹנִים שֶׁכָּל אִשָּׁה שֶׁתִּבָּעֵל בִּפְנֵי עֵדִים צְרִיכָה גֵּט. חֲזָקָה שֶׁאֵין אָדָם עוֹשֶׂה בְּעִילָתוֹ בְּעִילַת זְנוּת. וְהִגְדִּילוּ וְהוֹסִיפוּ בְּדָבָר זֶה שֶׁעָלָה עַל דַּעְתָּם עַד שֶׁהוֹרוּ שֶׁמִּי שֶׁיֵּשׁ לוֹ בֶּן מִשִּׁפְחָתוֹ חוֹשְׁשִׁין לוֹ וְלֹא תִּתְיַבֵּם אִשְׁתּוֹ שֶׁמָּא שִׁחְרֵר שִׁפְחָתוֹ וְאַחַר כָּךְ בָּא עָלֶיהָ. וְיֵשׁ מִי שֶׁהוֹרָה שֶׁוַּדַּאי שִׁחְרְרָהּ שֶׁאֵין אָדָם עוֹשֶׂה בְּעִילָתוֹ בְּעִילַת זְנוּת. וְכָל הַדְּבָרִים הָאֵלֶּה רְחוֹקִים הֵם בְּעֵינַי עַד מְאֹד מִדַּרְכֵי הַהוֹרָאָה וְאֵין רָאוּי לִסְמֹךְ עֲלֵיהֶן. שֶׁלֹּא אָמְרוּ חֲכָמִים חֲזָקָה זוֹ אֶלָּא בְּאִשְׁתּוֹ שֶׁגֵּרְשָׁהּ בִּלְבַד אוֹ בִּמְקַדֵּשׁ עַל תְּנַאי וּבָעַל סְתָם שֶׁהֲרֵי אִשְׁתּוֹ הִיא וּבְאִשְׁתּוֹ הִיא שֶׁחֶזְקָתוֹ שֶׁאֵינוֹ עוֹשֶׂה בְּעִילַת זְנוּת עַד שֶׁיְּפָרֵשׁ שֶׁהִיא בְּעִילַת זְנוּת אוֹ יְפָרֵשׁ שֶׁעַל תְּנַאי הוּא בּוֹעֵל. אֲבָל בִּשְׁאָר הַנָּשִׁים הֲרֵי כָּל זוֹנָה בְּחֶזְקַת שֶׁבָּעַל לְשֵׁם זְנוּת עַד שֶׁיְּפָרֵשׁ כִּי הוּא לְשֵׁם קִדּוּשִׁין. וְאֵין צָרִיךְ לוֹמַר בְּשִׁפְחָה אוֹ כּוּתִית שֶׁאֵינָהּ בַּת קִדּוּשִׁין שֶׁאֵין חוֹשְׁשִׁין לָהֶן כְּלָל. וַהֲרֵי הַבֵּן מֵהֶן בְּחֶזְקַת כּוּתִי וְעֶבֶד עַד שֶׁיִּוָּדַע בְּוַדַּאי שֶׁנִּשְׁתַּחְרְרָה אִמּוֹ אוֹ נִתְגַּיְּרָה:","מִי שֶׁהֻחְזְקָה אֵשֶׁת אִישׁ בֵּין מִן הַנִּשּׂוּאִין בֵּין מִן הָאֵרוּסִין וְיָצָא שְׁמָהּ בָּעִיר מְגֹרֶשֶׁת. אֲפִלּוּ רֹב הָעִיר אוֹ כֻּלָּהּ מַעֲבִירִין הַקּוֹל שֶׁנִּתְגָּרְשָׁה אֵין חוֹשְׁשִׁין לָהּ וַהֲרֵי הִיא בְּחֶזְקָתָהּ. אֲבָל אִם יָצָא שְׁמָהּ בָּעִיר מְקֻדֶּשֶׁת וְהֻחְזַק הַקּוֹל בְּבֵית דִּין שֶׁהֲרֵי הִיא מְקֻדֶּשֶׁת בְּסָפֵק כְּמוֹ שֶׁבֵּאַרְנוּ וְאַחַר כָּךְ יָצָא עָלֶיהָ קוֹל שֶׁנִּתְגָּרְשָׁה מֵאוֹתָן הַקִּדּוּשִׁין הַקּוֹל אֲסָרָהּ וְהַקּוֹל הִתִּירָהּ וַהֲרֵי זוֹ מְגֹרֶשֶׁת:","לֹא יִשָּׂא אָדָם אִשָּׁה וְדַעְתּוֹ לְגָרְשָׁהּ. וְלֹא תִּהְיֶה יוֹשֶׁבֶת תַּחְתָּיו וּמְשַׁמַּשְׁתּוֹ וְדַעְתּוֹ לְגָרְשָׁהּ. וְלֹא יְגָרֵשׁ אָדָם אִשְׁתּוֹ רִאשׁוֹנָה אֶלָּא אִם כֵּן מָצָא בָּהּ עֶרְוַת דָּבָר שֶׁנֶּאֱמַר (דברים כד א) ״‎כִּי מָצָא בָהּ עֶרְוַת דָּבָר״‎ וְגוֹ'. וְאֵין רָאוּי לוֹ לְמַהֵר לְשַׁלֵּחַ אִשְׁתּוֹ רִאשׁוֹנָה. אֲבָל שְׁנִיָּה אִם שְׂנֵאָהּ יְשַׁלְּחֶנָּה:","אִשָּׁה רָעָה בְּדֵעוֹתֶיהָ וְשֶׁאֵינָהּ צְנוּעָה כִּבְנוֹת יִשְׂרָאֵל הַכְּשֵׁרוֹת מִצְוָה לְגָרְשָׁהּ שֶׁנֶּאֱמַר (משלי כב י) ״‎גָּרֵשׁ לֵץ וְיֵצֵא מָדוֹן״‎. וְאִשָּׁה שֶׁנִּתְגָּרְשָׁה מִשּׁוּם פְּרִיצוּת אֵין רָאוּי לְאָדָם כָּשֵׁר שֶׁיִּשָּׂאֶנָּה. שֶׁלֹּא יֹאמְרוּ זֶה הוֹצִיא רְשָׁעָה מִבֵּיתוֹ וְזֶה מַכְנִיסָהּ:","מִי שֶׁנִּתְחָרְשָׁה אִשְׁתּוֹ הֲרֵי זֶה מְגָרְשָׁהּ בְּגֵט וְתִהְיֶה מְגֹרֶשֶׁת. אֲבָל אִם נִשְׁתַּטֵּית אֵינוֹ מוֹצִיאָהּ עַד שֶׁתַּבְרִיא. וְדָבָר זֶה תַּקָּנַת חֲכָמִים הוּא כְּדֵי שֶׁלֹּא תְּהֵא הֶפְקֵר לִפְרוּצִין שֶׁהֲרֵי אֵינָהּ יְכוֹלָה לִשְׁמֹר עַצְמָהּ. לְפִיכָךְ מַנִּיחָהּ וְנוֹשֵׂא אַחֶרֶת וּמַאֲכִילָהּ וּמַשְׁקָהּ מִשֶּׁלָּהּ. וְאֵין מְחַיְּבִין אוֹתוֹ בִּשְׁאֵר כְּסוּת וְעוֹנָה שֶׁאֵין כֹּחַ בְּבֶן דַּעַת לָדוּר עִם הַשּׁוֹטִים בְּבַיִת אֶחָד. וְאֵינוֹ חַיָּב לְרַפְּאוֹתָהּ וְלֹא לִפְדּוֹתָהּ. וְאִם גֵּרְשָׁהּ הֲרֵי זוֹ מְגֹרֶשֶׁת וּמוֹצִיאָהּ מִבֵּיתוֹ וְאֵינוֹ חַיָּב לַחֲזֹר וּלְהִטָּפֵל בָּהּ:"],"Mishneh Torah, Eruvin 1":["חָצֵר שֶׁיֵּשׁ בָּהּ שְׁכֵנִים הַרְבֵּה כָּל אֶחָד מֵהֶם בְּבַיִת לְעַצְמוֹ דִּין תּוֹרָה הוּא שֶׁיִּהְיוּ כֻּלָּן מֻתָּרִין לְטַלְטֵל בְּכָל הֶחָצֵר וּמִבָּתִּים לֶחָצֵר וּמֵהֶחָצֵר לַבָּתִּים מִפְּנֵי שֶׁכָּל הֶחָצֵר רְשׁוּת הַיָּחִיד אַחַת וּמֻתָּר לְטַלְטֵל בְּכֻלָּהּ. וְכֵן הַדִּין בְּמָבוֹי שֶׁיֵּשׁ לוֹ לֶחִי אוֹ קוֹרָה שֶׁיִּהְיוּ כָּל בְּנֵי הַמָּבוֹי מֻתָּרִים לְטַלְטֵל בְּכֻלּוֹ וּמֵחֲצֵרוֹת לַמָּבוֹי וּמִמָּבוֹי לַחֲצֵרוֹת שֶׁכָּל הַמָּבוֹי רְשׁוּת הַיָּחִיד הוּא. וְכֵן הַדִּין בִּמְדִינָה שֶׁהִיא מֻקֶּפֶת חוֹמָה גְּבוֹהָה עֲשָׂרָה טְפָחִים שֶׁיֵּשׁ לָהּ דְּלָתוֹת וְנִנְעָלוֹת בַּלַּיְלָה שֶׁכֻּלָּהּ רְשׁוּת הַיָּחִיד הִיא. זֶה הוּא דִּין תּוֹרָה:","אֲבָל מִדִּבְרֵי סוֹפְרִים אָסוּר לִשְׁכֵנִים לְטַלְטֵל בִּרְשׁוּת הַיָּחִיד שֶׁיֵּשׁ בָּהּ חֲלוּקָה בְּדִיּוּרִין עַד שֶׁיְּעָרְבוּ כָּל הַשְּׁכֵנִים כֻּלָּן מֵעֶרֶב שַׁבָּת. אֶחָד חָצֵר וְאֶחָד מָבוֹי וְאֶחָד הַמְּדִינָה. וְדָבָר זֶה תַּקָּנַת שְׁלֹמֹה וּבֵית דִּינוֹ:","וְכֵן יוֹשְׁבֵי אֹהָלִים אוֹ סֻכּוֹת אוֹ מַחֲנֶה שֶׁהִקִּיפוּהוּ מְחִצָּה אֵין מְטַלְטְלִין מֵאֹהֶל לְאֹהֶל עַד שֶׁיְּעָרְבוּ כֻּלָּן. אֲבָל שַׁיָּרָא שֶׁהִקִּיפָה מְחִצָּה אֵין צְרִיכִין לְעָרֵב אֶלָּא מוֹצִיאִין מֵאֹהֶל לְאֹהֶל בְּלֹא עֵרוּב לְפִי שֶׁהֵן כֻּלָּן מְעֹרָבִין וְאֵין אוֹתָן אֹהָלִים קְבוּעִין לָהֶן:","וּמִפְּנֵי מָה תִּקֵּן שְׁלֹמֹה דָּבָר זֶה. כְּדֵי שֶׁלֹּא יִטְעוּ הָעָם וְיֹאמְרוּ כְּשֵׁם שֶׁמֻּתָּר לְהוֹצִיא מִן הַחֲצֵרוֹת לִרְחוֹבוֹת הַמְּדִינָה וּשְׁוָקֶיהָ וּלְהַכְנִיס מֵהֶם לַחֲצֵרוֹת כָּךְ מֻתָּר לְהוֹצִיא מִן הַמְּדִינָה לַשָּׂדֶה וּלְהַכְנִיס מִן הַשָּׂדֶה לַמְּדִינָה. וְיַחְשְׁבוּ שֶׁהַשְּׁוָקִים וְהָרְחוֹבוֹת הוֹאִיל וְהֵן רְשׁוּת לַכֹּל הֲרֵי הֵן כְּשָׂדוֹת וּכְמִדְבָּרוֹת וְיֹאמְרוּ שֶׁהַחֲצֵרוֹת בִּלְבַד הֵן רְשׁוּת הַיָּחִיד וִידַמּוּ שֶׁאֵין הַהוֹצָאָה מְלָאכָה וְשֶׁמֻּתָּר לְהוֹצִיא וּלְהַכְנִיס מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הָרַבִּים:","לְפִיכָךְ תִּקֵּן שֶׁכָּל רְשׁוּת הַיָּחִיד שֶׁתֶּחֱלַּק בְּדִיּוּרִין וְיֹאחַז כָּל אֶחָד וְאֶחָד בָּהּ רְשׁוּת לְעַצְמוֹ וְיִשָּׁאֵר מִמֶּנָּה מָקוֹם בִּרְשׁוּת כֻּלָּן וְיַד כֻּלָּן שָׁוָה בּוֹ כְּגוֹן חָצֵר לַבָּתִּים. שֶׁנַּחְשֹׁב אוֹתוֹ הַמָּקוֹם שֶׁיַּד כֻּלָּן שָׁוָה בּוֹ כְּאִלּוּ הוּא רְשׁוּת לָרַבִּים. וְנֶחְשָׁב כָּל מָקוֹם וּמָקוֹם שֶׁאָחַז כָּל אֶחָד מִן הַשְּׁכֵנִים וְחִלְּקוֹ לְעַצְמוֹ שֶׁהוּא בִּלְבַד רְשׁוּת הַיָּחִיד. וְיִהְיֶה אָסוּר לְהוֹצִיא מֵרְשׁוּת שֶׁחָלַק לְעַצְמוֹ לִרְשׁוּת שֶׁיַּד כֻּלָּם שָׁוָה בּוֹ. כְּמוֹ שֶׁאֵין מוֹצִיאִין מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הָרַבִּים. אֶלָּא יִשְׁתַּמֵּשׁ כָּל אֶחָד בָּרְשׁוּת שֶׁחָלַק לְעַצְמוֹ בִּלְבַד עַד שֶׁיְּעָרְבוּ כֻּלָּן אַף עַל פִּי שֶׁהַכֹּל רְשׁוּת הַיָּחִיד:","וּמַה הוּא הָעֵרוּב הַזֶּה. הוּא שֶׁיִּתְעָרְבוּ בְּמַאֲכָל אֶחָד שֶׁמַּנִּיחִין אוֹתוֹ מֵעֶרֶב שַׁבָּת. כְּלוֹמַר שֶׁכֻּלָּנוּ מְעֹרָבִין וְאֹכֶל אֶחָד לְכֻלָּנוּ וְאֵין כָּל אֶחָד מִמֶּנּוּ חוֹלֵק רְשׁוּת מֵחֲבֵרוֹ אֶלָּא כְּשֵׁם שֶׁיַּד כֻּלָּנוּ שָׁוָה בְּמָקוֹם זֶה שֶׁנִּשְׁאַר לְכֻלָּנוּ כָּךְ יַד כֻּלָּנוּ שָׁוָה בְּכָל מָקוֹם שֶׁיֹּאחֵז כָּל אֶחָד לְעַצְמוֹ וַהֲרֵי כֻּלָּנוּ רְשׁוּת אֶחָד. וּבַמַּעֲשֶׂה הַזֶּה לֹא יָבוֹאוּ לִטְעוֹת וּלְדַמּוֹת שֶׁמֻּתָּר לְהוֹצִיא וּלְהַכְנִיס מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הָרַבִּים:","הָעֵרוּב שֶׁעוֹשִׂים בְּנֵי הֶחָצֵר זֶה עִם זֶה הוּא הַנִּקְרָא עֵרוּבֵי חֲצֵרוֹת. וְשֶׁעוֹשִׂין אַנְשֵׁי מָבוֹי זֶה עִם זֶה אוֹ כָּל בְּנֵי הַמְּדִינָה הוּא הַנִּקְרָא שִׁתּוּף:","אֵין מְעָרְבִין בַּחֲצֵרוֹת אֶלָּא בְּפַת שְׁלֵמָה בִּלְבַד. אֲפִלּוּ כִּכַּר מַאֲפֶה סְאָה וְהִיא פְּרוּסָה אֵין מְעָרְבִין בָּהּ. הָיְתָה שְׁלֵמָה וְהִיא כְּאִיסָר מְעָרְבִין בָּהּ. וּכְשֵׁם שֶׁמְּעָרְבִין בְּפַת תְּבוּאָה כָּךְ מְעָרְבִין בְּפַת אֹרֶז וּבְפַת עֲדָשִׁים אֲבָל לֹא בְּפַת דֹּחַן. וְשִׁתּוּף בֵּין בְּפַת בֵּין בִּשְׁאָר אֳכָלִים. בְּכָל אֹכֶל מִשְׁתַּתְּפִין חוּץ מִן הַמַּיִם בִּפְנֵי עַצְמָן אוֹ מֶלַח בִּפְנֵי עַצְמוֹ. וְכֵן כְּמֵהִין וּפִטְרִיּוֹת אֵין מִשְׁתַּתְּפִין בָּהֶן שֶׁאֵינָן חֲשׁוּבִין כָּאֳכָלִים. עֵרֵב מַיִם עִם מֶלַח נַעֲשָׂה כְּמוּרְיָס וּמִשְׁתַּתְּפִין:","וְכַמָּה שִׁעוּר הָאֹכֶל שֶׁמִּשְׁתַּתְּפִין בּוֹ. כִּגְרוֹגֶרֶת לְכָל אֶחָד וְאֶחָד מִבְּנֵי הַמָּבוֹי אוֹ מִבְּנֵי הַמְּדִינָה. וְהוּא שֶׁיִּהְיוּ שְׁמוֹנֶה עֶשְׂרֵה אוֹ פָּחוֹת. אֲבָל אִם הָיוּ מְרֻבִּים עַל זֶה שִׁעוּרוֹ שְׁתֵּי סְעֻדּוֹת שֶׁהֵן כִּשְׁמוֹנֶה עֶשְׂרֵה גְּרוֹגָרוֹת שֶׁהֵן כְּשֵׁשׁ בֵּיצִים בֵּינוֹנִיּוֹת. אֲפִלּוּ הָיוּ הַמִּשְׁתַּתְּפִין אֲלָפִים וּרְבָבוֹת שְׁתֵּי סְעֻדּוֹת לְכֻלָּן:","כָּל אֹכֶל שֶׁהוּא נֶאֱכָל כְּמוֹת שֶׁהוּא כְּגוֹן פַּת וּמִינֵי דָּגָן וּבָשָׂר חַי אִם נִשְׁתַּתְּפוּ בּוֹ שִׁעוּרוֹ מְזוֹן שְׁתֵּי סְעֻדּוֹת. וְכָל שֶׁהוּא לִפְתָּן וְדֶרֶךְ הָעָם לֶאֱכֹל בּוֹ פִּתָּן כְּגוֹן יַיִן מְבֻשָּׁל וּבָשָׂר צָלִי וְחֹמֶץ וּמוּרְיָס וְזֵיתִים וְאִמָּהוֹת שֶׁל בְּצָלִים שִׁעוּרוֹ כְּדֵי לֶאֱכֹל בּוֹ שְׁתֵּי סְעֻדּוֹת:","נִשְׁתַּתְּפוּ בְּיַיִן חַי שִׁעוּרוֹ שְׁתֵּי רְבִיעִיּוֹת לְכֻלָּן. וְכֵן בְּשֵׁכָר שְׁתֵּי רְבִיעִיּוֹת. בֵּיצִים שְׁתַּיִם וּמִשְׁתַּתְּפִין בָּהֶן וַאֲפִלּוּ הֵן חַיּוֹת. וְרִמּוֹנִים שְׁנַיִם. אֶתְרוֹג אֶחָד. חֲמִשָּׁה אֱגוֹזִים. חֲמִשָּׁה אֲפַרְסֵקִים. לִיטְרָא שֶׁל יָרָק בֵּין חַי בֵּין שָׁלוּק וְאִם הָיָה בָּשִׁיל וְלֹא בָּשִׁיל אֵין מְעָרְבִין בּוֹ לְפִי שֶׁאֵינוֹ רָאוּי לַאֲכִילָה. עֻכְּלָא תַּבְלִין. קַב תְּמָרִים. קַב גְּרוֹגָרוֹת. מָנֶה דְּבֵלָה. קַב תַּפּוּחִין. כְּשׁוּת כִּמְלוֹא הַיָּד. פּוֹלִין לַחִין כִּמְלוֹא הַיָּד. חֲזִין לִיטְרָא. וְהַתְּרָדִין הֲרֵי הֵן בִּכְלַל הָיָּרָק וּמְעָרְבִין בָּהֶן. עֲלֵי בְּצָלִים אֵין מְעָרְבִין בָּהֶן. אֶלָּא אִם הִבְצִילוּ וְנַעֲשָׂה אֹרֶךְ כָּל עָלֶה מֵהֶן זֶרֶת. אֲבָל פָּחוֹת מִכָּאן אֵינוֹ אֹכֶל. וְכָל אֵלּוּ הַדְּבָרִים הָאֲמוּרִין כְּלִפְתָּן הֵן. וּלְפִיכָךְ נָתְנוּ בָּהֶן שִׁעוּרִין אֵלּוּ. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן. וְכָל הָאֳכָלִין מִצְטָרְפִין לְשִׁעוּר הַשִּׁתּוּף:","לִיטְרָא הָאֲמוּרָה בְּכָל מָקוֹם מְלֹא שְׁתֵּי רְבִיעִיּוֹת. וְעֻכְּלָא חֲצִי רְבִיעִית. וּמָנֶה הָאֲמוּרָה בְּכָל מָקוֹם מֵאָה דִּינָר. וְהַדִּינָר שֵׁשׁ מָעִין. וְהַמָּעָה מִשְׁקַל שֵׁשׁ עֶשְׂרֵה שְׂעוֹרוֹת. וְהַסֶּלַע אַרְבָּעָה דִּינָרִין. וְהָרְבִיעִית מַחְזֶקֶת מִן הַמַּיִם אוֹ מִן הַיַּיִן מִשְׁקַל שִׁבְעָה עָשָׂר דִּינָרִין וַחֲצִי דִּינָר בְּקֵרוּב. נִמְצָא הַלִּיטְרָא מִשְׁקַל חֲמִשָּׁה וּשְׁלֹשִׁים דִּינָר. וְהָעֻכְּלָא מִשְׁקַל תִּשְׁעָה דִּינָרִין פָּחוֹת רְבִיעַ:","סְאָה הָאֲמוּרָה בְּכָל מָקוֹם שֵׁשֶׁת קַבִּין. וְהַקַּב אַרְבָּעָה לוֹגִין. וְהַלּוֹג אַרְבַּע רְבִיעִיּוֹת. וּכְבָר בֵּאַרְנוּ מִדַּת הָרְבִיעִית וּמִשְׁקָלָהּ. וְאֵלּוּ הַשִּׁעוּרִין שֶׁאָדָם צָרִיךְ לִזְכֹּר אוֹתָן תָּמִיד:","אֹכֶל שֶׁהוּא מֻתָּר בַּאֲכִילָה אַף עַל פִּי שֶׁהוּא אָסוּר לְזֶה הַמְעָרֵב הֲרֵי זֶה מְעָרֵב בּוֹ וּמִשְׁתַּתֵּף בּוֹ. כֵּיצַד. מִשְׁתַּתֵּף הַנָּזִיר בְּיַיִן וְיִשְׂרָאֵל בִּתְרוּמָה. וְכֵן הַנּוֹדֵר מֵאֹכֶל זֶה אוֹ שֶׁנִּשְׁבַּע שֶׁלֹּא יֹאכְלֶנּוּ מְעָרֵב בּוֹ וּמִשְׁתַּתֵּף בּוֹ. שֶׁאִם אֵינוֹ רָאוּי לָזֶה הֲרֵי הוּא רָאוּי לְאַחֵר:","אֲבָל דָּבָר הָאָסוּר לַכֹּל כְּגוֹן טֶבֶל אֲפִלּוּ טֶבֶל שֶׁל דִּבְרֵי סוֹפְרִים. וְכֵן מַעֲשֵׂר רִאשׁוֹן שֶׁלֹּא נִטְּלָה תְּרוּמָתוֹ כַּהֹגֶן. וְכֵן מַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁלֹּא נִפְדּוּ כַּהֲלָכָה. אֵין מְעָרְבִין וּמִשְׁתַּתְּפִין בָּהֶן. אֲבָל מְעָרְבִין וּמִשְׁתַּתְּפִין בִּדְמַאי מִפְּנֵי שֶׁרָאוּי לָעֲנִיִּים. וּבְמַעֲשֵׂר רִאשׁוֹן שֶׁנִּטְּלָה תְּרוּמָתוֹ. וּבְמַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁנִּפְדּוּ אַף עַל פִּי שֶׁלֹּא נָתַן אֶת הַחֹמֶשׁ שֶׁאֵין הַחֹמֶשׁ מְעַכֵּב. וּמְעָרְבִין בְּמַעֲשֵׂר שֵׁנִי בִּירוּשָׁלַיִם מִפְּנֵי שֶׁהוּא רָאוּי שָׁם לַאֲכִילָה אֲבָל לֹא בִּגְבוּלִין:","כֵּיצַד מְעָרְבִין בַּחֲצֵרוֹת. גּוֹבִין חַלָּה אַחַת שְׁלֵמָה מִכָּל בַּיִת וּבַיִת וּמַנִּיחִין הַכֹּל בִּכְלִי אֶחָד בְּבַיִת אֶחָד מִבָּתֵּי הֶחָצֵר אֲפִלּוּ בְּבֵית הַתֶּבֶן אוֹ בְּבֵית הַבָּקָר אוֹ בְּבֵית הָאוֹצָר. אֲבָל אִם נָתְנוּ בְּבֵית שַׁעַר אֲפִלּוּ בֵּית שַׁעַר שֶׁל יָחִיד אוֹ בְּאַכְסַדְרָה אוֹ בְּמִרְפֶּסֶת אוֹ בְּבַיִת שֶׁאֵין בּוֹ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת אֵינוֹ עֵרוּב. וּכְשֶׁמְּקַבֵּץ הָעֵרוּב מְבָרֵךְ בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל מִצְוַת עֵרוּב. וְאוֹמֵר בְּעֵרוּב זֶה יִהְיֶה מֻתָּר לְכָל בְּנֵי הֶחָצֵר לְהוֹצִיא וּלְהַכְנִיס מִבַּיִת לְבַיִת בְּשַׁבָּת. וְיֵשׁ לְקָטָן לִגְבּוֹת עֵרוּבֵי חֲצֵרוֹת. וּבַיִת שֶׁמַּנִּיחִין בּוֹ עֵרוּב אֵינוֹ צָרִיךְ לִתֵּן אֶת הַפַּת. וְאִם הָיוּ רְגִילִין לְהַנִּיחַ בּוֹ אֵין מְשַׁנִּין אוֹתוֹ מִפְּנֵי דַּרְכֵי שָׁלוֹם:","וְכֵיצַד מִשְׁתַּתְּפִין בְּמָבוֹי. גּוֹבֶה אֹכֶל כִּגְרוֹגֶרֶת מִכָּל אֶחָד וְאֶחָד אוֹ פָּחוֹת מִכִּגְרוֹגֶרֶת אִם הָיוּ מְרֻבִּין. וּמַנִּיחַ הַכֹּל בִּכְלִי אֶחָד בְּחָצֵר מֵחַצְרוֹת הַמָּבוֹי אוֹ בְּבַיִת מִן הַבָּתִּים אֲפִלּוּ בַּיִת קָטָן אוֹ אַכְסַדְרָה אוֹ מִרְפֶּסֶת הֲרֵי זֶה שִׁתּוּף. אֲבָל אִם הִנִּיחוֹ בַּאֲוִיר מָבוֹי אֵינוֹ שִׁתּוּף. וְאִם הִנִּיחַ הַכְּלִי בֶּחָצֵר צָרִיךְ לְהַגְבִּיהַּ הַכְּלִי מִן הַקַּרְקַע טֶפַח כְּדֵי שֶׁיִּהְיֶה נִכָּר. וּמְבָרֵךְ עַל מִצְוַת עֵרוּב. וְאוֹמֵר בְּזֶה הַשִּׁתּוּף יִהְיֶה מֻתָּר לְכָל בְּנֵי הַמָּבוֹי לְהוֹצִיא וּלְהַכְנִיס מֵחֲצֵרוֹת לַמָּבוֹי בְּשַׁבָּת:","חָלְקוּ אֶת הָעֵרוּב אוֹ אֶת הַשִּׁתּוּף אַף עַל פִּי שֶׁהוּא בְּבַיִת אֶחָד אֵינוֹ עֵרוּב. אֲבָל אִם מִלְּאוּ אֶת הַכְּלִי מִן הָעֵרוּב וְנִשְׁאַר מִמֶּנּוּ מְעַט וְהִנִּיחוּהוּ בִּכְלִי אַחֵר מֻתָּר:","הַמִּשְׁתַּתְּפִין בַּמָּבוֹי צְרִיכִים לְעָרֵב בַּחֲצֵרוֹת כְּדֵי שֶׁלֹּא יִשְׁכְּחוּ הַתִּינוֹקוֹת תּוֹרַת עֵרוּב. שֶׁהֲרֵי אֵין הַתִּינוֹקוֹת מַכִּירִין מַה נַּעֲשָׂה בַּמָּבוֹי. לְפִיכָךְ אִם נִשְׁתַּתְּפוּ בַּמָּבוֹי בְּפַת סוֹמְכִין עָלָיו וְאֵין צְרִיכִין לְעָרֵב בַּחֲצֵרוֹת שֶׁהֲרֵי הַתִּינוֹקוֹת מַכִּירִין בַּפַּת. בְּנֵי חֲבוּרָה שֶׁהָיוּ מְסֻבִּין וְקָדַּשׁ עֲלֵיהֶן הַיּוֹם פַּת שֶׁעַל הַשֻּׁלְחָן סוֹמְכִין עָלֶיהָ מִשּׁוּם עֵרוּבֵי חֲצֵרוֹת. וְאִם רָצוּ לִסְמֹךְ עָלֶיהָ מִשּׁוּם שִׁתּוּף סוֹמְכִין אַף עַל פִּי שֶׁהֵן מְסֻבִּין בֶּחָצֵר:","לָקַח אֶחָד מִבְּנֵי הֶחָצֵר פַּת אַחַת וְאָמַר הֲרֵי זוֹ לְכָל בְּנֵי הֶחָצֵר אוֹ שֶׁהוּא אֹכֶל כִּשְׁתֵּי סְעֻדּוֹת וְאָמַר הֲרֵי זֶה לְכָל בְּנֵי הַמָּבוֹי אֵינוֹ צָרִיךְ לִגְבּוֹת מִכָּל אֶחָד וְאֶחָד. אֲבָל צָרִיךְ לְזַכּוֹת לָהֶן בּוֹ עַל יְדֵי אַחֵר. וְיֵשׁ לוֹ לְזַכּוֹת עַל יְדֵי בְּנוֹ וּבִתּוֹ הַגְּדוֹלִים וְעַל יְדֵי עַבְדּוֹ הָעִבְרִי וְעַל יְדֵי אִשְׁתּוֹ. אֲבָל לֹא עַל יְדֵי בְּנוֹ וּבִתּוֹ הַקְּטַנִּים וְלֹא עַל יְדֵי עַבְדּוֹ וְשִׁפְחָתוֹ הַכְּנַעֲנִים מִפְּנֵי שֶׁיָּדָן כְּיָדוֹ. וְכֵן יֵשׁ לוֹ לְזַכּוֹת לָהֶן עַל יְדֵי שִׁפְחָתוֹ הָעִבְרִית אַף עַל פִּי שֶׁהִיא קְטַנָּה. שֶׁהַקָּטָן זוֹכֶה לַאֲחֵרִים בְּדָבָר שֶׁהוּא מִדִּבְרֵי סוֹפְרִים. וְאֵינוֹ צָרִיךְ לְהוֹדִיעַ לִבְנֵי הֶחָצֵר אוֹ לִבְנֵי הַמָּבוֹי שֶׁהֲרֵי זָכָה לָהֶן וְעֵרֵב עֲלֵיהֶן שֶׁזְּכוּת הִיא לָהֶן וְזָכִין לוֹ לְאָדָם שֶׁלֹּא בְּפָנָיו:","אֵין מְעָרְבִין וְלֹא מִשְׁתַּתְּפִין בְּשַׁבָּת אֶלָּא מִבְּעוֹד יוֹם. וּמְעָרְבִין עֵרוּבֵי חֲצֵרוֹת וְשִׁתּוּפֵי מְבוֹאוֹת בֵּין הַשְּׁמָשׁוֹת אַף עַל פִּי שֶׁהוּא סָפֵק מִן הַיּוֹם סָפֵק מִן הַלַּיְלָה. וּלְעוֹלָם צָרִיךְ שֶׁיְּהֵא הָעֵרוּב אוֹ הַשִּׁתּוּף מָצוּי וְאֶפְשָׁר לְאָכְלוֹ כָּל בֵּין הַשְּׁמָשׁוֹת. לְפִיכָךְ אִם נָפַל עָלָיו גַּל אוֹ אָבַד אוֹ נִשְׂרַף אוֹ שֶׁהָיָה תְּרוּמָה וְנִטְמֵאת מִבְּעוֹד יוֹם אֵינוֹ עֵרוּב. מִשֶּׁחֲשֵׁכָה הֲרֵי זֶה עֵרוּב. וְאִם סָפֵק הֲרֵי זֶה עֵרוּב שֶׁסְּפֵק הָעֵרוּב כָּשֵׁר:","נָתַן הָעֵרוּב אוֹ הַשִּׁתּוּף בַּמִּגְדָּל וְנָעַל עָלָיו וְאָבַד הַמַּפְתֵּחַ קֹדֶם שֶׁחֲשֵׁכָה אִם אִי אֶפְשָׁר לוֹ לְהוֹצִיא הָעֵרוּב אֶלָּא אִם כֵּן עָשָׂה מְלָאכָה בֵּין הַשְּׁמָשׁוֹת הֲרֵי זֶה כְּמִי שֶׁאָבַד וְאֵינוֹ עֵרוּב שֶׁהֲרֵי אִי אֶפְשָׁר לְאָכְלוֹ. הִפְרִישׁ תְּרוּמַת מַעֲשֵׂר אוֹ תְּרוּמָה גְּדוֹלָה וְהִתְנָה עָלֶיהָ שֶׁלֹּא תִּהְיֶה תְּרוּמָה עַד שֶׁתֶּחְשַׁךְ אֵין מְעָרְבִין בָּהּ שֶׁעֲדַיִן הִיא טֶבֶל כָּל בֵּין הַשְּׁמָשׁוֹת וְצָרִיךְ שֶׁתִּהְיֶה סְעֻדָּה הָרְאוּיָה מִבְּעוֹד יוֹם:"],"Mishneh Torah, Fasts 5":["יֵשׁ שָׁם יָמִים שֶׁכָּל יִשְׂרָאֵל מִתְעַנִּים בָּהֶם מִפְּנֵי הַצָּרוֹת שֶׁאֵרְעוּ בָּהֶן כְּדֵי לְעוֹרֵר הַלְּבָבוֹת לִפְתֹּחַ דַּרְכֵי הַתְּשׁוּבָה וְיִהְיֶה זֶה זִכָּרוֹן לְמַעֲשֵׂינוּ הָרָעִים וּמַעֲשֵׂה אֲבוֹתֵינוּ שֶׁהָיָה כְּמַעֲשֵׂינוּ עַתָּה עַד שֶׁגָּרַם לָהֶם וְלָנוּ אוֹתָן הַצָּרוֹת. שֶׁבְּזִכְרוֹן דְּבָרִים אֵלּוּ נָשׁוּב לְהֵיטִיב שֶׁנֶּאֱמַר (ויקרא כו, מ) \"וְהִתְוַדּוּ אֶת עֲוֹנָם וְאֶת עֲוֹן אֲבֹתָם\" וְגוֹ':","וְאֵלּוּ הֵן יוֹם שְׁלִישִׁי בְּתִשְׁרֵי שֶׁבּוֹ נֶהֱרַג גְּדַלְיָה בֵּן אֲחִיקָם וְנִכְבַּת גַּחֶלֶת יִשְׂרָאֵל הַנִּשְׁאָרָה וְסִבֵּב לְהָתָם גָּלוּתָן. וַעֲשִׂירִי בְּטֵבֵת שֶׁבּוֹ סָמַךְ מֶלֶךְ בָּבֶל נְבוּכַדְנֶאצַּר הָרָשָׁע עַל יְרוּשָׁלַיִם וֶהֱבִיאָהּ בְּמָצוֹר וּבְמָצוֹק. וְי\"ז בְּתַמּוּז חֲמִשָּׁה דְּבָרִים אֵרְעוּ בּוֹ. נִשְׁתַּבְּרוּ הַלּוּחוֹת. וּבָטֵל הַתָּמִיד מִבַּיִת רִאשׁוֹן. וְהֻבְקְעָה יְרוּשָׁלַיִם בְּחֻרְבָּן שֵׁנִי. וְשָׂרַף אַפּוֹסְטוֹמוֹס הָרָשָׁע אֶת הַתּוֹרָה. וְהֶעֱמִיד צֶלֶם בַּהֵיכָל:","וְתִשְׁעָה בְּאָב חֲמִשָּׁה דְּבָרִים אֵרְעוּ בּוֹ. נִגְזַר עַל יִשְׂרָאֵל בַּמִּדְבָּר שֶׁלֹּא יִכָּנְסוּ לָאָרֶץ. וְחָרַב הַבַּיִת בָּרִאשׁוֹנָה וּבַשְּׁנִיָּה. וְנִלְכְּדָה עִיר גְּדוֹלָה וּבֵיתָר שְׁמָהּ וְהָיוּ בָּהּ אֲלָפִים וּרְבָבוֹת מִיִּשְׂרָאֵל וְהָיָה לָהֶם מֶלֶךְ גָּדוֹל וְדִמּוּ כָּל יִשְׂרָאֵל וּגְדוֹלֵי הַחֲכָמִים שֶׁהוּא הַמֶּלֶךְ הַמָּשִׁיחַ. וְנָפַל בְּיַד הָרוֹמִיִּים וְנֶהֶרְגוּ כֻּלָּם וְהָיְתָה צָרָה גְּדוֹלָה כְּמוֹ חֻרְבַּן בֵּית הַמִּקְדָּשׁ. וּבוֹ בַּיּוֹם הַמּוּכָן לְפֻרְעָנוּת חָרַשׁ טוּרְנוּסְרוּפוּס הָרָשָׁע אֶת הַהֵיכָל וְאֶת סְבִיבָיו לְקַיֵּם מַה שֶּׁנֶּאֱמַר(ירמיה כו יח) (מיכה ג יב) \"צִיּוֹן שָׂדֶה תֵחָרֵשׁ\":","וְאַרְבָּעָה יְמֵי הַצּוֹמוֹת הָאֵלּוּ הֲרֵי הֵן מְפֹרָשִׁין בַּקַּבָּלָה (זכריה ח יט) \"צוֹם הָרְבִיעִי וְצוֹם הַחֲמִישִׁי\" וְגוֹ'. צוֹם הָרְבִיעִי זֶה שִׁבְעָה עָשָׂר בְּתַמּוּז שֶׁהוּא בַּחֹדֶשׁ הָרְבִיעִי. וְצוֹם הַחֲמִישִׁי זֶה תִּשְׁעָה בְּאָב שֶׁהוּא בַּחֹדֶשׁ הַחֲמִישִׁי. וְצוֹם הַשְּׁבִיעִי זֶה שְׁלֹשָׁה בְּתִשְׁרֵי שֶׁהוּא בַּחֹדֶשׁ הַשְּׁבִיעִי. וְצוֹם הָעֲשִׂירִי זֶה עֲשָׂרָה בְּטֵבֵת שֶׁהוּא בַּחֹדֶשׁ הָעֲשִׂירִי:","וְנָהֲגוּ כָּל יִשְׂרָאֵל בִּזְמַנִּים אֵלּוּ לְהִתְעַנּוֹת. וּבְי\"ג בַּאֲדָר זֵכֶר לַתַּעֲנִית שֶׁהִתְעַנּוּ בִּימֵי הָמָן שֶׁנֶּאֱמַר (אסתר ט לא) \"דִּבְרֵי הַצֹּמוֹת וְזַעֲקָתָם\". וְאִם חָל י\"ג בַּאֲדָר לִהְיוֹת בְּשַׁבָּת מַקְדִּימִין וּמִתְעַנִּין בַּחֲמִישִׁי שֶׁהוּא י\"א. אֲבָל אֶחָד מֵאַרְבָּעָה יְמֵי הַצּוֹמוֹת שֶׁחָל לִהְיוֹת בְּשַׁבָּת דּוֹחִין אוֹתוֹ לְאַחַר הַשַּׁבָּת. חָל לִהְיוֹת בְּעֶרֶב שַׁבָּת מִתְעַנִּין בְּעֶרֶב שַׁבָּת. וּבְכָל הַצּוֹמוֹת הָאֵלּוּ אֵין מַתְרִיעִין וְלֹא מִתְפַּלְּלִין בָּהֶן תְּפִלַּת נְעִילָה. אֲבָל קוֹרִין בַּתּוֹרָה שַׁחֲרִית וּמִנְחָה בְּ(שמות לב יא) \"וַיְחַל משֶׁה\". וּבְכֻלָּן אוֹכְלִים וְשׁוֹתִין בַּלַּיְלָה חוּץ מִתִּשְׁעָה בְּאָב:","מִשֶּׁיִּכָּנֵס אָב מְמַעֲטִין בְּשִׂמְחָה. וְשַׁבָּת שֶׁחָל תִּשְׁעָה בְּאָב לִהְיוֹת בְּתוֹכָהּ אָסוּר לְסַפֵּר וּלְכַבֵּס וְלִלְבּשׁ כְּלִי מְגֹהָץ אֲפִלּוּ כְּלִי פִּשְׁתָּן עַד שֶׁיַּעֲבֹר הַתַּעֲנִית. וַאֲפִלּוּ לְכַבֵּס וּלְהַנִּיחַ לְאַחַר הַתַּעֲנִית אָסוּר. וּכְבָר נָהֲגוּ יִשְׂרָאֵל שֶׁלֹּא לֶאֱכל בָּשָׂר בְּשַׁבָּת זוֹ וְלֹא יִכָּנְסוּ לַמֶּרְחָץ עַד שֶׁיַּעֲבֹר הַתַּעֲנִית. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ לְבַטֵּל הַשְּׁחִיטָה מֵרֹאשׁ הַחֹדֶשׁ עַד הַתַּעֲנִית:","תִּשְׁעָה בְּאָב לֵילוֹ כְּיוֹמוֹ לְכָל דָּבָר. וְאֵין אוֹכְלִין אֶלָּא מִבְּעוֹד יוֹם. וּבֵין הַשְּׁמָשׁוֹת שֶׁלּוֹ אָסוּר כְּיוֹם הַכִּפּוּרִים. וְלֹא יֹאכַל בָּשָׂר וְלֹא יִשְׁתֶּה יַיִן בַּסְּעֻדָּה הַמַּפְסִיק בָּהּ. אֲבָל שׁוֹתֶה הוּא יַיִן מִגִּתּוֹ שֶׁיֵּשׁ לוֹ שְׁלֹשָׁה יָמִים אוֹ פָּחוֹת. וְאוֹכֵל בָּשָׂר מָלִיחַ שֶׁיֵּשׁ לוֹ שְׁלֹשָׁה יָמִים אוֹ יֶתֶר. וְלֹא יֹאכַל שְׁנֵי תַּבְשִׁילִין:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאָכַל עֶרֶב תִּשְׁעָה בְּאָב אַחַר חֲצוֹת. אֲבָל אִם סָעַד קֹדֶם חֲצוֹת אַף עַל פִּי שֶׁהוּא מַפְסִיק בָּהּ אוֹכֵל כָּל מַה שֶּׁיִּרְצֶה. וְעֶרֶב תִּשְׁעָה בְּאָב שֶׁחָל לִהְיוֹת בְּשַׁבָּת אוֹכֵל וְשׁוֹתֶה כָּל צָרְכּוֹ וּמַעֲלֶה עַל שֻׁלְחָנוֹ אֲפִלּוּ כִּסְעֻדַּת שְׁלֹמֹה. וְכֵן תִּשְׁעָה בְּאָב עַצְמוֹ שֶׁחָל לִהְיוֹת בְּשַׁבָּת אֵינוֹ מְחַסֵּר כְּלוּם:","זוֹ הִיא מִדַּת כָּל הָעָם שֶׁאֵינָן יְכוֹלִין לִסְבּל יֶתֶר מִדַּאי. אֲבָל חֲסִידִים הָרִאשׁוֹנִים כָּךְ הָיְתָה מִדָּתָן. עֶרֶב תִּשְׁעָה בְּאָב הָיוּ מְבִיאִין לוֹ לָאָדָם לְבַדּוֹ פַּת חֲרֵבָה בְּמֶלַח וְשׁוֹרֶה בְּמַיִם וְיוֹשֵׁב בֵּין תַּנּוּר וְכִירַיִם וְאוֹכְלָהּ וְשׁוֹתֶה עָלֶיהָ קִיתוֹן שֶׁל מַיִם בִּדְאָגָה וּבְשִׁמָּמוֹן וּבְכִיָּה כְּמִי שֶׁמֵּתוֹ מֻטָּל לְפָנָיו. כָּזֶה רָאוּי לַחֲכָמִים לַעֲשׂוֹת אוֹ קָרוֹב מִזֶּה. וּמִיָּמֵינוּ לֹא אָכַלְנוּ עֶרֶב תִּשְׁעָה בְּאָב תַּבְשִׁיל אֲפִלּוּ שֶׁל עֲדָשִׁים אֶלָּא אִם כֵּן הָיָה בְּשַׁבָּת:","עֻבָּרוֹת וּמֵינִיקוֹת מִתְעַנּוֹת וּמַשְׁלִימוֹת בְּתִשְׁעָה בְּאָב. וְאָסוּר בִּרְחִיצָה בֵּין בְּחַמִּין בֵּין בְּצוֹנֵן וַאֲפִלּוּ לְהוֹשִׁיט אֶצְבָּעוֹ בְּמַיִם. וְאָסוּר בְּסִיכָה שֶׁל תַּעֲנוּג וּבִנְעִילַת הַסַּנְדָּל וּבְתַשְׁמִישׁ הַמִּטָּה כְּיוֹם הַכִּפּוּרִים. וּמָקוֹם שֶׁנָּהֲגוּ לַעֲשׂוֹת בּוֹ מְלָאכָה עוֹשִׂין. וּמָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא לַעֲשׂוֹת אֵין עוֹשִׂין. וּבְכָל מָקוֹם תַּלְמִידֵי חֲכָמִים בְּטֵלִין. וְאָמְרוּ חֲכָמִים שֶׁהָעוֹשֶׂה בּוֹ מְלָאכָה אֵינוֹ רוֹאֶה סִימַן בְּרָכָה לְעוֹלָם:","תַּלְמִידֵי חֲכָמִים אֵין נוֹתְנִין זֶה לָזֶה שָׁלוֹם בְּתִשְׁעָה בְּאָב. אֶלָּא יוֹשְׁבִים דָּוִים וְנֶאֱנָחִים כַּאֲבֵלִים. וְאִם נָתַן לָהֶם עַם הָאָרֶץ שָׁלוֹם מַחֲזִירִים לוֹ בְּשָׂפָה רָפָה וְכֹבֶד רֹאשׁ. וְאָסוּר לִקְרוֹת בְּתִשְׁעָה בְּאָב בַּתּוֹרָה אוֹ בַּנְּבִיאִים אוֹ בַּכְּתוּבִים וּבְמִשְׁנָה וּבַהֲלָכוֹת וּבִגְמָרָא וּבְהַגָּדוֹת. וְאֵינוֹ קוֹרֵא אֶלָּא בְּאִיּוֹב וּבְקִינוֹת וּבַדְּבָרִים הָרָעִים שֶׁבְּיִרְמְיָהוּ. וְתִינוֹקוֹת שֶׁל בֵּית רַבָּן בְּטֵלִין בּוֹ. וּמִקְצָת הַחֲכָמִים נוֹהֲגִין שֶׁלֹּא לְהַנִּיחַ בּוֹ תְּפִלִּין שֶׁל רֹאשׁ:","מִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ תִּקְּנוּ חֲכָמִים שֶׁהָיוּ בְּאוֹתוֹ הַדּוֹר שֶׁאֵין בּוֹנִין לְעוֹלָם בִּנְיָן מְסֻיָּד וּמְכֻיָּר כְּבִנְיַן הַמְּלָכִים. אֶלָּא טָח בֵּיתוֹ בְּטִיט וְסָד בְּסִיד וּמְשַׁיֵּר מָקוֹם אַמָּה עַל אַמָּה כְּנֶגֶד הַפֶּתַח בְּלֹא סִיד. וְהַלּוֹקֵחַ חָצֵר מְסֻיֶּדֶת וּמְכֻיֶּרֶת הֲרֵי זוֹ בְּחֶזְקָתָהּ וְאֵין מְחַיְּבִים אוֹתוֹ לִקְלֹף הַכְּתָלִים:","וְכֵן הִתְקִינוּ שֶׁהָעוֹרֵךְ שֻׁלְחָן לַעֲשׂוֹת סְעֻדָּה לָאוֹרְחִים מְחַסֵּר מִמֶּנּוּ מְעַט וּמַנִּיחַ מָקוֹם פָּנוּי בְּלֹא קְעָרָה מִן הַקְּעָרוֹת הָרְאוּיוֹת לָתֵת שָׁם. וּכְשֶׁהָאִשָּׁה עוֹשָׂה תַּכְשִׁיטֵי הַכֶּסֶף וְהַזָּהָב מְשַׁיֶּרֶת מִין מִמִּינֵי הַתַּכְשִׁיט שֶׁנּוֹהֶגֶת בָּהֶן כְּדֵי שֶׁלֹּא יִהְיֶה תַּכְשִׁיט שָׁלֵם. וּכְשֶׁהֶחָתָן נוֹשֵׂא אִשָּׁה לוֹקֵחַ אֵפֶר מַקְלֶה וְנוֹתֵן בְּרֹאשׁוֹ מְקוֹם הֲנָחַת הַתְּפִלִּין. וְכָל אֵלּוּ הַדְּבָרִים כְּדֵי לִזְכֹּר יְרוּשָׁלַיִם שֶׁנֶּאֱמַר (תהילים קלז ה) \"אִם אֶשְׁכָּחֵךְ יְרוּשָׁלָםִ תִּשְׁכַּח יְמִינִי\" (תהילים קלז ו) \"תִּדְבַּק לְשׁוֹנִי לְחִכִּי אִם לֹא אֶזְכְּרֵכִי אִם לֹא אַעֲלֶה אֶת יְרוּשָׁלַםִ עַל רֹאשׁ שִׂמְחָתִי\":","וְכֵן גָּזְרוּ שֶׁלֹּא לְנַגֵּן בִּכְלֵי שִׁיר. וְכָל מִינֵי זֶמֶר וְכָל מַשְׁמִיעֵי קוֹל שֶׁל שִׁיר אָסוּר לִשְׂמֹחַ בָּהֶן וְאָסוּר לְשָׁמְעָן מִפְּנֵי הַחֻרְבָּן. וַאֲפִלּוּ שִׁירָה בַּפֶּה עַל הַיַּיִן אֲסוּרָה שֶׁנֶּאֱמַר (ישעיה כד ט) \"בַּשִּׁיר לֹא יִשְׁתּוּ יָיִן\". וּכְבָר נָהֲגוּ כָּל יִשְׂרָאֵל לוֹמַר דִּבְרֵי תֻּשְׁבָּחוֹת אוֹ שִׁיר שֶׁל הוֹדָאוֹת לָאֵל וְכַיּוֹצֵא בָּהֶן עַל הַיַּיִן:","וְאַחַר כָּךְ גָּזְרוּ עַל עַטְרוֹת חֲתָנִים שֶׁלֹּא לְהַנִּיחָם כְּלָל. וְשֶׁלֹּא יַנִּיחַ הֶחָתָן בְּרֹאשׁוֹ שׁוּם כָּלִיל שֶׁנֶּאֱמַר (יחזקאל כא לא) \"הָסֵר הַמִּצְנֶפֶת וְהָרֵם הָעֲטָרָה\". וְכֵן גָּזְרוּ עַל עַטְרוֹת כַּלּוֹת אִם הָיָה שֶׁל כֶּסֶף אוֹ זָהָב אֲבָל שֶׁל גְּדִיל מֻתָּר לְכַלָּה:","מִי שֶׁרָאָה עָרֵי יְהוּדָה בְּחֻרְבָּנָם אוֹמֵר (ישעיה סד ט) \"עָרֵי קָדְשְׁךָ הָיוּ מִדְבָּר\" וְקוֹרֵעַ. רָאָה יְרוּשָׁלַיִם בְּחֻרְבָּנָהּ אוֹמֵר (ישעיה סד ט) \"יְרוּשָׁלַיִם מִדְבָּר\" וְגוֹ'. בֵּית הַמִּקְדָּשׁ בְּחֻרְבָּנוֹ אוֹמֵר (ישעיה סד י) \"בֵּית קָדְשֵׁנוּ וְתִפְאַרְתֵּנוּ\" וְגוֹ' וְקוֹרֵעַ. וּמֵהֵיכָן חַיָּב לִקְרֹעַ מִן הַצּוֹפִים. וּכְשֶׁיַּגִּיעַ לַמִּקְדָּשׁ קוֹרֵעַ קֶרַע אַחֵר. וְאִם פָּגַע בַּמִּקְדָּשׁ תְּחִלָּה כְּשֶּׁיָּבוֹא מִדֶּרֶךְ הַמִּדְבָּר קוֹרֵעַ עַל הַמִּקְדָּשׁ וּמוֹסִיף עַל יְרוּשָׁלַיִם:","כָּל הַקְּרָעִים הָאֵלּוּ כֻּלָּם קוֹרֵעַ בְּיָדוֹ מְעֵמָּד וְקוֹרֵעַ כָּל כְּסוּת שֶׁעָלָיו עַד שֶׁיְּגַלֶּה אֶת לִבּוֹ. וְאֵינוֹ מְאַחֶה קְרָעִים אֵלּוּ לְעוֹלָם. אֲבָל רַשַּׁאי הוּא לְשָׁלְלָן לְמָלְלָן לְלַקְּטָן וּלְתָפְרָן כְּמִין סֻלָּמוֹת:","הָיָה הוֹלֵךְ וּבָא לִירוּשָׁלַיִם הוֹלֵךְ וּבָא תּוֹךְ שְׁלֹשִׁים יוֹם אֵינוֹ קוֹרֵעַ קֶרַע אַחֵר. וְאִם לְאַחַר שְׁלֹשִׁים יוֹם חוֹזֵר וְקוֹרֵעַ:","כָּל הַצּוֹמוֹת הָאֵלּוּ עֲתִידִים לִבָּטֵל לִימוֹת הַמָּשִׁיחַ. וְלֹא עוֹד אֶלָּא שֶׁהֵם עֲתִידִים לִהְיוֹת יוֹם טוֹב וִימֵי שָׂשׂוֹן וְשִׂמְחָה שֶׁנֶּאֱמַר (זכריה ח יט) \"כֹּה אָמַר ה' צְבָאוֹת צוֹם הָרְבִיעִי וְצוֹם הַחֲמִישִׁי וְצוֹם הַשְּׁבִיעִי וְצוֹם הָעֲשִׂירִי יִהְיֶה לְבֵית יְהוּדָה לְשָׂשׂוֹן וּלְשִׂמְחָה וּלְמֹעֲדִים טוֹבִים וְהָאֱמֶת וְהַשָּׁלוֹם אֱהָבוּ\": סָלִיק הִלְכוֹת תַּענִיוֹת"],"Mishneh Torah, First Fruits and other Gifts to Priests Outside the Sanctuary 6":["הַלוֹקֵחַ מִן הַנַּחְתּוֹם חַיָּב בְּחַלָּה. וּמַפְרִישׁ מִן הַחַמָּה עַל הַצּוֹנֶנֶת וּמִן הַצּוֹנֶנֶת עַל הַחַמָּה אֲפִלּוּ מִדְּפוּסִין הַרְבֵּה:","אֵין חַיָּבִין בְּחַלָּה אֶלָּא חֲמִשָּׁה מִינֵי תְּבוּאָה בִּלְבַד וְהֵם הַחִטִּין וְהַשְּׂעוֹרִים וְהַכֻּסְּמִין וְשִׁבּלֶת שׁוּעָל וְהַשִּׁיפוֹן שֶׁנֶּאֱמַר (במדבר טו יט) \"בַּאֲכָלְכֶם מִלֶּחֶם הָאָרֶץ\". וְאֵין קָרוּי לֶחֶם אֶלָּא פַּת הַנַּעֲשֵׂית מֵאֵלּוּ אֲבָל הָעוֹשֶׂה פַּת אֹרֶז אוֹ דֹּחַן וְכַיּוֹצֵא בָּהֶן מִן הַקִּטְנִיּוֹת אֵינָן חַיָּבִין בְּחַלָּה כְּלָל:","הַלֶּקֶט וְהַשִּׁכְחָה וְהַפֵּאָה וְהַהֶפְקֵר וּתְבוּאָה שֶׁלֹּא הֵבִיאָה שְׁלִישׁ אַף עַל פִּי שֶׁהֵן פְּטוּרִין מִן הַתְּרוּמָה חַיָּבִין עָלֶיהָ בְּחַלָּה. וְכֵן מַעֲשֵׂר רִאשׁוֹן שֶׁהִקְדִּימוֹ בַּשִּׁבֳּלִים שֶׁנִּטְּלָה תְּרוּמָתוֹ אַף עַל פִּי שֶׁיֵּשׁ בּוֹ חֵלֶק תְּרוּמָה גְּדוֹלָה וּמַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁנִּפְדּוּ וּמוֹתַר הָעֹמֶר וּשְׁתֵּי הַלֶּחֶם וְלֶחֶם הַפָּנִים כְּשֶׁיִּפָּדוּ כָּל אוֹתָן הַמּוֹתָרוֹת הַכּל חַיָּבִין בְּחַלָּה:","עִסָּה שֶׁל מַעֲשֵׂר שֵׁנִי בִּירוּשָׁלַיִם וְעִסַּת שְׁבִיעִית וּסְפֵק מְדֻמָּע חַיָּבִין בְּחַלָּה. אֲבָל הַמְדֻמָּע פָּטוּר מִן הַחַלָּה:","חַלּוֹת תּוֹדָה וּרְקִיקֵי נָזִיר עֲשָׂאָן לְעַצְמוֹ פְּטוּרִין מִן הַחַלָּה מִפְּנֵי שֶׁהֵן קֹדֶשׁ. לְמָכְרָן בַּשּׁוּק לִנְזִירִים וּלְמַקְרִיבֵי תּוֹדָה חַיָּבִין בְּחַלָּה. לְפִי שֶׁבְּדַעְתּוֹ שֶׁאִם לֹא תִּמָּכֵר יֹאכְלֶנָּה:","עִסַּת הַשֻּׁתָּפִין וְהָעוֹשֶׂה עִסָּה לְרַבִּים חַיֶּבֶת בְּחַלָּה:","הָעוֹשֶׂה עִסָּה מִן הַטֶּבֶל. בֵּין שֶׁהִקְדִּים חַלָּה לִתְרוּמָה בֵּין שֶׁהִקְדִּים תְּרוּמָה לְחַלָּה מַה שֶּׁעָשָׂה עָשׂוּי. וְאִם הִפְרִישׁ הַחַלָּה תְּחִלָּה לֹא תֵּאָכֵל עַד שֶׁיּוֹצִיא עָלֶיהָ תְּרוּמָה וּתְרוּמַת מַעֲשֵׂר. וְאִם הִפְרִישׁ תְּחִלָּה תְּרוּמָה לֹא תֵּאָכֵל עַד שֶׁיּוֹצִיא עָלֶיהָ חַלָּה:","הָעוֹשֶׂה עִסָּה לְהַאֲכִיל הַפַּת שֶׁלָּהּ לִבְהֵמָה אוֹ לְחַיָּה פְּטוּרָה. עִסַּת הַכְּלָבִים בִּזְמַן שֶׁהָרוֹעִים אוֹכְלִין מִמֶּנָּה חַיֶּבֶת בְּחַלָּה. עִסַּת הָעַכּוּ\"ם פְּטוּרָה:","הָיוּ יִשְׂרָאֵל וְעַכּוּ\"ם שֻׁתָּפִין בָּעִסָּה אִם הָיָה בְּחֵלֶק יִשְׂרָאֵל שִׁעוּר עִסָּה הַחַיֶּבֶת בְּחַלָּה הֲרֵי זוֹ חַיֶּבֶת בְּחַלָּה:","עַכּוּ\"ם שֶׁהִפְרִישׁ חַלָּה אֲפִלּוּ בְּאֶרֶץ יִשְׂרָאֵל אֵינָהּ חַלָּה. אֶלָּא מוֹדִיעִין אוֹתוֹ שֶׁאֵינוֹ צָרִיךְ וְתֵאָכֵל לְזָר. וְלָמָּה לֹא חָשַׁשְׁנוּ לָהּ שֶׁמָּא עִסָּה שֶׁל יִשְׂרָאֵל הִיא וְתָלָה אוֹתָהּ בְּיַד עַכּוּ\"ם וּכְדֵי לְפָטְרָהּ. שֶׁאִם יִרְצֶה יִשְׂרָאֵל יִפְטֹר עַצְמוֹ וְיַעֲשֶׂה יִשְׂרָאֵל עִסָּתוֹ פָּחוֹת מִשִּׁעוּר חַלָּה:","הַמְעָרֵב קֶמַח חִטִּין וְקֶמַח אֹרֶז וְעָשָׂה מֵהֶן עִסָּה אִם יֵשׁ בָּהּ טַעַם דָּגָן חַיֶּבֶת בְּחַלָּה וְאִם לָאו פְּטוּרָה. אֲפִלּוּ הָיָה הַשְּׂאוֹר חִטִּים לְתוֹךְ עִסַּת אֹרֶז. אִם יֵשׁ בָּהּ טַעַם דָּגָן חַיֶּבֶת בְּחַלָּה וְאִם לָאו פְּטוּרָה:","עִסָּה שֶׁנִּלּוֹשָׁה בְּיַיִן אוֹ שֶׁמֶן אוֹ דְּבַשׁ אוֹ מַיִם רוֹתְחִים אוֹ שֶׁנָּתַן לְתוֹכָהּ תַּבְלִין אוֹ הִרְתִּיחַ הַמַּיִם וְהִשְׁלִיךְ הַקֶּמַח לְתוֹכוֹ וְלָשׁוֹ. אִם אֲפָאָהּ בֵּין בְּתַנּוּר בֵּין בְּקַרְקַע בֵּין עַל הַמַּחֲבַת וְהַמַּרְחֶשֶׁת. בֵּין שֶׁהִדְבִּיק אֶת הַבָּצֵק בְּמַחֲבַת וּבְמַרְחֶשֶׁת וְאַחַר כָּךְ הִרְתִּיחָן בָּאֵשׁ מִלְּמַטָּה עַד שֶׁנֶּאֱפֵית הַפַּת. בֵּין שֶׁהִרְתִּיחָהּ וְאַחַר כָּךְ הִדְבִּיק הַבָּצֵק. כָּל אֵלּוּ חַיָּבִין בְּחַלָּה. אֲבָל הָעוֹשֶׂה עִסָּה לְיַבְּשָׁהּ בַּחַמָּה בִּלְבַד אוֹ לְבַשְּׁלָהּ בִּקְדֵרָה הֲרֵי הִיא פְּטוּרָה מִן הַחַלָּה שֶׁאֵין מַעֲשֵׂה חַמָּה לֶחֶם בֵּין שֶׁלָּשָׁהּ בְּמַיִם בֵּין שֶׁלָּשָׁהּ בִּשְׁאָר מַשְׁקִין. וְכֵן קָלִי שֶׁלָּשִׁין אוֹתוֹ בְּמַיִם אוֹ בִּדְבַשׁ וְאוֹכְלִין אוֹתוֹ בְּלֹא אֲפִיָּה פָּטוּר שֶׁאֵין חַיֶּבֶת אֶלָּא עִסָּה שֶׁסּוֹפָהּ לְהֵאָפוֹת לֶחֶם לְמַאֲכַל אָדָם:","עִסָּה שֶׁלָּשָׁהּ תְּחִלָּה לַעֲשׂוֹתָהּ מַעֲשֵׂה חַמָּה וְהִשְׁלִימָהּ לַעֲשׂוֹתָהּ פַּת. אוֹ שֶׁהִתְחִיל בָּהּ לֶאֱפוֹת פַּת וְהִשְׁלִימָהּ לַעֲשׂוֹת מַעֲשֵׂה חַמָּה. וְכֵן קָלִי שֶׁלָּשׁוֹ לֶאֱפוֹתוֹ פַּת חַיָּבִין בְּחַלָּה:","לֶחֶם הֶעָשׂוּי לְכוּתָח מַעֲשֶׂיהָ מוֹכִיחִין עָלֶיהָ. עֲשָׂאָהּ כְּעָכִין חַיֶּבֶת בְּחַלָּה. עֲשָׂאָהּ כְּלִמּוּדִין פְּטוּרָה מִן הַחַלָּה:","כַּמָּה שִׁעוּר הָעִסָּה שֶׁחַיֶּבֶת בְּחַלָּה. מְלֹא הָעֹמֶר קֶמַח בֵּין מֵאֶחָד מֵחֲמִשָּׁה מִינִים בֵּין מֵחֲמִשְׁתָּן כֻּלָּם מִצְטָרְפִין לְשִׁעוּר. וְכַמָּה הוּא שִׁעוּר הָעֹמֶר שְׁנֵי קַבִּין פָּחוֹת חֹמֶשׁ. וְהַקַּב אַרְבָּעָה לוֹגִין. וְהַלּוֹג אַרְבַּע רְבִיעִיּוֹת וְהָרְבִיעִית אֶצְבָּעַיִם עַל אֶצְבָּעַיִם בְּרוּם אֶצְבָּעַיִם וַחֲצִי אֶצְבַּע וְחֹמֶשׁ אֶצְבַּע. וְכָל הָאֶצְבָּעוֹת הֵם רֹחַב גוּדָל אֶצְבָּעוֹת שֶׁל יָד. נִמְצֵאתָ לָמֵד שֶׁהַמִּדָּה שֶׁיֵּשׁ בָּהּ עֶשֶׂר אֶצְבָּעוֹת עַל עֶשֶׂר אֶצְבָּעוֹת בְּרוּם שָׁלֹשׁ אֶצְבָּעוֹת וּתְשִׁעַ אֶצְבַּע בְּקֵרוּב הוּא הָעֹמֶר. וְכֵן מִדָּה שֶׁיֵּשׁ בָּהּ שֶׁבַע אֶצְבָּעוֹת פָּחוֹת שְׁנֵי תְּשִׁיעֵי אֶצְבַּע עַל שֶׁבַע אֶצְבָּעוֹת פָּחוֹת שְׁנֵי תְּשִׁיעֵי אֶצְבַּע בְּרוּם שֶׁבַע אֶצְבָּעוֹת פָּחוֹת שְׁנֵי תְּשִׁיעֵי אֶצְבַּע הִיא מִדַּת הָעֹמֶר. וּשְׁתֵּי הַמִּדּוֹת כְּאֶחָד הֵם עוֹלִים. וְכַמָּה מְכִילָה מִדָּה זוֹ כְּמוֹ אַרְבָּעִים וְשָׁלֹשׁ בֵּיצִים בֵּינוֹנִיּוֹת וְחֹמֶשׁ בֵּיצָה וְהֵם מִשְׁקַל שִׁשָּׁה וּשְׁמוֹנִים סְלָעִים וּשְׁנֵי שְׁלִישֵׁי סֶלַע מִקֶּמַח הַחִטִּים שֶׁבְּמִצְרַיִם. שֶׁהֵם מִשְׁקַל חֲמֵשׁ מֵאוֹת וְעֶשְׂרִים זוּז מִזּוּזֵי מִצְרַיִם בַּזְּמַן הַזֶּה. וּמִדָּה שֶׁמְּכִילָה כַּמִּשְׁקָל הַזֶּה מִקֶּמַח הַחִטִּים הַזֶּה בָּהּ מוֹדְדִין לְחַלָּה בְּכָל מָקוֹם:","אָסוּר לְאָדָם לַעֲשׂוֹת עִסָּתוֹ פָּחוֹת פָּחוֹת מִכַּשִּׁעוּר כְּדֵי לְפָטְרָהּ מִן הַחַלָּה. וְהַמַּפְרִישׁ חַלָּה מֵעִסָּה שֶׁהִיא פְּחוּתָה מִכַּשִּׁעוּר לֹא עָשָׂה כְּלוּם וַהֲרֵי הִיא חֻלִּין כְּשֶׁהָיְתָה. עָשָׂה עִסָּה פְּחוּתָה מִכַּשִּׁעוּר וַאֲפָאָהּ וְנָתַן הַפַּת לַסַּל. וְחָזַר וְאָפָה פַּת אַחֶרֶת וְנָתַן לַסַּל אִם נִתְקַבֵּץ בַּסַּל שִׁעוּר חַלָּה הַסַּל מְצָרְפָן לְחַלָּה וּמַפְרֵשׁ הַחַלָּה מִן הַפַּת. שֶׁנֶּאֱמַר (במדבר טו יט) \"וְהָיָה בַּאֲכָלְכֶם מִלֶּחֶם הָאָרֶץ\" מְלַמֵּד שֶׁהוּא מַפְרִישׁ מִן הָאָפוּי. וְאֵין הַתַּנּוּר מְצָרְפָן לְחַלָּה:","הָיוּ הַכִּכָּרוֹת נוֹשְׁכוֹת זוֹ בְּזוֹ וְנִתְקַבֵּץ מִן הַכּל שִׁעוּר חַלָּה חַיָּבִין בְּחַלָּה אַף עַל פִּי שֶׁאֵינָן בַּסַּל. אָפָה מְעַט מְעַט וְקִבֵּץ הַכּל עַל לוּחַ שֶׁאֵין לוֹ תּוֹךְ הֲרֵי זֶה סָפֵק. וְאִם חַלָּה שֶׁל דִּבְרֵיהֶם הִיא אֵינוֹ חַיָּב לְהַפְרִישׁ עַד שֶׁיְּצָרֵף אוֹתוֹ כְּלִי שֶׁיֵּשׁ לוֹ תּוֹךְ:","קֶמַח שֶׁלֹּא רִקְּדּוֹ אֶלָּא לָשׁוֹ בַּסֻּבִּין שֶׁלּוֹ. הוֹאִיל וְיֵשׁ בְּכָל הַקֶּמַח עֹמֶר חַיָּב בְּחַלָּה. אֲבָל אִם נָטַל הַמֻּרְסָן מִן הַקֶּמַח וְחָזַר וְהִשְׁלִים שִׁעוּר הָעִסָּה בַּמֻּרְסָן שֶׁהֶחֱזִירוֹ לַקֶּמַח אֵינוֹ חַיָּב בְּחַלָּה:","נַחְתּוֹם שֶׁעָשָׂה עִסָּה לַעֲשׂוֹתָהּ שְׂאוֹר לְחַלְּקָהּ חַיֶּבֶת בְּחַלָּה. שֶׁאִם לֹא תִּמָּכֵר יַעֲשֶׂנָּה פַּת. אֲבָל הָעוֹשֶׂה עִסָּה לְחַלְּקָהּ בָּצֵק פְּטוּרָה:","נָשִׁים שֶׁנָּתְנוּ קֶמַח לְנַחְתּוֹם לַעֲשׂוֹת לָהֶם שְׂאוֹר. אִם אֵין בְּשֶׁל אַחַת מֵהֶן כַּשִּׁעוּר אַף עַל פִּי שֶׁיֵּשׁ בִּכְלָלָן כַּשִּׁעוּר פְּטוּרָה:"],"Mishneh Torah, Forbidden Foods 1":["מִצְוַת עֲשֵׂה לֵידַע הַסִּימָנִין שֶׁמַּבְדִּילִין בָּהֶן בֵּין בְּהֵמָה וְחַיָּה וְעוֹף וְדָגִים וַחֲגָבִים שֶׁמֻּתָּר לְאָכְלָן וּבֵין שֶׁאֵין מֻתָּר לְאָכְלָן שֶׁנֶּאֱמַר (ויקרא כ כה) \"וְהִבְדַּלְתֶּם בֵּין הַבְּהֵמָה הַטְּהֹרָה לַטְּמֵאָה וּבֵין הָעוֹף הַטָּמֵא לַטָּהֹר\". וְנֶאֱמַר (ויקרא יא מז) \"לְהַבְדִּיל בֵּין הַטָּמֵא וּבֵין הַטָּהֹר וּבֵין הַחַיָּה הַנֶּאֱכֶלֶת וּבֵין הַחַיָּה אֲשֶׁר לֹא תֵאָכֵל\":","סִימָנֵי בְּהֵמָה וְחַיָּה נִתְפָּרְשׁוּ בַּתּוֹרָה וְהֵם שְׁנֵי סִימָנִין (ויקרא יא ג) (דברים יד ו) \"מַפְרֶסֶת פַּרְסָה\" וּ (ויקרא יא ג) (דברים יד ו) \"מַעֲלַת גֵּרָה\" עַד שֶׁיִּהְיוּ שְׁנֵיהֶם. וְכָל בְּהֵמָה וְחַיָּה שֶׁהִיא מַעֲלַת גֵּרָה אֵין לָהּ שִׁנַּיִם בַּלְּחִי הָעֶלְיוֹן. וְכָל בְּהֵמָה שֶׁהִיא מַעֲלַת גֵּרָה הֲרֵי הִיא מַפְרֶסֶת פַּרְסָה. חוּץ מִן הַגָּמָל. וְכָל בְּהֵמָה שֶׁהִיא מַפְרֶסֶת פַּרְסָה הִיא מַעֲלַת גֵּרָה חוּץ מִן הַחֲזִיר:","לְפִיכָךְ הַמּוֹצֵא בְּהֵמָה בַּמִּדְבָּר וְאֵינוֹ מַכִּירָהּ וּמְצָאָהּ חֲתוּכַת הַפְּרָסוֹת בּוֹדֵק בְּפִיהָ אִם אֵין לָהּ שִׁנַּיִם לְמַעְלָה בְּיָדוּעַ שֶׁהִיא טְהוֹרָה. וְהוּא שֶׁיַּכִּיר גָּמָל. מָצָא בְּהֵמָה שֶׁפִּיהָ חָתוּךְ בּוֹדֵק בְּפַרְסוֹתֶיהָ אִם הִיא שְׁסוּעָה טְהוֹרָה. וְהוּא שֶׁיַּכִּיר חֲזִיר. מָצָא פִּיהָ חָתוּךְ וְרַגְלֶיהָ חֲתוּכוֹת בּוֹדֵק בָּהּ אַחַר שֶׁשְּׁחָטָהּ בְּכַנְפֵי הָעֹקֶץ אִם מָצָא בְּשָׂרָהּ שָׁם מַהֲלַךְ שְׁתִי וָעֵרֶב טְהוֹרָה. וְהוּא שֶׁיַּכִּיר עָרוֹד שֶׁכֵּן הוּא בְּשָׂרוֹ שְׁתִי וָעֵרֶב:","בְּהֵמָה טְהוֹרָה שֶׁיָּלְדָה כְּמִין בְּהֵמָה טְמֵאָה אַף עַל פִּי שֶׁאֵינוֹ מַפְרִיס פַּרְסָה וְלֹא מַעֲלֶה גֵּרָה אֶלָּא כְּמִין סוּס אוֹ חֲמוֹר לְכָל דָּבָר הֲרֵי זֶה מֻתָּר בַּאֲכִילָה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁיָּלְדָה לְפָנָיו. אֲבָל אִם הִנִּיחַ פָּרָה מְעֻבֶּרֶת בְּעֶדְרוֹ וּבָא וּמָצָא כְּמִין חֲזִיר כָּרוּךְ אַחֲרֶיהָ אַף עַל פִּי שֶׁהוּא יוֹנֵק מִמֶּנָּה הֲרֵי זֶה סָפֵק וְאָסוּר בַּאֲכִילָה. שֶׁמָּא מִן הַטֻּמְאָה נוֹלָד וְנִכְרָךְ אַחַר הַטְּהוֹרָה:","בְּהֵמָה טְמֵאָה שֶׁיָּלְדָה כְּמִין בְּהֵמָה טְהוֹרָה אַף עַל פִּי שֶׁהוּא מַפְרִיס פַּרְסָה וּמַעֲלֶה גֵּרָה וַהֲרֵי הוּא כְּמִין שׁוֹר לְכָל דָּבָר אוֹ כְּמִין שֶׂה הֲרֵי זֶה אָסוּר בַּאֲכִילָה. שֶׁהַגָּדֵל מִן הַטְּמֵאָה טָמֵא וּמִן הַטְּהוֹרָה טָהוֹר. (לְפִיכָךְ) דָּג טָמֵא שֶׁנִּמְצָא בִּמְעֵי דָּג טָהוֹר אָסוּר. וְדָג טָהוֹר הַנִּמְצָא בִּמְעֵי דָּג טָמֵא מֻתָּר לְפִי שֶׁאֵין גִּדּוּלָיו אֶלָּא בְּלָעוֹ:","בְּהֵמָה טְהוֹרָה שֶׁיָּלְדָה אוֹ שֶׁנִּמְצָא בָּהּ בְּרִיָּה שֶׁיֵּשׁ לָהּ שְׁתֵּי גַּבִּין וּשְׁתֵּי שְׁדָרוֹת אֲסוּרָה בַּאֲכִילָה. וְזוֹ הִיא הַשְּׁסוּעָה שֶׁנֶּאֶסְרָה בַּתּוֹרָה שֶׁנֶּאֱמַר (דברים יד ז) \"אֶת זֶה לֹא תֹאכְלוּ מִמַּעֲלֵי הַגֵּרָה וּמִמַּפְרִיסֵי הַפַּרְסָה הַשְּׁסוּעָה\" כְּלוֹמַר בְּרִיָּה שֶׁנּוֹלְדָה שְׁסוּעָה לִשְׁתֵּי בְּהֵמוֹת:","וְכֵן בְּהֵמָה שֶׁנִּמְצָא בָּהּ דְּמוּת עוֹף אַף עַל פִּי שֶׁהוּא עוֹף טָהוֹר הֲרֵי זֶה אָסוּר בַּאֲכִילָה. לֹא הֻתַּר מִן הַנִּמְצָא בַּבְּהֵמָה אֶלָּא מַה שֶּׁיֵּשׁ לוֹ פַּרְסָה:","אֵין לְךָ בְּכָל בְּהֵמָה וְחַיָּה שֶׁבָּעוֹלָם שֶׁמֻּתָּר בַּאֲכִילָה חוּץ מֵעֲשֶׂרֶת הַמִּינִין הַמְּנוּיִין בַּתּוֹרָה. שְׁלֹשָׁה מִינֵי בְּהֵמָה וְהֵם. שׁוֹר שֶׂה וְעֵז. וְשִׁבְעָה מִינֵי חַיָּה. אַיָּל וּצְבִי וְיַחְמוּר וְאַקּוֹ וְדִישֹׁן וּתְאוֹ וָזָמֶר. הֵם וּמִינֵיהֶן כְּגוֹן שׁוֹר הַבָּר וְהַמְּרִיא שֶׁהֵן מִמִּין הַשּׁוֹר. וְכָל הָעֲשָׂרָה מִינִין וּמִינֵיהֶם מַעֲלֶה גֵּרָה וּמַפְרִיס פַּרְסָה. לְפִיכָךְ מִי שֶׁהוּא מַכִּירָן אֵינוֹ צָרִיךְ לִבְדֹּק לֹא בַּפֶּה וְלֹא בָּרַגְלַיִם:","אַף עַל פִּי שֶׁכֻּלָּן מֻתָּרִין בַּאֲכִילָה צְרִיכִין אָנוּ לְהַבְדִּיל בֵּין בְּהֵמָה טְהוֹרָה וְחַיָּה טְהוֹרָה. שֶׁהַחַיָּה חֶלְבָּהּ מֻתָּר וְדָמָהּ טָעוּן כִּסּוּי וְהַבְּהֵמָה הַטְּהוֹרָה חֶלְבָּהּ בְּכָרֵת וְאֵין דָּמָהּ טָעוּן כִּסּוּי:","וְסִימָנֵי חַיָּה מִפִּי הַשְּׁמוּעָה הֵן. כָּל מִין שֶׁהוּא מַפְרִיס פַּרְסָה וּמַעֲלֶה גֵּרָה וְיֵשׁ לוֹ קַרְנַיִם מְפֻצָּלוֹת כְּגוֹן הָאַיָּל הֲרֵי זֶה חַיָּה טְהוֹרָה בְּוַדַּאי. וְכָל שֶׁאֵין קַרְנָיו מְפֻצָּלוֹת אִם הָיוּ קַרְנָיו כְּרוּכוֹת כְּקַרְנֵי הַשּׁוֹר וַחֲרוּקוֹת כְּקַרְנֵי הָעֵז וְיִהְיֶה הֶחָרָק מֻבְלָע בָּהֶן וַהֲדוּרוֹת כְּקַרְנֵי הַצְּבִי הֲרֵי זוֹ חַיָּה טְהוֹרָה. וּבִלְבַד שֶׁיִּהְיֶה בַּקַּרְנַיִם שְׁלֹשָׁה סִימָנִין אֵלּוּ כְּרוּכוֹת חֲרוּקוֹת וַהֲדוּרוֹת:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּמִין שֶׁאֵינוֹ מַכִּירוֹ אֲבָל שִׁבְעָה מִינֵי חַיָּה הָאֲמוּרִין בַּתּוֹרָה אִם הָיָה מַכִּיר אוֹתָן אֲפִלּוּ לֹא מָצָא לוֹ קַרְנַיִם הֲרֵי זֶה אוֹכֵל חֶלְבּוֹ וְחַיָּב לְכַסּוֹת דָּמוֹ:","שׁוֹר הַבָּר מִין בְּהֵמָה הוּא וְהַקֶּרֶשׁ אַף עַל פִּי שֶׁאֵין לוֹ אֶלָּא קֶרֶן אַחַת הֲרֵי הוּא חַיָּה. וְכָל שֶׁיִּסְתַּפֵּק לְךָ אִם הוּא מִין חַיָּה אוֹ מִין בְּהֵמָה חֶלְבּוֹ אָסוּר וְאֵין לוֹקִין עָלָיו וּמְכַסִּין אֶת דָּמוֹ:","כִּלְאַיִם הַבָּא מִבְּהֵמָה טְהוֹרָה עִם חַיָּה טְהוֹרָה הוּא הַנִּקְרָא כְּוִי. חֶלְבּוֹ אָסוּר וְאֵין לוֹקִין עָלָיו וּמְכַסִּין אֶת דָּמוֹ. וְאֵין מִין טָמֵא מִתְעַבֵּר מִמִּין טָהוֹר כְּלָל:","סִימָנֵי עוֹף טָהוֹר לֹא נִתְפָּרֵשׁ מִן הַתּוֹרָה. אֶלָּא מָנָה מִנְיַן טְמֵאִים בִּלְבַד וּשְׁאָר מִינֵי הָעוֹף מֻתָּרִין. וְהַמִּנְיָן הָאֲסוּרִין אַרְבָּעָה וְעֶשְׂרִים הֵן. וְאֵלּוּ הֵן. א) נֶשֶׁר. ב) פֶּרֶס. ג) עָזְנִיָּה. ד) דָּאָה וְהִיא הָרָאָה הָאֲמוּרָה בְּמִשְׁנֵה תּוֹרָה. ה) אַיָּה וְהִיא הַדַּיָּהּ הָאֲמוּרָה בְּמִשְׁנֵה תּוֹרָה. ו) מִין הָאַיָּה שֶׁכֵּן כָּתוּב בָּהּ לְמִינָהּ מִכְלַל שֶׁהוּא שְׁנֵי מִינִין. ז) עוֹרֵב. ח) זַרְזִיר שֶׁכֵּן נֶאֱמַר בְּעוֹרֵב לְמִינוֹ לְהָבִיא אֶת הַזַּרְזִיר. ט) יַעֲנָה. י) תַּחְמָס. יא) שַׁחַף. יב) נֵץ. יג) וְשַׁרְנְקָא וְהוּא מִין הַנֵּץ שֶׁכֵּן כָּתוּב בּוֹ לְמִינֵהוּ. יד) כּוֹס. טו) שָׁלָךְ. טז) יַנְשׁוּף. יז) תִּנְשֶׁמֶת. יח) קָאָת. יט) רָחָמָה. כ) חֲסִידָה. כא) הָאֲנָפָה. כב) מִין הָאֲנָפָה שֶׁכֵּן נֶאֱמַר בָּהּ לְמִינָהּ. כג) הַדּוּכִיפַת. כד) הָעֲטַלֵּף:","כָּל מִי שֶׁהוּא בָּקִי בְּמִינִין אֵלּוּ וּבִשְׁמוֹתֵיהֶן הֲרֵי זֶה אוֹכֵל עוֹף שֶׁאֵינוֹ מֵהֶם וְאֵינוֹ צָרִיךְ בְּדִיקָה. וְעוֹף טָהוֹר נֶאֱכַל בְּמָסֹרֶת. וְהוּא שֶׁיִּהְיֶה דָּבָר פָּשׁוּט בְּאוֹתוֹ מָקוֹם שֶׁזֶּה עוֹף טָהוֹר. וְנֶאֱמָן צַיָּד לוֹמַר עוֹף זֶה הִתִּיר לִי רַבִּי הַצַּיָּד. וְהוּא שֶׁיֻּחְזַק אוֹתוֹ צַיָּד שֶׁהוּא בָּקִי בְּמִינִין אֵלּוּ וּבִשְׁמוֹתֵיהֶן:","מִי שֶׁאֵינוֹ מַכִּירָן וְאֵינוֹ יוֹדֵעַ שְׁמוֹתֵיהֶן בּוֹדֵק בְּסִימָנִין אֵלּוּ שֶׁנָּתְנוּ חֲכָמִים. כָּל עוֹף שֶׁהוּא דּוֹרֵס וְאוֹכֵל בְּיָדוּעַ שֶׁהוּא מֵאֵלּוּ הַמִּינִין וְטָמֵא. וְשֶׁאֵינוֹ דּוֹרֵס וְאוֹכֵל אִם יֵשׁ בּוֹ אֶחָד מִשְּׁלֹשָׁה סִימָנִין אֵלּוּ הֲרֵי זֶה עוֹף טָהוֹר. וְאֵלּוּ הֵן. אֶצְבַּע יְתֵרָה. אוֹ זֶפֶק וְהִיא הַמֻּרְאָה. אוֹ שֶׁהָיָה קֻרְקְבָנוֹ נִקְלַף בְּיָד:","לְפִי שֶׁאֵין בְּכָל אֵלּוּ הַמִּינִין הָאֲסוּרִין מִין שֶׁאֵינוֹ דּוֹרֵס וְיֵשׁ בּוֹ אֶחָד מִשְּׁלֹשָׁה סִימָנִין אֵלּוּ חוּץ מִפֶּרֶס וְעָזְנִיָּה וּפֶרֶס וְעָזְנִיָּה אֵינָן מְצוּיִין בְּיִשּׁוּב אֶלָּא בְּמִדְבָּרוֹת אִיֵּי הַיָּם הָרְחוֹקוֹת עַד מְאֹד שֶׁהֵן סוֹף הַיִּשּׁוּב:","הָיָה הַקֻּרְקְבָן נִקְלָף בְּסַכִּין וְאֵינוֹ נִקְלָף בְּיָד וְאֵין בּוֹ סִימָן אַחֵר אַף עַל פִּי שֶׁאֵינוֹ דּוֹרֵס הֲרֵי זֶה סָפֵק. הָיָה חָזָק וְדָבֵק וְהִנִּיחוֹ בַּשֶּׁמֶשׁ וְנִתְרַפָּה וְנִקְלָף בְּיָד הֲרֵי זֶה מֻתָּר:","אָמְרוּ הַגְּאוֹנִים שֶׁמָּסֹרֶת הִיא בִּידֵיהֶם שֶׁאֵין מוֹרִין לְהַתִּיר עוֹף הַבָּא בְּסִימָן אֶחָד אֶלָּא אִם הָיָה אוֹתוֹ סִימָן שֶׁיִּקָּלֵף קֻרְקְבָנוֹ בְּיָד. אֲבָל אִם אֵינוֹ נִקְלָף בְּיָד אַף עַל פִּי שֶׁיֵּשׁ לוֹ זֶפֶק אוֹ אֶצְבַּע יְתֵרָה מֵעוֹלָם לֹא הִתִּירוּהוּ:","כָּל עוֹף שֶׁחוֹלֵק אֶת רַגְלָיו כְּשֶׁמּוֹתְחִין לוֹ חוּט שְׁתַּיִם לְכָאן וּשְׁתַּיִם לְכָאן. אוֹ שֶׁקּוֹלֵט מִן הָאֲוִיר וְאוֹכֵל בָּאֲוִיר. הֲרֵי זֶה דּוֹרֵס וְטָמֵא. וְכָל הַשּׁוֹכֵן עִם הַטְּמֵאִים וְנִדְמֶה לָהֶם הֲרֵי זֶה טָמֵא:","וּמִינֵי חֲגָבִים שֶׁהִתִּירָה תּוֹרָה שְׁמוֹנָה. וְאֵלּוּ הֵן. א) חָגָב. ב) מִין חָגָב וְהוּא הָרַזְבָנִית. ג) חַרְגּל. ד) וּמִין חַרְגּל וְהוּא עַרְצוּבְיָא. ה) אַרְבֶּה. ו) וּמִין אַרְבֶּה וְהִיא צִפֹּרֶת כְּרָמִים. ז) סָלְעָם. ח) וּמִין סָלְעָם וְהִיא יוֹחָנָא יְרוּשַׁלְמִית:","מִי שֶׁהוּא בָּקִי בָּהֶן וּבִשְׁמוֹתֵיהֶן אוֹכֵל. וְהַצַּיָּד נֶאֱמָן עֲלֵיהֶן כְּעוֹף. ומִי שֶׁאֵינוֹ בָּקִי בָּהֶן בּוֹדֵק בְּסִימָנִין. וּשְׁלֹשָׁה סִימָנִין יֵשׁ בָּהֶן. כָּל שֶׁיֵּשׁ לוֹ אַרְבַּע רַגְלַיִם. וְאַרְבַּע כְּנָפַיִם שֶׁחוֹפוֹת רֹב אֹרֶךְ גּוּפוֹ וְרֹב הֶקֵּף גּוּפוֹ. וְיֵשׁ לוֹ שְׁנֵי כְּרָעַיִם לְנַתֵּר בָּהֶם הֲרֵי זֶה מִין טָהוֹר. וְאַף עַל פִּי שֶׁרֹאשׁוֹ אָרֹךְ וְיֵשׁ לוֹ זָנָב אִם הָיָה שְׁמוֹ חָגָב טָהוֹר:","מִי שֶׁאֵין לוֹ עַכְשָׁו כְּנָפַיִם אוֹ כְּרָעַיִם אוֹ שֶׁאֵין לוֹ כְּנָפַיִם הַחוֹפִין אֶת רֻבּוֹ וְעָתִיד לְגַדֵּל אוֹתָן אַחַר זְמַן כְּשֶׁיַּגְדִּיל הֲרֵי זֶה מֻתָּר מֵעַתָּה:","וּבְדָגִים שְׁנֵי סִימָנִין. סְנַפִּיר וְקַשְׂקֶשֶׂת. וּסְנַפִּיר הוּא שֶׁפּוֹרֵחַ בּוֹ. וְקַשְׂקֶשֶׂת הִיא הַדְּבוּקָה בְּכָל גּוּפוֹ. וְכָל שֶׁיֵּשׁ לוֹ קַשְׂקֶשֶׂת יֵשׁ לוֹ סְנַפִּיר. אֵין לוֹ עַכְשָׁו וּכְשֶׁיַּגְדִּיל יִהְיֶה לוֹ אוֹ שֶׁיֵּשׁ לוֹ קַשְׂקֶשֶׂת כְּשֶׁהוּא בַּיָּם וּכְשֶׁיַּעֲלֶה יַשִּׁיר קַשְׂקַשָּׂיו הֲרֵי זֶה מֻתָּר. וּמִי שֶׁאֵין לוֹ קַשְׂקַשִּׂים הַחוֹפִין אֶת כֻּלּוֹ מֻתָּר. אֲפִלּוּ אֵין בּוֹ אֶלָּא סְנַפִּיר אַחַת וְקַשְׂקֶשֶׂת אַחַת הֲרֵי זֶה מֻתָּר:"],"Mishneh Torah, Forbidden Foods 5":["מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה שֶׁנֶּאֱמַר בַּתּוֹרָה (דברים יב כג) \"לֹא תֹאכַל הַנֶּפֶשׁ עִם הַבָּשָׂר\" לֶאֱסֹר אֵיבָר שֶׁנֶּחְתַּךְ מִן הַחַי. וְעַל אֵיבָר מִן הַחַי הוּא אוֹמֵר לְנֹחַ (בראשית ט ד) \"אַךְ בָּשָׂר בְּנַפְשׁוֹ דָמוֹ לֹא תֹאכֵלוּ\". וְאִסּוּר אֵיבָר מִן הַחַי נוֹהֵג בִּבְהֵמָה חַיָּה וְעוֹף בִּטְהוֹרִים אֲבָל לֹא בִּטְמֵאִים:","אֶחָד אֵיבָר שֶׁיֵּשׁ בּוֹ בָּשָׂר וְגִידִים וַעֲצָמוֹת כְּגוֹן הַיָּד וְהָרֶגֶל. וְאֶחָד אֵיבָר שֶׁאֵין בּוֹ עֶצֶם כְּגוֹן הַלָּשׁוֹן וְהַבֵּיצִים וְהַטְּחוֹל וְהַכְּלָיוֹת וְחֵלֶב וְכַיּוֹצֵא בָּהֶן. אֶלָּא שֶׁהָאֵיבָר שֶׁאֵין בּוֹ עֶצֶם בֵּין שֶׁחָתַךְ כֻּלּוֹ בֵּין שֶׁחָתַךְ מִקְצָתוֹ הֲרֵי זֶה אָסוּר מִשּׁוּם אֵיבָר מִן הַחַי. וְהָאֵיבָר שֶׁיֵּשׁ בּוֹ עֶצֶם אֵינוֹ חַיָּב עָלָיו מִשּׁוּם אֵיבָר מִן הַחַי עַד שֶׁיִּפְרשׁ כִּבְרִיָּתוֹ בָּשָׂר וְגִידִים וַעֲצָמוֹת. אֲבָל אִם פָּרַשׁ מִן הַחַי הַבָּשָׂר בִּלְבַד חַיָּב עָלָיו מִשּׁוּם טְרֵפָה כְּמוֹ שֶׁבֵּאַרְנוּ לֹא מִשּׁוּם אֵיבָר מִן הַחַי:","הָאוֹכֵל מֵאֵיבָר מִן הַחַי כְּזַיִת לוֹקֶה וַאֲפִלּוּ אָכַל אֵיבָר שָׁלֵם אִם יֵשׁ בּוֹ כְּזַיִת חַיָּב פָּחוֹת מִכְּזַיִת פָּטוּר. חָתַךְ מִן הָאֵיבָר כִּבְרִיָּתוֹ בָּשָׂר וְגִידִים וַעֲצָמוֹת כְּזַיִת וַאֲכָלוֹ לוֹקֶה אַף עַל פִּי שֶׁאֵין בּוֹ בָּשָׂר אֶלָּא כָּל שֶׁהוּא. אֲבָל אִם הִפְרִיד הָאֵיבָר אַחַר שֶׁתְּלָשׁוֹ מִן הַחַי וְהִפְרִיד הַבָּשָׂר מִן הַגִּידִים וּמִן הָעֲצָמוֹת אֵינוֹ לוֹקֶה עַד שֶׁיֹּאכַל כְּזַיִת מִן הַבָּשָׂר לְבַדּוֹ. וְאֵין הָעֲצָמוֹת וְהַגִּידִים מִצְטָרְפִין בּוֹ לִכְזַיִת מֵאַחַר שֶׁשִּׁנָּה בְּרִיָּתוֹ:","חִלְּקוֹ לְאֵיבָר זֶה וַאֲכָלוֹ מְעַט מְעַט. אִם יֵשׁ בְּמַה שֶּׁאָכַל כְּזַיִת בָּשָׂר חַיָּב וְאִם לָאו פָּטוּר. לָקַח כְּזַיִת מִן הָאֵיבָר כִּבְרִיָּתוֹ בָּשָׂר וְגִידִים וַעֲצָמוֹת וַאֲכָלוֹ אַף עַל פִּי שֶׁנֶּחְלַק בְּפִיו בִּפְנִים קֹדֶם שֶׁיִּבְלָעֶנּוּ חַיָּב:","תָּלַשׁ אֵיבָר מִן הַחַי וְנִטְרְפָה בִּנְטִילָתוֹ וַאֲכָלוֹ חַיָּב שְׁתַּיִם. מִשּׁוּם אֵיבָר מִן הַחַי וּמִשּׁוּם טְרֵפָה שֶׁהֲרֵי שְׁנֵי הָאִסּוּרִין בָּאִין כְּאַחַת. וְכֵן הַתּוֹלֵשׁ חֵלֶב מִן הַחַי וַאֲכָלוֹ לוֹקֶה שְׁתַּיִם. מִשּׁוּם אֵיבָר מִן הַחַי וּמִשּׁוּם חֵלֶב. תָּלַשׁ חֵלֶב מִן הַטְּרֵפָה וַאֲכָלוֹ לוֹקֶה שָׁלֹשׁ:","בָּשָׂר הַמְדֻלְדָּל בִּבְהֵמָה וְאֵיבָר הַמְדֻלְדָּל בָּהּ אִם אֵינוֹ יָכוֹל לַחֲזֹר וְלִחְיוֹת אַף עַל פִּי שֶׁלֹּא פָּרַשׁ אֶלָּא אַחַר שֶׁנִּשְׁחֲטָה אָסוּר וְאֵין לוֹקִין עָלָיו. וְאִם מֵתָה הַבְּהֵמָה רוֹאִין אוֹתוֹ כְּאִלּוּ נָפַל מֵחַיִּים. לְפִיכָךְ לוֹקִין עָלָיו מִשּׁוּם אֵיבָר מִן הַחַי. אֲבָל הַיָּכוֹל לַחֲזֹר וְלִחְיוֹת אִם נִשְׁחֲטָה הַבְּהֵמָה הֲרֵי זֶה מֻתָּר:","שָׁמַט אֵיבָר אוֹ מְעָכוֹ אוֹ דָּכוֹ כְּגוֹן הַבֵּיצִים שֶׁמָּעַךְ אוֹתָן אוֹ נִתְּקָן הֲרֵי זֶה אֵינוֹ אָסוּר מִן הַתּוֹרָה שֶׁהֲרֵי יֵשׁ בּוֹ מִקְצָת חַיִּים. וּלְפִיכָךְ אֵין מַסְרִיחַ. וְאַף עַל פִּי כֵן אָסוּר לְאָכְלוֹ מִמִּנְהָג שֶׁנָּהֲגוּ כָּל יִשְׂרָאֵל מִקֶּדֶם שֶׁהֲרֵי הוּא דּוֹמֶה לְאֵיבָר מִן הַחַי:","עֶצֶם שֶׁנִּשְׁבַּר אִם הָיָה הַבָּשָׂר אוֹ הָעוֹר חוֹפֶה רֹב עָבְיוֹ שֶׁל עֶצֶם הַנִּשְׁבָּר וְרֹב הֶקֵּף הַשֶּׁבֶר הֲרֵי זֶה מֻתָּר. וְאִם יָצָא הָעֶצֶם לַחוּץ הֲרֵי הָאֵיבָר אָסוּר. וּכְשֶׁיִּשְׁחֹט הַבְּהֵמָה אוֹ הָעוֹף יַחְתֹּךְ מִמְּקוֹם הַשֶּׁבֶר וְיַשְׁלִיכוֹ וְהַשְּׁאָר מֻתָּר. נִשְׁבַּר הָעֶצֶם וְהַבָּשָׂר חוֹפֶה אֶת רֻבּוֹ אֲבָל הָיָה אוֹתוֹ בָּשָׂר מְרֻסָּס אוֹ נִתְאַכֵּל כְּבָשָׂר שֶׁהָרוֹפֵא גּוֹרְרוֹ. אוֹ שֶׁהָיָה מִתְלַקֵּט הָרֹב מִמְּקוֹמוֹת הַרְבֵּה. אוֹ שֶׁהָיָה הַבָּשָׂר שֶׁעָלָיו נְקָבִים נְקָבִים. אוֹ שֶׁנִּסְדַּק הַבָּשָׂר. אוֹ שֶׁנִּקְדַר כְּמִין טַבַּעַת. אוֹ שֶׁנִּגְרַר הַבָּשָׂר מִלְּמַעְלָה עַד שֶׁלֹּא נִשְׁאַר מִן הַבָּשָׂר אֶלָּא כִּקְלִיפָה. אוֹ שֶׁנִּתְאַכֵּל הַבָּשָׂר מִלְּמַטָּה מֵעַל הָעֶצֶם שֶׁנִּשְׁבַּר עַד שֶׁנִּמְצָא הַבָּשָׂר הַחוֹפֶה אֵינוֹ נוֹגֵעַ בָּעֶצֶם. בְּכָל אֵלּוּ מוֹרִין לְאִסּוּר עַד שֶׁיִּתְרַפֵּא הַבָּשָׂר. וְאִם אָכַל מִכָּל אֵלּוּ מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","הַמּוֹשִׁיט יָדוֹ לִמְעֵי הַבְּהֵמָה וְחָתַךְ מִן הַטְּחוֹל וּמִן הַכְּלָיוֹת וְכַיּוֹצֵא בָּהֶן וְהִנִּיחַ הַחֲתִיכוֹת בְּתוֹךְ מֵעֶיהָ וְאַחַר כָּךְ שְׁחָטָהּ. הֲרֵי אוֹתָן הַחֲתִיכוֹת אֲסוּרוֹת מִשּׁוּם אֵיבָר מִן הַחַי. וְאַף עַל פִּי שֶׁהוּא בְּתוֹךְ מֵעֶיהָ. אֲבָל אִם חָתַךְ מִן הָעֻבָּר שֶׁבְּמֵעֶיהָ וְלֹא הוֹצִיאוֹ וְאַחַר כָּךְ שְׁחָטָהּ הֲרֵי חֲתִיכַת הָעֻבָּר אוֹ אֵיבָרוֹ מֻתָּר הוֹאִיל וְלֹא יָצָא. עֻבָּר שֶׁהוֹצִיא יָדוֹ אוֹ רַגְלוֹ נֶאֱסַר אוֹתוֹ אֵיבָר לְעוֹלָם בֵּין שֶׁחֲתָכוֹ קֹדֶם שֶׁתִּשָּׁחֵט אִמּוֹ בֵּין שֶׁחֲתָכוֹ אַחַר שֶׁנִּשְׁחֲטָה אִמּוֹ. וַאֲפִלּוּ הֶחֱזִיר אוֹתוֹ אֵיבָר לִמְעֵי אִמּוֹ וְאַחַר כָּךְ נִשְׁחַט אוֹ נוֹלַד הַוָּלָד וְחָיָה כַּמָּה שָׁנִים הֲרֵי אוֹתוֹ הָאֵיבָר אָסוּר מִשּׁוּם טְרֵפָה. שֶׁכָּל בָּשָׂר שֶׁיָּצָא חוּץ לִמְחִצָּתוֹ נֶאֱסַר כְּבָשָׂר שֶׁפָּרַשׁ מִן הַחַי שֶׁנֶּאֱמַר (שמות כב ל) \"וּבָשָׂר בַּשָּׂדֶה טְרֵפָה\" כֵּיוָן שֶׁיָּצָא לְמָקוֹם שֶׁהוּא לוֹ כְּשָׂדֶה נַעֲשָׂה טְרֵפָה כְּמוֹ שֶׁבֵּאַרְנוּ:","הוֹצִיא מִקְצָת הָאֵיבָר וְנִשְׁאַר מִקְצָתוֹ בִּפְנִים אֲפִלּוּ לֹא נִשְׁאַר אֶלָּא מִעוּטוֹ הַיּוֹצֵא אָסוּר וְשֶׁבִּפְנִים מֻתָּר. וְאִם חָתַךְ הַיּוֹצֵא מִן הָאֵיבָר אַחַר שֶׁהֶחְזִירוֹ וְנִשְׁחֲטָה. אוֹתוֹ שֶׁיָּצָא בִּלְבַד אָסוּר וּשְׁאָר הָאֵיבָר מֻתָּר. וְאִם לֹא הֶחְזִירוֹ וַחֲתָכוֹ וְהוּא בַּחוּץ. בֵּין שֶׁחֲתָכוֹ קֹדֶם שְׁחִיטָה אוֹ אַחַר שְׁחִיטָה. מְקוֹם הַחֲתָךְ אָסוּר. וְהוּא הַמָּקוֹם שֶׁנֶּגֶד הָאֲוִיר. אַחַר שֶׁיֵּחָתֵךְ הַיּוֹצֵא חוֹזֵר וְחוֹתֵךְ מְקוֹם הַחֲתָךְ:","כָּל אֵיבָר עֻבָּר שֶׁיָּצָא וַחֲתָכוֹ קֹדֶם שְׁחִיטָה וְהוּא בַּחוּץ הֲרֵי זֶה אֵיבָר מִן הַחַי וְלוֹקִין עָלָיו. וַאֲפִלּוּ מֵת הָעֻבָּר קֹדֶם שְׁחִיטָה. וְאִם נֶחְתַּךְ אַחַר שְׁחִיטָה הָאוֹכְלוֹ אֵינוֹ לוֹקֶה וַאֲפִלּוּ מֵת. וְאִם מֵתָה הַבְּהֵמָה וְאַחַר כָּךְ חֲתָכוֹ הָאוֹכְלוֹ לוֹקֶה מִשּׁוּם אֵיבָר מִן הַחַי:","עֻבָּר שֶׁהוֹצִיא אֵיבָר וְנֶאֱסַר הָאֵיבָר וְאַחַר כָּךְ נוֹלַד וַהֲרֵי הִיא נְקֵבָה. הֶחָלָב שֶׁלָּהּ אָסוּר לִשְׁתּוֹתוֹ מִסָּפֵק. הוֹאִיל וְהוּא בָּא מִכְּלָל הָאֵיבָרִין וְיֵשׁ בָּהּ אֵיבָר אֶחָד אָסוּר. וַהֲרֵי זֶה כַּחֲלֵב טְרֵפָה שֶׁנִּתְעָרֵב בַּחֲלֵב טְהוֹרָה:","הַשּׁוֹחֵט בְּהֵמָה מְעֻבֶּרֶת וּמָצָא בָּהּ שָׁלִיל בֵּין חַי בֵּין מֵת הֲרֵי זֶה מֻתָּר בַּאֲכִילָה. וַאֲפִלּוּ שִׁלְיָא מֻתֶּרֶת בַּאֲכִילָה. וְשִׁלְיָא שֶׁיָּצָאת מִקְצָתָהּ וְשָׁחַט אֶת הַבְּהֵמָה. אִם הָיְתָה שִׁלְיָא זוֹ קְשׁוּרָה בַּוָּלָד מַה שֶּׁיָּצָא מִמֶּנָּה אָסוּר וְהַשְּׁאָר מֻתָּר. וְאִם לֹא הָיְתָה קְשׁוּרָה בּוֹ כֻּלָּהּ אֲסוּרָה. שֶׁמָּא שִׁלְיָא זוֹ שֶׁיָּצָאת מִקְצָתָהּ הָלַךְ לוֹ וָלָד שֶׁהָיָה בָּהּ וְוָלָד זֶה שֶׁנִּמְצָא בַּבֶּטֶן הָלְכָה שִׁלְיָא שֶׁלּוֹ. וְאֵין צָרִיךְ לוֹמַר שֶׁאִם לֹא נִמְצָא בַּבֶּטֶן וָלָד כְּלָל שֶׁהַשִּׁלְיָא כֻּלָּהּ אֲסוּרָה:","מָצָא בָּהּ עֻבָּר חַי אַף עַל פִּי שֶׁהוּא בֶּן תִּשְׁעָה חֳדָשִׁים גְּמוּרִין וְאֶפְשָׁר שֶׁיִּחְיֶה אֵינוֹ צָרִיךְ שְׁחִיטָה אֶלָּא שְׁחִיטַת אִמּוֹ מְטַהַרְתּוֹ. וְאִם הִפְרִיס עַל גַּבֵּי קַרְקַע צָרִיךְ שְׁחִיטָה:","קָרַע אֶת הַבְּהֵמָה אוֹ שָׁחַט בְּהֵמָה טְרֵפָה וּמָצָא בָּהּ בֶּן תִּשְׁעָה חַי צָרִיךְ שְׁחִיטָה לְהַתִּירוֹ וְאֵין שְׁחִיטַת אִמּוֹ מוֹעֶלֶת לוֹ. וְאִם לֹא גָּמְרוּ לוֹ חֳדָשָׁיו אַף עַל פִּי שֶׁהוּא חַי בִּמְעֵי הַטְּרֵפָה הֲרֵי זֶה אָסוּר מִפְּנֵי שֶׁהוּא כְּאֵיבָר מֵאִמּוֹ. כָּל עֻבָּר שֶׁהוֹצִיא רֹאשׁוֹ וְהֶחְזִירוֹ וְאַחַר כָּךְ שָׁחַט אֶת אִמּוֹ אֵין שְׁחִיטַת אִמּוֹ מוֹעֶלֶת לוֹ וַהֲרֵי הוּא כְּיָלוּד וְצָרִיךְ שְׁחִיטָה:"],"Mishneh Torah, Forbidden Intercourse 16":["פְּצוּעַ דַּכָּא וּכְרוּת שָׁפְכָה שֶׁנָּשְׂאוּ בַּת יִשִׂרָאֵל וּבָעֲלוּ לוֹקִין שֶׁנֶּאֱמַר (דברים כג ב) \"לֹא יָבֹא פְצוּעַ דַּכָּא וּכְרוּת שָׁפְכָה בִּקְהַל ה'\". וּמֻתָּרִין לִשָּׂא גִּיֹּרֶת וּמְשֻׁחְרֶרֶת. וַאֲפִלּוּ כֹּהֵן שֶׁהוּא פְּצוּעַ דַּכָּא מֻתָּר לִשָּׂא גִּיֹּרֶת וּמְשֻׁחְרֶרֶת לְפִי שֶׁאֵינוֹ בִּקְדֻשָּׁתוֹ. וַאֲפִלּוּ נְתִינָה אוֹ אֶחָד מִן הַסְּפֵקוֹת מֻתֶּרֶת לוֹ:","הוֹאִיל וּפְצוּעַ דַּכָּא אָסוּר לָבוֹא בַּקָּהָל לֹא גָּזְרוּ בּוֹ עַל הַנְּתִינִים וְלֹא עַל הַסְּפֵקוֹת. אֲבָל פְּצוּעַ דַּכָּא וּכְרוּת שָׁפְכָה אָסוּר בְּמַמְזֶרֶת וַדָּאִית שֶׁהֲרֵי אֲסוּרָה מִן הַתּוֹרָה:","ואֵי זֶהוּ פְּצוּעַ דַּכָּא. כָּל שֶׁנִּפְצְעוּ הַבֵּיצִים שֶׁלּוֹ. וּכְרוּת שָׁפְכָה כָּל שֶׁנִּכְרַת הַגִּיד שֶׁלּוֹ. וּבִשְׁלֹשָׁה אֵיבָרִין אֶפְשָׁר שֶׁיִּפָּסֵל הַזָּכָר בַּגִּיד וּבַבֵּיצִים וּבַשְּׁבִילִין שֶׁבָּהֶן תִּתְבַּשֵּׁל שִׁכְבַת זֶרַע וְהֵן הַנִּקְרָאִין חוּטֵי בֵּיצִים. וְכֵיוָן שֶׁנִּפְצַע אֶחָד מִשְּׁלֹשָׁה אֵיבָרִין אֵלּוּ אוֹ נִדָּךְ הֲרֵי זֶה פָּסוּל:","כֵּיצַד. נִפְצַע הַגִּיד אוֹ נִדָּךְ אוֹ שֶׁנִּכְרַת הָעֲטָרָה אוֹ לְמַעְלָה מֵעֲטָרָה פָּסוּל. וְאִם נִכְרַת מֵרֹאשׁ הָעֲטָרָה וְנִשְׁתַּיֵּר מִמֶּנָּה אֲפִלּוּ כְּחוּט הַשַּׂעֲרָה מֻקָּף לְכָל הַגִּיד כָּשֵׁר. נִכְרַת הַגִּיד לְמַעְלָה מֵעֲטָרָה כְּקֻלְמוֹס אוֹ כְּמַרְזֵב כָּשֵׁר:","נִקַּב לְמַטָּה מֵעֲטָרָה כָּשֵׁר. נִקְּבָה הָעֲטָרָה עַצְמָהּ אִם כְּשֶׁיִּרְאֶה קֶרִי תֵּצֵא שִׁכְבַת זֶרַע מִן הַנֶּקֶב פָּסוּל. נִסְתַּם הַנֶּקֶב חָזַר לְהֶכְשֵׁרוֹ. נִקַּב לְמַטָּה מֵעֲטָרָה שֶׁכְּנֶגְדּוֹ לְמַעְלָה בְּתוֹךְ הָעֲטָרָה פָּסוּל שֶׁהָעֲטָרָה כֻּלָּהּ מְעַכֶּבֶת:","נִסְתַּם שְׁבִיל שִׁכְבַת זֶרַע וְחָזַר לִרְאוֹת שִׁכְבַת זֶרַע מִשְּׁבִיל שֶׁמַּשְׁתִּין בּוֹ הֲרֵי זֶה פָּסוּל:","נִכְרְתוּ הַבֵּיצִים אוֹ אַחַת מֵהֶן אוֹ שֶׁנִּפְצְעָה אַחַת מֵהֶן אוֹ שֶׁנִּדּוֹכָה אַחַת מֵהֶן אוֹ שֶׁחָסְרָה אוֹ שֶׁנִּקְּבָה הֲרֵי זֶה פָּסוּל. נִכְרְתוּ חוּטֵי בֵּיצִים אוֹ אַחַת אוֹ שֶׁנִּדָּךְ אוֹ נִפְצַע הֲרֵי זֶה פָּסוּל:","נִקַּב חוּט מִחוּטֵי הַבֵּיצִים לִשְׁבִיל מֵי רַגְלַיִם וַהֲרֵי הוּא מַטִּיל מַיִם מִשְּׁנֵי מְקוֹמוֹת מִשְּׁבִיל הַמַּיִם וּמִשְּׁבִיל שִׁכְבַת זֶרַע הֲרֵי זֶה כָּשֵׁר:","כָּל פָּסוּל שֶׁאָמַרְנוּ בְּעִנְיָן זֶה כְּשֶׁלֹּא הָיוּ בִּידֵי שָׁמַיִם כְּגוֹן שֶׁכְּרָתוֹ אָדָם אוֹ כֶּלֶב אוֹ הִכָּהוּ קוֹץ וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. אֲבָל אִם נוֹלַד כְּרוּת שָׁפְכָה אוֹ פְּצוּעַ דַּכָּא אוֹ שֶׁנּוֹלַד בְּלֹא בֵּיצִים אוֹ שֶׁחָלָה מֵחֲמַת גּוּפוֹ וּבָטְלוּ מִמֶּנּוּ אֵיבָרִים אֵלּוּ אוֹ שֶׁנּוֹלַד בָּהֶם שְׁחִין וְהֵמֵסָּה אוֹתָן אוֹ כְּרָתָן הֲרֵי זֶה כָּשֵׁר לָבֹא בַּקָּהָל שֶׁכָּל אֵלּוּ בִּידֵי שָׁמַיִם:","אָסוּר לְהַפְסִיד אֵיבְרֵי זֶרַע בֵּין בְּאָדָם בֵּין בִּבְהֵמָה חַיָּה וְעוֹף. אֶחָד טְמֵאִים וְאֶחָד טְהוֹרִים. בֵּין בְּאֶרֶץ יִשְׂרָאֵל בֵּין בְּחוּצָה לָאָרֶץ. אַף עַל פִּי שֶׁנֶּאֱמַר (ויקרא כב כד) \"וּבְאַרְצְכֶם לֹא תַעֲשׂוּ\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁדָּבָר זֶה נוֹהֵג בְּכָל מָקוֹם. וְעִנְיַן הַכָּתוּב לֹא יֵעָשֶׂה זֹאת בְּיִשְׂרָאֵל בֵּין בְּגוּפָן בֵּין בְּגוּף אֲחֵרִים. וְכָל הַמְסָרֵס לוֹקֶה מִן הַתּוֹרָה בְּכָל מָקוֹם. וַאֲפִלּוּ מְסָרֵס אַחַר מְסָרֵס לוֹקֶה:","כֵּיצַד. הֲרֵי שֶׁבָּא אֶחָד וְכָרַת אֶת הַגִּיד וּבָא אַחֵר וְכָרַת אֶת הַבֵּיצִים אוֹ נִתְּקָן וּבָא אַחֵר וְכָרַת חוּטֵי בֵּיצִים. אוֹ שֶׁבָּא אֶחָד וּמָעַךְ אֶת הַגִּיד וּבָא אַחֵר וְנִתְּקוֹ וּבָא אַחֵר וּכְרָתוֹ כֻּלָּן לוֹקִין. וְאַף עַל פִּי שֶׁלֹּא סֵרֵס הָאַחֲרוֹן אֶלָּא מְסֹרָס. בֵּין בָּאָדָם בֵּין בִּבְהֵמָה חַיָּה וָעוֹף. וְהַמְסָרֵס אֶת הַנְּקֵבָה בֵּין בְּאָדָם בֵּין בִּשְׁאָר מִינִים פָּטוּר:","הַמַּשְׁקֶה עִקָּרִין לְאָדָם אוֹ לִשְׁאָר מִינִים כְּדֵי לְסָרְסוֹ הֲרֵי זֶה אָסוּר וְאֵין לוֹקִין עָלָיו. וְאִשָּׁה מֻתֶּרֶת לִשְׁתּוֹת עִקָּרִין כְּדֵי לְסָרְסָהּ עַד שֶׁלֹּא תֵּלֵד. הֲרֵי שֶׁכָּפָה אֶת הָאָדָם וְשִׁסָּה בּוֹ כֶּלֶב אוֹ שְׁאָר חַיּוֹת עַד שֶׁעֲשָׂאוּהוּ כְּרוּת שָׁפְכָה אוֹ שֶׁהוֹשִׁיבוֹ בַּמַּיִם אוֹ בַּשֶּׁלֶג עַד שֶׁבִּטֵּל מִמֶּנּוּ אֵיבְרֵי תַּשְׁמִישׁ אֵינוֹ לוֹקֶה עַד שֶׁיְּסָרֵס בְּיָדוֹ. וְרָאוּי לְהַכּוֹתוֹ מַכַּת מַרְדּוּת:","אָסוּר לוֹמַר לְעַכּוּ\"ם לְסָרֵס בְּהֵמָה שֶׁלָּנוּ. וְאִם לְקָחָהּ הוּא מֵעַצְמוֹ וְסֵרְסָהּ מֻתָּר. וְאִם הֶעֱרִים יִשְׂרָאֵל בְּדָבָר זֶה קוֹנְסִין אוֹתוֹ וּמוֹכְרָהּ לְיִשְׂרָאֵל אַחֵר. וַאֲפִלּוּ לִבְנוֹ הַגָּדוֹל מֻתָּר לְמָכְרָהּ. אֲבָל לִבְנוֹ הַקָּטָן אֵינוֹ מוֹכְרָהּ לוֹ וְלֹא נוֹתְנָה לוֹ:"],"Mishneh Torah, Forbidden Intercourse 7":["מְעֻבֶרֶת שֶׁהִתְחִילָה לְהִצְטַעֵר וַאֲחָזוּהָ חֶבְלֵי לֵדָה וְהִתְחִיל הַדָּם לָצֵאת קֹדֶם שֶׁתֵּלֵד אוֹתוֹ הַדָּם הוּא הַנִּקְרָא דַּם הַקֹּשִׁי. וְהֵיאַךְ דִּינוֹ. אִם בָּא בִּימֵי נִדָּתָהּ הֲרֵי הוּא דַּם נִדָּה וַהֲרֵי זוֹ טְמֵאָה נִדָּה. וְאִם בָּא בִּימֵי זִיבָתָהּ הֲרֵי זוֹ טְהוֹרָה שֶׁנֶּאֱמַר בְּזָבָה (ויקרא טו יט) \"דָּם יִהְיֶה זֹבָהּ בִּבְשָׂרָהּ\". מִפִּי הַשְּׁמוּעָה לָמְדוּ זוֹבָהּ מֵחֲמַת עַצְמָהּ וְלֹא מֵחֲמַת וָלָד. וּבִלְבַד שֶׁתֵּלֵד וָלָד חַי. אֲבָל אִם הִפִּילָה אֵין קֹשִׁי לִנְפָלִים. אֲפִלּוּ הָיָה הַדָּם שׁוֹתֵת וְיוֹרֵד עִם הַחֲבָלִים וְהַצַּעַר י\"ד יוֹם קֹדֶם שֶׁתֵּלֵד הֲרֵי זֶה דַּם קֹשִׁי וְטָהוֹר. אֲבָל אִם הִתְחִיל הַדָּם קֹדֶם הַלֵּדָה בְּט\"ו יוֹם אוֹ יֶתֶר הֲרֵי זֶה דַּם זִיבָה וַהֲרֵי הִיא יוֹלֶדֶת בְּזוֹב:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא פָּסְקוּ הַצִּירִים וְהַחֲבָלִים וְהַצַּעַר אֶלָּא מִתְקַשָּׁה וְהוֹלֶכֶת עַד שֶׁיָּלְדָה. אֲבָל אִם רָאֲתָה דָּם שְׁלֹשָׁה יָמִים אוֹ יֶתֶר בִּימֵי זִיבָתָהּ בְּצַעַר וַחֲבָלִים וּפָסַק לָהּ הַצַּעַר וְרָוַח לָהּ מִן הַחֲבָלִים אַחַר הַשְּׁלֹשָׁה יָמִים וְעָמְדָה בְּנַחַת כ\"ד שָׁעוֹת אוֹ יֶתֶר אַף עַל פִּי שֶׁלֹּא פָּסַק הַדָּם וְאַף עַל פִּי שֶׁחָזַר הַצַּעַר וְהַחֲבָלִים אַחַר כ\"ד שָׁעוֹת הֲרֵי זוֹ זָבָה. שֶׁאִלּוּ הָיָה הַדָּם מֵחֲמַת הַוָּלָד לֹא פָּסַק הַצַּעַר וְלֹא הַחֲבָלִים. וְאִם יָלְדָה אַחֲרֵי כֵן הֲרֵי זוֹ יוֹלֶדֶת בְּזוֹב:","רָאֲתָה יוֹם אֶחָד בְּלֹא צַעַר וּשְׁנַיִם בְּקֹשִׁי וְיָלְדָה. אוֹ שְׁנַיִם בְּלֹא צַעַר וְיוֹם אֶחָד בְּקֹשִׁי וְיָלְדָה. אוֹ יוֹם בְּקֹשִׁי וְיוֹם בְּלֹא צַעַר וְיוֹם בְּקֹשִׁי וְיָלְדָה אֵינָהּ יוֹלֶדֶת בְּזוֹב. אֲבָל אִם רָאֲתָה יוֹם אֶחָד בְּקֹשִׁי וּשְׁנַיִם בְּלֹא צַעַר וְיָלְדָה. אוֹ שְׁנַיִם בְּקֹשִׁי וְאֶחָד בְּלֹא צַעַר וְיָלְדָה. אוֹ יוֹם בְּלֹא צַעַר וְיוֹם בְּקֹשִׁי וְיוֹם בְּלֹא צַעַר וְיָלְדָה הֲרֵי זוֹ יוֹלֶדֶת בְּזוֹב. זֶה הַכְּלָל קֹשִׁי סָמוּךְ לַלֵּדָה אֵין זוֹ יוֹלֶדֶת בְּזוֹב. שֹׁפִי סָמוּךְ לַלֵּדָה הֲרֵי זוֹ יוֹלֶדֶת בְּזוֹב:","חָל שְׁלִישִׁי לִרְאִיָּתָהּ לִהְיוֹת בְּיוֹם הַלֵּדָה אֲפִלּוּ כָּל הַיּוֹם כֻּלּוֹ בְּשֹׁפִי אֵין זוֹ יוֹלֶדֶת בְּזוֹב. שֶׁהֲרֵי יוֹם הַלֵּדָה סָמוּךְ לַקֹּשִׁי. רָאֲתָה שְׁנֵי יָמִים וּבַשְּׁלִישִׁי הִפִּילָה וְאֵין יָדוּעַ מַה הִפִּילָה הֲרֵי זוֹ סְפֵק יוֹלֶדֶת וּסְפֵק זָבָה:","כֵּיצַד דִּין יוֹלֶדֶת בְּזוֹב. צְרִיכָה לֵישֵׁב שִׁבְעָה יָמִים נְקִיִּים וְטוֹבֶלֶת לָעֶרֶב. וְאַחַר כָּךְ תִּהְיֶה מֻתֶּרֶת לְבַעְלָהּ וְאַחַר כָּךְ יִהְיֶה לָהּ דַּם טֹהַר וּמְבִיאָה קָרְבַּן זָבָה וְקָרְבַּן יוֹלֶדֶת. לְפִיכָךְ אִם יָלְדָה זָכָר אֲפִלּוּ פָּסַק הַדָּם בְּיוֹם הַלֵּדָה סוֹפֶרֶת שִׁבְעַת יָמִים נְקִיִּים וְטוֹבֶלֶת. וְאִם יָלְדָה נְקֵבָה וְסָפְרָה שִׁבְעָה נְקִיִּים וְשָׁלְמוּ עִם י\"ד שֶׁל לֵדָה אוֹ לְאַחֲרֵיהֶן הֲרֵי זוֹ טוֹבֶלֶת וּמֻתֶּרֶת לְבַעְלָהּ. וְאִם שָׁלְמוּ יְמֵי הַסְּפִירָה בְּתוֹךְ י\"ד הֲרֵי זוֹ אֲסוּרָה לְבַעְלָהּ עַד לֵיל ט\"ו:","כֵּיצַד. הֲרֵי שֶׁרָאֲתָה דָּם שְׁלֹשָׁה וְסָפְרָה שִׁבְעַת יָמִים נְקִיִּים הֲרֵי עֲשָׂרָה. וַעֲדַיִן הִיא אֲסוּרָה לְבַעְלָהּ עַד לֵיל ט\"ו. שֶׁכָּל י\"ד הִיא כְּנִדָּה. וְלָמָּה אֵין מַצְרִיכִין אֶת הַיּוֹלֶדֶת בְּזוֹב לִסְפִירַת שִׁבְעָה אַחַר שִׁבְעָה שֶׁל זָכָר וְאַחַר י\"ד שֶׁל נְקֵבָה. מִפְּנֵי שֶׁיְּמֵי לֵדָתָהּ וִימֵי נִדָּתָהּ שֶׁאֵינָהּ רוֹאָה בָּהֶן עוֹלִין לָהּ לִסְפִירַת שִׁבְעָה כְּמוֹ שֶׁיִּתְבָּאֵר:","יוֹלֶדֶת בְּזוֹב שֶׁלֹּא פָּסַק דָּמָהּ אֵין לָהּ דַּם טֹהַר. אֶלָּא כָּל דָּם שֶׁתִּרְאֶה כְּדַם זִיבָה הוּא. אֲבָל אִם סָפְרָה שִׁבְעַת יָמִים נְקִיִּים וְשָׁלְמוּ י\"ד שֶׁל נְקֵבָה וְטָבְלָה וְאַחַר כָּךְ רָאֲתָה דָּם בְּתוֹךְ אַרְבָּעִים שֶׁל זָכָר וּשְׁמוֹנִים שֶׁל נְקֵבָה הֲרֵי זֶה דַּם טֹהַר:","סָפְרָה שִׁבְעָה יָמִים נְקִיִּים וְלֹא טָבְלָה וְאַחַר כָּךְ רָאֲתָה דָּם הֲרֵי זוֹ טוֹבֶלֶת וּמֻתֶּרֶת לְבַעְלָהּ מִיָּד. שֶׁכָּל יְמֵי טֹהַר אֵינָן רְאוּיוֹת לֹא לְנִדָּה וְלֹא לְזִיבָה. אֲבָל עַצְמוֹ שֶׁל דָּם טָמֵא וּמְטַמֵּא כְּדִין דַּם הַנִּדָּה עַד שֶׁתִּטְבּל:","הַיּוֹלֶדֶת נְקֵבָה וְאַחַר י\"ד שֶׁלָּהּ נִתְעַבְּרָה וְהִתְחִיל דַּם הַקֹּשִׁי לָבֹא לָהּ בְּתוֹךְ שְׁמוֹנִים הֲרֵי הוּא דַּם טֹהַר. אַף עַל פִּי שֶׁאֵין קֹשִׁי לִנְפָלִים שֶׁכָּל דָּמִים שֶׁתִּרְאֶה בְּתוֹךְ יְמֵי טֹהַר טָהוֹר הוּא עַד שֶׁתַּפִּיל הַוָּלָד. וּכְשֶׁתַּפִּיל תִּהְיֶה טְמֵאָה לֵדָה. אִם הִפִּילָה זָכָר טֻמְאַת זָכָר וְאִם הִפִּילָה נְקֵבָה טֻמְאַת נְקֵבָה. וּמוֹנָה יְמֵי טֻמְאָה וִימֵי מְלֹאת מִוָּלָד שֵׁנִי. אֲפִלּוּ הָיוּ תְּאוֹמִים וְהִפִּילָה הַיּוֹם אֶחָד וְהִפִּילָה הָאַחֵר אֲפִלּוּ אַחַר כַּמָּה יָמִים מוֹנָה לַשֵּׁנִי יְמֵי טֻמְאָה וִימֵי מְלֹאת:","זָבָה שֶׁפָּסַק זוֹבָהּ וְהִתְחִילָה לִמְנוֹת שִׁבְעַת יָמִים נְקִיִּים וּבָא לָהּ דַּם קֹשִׁי בְּתוֹךְ יָמִים נְקִיִּים אֵינוֹ סוֹתֵר. וִימֵי הַקֹּשִׁי עוֹלִים לְמִנְיַן שִׁבְעָה. וְכֵן אִם יָלְדָה בְּשִׁבְעָה יָמִים נְקִיִּים אֵין הַלֵּדָה סוֹתֶרֶת. וִימֵי הַלֵּדָה עוֹלִין לָהּ לְמִנְיַן שִׁבְעָה אַף עַל פִּי שֶׁהִיא טְמֵאָה בָּהֶן שֶׁנֶּאֱמַר (ויקרא טו כח) \"וְאִם טָהֲרָה מִזּוֹבָהּ\" כֵּיוָן שֶׁטָּהֲרָה מִזּוֹבָהּ אַף עַל פִּי שֶׁהִיא טְמֵאָה טֻמְאָה אַחֶרֶת כְּגוֹן טֻמְאַת לֵדָה אוֹ טֻמְאַת נִדָּה אוֹ טֻמְאַת צָרַעַת הֲרֵי זוֹ סוֹפֶרֶת בָּהֶן. וְאֵין טֻמְאוֹת אֵלּוּ וְכַיּוֹצֵא בָּהֶן סוֹתְרִין הַסְּפִירָה:","יְמֵי לֵדָתָהּ וִימֵי נִדָּתָהּ אִם לֹא רָאֲתָה בָּהֶן דָּם הֲרֵי אֵלּוּ עוֹלִין לָהּ לִסְפִירַת שִׁבְעַת יָמִים נְקִיִּים וְאִם רָאֲתָה בָּהֶן דָּם אֵין עוֹלִין לָהּ יְמֵי הָרְאִיָּה וְלֹא סוֹתְרִין כָּל הַיָּמִים. אֶלָּא מַשְׁלֶמֶת עַל הַיָּמִים שֶׁסָּפְרָה כְּשֶׁיִּפְסֹק הַדָּם. שֶׁאֵין סוֹתֵר הַכּל אֶלָּא רְאִיָּה שֶׁל זוֹב אֲבָל אֵלּוּ סוֹתְרִין יוֹמָן בִּלְבַד:","מֵאַחַר שֶׁתָּבִין כָּל הָעִקָּרִים שֶׁבֵּאַרְנוּ. יִתְבָּאֵר לְךָ מַה שֶּׁאָמְרוּ חֲכָמִים שֶׁאֶפְשָׁר שֶׁתִּרְאֶה הָאִשָּׁה דָּם מִן הַמָּקוֹר יוֹם אַחַר יוֹם מֵאָה וְאַרְבָּעָה עָשָׂר יוֹם וְלֹא תִּהְיֶה זָבָה. כֵּיצַד. שְׁנַיִם לִפְנֵי נִדָּתָהּ וְשִׁבְעָה יְמֵי נִדָּתָהּ וּשְׁנַיִם לְאַחַר יְמֵי נִדָּתָהּ. וְאַרְבָּעָה עָשָׂר קֹשִׁי. וּשְׁמוֹנִים שֶׁל נְקֵבָה. וְשִׁבְעָה יְמֵי נִדָּה. וּשְׁנַיִם אַחַר יְמֵי נִדָּה. הָא לָמַדְתָּ שֶׁכָּל דָּם שֶׁתִּרְאֶה הָאִשָּׁה אַחַר יוֹם מְלֹאת הוּא תְּחִלַּת נִדָּתָהּ וְאֵין מַשְׁגִּיחִין עַל וְסָתוֹת שֶׁמִּקֹּדֶם. לְפִיכָךְ הָרוֹאָה דָּם בְּסוֹף יוֹם מְלֹאת בֵּין הַשְּׁמָשׁוֹת הֲרֵי זוֹ סְפֵק נִדָּה שֶׁמָּא בַּלַּיְלָה רָאֲתָה הַדָּם שֶׁהוּא תְּחִלַּת יְמֵי נִדָּתָהּ:","כְּבָר בֵּאַרְנוּ שֶׁהַנִּדָּה שֶׁרָאֲתָה דָּם כָּל שִׁבְעָה מֻתֶּרֶת לְשַׁמֵּשׁ בְּלֵיל שְׁמִינִי אַחַר שֶׁתִּטְבּל. וְזָבָה קְטַנָּה מְשַׁמֶּרֶת יוֹם אֶחָד טָהוֹר וְטוֹבֶלֶת וּמֻתֶּרֶת לְשַׁמֵּשׁ לָעֶרֶב. וְזָבָה גְּדוֹלָה סוֹפֶרֶת שִׁבְעַת יָמִים נְקִיִּים וְטוֹבֶלֶת וּמֻתֶּרֶת לְשַׁמֵּשׁ בְּלֵיל שְׁמִינִי. וְאֵין בֵּין זְמַן נִדָּה לְנִדָּה אֶלָּא אַחַד עָשָׂר יוֹם בִּלְבַד. וּבְאוֹתָן הָאַחַד עָשָׂר תִּהְיֶה זָבָה קְטַנָּה אוֹ גְּדוֹלָה:","וּמֵאַחַר שֶׁתִּהְיֶה זוֹכֵר כָּל אֵלּוּ הָעִקָּרִים יִתְבָּאֵר לְךָ זֶה שֶׁאָמְרוּ חֲכָמִים. הָאִשָּׁה שֶׁהֻחְזְקָה כָּל יָמֶיהָ יוֹם תִּרְאֶה דָּם וְיוֹם לֹא תִּרְאֶה בַּתְּחִלָּה מְשַׁמֶּשֶׁת בְּלֵיל שְׁמִינִי וּבְיוֹם שְׁמִינִי שֶׁהוּא יוֹם אֶחָד אַחַר יְמֵי נִדָּתָהּ. וּמְשַׁמֶּשֶׁת בְּכָל י\"ח יוֹם אַרְבָּעָה לֵילוֹת בִּלְבַד. וְאֵינָהּ יְכוֹלָה לְשַׁמֵּשׁ בַּיָּמִים הַטְּהוֹרִים שֶׁהַיּוֹם הַטָּהוֹר הוּא שׁוֹמֵר לַיּוֹם הַטָּמֵא. לְפִיכָךְ אִם הָיְתָה רוֹאָה הַדָּם בְּכָל יוֹם טָמֵא מִתְּחִלַּת הַלַּיְלָה אֵינָהּ מְשַׁמֶּשֶׁת אֶלָּא בַּשְּׁמִינִי בִּלְבַד שֶׁהוּא יוֹם אֶחָד אַחַר יְמֵי נִדָּתָהּ:","הָיְתָה רוֹאָה שְׁנֵי יָמִים טְמֵאִין וּשְׁנֵי יָמִים טְהוֹרִים מְשַׁמֶּשֶׁת בַּשְּׁמִינִי וּבַשְּׁנֵים עָשָׂר וּבַחֲמִשָּׁה עָשָׂר וּבַעֶשְׂרִים:","הָיְתָה רוֹאָה שְׁלֹשָׁה יָמִים טְמֵאִין וּשְׁלֹשָׁה טְהוֹרִין מְשַׁמֶּשֶׁת שְׁנֵי יָמִים מֵהַשְּׁלֹשָׁה הַטְּהוֹרִין שֶׁאַחַר יְמֵי נִדָּתָהּ. שֶׁהָאֶחָד מֵהֶן שָׁמוּר לַשְּׁנַיִם הַטְּמֵאִין הַסְּמוּכִין לְנִדָּתָהּ. וְשׁוּב אֵינָהּ מְשַׁמֶּשֶׁת לְעוֹלָם שֶׁהֲרֵי הֻחְזְקָה זָבָה גְּדוֹלָה וְאֵין לָהּ שִׁבְעַת יָמִים נְקִיִּים:","הָיְתָה רוֹאָה אַרְבָּעָה יָמִים טְמֵאִים וְאַרְבָּעָה יָמִים טְהוֹרִין מְשַׁמֶּשֶׁת יוֹם אֶחָד שֶׁאַחַר נִדָּתָהּ וְשׁוּב אֵינָהּ מְשַׁמֶּשֶׁת לְעוֹלָם:","הָיְתָה רוֹאָה חֲמִשָּׁה יָמִים טְמֵאִים וַחֲמִשָּׁה יָמִים טְהוֹרִים. מְשַׁמֶּשֶׁת הַשְּׁלֹשָׁה הַסְּמוּכִים לְנִדָּתָהּ וְשׁוּב אֵינָהּ מְשַׁמֶּשֶׁת לְעוֹלָם:","הָיְתָה רוֹאָה שִׁשָּׁה יָמִים טְמֵאִין וְשִׁשָּׁה יָמִים טְהוֹרִין מְשַׁמֶּשֶׁת בַּחֲמִשָּׁה יָמִים הַסְּמוּכִים לְנִדָּתָהּ תְּחִלָּה וְשׁוּב אֵינָהּ מְשַׁמֶּשֶׁת לְעוֹלָם:","הָיְתָה רוֹאָה שִׁבְעָה טְמֵאִין וְשִׁבְעָה טְהוֹרִין. מְשַׁמֶּשֶׁת הַשָּׁבוּעַ הָרִאשׁוֹן הַטָּהוֹר הַסָּמוּךְ לְנִדָּתָהּ וְיָבוֹא אַחֲרָיו שָׁבוּעַ טָמֵא תִּקָּבַע בּוֹ זָבָה וְהַשָּׁבוּעַ הַטָּהוֹר שֶׁיָּבוֹא אַחֲרָיו לִסְפִירָה וַאֲסוּרָה לְשַׁמֵּשׁ בּוֹ. נִמְצֵאת שֶׁלֹּא שִׁמְּשָׁה מִטָּתָהּ בְּאַרְבָּעָה שָׁבוּעוֹת אֶלָּא שָׁבוּעַ אֶחָד. וְכָל יָמֶיהָ מְשַׁמֶּשֶׁת שְׁמוֹנָה עָשָׂר יוֹם בְּכָל שְׁמוֹנָה עָשָׂר שָׁבוּעוֹת. כֵּיצַד. שָׁבוּעַ חֲמִישִׁי הֲרֵי הִיא זָבָה. שָׁבוּעַ שִׁשִּׁי שֶׁהִיא בּוֹ טְהוֹרָה לִסְפִירָה. שָׁבוּעַ שְׁבִיעִי זָבָה. שָׁבוּעַ שְׁמִינִי לִסְפִירָה. שָׁבוּעַ תְּשִׁיעִי שֶׁהִיא רוֹאָה בּוֹ. חֲמִשָּׁה יָמִים מִמֶּנּוּ מִימֵי נִדָּה. וּשְׁנַיִם מִתְּחִלַּת יְמֵי זִיבָה. מְשַׁמֶּרֶת יוֹם אֶחָד מִן הַשָּׁבוּעַ הַעֲשִׂירִי הַטָּהוֹר וּמְשַׁמֶּשֶׁת שִׁשָּׁה. שָׁבוּעַ אַחַד עָשָׂר שֶׁהִיא רוֹאָה בּוֹ שְׁנַיִם מִסּוֹף יְמֵי זוֹבָהּ. וַחֲמִשָּׁה מִתְּחִלַּת יְמֵי נִדָּה. וּמְשַׁמֶּשֶׁת חֲמִשָּׁה יָמִים מִשָּׁבוּעַ שְׁנֵים עָשָׂר הַטָּהוֹר. שָׁבוּעַ י\"ג זָבָה וְשָׁבוּעַ י\"ד לִסְפִירָה. וְכֵן שָׁבוּעַ ט\"ו זָבָה. שָׁבוּעַ ט\"ז לִסְפִירָה. וְשָׁבוּעַ י\"ז זָבָה. וְשָׁבוּעַ י\"ח לִסְפִירָה. וְסוֹפֶרֶת עַל דֶּרֶךְ זוֹ לְעוֹלָם. נִמְצֵאתָ אוֹמֵר שֶׁבְּכָל י\"ח שָׁבוּעוֹת מְשַׁמֶּשֶׁת י\"ח יוֹם. וְאִלּוּ לֹא אֵרַע לָהּ חלִי זֶה וְהָיְתָה שָׁבוּעַ נִדָּה וְי\"א יוֹם טְהוֹרָה הָיְתָה מְשַׁמֶּשֶׁת בְּכָל הַי\"ח שָׁבוּעוֹת י\"א שָׁבוּעוֹת שֶׁהֵן שִׁבְעָה וְשִׁבְעִים יוֹם:","וּבִזְמַן שֶׁהִיא רוֹאָה שָׁבוּעַ טָמֵא וְשָׁבוּעַ טָהוֹר מְשַׁמֶּשֶׁת י\"ח יוֹם שֶׁהֵם כְּמוֹ רְבִיעַ הַיָּמִים. וְזוֹ הִיא שֶׁאָמְרוּ חֲכָמִים מְשַׁמֶּשֶׁת רְבִיעַ יָמֶיהָ:","הָיְתָה רוֹאָה שְׁמֹנָה יָמִים טָמֵא וּשְׁמֹנָה יָמִים טָהוֹר הֲרֵי זוֹ מְשַׁמֶּשֶׁת ט\"ו יוֹם מִתּוֹךְ מ\"ח יָמִים. כֵּיצַד. שְׁמוֹנָה טָמֵא שֶׁבַּתְּחִלָּה שִׁבְעָה מֵהֶן יְמֵי נִדָּתָהּ. וְיוֹם אֶחָד זִיבוּת סָמוּךְ לְנִדָּתָהּ מְשַׁמֶּרֶת לוֹ יוֹם אֶחָד מִן הַשְּׁמוֹנָה הַטְּהוֹרִין וּמְשַׁמֶּשֶׁת שִׁבְעָה. וְאַחַר כָּךְ יָבוֹאוּ לָהּ שְׁמוֹנָה טְמֵאִין. מֵהֶן שְׁנַיִם תַּשְׁלוּם יְמֵי זִיבָתָהּ. וְשִׁשָּׁה מִימֵי נִדָּתָהּ. וְיָבוֹאוּ שְׁמֹנָה טְהוֹרִין יוֹם אֶחָד מֵהֶן תַּשְׁלוּם יְמֵי נִדָּתָהּ וּמְשַׁמֶּשֶׁת שִׁבְעָה שְׁנִיּוֹת וְאַחַר כָּךְ יָבוֹאוּ לָהּ שְׁמוֹנָה טְמֵאִים. מֵהֶן אַרְבָּעָה תַּשְׁלוּם יְמֵי זִיבָתָהּ. וְאַרְבָּעָה מִימֵי נִדָּתָהּ. נִמְצֵאת זָבָה גְּדוֹלָה וּצְרִיכָה סְפִירַת שִׁבְעָה. יָבוֹאוּ לָהּ שְׁמֹנָה טְהוֹרִים. סוֹפֶרֶת מֵהֶן שִׁבְעָה וּמְשַׁמֶּשֶׁת יוֹם אֶחָד. נִמְצֵאת מְשַׁמֶּשֶׁת ט\"ו יוֹם בְּכָל מ\"ח:","הָיְתָה רוֹאָה תִּשְׁעָה יָמִים טְמֵאִים וְתִּשְׁעָה יָמִים טְהוֹרִין מְשַׁמֶּשֶׁת שְׁמֹנָה יָמִים בְּכָל י\"ח יוֹם לְעוֹלָם. כֵּיצַד תִּשְׁעָה הַטְּמֵאִים. שִׁבְעָה מֵהֶן נִדָּתָהּ וּשְׁנַיִם זִיבוּת סָמוּךְ לְנִדָּתָהּ מְשַׁמֶּרֶת לָהֶן יוֹם אֶחָד מִן הַתִּשְׁעָה הַטְּהוֹרִין וּמְשַׁמֶּשֶׁת שְׁמוֹנָה וְכֵן לְעוֹלָם:","הָיְתָה רוֹאָה עֲשָׂרָה יָמִים טָמֵא וַעֲשָׂרָה טָהוֹר. וּמֵעֲשָׂרָה וּלְמַעְלָה אֲפִלּוּ אֶלֶף יוֹם טָמֵא וְאֶלֶף יוֹם טָהוֹר יִהְיֶה יְמֵי שִׁמּוּשָׁהּ כְּמִנְיַן זִיבָתָהּ. כֵּיצַד עֲשָׂרָה הַטְּמֵאִים. מֵהֶם שִׁבְעָה נִדָּה וּשְׁלֹשָׁה זִיבָה. עֲשָׂרָה הַטְּהוֹרִים סוֹפֶרֶת מֵהֶן שִׁבְעָה וּמְשַׁמֶּשֶׁת שְׁלֹשָׁה. נִמְצְאוּ יְמֵי הַשִּׁמּוּשׁ שְׁלֹשָׁה וִימֵי הַזָּבוּת שְׁלֹשָׁה. וְכֵן מֵאָה יוֹם טְמֵאִין וּמֵאָה טְהוֹרִין. וּמֵאָה הַטְּמֵאִין שִׁבְעָה מֵהֶן לְנִדָּה וְצ\"ג זִיבוּת. הַמֵּאָה הַטְּהוֹרִין שִׁבְעָה מֵהֶן לִסְפִירָה צ\"ג לְשִׁמּוּשׁ. וְכֵן אֶלֶף וְכֵן כָּל מִנְיָן וּמִנְיָן עַל דֶּרֶךְ זוֹ:"],"Mishneh Torah, Foreign Worship and Customs of the Nations 7":["מִצְוַת עֲשֵׂה הִיא לְאַבֵּד עֲבוֹדַת כּוֹכָבִים וּמְשַׁמְּשֶׁיהָ וְכָל הַנַּעֲשֶׂה בִּשְׁבִילָהּ שֶׁנֶּאֱמַר (דברים יב ב) \"אַבֵּד תְּאַבְּדוּן אֶת כָּל הַמְּקוֹמֹת\" וְנֶאֱמַר (דברים ז ה) \"כִּי אִם כֹּה תַעֲשׂוּ לָהֶם\" וְגוֹ'. וּבְאֶרֶץ יִשְׂרָאֵל מִצְוָה לִרְדֹּף אַחֲרֶיהָ עַד שֶׁנְּאַבֵּד אוֹתָהּ מִכָּל אַרְצֵנוּ. אֲבָל בְּחוּץ לָאָרֶץ אֵין אָנוּ מְצֻוִּין לִרְדֹּף אַחֲרֶיהָ אֶלָּא כָּל מָקוֹם שֶׁנִּכְבּשׁ אוֹתוֹ נְאַבֵּד כָּל עֲבוֹדַת כּוֹכָבִים שֶׁבּוֹ. שֶׁנֶּאֱמַר (דברים יב ג) \"וְאִבַּדְתֶּם אֶת שְׁמָם מִן הַמָּקוֹם הַהוּא\". בְּאֶרֶץ יִשְׂרָאֵל אַתָּה מְצֻוֶּה לִרְדֹּף אַחֲרֵיהֶן וְאִי אַתָּה מְצֻוֶּה לִרְדֹּף אַחֲרֵיהֶן בְּחוּץ לָאָרֶץ:","עֲבוֹדַת כּוֹכָבִים וּמְשַׁמְּשֶׁיהָ וְתִקְרֹבֶת שֶׁלָּהּ וְכָל הַנַּעֲשֶׂה בִּשְׁבִילָהּ אָסוּר בַּהֲנָאָה שֶׁנֶּאֱמַר (דברים ז כו) \"וְלֹא תָבִיא תוֹעֵבָה אֶל בֵּיתֶךָ\" וְכָל הַנֶּהֱנֶה בְּאֶחָד מִכָּל אֵלּוּ לוֹקֶה שְׁתַּיִם. אַחַת מִשּׁוּם וְלֹא תָבִיא. וְאַחַת מִשּׁוּם וְלֹא יִדְבַּק בְּיָדְךָ מְאוּמָה מִן הַחֵרֶם:","בְּהֵמָה שֶׁהִקְרִיבוּהָ כֻּלָּהּ לַעֲבוֹדַת כּוֹכָבִים אֲסוּרָה בַּהֲנָאָה אֲפִלּוּ פִּרְשָׁהּ וְעַצְמוֹתֶיהָ וְקַרְנֶיהָ וּטְלָפֶיהָ וְעוֹרָהּ הַכּל אָסוּר בַּהֲנָאָה. לְפִיכָךְ אִם הָיָה בָּעוֹר סִימָן שֶׁיּוֹדֵעַ בּוֹ שֶׁזֶּה הָעוֹר תִּקְרֹבֶת עֲבוֹדַת כּוֹכָבִים הוּא כְּגוֹן שֶׁהָיוּ עוֹשִׂים שֶׁקּוֹרְעִים קֶרַע עָגֹל כְּנֶגֶד הַלֵּב וּמוֹצִיאִין הַלֵּב הֲרֵי כָּל אוֹתָן הָעוֹרוֹת שֶׁהֵן כָּךְ אֲסוּרִין בַּהֲנָאָה וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מַה בֵּין עֲבוֹדַת כּוֹכָבִים שֶׁל עוֹבֵד כּוֹכָבִים לַעֲבוֹדַת כּוֹכָבִים שֶׁל יִשְׂרָאֵל. עֲבוֹדַת כּוֹכָבִים שֶׁל עוֹבֵד כּוֹכָבִים אֲסוּרָה בַּהֲנָאָה מִיָּד שֶׁנֶּאֱמַר (דברים ז כה) \"פְּסִילֵי אֱלֹהֵיהֶם תִּשְׂרְפוּן בָּאֵשׁ\" מִשֶּׁפְּסָלוֹ נַעֲשָׂה לוֹ אֱלוֹהַּ. וְשֶׁל יִשְׂרָאֵל אֵינָהּ אֲסוּרָה בַּהֲנָאָה עַד שֶׁתֵּעֲבֵד שֶׁנֶּאֱמַר (דברים כז טו) \"וְשָׂם בַּסָּתֶר\" עַד שֶׁיַּעֲשֶׂה לָהּ דְּבָרִים שֶׁבַּסֵּתֶר שֶׁהֵן עֲבוֹדָתָהּ. וּמְשַׁמְּשֵׁי עֲבוֹדַת כּוֹכָבִים בֵּין שֶׁל עוֹבֵד כּוֹכָבִים בֵּין שֶׁל יִשְׂרָאֵל אֵינָן אֲסוּרִין עַד שֶׁיִּשְׁתַּמְּשׁוּ בָּהֶן לַעֲבוֹדַת כּוֹכָבִים:","הָעוֹשֶׂה עֲבוֹדַת כּוֹכָבִים לַאֲחֵרִים אַף עַל פִּי שֶׁהוּא לוֹקֶה שְׂכָרוֹ מֻתָּר וַאֲפִלּוּ עֲשָׂאָהּ לְעוֹבֵד כּוֹכָבִים שֶׁהִיא אֲסוּרָה מִיָּד. מִפְּנֵי שֶׁאֵינָהּ נֶאֱסֶרֶת עַד שֶׁתִּגָּמֵר וּמַכּוֹשׁ אַחֲרוֹן שֶׁגּוֹמְרָהּ אֵין בּוֹ שְׁוֵה פְּרוּטָה. הַלּוֹקֵחַ גְּרוּטָאוֹת מִן הָעוֹבֵד כּוֹכָבִים וּמָצָא בָּהֶן עֲבוֹדַת כּוֹכָבִים. אִם נָתַן מָעוֹת וְלֹא מָשַׁךְ יַחֲזִירֵם לָעוֹבֵד כּוֹכָבִים. וְכֵן אִם מָשַׁךְ וְלֹא נָתַן מָעוֹת אַף עַל פִּי שֶׁמְּשִׁיכָה בְּעוֹבֵד כּוֹכָבִים קוֹנָה כְּמֶקַח טָעוּת הוּא. נָתַן מָעוֹת וּמָשַׁךְ יוֹלִיכֵם לְיָם הַמֶּלַח. וְכֵן עוֹבֵד כּוֹכָבִים וְגֵר שֶׁיָּרְשׁוּ אֶת אֲבִיהֶן עוֹבֵד כּוֹכָבִים יָכוֹל הַגֵּר לוֹמַר לְעוֹבֵד כּוֹכָבִים טֹל אַתָּה עֲבוֹדַת כּוֹכָבִים וַאֲנִי מָעוֹת. טֹל אַתָּה יֵין נֶסֶךְ וַאֲנִי פֵּרוֹת. וְאִם מִשֶּׁבָּאוּ לִרְשׁוּת הַגֵּר אָסוּר:","צוּרוֹת שֶׁעֲשָׂאוּם עוֹבְדֵי כּוֹכָבִים לְנוֹי מֻתָּרִין בַּהֲנָאָה וְצוּרוֹת שֶׁעֲשָׂאוּם לַעֲבוֹדַת כּוֹכָבִים אֲסוּרִין. כֵּיצַד. כָּל הַצּוּרוֹת הַנִּמְצָאִים בַּכְּפָרִים אֲסוּרִים בַּהֲנָאָה מִפְּנֵי שֶׁחֶזְקָתָן שֶׁלַּעֲבוֹדַת כּוֹכָבִים הֵן עֲשׂוּיִין, וְהַנִּמְצָאוֹת בַּמְּדִינָה אִם הָיוּ עוֹמְדִין עַל פֶּתַח הַמְּדִינָה וְהָיָה בְּיַד הַצּוּרָה צוּרַת מַקֵּל אוֹ צִפּוֹר אוֹ כַּדּוּר אוֹ סַיִף אוֹ עֲטָרָה וְטַבַּעַת חֶזְקָתוֹ שֶׁהוּא לַעֲבוֹדַת כּוֹכָבִים וְאָסוּר בַּהֲנָאָה. וְאִם לָאו הֲרֵי הוּא בְּחֶזְקַת לְנוֹי וּמֻתָּר:","צַלְמֵי עֲבוֹדַת כּוֹכָבִים הַנִּמְצָאִים מֻשְׁלָכִים בַּשְּׁוָקִים אוֹ בְּתוֹךְ הַגְּרוּטָאוֹת הֲרֵי אֵלּוּ מֻתָּרִין וְאֵין צָרִיךְ לוֹמַר שִׁבְרֵי צַלְמֵיהֶן. אֲבָל הַמּוֹצֵא יָד מִצּוּרַת כּוֹכָב אוֹ מַזָּל אוֹ רַגְלָהּ אוֹ אֵיבָר מֵאֵיבָרֶיהָ מֻשְׁלָךְ הֲרֵי זֶה אָסוּר בַּהֲנָאָה הוֹאִיל וְיָדַע בְּוַדַּאי שֶׁזֶּה הָאֵיבָר מִן צוּרַת עֲבוֹדַת כּוֹכָבִים הַנֶּעֱבֶדֶת הֲרֵי הִיא בְּאִסּוּרָהּ עַד שֶׁיִּוָדַּע לוֹ שֶׁהָעוֹבְדֵי כּוֹכָבִים עוֹבְדֶיהָ בִּטְּלוּהָ:","הַמּוֹצֵא כֵּלִים וַעֲלֵיהֶן צוּרַת חַמָּה וּלְבָנָה וּדְרָקוֹן. אִם הָיוּ כְּלֵי כֶּסֶף וְזָהָב אוֹ בִּגְדֵי שָׁנִי אוֹ שֶׁהָיוּ חֲקוּקִים עַל הַנְּזָמִים וְעַל הַטַּבָּעוֹת הֲרֵי אֵלּוּ אֲסוּרִין. וְעַל שְׁאָר הַכֵּלִים מֻתָּרִין מִפְּנֵי שֶׁחֶזְקָתָן לְנוֹי. וְכֵן שְׁאָר הַצּוּרוֹת הַנִּמְצָאוֹת עַל כָּל הַכֵּלִים חֶזְקָתָן לְנוֹי וּמֻתָּרִין:","עֲבוֹדַת כּוֹכָבִים וּמְשַׁמְּשֶׁיהָ וְכָל הַתִּקְרֹבֶת שֶׁלָּהּ אוֹסְרִים בְּכָל שֶׁהֵן. כֵּיצַד. עֲבוֹדַת כּוֹכָבִים שֶׁנִּתְעָרְבָה בְּצוּרוֹת שֶׁל נוֹי אֲפִלּוּ אַחַת בְּכַמָּה אֲלָפִים יוֹלִיךְ הַכּל לְיָם הַמֶּלַח. וְכֵן אִם נִתְעָרֵב כּוֹס שֶׁל עֲבוֹדַת כּוֹכָבִים בְּכַמָּה כּוֹסוֹת אוֹ חֲתִיכָה מִן הַבָּשָׂר (שֶׁנִּתְעָרְבָה) בְּכַמָּה חֲתִיכוֹת יוֹלִיךְ הַכּל לְיָם הַמֶּלַח. וְכֵן עוֹר לָבוּב שֶׁנִּתְעָרֵב בְּכַמָּה עוֹרוֹת הַכּל אָסוּר בַּהֲנָאָה. עָבַר וּמָכַר עֲבוֹדַת כּוֹכָבִים אוֹ אֶחָד מִמְּשַׁמְּשֶׁיהָ אוֹ תִּקְרֹבֶת שֶׁלָּהּ הֲרֵי הַדָּמִים אֲסוּרִין בַּהֲנָאָה וְאוֹסְרִין בְּכָל שֶׁהֵן כַּעֲבוֹדַת כּוֹכָבִים שֶׁנֶּאֱמַר (דברים ז כו) \"וְהָיִיתָ חֵרֶם כָּמֹהוּ\" כָּל מַה שֵּׁאַתָּה מֵבִיא מֵעֲבוֹדַת כּוֹכָבִים וּמִכָּל מְשַׁמְּשֶׁיהָ וְתִקְרָבְתָּהּ הֲרֵי הִיא כָּמוֹהָ:","עֲבוֹדַת כּוֹכָבִים אוֹ אֲשֵׁרָה שֶׁנִּשְׂרְפָה אֶפְרָהּ אָסוּר בַּהֲנָאָה. וְגַחֶלֶת שֶׁל עֲבוֹדַת כּוֹכָבִים אֲסוּרָה וְהַשַּׁלְהֶבֶת מֻתֶּרֶת מִפְּנֵי שֶׁאֵין בָּהּ מַמָּשׁ. סְפֵק עֲבוֹדַת כּוֹכָבִים אָסוּר, סְפֵק סְפֵקָהּ מֻתָּר. כֵּיצַד. כּוֹס שֶׁל עֲבוֹדַת כּוֹכָבִים שֶׁנָּפַל בְּאוֹצָר מָלֵא כּוֹסוֹת כֻּלָּן אֲסוּרִים, מִפְּנֵי שֶׁעֲבוֹדַת כּוֹכָבִים וְכָל מְשַׁמְּשֶׁיהָ אוֹסְרִין בְּכָל שֶׁהֵן. פֵּרַשׁ כּוֹס אֶחָד מִן הַתַּעֲרֹבֶת וְנָפַל לְכוֹסוֹת שְׁנַיִם הֲרֵי אֵלּוּ מֻתָּרִין. טַבַּעַת שֶׁל עֲבוֹדַת כּוֹכָבִים שֶׁנִּתְעָרְבָה בְּכַמָּה טַבָּעוֹת וְנָפְלוּ שְׁתַּיִם מֵהֶן לַיָּם הַגָּדוֹל הֻתְּרוּ כֻּלָּן שֶׁאֲנִי אוֹמֵר אוֹתָהּ הַטַּבַּעַת הָיְתָה בִּכְלַל הַשְּׁתַּיִם. נִתְעָרְבָה בְּמֵאָה וְנִתְחַלְּקוּ אַרְבָּעִים לְמָקוֹם אֶחָד וְשִׁשִּׁים לְמָקוֹם אַחֵר וְנָפְלוּ הָאַרְבָּעִים כֻּלָּן לְטַבָּעוֹת אֲחֵרוֹת כֻּלָּן מֻתָּרוֹת שֶׁאֲנִי אוֹמֵר אוֹתָהּ הַטַּבַּעַת הָאֲסוּרָה בָּרֹב הִיא. נָפְלוּ הַשִּׁשִּׁים לְטַבָּעוֹת אֲחֵרוֹת כֻּלָּן אֲסוּרוֹת:","הָאֲשֵׁרָה בֵּין שֶׁהָיְתָה נֶעֱבֶדֶת בֵּין שֶׁהָיְתָה עֲבוֹדַת כּוֹכָבִים מֻנַּחַת תַּחְתֶּיהָ אָסוּר לֵישֵׁב בְּצֵל קוֹמָתָהּ. וּמֻתָּר לֵישֵׁב בְּצֵל הַשָּׂרִיגִים וְהֶעָלִים שֶׁלָּהּ. וְאִם יֵשׁ לוֹ דֶּרֶךְ אַחֶרֶת אָסוּר לוֹ לַעֲבֹר תַּחְתֶּיהָ. וְאִם אֵין שָׁם דֶּרֶךְ אַחֶרֶת עוֹבֵר תַּחְתֶּיהָ כְּשֶׁהוּא רָץ:","אֶפְרוֹחִים שֶׁקִּנְּנוּ בָּהּ וְאֵין צְרִיכִין לְאִמָּן מֻתָּרִין. וְהָאֶפְרוֹחִים וְהַבֵּיצִים שֶׁצְּרִיכִין לְאִמָּן אֲסוּרִין שֶׁהֲרֵי הָאֲשֵׁרָה כְּמוֹ בָּסִיס לָהֶן. וְהַקֵּן עַצְמָהּ שֶׁבְּרֹאשָׁהּ מֻתָּר מִפְּנֵי שֶׁהָעוֹף מֵבִיא עֵצָיו מִמָּקוֹם אַחֵר:","נָטַל מִמֶּנָּה עֵצִים אֲסוּרִים בַּהֲנָאָה. הֵסִיק בָּהֶן אֶת הַתַּנּוּר יוּצָן וְאַחַר כָּךְ יַסִּיק בְּעֵצִים אֲחֵרִים שֶׁל הֶתֵּר וְיֹאפֶה בּוֹ. אָפָה בּוֹ אֶת הַפַּת וְלֹא צִנְּנוֹ הַפַּת אֲסוּרָה בַּהֲנָאָה. נִתְעָרְבָה בַּאֲחֵרוֹת יוֹלִיךְ דְּמֵי אוֹתָהּ הַפַּת לְיָם הַמֶּלַח כְּדֵי שֶׁלֹּא יֵהָנֶה בָּהּ וּשְׁאָר הַכִּכָּרוֹת מֻתָּרִין:","נָטַל מִמֶּנָּה כַּרְכַּר וְאָרַג בּוֹ אֶת הַבֶּגֶד אָסוּר בַּהֲנָאָה. נִתְעָרֵב בִּבְגָדִים אֲחֵרִים יוֹלִיךְ דְּמֵי אוֹתוֹ הַבֶּגֶד לְיָם הַמֶּלַח וּשְׁאָר כָּל הַבְּגָדִים מֻתָּרִין. וּמֻתָּר לִטַּע תַּחְתֶּיהָ יְרָקוֹת בֵּין בִּימוֹת הַחַמָּה שֶׁהֵן צְרִיכִין לְצֵל. בֵּין בִּימוֹת הַגְּשָׁמִים. מִפְּנֵי שֶׁצֵּל הָאֲשֵׁרָה שֶׁהוּא אָסוּר עִם הַקַּרְקַע שֶׁאֵינָהּ נֶאֱסֶרֶת גּוֹרְמִין לִירָקוֹת אֵלּוּ לִצְמֹחַ וְכָל שֶׁדָּבָר אָסוּר וְדָבָר מֻתָּר גּוֹרְמִין לוֹ הֲרֵי זֶה מֻתָּר בְּכָל מָקוֹם. לְפִיכָךְ שָׂדֶה שֶׁזִּבְּלָהּ בְּזֶבֶל עֲבוֹדַת כּוֹכָבִים מֻתָּר לִזְרֹעַ אוֹתָהּ. וּפָרָה שֶׁפִּטְּמָהּ בְּכַרְשִׁינֵי עֲבוֹדַת כּוֹכָבִים תֵּאָכֵל וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","בָּשָׂר אוֹ יַיִן אוֹ פֵּרוֹת שֶׁהֱכִינוּם לְהַקְרִיבָם לַעֲבוֹדַת כּוֹכָבִים לֹא נֶאֶסְרוּ בַּהֲנָאָה אַף עַל פִּי שֶׁהִכְנִיסוּם לְבֵית עֲבוֹדַת כּוֹכָבִים עַד שֶׁיַּקְרִיבוּם לְפָנֶיהָ. הִקְרִיבוּם לְפָנֶיהָ נַעֲשׂוּ תִּקְרֹבֶת וְאַף עַל פִּי שֶׁחָזְרוּ וְהוֹצִיאוּם הֲרֵי אֵלּוּ אֲסוּרִין לְעוֹלָם. וְכָל הַנִּמְצָא בְּבֵית עֲבוֹדַת כּוֹכָבִים אֲפִלּוּ מַיִם וּמֶלַח אָסוּר בַּהֲנָאָה מִן הַתּוֹרָה. וְהָאוֹכֵל מִמֶּנּוּ כָּל שֶׁהוּא לוֹקֶה:","הַמּוֹצֵא כְּסוּת וְכֵלִים וּמָעוֹת בְּרֹאשׁ עֲבוֹדַת כּוֹכָבִים. אִם מְצָאָן דֶּרֶךְ בִּזָּיוֹן הֲרֵי אֵלּוּ מֻתָּרִין וְאִם מְצָאָן דֶּרֶךְ כָּבוֹד הֲרֵי אֵלּוּ אֲסוּרִין. כֵּיצַד. מָצָא כִּיס תָּלוּי בְּצַוָּארוֹ. כְּסוּת מְקֻפֶּלֶת וּמֻנַּחַת עַל רֹאשׁוֹ. כְּלִי כָּפוּי עַל רֹאשׁוֹ הֲרֵי זֶה מֻתָּר מִפְּנֵי שֶׁהוּא דֶּרֶךְ בִּזָּיוֹן וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. מָצָא בְּרֹאשׁוֹ דָּבָר שֶׁכַּיּוֹצֵא בּוֹ קָרֵב לְגַבֵּי הַמִּזְבֵּחַ הֲרֵי זֶה אָסוּר. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁמְּצָאָן חוּץ לִמְקוֹם עֲבוֹדָתוֹ אֲבָל אִם מְצָאוֹ בִּפְנִים בֵּין דֶּרֶךְ כָּבוֹד בֵּין דֶּרֶךְ בִּזָּיוֹן בֵּין דָּבָר הָרָאוּי לַמִּזְבֵּחַ בֵּין דָּבָר שֶׁאֵינוֹ רָאוּי כָּל הַנִּמְצָא בִּפְנִים אָסוּר אֲפִלּוּ מַיִם וּמֶלַח. וּפְעוֹר וּמַרְקוּלִיס כָּל הַנִּמְצָא עִמָּהֶן בֵּין בִּפְנִים בֵּין בַּחוּץ אָסוּר בַּהֲנָאָה. וְכֵן אַבְנֵי מַרְקוּלִיס אֶבֶן הַנִּרְאֵית שֶׁהִיא עִמּוֹ אָסוּר בַּהֲנָאָה:","עֲבוֹדַת כּוֹכָבִים שֶׁהָיָה לָהּ מֶרְחָץ אוֹ גִּנָּה נֶהֱנִים בָּהֶם שֶׁלֹּא בְּטוֹבָה וְאֵין נֶהֱנִים בָּהֶם בְּטוֹבָה. הָיָה לָהּ וְלַאֲחֵרִים נֶהֱנִין בָּהֶן אֲפִלּוּ בְּטוֹבַת כֹּהֲנֶיהָ וּבִלְבַד שֶׁלֹּא יִתֵּן שָׂכָר:","מֶרְחָץ שֶׁיֵּשׁ בָּהּ עֲבוֹדַת כּוֹכָבִים מֻתָּר לִרְחֹץ בָּהּ מִפְּנֵי שֶׁהִיא נַעֲשֵׂית שָׁם לְנוֹי וְלֹא לְעָבְדָהּ. שֶׁנֶּאֱמַר אֱלֹהֵיהֶם. בִּזְמַן שֶׁנּוֹהֲגִים בָּהּ מִנְהַג אֱלֹהוּת וְלֹא בִּזְמַן שֶׁמְּבַזִּין אוֹתָן כְּגוֹן זוֹ שֶׁהִיא עוֹמֶדֶת עַל הַבִּיב וְהַכּל מַשְׁתִּינִין בְּפָנֶיהָ. וְאִם הָיְתָה דֶּרֶךְ עֲבוֹדָתָהּ בְּכָךְ אָסוּר לִכָּנֵס בּוֹ:","סַכִּין שֶׁל עֲבוֹדַת כּוֹכָבִים שֶׁשָּׁחַט בָּהּ הֲרֵי זֶה מֻתָּר מִפְּנֵי שֶׁהוּא מְקַלְקֵל. וְאִם הָיְתָה בְּהֵמָה מְסֻכֶּנֶת הֲרֵי זוֹ אֲסוּרָה מִפְּנֵי שֶׁהוּא מְתַקֵּן וַהֲרֵי זֶה הַתִּקּוּן מֵהֲנָאַת מְשַׁמְּשֵׁי עֲבוֹדַת כּוֹכָבִים. וְכֵן אָסוּר לַחְתֹּךְ בָּהּ בָּשָׂר מִפְּנֵי שֶׁהוּא מְתַקֵּן וְאִם חָתַךְ דֶּרֶךְ הֶפְסֵד וְהַשְׁחָתָה מֻתָּר:"],"Mishneh Torah, Foundations of the Torah 9":["דָּבָר בָּרוּר וּמְפֹרָשׁ בַּתּוֹרָה שֶׁהִיא מִצְוָה עוֹמֶדֶת לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים אֵין לָהּ לֹא שִׁנּוּי וְלֹא גֵּרָעוֹן וְלֹא תּוֹסֶפֶת שֶׁנֶּאֱמַר (דברים יג א) \"אֵת כָּל הַדָּבָר אֲשֶׁר אָנֹכִי מְצַוֶּה אֶתְכֶם אֹתוֹ תִשְׁמְרוּן לַעֲשׂוֹת לֹא תֹסֵף עָלָיו וְלֹא תִגְרַע מִמֶּנּוּ\". וְנֶאֱמַר (דברים כט כח) \"וְהַנִּגְלֹת לָנוּ וּלְבָנֵינוּ עַד עוֹלָם לַעֲשׂוֹת אֶת כָּל דִּבְרֵי הַתּוֹרָה הַזֹּאת\". הָא לָמַדְתָּ שֶׁכָּל דִּבְרֵי תּוֹרָה מְצֻוִּין אָנוּ לַעֲשׂוֹתָן עַד עוֹלָם. וְכֵן הוּא אוֹמֵר חֻקַּת עוֹלָם לְדֹרֹתֵיכֶם. וְנֶאֱמַר (דברים ל יב) \"לֹא בַשָּׁמַיִם הִיא\". הָא לָמַדְתָּ שֶׁאֵין נָבִיא רַשַּׁאי לְחַדֵּשׁ דָּבָר מֵעַתָּה. לְפִיכָךְ אִם יַעֲמֹד אִישׁ בֵּין מִן הָאֻמּוֹת בֵּין מִיִּשְׂרָאֵל וְיַעֲשֶׂה אוֹת וּמוֹפֵת וְיֹאמַר שֶׁה' שְׁלָחוֹ לְהוֹסִיף מִצְוָה אוֹ לִגְרֹעַ מִצְוָה אוֹ לְפָרֵשׁ בְּמִצְוָה מִן הַמִּצְוֹת פֵּרוּשׁ שֶׁלֹּא שָׁמַעְנוּ מִמּשֶׁה. אוֹ שֶׁאָמַר שֶׁאוֹתָן הַמִּצְוֹת שֶׁנִּצְטַוּוּ בָּהֶן יִשְׂרָאֵל אֵינָן לְעוֹלָם וּלְדוֹרֵי דּוֹרוֹת אֶלָּא מִצְוֹת לְפִי זְמַן הָיוּ. הֲרֵי זֶה נְבִיא שֶׁקֶר שֶׁהֲרֵי בָּא לְהַכְחִישׁ נְבוּאָתוֹ שֶׁל משֶׁה. וּמִיתָתוֹ בְּחֶנֶק עַל שֶׁהֵזִיד לְדַבֵּר בְּשֵׁם ה' אֲשֶׁר לֹא צִוָּהוּ. שֶׁהוּא בָּרוּךְ שְׁמוֹ צִוָּה לְמשֶׁה שֶׁהַמִּצְוָה הַזֹּאת לָנוּ וּלְבָנֵינוּ עַד עוֹלָם (במדבר כג יט) וְ\"לֹא אִישׁ אֵל וִיכַזֵּב\":","אִם כֵּן לָמָּה נֶאֱמַר בַּתּוֹרָה (דברים יח יח) \"נָבִיא אָקִים לָהֶם מִקֶּרֶב אֲחֵיהֶם כָּמוֹךָ\". לֹא לַעֲשׂוֹת דָּת הוּא בָּא אֶלָּא לְצַוּוֹת עַל דִּבְרֵי הַתּוֹרָה וּלְהַזְהִיר הָעָם שֶׁלֹּא יַעַבְרוּ עָלֶיהָ. כְּמוֹ שֶׁאָמַר הָאַחֲרוֹן שֶׁבָּהֶן (מלאכי ג כב) \"זִכְרוּ תּוֹרַת משֶׁה עַבְדִּי\". וְכֵן אִם צִוָּנוּ בְּדִבְרֵי הָרְשׁוּת כְּגוֹן לְכוּ לְמָקוֹם פְּלוֹנִי אוֹ אַל תֵּלְכוּ. עֲשׂוּ מִלְחָמָה הַיּוֹם אוֹ אַל תַּעֲשׂוּ. בְּנוּ חוֹמָה זוֹ אוֹ אַל תִּבְנוּהָ. מִצְוָה לִשְׁמֹעַ לוֹ. וְהָעוֹבֵר עַל דְּבָרָיו חַיָּב מִיתָה בִּידֵי שָׁמַיִם שֶׁנֶּאֱמַר (דברים יח יט) \"וְהָיָה הָאִישׁ אֲשֶׁר לֹא יִשְׁמַע אֶל דְּבָרַי אֲשֶׁר יְדַבֵּר בִּשְׁמִי אָנֹכִי אֶדְרשׁ מֵעִמּוֹ\":","וְכֵן נָבִיא שֶׁעָבַר עַל דִּבְרֵי עַצְמוֹ וְהַכּוֹבֵשׁ נְבוּאָתוֹ חַיָּב מִיתָה בִּידֵי שָׁמַיִם וּבִשְׁלָשְׁתָּן נֶאֱמַר (דברים יח יט) \"אָנֹכִי אֶדְרשׁ מֵעִמּוֹ\". וְכֵן אִם יֹאמַר לָנוּ הַנָּבִיא שֶׁנּוֹדַע לָנוּ שֶׁהוּא נָבִיא לַעֲבֹר עַל אַחַת מִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה אוֹ עַל מִצְוֹת הַרְבֵּה בֵּין קַלּוֹת בֵּין חֲמוּרוֹת לְפִי שָׁעָה מִצְוָה לִשְׁמֹעַ לוֹ. וְכֵן לָמַדְנוּ מֵחֲכָמִים רִאשׁוֹנִים מִפִּי הַשְּׁמוּעָה בְּכָל אִם יֹאמַר לְךָ הַנָּבִיא עֲבֹר עַל דִּבְרֵי תּוֹרָה כְּאֵלִיָּהוּ בְּהַר הַכַּרְמֶל שְׁמַע לוֹ חוּץ מֵעֲבוֹדַת כּוֹכָבִים. וְהוּא שֶׁיִּהְיֶה הַדָּבָר לְפִי שָׁעָה. כְּגוֹן אֵלִיָּהוּ בְּהַר הַכַּרְמֶל שֶׁהִקְרִיב עוֹלָה בַּחוּץ וִירוּשָׁלַיִם נִבְחֶרֶת לְכָךְ וְהַמַּקְרִיב בַּחוּץ חַיָּב כָּרֵת. וּמִפְּנֵי שֶׁהוּא נָבִיא מִצְוָה לִשְׁמֹעַ לוֹ וְגַם בָּזֶה נֶאֱמַר (דברים יח טו) \"אֵלָיו תִּשְׁמָעוּן\". וְאִלּוּ שָׁאֲלוּ אֶת אֵלִיָּהוּ וְאָמְרוּ לוֹ הֵיאַךְ נַעֲקֹר מַה שֶּׁכָּתוּב בַּתּוֹרָה (דברים יב יג) \"פֶּן תַּעֲלֶה עלֹתֶיךָ בְּכָל מָקוֹם\". הָיָה אוֹמֵר לֹא נֶאֱמַר אֶלָּא הַמַּקְרִיב בַּחוּץ לְעוֹלָם חַיָּב כָּרֵת כְּמוֹ שֶׁצִּוָּה משֶׁה. אֲבָל אֲנִי אַקְרִיב הַיּוֹם בַּחוּץ בִּדְבַר ה' כְּדֵי לְהַכְחִישׁ נְבִיאֵי הַבַּעַל. וְעַל הַדֶּרֶךְ הַזֹּאת אִם צִוּוּ כָּל הַנְּבִיאִים לַעֲבֹר לְפִי שָׁעָה מִצְוָה לִשְׁמֹעַ לָהֶם. וְאִם אָמְרוּ שֶׁהַדָּבָר נֶעֱקַר לְעוֹלָם מִיתָתוֹ בְּחֶנֶק שֶׁהַתּוֹרָה אָמְרָה (דברים כט כח) \"לָנוּ וּלְבָנֵינוּ עַד עוֹלָם\":","וְכֵן אִם עָקַר דָּבָר מִדְּבָרִים שֶׁלָּמַדְנוּ מִפִּי הַשְּׁמוּעָה אוֹ שֶׁאָמַר בְּדִין מִדִּינֵי תּוֹרָה שֶׁה' צִוָּה לוֹ שֶׁהַדִּין כָּךְ הוּא וַהֲלָכָה כְּדִבְרֵי פְּלוֹנִי הֲרֵי זֶה נְבִיא הַשֶּׁקֶר וְיֵחָנֵק. אַף עַל פִּי שֶׁעָשָׂה אוֹת. שֶׁהֲרֵי בָּא לְהַכְחִישׁ הַתּוֹרָה שֶׁאָמְרָה (דברים ל יב) \"לֹא בַשָּׁמַיִם הִיא\". אֲבָל לְפִי שָׁעָה שׁוֹמְעִין לוֹ בַּכּל:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר מִצְוֹת. אֲבָל בַּעֲבוֹדַת כּוֹכָבִים אֵין שׁוֹמְעִין לוֹ וַאֲפִלּוּ לְפִי שָׁעָה. וַאֲפִלּוּ עָשָׂה אוֹתוֹת וּמוֹפְתִים גְּדוֹלִים וְאָמַר שֶׁה' צִוָּהוּ שֶׁתֵּעָבֵד עֲבוֹדַת כּוֹכָבִים הַיּוֹם בִּלְבַד אוֹ בְּשָׁעָה זוֹ בִּלְבַד הֲרֵי זֶה דִּבֵּר סָרָה עַל ה'. וְעַל זֶה צִוָּה הַכָּתוּב וְאָמַר (דברים יג ג) \"וּבָא הָאוֹת וְהַמּוֹפֵת\" (דברים יג ד) \"לֹא תִּשְׁמַע אֶל דִּבְרֵי הַנָּבִיא הַהוּא\" (דברים יג ו) \"כִּי דִּבֵּר סָרָה עַל ה' אֱלֹהֵיכֶם\". שֶׁהֲרֵי בָּא לְהַכְחִישׁ נְבוּאָתוֹ שֶׁל משֶׁה. וּלְפִיכָךְ נֵדַע בְּוַדַּאי שֶׁהוּא נְבִיא שֶׁקֶר וְכָל מַה שֶּׁעָשָׂה בְּלָט וְכִשּׁוּף עָשָׂה וְיֵחָנֵק:"],"Mishneh Torah, Gifts to the Poor 8":["הַצְדָקָה הֲרֵי הִיא בִּכְלַל הַנְּדָרִים. לְפִיכָךְ הָאוֹמֵר הֲרֵי עָלַי סֶלַע לִצְדָקָה אוֹ הֲרֵי סֶלַע זוֹ צְדָקָה חַיָּב לִתְּנָהּ לָעֲנִיִּים מִיָּד וְאִם אִחֵר עָבַר בְּ (דברים כג כב) \"בַל תְּאַחֵר\" שֶׁהֲרֵי בְּיָדוֹ לִתֵּן מִיָּד וַעֲנִיִּים מְצוּיִין הֵן. אֵין שָׁם עֲנִיִּים מַפְרִישׁ וּמַנִּיחַ עַד שֶׁיִּמְצָא עֲנִיִּים. וְאִם הִתְנָה שֶׁלֹּא יִתֵּן עַד שֶׁיִּמְצָא עָנִי אֵינוֹ צָרִיךְ לְהַפְרִישׁ. וְכֵן אִם הִתְנָה בְּשָׁעָה שֶׁנָּדַר בִּצְדָקָה אוֹ הִתְנַדֵּב אוֹתוֹ שֶׁיִּהְיוּ הַגַּבָּאִין רַשָּׁאִין לְשַׁנּוֹתָהּ וּלְצָרְפָהּ בְּזָהָב הֲרֵי אֵלּוּ מֻתָּרִין:","הַמַּתְפִּיס בִּצְדָקָה חַיָּב כִּשְׁאָר הַנְּדָרִים. כֵּיצַד. אָמַר הֲרֵי סֶלַע זוֹ כְּזוֹ הֲרֵי זוֹ צְדָקָה. הַמַּפְרִישׁ סֶלַע וְאָמַר הֲרֵי זוֹ צְדָקָה וְלָקַח סֶלַע שְׁנִיָּה וְאָמַר וְזוֹ הֲרֵי שְׁנִיָּה צְדָקָה. וְאַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ:","הַנּוֹדֵר צְדָקָה וְלֹא יָדַע כַּמָּה נָדַר יִתֵּן עַד שֶׁיֹּאמַר לֹא לְכָךְ נִתְכַּוַּנְתִּי:","אֶחָד הָאוֹמֵר סֶלַע זוֹ צְדָקָה אוֹ הָאוֹמֵר הֲרֵי עָלַי סֶלַע לִצְדָקָה וְהִפְרִישׁוֹ. אִם רָצָה לְשַׁנּוֹתוֹ בְּאַחֵר מֻתָּר. וְאִם מִשֶּׁהִגִּיעַ לְיַד הַגַּבַּאי אָסוּר לְשַׁנּוֹתוֹ. וְאִם רָצוּ הַגַּבָּאִים לְצָרֵף הַמָּעוֹת וְלַעֲשׂוֹתָן דִּינָרִין אֵינָן רַשָּׁאִין אֶלָּא אִם אֵין שָׁם עֲנִיִּים לְחַלֵּק מְצָרְפִין לַאֲחֵרִים. אֲבָל לֹא לְעַצְמָן:","הָיָה לַעֲנִיִּים הֲנָאָה בְּעִכּוּב הַמָּעוֹת בְּיַד הַגַּבַּאי כְּדֵי לַעֲשׂוֹת לַאֲחֵרִים לִתֵּן. הֲרֵי אוֹתוֹ הַגַּבַּאי מֻתָּר לִלְווֹת אוֹתָם הַמָּעוֹת שֶׁל עֲנִיִּים וּפוֹרֵעַ. שֶׁהַצְּדָקָה אֵינָהּ כְּהֶקְדֵּשׁ שֶׁאָסוּר לֵהָנוֹת בּוֹ:","מִי שֶׁהִתְנַדֵּב מְנוֹרָה אוֹ נֵר לְבֵית הַכְּנֶסֶת אָסוּר לְשַׁנּוֹתָהּ. וְאִם לִדְבַר מִצְוָה מֻתָּר לְשַׁנּוֹתָהּ. אַף עַל פִּי שֶׁלֹּא נִשְׁתַּקַּע שֵׁם בְּעָלֶיהָ מֵעָלֶיהָ. אֶלָּא אוֹמְרִים זוֹ הַמְּנוֹרָה אוֹ נֵר שֶׁל פְּלוֹנִי. וְאִם נִשְׁתַּקַּע שֵׁם הַבְּעָלִים מֵעָלֶיהָ מֻתָּר לְשַׁנּוֹתָהּ אֲפִלּוּ לִדְבַר הָרְשׁוּת:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה הַמִּתְנַדֵּב יִשְׂרָאֵל. אֲבָל אִם הָיָה עַכּוּ\"ם אָסוּר לְשַׁנּוֹתָהּ אֲפִלּוּ לִדְבַר מִצְוָה עַד שֶׁיִּשְׁתַּקֵּעַ שֵׁם בְּעָלֶיהָ מֵעָלֶיהָ. שֶׁמָּא יֹאמַר הָעַכּוּ\"ם הִקְדַּשְׁתִּי דָּבָר לְבֵית הַכְּנֶסֶת שֶׁל יְהוּדִים וּמְכָרוּהוּ לְעַצְמָן:","עַכּוּ\"ם שֶׁהִתְנַדֵּב לְבֶדֶק הַבַּיִת אֵין מְקַבְּלִין מִמֶּנּוּ לְכַתְּחִלָּה. וְאִם לָקְחוּ מִמֶּנּוּ אֵין מַחְזִירִין לוֹ. הָיָה הַדָּבָר מְסֻיָּם כְּגוֹן קוֹרָה אוֹ אֶבֶן מַחְזִירִין לוֹ כְּדֵי שֶׁלֹּא יְהֵא לָהֶן דָּבָר מְסֻיָּם בַּמִּקְדָּשׁ שֶׁנֶּאֱמַר (עזרא ד ג) \"לֹא לָכֶם וָלָנוּ\" וְגוֹ'. אֲבָל לְבֵית הַכְּנֶסֶת מְקַבְּלִין מֵהֶן לְכַתְּחִלָּה. וְהוּא שֶׁיֹּאמַר כְּדַעַת יִשְׂרָאֵל הִפְרַשְׁתִּי. וְאִם לֹא אָמַר טָעוּן גְּנִיזָה שֶׁמָּא לִבּוֹ לַשָּׁמַיִם. וְאֵין מְקַבְּלִים מֵהֶם לְחוֹמַת יְרוּשָׁלַיִם וְלֹא לְאַמַּת הַמַּיִם שֶׁבָּהּ שֶׁנֶּאֱמַר (נחמיה ב כ) \"וְלָכֶם אֵין חֵלֶק וְזִכָּרוֹן בִּירוּשָׁלָיִם\":","אָסוּר לְיִשְׂרָאֵל לִטּל צְדָקָה מִן הָעַכּוּ\"ם בְּפַרְהֶסְיָא. וְאִם אֵינוֹ יָכוֹל לִחְיוֹת בִּצְדָקָה שֶׁל יִשְׂרָאֵל וְאֵינוֹ יָכוֹל לִטְּלָהּ מִן הָעַכּוּ\"ם בְּצִנְעָה הֲרֵי זֶה מֻתָּר. וּמֶלֶךְ אוֹ שַׂר מִן הָעַכּוּ\"ם שֶׁשָּׁלַח מָמוֹן לְיִשְׂרָאֵל לִצְדָקָה אֵין מַחְזִירִין אוֹתוֹ לוֹ מִשּׁוּם שְׁלוֹם מַלְכוּת. אֶלָּא נוֹטְלִין מִמֶּנּוּ וְיִנָּתֵן לַעֲנִיֵּי עַכּוּ\"ם בַּסֵּתֶר כְּדֵי שֶׁלֹּא יִשְׁמַע הַמֶּלֶךְ:","פִּדְיוֹן שְׁבוּיִים קוֹדֵם לְפַרְנָסַת עֲנִיִּים וְלִכְסוּתָן. וְאֵין לְךָ מִצְוָה גְּדוֹלָה כְּפִדְיוֹן שְׁבוּיִים שֶׁהַשָּׁבוּי הֲרֵי הוּא בִּכְלַל הָרְעֵבִים וְהַצְּמֵאִים וַעֲרוּמִּים וְעוֹמֵד בְּסַכָּנַת נְפָשׁוֹת. וְהַמַּעֲלִים עֵינָיו מִפִּדְיוֹנוֹ הֲרֵי זֶה עוֹבֵר עַל (דברים טו ז) \"לֹא תְאַמֵּץ אֶת לְבָבְךָ וְלֹא תִקְפֹּץ אֶת יָדְךָ\" וְעַל (ויקרא יט טז) \"לֹא תַעֲמֹד עַל דַּם רֵעֶךָ\" וְעַל (ויקרא כה נג) \"לֹא יִרְדֶּנּוּ בְּפֶרֶךְ לְעֵינֶיךָ\". וּבִטֵּל מִצְוַת (דברים טו ח) (דברים טו יא) \"פָתֹחַ תִּפְתַּח אֶת יָדְךָ לוֹ\". וּמִצְוַת (ויקרא כה לו) \"וְחֵי אָחִיךָ עִמָּךְ\". (ויקרא יט יח) \"וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ\". (משלי כד יא) \"וְהַצֵּל לְקֻחִים לַמָּוֶת\" וְהַרְבֵּה דְּבָרִים כָּאֵלּוּ. וְאֵין לְךָ מִצְוָה רַבָּה כְּפִדְיוֹן שְׁבוּיִים:","אַנְשֵׁי הָעִיר שֶׁגָּבוּ מָעוֹת לְבִנְיַן בֵּית הַכְּנֶסֶת וּבָא לָהֶן דְּבַר מִצְוָה מוֹצִיאִין בּוֹ הַמָּעוֹת. קָנוּ אֲבָנִים וְקוֹרוֹת לֹא יִמְכְּרוּם לִדְבַר מִצְוָה אֶלָּא לְפִדְיוֹן שְׁבוּיִים. אַף עַל פִּי שֶׁהֵבִיאוּ אֶת הָאֲבָנִים וּגְדָרוּם וְאֶת הַקּוֹרוֹת וּפְסָלוּם וְהִתְקִינוּ הַכּל לַבִּנְיָן מוֹכְרִין הַכּל לְפִדְיוֹן שְׁבוּיִים בִּלְבַד. אֲבָל אִם בָּנוּ וְגָמְרוּ לֹא יִמְכְּרוּ אֶת בֵּית הַכְּנֶסֶת אֶלָּא יִגְבּוּ לְפִדְיוֹנָן מִן הַצִּבּוּר:","אֵין פּוֹדִין אֶת הַשְּׁבוּיִים בְּיֶתֶר עַל דְּמֵיהֶן מִפְּנֵי תִּקּוּן הָעוֹלָם. שֶׁלֹּא יִהְיוּ הָאוֹיְבִים רוֹדְפִין אַחֲרֵיהֶם לִשְׁבּוֹתָם. וְאֵין מַבְרִיחִין אֶת הַשְּׁבוּיִים מִפְּנֵי תִּקּוּן הָעוֹלָם שֶׁלֹּא יִהְיוּ הָאוֹיְבִים מַכְבִּידִין עֲלֵיהֶן אֶת הָעל וּמַרְבִּים בִּשְׁמִירָתָן:","מִי שֶׁמָּכַר עַצְמוֹ וּבָנָיו לְעַכּוּ\"ם אוֹ שֶׁלָּוָה מֵהֶן וְשָׁבוּ אוֹתָן אוֹ אֲסָרוּהוּ בְּהַלְוָאָתָן. פַּעַם רִאשׁוֹנָה וּשְׁנִיָּה מִצְוָה לִפְדּוֹתָן. שְׁלִישִׁית אֵין פּוֹדִין אוֹתָן. אֲבָל פּוֹדִין אֶת הַבָּנִים לְאַחַר מִיתַת אֲבִיהֶן. וְאִם בִּקְּשׁוּהוּ לְהָרְגוֹ פּוֹדִין אוֹתוֹ מִיָּדָם אֲפִלּוּ אַחַר כַּמָּה פְּעָמִים:","עֶבֶד שֶׁנִּשְׁבָּה הוֹאִיל וְטָבַל לְשֵׁם עַבְדוּת וְקִבֵּל עָלָיו מִצְוֹת פּוֹדִין אוֹתוֹ כְּיִשְׂרָאֵל שֶׁנִּשְׁבָּה. וְשָׁבוּי שֶׁהֵמִיר לְעַכּוּ\"ם וַאֲפִלּוּ לְמִצְוָה אַחַת כְּגוֹן שֶׁהָיָה אוֹכֵל נְבֵלָה לְהַכְעִיס וְכַיּוֹצֵא בּוֹ אָסוּר לִפְדּוֹתוֹ:","הָאִשָּׁה קוֹדֶמֶת לְאִישׁ לְהַאֲכִיל וְלִכְסוּת וּלְהוֹצִיא מִבֵּית הַשֶּׁבִי. מִפְּנֵי שֶׁהָאִישׁ דַּרְכּוֹ לְחַזֵּר לֹא הָאִשָּׁה וּבָשְׁתָּהּ מְרֻבָּה. וְאִם הָיוּ שְׁנֵיהֶם בַּשִּׁבְיָה וְנִתְבְּעוּ שְׁנֵיהֶן לִדְבַר עֲבֵרָה הָאִישׁ קוֹדֵם לִפְדּוֹת לְפִי שֶׁאֵין דַּרְכּוֹ לְכָךְ:","יָתוֹם וִיתוֹמָה שֶׁבָּאוּ לְהַשִּׂיא אוֹתָן מַשִּׂיאִין הָאִשָּׁה קֹדֶם לָאִישׁ מִפְּנֵי שֶׁבָּשְׁתָּהּ שֶׁל אִשָּׁה מְרֻבָּה. וְלֹא יִפְחֲתוּ לָהּ מִמִּשְׁקַל שִׁשָּׁה דִּינָרִים וּרְבִיעַ דִּינָר שֶׁל כֶּסֶף טָהוֹר. וְאִם יֵשׁ בְּכִיס שֶׁל צְדָקָה נוֹתְנִין לָהּ לְפִי כְּבוֹדָהּ:","הָיוּ לְפָנֵינוּ עֲנִיִּים הַרְבֵּה אוֹ שְׁבוּיִים הַרְבֵּה וְאֵין בַּכִּיס כְּדֵי לְפַרְנֵס אוֹ כְּדֵי לְכַסּוֹת אוֹ כְּדֵי לִפְדּוֹת אֶת כֻּלָּן. מַקְדִּימִין אֶת הַכֹּהֵן לַלֵּוִי. וְלֵוִי לְיִשְׂרָאֵל. וְיִשְׂרָאֵל לְחָלָל. וְחָלָל לִשְׁתוּקִי. וּשְׁתוּקִי לַאֲסוּפִי. וַאֲסוּפִי לְמַמְזֵר. וּמַמְזֵר לְנָתִין. וְנָתִין לְגֵר. שֶׁהַנָּתִין גָּדַל עִמָּנוּ בִּקְדֻשָּׁה. וְגֵר קוֹדֵם לְעֶבֶד מְשֻׁחְרָר. לְפִי שֶׁהָיָה בִּכְלַל אָרוּר:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיוּ שְׁנֵיהֶן שָׁוִין בְּחָכְמָה. אֲבָל אִם הָיָה כֹּהֵן גָּדוֹל עַם הָאָרֶץ וּמַמְזֵר תַּלְמִיד חָכָם. תַּלְמִיד חָכָם קוֹדֵם. וְכָל הַגָּדוֹל בְּחָכְמָה קוֹדֵם אֶת חֲבֵרוֹ. וְאִם הָיָה אֶחָד מֵהֶן רַבּוֹ אוֹ אָבִיו אַף עַל פִּי שֶׁיֵּשׁ שָׁם גָּדוֹל מֵהֶן בְּחָכְמָה. רַבּוֹ אוֹ אָבִיו שֶׁהוּא תַּלְמִיד חָכָם קוֹדֵם לָזֶה שֶׁהוּא גָּדוֹל מֵהֶם בְּחָכְמָה:"],"Mishneh Torah, Heave Offerings 5":["אֵין תּוֹרְמִין אֶלָּא מִן הַיָּפֶה שֶׁנֶּאֱמַר (במדבר יח ל) (במדבר יח לב) \"בַּהֲרִימְכֶם אֶת חֶלְבּוֹ מִמֶּנּוּ\". וְאִם אֵין שָׁם כֹּהֵן תּוֹרֵם מִן הַמִּתְקַיֵּם אַף עַל פִּי שֶׁיֵּשׁ שָׁם יָפֶה שֶׁאֵינוֹ מִתְקַיֵּם. כֵּיצַד. תּוֹרֵם תְּאֵנִים עַל הַגְּרוֹגָרוֹת. וּבְמָקוֹם שֶׁאֵין שָׁם כֹּהֵן תּוֹרֵם גְּרוֹגָרוֹת עַל הַתְּאֵנִים. וְאִם רָגִיל לַעֲשׂוֹת תְּאֵנִים גְּרוֹגָרוֹת תּוֹרֵם מִן הַתְּאֵנִים עַל הַגְּרוֹגָרוֹת אֲפִלּוּ בְּמָקוֹם שֶׁאֵין שָׁם כֹּהֵן. אֲבָל בְּמָקוֹם שֶׁיֵּשׁ בּוֹ כֹּהֵן אֵין תּוֹרְמִין מִן הַגְּרוֹגָרוֹת עַל הַתְּאֵנִים אֲפִלּוּ לְמָקוֹם שֶׁדַּרְכָּן לַעֲשׂוֹת תְּאֵנִים גְּרוֹגָרוֹת:","תּוֹרְמִין בָּצָל שָׁלֵם אַף עַל פִּי שֶׁהוּא קָטָן. אֲבָל לֹא חֲצִי בָּצָל אַף עַל פִּי שֶׁהוּא גָּדוֹל. בְּכָל מָקוֹם אֵין תּוֹרְמִין מִמִּין עַל שֶׁאֵינוֹ מִינוֹ שֶׁנֶּאֱמַר (במדבר יח כז) \"כַּדָּגָן מִן הַגֹּרֶן וְכַמְלֵאָה מִן הַיֶּקֶב\". וְאִם תָּרַם אֵין תְּרוּמָתוֹ תְּרוּמָה:","הַקְּשׁוּת וְהַמְּלָפְפוֹן מִין אֶחָד. כָּל מִין חִטִּים אֶחָד. כָּל מִין תְּאֵנִים וּגְרוֹגָרוֹת וּדְבֵלָה אֶחָד. וְתוֹרֵם מִזֶּה עַל זֶה. וְכָל שֶׁהוּא כִּלְאַיִם בַּחֲבֵרוֹ לֹא יִתְרֹם מִזֶּה עַל זֶה אֲפִלּוּ מִן הַיָּפֶה עַל הָרַע. כֵּיצַד. הָיוּ לוֹ חֲמִשִּׁים סְאָה חִטִּין וַחֲמִשִּׁים סְאָה שְׂעוֹרִים בְּבַיִת אֶחָד וְהִפְרִישׁ עַל הַכּל שְׁנֵי סְאִין חִטִּין אֵינָן תְּרוּמָה. וְכָל שֶׁאֵינוֹ כִּלְאַיִם בַּחֲבֵרוֹ תּוֹרֵם מִן הַיָּפֶה עַל הָרַע אֲבָל לֹא מִן הָרַע עַל הַיָּפֶה. וְאִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה חוּץ מִן הַזּוֹנִין עַל הַחִטִּים מִפְּנֵי שֶׁאֵינָן אֹכֶל אָדָם:","אֵין תּוֹרְמִין מִדָּבָר שֶׁנִּגְמְרָה מְלַאכְתּוֹ עַל דָּבָר שֶׁלֹּא נִגְמְרָה מְלַאכְתּוֹ. וְלֹא מִדָּבָר שֶׁלֹּא נִגְמְרָה מְלַאכְתּוֹ עַל דָּבָר שֶׁלֹּא נִגְמְרָה מְלַאכְתּוֹ. וְלֹא מִדָּבָר שֶׁלֹּא נִגְמְרָה מְלַאכְתּוֹ עַל דָּבָר שֶׁנִּגְמְרָה מְלַאכְתּוֹ. שֶׁנֶּאֱמַר (במדבר יח כז) \"כַּדָּגָן מִן הַגֹּרֶן וְכַמְלֵאָה מִן הַיֶּקֶב\" מִן הַגָּמוּר עַל הַגָּמוּר. וְאִם תָּרְמוּ תְּרוּמָתָן תְּרוּמָה:","מֵאֵימָתַי תּוֹרְמִין אֶת הַגֹּרֶן מִשֶּׁיִּבְרֹר. בָּרַר מִקְצָת תּוֹרְמִין מִן הַבָּרוּר עַל שֶׁאֵינוֹ בָּרוּר. הַמַּכְנִיס שִׁבֳּלִים לְתוֹךְ בֵּיתוֹ לַעֲשׂוֹתָן מְלִילוֹת הֲרֵי זֶה תּוֹרֵם מִן שִׁבֳּלִים:","מֵאֵימָתַי תּוֹרְמִין אֶת הַגַּת מִשֶּׁיְּהַלְּכוּ בָּהּ שְׁתִי וָעֵרֶב. מֵאֵימָתַי תּוֹרְמִין אֶת הַזֵּיתִים מִשֶּׁיִּטְעֲנוּ:","אֵין תּוֹרְמִין מִן הַטָּהוֹר עַל הַטָּמֵא וְאִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה. וַהֲלָכָה לְמשֶׁה מִסִּינַי שֶׁעִגּוּל שֶׁל דְּבֵלָה שֶׁנִּטְמָא מִקְצָתוֹ תּוֹרְמִין לְכַתְּחִלָּה מִן הַטָּהוֹר שֶׁבּוֹ עַל הַטָּמֵא שֶׁבּוֹ. וְלֹא הָעִגּוּל בִּלְבַד שֶׁהוּא גּוּף אֶחָד אֶלָּא אֲפִלּוּ אֲגֻדָּה שֶׁל יָרָק אֲפִלּוּ עֲרֵמוֹת שֶׁל חִטִּים שֶׁנִּטְמְאָה מִקְצָתָהּ תּוֹרְמִין מִן הַטָּהוֹר שֶׁבָּהּ עַל הַטָּמֵא שֶׁבָּהּ. אֲבָל אִם הָיוּ שְׁנֵי עִגּוּלִים אוֹ שְׁתֵּי אֲגֻדּוֹת אוֹ שְׁתֵּי עֲרֵמוֹת אַחַת טְמֵאָה וְאַחַת טְהוֹרָה בְּצִדָּהּ לֹא יִתְרֹם מִן הַטָּהוֹר עַל הַטָּמֵא לְכַתְּחִלָּה. וְתוֹרְמִין תְּרוּמַת מַעֲשֵׂר מִן הַטָּהוֹר עַל הַטָּמֵא לְכַתְּחִלָּה שֶׁנֶּאֱמַר (במדבר יח כט) \"אֶת מִקְדָּשׁוֹ מִמֶּנּוּ\" טֹל מִן הַמְקֻדָּשׁ שֶׁבּוֹ:","אֵין תּוֹרְמִין מִן הַטָּמֵא עַל הַטָּהוֹר וְאִם תָּרַם בְּשׁוֹגֵג תְּרוּמָתוֹ תְּרוּמָה. בְּמֵזִיד לֹא תִּקֵּן אֶת הַשְּׁיָרִים וְזֶה שֶׁהֵרִים תְּרוּמָה וְיַחֲזֹר וְיִתְרֹם. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁלֹּא יָדַע בַּטֻּמְאָה. אֲבָל אִם יָדַע וְשָׁגַג שֶׁמֻּתָּר לִתְרֹם מִן הַטָּמֵא עַל הַטָּהוֹר הֲרֵי הוּא כְּמֵזִיד. וְכֵן בִּתְרוּמַת מַעֲשֵׂר:","אֵין תּוֹרְמִין מִן הַמְחֻבָּר עַל הַתָּלוּשׁ וְלֹא מִן הַתָּלוּשׁ עַל הַמְחֻבָּר. כֵּיצַד. הָיוּ לוֹ פֵּרוֹת תְּלוּשִׁין וְאָמַר פֵּרוֹת אֵלּוּ יִהְיוּ תְּרוּמָה עַל פֵּרוֹת אֵלּוּ הַמְחֻבָּרִים אֲפִלּוּ (אָמַר) לִכְשֶׁיִּתָּלְשׁוּ. אוֹ שֶׁהָיוּ לוֹ שְׁתֵּי עֲרוּגוֹת וְאָמַר פֵּרוֹת עֲרוּגָה זוֹ תְּלוּשִׁין יִהְיוּ תְּרוּמָה עַל פֵּרוֹת עֲרוּגָה זוֹ מְחֻבָּרִים. אוֹ שֶׁאָמַר פֵּרוֹת עֲרוּגָה זוֹ מְחֻבָּרִים יִהְיוּ תְּרוּמָה עַל פֵּרוֹת עֲרוּגָה זוֹ תְּלוּשִׁין לֹא אָמַר כְּלוּם. אֲבָל אִם אָמַר פֵּרוֹת עֲרוּגָה זוֹ תְּלוּשִׁין יִהְיוּ תְּרוּמָה עַל פֵּרוֹת עֲרוּגָה זוֹ לִכְשֶׁיִּתָּלְשׁוּ וְנִתְלְשׁוּ הוֹאִיל וּבְיָדוֹ לְתָלְשָׁן אֵינוֹ מְחֻסָּר מַעֲשֶׂה וְלִכְשֶׁיִּתָּלְשׁוּ שְׁנֵיהֶם דְּבָרָיו קַיָּמִין. וְהוּא שֶׁיָּבִיאוּ שְׁתֵּיהֶן שְׁלִישׁ בְּעֵת שֶׁאָמַר:","אֵין תּוֹרְמִין מִן הַלַּח עַל הַיָּבֵשׁ וְלֹא מִן הַיָּבֵשׁ עַל הַלַּח. וְאִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה. כֵּיצַד. לִקֵּט יָרָק הַיּוֹם וְלִקֵּט מִמֶּנּוּ לְמָחָר אֵין תּוֹרְמִין מִזֶּה עַל זֶה אֶלָּא אִם כֵּן דַּרְכּוֹ לְהִשְׁתַּמֵּר שְׁנֵי יָמִים. וְכֵן יָרָק שֶׁדַּרְכּוֹ לְהִשְׁתַּמֵּר שְׁלֹשָׁה יָמִים כְּגוֹן הַמְּלָפְפוֹנוֹת כָּל שֶׁלִּקֵּט בִּשְׁלֹשֶׁת יָמִים מִצְטָרֵף וְתוֹרֵם מִזֶּה עַל זֶה. יָרָק שֶׁדַּרְכּוֹ לְהִשְׁתַּמֵּר יוֹם אֶחָד בִּלְבַד וְלִקֵּט בְּשַׁחֲרִית וְלִקֵּט בָּעֶרֶב תּוֹרֵם מִזֶּה עַל זֶה:","אֵין תּוֹרְמִין מִפֵּרוֹת שָׁנָה זוֹ עַל פֵּרוֹת שָׁנָה שֶׁעָבְרָה. וְלֹא מִפֵּרוֹת שָׁנָה שֶׁעָבְרָה עַל פֵּרוֹת שָׁנָה זוֹ. וְאִם תָּרַם אֵינָהּ תְּרוּמָה שֶׁנֶּאֱמַר (דברים יד כב) \"שָׁנָה שָׁנָה\". לִקֵּט יָרָק עֶרֶב רֹאשׁ הַשָּׁנָה עַד שֶׁלֹּא בָּאָה הַשֶּׁמֶשׁ וְחָזַר וְלִקֵּט אַחַר שֶׁבָּאָה הַשֶּׁמֶשׁ אֵין תּוֹרְמִין מִזֶּה עַל זֶה שֶׁזֶּה חָדָשׁ וְזֶה יָשָׁן. וְכֵן אִם לִקֵּט אֶתְרוֹג בְּעֶרֶב ט\"ו בִּשְׁבָט עַד שֶׁלֹּא בָּא הַשֶּׁמֶשׁ וְחָזַר וְלִקֵּט אֶתְרוֹג אַחֵר מִשֶּׁבָּאָה הַשֶּׁמֶשׁ אֵין תּוֹרְמִין מִזֶּה עַל זֶה מִפְּנֵי שֶׁאֶחָד בְּתִשְׁרֵי רֹאשׁ הַשָּׁנָה לְמַעַשְׂרוֹת תְּבוּאָה וְקִטְנִיּוֹת וִירָקוֹת. וְט\"ו בִּשְׁבָט רֹאשׁ הַשָּׁנָה לְמַעַשְׂרוֹת הָאִילָן:","אֵין תּוֹרְמִין פֵּרוֹת הָאָרֶץ עַל פֵּרוֹת חוּצָה לָאָרֶץ. וְלֹא מִפֵּרוֹת חוּצָה לָאָרֶץ עַל פֵּרוֹת הָאָרֶץ. [וְלֹא מִפֵּרוֹת הָאָרֶץ עַל פֵּרוֹת סוּרְיָא. וְלֹא מִפֵּרוֹת סוּרְיָא עַל פֵּרוֹת הָאָרֶץ]. וְלֹא מִפֵּרוֹת שֶׁאֵינָן חַיָּבִין בִּתְרוּמָה כְּגוֹן לֶקֶט שִׁכְחָה וּפֵאָה. אוֹ פֵּרוֹת שֶׁנִּתְרְמָה תְּרוּמָתָן עַל פֵּרוֹת שֶׁחַיָּבִין בִּתְרוּמָה. וְלֹא מִפֵּרוֹת שֶׁחַיָּבִין בִּתְרוּמָה עַל פֵּרוֹת הַפְּטוּרִין. וְאִם תָּרַם אֵינָהּ תְּרוּמָה:","הַמַּפְרִישׁ תְּרוּמָה מִמַּעֲשֵׂר רִאשׁוֹן שֶׁלֹּא נִטְּלָה תְּרוּמָתוֹ. אוֹ מִמַּעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁלֹּא נִפְדּוּ עַל פֵּרוֹת אֲחֵרוֹת אֵין תְּרוּמָתָן תְּרוּמָה:","אֵין תּוֹרְמִין מִדָּבָר שֶׁהוּא חַיָּב מִן הַתּוֹרָה עַל דָּבָר שֶׁהוּא חַיָּב מִדִּבְרֵיהֶן וְלֹא מִן הַמְחֻיָּב מִדִּבְרֵיהֶן עַל הַחַיָּב מִן הַתּוֹרָה. וְאִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה וְיַחֲזֹר וְיִתְרֹם:","עָצִיץ נָקוּב הֲרֵי הוּא כְּאֶרֶץ. וְכַמָּה יְהֵא בַּנֶּקֶב כְּדֵי שֹׁרֶשׁ קָטָן וְהוּא פָּחוֹת מִכְּזַיִת. זָרַע תְּבוּאָה בְּעָצִיץ שֶׁאֵינוֹ נָקוּב וְהֵבִיאָה שְׁלִישׁ וְאַחַר כָּךְ נִקְּבוֹ וְנִגְמְרָה הַתְּבוּאָה וְהוּא נָקוּב הֲרֵי הוּא כַּצּוֹמֵחַ בְּשֶׁאֵינוֹ נָקוּב עַד שֶׁיִּקְּבֶנּוּ קֹדֶם שֶׁיָּבִיא שְׁלִישׁ:","הַתּוֹרֵם מִפֵּרוֹת הַגְּדֵלִין בְּאֶרֶץ עַל הַגְּדֵלִין בְּעָצִיץ נָקוּב אוֹ מִפֵּרוֹת עָצִיץ נָקוּב עַל הַגְּדֵלִין בָּאָרֶץ תְּרוּמָתוֹ תְּרוּמָה. תָּרַם מִשֶּׁאֵינוֹ נָקוּב עַל הַנָּקוּב תְּרוּמָתוֹ תְּרוּמָה וְיַחֲזֹר וְיִתְרֹם. תָּרַם מִן הַנָּקוּב עַל שֶׁאֵינוֹ נָקוּב תְּרוּמָתוֹ תְּרוּמָה וְלֹא תֵּאָכֵל עַד שֶׁיּוֹצִיא עָלֶיהָ תְּרוּמָה וּמַעַשְׂרוֹת מִמָּקוֹם אַחֵר:","הַתּוֹרֵם מִן הַדְּמַאי עַל הַדְּמַאי וּמִן הַדְּמַאי עַל הַוַּדַּאי תְּרוּמָתוֹ תְּרוּמָה וְיַחֲזֹר וְיִתְרֹם מִכָּל אֶחָד וְאֶחָד בִּפְנֵי עַצְמוֹ. תָּרַם מִן הַוַּדַּאי עַל הַדְּמַאי תְּרוּמָתוֹ תְּרוּמָה וְלֹא תֵּאָכֵל עַד שֶׁיּוֹצִיא עָלֶיהָ תְּרוּמָה וּמַעַשְׂרוֹת:","אֵין תּוֹרְמִין שִׁבֳּלִים עַל הַחִטִּים. וְזֵיתִים עַל שֶׁמֶן. וַעֲנָבִים עַל יַיִן. וְאִם תָּרַם אֵינָהּ תְּרוּמָה גְּזֵרָה שֶׁמָּא יַטְרִיחַ הַכֹּהֵן לִדְרֹךְ וְלִכְתּשׁ. אֲבָל תּוֹרְמִין שֶׁמֶן עַל הַזֵּיתִים הַנִּכְבָּשִׁין וְיַיִן עַל עֲנָבִים לַעֲשׂוֹתָן צִמּוּקִין. לְמָה זֶה דּוֹמֶה לְתוֹרֵם מִשְּׁנֵי מִינִין שֶׁאֵינָן כִּלְאַיִם זֶה בָּזֶה מִן הַיָּפֶה עַל הָרַע. וְכֵן תּוֹרְמִין מִזֵּיתֵי שֶׁמֶן עַל זֵיתֵי כֶּבֶשׁ. אֲבָל לֹא מִזֵּיתֵי כֶּבֶשׁ עַל זֵיתֵי שֶׁמֶן. מִיַּיִן שֶׁאֵינוֹ מְבֻשָּׁל עַל הַמְבֻשָּׁל. אֲבָל לֹא מִן הַמְבֻשָּׁל עַל שֶׁאֵינוֹ מְבֻשָּׁל. מִן הַצָּלוּל עַל שֶׁאֵינוֹ צָלוּל. אֲבָל לֹא מִשֶּׁאֵינוֹ צָלוּל עַל הַצָּלוּל. מִתְּאֵנִים עַל גְּרוֹגָרוֹת בְּמִנְיָן. מִגְּרוֹגָרוֹת עַל הַתְּאֵנִים בְּמִדָּה. אֲבָל לֹא תְּאֵנִים עַל גְּרוֹגָרוֹת בְּמִדָּה. וְלֹא גְּרוֹגָרוֹת עַל הַתְּאֵנִים בְּמִנְיָן. כְּדֵי שֶׁיִּתְרֹם לְעוֹלָם בְּעֵין יָפָה. וְתוֹרְמִין חִטִּים עַל הַפַּת. אֲבָל לֹא מִן הַפַּת עַל הַחִטִּים לְפִי חֶשְׁבּוֹן. וּבְכָל אֵלּוּ אִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה:","אֵין תּוֹרְמִין שֶׁמֶן עַל הַזֵּיתִים הַנִּכְתָּשִׁין. וְלֹא יַיִן עַל עֲנָבִים הַנִּדְרָכוֹת שֶׁזֶּה דּוֹמֶה לְתוֹרֵם מִדָּבָר שֶׁנִּגְמְרָה מְלַאכְתּוֹ עַל דָּבָר שֶׁלֹּא נִגְמְרָה מְלַאכְתּוֹ. וְאִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה וְיַחֲזֹר וְיִתְרֹם מִן הַזֵּיתִים וְהָעֲנָבִים בִּפְנֵי עַצְמָן. הָרִאשׁוֹנָה מְדַמַּעַת בִּפְנֵי עַצְמָהּ וְהָאוֹכְלָהּ חַיָּב עָלֶיהָ כִּשְׁאָר תְּרוּמוֹת גְּמוּרוֹת אֲבָל לֹא מִן הַשְּׁנִיָּה:","מִי שֶׁתָּרַם שֶׁמֶן עַל זֵיתִים שֶׁדַּעְתּוֹ לְאָכְלָן. אוֹ זֵיתִים עַל זֵיתִים וְדַעְתּוֹ עַל הַכּל לַאֲכִילָה. אוֹ שֶׁתָּרַם יַיִן עַל עֲנָבִים שֶׁהֵם לַאֲכִילָה. אוֹ עֲנָבִים עַל עֲנָבִים וְהַכּל לַאֲכִילָה. וְנִמְלַךְ לְדָרְכָן וְדָרַךְ הַזֵּיתִים וְהָעֲנָבִים שֶׁכְּבָר תָּרַם עֲלֵיהֶם. אֵינוֹ צָרִיךְ לַחֲזֹר וְלִתְרֹם:","אֵין תּוֹרְמִין חֹמֶץ עַל יַיִן. אֲבָל תּוֹרְמִין יַיִן עַל חֹמֶץ. שֶׁהַיַּיִן וְהַחֹמֶץ מִין אֶחָד הֵן. (הָיָה בְּלִבּוֹ לִתְרֹם מִן הַיַּיִן עַל הַיַּיִן וְנִמְצָא בְּיָדוֹ חֹמֶץ אֵינָהּ תְּרוּמָה). הָיָה בְּלִבּוֹ לִתְרֹם חֹמֶץ עַל חֹמֶץ וְנִמְצָא הַחֹמֶץ שֶׁתָּרַם יַיִן תְּרוּמָתוֹ תְּרוּמָה:","הַתּוֹרֵם חָבִית שֶׁל יַיִן עַל הַיַּיִן וְנִמְצָא חֹמֶץ אִם יוֹדֵעַ שֶׁהָיְתָה חֹמֶץ עַד שֶׁלֹּא תְּרָמָהּ אֵינָהּ תְּרוּמָה. וְאִם אַחַר שֶׁתְּרָמָהּ הֶחְמִיצָה הֲרֵי זוֹ תְּרוּמָה. וְאִם סָפֵק תְּרוּמָה וְיַחֲזֹר וְיִתְרֹם. וְכֵן הַתּוֹרֵם קִשּׁוּת וְנִמְצֵאת מָרָה אֲבַטִּיחַ וְנִמְצָא סָרוּחַ אוֹ שֶׁנִּמְצְאוּ נְקוּרִין. תָּרַם חָבִית שֶׁל יַיִן וְנִמְצֵאת מְגֻלָּה שֶׁאָסוּר לִשְׁתּוֹתָהּ תְּרוּמָה וְיַחֲזֹר וְיִתְרֹם שְׁנִיָּה. וְאֵין אַחַת מִשְּׁתֵּיהֶן מְדַמַּעַת בִּפְנֵי עַצְמָהּ. וְהָאוֹכֵל אַחַת מִשְּׁתֵּיהֶן אֵינוֹ חַיָּב חֹמֶשׁ:","כֵּיצַד. נָפְלָה אַחַת מֵהֶן עַל הַחֻלִּין אֵינָהּ מְדַמַּעַת. נָפְלָה שְׁנִיָּה לְמָקוֹם אַחֵר אֵינָהּ מְדַמַּעְתָּהּ. נָפְלוּ שְׁתֵּיהֶן לְמָקוֹם אֶחָד מְדַמְּעוֹת בַּקְּטַנָּה שֶׁבִּשְׁתֵּיהֶן. וְכֵן אִם אָכַל זָר שְׁתֵּיהֶן מְשַׁלֵּם בַּקְּטַנָּה שֶׁבִּשְׁתֵּיהֶן וְחֻמְשָׁהּ. וְכֵיצַד הוּא עוֹשֶׂה בִּשְׁתֵּיהֶן נוֹתְנָן לְכֹהֵן אֶחָד וְנוֹטֵל מִן הַכֹּהֵן דְּמֵי הַגְּדוֹלָה:","הַבּוֹדֵק אֶת הֶחָבִית וְהִנִּיחָהּ לְהַפְרִישָׁהּ תְּרוּמָה עַל אֲחֵרִים עַד שֶׁתֵּעָשֶׂה כֻּלָּהּ תְּרוּמָה וְיִתְּנֶנָּה לַכֹּהֵן. וּלְאַחַר זְמַן בְּדָקָהּ וּמְצָאָהּ חֹמֶץ. מֵעֵת שֶׁבְּדָקָהּ תְּחִלָּה עַד שְׁלֹשָׁה יָמִים וַדַּאי יַיִן וְכָל יַיִן שֶׁחָשַׁב אוֹתָן הַיָּמִים שֶׁהַתְּרוּמָה שֶׁלּוֹ בְּחָבִית זוֹ הֲרֵי הוּא מְתֻקָּן. מִכָּאן וְאֵילָךְ סָפֵק וְצָרִיךְ לְהַפְרִישׁ מִמֶּנּוּ תְּרוּמָה שְׁנִיָּה:","בִּשְׁלֹשָׁה פְּרָקִים צָרִיךְ לִבְדֹּק אֶת הַיַּיִן שֶׁהִנִּיחוֹ לִפְרשׁ עָלָיו שֶׁמָּא הֶחְמִיץ. וְאֵלּוּ הֵן. בְּקַדִּים שֶׁל מוֹצָאֵי הֶחָג. וּבְהוֹצָאַת הַסְּמָדַר. וּבִשְׁעַת כְּנִיסַת מַיִם לַבֹּסֶר. וְיַיִן מִגִּתּוֹ מַפְרִישִׁין עָלָיו בְּחֶזְקַת שֶׁהוּא יַיִן [עַד] אַרְבָּעִים יוֹם:","הַמַּנִּיחַ פֵּרוֹת לִהְיוֹת מַפְרִישׁ עֲלֵיהֶן עַד שֶׁיֵּעָשׂוּ תְּרוּמָה אַף עַל פִּי שֶׁאֵין מַפְרִישִׁין לְכַתְּחִלָּה אֶלָּא מִן הַמֻּקָּף אִם הִפְרִישׁ הֲרֵי הֵן בְּחֶזְקַת קַיָּמִין. מְצָאָן שֶׁאָבְדוּ הֲרֵי זֶה חוֹשֵׁשׁ לְכָל מַה שֶּׁתִּקֵּן שֶׁמָּא לֹא הִפְרִישׁ עֲלֵיהֶן אֶלָּא אַחַר שֶׁאָבְדוּ לְפִיכָךְ מַפְרִישׁ תְּרוּמָה שְׁנִיָּה:"],"Mishneh Torah, Hiring 4":["הַשׂוֹכֵר אֶת הַחֲמוֹר לְהוֹלִיכָהּ בָּהָר וְהוֹלִיכָהּ בַּבִּקְעָה אִם הֻחְלְקָה פָּטוּר אַף עַל פִּי שֶׁעָבַר עַל דַּעַת הַבְּעָלִים. וְאִם הוּחַמָּה חַיָּב. שְׂכָרָהּ לְהוֹלִיכָהּ בַּבִּקְעָה וְהוֹלִיכָהּ בָּהָר אִם הֻחְלְקָה חַיָּב שֶׁהַחֲלָקוּת יֶתֶר בָּהָר מִן הַבִּקְעָה. וְאִם הוּחַמָּה פָּטוּר שֶׁחֲמִימוּת בַּבִּקְעָה יֶתֶר מִן הָהָר מִפְּנֵי הָרוּחַ שֶׁמְּנַשֶּׁבֶת בְּרֹאשׁ הֶהָרִים. וְאִם הוּחַמָּה מֵחֲמַת הַמַּעֲלָה חַיָּב וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְכֵן הַשּׂוֹכֵר אֶת הַפָּרָה לַחְרשׁ בָּהָר וְחָרַשׁ בַּבִּקְעָה וְנִשְׁבַּר הַקַּנְקַן וְהוּא הַכְּלִי שֶׁחוֹרֵשׁ בּוֹ הֲרֵי הַשּׂוֹכֵר פָּטוּר וְדִין בַּעַל הַפָּרָה עִם הָאֻמָּנִין שֶׁחָרְשׁוּ. וְכֵן אִם לֹא שִׁנָּה עַל דַּעַת הַבְּעָלִים וְנִשְׁבַּר הַקַּנְקַן דִּין בַּעַל הַפָּרָה עִם הָאֻמָּנִין. שְׂכָרָהּ לַחְרשׁ בַּבִּקְעָה וְחָרַשׁ בָּהָר וְנִשְׁבַּר הַקַּנְקַן הַשּׂוֹכֵר חַיָּב וְדִינוֹ שֶׁל שׂוֹכֵר עִם הָאֻמָּנִים:","וּמַהוּ דִּין הָאֻמָּנִין שֶׁשָּׁבְרוּ בְּעֵת חֲרִישָׁה שֶׁמְּשַׁלְּמִין. מִי מְשַׁלֵּם זֶה הָאוֹחֵז אֶת הַכְּלִי בְּעֵת הַחֲרִישָׁה. וְאִם הָיְתָה הַשָּׂדֶה מַעֲלוֹת מַעֲלוֹת שְׁנֵיהֶם חַיָּבִים בִּדְמֵי הַקַּנְקַן. הַמַּנְהִיג אוֹתָהּ בְּמַלְמַד וְהָאוֹחֵז אֶת הַכְּלִי:","שְׂכָרָהּ לָדוּשׁ בְּקִטְנִית וְדָשׁ בִּתְבוּאָה וְהֻחְלְקָה פָּטוּר בִּתְבוּאָה וְדָשׁ בְּקִטְנִית חַיָּב שֶׁהַקִּטְנִית מַחְלֶקֶת. מַעֲשֶׂה בְּאֶחָד שֶׁהִשְׂכִּיר חֲמוֹר לַחֲבֵרוֹ וְאָמַר לוֹ לֹא תֵּלֵךְ בּוֹ בְּדֶרֶךְ נָהָר פְּקוֹד שֶׁהַמַּיִם מְצוּיִין שָׁם אֶלָּא בְּדֶרֶךְ נֶרֶשׁ שֶׁאֵין בָּהּ מַיִם. הָלַךְ בְּדֶרֶךְ נָהָר פְּקוֹד וּמֵת הַחֲמוֹר וְלֹא הָיוּ שָׁם עֵדִים שֶׁמְּעִידִים בְּאֵי זֶה דֶּרֶךְ הָלַךְ אֶלָּא הוּא מֵעַצְמוֹ אָמַר בְּנָהָר פְּקוֹד הָלָכְתִּי וְלֹא הָיוּ שָׁם מַיִם וּמֵחֲמַת עַצְמוֹ מֵת וְאָמְרוּ חֲכָמִים הוֹאִיל וְיֵשׁ עֵדִים שֶׁהַמַּיִם בְּנָהָר פְּקוֹד מְצוּיִין חַיָּב לְשַׁלֵּם שֶׁהֲרֵי שִׁנָּה עַל דַּעַת הַבְּעָלִים וְאֵין אוֹמְרִים מַה לִּי לְשַׁקֵּר בִּמְקוֹם עֵדִים:","הַשּׂוֹכֵר אֶת הַבְּהֵמָה לְהָבִיא עָלֶיהָ מָאתַיִם לִיטְרִין שֶׁל חִטִּים וְהֵבִיא מָאתַיִם לִיטְרִין שֶׁל שְׂעוֹרִים וּמֵתָה חַיָּב מִפְּנֵי שֶׁהַנֶּפַח קָשֶׁה לְמַשּׂאוֹי וְהַשְּׂעוֹרִין יֵשׁ לָהֶן נֶפַח. וְכֵן אִם שְׂכָרָהּ לְהָבִיא תְּבוּאָה וְהֵבִיא בְּמִשְׁקָלָהּ תֶּבֶן. אֲבָל אִם שְׂכָרָהּ לְהָבִיא עָלֶיהָ שְׂעוֹרִים וְהֵבִיא בְּמִשְׁקָלָן חִטִּים וּמֵתָה פָּטוּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","שָׂכַר אֶת הַבְּהֵמָה לִרְכֹּב עָלֶיהָ אִישׁ לֹא יַרְכִּיב עָלֶיהָ אִשָּׁה. שְׂכָרָהּ לִרְכֹּב עָלֶיהָ אִשָּׁה מַרְכִּיב עָלֶיהָ אִישׁ. וּמַרְכִּיב עָלֶיהָ כָּל אִשָּׁה בֵּין קְטַנָּה בֵּין גְּדוֹלָה וַאֲפִלּוּ מְעֵבֶּרֶת שֶׁהִיא מֵינִיקָה:","הַשּׂוֹכֵר אֶת הַבְּהֵמָה לָשֵׂאת עָלֶיהָ מִשְׁקָל יָדוּעַ וְהוֹסִיף עַל מַשָּׂאוֹ אִם הוֹסִיף חֵלֶק מִשְּׁלֹשִׁים עַל הַשִּׁעוּר שֶׁפָּסַק עִמּוֹ וּמֵתָה חַיָּב פָּחוֹת מִכָּאן פָּטוּר אֲבָל נוֹתֵן הוּא שְׂכַר הַתּוֹסֶפֶת. שָׂכַר סְתָם אֵינוֹ נוֹשֵׂא אֶלָּא בְּמִשְׁקָל הַיָּדוּעַ בַּמְּדִינָה לְאוֹתָהּ בְּהֵמָה. וְאִם הוֹסִיף חֵלֶק מִשְּׁלֹשִׁים כְּגוֹן שֶׁדַּרְכָּהּ לָשֵׂאת שְׁלֹשִׁים וְטָעַן עָלֶיהָ שְׁלֹשִׁים וְאֶחָד וּמֵתָה אוֹ נִשְׁבְּרָה חַיָּב. וְכֵן סְפִינָה שֶׁהוֹסִיף בָּהּ אֶחָד מִשְּׁלֹשִׁים עַל מַשָּׂאָהּ וְטָבְעָה חַיָּב לְשַׁלֵּם דָּמֶיהָ:","הַכַּתָּף שֶׁהוֹסִיף עַל מַשָּׂאוֹ קַב אֶחָד הֻזַּק בְּמַשָּׂא זֶה חַיָּב בִּנְזָקָיו. שֶׁאַף עַל פִּי שֶׁהוּא בֶּן דַּעַת וַהֲרֵי הוּא מַרְגִּישׁ בְּכֹבֶד הַמַּשָּׂא יַעֲלֶה עַל לִבּוֹ שֶׁמָּא מֵחֲמַת חָלְיוֹ הוּא זֶה הַכֹּבֶד:","הַשּׂוֹכֵר אֶת הַחֲמוֹר לִרְכֹּב עָלֶיהָ יֵשׁ לוֹ לְהַנִּיחַ עָלֶיהָ כְּסוּתוֹ וְלָגִינוֹ וּמְזוֹנוֹתָיו שֶׁל אוֹתוֹ הַדֶּרֶךְ לְפִי שֶׁאֵין דֶּרֶךְ הַשּׂוֹכֵר לַחְזֹר בְּכָל מָלוֹן וּמָלוֹן לִקְנוֹת מְזוֹנוֹת. יֶתֶר עַל זֶה הֲרֵי מְעַכֵּב עָלָיו בַּעַל הַחֲמוֹר. וְכֵן יֵשׁ לְבַעַל הַחֲמוֹר לְהַנִּיחַ עָלֶיהָ שְׂעוֹרִים וְתֶבֶן וּמְזוֹנוֹת שֶׁל אוֹתוֹ הַיּוֹם יֶתֶר עַל זֶה הַשּׂוֹכֵר מְעַכֵּב מִפְּנֵי שֶׁאֶפְשָׁר לוֹ לִקְנוֹת בְּכָל מָלוֹן וּמָלוֹן. לְפִיכָךְ אִם אֵין שָׁם מֵאַיִן יִקְנֶה מַנִּיחַ עָלָיו מְזוֹנוֹתָיו וּמְזוֹנוֹת בְּהֶמְתּוֹ שֶׁל כָּל אוֹתָהּ הַדֶּרֶךְ. וְכָל אֵלּוּ הַדְּבָרִים בְּשׂוֹכֵר סְתָם וּבְמָקוֹם שֶׁאֵין מִנְהָג יָדוּעַ. אֲבָל בְּמָקוֹם שֶׁיֵּשׁ מִנְהָג הַכּל לְפִי הַמִּנְהָג:"],"Mishneh Torah, Human Dispositions 7":["הַמְרַגֵּל בַּחֲבֵרוֹ עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (ויקרא יט טז) \"לֹא תֵלֵךְ רָכִיל בְּעַמֶּיךָ\". וְאַף עַל פִּי שֶׁאֵין לוֹקִין עַל דָּבָר זֶה עָוֹן גָּדוֹל הוּא וְגוֹרֵם לַהֲרֹג נְפָשׁוֹת רַבּוֹת מִיִּשְׂרָאֵל. לְכָךְ נִסְמָךְ לוֹ (ויקרא יט טז) \"וְלֹא תַעֲמֹד עַל דַּם רֵעֶךָ\". צֵא וּלְמַד מָה אֵרַע לְדוֹאֵג הָאֲדֹמִי:","אֵי זֶהוּ רָכִיל. זֶה שֶׁטּוֹעֵן דְּבָרִים וְהוֹלֵךְ מִזֶּה לָזֶה וְאוֹמֵר כָּךְ אָמַר פְּלוֹנִי כָּךְ וְכָךְ שָׁמַעְתִּי עַל פְּלוֹנִי. אַף עַל פִּי שֶׁהוּא אֱמֶת הֲרֵי זֶה מַחֲרִיב אֶת הָעוֹלָם. יֵשׁ עָוֹן גָּדוֹל מִזֶּה עַד מְאֹד וְהוּא בִּכְלַל לָאו זֶה וְהוּא לָשׁוֹן הָרַע. וְהוּא הַמְסַפֵּר בִּגְנוּת חֲבֵרוֹ אַף עַל פִּי שֶׁאוֹמֵר אֱמֶת. אֲבָל הָאוֹמֵר שֶׁקֶר נִקְרָא מוֹצִיא שֵׁם רַע עַל חֲבֵרוֹ. אֲבָל בַּעַל לָשׁוֹן הָרַע זֶה שֶׁיּוֹשֵׁב וְאוֹמֵר כָּךְ וְכָךְ עָשָׂה פְּלוֹנִי וְכָךְ וְכָךְ הָיוּ אֲבוֹתָיו וְכָךְ וְכָךְ שָׁמַעְתִּי עָלָיו וְאָמַר דְּבָרִים שֶׁל גְּנַאי. עַל זֶה אָמַר הַכָּתוּב (תהילים יב ד) \"יַכְרֵת ה' כָּל שִׂפְתֵי חֲלָקוֹת לָשׁוֹן מְדַבֶּרֶת גְּדֹלוֹת\":","אָמְרוּ חֲכָמִים שָׁלֹשׁ עֲבֵרוֹת נִפְרָעִין מִן הָאָדָם בָּעוֹלָם הַזֶּה וְאֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא. עֲבוֹדַת כּוֹכָבִים וְגִלּוּי עֲרָיוֹת וּשְׁפִיכוּת דָּמִים. וְלָשׁוֹן הָרַע כְּנֶגֶד כֻּלָּם. וְעוֹד אָמְרוּ חֲכָמִים כָּל הַמְסַפֵּר בְּלָשׁוֹן הָרַע כְּאִלּוּ כּוֹפֵר בָּעִקָּר. שֶׁנֶּאֱמַר (תהילים יב ה) \"אֲשֶׁר אָמְרוּ לִלְשֹׁנֵנוּ נַגְבִּיר שְׂפָתֵינוּ אִתָּנוּ מִי אָדוֹן לָנוּ\". וְעוֹד אָמְרוּ חֲכָמִים שְׁלֹשָׁה לָשׁוֹן הָרַע הוֹרֶגֶת. הָאוֹמְרוֹ. וְהַמְקַבְּלוֹ. וְזֶה שֶׁאוֹמֵר עָלָיו. וְהַמְקַבְּלוֹ יוֹתֵר מִן הָאוֹמְרוֹ:","וְיֵשׁ דְּבָרִים שֶׁהֵן אֲבַק לָשׁוֹן הָרַע. כֵּיצַד. מִי יֹאמַר לִפְלוֹנִי שֶׁיִּהְיֶה כְּמוֹת שֶׁהוּא עַתָּה. אוֹ שֶׁיֹּאמַר שִׁתְקוּ מִפְּלוֹנִי אֵינִי רוֹצֶה לְהוֹדִיעַ מָה אֵרַע וּמֶה הָיָה. וְכַיּוֹצֵא בַּדְּבָרִים הָאֵלּוּ. וְכָל הַמְסַפֵּר בְּטוֹבַת חֲבֵרוֹ בִּפְנֵי שׂוֹנְאָיו הֲרֵי זֶה אֲבַק לָשׁוֹן הָרַע שֶׁזֶּה גּוֹרֵם לָהֶם שֶׁיְּסַפְּרוּ בִּגְנוּתוֹ. וְעַל זֶה הָעִנְיָן אָמַר שְׁלֹמֹה (משלי כז יד) \"מְבָרֵךְ רֵעֵהוּ בְּקוֹל גָּדוֹל בַּבֹּקֶר הַשְׁכֵּים קְלָלָה תֵּחָשֶׁב לוֹ\". שֶׁמִּתּוֹךְ טוֹבָתוֹ בָּא לִידֵי רָעָתוֹ. וְכֵן הַמְסַפֵּר בְּלָשׁוֹן הָרַע דֶּרֶךְ שְׂחוֹק וְדֶרֶךְ קַלּוּת רֹאשׁ כְּלוֹמַר שֶׁאֵינוֹ מְדַבֵּר בְּשִׂנְאָה. הוּא שֶׁשְּׁלֹמֹה אָמַר בְּחָכְמָתוֹ (משלי כו יח) \"כְּמִתְלַהְלֵהַּ הַיֹּרֶה זִקִּים חִצִּים וָמָוֶת\" (משלי כו יט) \"וְאָמַר הֲלֹא מְשַׂחֵק אָנִי\". וְכֵן הַמְסַפֵּר לָשׁוֹן הָרַע דֶּרֶךְ רַמָּאוּת וְהוּא שֶׁיְּסַפֵּר לְתֻמּוֹ כְּאִלּוּ אֵינוֹ יוֹדֵעַ שֶׁדָּבָר זֶה שֶׁדִּבֵּר לָשׁוֹן הָרַע הוּא אֶלָּא כְּשֶׁמְּמַחִין בּוֹ אוֹמֵר אֵינִי יוֹדֵעַ שֶׁדָּבָר זֶה לָשׁוֹן הָרַע אוֹ שֶׁאֵלּוּ מַעֲשָׂיו שֶׁל פְּלוֹנִי:","אֶחָד הַמְסַפֵּר בְּלָשׁוֹן הָרַע בִּפְנֵי חֲבֵרוֹ אוֹ שֶׁלֹּא בְּפָנָיו, וְהַמְסַפֵּר דְּבָרִים שֶׁגּוֹרְמִים אִם נִשְׁמְעוּ אִישׁ מִפִּי אִישׁ לְהַזִּיק חֲבֵרוֹ בְּגוּפוֹ אוֹ בְּמָמוֹנוֹ, וַאֲפִלּוּ לְהָצֵר לוֹ אוֹ לְהַפְחִידוֹ, הֲרֵי זֶה לָשׁוֹן הָרַע. וְאִם נֶאֶמְרוּ דְּבָרִים אֵלּוּ בִּפְנֵי שְׁלֹשָׁה כְּבָר נִשְׁמַע הַדָּבָר וְנוֹדַע. וְאִם סִפֵּר הַדָּבָר אֶחָד מִן הַשְּׁלֹשָׁה פַּעַם אַחֶרֶת אֵין בּוֹ מִשּׁוּם לָשׁוֹן הָרַע. וְהוּא שֶׁלֹּא יִתְכַּוֵּן לְהַעֲבִיר הַקּוֹל וּלְגַלּוֹתוֹ יוֹתֵר:","כָּל אֵלּוּ הֵם בַּעֲלֵי לָשׁוֹן הָרַע שֶׁאָסוּר לָדוּר בִּשְׁכוּנָתָם וְכָל שֶׁכֵּן לֵישֵׁב עִמָּהֶם וְלִשְׁמֹעַ דִּבְרֵיהֶם. וְלֹא נֶחְתַּם גְּזַר דִּין עַל אֲבוֹתֵינוּ בַּמִּדְבָּר אֶלָּא עַל לָשׁוֹן הָרַע לְבַד:","הַנּוֹקֵם מֵחֲבֵרוֹ עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר לֹא תִקֹּם. וְאַף עַל פִּי שֶׁאֵינוֹ לוֹקֶה עָלָיו דֵּעָה רָעָה הִיא עַד מְאֹד. אֶלָּא רָאוּי לוֹ לָאָדָם לִהְיוֹת מַעֲבִיר עַל מִדּוֹתָיו עַל כָּל דִּבְרֵי הָעוֹלָם שֶׁהַכּל אֵצֶל הַמְּבִינִים דִּבְרֵי הֶבֶל וַהֲבַאי וְאֵינָן כְּדַאי לִנְקֹם עֲלֵיהֶם. כֵּיצַד הִיא הַנְּקִימָה. אָמַר לוֹ חֲבֵרוֹ הַשְׁאִילֵנִי קַרְדֻּמְךָ, אָמַר לוֹ אֵינִי מַשְׁאִילְךָ. לְמָחָר צָרִיךְ לִשְׁאֹל מִמֶּנּוּ, אָמַר לוֹ חֲבֵרוֹ הַשְׁאִילֵנִי קַרְדֻּמְךָ, אָמַר לוֹ אֵינִי מַשְׁאִילְךָ כְּדֶרֶךְ שֶׁלֹּא הִשְׁאַלְתַּנִי כְּשֶׁשָּׁאַלְתִּי מִמְּךָ, הֲרֵי זֶה נוֹקֵם. אֶלָּא כְּשֶׁיָּבוֹא לוֹ לִשְׁאֹל יִתֵּן בְּלֵב שָׁלֵם וְלֹא יִגְמל לוֹ כַּאֲשֶׁר גְּמָלוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּאֵלּוּ. וְכֵן אָמַר דָּוִד בְּדֵעוֹתָיו הַטּוֹבוֹת (תהילים ז ה) \"אִם גָּמַלְתִּי שׁוֹלְמִי רָע וָאֲחַלְּצָה\" וְגוֹ':","וְכֵן כָּל הַנּוֹטֵר לְאֶחָד מִיִּשְׂרָאֵל עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (ויקרא יט יח) \"וְלֹא תִטֹּר אֶת בְּנֵי עַמֶּךָ\". כֵּיצַד הִיא הַנְּטִירָה. רְאוּבֵן שֶׁאָמַר לְשִׁמְעוֹן הַשְׂכֵּר לִי בַּיִת זֶה אוֹ הַשְׁאִילֵנִי שׁוֹר זֶה וְלֹא רָצָה שִׁמְעוֹן. לְיָמִים בָּא שִׁמְעוֹן לִרְאוּבֵן לִשְׁאֹל מִמֶּנּוּ אוֹ לִשְׂכֹּר מִמֶּנּוּ וְאָמַר לוֹ רְאוּבֵן הֵא לְךָ הֲרֵינִי מַשְׁאִילְךָ וְאֵינִי כְּמוֹתְךָ לֹא אֲשַׁלֵּם לְךָ כְּמַעֲשֶׂיךָ. הָעוֹשֶׂה כָּזֶה עוֹבֵר בְּלֹא תִטֹּר. אֶלָּא יִמְחֶה הַדָּבָר מִלִּבּוֹ וְלֹא יִטְּרֶנּוּ. שֶׁכָּל זְמַן שֶׁהוּא נוֹטֵר אֶת הַדָּבָר וְזוֹכְרוֹ שֶׁמָּא יָבוֹא לִנְקֹם. לְפִיכָךְ הִקְפִּידָה תּוֹרָה עַל הַנְּטִירָה עַד שֶׁיִּמְחֶה הֶעָוֹן מִלִּבּוֹ וְלֹא יִזְכְּרֶנּוּ כְּלָל. וְזוֹ הִיא הַדֵּעָה הַנְּכוֹנָה שֶׁאֶפְשָׁר שֶׁיִּתְקַיֵּם בָּהּ יִשּׁוּב הָאָרֶץ וּמַשָּׂאָם וּמַתָּנָם שֶׁל בְּנֵי אָדָם זֶה עִם זֶה:"],"Mishneh Torah, Inheritances 1":["סֵדֶר נְחָלוֹת כָּךְ הִיא. מִי שֶׁמֵּת יִירָשׁוּהוּ בָּנָיו וְהֵם קוֹדְמִין לַכּל. וְהַזְּכָרִים קוֹדְמִין לִנְקֵבוֹת:","בְּכָל מָקוֹם אֵין לִנְקֵבָה עִם הַזָּכָר יְרֻשָּׁה. אִם אֵין לוֹ בָּנִים יִירָשֶׁנּוּ אָבִיו. וְאֵין הָאֵם יוֹרֶשֶׁת אֶת בָּנֶיהָ וְדָבָר זֶה מִפִּי הַקַּבָּלָה:","וְכָל הַקּוֹדֵם בְּנַחֲלָה יוֹצְאֵי יְרֵכוֹ קוֹדְמִין. לְפִיכָךְ מִי שֶׁמֵּת בֵּין אִישׁ בֵּין אִשָּׁה אִם הִנִּיחַ בֵּן יוֹרֵשׁ הַכּל. לֹא נִמְצָא לוֹ בֵּן לְעוֹלָם מְעַיְּנִין בְּזַרְעוֹ שֶׁל בֵּן אִם נִמְצָא לִבְנוֹ זֶרַע בֵּין זְכָרִים בֵּין נְקֵבוֹת אֲפִלּוּ בַּת בַּת בַּת בְּנוֹ עַד סוֹף הָעוֹלָם הִיא תִּירַשׁ אֶת הַכּל. לֹא נִמְצָא לוֹ זֶרַע בֶּן חוֹזְרִין אֵצֶל הַבַּת. הָיְתָה לוֹ בַּת תִּירַשׁ אֶת הַכּל לֹא נִמְצֵאת לוֹ בַּת בָּעוֹלָם מְעַיְּנִין עַל זֶרַע הַבַּת. אִם נִמְצָא לָהּ זֶרַע בֵּין זְכָרִים בֵּין נְקֵבוֹת עַד סוֹף הָעוֹלָם הוּא יוֹרֵשׁ הַכּל. לֹא נִמְצָא לָהּ זֶרַע בַּת חוֹזֵר הַיְרֻשָּׁה לְאָבִיו. לֹא הָיָה אָבִיו קַיָּם מְעַיְּנִין עַל זֶרַע הָאָב שֶׁהֵן אֲחֵי הַמֵּת. נִמְצָא לוֹ אָח אוֹ זֶרַע אָח יוֹרֵשׁ אֶת הַכּל וְאִם לָאו חוֹזְרִין אֵצֶל אָחוֹת. נִמְצֵאת לוֹ אָחוֹת אוֹ זַרְעָהּ יוֹרֵשׁ הַכּל. וְאִם לֹא נִמְצֵאת לוֹ זֶרַע אַחִים וְלֹא זֶרַע אָחוֹת הוֹאִיל וְאֵין לָאָב זֶרַע תַּחְזֹר הַיְרֻשָּׁה לַאֲבִי הָאָב. לֹא הָיָה אֲבִי הָאָב קַיָּם מְעַיְּנִין עַל זֶרַע שֶׁל אֲבִי הָאָב שֶׁהֵן אֲחֵי אָבִיו שֶׁל מֵת וְהַזְּכָרִים קוֹדְמִין לִנְקֵבוֹת וְזַרְעָן שֶׁל זְכָרִים קוֹדְמִין לִנְקֵבוֹת כְּמוֹ שֶׁהָיָה הַדִּין בְּזַרְעוֹ שֶׁל מֵת עַצְמוֹ. לֹא נִמְצְאוּ אַחִים לְאָבִיו לֹא הֵם וְלֹא זַרְעָן תַּחְזֹר הַיְרֻשָּׁה לַאֲבִי אֲבִי הָאָב. וְעַל הַדֶּרֶךְ הַזֹּאת נַחֲלָה מְמַשְׁמֶשֶׁת וְהוֹלֶכֶת עַד רְאוּבֵן. נִמְצֵאתָ אוֹמֵר הַבֵּן קוֹדֵם לַבַּת וְכָל יוֹצְאֵי יְרֵכוֹ שֶׁל בֵּן קוֹדְמִין לַבַּת וְהַבַּת קוֹדֶמֶת לַאֲבִי אָבִיהָ וְכָל יוֹצְאֵי יְרֵכָהּ קוֹדְמִין לַאֲבִי אָבִיהָ. וַאֲבִי הַמֵּת קוֹדֵם לַאֲחֵי הַמֵּת מִפְּנֵי שֶׁהֵם יוֹצְאֵי יְרֵכוֹ וְהָאָח קוֹדֵם לָאָחוֹת. וְכָל יוֹצְאֵי יְרֵכוֹ שֶׁל אָח קוֹדְמִין לָאָחוֹת. וְאָחוֹת קוֹדֶמֶת לַאֲבִי אָבִיהָ. וְכָל יוֹצְאֵי יְרֵכָהּ קוֹדְמִין לַאֲבִי אָבִיהָ. אֲבִי הָאָב קוֹדֵם לַאֲחֵי הָאָב שֶׁל מֵת וַאֲחֵי אָבִיו קוֹדְמִין לַאֲחוֹת אָבִיו וְכָל יוֹצְאֵי יְרֵכוֹ שֶׁל אֲחֵי אָבִיו קוֹדְמִין לַאֲחוֹת אָבִיו וַאֲחוֹת אָבִיו קוֹדֶמֶת לַאֲבִי אֲבִי אָבִיו שֶׁל מֵת. וְכֵן כָּל יוֹצְאֵי יְרֵכָהּ שֶׁל אֲחוֹת אָבִיו קוֹדְמִין לַאֲבִי אֲבִי אָבִיו. וְעַל דֶּרֶךְ זוֹ הוֹלֵךְ וְעוֹלֶה עַד רֹאשׁ הַדּוֹרוֹת. לְפִיכָךְ אֵין לְךָ אָדָם מִיִּשְׂרָאֵל שֶׁאֵין לוֹ יוֹרְשִׁין:","מִי שֶׁמֵּת וְהִנִּיחַ בַּת וּבַת הַבֵּן וַאֲפִלּוּ בַּת בַּת בַּת הַבֵּן עַד סוֹף כַּמָּה דּוֹרוֹת הִיא קוֹדֶמֶת וְתִירַשׁ הַכּל וְאֵין לַבַּת כְּלוּם. וְהוּא הַדִּין לְבַת הָאָח עִם הָאָחוֹת וּלְבַת בֶּן אֲחִי אָבִיו עִם אֲחוֹת אָבִיו. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן:","מִי שֶׁהָיוּ לוֹ שְׁנֵי בָּנִים וּמֵתוּ הַשְּׁנֵי בָּנִים בְּחַיָּיו וְהִנִּיחַ הַבֵּן הָאֶחָד שְׁלֹשָׁה בָּנִים וְהִנִּיחַ הַבֵּן הַשֵּׁנִי בַּת אַחַת וְאַחַר כָּךְ מֵת הַזָּקֵן נִמְצְאוּ שְׁלֹשֶׁת בְּנֵי בָּנָיו יוֹרְשִׁין חֲצִי הַנַּחֲלָה וּבַת בְּנוֹ יוֹרֶשֶׁת הַחֵצִי שֶׁכָּל אֶחָד וְאֶחָד מֵהֶן יוֹרֵשׁ חֵלֶק אָבִיו. וְעַל דֶּרֶךְ זוֹ חוֹלְקִין בְּנֵי הָאַחִים וּבְנֵי אֲחֵי הָאָב עַד רֹאשׁ הַדּוֹרוֹת:","מִשְׁפַּחַת הָאֵם אֵינָהּ קְרוּיָה מִשְׁפָּחָה וְאֵין יְרֻשָּׁה אֶלָּא לְמִשְׁפַּחַת הָאָב. לְפִיכָךְ הָאַחִים מִן הָאֵם אֵין יוֹרְשִׁין זֶה אֶת זֶה וְאַחִין מִן הָאָב יוֹרְשִׁין זֶה אֶת זֶה. וְאֶחָד אָחִיו שֶׁהוּא מֵאָבִיו בִּלְבַד אוֹ אָחִיו מֵאָבִיו וּמֵאִמּוֹ:","כָּל הַקְּרוֹבִין בַּעֲבֵרָה יוֹרְשִׁין כִּכְשֵׁרִים. כֵּיצַד. כְּגוֹן שֶׁהָיָה לוֹ בֵּן מַמְזֵר אוֹ אָח מַמְזֵר הֲרֵי אֵלּוּ כִּשְׁאָר בָּנִים וְכִשְׁאָר אַחִים לַנַּחֲלָה. אֲבָל בְּנוֹ מִן הַשִּׁפְחָה אוֹ מִן הַנָּכְרִית אֵינוֹ בֵּן לְדָבָר מִן הַדְּבָרִים וְאֵינוֹ יוֹרֵשׁ כְּלָל:","הָאִשָּׁה אֵינָהּ יוֹרֶשֶׁת בַּעְלָהּ כְּלָל. וְהַבַּעַל יוֹרֵשׁ אֶת כָּל נִכְסֵי אִשְׁתּוֹ מִדִּבְרֵי סוֹפְרִים. וְהוּא קוֹדֵם לַכּל בִּירֻשָּׁתָהּ אַף עַל פִּי שֶׁהִיא אֲסוּרָה עָלָיו. כְּגוֹן אַלְמָנָה לְכֹהֵן גָּדוֹל גְּרוּשָׁה וַחֲלוּצָה לְכֹהֵן הֶדְיוֹט. וְאַף עַל פִּי שֶׁהִיא קְטַנָּה וְאַף עַל פִּי שֶׁהַבַּעַל חֵרֵשׁ הוּא יוֹרֵשׁ אֶת אִשְׁתּוֹ:","כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת אִישׁוּת שֶׁאֵין הַבַּעַל יוֹרֵשׁ אֶת אִשְׁתּוֹ עַד שֶׁתִּכָּנֵס בִּרְשׁוּתוֹ וְשֶׁאֵין הַפִּקֵּחַ יוֹרֵשׁ אֶת הַחֵרֶשֶׁת שֶׁנִּשֵּׂאת כְּשֶׁהִיא חֵרֶשֶׁת אֲפִלּוּ נִתְפַּקְּחָה. וְשָׁם בֵּאַרְנוּ שֶׁהוּא יוֹרֵשׁ אֶת נִכְסֵי אִשְׁתּוֹ שֶׁבָּאוּ לִירֻשָּׁתָהּ וְהֻחְזְקוּ בֵּין נְכָסִים שֶׁהִכְנִיסָה לוֹ בִּנְדֻנְיָתָהּ בֵּין נְכָסִים שֶׁלֹּא הִכְנִיסָה לוֹ. וּמִי שֶׁנִּתְגָּרְשָׁה סְפֵק גֵּרוּשִׁין וּמֵתָה אֵין הַבַּעַל יוֹרְשָׁהּ:","בַּעַל שֶׁנָּשָׂא קְטַנָּה שֶׁאֵינָהּ צְרִיכָה מֵאוּן אֵינוֹ יוֹרְשָׁהּ שֶׁהֲרֵי אֵין כָּאן שׁוּם אִישׁוּת. וְכֵן שׁוֹטֶה שֶׁנָּשָׂא פִּקַּחַת אוֹ פִּקֵּחַ שֶׁנָּשָׂא שׁוֹטָה אֵינוֹ יוֹרְשָׁהּ שֶׁהֲרֵי לֹא תִּקְּנוּ חֲכָמִים לָהֶן נִשּׂוּאִין:","בַּעַל שֶׁמֵּתָה אִשְׁתּוֹ וְאַחַר כָּךְ מֵת אָבִיהָ אוֹ אָחִיהָ אוֹ אֶחָד מִן הַמּוֹרִישִׁין אוֹתָהּ אֵין הַבַּעַל יוֹרֵשׁ אוֹתָן. אֶלָּא יוֹרֵשׁ אוֹתָן זַרְעָהּ אִם הָיָה לָהּ זֶרַע אוֹ תַּחְזֹר הַיְרֻשָּׁה לְמִשְׁפַּחַת בֵּית אָבִיהָ. שֶׁאֵין הַבַּעַל יוֹרֵשׁ נְכָסִים הָרְאוּיִין לָבֹא לְאַחַר מִכָּאן אֶלָּא לַנְּכָסִים שֶׁכְּבָר בָּאוּ לִירֻשָּׁה קֹדֶם שֶׁתָּמוּת:","וְכֵן אֵין הַבַּעַל יוֹרֵשׁ אֶת אִשְׁתּוֹ וְהוּא בַּקֶּבֶר כִּשְׁאָר הַיּוֹרְשִׁין שֶׁל מִשְׁפַּחַת הָאָב. כֵּיצַד. בַּעַל שֶׁמֵּת וְאַחַר כָּךְ מֵתָה אִשְׁתּוֹ אֵין אוֹמְרִין הוֹאִיל וְהַבַּעַל הָיָה קוֹדֵם לְכָל אָדָם בִּירֻשָּׁתָהּ כָּךְ יוֹרְשֵׁי הַבַּעַל יִקְדְּמוּ לִשְׁאָר יוֹרְשֵׁי הָאִשָּׁה אֶלָּא יוֹרְשֵׁי הָאִשָּׁה מִמִּשְׁפַּחַת בֵּית אָבִיהָ הֵם הַיּוֹרְשִׁים אוֹתָהּ אִם מֵתָה אַחַר בַּעְלָהּ:","וְכֵן אֵין הַבֵּן יוֹרֵשׁ אֶת אִמּוֹ בַּקֶּבֶר כְּדֵי לְהַנְחִיל לְאֶחָיו מֵאָבִיו. כֵּיצַד. מִי שֶׁמֵּת וְאַחַר כָּךְ מֵתָה אִמּוֹ אֵין אוֹמְרִין הוֹאִיל וְאִלּוּ הָיָה הַבֵּן קַיָּם הָיָה קוֹדֵם אַף יוֹרְשִׁין שֶׁל בֶּן קוֹדְמִין לְיוֹרְשֶׁיהָ שֶׁל אִשָּׁה זוֹ וְנִמְצְאוּ אֶחָיו מֵאָבִיו יוֹרְשִׁין אֶת אִמּוֹ שֶׁל זֶה אַחַר מוֹתוֹ שֶׁל זֶה. אֶלָּא זֶרַע בְּנָהּ הוּא שֶׁיִּירָשֶׁנָּה אִם הָיָה לוֹ זֶרַע וְאִם אֵין לוֹ זֶרַע תַּחְזֹר יְרֻשָּׁתָהּ לְמִשְׁפַּחַת בֵּית אָבִיהָ. אֲבָל אִם מֵתָה הָאֵם תְּחִלָּה וְאַחַר כָּךְ מֵת הַבֵּן אֲפִלּוּ הָיָה קָטָן בֶּן יוֹמוֹ וְלֹא כָּלוּ לוֹ חֳדָשָׁיו הוֹאִיל וְחָיָה אַחַר אִמּוֹ שָׁעָה אַחַת וּמֵת הֲרֵי זֶה נוֹחֵל אֶת אִמּוֹ וּמַנְחִיל הַנַּחֲלָה לְיוֹרְשָׁיו מִמִּשְׁפַּחַת אָבִיו:"],"Mishneh Torah, Kings and Wars 10":["בֶּן נֹחַ שֶׁשָּׁגַג בְּאַחַת מִמִּצְוֹתָיו פָּטוּר מִכְּלוּם. חוּץ מֵרוֹצֵחַ בִּשְׁגָגָה שֶׁאִם הֲרָגוֹ גּוֹאֵל הַדָּם אֵינוֹ נֶהֱרָג עָלָיו. וְאֵין לוֹ עִיר מִקְלָט. אֲבָל בָּתֵּי דִּינֵיהֶן אֵין מְמִיתִין אוֹתוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשָׁגַג בְּאַחַת מִמִּצְוֹת וְעָבַר בְּלֹא כַּוָּנָה. כְּגוֹן שֶׁבָּעַל אֵשֶׁת חֲבֵרוֹ וְדִמָּה שֶׁהִיא אִשְׁתּוֹ אוֹ פְּנוּיָה. אֲבָל אִם יָדַע שֶׁהִיא אֵשֶׁת חֲבֵרוֹ וְלֹא יָדַע שֶׁהִיא אֲסוּרָה עָלָיו. אֶלָּא עָלָה עַל לִבּוֹ שֶׁדָּבָר זֶה מֻתָּר לוֹ. וְכֵן אִם הָרַג וְהוּא לֹא יָדַע שֶׁאָסוּר לַהֲרֹג. הֲרֵי זֶה קָרוֹב לְמֵזִיד וְנֶהֱרָג. וְלֹא תֵּחָשֵׁב זוֹ לָהֶם שְׁגָגָה מִפְּנֵי שֶׁהָיָה לוֹ לִלְמֹד וְלֹא לָמַד:","בֶּן נֹחַ שֶׁאֲנָסוֹ אַנָּס לַעֲבֹר עַל אַחַת מִמִּצְוֹתָיו. מֻתָּר לוֹ לַעֲבֹר. אֲפִלּוּ נֶאֱנַס לַעֲבֹד עֲבוֹדָה זָרָה עוֹבֵד. לְפִי שֶׁאֵינָן מְצֻוִּין עַל קִדּוּשׁ הַשֵּׁם. וּלְעוֹלָם אֵין עוֹנְשִׁין מֵהֶן לֹא קָטָן וְלֹא חֵרֵשׁ וְלֹא שׁוֹטֶה לְפִי שֶׁאֵינָן בְּנֵי מִצְוֹת:","בֶּן נֹחַ שֶׁנִּתְגַּיֵּר וּמָל וְטָבַל וְאַחַר כָּךְ רָצָה לַחְזֹר מֵאַחֲרֵי ה' וְלִהְיוֹת גֵּר תּוֹשָׁב בִּלְבַד כְּשֶׁהָיָה מִקֹּדֶם. אֵין שׁוֹמְעִין לוֹ. אֶלָּא יִהְיֶה כְּיִשְׂרָאֵל לְכָל דָּבָר אוֹ יֵהָרֵג. וְאִם הָיָה קָטָן כְּשֶׁהִטְבִּילוּהוּ בֵּית דִּין. יָכוֹל לִמְחוֹת בְּשָׁעָה שֶׁיַּגְדִּיל וְיִהְיֶה גֵּר תּוֹשָׁב בִּלְבַד. וְכֵיוָן שֶׁלֹּא מִחָה בִּשְׁעָתוֹ שׁוּב אֵינוֹ מוֹחֶה אֶלָּא הֲרֵי הוּא גֵּר צֶדֶק. לְפִיכָךְ אִם בָּא יִשְׂרָאֵל עַל קְטַנָּה שֶׁהִטְבִּילוּהָ בֵּית דִּין. כֶּסֶף כְּתֻבָּתָהּ אוֹ קְנָס אוֹנֵס אוֹ מְפַתֶּה יִהְיֶה הַכּל תַּחַת יַד בֵּית דִּין עַד שֶׁתַּגְדִּיל וְלֹא תִּמְחֶה בַּגֵּרוּת. שֶׁמָּא תִּטּל וְתַגְדִּיל וְתִמְחֶה וְנִמְצֵאת זוֹ אוֹכֶלֶת בְּגֵיוּתָהּ מָעוֹת שֶׁאֵין לָהּ זְכוּת בָּהֶן אֶלָּא בְּדִינֵי יִשְׂרָאֵל:","בֶּן נֹחַ שֶׁבֵּרֵךְ אֶת הַשֵּׁם אוֹ שֶׁעָבַד עֲבוֹדָה זָרָה אוֹ שֶׁבָּא עַל אֵשֶׁת חֲבֵרוֹ אוֹ שֶׁהָרַג חֲבֵרוֹ וְנִתְגַּיֵּר. פָּטוּר. הָרַג בֶּן יִשְׂרָאֵל אוֹ שֶׁבָּא עַל אֵשֶׁת יִשְׂרָאֵל וְנִתְגַּיֵּר חַיָּב וְהוֹרְגִין אוֹתוֹ עַל בֶּן יִשְׂרָאֵל. וְחוֹנְקִין אוֹתוֹ עַל אֵשֶׁת יִשְׂרָאֵל שֶׁבָּעַל שֶׁהֲרֵי נִשְׁתַּנָּה דִּינוֹ:","כְּבָר בֵּאַרְנוּ שֶׁכָּל מִיתַת בְּנֵי נֹחַ בְּסַיִף. אֶלָּא אִם בָּעַל אֵשֶׁת יִשְׂרָאֵל אוֹ נַעֲרָה מְאֹרָסָה יִסָּקֵל. וְאִם בְּעָלָהּ אַחַר שֶׁנִּכְנְסָה לַחֻפָּה קֹדֶם שֶׁתִּבָּעֵל יֵחָנֵק:","מִפִּי הַקַּבָּלָה שֶׁבְּנֵי נֹחַ אֲסוּרִין בְּהַרְבָּעַת בְּהֵמָה וּבְהַרְכָּבַת אִילָן בִּלְבַד. וְאֵין נֶהֱרָגִין עֲלֵיהֶן. וְעַכּוּ\"ם שֶׁהִכָּה יִשְׂרָאֵל אֲפִלּוּ חָבַל בּוֹ כָּל שֶׁהוּא אַף עַל פִּי שֶׁהוּא חַיָּב מִיתָה אֵינוֹ נֶהֱרָג:","הַמִּילָה נִצְטַוָּה בָּהּ אַבְרָהָם וְזַרְעוֹ בִּלְבַד. שֶׁנֶּאֱמַר (בראשית יז, ט) \"אַתָּה וְזַרְעֲךָ אַחֲרֶיךָ\". יָצָא זַרְעוֹ שֶׁל יִשְׁמָעֵאל שֶׁנֶּאֱמַר (בראשית כא, יב) \"כִּי בְיִצְחָק יִקָּרֵא לְךָ זָרַע\". וְיָצָא עֵשָׂו שֶׁהֲרֵי יִצְחָק אָמַר לְיַעֲקֹב (בראשית כח, ד) \"וְיִתֶּן לְךָ אֶת בִּרְכַּת אַבְרָהָם לְךָ וּלְזַרְעֲךָ\". מִכְלַל שֶׁהוּא לְבַדּוֹ זַרְעוֹ שֶׁל אַבְרָהָם הַמַּחֲזִיק בְּדָתוֹ וּבְדַרְכּוֹ הַיְשָׁרָה. וְהֵם הַמְחֻיָּבִין בְּמִילָה:","אָמְרוּ חֲכָמִים שֶׁבְּנֵי קְטוּרָה שֶׁהֵם זַרְעוֹ שֶׁל אַבְרָהָם שֶׁבָּא אַחַר יִשְׁמָעֵאל וְיִצְחָק חַיָּבִין בְּמִילָה. וְהוֹאִיל וְנִתְעָרְבוּ הַיּוֹם בְּנֵי יִשְׁמָעֵאל בִּבְנֵי קְטוּרָה יִתְחַיְּבוּ הַכּל בְּמִילָה בַּשְּׁמִינִי. וְאֵין נֶהֱרָגִין עָלֶיהָ:","עַכּוּ\"ם שֶׁעָסַק בַּתּוֹרָה חַיָּב מִיתָה. לֹא יַעֲסֹק אֶלָּא בְּשֶׁבַע מִצְוֹת שֶׁלָּהֶן בִּלְבַד. וְכֵן עַכּוּ\"ם שֶׁשָּׁבַת אֲפִלּוּ בְּיוֹם מִימוֹת הַחל אִם עֲשָׂאָהוּ לְעַצְמוֹ כְּמוֹ שַׁבָּת חַיָּב מִיתָה. וְאֵין צָרִיךְ לוֹמַר אִם עָשָׂה מוֹעֵד לְעַצְמוֹ. כְּלָלוֹ שֶׁל דָּבָר אֵין מְנִיחִין אוֹתָן לְחַדֵּשׁ דָּת וְלַעֲשׂוֹת מִצְוֹת לְעַצְמָן מִדַּעְתָּן. אֶלָּא אוֹ יִהְיֶה גֵּר צֶדֶק וִיקַבֵּל כָּל הַמִּצְוֹת. אוֹ יַעֲמֹד בְּתוֹרָתוֹ וְלֹא יוֹסִיף וְלֹא יִגְרַע. וְאִם עָסַק בַּתּוֹרָה אוֹ שָׁבַת אוֹ חִדֵּשׁ דָּבָר. מַכִּין אוֹתוֹ וְעוֹנְשִׁין אוֹתוֹ וּמוֹדִיעִין אוֹתוֹ שֶׁהוּא חַיָּב מִיתָה עַל זֶה. אֲבָל אֵינוֹ נֶהֱרָג:","בֶּן נֹחַ שֶׁרָצָה לַעֲשׂוֹת מִצְוָה מִשְּׁאָר מִצְוֹת הַתּוֹרָה כְּדֵי לְקַבֵּל שָׂכָר. אֵין מוֹנְעִין אוֹתוֹ לַעֲשׂוֹתָהּ כְּהִלְכָתָהּ. וְאִם הֵבִיא עוֹלָה מְקַבְּלִין מִמֶּנּוּ. נָתַן צְדָקָה מְקַבְּלִין מִמֶּנּוּ. וְיֵרָאֶה לִי שֶׁנּוֹתְנִין אוֹתָהּ לַעֲנִיֵּי יִשְׂרָאֵל. הוֹאִיל וְהוּא נִזּוֹן מִיִּשְׂרָאֵל וּמִצְוָה עֲלֵיהֶם לְהַחְיוֹתוֹ. אֲבָל הָעַכּוּ\"ם שֶׁנָּתַן צְדָקָה מְקַבְּלִין מִמֶּנּוּ וְנוֹתְנִין אוֹתָהּ לַעֲנִיֵּי עַכּוּ\"ם:","חַיָּבִין בֵּית דִּין שֶׁל יִשְׂרָאֵל לַעֲשׂוֹת שׁוֹפְטִים לְאֵלּוּ הַגֵּרִים הַתּוֹשָׁבִים לָדוּן לָהֶן עַל פִּי מִשְׁפָּטִים אֵלּוּ. כְּדֵי שֶׁלֹּא יִשָּׁחֵת הָעוֹלָם. אִם רָאוּ בֵּית דִּין שֶׁיַּעֲמִידוּ שׁוֹפְטֵיהֶם מֵהֶן מַעֲמִידִין. וְאִם רָאוּ שֶׁיַּעֲמִידוּ לָהֶן מִיִּשְׂרָאֵל מַעֲמִידִין:","שְׁנֵי עַכּוּ\"ם שֶׁבָּאוּ לְפָנֶיךָ לָדוּן בְּדִינֵי יִשְׂרָאֵל וְרָצוּ שְׁנֵיהֶן לָדוּן דִּין תּוֹרָה דָּנִין. הָאֶחָד רוֹצֶה וְהָאֶחָד אֵינוֹ רוֹצֶה אֵין כּוֹפִין אוֹתוֹ לָדוּן אֶלָּא בְּדִינֵיהֶן. הָיָה יִשְׂרָאֵל וְעַכּוּ\"ם אִם יֵשׁ זְכוּת לְיִשְׂרָאֵל בְּדִינֵיהֶן דָּנִין לוֹ בְּדִינֵיהֶם. וְאוֹמְרִים לוֹ כָּךְ דִּינֵיכֶם. וְאִם יֵשׁ זְכוּת לְיִשְׂרָאֵל בְּדִינֵינוּ דָּנִין לוֹ דִּין תּוֹרָה וְאוֹמְרִים לוֹ כָּךְ דִּינֵינוּ. וְיֵרָאֶה לִי שֶׁאֵין עוֹשִׂין כֵּן לְגֵר תּוֹשָׁב אֶלָּא לְעוֹלָם דָּנִין לוֹ בְּדִינֵיהֶם. וְכֵן יֵרָאֶה לִי שֶׁנּוֹהֲגִין עִם גֵּרֵי תּוֹשָׁב בְּדֶרֶךְ אֶרֶץ וּגְמִילוּת חֲסָדִים כְּיִשְׂרָאֵל. שֶׁהֲרֵי אָנוּ מְצֻוִּין לְהַחֲיוֹתָן שֶׁנֶּאֱמַר (דברים יד, כא) \"לַגֵּר אֲשֶׁר בִּשְׁעָרֶיךָ תִּתְּנֶנָּה וַאֲכָלָהּ\". וְזֶה שֶׁאָמְרוּ חֲכָמִים אֵין כּוֹפְלִין לָהֶן שָׁלוֹם בְּעַכּוּ\"ם לֹא בְּגֵר תּוֹשָׁב. אֲפִלּוּ הָעַכּוּ\"ם צִוּוּ חֲכָמִים לְבַקֵּר חוֹלֵיהֶם וְלִקְבֹּר מֵתֵיהֶם עִם מֵתֵי יִשְׂרָאֵל וּלְפַרְנֵס עֲנִיֵּיהֶם בִּכְלַל עֲנִיֵּי יִשְׂרָאֵל מִפְּנֵי דַּרְכֵי שָׁלוֹם. הֲרֵי נֶאֱמַר (תהילים קמה, ט) \"טוֹב ה' לַכּל וְרַחֲמָיו עַל כָּל מַעֲשָׂיו\". וְנֶאֱמַר (משלי ג, יז) \"דְּרָכֶיהָ דַרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם\":"],"Mishneh Torah, Leavened and Unleavened Bread 2":["מִצְוַת עֲשֵׂה מִן הַתּוֹרָה לְהַשְׁבִּית הֶחָמֵץ קֹדֶם זְמַן אִסּוּר אֲכִילָתוֹ שֶׁנֶּאֱמַר (שמות יב טו) \"בַּיּוֹם הָרִאשׁוֹן תַּשְׁבִּיתוּ שְּׂאֹר מִבָּתֵּיכֶם\". וּמִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁבָּרִאשׁוֹן זֶה הוּא יוֹם אַרְבָּעָה עָשָׂר. רְאָיָה לְדָבָר זֶה מַה שֶּׁכָּתוּב בַּתּוֹרָה (שמות לד כה) \"לֹא תִשְׁחַט עַל חָמֵץ דַּם זִבְחִי\" כְּלוֹמַר לֹא תִּשְׁחַט הַפֶּסַח וַעֲדַיִן הֶחָמֵץ קַיָּם. וּשְׁחִיטַת הַפֶּסַח הוּא יוֹם אַרְבָּעָה עָשָׂר אַחַר חֲצוֹת:","וּמַה הִיא הַשְׁבָּתָה זוֹ הָאֲמוּרָה בַּתּוֹרָה הִיא שֶׁיְּבַטֵּל הֶחָמֵץ בְּלִבּוֹ וְיַחֲשֹׁב אוֹתוֹ כְּעָפָר וְיָשִׂים בְּלִבּוֹ שֶׁאֵין בִּרְשׁוּתוֹ חָמֵץ כְּלָל. וְשֶׁכָּל חָמֵץ שֶׁבִּרְשׁוּתוֹ הֲרֵי הוּא כְּעָפָר וּכְדָבָר שֶׁאֵין בּוֹ צֹרֶךְ כְּלָל:","וּמִדִּבְרֵי סוֹפְרִים לְחַפֵּשׂ אַחַר הֶחָמֵץ בַּמַּחֲבוֹאוֹת וּבַחוֹרִים וְלִבְדֹּק וּלְהוֹצִיאוֹ מִכָּל גְּבוּלוֹ. וְכֵן מִדִּבְרֵי סוֹפְרִים שֶׁבּוֹדְקִין וּמַשְׁבִּיתִין הֶחָמֵץ בַּלַּיְלָה מִתְּחִלַּת לֵיל אַרְבָּעָה עָשָׂר לְאוֹר הַנֵּר. מִפְּנֵי שֶׁבַּלַּיְלָה כָּל הָעָם מְצוּיִין בַּבָּתִּים וְאוֹר הַנֵּר יָפֶה לִבְדִיקָה. וְאֵין קוֹבְעִין מִדְרָשׁ בְּסוֹף יוֹם שְׁלֹשָׁה עָשָׂר. וְכֵן הֶחָכָם לֹא יַתְחִיל לִקְרוֹת בְּעֵת זוֹ שֶׁמָּא יִמָּשֵׁךְ וְיִמָּנַע מִבְּדִיקַת חָמֵץ בִּתְחִלַּת זְמַנָּה:","אֵין בּוֹדְקִין לֹא לְאוֹר הַלְּבָנָה וְלֹא לְאוֹר הַחַמָּה וְלֹא לְאוֹר הָאֲבוּקָה אֶלָּא לְאוֹר הַנֵּר. בַּמֶּה דְּבָרִים אֲמוּרִים בְּחוֹרִים וּבְמַחֲבוֹאוֹת אֲבָל אַכְסַדְרָה שֶׁאוֹרָהּ רַב אִם בְּדָקָהּ לְאוֹר הַחַמָּה דַּיּוֹ. וְאֶמְצַע הֶחָצֵר אֵינוֹ צָרִיךְ בְּדִיקָה מִפְּנֵי שֶׁהָעוֹפוֹת מְצוּיִים שָׁם וְהֵן אוֹכְלִין כָּל חָמֵץ שֶׁיִּפּל שָׁם:","חוֹר שֶׁבְּאֶמְצַע הַבַּיִת שֶׁבֵּין אָדָם לַחֲבֵרוֹ זֶה בּוֹדֵק עַד מָקוֹם שֶׁיָּדוֹ מַגַּעַת וְזֶה בּוֹדֵק עַד מָקוֹם שֶׁיָּדוֹ מַגַּעַת וְהַשְּׁאָר מְבַטְּלוֹ בְּלִבּוֹ. אֲבָל חוֹר שֶׁבֵּין יִשְׂרָאֵל לְעַכּוּ\"ם אֵינוֹ בּוֹדֵק כְּלָל שֶׁמָּא יֹאמַר הָעַכּוּ\"ם כְּשָׁפִים הוּא עוֹשֶׂה לִי אֶלָּא מְבַטְּלוֹ בְּלִבּוֹ וְדַיּוֹ. וְכָל מָקוֹם שֶׁאֵין מַכְנִיסִין בּוֹ חָמֵץ אֵינוֹ צָרִיךְ בְּדִיקָה:","חוֹרֵי הַבַּיִת הַתַּחְתּוֹנִים וְהָעֶלְיוֹנִים וְגַג הַיָּצִיעַ וְרֶפֶת בָּקָר וְלוּלִין וּמַתְבֵּן וְאוֹצְרוֹת יַיִן וְאוֹצְרוֹת שֶׁמֶן שֶׁאֵינוֹ מִסְתַּפֵּק מֵהֶן וּבֵית דָּגִים גְּדוֹלִים אֵינָן צְרִיכִין בְּדִיקָה אֶלָּא אִם כֵּן הִכְנִיס לָהֶן חָמֵץ. אֲבָל אוֹצְרוֹת שֵׁכָר וְאוֹצְרוֹת יַיִן שֶׁמִּסְתַּפֵּק מִמֶּנּוּ וּבֵית דָּגִים קְטַנִּים וּבֵית הָעֵצִים וּבֵית הַמּוּרְיָס וְחוֹרֵי הַבַּיִת הָאֶמְצָעִים וְכַיּוֹצֵא בָּאֵלּוּ צְרִיכִין בְּדִיקָה שֶׁסְּתָמָן שֶׁמַּכְנִיסִין לָהֶן חָמֵץ. וְאִם יָדַע בְּוַדַּאי שֶׁלֹּא הִכְנִיס שָׁם חָמֵץ אֵינוֹ צָרִיךְ בְּדִיקָה. וּכְשֶׁבּוֹדֵק הַמַּרְתֵּף בּוֹדֵק מִמֶּנּוּ שְׁתֵּי שׁוּרוֹת הַחִיצוֹנוֹת שֶׁהֵן הָעֶלְיוֹנָה וְשֶׁלְּמַטָּה מִמֶּנָּה:","אֵין חוֹשְׁשִׁין שֶׁמָּא גָּרְרָה חֻלְדָּה חָמֵץ לְמָקוֹם שֶׁאֵין מַכְנִיסִין בּוֹ חָמֵץ שֶׁאִם נָחוּשׁ מִבַּיִת לְבַיִת נָחוּשׁ מֵעִיר לְעִיר וְאֵין לַדָּבָר סוֹף. בָּדַק לֵיל אַרְבָּעָה עָשָׂר וְהִנִּיחַ עֶשֶׂר חַלּוֹת וּמָצָא תֵּשַׁע הֲרֵי זֶה חוֹשֵׁשׁ וְצָרִיךְ לִבְדֹּק פַּעַם שְׁנִיָּה שֶׁהֲרֵי גָּרְרָה חֻלְדָּה אוֹ עַכְבָּר בְּוַדַּאי:","וְכֵן אִם רָאָה עַכְבָּר שֶׁנִּכְנַס לַבַּיִת וְחָמֵץ בְּפִיו אַחַר בְּדִיקָה צָרִיךְ לִבְדֹּק פַּעַם שְׁנִיָּה אַף עַל פִּי שֶׁמָּצָא פֵּרוּרִין בְּאֶמְצַע הַבַּיִת אֵין אוֹמְרִין כְּבָר אָכַל אוֹתָהּ הַפַּת בְּמָקוֹם זֶה וַהֲרֵי הַפֵּרוּרִין אֶלָּא חוֹשְׁשִׁין שֶׁמָּא הִנִּיחָה בְּחוֹר אוֹ בְּחַלּוֹן וְאִלּוּ הַפֵּרוּרִין שָׁם הָיוּ. וּלְפִיכָךְ חוֹזֵר וּבוֹדֵק. אִם לֹא מָצָא כְּלוּם הֲרֵי זֶה בּוֹדֵק כָּל הַבַּיִת וְאִם מָצָא אוֹתָהּ הַפַּת שֶׁנְּטָלָהּ הָעַכְבָּר וְנִכְנַס אֵין צָרִיךְ בְּדִיקָה:","רָאָה תִּינוֹק שֶׁנִּכְנַס לְבַיִת בָּדוּק וּבְיָדוֹ כִּכָּר וְנִכְנַס אַחֲרָיו וּמָצָא פֵּרוּרִין אֵינוֹ צָרִיךְ בְּדִיקָה שֶׁחֶזְקָתוֹ שֶׁאֲכָלוֹ וְאֵלּוּ הַפֵּרוּרִין שֶׁנָּפְלוּ מִמֶּנּוּ בִּשְׁעַת אֲכִילָה שֶׁדֶּרֶךְ הַתִּינוֹק לְפָרֵר בְּעֵת אֲכִילָתוֹ וְאֵין דֶּרֶךְ עַכְבָּר לְפָרֵר. וְאִם לֹא מָצָא פֵּרוּרִין כְּלָל צָרִיךְ לִבְדֹּק:","הִנִּיחַ תִּשְׁעָה צְבוּרִין שֶׁל מַצָּה וְאֶחָד שֶׁל חָמֵץ וּבָא עַכְבָּר וְנָטַל וְלֹא יָדַעְנוּ אִם חָמֵץ אוֹ מַצָּה נָטַל וְנִכְנַס לְבַיִת בָּדוּק צָרִיךְ לִבְדֹּק שֶׁכָּל הַקָּבוּעַ כְּמֶחֱצָה עַל מֶחֱצָה:","שְׁנֵי צְבוּרִין אֶחָד שֶׁל חָמֵץ וְאֶחָד שֶׁל מַצָּה וּשְׁנֵי בָּתִּים אֶחָד בָּדוּק וְאֶחָד שֶׁאֵינוֹ בָּדוּק וּבָאוּ שְׁנֵי עַכְבָּרִים זֶה נָטַל חָמֵץ וְזֶה נָטַל מַצָּה וְאֵין יָדוּעַ לְאֵי זֶה בַּיִת נִכְנַס זֶה שֶׁנָּטַל הֶחָמֵץ. וְכֵן שְׁנֵי בָּתִּים בְּדוּקִין וּצְבוּר אֶחָד שֶׁל חָמֵץ וּבָא עַכְבָּר וְנָטַל וְאֵין יָדוּעַ לְאֵיזֶה בַּיִת נִכְנַס. אוֹ שֶׁיָּדַע שֶׁנִּכְנַס לְאֶחָד מֵהֶן וְנִכְנַס אַחֲרָיו וּבָדַק וְלֹא מָצָא כְּלוּם אוֹ שֶׁבָּדַק וּמָצָא כִּכָּר. אוֹ שֶׁהָיוּ תִּשְׁעָה צְבוּרִין שֶׁל מַצָּה וְאֶחָד שֶׁל חָמֵץ וּפֵרַשׁ כִּכָּר מֵהֶן וְאֵין יָדוּעַ אִם חָמֵץ אִם מַצָּה וּבָא עַכְבָּר וְנָטַל הַכִּכָּר שֶׁפֵּרַשׁ וְנִכְנַס לְבַיִת בָּדוּק בְּכָל אֵלּוּ אֵינוֹ צָרִיךְ לִבְדֹּק פַּעַם שְׁנִיָּה שֶׁאֵין כָּאן קָבוּעַ:","הִנִּיחַ הֶחָמֵץ בְּזָוִית זוֹ וּמְצָאוֹ בְּזָוִית אַחֵר אוֹ שֶׁהִנִּיחַ תֵּשַׁע חַלּוֹת וּמָצָא עֶשֶׂר. אוֹ שֶׁבָּא עַכְבָּר וְנָטַל הֶחָמֵץ וְסָפֵק נִכְנַס לְבַיִת זֶה אוֹ לֹא נִכְנַס. בְּכָל אֵלּוּ צָרִיךְ לִבְדֹּק:","נִכְנַס עַכְבָּר לְבַיִת וְכִכָּר בְּפִיו וְיָצָא עַכְבָּר מִשָּׁם וְכִכָּר בְּפִיו אוֹמְרִים הוּא הָרִאשׁוֹן שֶׁנִּכְנַס הוּא הָאַחֲרוֹן שֶׁיָּצָא וְאֵינוֹ צָרִיךְ לִבְדֹּק. הָיָה הָרִאשׁוֹן שֶׁנִּכְנַס שָׁחוֹר וְזֶה שֶׁיָּצָא לָבָן צָרִיךְ לִבְדֹּק. נִכְנַס עַכְבָּר וְכִכָּר בְּפִיו וְיָצְאתָה מִשָּׁם חֻלְדָּה וְכִכָּר בְּפִיהָ צָרִיךְ לִבְדֹּק. יָצָאת מִשָּׁם חֻלְדָּה וְעַכְבָּר וְכִכָּר בְּפִיהָ אֵינוֹ צָרִיךְ לִבְדֹּק שֶׁזֶּה הַכִּכָּר הוּא שֶׁהָיָה בְּפִי הָעַכְבָּר. נָחָשׁ שֶׁנִּכְנַס לְחוֹר וּפַת בְּפִיו אֵין חַיָּב לְהָבִיא חֲבָּר לְהוֹצִיאוֹ:","כְּזַיִת חָמֵץ בִּשְׁמֵי קוֹרָה מְחַיְּבִין אוֹתוֹ לְהָבִיא סֻלָּם לְהוֹרִידוֹ שֶׁפְּעָמִים יִפּל מִשְּׁמֵי קוֹרָה. הָיָה חָמֵץ בְּבוֹר אֵין מְחַיְּבִין אוֹתוֹ לְהַעֲלוֹתוֹ אֶלָּא מְבַטְּלוֹ בְּלִבּוֹ וְדַיּוֹ:","כִּפַּת שְׂאוֹר שֶׁיִּחֲדָהּ לִישִׁיבָה אִם טָח פָּנֶיהָ בְּטִיט הֲרֵי זוֹ בְּטֵלָה וּמֻתָּר לְקַיְּמָהּ. בָּצֵק שֶׁבְּסִדְקֵי הָעֲרֵבָה אִם יֵשׁ כְּזַיִת בְּמָקוֹם אֶחָד חַיָּב לְבַעֵר. וְאִם לָאו אִם הָיָה עָשׂוּי לְחַזֵּק בּוֹ שִׁבְרֵי הָעֲרֵבָה אוֹ לִסְתֹּם בּוֹ נֶקֶב בָּטֵל בְּמִעוּטוֹ וְאִם לָאו חַיָּב לְבַעֵר. הָיוּ בּוֹ שְׁנֵי חֲצָאֵי זֵיתִים בִּשְׁנֵי מְקוֹמוֹת וְחוּט שֶׁל בָּצֵק בֵּינֵיהֶם רוֹאִין כּל שֶׁאִלּוּ יִנָּטֵל הַחוּט נִטָּלִין עִמּוֹ חַיָּב לְבַעֵר וְאִם לָאו אֵינוֹ צָרִיךְ לְבַעֵר:","בַּמֶּה דְּבָרִים אֲמוּרִים בַּעֲרֵבָה אֲבָל בְּבַיִת אַף עַל פִּי שֶׁאִם יִנָּטֵל הַחוּט אֵין נִטָּלִין עִמּוֹ חַיָּב לְבַעֵר מִפְּנֵי שֶׁפְּעָמִים מְקַבֵּץ אוֹתָן. הָיָה חֲצִי זַיִת בַּבַּיִת וַחֲצִי זַיִת בָּעֲלִיָּה. חֲצִי זַיִת בַּבַּיִת וַחֲצִי זַיִת בָּאַכְסַדְרָה. חֲצִי זַיִת בְּבַיִת זֶה וַחֲצִי זַיִת בְּבַיִת שֶׁלִּפְנִים מִמֶּנּוּ. הוֹאִיל וְאֵלּוּ הַחֲצָאֵי זֵיתִים דְּבוּקִין בַּכְּתָלִים אוֹ בַּקּוֹרוֹת אוֹ בַּקַּרְקָעוֹת אֵינוֹ חַיָּב לְבָעֵר אֶלָּא מְבַטֵּל בְּלִבּוֹ וְדַיּוֹ:","הַמַּשְׂכִּיר בַּיִת סְתָם בְּאַרְבָּעָה עָשָׂר הֲרֵי זֶה בְּחֶזְקַת בָּדוּק וְאֵינוֹ צָרִיךְ לִבְדֹּק. וְאִם הֻחְזַק זֶה הַמַּשְׂכִּיר שֶׁלֹּא בָּדַק וְאָמְרוּ אִשָּׁה אוֹ קָטָן אָנוּ בְּדַקְנוּהוּ הֲרֵי אֵלּוּ נֶאֱמָנִין שֶׁהַכּל נֶאֱמָנִים עַל בִּעוּר חָמֵץ. וְהַכּל כְּשֵׁרִין לִבְדִיקָה וַאֲפִלּוּ נָשִׁים וַעֲבָדִים וּקְטַנִּים וְהוּא שֶׁיִּהְיֶה קָטָן שֶׁיֵּשׁ בּוֹ דַּעַת לִבְדֹּק:","הַמַּשְׂכִּיר בַּיִת לַחֲבֵרוֹ אִם עַד שֶׁלֹּא מָסַר לוֹ הַמַּפְתֵּחַ חָל אַרְבָּעָה עָשָׂר עַל הַמַּשְׂכִּיר לִבְדֹּק. וְאִם מִשֶּׁמָּסַר הַמַּפְתֵּחַ חָל אַרְבָּעָה עָשָׂר עַל הַשּׂוֹכֵר לִבְדֹּק. הַמַּשְׂכִּיר בַּיִת בְּחֶזְקַת שֶׁהוּא בָּדוּק וְנִמְצָא שֶׁאֵינוֹ בָּדוּק עַל הַשּׂוֹכֵר לִבְדֹּק וְאֵינוֹ מִקָּח טָעוּת. וַאֲפִלּוּ בְּמָקוֹם שֶׁבּוֹדְקִים בְּשָׂכָר שֶׁהֲרֵי מִצְוָה הוּא עוֹשֶׂה:","הַמְפָרֵשׁ בַּיָּם וְהַיּוֹצֵא בְּשַׁיָּרָא תּוֹךְ שְׁלֹשִׁים יוֹם זָקוּק לִבְדֹּק. קֹדֶם שְׁלֹשִׁים יוֹם אֵינוֹ צָרִיךְ לִבְדֹּק. וְאִם דַּעְתּוֹ לַחֲזֹר קֹדֶם הַפֶּסַח צָרִיךְ לִבְדֹּק וְאַחַר כָּךְ יֵצֵא שֶׁמָּא יַחֲזֹר עֶרֶב הַפֶּסַח בֵּין הַשְּׁמָשׁוֹת וְלֹא יִהְיֶה לוֹ פְּנַאי לְבַעֵר. וְאִם אֵין דַּעְתּוֹ לַחֲזֹר אֵין צָרִיךְ לִבְדֹּק. וְכֵן הָעוֹשֶׂה בֵּיתוֹ אוֹצָר. תּוֹךְ שְׁלֹשִׁים יוֹם זָקוּק לִבְדֹּק וְאַחַר כָּךְ כּוֹנֵס אוֹצָרוֹ לְתוֹכוֹ. קֹדֶם שְׁלֹשִׁים יוֹם אִם דַּעְתּוֹ לְפַנּוֹתוֹ קֹדֶם הַפֶּסַח צָרִיךְ לִבְדֹּק וְאַחַר כָּךְ עוֹשֵׂהוּ אוֹצָר. וְאִם אֵין דַּעְתּוֹ לְפַנּוֹתוֹ קֹדֶם הַפֶּסַח אֵינוֹ צָרִיךְ לִבְדֹּק:"],"Mishneh Torah, Levirate Marriage and Release 5":["הַיְבָמָה שֶׁנָּתַן לָהּ הַיָּבָם גֵּט כְּרִיתוּת פְּסָלָהּ וּפָסַל אֶת צָרוֹתֶיהָ עָלָיו וְעַל שְׁאָר הָאַחִין שֶׁהֲרֵי נַעֲשָׂה כְּמִי שֶׁחָלַץ לָהּ. וְאֵין הַגֵּט מוֹעִיל בִּיבָמָה אֶלָּא מִדִּבְרֵיהֶן הוֹאִיל וְהַגֵּט מְגָרֵשׁ אֵשֶׁת אִישׁ. וְכָל גֵּט שֶׁפּוֹסֵל אִשְׁתּוֹ מִן הַכְּהֻנָּה פּוֹסֵל אֶת יְבִמְתּוֹ מִן הַיִּבּוּם וְאֵינָהּ מֻתֶּרֶת לְזָר עַד שֶׁיַּחֲלֹץ לָהּ:","הַמַּאֲמָר אַף עַל פִּי שֶׁאֵינוֹ קוֹנֶה בִּיבָמָה קִנְיָן גָּמוּר וְאֵינָהּ נַעֲשֵׂית בּוֹ אֵשֶׁת אִישׁ גְּמוּרָה צְרִיכָה מִמֶּנּוּ גֵּט וְאֵינָהּ נִתֶּרֶת לְזָר אֶלָּא בַּחֲלִיצָה:","כֵּיצַד. הָעוֹשֶׂה מַאֲמָר בִּיבִמְתּוֹ וְאֵינוֹ רוֹצֶה לִבְעל צָרִיךְ לִכְתֹּב לָהּ גֵּט שֶׁהֲרֵי נִתְקַדְּשָׁה לוֹ. וְצָרִיךְ לַחֲלֹץ לָהּ כְּדֵי לְהַתִּירָהּ לְזָר. שֶׁאֵין הַיְבָמָה נִתֶּרֶת לְזָר אֶלָּא אַחַר בְּעִילַת הַיָּבָם אוֹ אַחַר חֲלִיצָה. אֲבָל הַגֵּט פּוֹסְלָהּ לְיִבּוּם וְאֵינוֹ מַתִּירָהּ לְזָר. וְהַמַּאֲמָר אֵינוֹ קוֹנֶה בָּהּ קִנְיָן גָּמוּר כְּמוֹ הַבְּעִילָה:","נָתַן מַאֲמָר לִיבִמְתּוֹ וְחָזַר וְנָתַן גֵּט לְמַאֲמָרוֹ מַה שֶּׁעָשָׂה הֲרֵי בִּטְּלוֹ וְהֻתְּרָה. וְיֵרָאֶה לִי שֶׁלֹּא הֻתְּרָה אֶלָּא לְאֶחָיו אֲבָל זֶה שֶׁנָּתַן הַגֵּט אֲסוּרָה הִיא לוֹ:","נָתַן גֵּט לְזִקָּתוֹ [וְלֹא לְמַאֲמָרוֹ] פְּסָלָהּ עָלָיו וְעַל שְׁאָר הָאַחִין כְּמוֹ שֶׁבֵּאַרְנוּ וּצְרִיכָה גֵּט לְמַאֲמָרוֹ וַחֲלִיצָה לְהַתִּירָהּ לְזָר:","הַמַּאֲמָר שֶׁנִּתַּן לִיבָמָה תְּחִלָּה וְלֹא קְדָמוֹ דָּבָר אַחֵר וְלֹא נַעֲשָׂה אַחֲרָיו דָּבָר אַחֵר אֶלָּא שֶׁבָּעַל אוֹתָהּ זֶה שֶׁנָּתַן לָהּ הַמַּאֲמָר הוּא הַנִּקְרָא מַאֲמָר כָּשֵׁר. וְאִם קְדָמוֹ גֵּט אוֹ חֲלִיצָה בֵּין מִיָּבָם זֶה בֵּין מִיָּבָם אַחֵר בֵּין בָּהּ בֵּין בְּצָרָתָהּ. וְכֵן אִם קְדָמַתּוּ בְּעִילָה בְּצָרָתָהּ בֵּין מִמֶּנּוּ בֵּין מֵאֶחָיו. אוֹ שֶׁנַּעֲשָׂה אַחֲרָיו גֵּט אוֹ חֲלִיצָה בֵּין בָּהּ בֵּין בְּצָרָתָהּ בֵּין מִמֶּנּוּ בֵּין מֵאֶחָיו. אוֹ שֶׁבָּעַל אוֹ נָתַן מַאֲמָר אַחֵר לְצָרָתָהּ בֵּין הוּא בֵּין אָחִיו. אוֹ שֶׁנָּתַן לָהּ אָחִיו מַאֲמָר אַחֵר אוֹ בְּעָלָהּ הֲרֵי זֶה נִקְרָא מַאֲמָר פָּסוּל. בֵּין הַמַּאֲמָר שֶׁקְּדָמוּהוּ הַמַּעֲשִׂים הָאֵלּוּ בֵּין הַמַּאֲמָר שֶׁנִּתְאַחֲרוּ אַחֲרָיו:","כֵּיצַד. נָתַן גֵּט אוֹ חָלַץ לִיבִמְתּוֹ וְחָזַר וְנָתַן מַאֲמָר לָהּ אוֹ לְצָרָתָהּ בֵּין הוּא בֵּין אֶחָיו. אוֹ שֶׁבָּא עַל יְבִמְתּוֹ אוֹ נָתַן לָהּ מַאֲמָר וְחָזַר וְנָתַן לָהּ מַאֲמָר אַחֵר לְצָרָתָהּ בֵּין הוּא בֵּין אֶחָיו. אוֹ שֶׁנָּתַן מַאֲמָר לִיבִמְתּוֹ וְחָזַר אָחִיו וְנָתַן לָהּ מַאֲמָר אַחֵר אוֹ בְּעָלָהּ הֲרֵי זֶה מַאֲמָר פָּסוּל בֵּין הַמַּאֲמָר הָרִאשׁוֹן בֵּין הַמַּאֲמָר הָאַחֲרוֹן:","נִמְצֵאתָ לָמֵד שֶׁהַמַּאֲמָר בֵּין שֶׁקְּדָמוֹ מַאֲמָר אַחֵר אוֹ גֵּט אוֹ חֲלִיצָה אוֹ בְּעִילָה. בֵּין שֶׁקָּדַם הַמַּאֲמָר לְאֶחָד מֵאֵלּוּ. הֲרֵי זֶה מַאֲמָר פָּסוּל. חוּץ מִן הַנּוֹתֵן מַאֲמָר וּבָעַל בְּעִילָה אַחַר הַמַּאֲמָר שֶׁזּוֹ הִיא כְּהִלְכָתָהּ:","הַבְּעִילָה שֶׁבּוֹעֵל הַיָּבָם אֶת יְבִמְתּוֹ תְּחִלָּה אוֹ אַחַר מַאֲמָרוֹ בָּהּ וְלֹא קְדָמָהּ דָּבָר אַחֵר נִקְרֵאת בְּעִילָה כְּשֵׁרָה. וְאִם קְדָמָהּ מַאֲמָר מֵאֶחָיו אוֹ גֵּט בֵּין מִמֶּנּוּ בֵּין מֵאֶחָיו בֵּין בָּהּ בֵּין בְּצָרָתָהּ. אוֹ שֶׁקְּדָמָהּ מַאֲמָר בְּצָרָתָהּ בֵּין מִמֶּנּוּ בֵּין מֵאֶחָיו הֲרֵי זוֹ נִקְרֵאת בְּעִילָה פְּסוּלָה:","הַחֲלִיצָה שֶׁחוֹלֵץ הַיָּבָם לִיבִמְתּוֹ תְּחִלָּה אִם לֹא קְדָמָהּ דָּבָר אַחֵר נִקְרֵאת חֲלִיצָה מְעֻלָּה. וְאִם קְדָמָהּ גֵּט אוֹ מַאֲמָר בֵּין מִיָּבָם זֶה בֵּין מֵאֶחָיו בֵּין בָּהּ בֵּין בְּצָרָתָהּ הֲרֵי זוֹ נִקְרֵאת חֲלִיצָה פְּחוּתָה:","יְבָמוֹת רַבּוֹת הַבָּאוֹת מִבַּיִת אֶחָד כֵּיוָן שֶׁנִּבְעֲלָה אַחַת מֵהֶן בְּעִילָה כְּשֵׁרָה אוֹ נֶחְלְצָה חֲלִיצָה מְעֻלָּה הֻתְּרוּ הַכּל וְנִסְתַּלְּקָה זִקַּת הַיָּבָם מֵעֲלֵיהֶן. וְאִם נִבְעֲלָה אַחַת מֵהֶן בְּעִילָה פְּסוּלָה אוֹ נִתַּן לָהּ מַאֲמָר פָּסוּל נֶאֶסְרוּ כֻּלָּן לְיִבּוּם וּצְרִיכָה גֵּט זוֹ שֶׁנִּבְעֲלָה אוֹ שֶׁנִּתַּן לָהּ מַאֲמָר. וּצְרִיכָה חֲלִיצָה [כָּל] אַחַת מֵהֶן לְהַתִּירָן לְזָר. שֶׁאֵין זִקַּת הַיִּבּוּם מִסְתַּלֶּקֶת בִּבְעִילָה פְּחוּתָה:","נֶחְלְצָה אַחַת מֵהֶן חֲלִיצָה פְּחוּתָה הֻתְּרָה לְהִנָּשֵׂא לְזָר זוֹ שֶׁנֶּחְלְצָה אֲבָל צָרָתָהּ אֲסוּרָה עַד שֶׁתַּחֲלֹץ גַּם הִיא אוֹ עַד שֶׁיַּחְלְצוּ כָּל הָאַחִין לָרִאשׁוֹנָה שֶׁנֶּחְלְצָה הַחֲלִיצָה הַפְּחוּתָה. שֶׁאֵין חֲלִיצָה פְּחוּתָה מְסַלֶּקֶת זִקַּת יִבּוּם מִבַּיִת זֶה עַד שֶׁתַּחֲזֹר עַל כָּל הָאַחִין אוֹ עַד שֶׁתֵּחָלֵץ כָּל אַחַת מֵהֶן:","כָּל יְבָמָה שֶׁנִּבְעֲלָה לִיבָמָהּ בֵּין בְּעִילָה כְּשֵׁרָה בֵּין בְּעִילָה פְּסוּלָה. וַאֲפִלּוּ בְּעָלָהּ אַחַר שֶׁחָלַץ לָהּ בֵּין הוּא בֵּין אֶחָיו בֵּין לְשֵׁם אִישׁוּת בֵּין לְשֵׁם יַבְּמוּת. וַאֲפִלּוּ בָּעַל צָרָתָהּ אַחַר שֶׁבָּעַל בְּעִילָה כְּשֵׁרָה בֵּין הוּא בֵּין אֶחָיו. הֲרֵי זוֹ צְרִיכָה גֵּט שֶׁהֲרֵי נַעֲשֵׂית אֵשֶׁת אִישׁ בַּבְּעִילָה. וְכֵן כָּל יְבָמָה שֶׁנִּתַּן לָהּ מַאֲמָר בֵּין מַאֲמָר כָּשֵׁר בֵּין מַאֲמָר פָּסוּל הֲרֵי זוֹ צְרִיכָה גֵּט מִפְּנֵי הַמַּאֲמָר כְּמוֹ שֶׁבֵּאַרְנוּ וְאַחַר כָּךְ יָסוּר אִסּוּר הַמַּאֲמָר:","כְּבָר אָמַרְנוּ שֶׁאֵין הַגֵּט דּוֹחֶה הַיְבָמָה דְּחִיָּה גְּמוּרָה וְכֵן הַמַּאֲמָר אֵינוֹ קוֹנֶה בָּהּ קִנְיָן גָּמוּר. אֲבָל הַבְּעִילָה קוֹנָה קִנְיָן גָּמוּר. וְהַחֲלִיצָה דּוֹחָה אוֹתָהּ דְּחִיָּה גְּמוּרָה. לְפִיכָךְ גֵּט אַחַר גֵּט בִּיבָמָה אוֹ מַאֲמָר אַחַר מַאֲמָר מוֹעִיל. אֲבָל בְּעִילָה אַחַר בְּעִילָה וַחֲלִיצָה אַחַר חֲלִיצָה אֵין הָאַחֲרוֹנָה מוֹעֶלֶת כְּלוּם. וְכֵן גֵּט אוֹ חֲלִיצָה אַחַר הַבְּעִילָה אֵינָהּ כְּלוּם:","כֵּיצַד. יָבָם שֶׁנָּתַן גֵּט לִיבִמְתּוֹ וְחָזַר וְנָתַן גֵּט לְצָרָתָהּ הֲרֵי זֶה אָסוּר בִּקְרוֹבוֹת שְׁתֵּיהֶן. וְכֵן שְׁנֵי יְבָמִין שֶׁנָּתְנוּ שְׁנֵי גִּטִּין לִיבָמָה אַחַת זֶה אַחַר זֶה הֲרֵי זוֹ כִּגְרוּשָׁה לִשְׁנֵיהֶן וּשְׁנֵיהֶן אֲסוּרִין בִּקְרוֹבוֹתֶיהָ וְאֶחָד מֵהֶן חוֹלֵץ. וְכֵן אִם נָתַן גֵּט לִיבִמְתּוֹ וְחָזַר וְנָתַן אָחִיו גֵּט לְצָרָתָהּ כָּל אֶחָד אָסוּר בִּקְרוֹבוֹת זוֹ שֶׁנָּתַן לָהּ הַגֵּט. וְכֵן אִם נָתְנוּ מַאֲמָר אַחַר מַאֲמָר כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל הַיָּבָם שֶׁחָלַץ לִיבִמְתּוֹ וְחָזַר וְחָלַץ לְצָרָתָהּ בֵּין הוּא בֵּין אָחִיו. וְכֵן שְׁתֵּי יְבָמִין שֶׁחָלְצוּ זֶה אַחַר זֶה לִיבָמָה אַחַת אֵין חֲלִיצָה אַחֲרוֹנָה כְּלוּם וְאֵין הַחוֹלֵץ אוֹתָהּ בָּאַחֲרוֹנָה אָסוּר בִּקְרוֹבוֹתֶיהָ. שֶׁזֶּה כְּחוֹלֵץ לִשְׁאָר הַנָּשִׁים שֶׁאֵין לוֹ עֲלֵיהֶן זִקָּה:","וְכֵן הַבּוֹעֵל יְבִמְתּוֹ וְחָזַר בֵּין הוּא בֵּין אָחִיו וְחָלַץ לָהּ אוֹ לְצָרָתָהּ אֵין חֲלִיצָה זוֹ כְּלוּם. וְכֵן אִם חָזַר אָחִיו וְנָתַן גֵּט לָהּ אוֹ לְצָרָתָהּ אֵינוֹ כְּלוּם. חָזַר אָחִיו וְנָתַן לָהּ מַאֲמָר אוֹ בָּעַל לֹא עָשָׂה כְּלוּם מֵאַחַר שֶׁבָּעַל אָחִיו תְּחִלָּה קָנָה קִנְיָן גָּמוּר וְאֵין הַקִּדּוּשִׁין תּוֹפְסִין בְּאֵשֶׁת אִישׁ. אֲבָל אִם נָתַן מַאֲמָר לְצָרָתָהּ אוֹ בָּעַל צָרָתָהּ צְרִיכָה גֵּט מִמֶּנּוּ כְּמוֹ שֶׁבֵּאַרְנוּ:","שְׁנֵי יְבָמִין שֶׁיִּבְּמוּ שְׁתֵּי יְבָמוֹת הַבָּאוֹת מִבַּיִת אֶחָד וְלֹא נוֹדַע מִי יִבֵּם תְּחִלָּה שְׁנֵיהֶן יוֹצִיאוּ בְּגֵט וְיֻתְּרוּ לְזָרִים וַאֲסוּרוֹת לַיְבָמִין. לְפִיכָךְ רְאוּבֵן שֶׁהָיָה בִּירוּשָׁלַיִם וְלוֹ שְׁתֵּי נָשִׁים אַחַת בְּעַכּוֹ וְאַחַת בְּצוֹר וְשִׁמְעוֹן אָחִיו בְּעַכּוֹ וְלֵוִי אָחִיו בְּצוֹר וְשָׁמְעוּ שֶׁמֵּת רְאוּבֵן הַדִּין נוֹתֵן שֶׁלֹּא יְיַבֵּם אֶחָד מֵהֶן עַד שֶׁיִּוָּדַע מֶה עָשָׂה אָחִיו שֶׁמָּא קָדַם וְיִבֵּם. קָדַם אֶחָד מֵהֶן וְיִבֵּם אֵין מוֹצִיאִין מִיָּדוֹ עַד שֶׁיִּוָּדַע שֶׁאָחִיו יִבֵּם תְּחִלָּה. רָצָה הָאֶחָד לַחֲלֹץ קֹדֶם שֶׁיָּדַע מֶה עָשָׂה אָחִיו אֵין מוֹנְעִין אוֹתוֹ:","יָבָם קָטָן בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד בִּיאָתוֹ כְּמַאֲמָר מִן הַגָּדוֹל שֶׁאֵינוֹ קוֹנֶה קִנְיָן גָּמוּר. וּמַאֲמָר בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד אִם נְתָנוֹ בַּתְּחִלָּה מוֹעִיל וַהֲרֵי הוּא פּוֹסֵל בּוֹ עַל הַגָּדוֹל אֲבָל אִם נְתָנוֹ בַּסּוֹף אֵינוֹ כְּלוּם. וְגִטּוֹ וַחֲלִיצָתוֹ אֵינָם כְּלוּם בֵּין בַּתְּחִלָּה בֵּין בַּסּוֹף:","כֵּיצַד. בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד שֶׁבָּא עַל יְבִמְתּוֹ אוֹ שֶׁנָּתַן לָהּ מַאֲמָר תְּחִלָּה פְּסָלָהּ עַל שְׁאָר אַחִין. אֲבָל אִם עָשָׂה הַגָּדוֹל מַאֲמָר בִּיבִמְתּוֹ וְחָזַר בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד וְנָתַן לָהּ אוֹ לְצָרָתָהּ מַאֲמָר לֹא עָשָׂה כְּלוּם וְלֹא פְּסָלָהּ עַל אָחִיו הַגָּדוֹל. חָזַר בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד וּבָא עָלֶיהָ אוֹ עַל צָרָתָהּ אַחַר מַאֲמַר אָחִיו הַגָּדוֹל פְּסָלָהּ עַל הַגָּדוֹל כִּשְׁנֵי גְּדוֹלִים שֶׁעָשׂוּ מַאֲמָר אַחַר מַאֲמָר כְּמוֹ שֶׁבֵּאַרְנוּ:","בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד שֶׁבָּא עַל יְבִמְתּוֹ וְחָזַר אָחִיו הַגָּדוֹל וּבָא עָלֶיהָ אוֹ חָלַץ אוֹ נָתַן גֵּט לָהּ אוֹ לְצָרָתָהּ הֲרֵי זֶה פְּסָלָהּ עַל הַקָּטָן. וְכֵן אִם חָזַר הַקָּטָן וּבָא עַל צָרָתָהּ אוֹ בָּא אָחִיו הָאַחֵר שֶׁהוּא בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד עָלֶיהָ אוֹ עַל צָרָתָהּ נִפְסְלָה עָלָיו כְּדִין כָּל מַאֲמָר וּמַאֲמָר:","בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד שֶׁבָּא עַל יְבִמְתּוֹ וְהִגְדִּיל וְלֹא בָּא עָלֶיהָ מִשֶּׁהִגְדִּיל צְרִיכָה גֵּט וַחֲלִיצָה. גֵּט מִפְּנֵי בִּיאָתוֹ שֶׁהִיא כְּמַאֲמָר וַחֲלִיצָה לְהַתִּירָהּ לְזָר שֶׁהֲרֵי לֹא נִבְעֲלָה בְּעִילָה שֶׁקּוֹנָה קִנְיָן גָּמוּר. וְאִם בָּא עָלֶיהָ מִשֶּׁהִגְדִּיל הֲרֵי זוֹ צְרִיכָה גֵּט בִּלְבַד:","אֶחָד בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד. וְאֶחָד בֶּן עֶשְׂרִים שָׁנָה שֶׁלֹּא הֵבִיא שְׁתֵּי שְׂעָרוֹת וְלֹא נוֹלְדוּ בּוֹ סִימָנֵי סָרִיס כְּמוֹ שֶׁבֵּאַרְנוּ בִּתְחִלַּת הַסֵּפֶר:","קְטַנָּה שֶׁרְאוּיָה לְמָאֵן. וְהַחֵרֶשֶׁת. אַף עַל פִּי שֶׁקִּדּוּשֵׁי שְׁתֵּיהֶן מִדִּבְרֵי סוֹפְרִים כְּמוֹ שֶׁבֵּאַרְנוּ שְׁנֵי מִינֵי קִדּוּשִׁין הֵן. קְטַנָּה יֵשׁ לָהּ קִדּוּשִׁין כְּדֵי שֶׁלֹּא יִנְהֲגוּ בָּהּ מִנְהַג הֶפְקֵר. וְקִדּוּשֶׁיהָ תְּלוּיִין עַד שֶׁתַּגְדִּיל. וְחֵרֶשֶׁת תִּקְּנוּ לָהּ נִשּׂוּאִין כְּדֵי שֶׁלֹּא תִּשָּׁאֵר פְּנוּיָה לְעוֹלָם. לְפִיכָךְ אִם הָיוּ כָּל הַיְבָמוֹת הַבָּאוֹת מִבַּיִת אֶחָד קְטַנּוֹת אוֹ חֵרְשׁוֹת בִּיאָתָהּ שֶׁל אַחַת מֵהֶן פּוֹטֶרֶת אֶת כֻּלָּן:","הָיְתָה אַחַת חֵרֶשֶׁת וְאַחַת קְטַנָּה אֵין בִּיאַת אַחַת מֵהֶן פּוֹטֶרֶת אֶת צָרָתָהּ. וְכֵיצַד תַּקָּנָתָן. מְלַמְּדִין הַקְּטַנָּה שֶׁתְּמָאֵן וְכוֹנֵס אֶת הַחֵרֶשֶׁת. וְאִם רָצָה לְגָרְשָׁהּ כּוֹתֵב לָהּ גֵּט אַחַר שֶׁיָּבוֹא עָלֶיהָ וְתֻתַּר לְזָר:","הָיְתָה אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת בִּיאַת הַפִּקַּחַת אוֹ חֲלִיצָתָהּ פּוֹטֶרֶת הַחֵרֶשֶׁת. וְאֵין בִּיאַת הַחֵרֶשֶׁת פּוֹטֶרֶת הַפִּקַּחַת שֶׁאֵין קִדּוּשֶׁיהָ אֶלָּא מִדִּבְרֵיהֶן. וְכֵן גְּדוֹלָה וּקְטַנָּה בִּיאַת הַגְּדוֹלָה אוֹ חֲלִיצָתָהּ פּוֹטֶרֶת הַקְּטַנָּה וְאֵין בִּיאַת הַקְּטַנָּה פּוֹטֶרֶת אֶת הַגְּדוֹלָה:","הָיוּ שְׁתֵּיהֶן קְטַנּוֹת הָרְאוּיוֹת לְמָאֵן וּבָא הַיָּבָם עַל אַחַת מֵהֶן וְחָזַר וּבָא אוֹ הוּא אוֹ אָחִיו עַל הַשְּׁנִיָּה לֹא פָּסַל אֶת הָרִאשׁוֹנָה. אֲבָל מְלַמְּדִין אֶת הַשְּׁנִיָּה שֶׁתְּמָאֵן וִיקַיֵּם זֶה יְבִמְתּוֹ הַקְּטַנָּה שֶׁנִּבְעֲלָה תְּחִלָּה:","וְכֵן הַדִּין בִּקְטַנָּה וְחֵרֶשֶׁת שֶׁבָּא הַיָּבָם תְּחִלָּה עַל הַקְּטַנָּה וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַחֵרֶשֶׁת לֹא פָּסַל אֶת הַקְּטַנָּה וְהַחֵרֶשֶׁת צְרִיכָה גֵּט. שֶׁבִּיאַת הַקְּטַנָּה מְעֻלָּה מִבִּיאַת הַחֵרֶשֶׁת. שֶׁהַקְּטַנָּה רְאוּיָה לְאַחַר זְמַן. לְפִיכָךְ יְקַיֵּם הַקְּטַנָּה שֶׁנִּבְעֲלָה תְּחִלָּה:","בָּא הַיָּבָם תְּחִלָּה עַל הַחֵרֶשֶׁת וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַקְּטַנָּה פָּסַל אֶת הַחֵרֶשֶׁת. וּמְלַמְּדִין הַקְּטַנָּה שֶׁתְּמָאֵן וְהַחֵרֶשֶׁת יוֹצְאָה בְּגֵט:","הָיוּ אַחַת פִּקַּחַת וְאַחַת חֵרֶשֶׁת. בָּא הַיָּבָם עַל הַפִּקַּחַת וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַחֵרֶשֶׁת לֹא פָּסַל אֶת הַפִּקַּחַת וְהַחֵרֶשֶׁת צְרִיכָה גֵּט. בָּא הַיָּבָם עַל הַחֵרֶשֶׁת וְחָזַר הוּא אוֹ אָחִיו וּבָא עַל הַפִּקַּחַת פָּסַל אֶת הַחֵרֶשֶׁת. וְהַחֵרֶשֶׁת יוֹצְאָה בְּגֵט. וְהַפִּקַּחַת בְּגֵט וּבַחֲלִיצָה:","הָיוּ גְּדוֹלָה וּקְטַנָּה וּבָא עַל הַגְּדוֹלָה וְחָזַר הוּא אוֹ אָחִיו וּבָא עַל הַקְּטַנָּה לֹא פָּסַל הַגְּדוֹלָה וּמְלַמְּדִין אֶת הַקְּטַנָּה שֶׁתְּמָאֵן. בָּא עַל הַקְּטַנָּה וְחָזַר וּבָא הוּא אוֹ אָחִיו עַל הַגְּדוֹלָה. מְלַמְּדִין אֶת הַקְּטַנָּה שֶׁתְּמָאֵן וִיקַיֵּם הַגְּדוֹלָה שֶׁבְּעִילָתָהּ קוֹנָה קִנְיָן גָּמוּר:"],"Mishneh Torah, Marriage 17":["מִי שֶׁהָיָה נָשׂוּי נָשִׁים רַבּוֹת וּמֵת. כָּל שֶׁנִּשֵּׂאת בַּתְּחִלָּה קוֹדֶמֶת לִטּל כְּתֻבָּתָהּ. וְאֵין אַחַת מֵהֶן נוֹטֶלֶת אֶלָּא בִּשְׁבוּעָה. וְאֵין לָאַחֲרוֹנָה אֶלָּא מַה שֶּׁשִּׁיְּרָה שֶׁלְּפָנֶיהָ וְגַם הִיא נִשְׁבַּעַת וְנוֹטֶלֶת הַשְּׁאָר. וְכֵן אִם הָיָה עָלָיו שְׁטַר חוֹב. אִם הָיָה הַחוֹב קוֹדֵם גּוֹבֶה בַּעַל חוֹב תְּחִלָּה. וְאִם הַכְּתֻבָּה קָדְמָה גּוֹבָה הָאִשָּׁה בַּתְּחִלָּה וְהַנִּשְׁאָר לַבַּעַל חוֹב:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיְתָה הַקַּרְקַע שֶׁבָּאוּ לִגְבּוֹת מִמֶּנָּה קְנוּיָה לוֹ בִּשְׁעַת נִשּׂוּאִים וּבְשָׁעָה שֶׁלָּוָה הוּא. שֶׁהַדִּין נוֹתֵן שֶׁכָּל הַקּוֹדֵם בִּשְׁטָר תְּחִלָּה זָכָה תְּחִלָּה. אֲבָל אִם נָשָׂא נָשִׁים זוֹ אַחַר זוֹ וְלָוָה בֵּין קֹדֶם נִשּׂוּאִין בֵּין אַחַר נִשּׂוּאִין וְאַחַר שֶׁנָּשָׂא וְלָוָה קָנָה קַרְקַע כֻּלָּן חוֹלְקִין כְּאֶחָד שֶׁשִּׁעְבּוּד כֻּלָּן כְּאֶחָד בָּא. שֶׁבְּשָׁעָה שֶׁקָּנָה הָיָה מְשֻׁעְבָּד לַכּל וְאֵין כָּאן דִּין קְדִימָה:","וְכֵן אִם הָיָה זְמַן הַכְּתֻבּוֹת וְהַשְּׁטָרוֹת כֻּלָּן יוֹם אֶחָד אוֹ שָׁעָה אַחַת בְּמָקוֹם שֶׁכּוֹתְבִים שָׁעוֹת חוֹלְקִין כְּאֶחָד שֶׁאֵין שָׁם קוֹדֵם. וּלְעוֹלָם כָּל שֶׁקָּדַם וְזָכָה בְּמִטַּלְטְלִין כְּדֵי חוֹבוֹ אוֹ כְּדֵי כְּתֻבָּתָהּ אֵין מוֹצִיאִין מִיָּדוֹ שֶׁאֵין דִּין קְדִימָה בְּמִטַּלְטְלִין:","מִי שֶׁגֵּרֵשׁ אֶת אִשְׁתּוֹ וְעָלָיו שְׁטַר חוֹב וּבָא בַּעַל חוֹב וְהָאִשָּׁה לִגְבּוֹת וְהָיוּ לוֹ מָעוֹת וְקַרְקַע כְּדֵי הַחוֹב וְהַכְּתֻבָּה. בַּעַל חוֹב נוֹטֵל מָעוֹת וְהָאִשָּׁה נוֹטֶלֶת כְּתֻבָּתָהּ מִן הַקַּרְקַע. וְאִם אֵין לוֹ אֶלָּא קַרְקַע שֶׁאֵין בָּהּ כְּדֵי לִגְבּוֹת שְׁנֵיהֶם וְלֹא הָיָה בָּהּ דִּין קְדִימָה נוֹתְנִין אוֹתוֹ לְבַעַל חוֹב. וְאִם נִשְׁאַר לָאִשָּׁה כְּלוּם תִּטּל וְאִם לָאו תִּדָּחֶה מִפְּנֵי בַּעַל חוֹב. שֶׁהֲרֵי בַּעַל חוֹב הִפְסִיד וְהוֹצִיא מְעוֹתָיו וְהָאִשָּׁה לֹא חָסְרָה דָּבָר שֶׁיּוֹתֵר מִשֶּׁהָאִישׁ רוֹצֶה לִשָּׂא אִשָּׁה רוֹצֶה לְהִנָּשֵׂא:","וְכֵן מִי שֶׁמֵּת וְהִנִּיחַ אִשָּׁה וּבַעַל חוֹב וְקַרְקַע שֶׁאֵין בָּהּ דִּין קְדִימָה הָאִשָּׁה נִדְחֵית מִפְּנֵי בַּעַל חוֹב וְהוּא גּוֹבֶה חוֹבוֹ תְּחִלָּה:","וְכֵיוָן שֶׁתִּקְּנוּ הַגְּאוֹנִים שֶׁתִּגְבֶּה הָאִשָּׁה וּבַעַל חוֹב מִן הַמִּטַּלְטְלִין וְהַדָּבָר יָדוּעַ שֶׁאֵין דִּין קְדִימָה בְּמִטַּלְטְלִין אִם לֹא הִנִּיחַ מִטַּלְטְלִין כְּדֵי לִתֵּן לִשְׁנֵיהֶם נוֹתְנִין לְבַעַל חוֹב כָּל חוֹבוֹ תְּחִלָּה. וְאִם נִשְׁאַר לָאִשָּׁה מַה שֶּׁתִּטּל בִּכְתֻבָּתָהּ תִּטּל וְאִם לָאו תִּדָּחֶה:","הָיוּ כְּתוּבִין בִּכְתֻבָּתָהּ נִכְסֵי צֹאן בַּרְזֶל וְטָעֲנָה שֶׁאָבְדוּ אוֹ שֶׁלְּקָחָם הַבַּעַל הֲרֵי הִיא בְּנִכְסֵי צֹאן בַּרְזֶל שֶׁלָּהּ כִּשְׁאָר בַּעֲלֵי חוֹבוֹת וְנִשְׁבַּעַת שֶׁלֹּא לָקְחָה אוֹתָן וְלֹא נָתְנָה וְלֹא מָחֲלָה וְחוֹלֶקֶת עִם בַּעֲלֵי חוֹבוֹת:","מִי שֶׁמֵּת אוֹ גֵּרֵשׁ וְיֵשׁ לוֹ נָשִׁים רַבּוֹת וְאֵין שָׁם דִּין קְדִימָה וְאֵין לוֹ כְּדֵי כָּל הַכְּתֻבּוֹת כֵּיצַד הֵן חוֹלְקוֹת. רוֹאִים אִם כְּשֶׁיֵחָלֵק הַמָּמוֹן עַל מִנְיַן הַנָּשִׁים יְגִיעַ לַפְּחוּתָה שֶׁבָּהֶן כְּדֵי כְּתֻבָּתָהּ אוֹ פָּחוֹת חוֹלְקוֹת בְּשָׁוֶה. וְאִם הָיָה הַמָּמוֹן יוֹתֵר עַל זֶה חוֹלְקִים מִמֶּנּוּ כְּדֵי שֶׁיַּגִּיעַ לַפְּחוּתָה שֶׁבָּהֶן כַּשִּׁעוּר כְּתֻבָּתָהּ. וְחוֹזְרוֹת וְחוֹלְקוֹת אֶת הַמּוֹתָר בֵּין הַנּוֹתָרוֹת עַל דֶּרֶךְ הָרִאשׁוֹן. כֵּיצַד. מִי שֶׁהָיָה נָשׂוּי אַרְבַּע נָשִׁים כְּתֻבָּתָהּ שֶׁל רִאשׁוֹנָה אַרְבַּע מֵאוֹת וְשֶׁל שְׁנִיָּה שְׁלֹשׁ מֵאוֹת וְשֶׁל שְׁלִישִׁית מָאתַיִם וְשֶׁל רְבִיעִית מֵאָה נִמְצָא הַכּל אֶלֶף וְגֵרֵשׁ כֻּלָּן אוֹ מֵת. אִם הִנִּיחַ אַרְבַּע מֵאוֹת אוֹ פָּחוֹת חוֹלְקוֹת בְּשָׁוֶה וְכָל אַחַת נוֹטֶלֶת מֵאָה אוֹ פָּחוֹת. הִנִּיחַ שְׁמוֹנֶה מֵאוֹת אִם תֵּחָלֵק בֵּין כֻּלָּן בְּשָׁוֶה נִמְצֵאת הָרְבִיעִית נוֹטֶלֶת מָאתַיִם וַהֲרֵי אֵין בִּכְתֻבָּתָהּ אֶלָּא מֵאָה אֶלָּא כֵּיצַד עוֹשִׂין. לוֹקְחִין אַרְבַּע מֵאוֹת זוּז וְחוֹלְקִין אוֹתָן בֵּינֵיהֶן בְּשָׁוֶה מֵאָה מֵאָה נִמְצֵאת הָרְבִיעִית נָטְלָה כְּדֵי כְּתֻבָּתָהּ וְהָלְכָה לָהּ נִשְׁאַר כָּאן אַרְבַּע מֵאוֹת זוּז וְשָׁלֹשׁ נָשִׁים שֶׁבְּיַד כָּל אַחַת מִשְּׁלָשְׁתָּן מֵאָה זוּז אִם תַּחֲלֹק הָאַרְבַּע מֵאוֹת בֵּין שְׁלָשְׁתָּן בְּשָׁוֶה נִמְצָא הַשְּׁלִישִׁית נוֹטֶלֶת מָאתַיִם וּשְׁלֹשִׁים וְשָׁלֹשׁ וּשְׁלִישׁ וַהֲרֵי אֵין בִּכְתֻבָּתָהּ אֶלָּא מָאתַיִם. לְפִיכָךְ לוֹקְחִין מֵאַרְבַּע הַמֵּאוֹת שְׁלֹשׁ מֵאוֹת וְחוֹלְקִין בֵּין שְׁלָשְׁתָּן בְּשָׁוֶה שֶׁנִּמְצֵאת הַשְּׁלִישִׁית שֶׁנָּטְלָה מָאתַיִם שֶׁלָּהּ וְהָלְכָה לָהּ נִשְׁאַר כָּאן מֵאָה וּשְׁתֵּי נָשִׁים חוֹלְקִין אֶת הַמֵּאָה בְּשָׁוֶה בֵּין רִאשׁוֹנָה וּשְׁנִיָּה. נִמְצָא בְּיַד הָרִאשׁוֹנָה מָאתַיִם וַחֲמִשִּׁים וְכֵן בְּיַד הַשְּׁנִיָּה. וְנִמְצָא בְּיַד הַשְּׁלִישִׁית מָאתַיִם וּבְיַד הָרְבִיעִית מֵאָה וְעַל דֶּרֶךְ זוֹ חוֹלְקוֹת לְעוֹלָם אֲפִלּוּ הֵן מֵאָה:","הֶעָרֵב לְאִשָּׁה בִּכְתֻבָּתָהּ אַף עַל פִּי שֶׁקָּנוּ מִיָּדוֹ אֵינוֹ חַיָּב לְשַׁלֵּם שֶׁמִּצְוָה עָשָׂה וַהֲרֵי לֹא חָסְרָה כְּלוּם. וְאִם עָרֵב שֶׁל כְּתֻבַּת בְּנוֹ הוּא וְקָנוּ מִיָּדוֹ חַיָּב לְשַׁלֵּם שֶׁהָאָב בִּגְלַל בְּנוֹ מְשַׁעְבֵּד עַצְמוֹ וְגוֹמֵר וּמַקְנֶה. וְקַבְּלָן שֶׁל כְּתֻבָּה חַיָּב לְשַׁלֵּם אַף עַל פִּי שֶׁלֹּא קָנוּ מִיָּדוֹ. וְאֵי זֶה הוּא קַבְּלָן זֶה שֶׁאָמַר לְאִשָּׁה הִנָּשְׂאִי לְזֶה וַאֲנִי נוֹתֵן כְּתֻבָּה זוֹ. אֲבָל אִם אָמַר לָהּ הֲרֵינִי עָרֵב כְּתֻבָּה זוֹ. אֲנִי פּוֹרֵעַ כְּתֻבָּה זוֹ. אֲנִי חַיָּב בָּהּ וְכַיּוֹצֵא בָּזֶה פָּטוּר אֶלָּא אִם כֵּן הָיָה אָבִיו. הַמְגָרֵשׁ אֶת אִשְׁתּוֹ יַדִּירֶנָּה הֲנָאָה וְאַחַר כָּךְ תִּפָּרַע כְּתֻבָּתָהּ מִן הַקַּבְּלָן אוֹ מֵאָבִיו אִם הָיָה עָרֵב. שֶׁמָּא יַחֲזִירֶנָהּ וְנִמְצְאוּ עוֹשִׂין קְנוּנְיָא עַל נְכָסָיו שֶׁל זֶה:","וְכֵן הַמַּקְדִּישׁ נְכָסָיו וְגֵרֵשׁ אֶת אִשְׁתּוֹ יַדִּירֶנָּה הֲנָאָה וְאַחַר כָּךְ תִּפָּרַע מִן הַפּוֹדֶה מִיַּד הַהֶקְדֵּשׁ שֶׁמָּא יַעֲשׂוּ קְנוּנְיָא עַל הַהֶקְדֵּשׁ. אֲבָל הַמְגָרֵשׁ אֶת אִשְׁתּוֹ וּבָאָה לִטְרֹף מִן הַלָּקוֹחוֹת אֵין מְחַיְּבִין אוֹתוֹ לְהַדִּירָהּ אֶלָּא נִשְׁבַּעַת וְטוֹרֶפֶת. וְאִם רָצְתָה תַּחֲזֹר לְבַעְלָהּ שֶׁכְּבָר יָדְעוּ הַלָּקוֹחוֹת שֶׁיֵּשׁ עָלָיו כְּתֻבַּת אִשָּׁה וְהֵם הִפְסִידוּ עַל עַצְמָם שֶׁלָּקְחוּ נְכָסִים שֶׁתַּחַת שִׁעְבּוּדָהּ:","הַבַּעַל שֶׁמָּכַר נְכָסָיו וְאַחַר כָּךְ כָּתְבָה אִשְׁתּוֹ לַלּוֹקֵחַ דִּין וּדְבָרִים אֵין לִי עִמְּךָ וְהִסְכִּימָה לְמַעֲשָׂיו אַף עַל פִּי שֶׁקָּנוּ מִמֶּנָּה הֲרֵי זוֹ טוֹרֶפֶת. שֶׁלֹּא כָּתְבָה לוֹ אֶלָּא שֶׁלֹּא תִּהְיֶה בֵּינָהּ לְבֵין בַּעְלָהּ קְטָטָה וְיֵשׁ לָהּ לוֹמַר נַחַת רוּחַ עָשִׂיתִי לְבַעְלִי. אֲבָל אִם קָנוּ מִיַּד הָאִשָּׁה תְּחִלָּה שֶׁאֵין לָהּ שִׁעְבּוּד עַל מָקוֹם זֶה וְאַחַר כָּךְ מָכַר אוֹתוֹ הַבַּעַל אֵינָהּ טוֹרֶפֶת אוֹתוֹ. וְכֵן אִם מָכַר הַבַּעַל וְאָמַר לְאִשְׁתּוֹ לִכְתֹּב לַלּוֹקֵחַ דִּין וּדְבָרִים אֵין לִי עִמְּךָ וְלֹא כָּתְבָה וְלֹא הִסְכִּימָה לְמַעֲשָׂיו וְנִפְסַד הַמֶּכֶר וְחָזַר הַבַּעַל וּמָכַר לְאִישׁ אַחֵר בֵּין אוֹתָהּ שָׂדֶה בֵּין שָׂדֶה אַחֶרֶת וְאַחַר שֶׁמָּכַר הַבַּעַל הִסְכִּימָה לְמַעֲשָׂיו וְקָנוּ מִיָּדָהּ, שֶׁאֵין לָהּ שִׁעְבּוּד עַל שָׂדֶה זוֹ, אֵינָהּ יְכוֹלָה לִטְרֹף שֶׁאֵינָהּ יְכוֹלָה לוֹמַר נַחַת רוּחַ עָשִׂיתִי לְבַעְלִי שֶׁהֲרֵי בָּרִאשׁוֹנָה כְּשֶׁלֹּא רָצְתָה לֹא הָלְכָה בִּרְצוֹן בַּעְלָהּ:","מִי שֶׁהָיוּ לוֹ שְׁתֵּי נָשִׁים וּמָכַר אֶת שָׂדֵהוּ וְקָנוּ מִיַּד הָרִאשׁוֹנָה שֶׁאֵין לָהּ שִׁעְבּוּד עַל שָׂדֶה זוֹ וְאֵינָהּ טוֹרֶפֶת אוֹתוֹ מִן הַלּוֹקֵחַ וְהָיָה הַקִּנְיָן מוֹעִיל שֶׁאֵינָהּ יְכוֹלָה לִטְעֹן בּוֹ נַחַת רוּחַ עָשִׂיתִי לְבַעְלִי וְאַחַר כָּךְ מֵת הַבַּעַל אוֹ גֵּרֵשׁ שְׁתֵּיהֶן הַשְּׁנִיָּה מוֹצִיאָה מִיַּד הַלּוֹקֵחַ שֶׁהֲרֵי לֹא קָנוּ מִיָּדָהּ לַלּוֹקֵחַ. וְהָרִאשׁוֹנָה מוֹצִיאָה מִיַּד הַשְּׁנִיָּה מִפְּנֵי שֶׁהִיא קָדְמָה וְלֹא הֵסִירָה שִׁעְבּוּדָהּ אֶלָּא מֵעַל הַלּוֹקֵחַ. וּכְשֶׁתַּחְזֹר הַשָּׂדֶה לָרִאשׁוֹנָה חוֹזֵר הַלּוֹקֵחַ וּמוֹצִיאָהּ מִיָּדָהּ שֶׁהֲרֵי קָנוּ לוֹ. וְחוֹזְרוֹת חֲלִילָה עַד שֶׁיַּעֲשׂוּ פְּשָׁרָה בֵּינֵיהֶן:","אַלְמָנָה בֵּין מִן הַנִּשּׂוּאִין בֵּין מִן הָאֵרוּסִין נִשְׁבַּעַת וּמוֹכֶרֶת מִקַּרְקַע בַּעְלָהּ וְנִפְרַעַת כְּתֻבָּתָהּ בֵּין בְּבֵית דִּין מֻמְחִין בֵּין בְּבֵית דִּין שֶׁאֵינָן מֻמְחִין. וְהוּא שֶׁיִּהְיוּ הַשְּׁלֹשָׁה הָאֲנָשִׁים נֶאֱמָנִין וְיוֹדְעִין בְּשׁוּמַת הַקַּרְקַע. וְאַחֲרָיוּת הַמֶּכֶר עַל נִכְסֵי יְתוֹמִים. אֲבָל הַגְּרוּשָׁה לֹא תִּמְכֹּר אֶלָּא בְּבֵית דִּין מֻמְחִין. וְכָל הַמּוֹכֶרֶת בְּבֵית דִּין לֹא תִּמְכֹּר אֶלָּא בְּהַכְרָזָה. וּבְהִלְכוֹת הַלְוָאָה יִתְבָּאֵר מִשְׁפַּט מְכִירַת בֵּית דִּין הֵיאַךְ הִיא. אֲבָל הַמּוֹכֶרֶת שֶׁלֹּא בְּבֵית דִּין אֵינָהּ צְרִיכָה הַכְרָזָה וְאַף עַל פִּי כֵן צָרִיךְ שְׁלֹשָׁה שֶׁהֵם נֶאֱמָנִים וְיוֹדְעִים בְּשׁוּמָא:","אַלְמָנָה שֶׁמָּכְרָה קַרְקַע בִּכְתֻבָּתָהּ בֵּינָהּ לְבֵין עַצְמָהּ אִם מָכְרָה שָׁוֶה בְּשָׁוֶה מִכְרָהּ קַיָּם וְנִשְׁבַּעַת שְׁבוּעַת אַלְמָנָה אַחַר שֶׁמָּכְרָה. וְהוּא שֶׁמָּכְרָה לְאַחֵר אֲבָל אִם שָׁמָה לְעַצְמָהּ לֹא עָשְׂתָה כְּלוּם וַאֲפִלּוּ הִכְרִיזָה:","הָיְתָה כְּתֻבָּתָהּ מָאתַיִם וּמָכְרָה שְׁוֵה מֵאָה בְּמָאתַיִם אוֹ שְׁוֵה מָאתַיִם בְּמֵאָה נִתְקַבְּלָה כְּתֻבָּתָהּ וְאֵין לָהּ כְּלוּם וּבִלְבַד שֶׁתִּשָּׁבַע שְׁבוּעַת אַלְמָנָה. הָיְתָה כְּתֻבָּתָהּ מֵאָה וּמָכְרָה שְׁוֵה מֵאָה וְדִינָר בְּמֵאָה מִכְרָהּ בָּטֵל וַאֲפִלּוּ אָמְרָה אֲנִי אַחֲזִיר אֶת הַדִּינָר לַיּוֹרְשִׁים:","הָיְתָה כְּתֻבָּתָהּ אַרְבַּע מֵאוֹת זוּז וּמָכְרָה לָזֶה בְּמָנֶה וְלָזֶה בְּמָנֶה שָׁוֶה בְּשָׁוֶה וְלָאַחֲרוֹן שְׁוֵה מֵאָה וְדִינָר בְּמֵאָה שֶׁל אַחֲרוֹן בָּטֵל וְשֶׁל כֻּלָּם קַיָּם:","יֵשׁ לָאִשָּׁה לִמְכֹּר כְּתֻבָּתָהּ אוֹ לִתְּנָהּ בְּמַתָּנָה אִם מֵת הַבַּעַל אוֹ גֵּרְשָׁהּ יָבֹא הַלָּה וְיִטּל וְאִם מֵתָה הִיא בְּחַיֵּי בַּעְלָהּ אוֹ קֹדֶם שֶׁנִּשְׁבְּעָה אֵין לוֹ כְּלוּם:","הֲרֵי שֶׁמָּכְרָה מִקְצָת כְּתֻבָּתָהּ אוֹ מִשְׁכְּנָה מִקְצָת כְּתֻבָּתָהּ אוֹ נָתְנָה לְאַחֵר מִקְצָת כְּתֻבָּתָהּ מוֹכֶרֶת מִקַּרְקַע בַּעְלָהּ וְתִגְבֶּה הַשְּׁאָר בֵּין בְּבֵית דִּין מֻמְחִין בֵּין בִּשְׁלֹשָׁה נֶאֱמָנִים. וּמוֹכֶרֶת לִכְתֻבָּתָהּ אֲפִלּוּ פְּעָמִים רַבּוֹת בֵּין בְּבֵית דִּין בֵּין בִּשְׁלֹשָׁה נֶאֱמָנִים וְיוֹדְעִים שׁוּמַת הַקַּרְקַע:","הַמּוֹכֶרֶת כְּתֻבָּתָהּ בֵּין לַאֲחֵרִים בֵּין לְבַעְלָהּ לֹא אִבְּדָה שְׁאָר תְּנָאֵי כְּתֻבָּה. וְאִם הָיָה לָהּ בֵּן זָכָר יוֹרֵשׁ כְּנֶגֶד הַכְּתֻבָּה הַזֹּאת שֶׁנִּמְכְּרָה מִנִּכְסֵי אָבִיו יוֹתֵר עַל חֶלְקוֹ כְּדִין תְּנַאי זֶה. אֲבָל הַמּוֹחֶלֶת כְּתֻבָּתָהּ לְבַעְלָהּ אִבְּדָה כָּל תְּנָאֵי כְּתֻבָּתָהּ וַאֲפִלּוּ מְזוֹנוֹת אֵין לָהּ עָלָיו. וּמוֹחֶלֶת כְּתֻבָּתָהּ אֵינָהּ צְרִיכָה קִנְיָן וְלֹא עֵדִים כִּשְׁאָר כָּל הַמּוֹחֲלִים שֶׁאֵינָן צְרִיכִין לֹא עֵדִים וְלֹא קִנְיָן אֶלָּא בִּדְבָרִים בִּלְבַד. וְהוּא שֶׁיִּהְיוּ דְּבָרִים שֶׁהַדַּעַת סוֹמֶכֶת עֲלֵיהֶן וְלֹא יִהְיוּ דִּבְרֵי שְׂחוֹק וְהִתּוּל אוֹ דִּבְרֵי תֵּימָהּ אֶלָּא בְּדַעַת נְכוֹנָה:"],"Mishneh Torah, Marriage 5":["הַמְקַדֵשׁ בְּדָבָר שֶׁהוּא אָסוּר בַּהֲנָאָה כְּגוֹן חָמֵץ בְּפֶסַח אוֹ בָּשָׂר בְּחָלָב וְכַיּוֹצֵא בָּהֶן מִשְּׁאָר אִסּוּרֵי הֲנָאָה אֵינָהּ מְקֻדֶּשֶׁת. וַאֲפִלּוּ הָיָה אָסוּר בַּהֲנָאָה מִדִּבְרֵיהֶם כְּגוֹן חָמֵץ בְּשָׁעָה שִׁשִּׁית מִיּוֹם אַרְבָּעָה עָשָׂר אֵינָהּ מְקֻדֶּשֶׁת:","עָבַר וּמָכַר דָּבָר הָאָסוּר בַּהֲנָאָה וְקִדֵּשׁ בְּדָמָיו הֲרֵי זוֹ מְקֻדֶּשֶׁת חוּץ מֵעַכּוּ\"ם שֶׁאִם קִדֵּשׁ בְּדָמֶיהָ אֵינָהּ מְקֻדֶּשֶׁת מִפְּנֵי שֶׁדְּמֵי עַכּוּ\"ם אֲסוּרִין בַּהֲנָאָה כָּמוֹהָ. הַמְקַדֵּשׁ בְּפֶרֶשׁ עֶגְלֵי עַכּוּ\"ם אֵינָהּ מְקֻדֶּשֶׁת שֶׁהַכּל מֵעַכּוּ\"ם אָסוּר בַּהֲנָאָה שֶׁנֶּאֱמַר (דברים יג יח) \"וְלֹא יִדְבַּק בְּיָדְךָ מְאוּמָה מִן הַחֵרֶם\". אֲבָל הַמְקַדֵּשׁ בְּפֶרֶשׁ שׁוֹר הַנִּסְקָל הֲרֵי זוֹ מְקֻדֶּשֶׁת אַף עַל פִּי שֶׁשּׁוֹר הַנִּסְקָל אָסוּר בַּהֲנָאָה פִּרְשׁוֹ אֵינוֹ אָסוּר בַּהֲנָאָה שֶׁאֵינוֹ דָּבָר חָשׁוּב לְגַבֵּי הַשּׁוֹר:","הַמְקַדֵּשׁ בְּפֵרוֹת שְׁבִיעִית אוֹ בְּאֵפֶר פָּרָה אֲדֻמָּה אוֹ בְּמַיִם שֶׁמִּלְּאָן לַעֲשׂוֹתָן מֵי נִדָּה הֲרֵי זוֹ מְקֻדֶּשֶׁת. הַמְקַדֵּשׁ בְּהֶקְדֵּשׁ שֶׁל בֶּדֶק הַבַּיִת בְּשׁוֹגֵג הֲרֵי זוֹ מְקֻדֶּשֶׁת. וְהוּא יְשַׁלֵּם קֶרֶן וְחֹמֶשׁ לְהֶקְדֵּשׁ וְיָבִיא אֲשָׁמוֹ כְּדִין כָּל מוֹעֵל בִּשְׁגָגָה. וְאִם קִדֵּשׁ בּוֹ אִשָּׁה בְּמֵזִיד אֵינָהּ מְקֻדֶּשֶׁת:","קִדְּשָׁהּ בְּמַעֲשֵׂר שֵׁנִי בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד אֵינָהּ מְקֻדֶּשֶׁת. לְפִי שֶׁאֵין לוֹ לַעֲשׂוֹת בּוֹ שְׁאָר חֲפָצָיו עַד שֶׁיִּתְחַלֵּל שֶׁנֶּאֱמַר בְּמַעֲשֵׂר (ויקרא כז ל) \"לַה' הוּא\":","כֹּהֵן שֶׁקִּדֵּשׁ בְּחֶלְקוֹ מִקָּדְשֵׁי קָדָשִׁים אוֹ מִקָּדָשִׁים קַלִּים אֵינָהּ מְקֻדֶּשֶׁת מִפְּנֵי שֶׁלֹּא הֻתְּרוּ אֶלָּא לַאֲכִילָה בִּלְבַד. אֲבָל כֹּהֵן שֶׁקִּדֵּשׁ בִּתְרוּמָה גְּדוֹלָה וּבִתְרוּמַת מַעֲשֵׂר וּבְבִכּוּרִים וְכֵן לֵוִי שֶׁקִּדֵּשׁ בְּמַעֲשֵׂר רִאשׁוֹן וְיִשְׂרָאֵל שֶׁקִּדֵּשׁ בְּמַעֲשַׂר עָנִי הֲרֵי זוֹ מְקֻדֶּשֶׁת:","מַתָּנוֹת שֶׁלֹּא הוּרְמוּ הֲרֵי הֵם כְּמוֹ שֶׁהוּרְמוּ. לְפִיכָךְ יִשְׂרָאֵל שֶׁנָּפְלוּ לוֹ טְבָלִים מִבֵּית אֲבִי אִמּוֹ כֹּהֵן וְהִפְרִישׁ מֵהֶן תְּרוּמָה וּמַעַשְׂרוֹת הֲרֵי הֵן כִּתְרוּמוֹת וּמַעַשְׂרוֹת שֶׁנָּפְלוּ לוֹ בִּירֻשָּׁה מֵאֲבִי אִמּוֹ. וְאִם קִדֵּשׁ בָּהֶן אִשָּׁה הֲרֵי זוֹ מְקֻדֶּשֶׁת. שֶׁאַף עַל פִּי שֶׁאֵינָן רְאוּיִין לוֹ לַאֲכִילָה יֵשׁ לוֹ לְמָכְרָן לְמִי שֶׁהֵן רְאוּיִין לוֹ. אֲבָל יִשְׂרָאֵל שֶׁקִּדֵּשׁ בִּתְרוּמָה שֶׁהִפְרִישׁ מִגָּרְנוֹ אֵינָהּ מְקֻדֶּשֶׁת שֶׁהֲרֵי אֵין לוֹ לְמָכְרָהּ וְאֵין לוֹ בָּהּ אֶלָּא טוֹבַת הֲנָאָה. לְפִי שֶׁנּוֹתְנָהּ לְכָל כֹּהֵן שֶׁיִּרְצֶה וְטוֹבַת הֲנָאָה אֵינָהּ מָמוֹן:","הַמְקַדֵּשׁ אֶת הָאִשָּׁה בְּגֵזֶל אוֹ בִּגְנֵבָה אוֹ בְּחָמָס. אִם נִתְיָאֲשׁוּ הַבְּעָלִים וְנוֹדַע שֶׁקָּנָה אוֹתוֹ דָּבָר בְּיֵאוּשׁ הֲרֵי זוֹ מְקֻדֶּשֶׁת וְאִם לָאו אֵינָהּ מְקֻדֶּשֶׁת:","הַנִּכְנָס לְבֵית חֲבֵרוֹ וְלָקַח לוֹ כְּלִי אוֹ אֹכֶל וְכַיּוֹצֵא בָּהֶן וְקִדֵּשׁ בּוֹ אִשָּׁה וּבָא בַּעַל הַבַּיִת אַף עַל פִּי שֶׁאָמַר לוֹ לָמָּה לֹא נָתַתָּ לָהּ דָּבָר זֶה שֶׁהוּא טוֹב מִמַּה שֶּׁנָּתַתָּ לָהּ אֵינָהּ מְקֻדֶּשֶׁת. שֶׁלֹּא אָמַר לוֹ דָּבָר זֶה אֶלָּא כְּדֵי שֶׁלֹּא לְהִתְבַּיֵּשׁ עִמּוֹ. וְהוֹאִיל וְקִדֵּשׁ בְּמָמוֹן חֲבֵרוֹ שֶׁלֹּא מִדַּעַת חֲבֵרוֹ הֲרֵי זֶה גֵּזֶל וְאֵינָהּ מְקֻדֶּשֶׁת. וְאִם קִדְּשָׁהּ בְּדָבָר שֶׁאֵין בַּעַל הַבַּיִת מַקְפִּיד עָלָיו כְּגוֹן תְּמָרָה אוֹ אֱגוֹז הֲרֵי זוֹ מְקֻדֶּשֶׁת מִסָּפֵק:","הָיְתָה סְחוֹרָה בֵּינוֹ וּבֵין חֲבֵרוֹ וְחִלְּקָהּ שֶׁלֹּא מִדַּעַת חֲבֵרוֹ וְקִדֵּשׁ בְּחֶלְקוֹ הוֹאִיל וּצְרִיכָה שׁוּמַת בֵּית דִּין אֵינָהּ מְקֻדֶּשֶׁת שֶׁאֵין זֶה נוֹטֵל לְעַצְמוֹ מַה שֶּׁיִּרְצֶה וְיַנִּיחַ מַה שֶּׁיִּרְצֶה:","גָּזַל אֶת הָאִשָּׁה אוֹ גָּנַב מִמֶּנָּה אוֹ חֲמָסָהּ וְחָזַר וְקִדְּשָׁהּ בַּגֵּזֶל וּבַגְּנֵבָה וּבֶחָמָס שֶׁלָּהּ וְאָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת בּוֹ. אִם קָדַם בֵּינֵיהֶן שִׁדּוּכִין וְנָטְלָה וְשָׁתְקָה הֲרֵי זוֹ מְקֻדֶּשֶׁת. וְאִם לֹא שִׁדֵּךְ אוֹתָהּ מֵעוֹלָם אַף עַל פִּי שֶׁשָּׁתְקָה כְּשֶׁנָּתַן לָהּ דְּבָרִים אֵלּוּ בְּתוֹרַת קִדּוּשִׁין אֵינָהּ מְקֻדֶּשֶׁת. וְאִם אָמְרָה הֵן הֲרֵי זוֹ מְקֻדֶּשֶׁת:","וְכֵן אִם נָתַן לָהּ פִּקָּדוֹן וְאָמַר לָהּ כִּנְסִי פִּקָּדוֹן זֶה וְחָזַר וְאָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בּוֹ. אִם אָמַר לָהּ קֹדֶם שֶׁנְּטָלַתּוּ וּנְטָלַתּוּ וְשָׁתְקָה הֲרֵי זוֹ מְקֻדֶּשֶׁת. וְאִם אַחַר שֶׁנְּטָלַתּוּ בְּתוֹרַת פִּקָּדוֹן אָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת בּוֹ וְשָׁתְקָה אֵין זֶה כְּלוּם שֶׁכָּל שְׁתִיקָה שֶׁלְּאַחַר מַתַּן מָעוֹת אֵינָהּ מוֹעֶלֶת. אֲבָל אִם אָמְרָה הֵן אַחַר שֶׁנָּטְלָה הֲרֵי זוֹ מְקֻדֶּשֶׁת:","הֶחֱזִיר לָהּ חוֹב שֶׁהָיָה לָהּ אֶצְלוֹ וְאָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת בּוֹ קֹדֶם שֶׁתִּטְּלֶנּוּ וּנְטָלַתּוּ וְשָׁתְקָה. אִם הָיָה בֵּינֵיהֶן שִׁדּוּכִין הֲרֵי זוֹ מְקֻדֶּשֶׁת. וְאִם לֹא שִׁדֵּךְ אֵינָהּ מְקֻדֶּשֶׁת עַד שֶׁתֹּאמַר הֵן. וְאִם אָמַר לָהּ אַחַר שֶׁנָּטְלָה הַחוֹב שֶׁלָּהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת בּוֹ אֲפִלּוּ אָמְרָה הֵן אֵינָהּ מְ[קֻ]דֶּשֶׁת. שֶׁהֲרֵי לֹא הִגִּיעַ לְיָדָהּ מִמֶּנּוּ כְּלוּם אֶלָּא שֶׁלָּהּ נָטְלָה וּכְבָר נִפְרַע חוֹבוֹ מִשָּׁעָה שֶׁנָּטְלָה וְאֵינָהּ יְכוֹלָה לַחֲזֹר וּלְתָבְעוֹ בַּחוֹב פַּעַם אַחֶרֶת:","הַמְקַדֵּשׁ בְּמִלְוֶה אֲפִלּוּ הָיְתָה בִּשְׁטָר אֵינָהּ מְקֻדֶּשֶׁת. כֵּיצַד. כְּגוֹן שֶׁהָיָה לוֹ אֶצְלָהּ חוֹב דִּינָר וְאָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בַּדִּינָר שֶׁיֵּשׁ לִי בְּיָדֵךְ אֵינָהּ מְקֻדֶּשֶׁת. מִפְּנֵי שֶׁהַמִּלְוֶה לְהוֹצָאָה נִתְּנָה וְאֵין כָּאן שׁוּם דָּבָר קַיָּם לֵהָנוֹת בּוֹ מֵעַתָּה שֶׁכְּבָר הוֹצִיאָה אוֹתוֹ דִּינָר וְעָבְרָה הֲנָאָתוֹ:","הָיָה לוֹ אֶצְלָהּ מִלְוֶה עַל הַמַּשְׁכּוֹן וְקִדְּשָׁהּ בְּאוֹתָהּ הַמִּלְוֶה וְהֶחֱזִיר לָהּ הַמַּשְׁכּוֹן הֲרֵי זוֹ מְקֻדֶּשֶׁת שֶׁהֲרֵי הִיא נֶהֱנֵית בַּמַּשְׁכּוֹן מֵעַתָּה וַהֲרֵי הִגִּיעַ הֲנָאָה לְיָדָהּ:","הַמְקַדֵּשׁ בַּהֲנָאַת מִלְוֶה הֲרֵי זוֹ מְקֻדֶּשֶׁת. כֵּיצַד. כְּגוֹן שֶׁהִלְוָה אוֹתָהּ עַתָּה מָאתַיִם זוּז וְאָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בַּהֲנָאַת זְמַן שֶׁאַרְוִיחַ לָךְ בְּמִלְוֶה זוֹ שֶׁתִּהְיֶה בְּיָדֵךְ כָּךְ וְכָךְ יוֹם וְאֵינִי תּוֹבְעָהּ מִמֵּךְ עַד זְמַן פְּלוֹנִי הֲרֵי זוֹ מְקֻדֶּשֶׁת. שֶׁהֲרֵי יֵשׁ לָהּ הֲנָאָה מֵעַתָּה לְהִשְׁתַּמֵּשׁ בְּמִלְוֶה זוֹ עַד סוֹף זְמַן שֶׁקָּבַע. וְאָסוּר לַעֲשׂוֹת כֵּן מִפְּנֵי שֶׁהִיא כְּרִבִּית. וּפֵרְשׁוּ רַבּוֹתַי בַּהֲנָאַת מִלְוֶה דְּבָרִים שֶׁאֵין רָאוּי לְשָׁמְעָן:","אָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בִּפְרוּטָה זוֹ וּבַחוֹב שֶׁיֵּשׁ לִי אֶצְלֵךְ הֲרֵי זוֹ מְקֻדֶּשֶׁת. וְכֵן אִם אָמַר לָהּ בַּמִּלְוֶה שֶׁיֵּשׁ לִי אֶצְלֵךְ וּבִפְרוּטָה זוֹ הֲרֵי זוֹ מְקֻדֶּשֶׁת:","הָיָה לוֹ חוֹב בְּיַד אֲחֵרִים וְאָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בַּחוֹב שֶׁיֵּשׁ לִי בְּיַד זֶה בְּמַעֲמַד שְׁלָשְׁתָּן הֲרֵי זוֹ מְקֻדֶּשֶׁת:","קִדְּשָׁהּ בְּפִקָּדוֹן שֶׁיֵּשׁ לוֹ בְּיָדָהּ אוֹ בִּשְׁאֵלָה שֶׁהִשְׁאִילָהּ. אִם הָיָה הַפִּקָּדוֹן וְהַשְּׁאֵלָה פְּרוּטָה אוֹ שְׁוֵה פְּרוּטָה בְּאֶחָד מֵהֶן קַיָּם בִּרְשׁוּתָהּ הֲרֵי זוֹ מְקֻדֶּשֶׁת:","אָמַר לָהּ הֲרֵי אֶת מְקֻדֶּשֶׁת לִי בִּשְׂכַר שֶׁאֲדַבֵּר עָלַיִךְ לַשִּׁלְטוֹן וְדִבֵּר עָלֶיהָ לַשִּׁלְטוֹן וְהִנִּיחַ הַשִּׁלְטוֹן וְלֹא תְּבָעָהּ אֵינָהּ מְקֻדֶּשֶׁת אֶלָּא אִם נָתַן לָהּ פְּרוּטָה מִשֶּׁלּוֹ. שֶׁהַהֲנָאָה שֶׁבָּאָה לָהּ מִדְּבָרָיו הֲרֵי הִיא כְּמִלְוֶה וְהַמְקַדֵּשׁ בְּמִלְוֶה אֵינָהּ מְקֻדֶּשֶׁת:","הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בִּמְלָאכָה זוֹ שֶׁאֶעֱשֶׂה עִמָּךְ וְעָשָׂה אֵינָהּ מְקֻדֶּשֶׁת אֶלָּא אִם כֵּן נָתַן לָהּ פְּרוּטָה מִשֶּׁלּוֹ. לְפִי שֶׁהַשְּׂכִירוּת יִזְכֶּה בָּהּ הַפּוֹעֵל מִתְּחִלָּה וְעַד סוֹף כָּל זְמַן שֶׁיַּעֲשֶׂה מִקְצָת מִן הַמְּלָאכָה זוֹכֶה בְּמִקְצָת מִן הַשָּׂכָר וְנִמְצָא הַשָּׂכָר כֻּלּוֹ מִלְוֶה אֶצְלָהּ וְהַמְקַדֵּשׁ בְּמִלְוֶה אֵינָהּ מְקֻדֶּשֶׁת:","הָאִשָּׁה שֶׁאָמְרָה תֵּן דִּינָר לִפְלוֹנִי מַתָּנָה וְאֶתְקַדֵּשׁ אֲנִי לְךָ וְנָתַן וְאָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בַּהֲנָאַת מַתָּנָה זוֹ שֶׁנָּתַתִּי עַל פִּיךְ הֲרֵי זוֹ מְקֻדֶּשֶׁת. אַף עַל פִּי שֶׁלֹּא הִגִּיעַ לָהּ כְּלוּם הֲרֵי נֶהֱנֵית בִּרְצוֹנָהּ שֶׁנַּעֲשָׂה וְנֶהֱנָה פְּלוֹנִי בִּגְלָלָהּ. וְכֵן אִם אָמְרָה לוֹ תֵּן דִּינָר לִפְלוֹנִי מַתָּנָה וְאֶתְקַדֵּשׁ לוֹ וְנָתַן לוֹ וְקִדְּשָׁהּ אוֹתוֹ פְּלוֹנִי וְאָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בַּהֲנָאַת מַתָּנָה זוֹ שֶׁקִּבַּלְתִּי בִּרְצוֹנֵךְ הֲרֵי זוֹ מְקֻדֶּשֶׁת:","אָמַר לָהּ הֵילָךְ דִּינָר זֶה בְּמַתָּנָה וְהִתְקַדְּשִׁי לִפְלוֹנִי וְקִדְּשָׁהּ אוֹתוֹ פְּלוֹנִי וְאָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בַּהֲנָאָה זוֹ הַבָּאָה לִיךְ בִּגְלָלִי הֲרֵי זוֹ מְקֻדֶּשֶׁת אַף עַל פִּי שֶׁלֹּא נָתַן לָהּ הַמְקַדֵּשׁ כְּלוּם. אָמְרָה לוֹ הֵילָךְ דִּינָר זֶה מַתָּנָה וְאֶתְקַדֵּשׁ לְךָ וּלְקָחוֹ וְאָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בַּהֲנָאָה זוֹ שֶׁקִּבַּלְתִּי מִמֵּךְ מַתָּנָה אִם אָדָם חָשׁוּב הוּא הֲרֵי זוֹ מְקֻדֶּשֶׁת שֶׁהֲנָאָה יֵשׁ לָהּ בִּהְיוֹתוֹ נֶהֱנֶה מִמֶּנָּה וּבַהֲנָאָה זוֹ הִקְנַת עַצְמָהּ לוֹ:","הָאוֹמֵר לְאִשָּׁה הִתְקַדְּשִׁי לִי בְּדִינָר וַהֲרֵי זֶה הַמַּשְׁכּוֹן בְּיָדֵךְ עַד שֶׁאֶתֵּן הַדִּינָר אֵינָהּ מְקֻדֶּשֶׁת לוֹ. לְפִי שֶׁלֹּא הִגִּיעַ הַדִּינָר לְיָדָהּ וְלֹא הַמַּשְׁכּוֹן נָתַן לֶהֱיוֹתוֹ שֶׁלָּהּ. הָיָה בְּיָדוֹ מַשְׁכּוֹן עַל חוֹב שֶׁיֵּשׁ לוֹ אֵצֶל אֲחֵרִים וְקִדֵּשׁ בּוֹ אִשָּׁה אַף עַל פִּי שֶׁאֵינוֹ שֶׁלּוֹ הֲרֵי זוֹ מְקֻדֶּשֶׁת. לְפִי שֶׁבַּעַל חוֹב יֵשׁ לוֹ מִקְצָת קִנְיָן בְּגוּפוֹ שֶׁל מַשְׁכּוֹן:","הָאוֹמֵר לְאִשָּׁה הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בְּדִינָר זֶה עַל מְנָת שֶׁתַּחֲזִירִיהוּ לִי אֵינָהּ מְקֻדֶּשֶׁת בֵּין הֶחֱזִירָה בֵּין לֹא הֶחֱזִירָה. שֶׁאִם לֹא הֶחֱזִירַתּוּ לֹא נִתְקַיֵּם הַתְּנַאי. וְאִם הֶחֱזִירַתּוּ הֲרֵי לֹא נֶהֱנֵית וְלֹא הִגִּיעַ לְיָדָהּ כְּלוּם:","נָתַן לָהּ אֲגֻדָּה שֶׁל הֲדַס וְכַיּוֹצֵא בָּהּ וְאָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בְּזוֹ וְקִבְּלָה אוֹתוֹ. וְאָמְרוּ לוֹ וַהֲלֹא אֵין בָּהּ שְׁוֵה פְּרוּטָה וְאָמַר תִּתְקַדֵּשׁ בְּאַרְבָּעָה זוּזִים הַמֻּחְבָּאִים בְּתוֹךְ הָאֲגֻדָּה. אִם אָמְרָה הֵן הֲרֵי זוֹ מְקֻדֶּשֶׁת. וְאִם שָׁתְקָה אֵינָהּ מְקֻדֶּשֶׁת בְּמָעוֹת אֵלּוּ שֶׁהַשְּׁתִיקָה שֶׁלְּאַחַר מַתַּן מָעוֹת אֵינָהּ מוֹעֶלֶת כְּלוּם וְתִהְיֶה מְקֻדֶּשֶׁת בְּסָפֵק מִפְּנֵי הָאֲגֻדָּה שֶׁמָּא שְׁוֵה פְּרוּטָה בְּמָקוֹם אַחֵר:","הָאוֹמֵר לְאִשָּׁה הִתְקַדְּשִׁי לִי בִּתְמָרָה זוֹ הִתְקַדְּשִׁי לִי בְּזוֹ הִתְקַדְּשִׁי לִי בְּזוֹ אִם יֵשׁ בְּאַחַת מֵהֶן שְׁוֵה פְּרוּטָה הֲרֵי זוֹ מְקֻדֶּשֶׁת וְאִם לָאו אֵינָהּ מְקֻדֶּשֶׁת אֶלָּא מִסָּפֵק שֶׁמָּא תִּשְׁוֶה תְּמָרָה אַחַת פְּרוּטָה בְּמָקוֹם אַחֵר:","אָמַר לָהּ הִתְקַדְּשִׁי לִי בְּזוֹ וּבְזוֹ וּבְזוֹ אִם יֵשׁ בְּכֻלָּם שְׁוֵה פְּרוּטָה מְקֻדֶּשֶׁת וְאִם לָאו אֵינָהּ מְקֻדֶּשֶׁת אֶלָּא מִסָּפֵק. הָיְתָה אוֹכֶלֶת רִאשׁוֹנָה רִאשׁוֹנָה אִם יֵשׁ בָּאַחֲרוֹנָה שְׁוֵה פְּרוּטָה מְקֻדֶּשֶׁת וְאִם לָאו אֵינָהּ מְקֻדֶּשֶׁת אֶלָּא מִסָּפֵק. שֶׁאוֹתָן תְּמָרִים שֶׁאָכְלָה הֲרֵי הֵן כְּמִלְוֶה וְהַמְקַדֵּשׁ בְּמִלְוֶה אֵינָהּ מְקֻדֶּשֶׁת וְנִמְצָא שֶׁאֵין הַקִּדּוּשִׁין אֶלָּא בִּתְמָרָה אַחֲרוֹנָה:","אָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בְּאֵלּוּ אִם יֵשׁ בְּכֻלָּן שְׁוֵה פְּרוּטָה מְ[קֻ]דֶּשֶׁת אַף עַל פִּי שֶׁהִיא אוֹכֶלֶת רִאשׁוֹנָה רִאשׁוֹנָה שֶׁלָּהּ הִיא אוֹכֶלֶת וּמְ[קֻ]דֶּשֶׁת:","הָאוֹמֵר לְאִשָּׁה הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בְּכוֹס זֶה אִם הָיָה מָלֵא מַיִם הֲרֵי זוֹ מְקֻדֶּשֶׁת בּוֹ וּבְמַה שֶּׁבְּתוֹכוֹ. וְאִם הָיָה מָלֵא יַיִן הֲרֵי זוֹ מְקֻדֶּשֶׁת בּוֹ וְלֹא בְּמַה שֶּׁבְּתוֹכוֹ. וְאִם הָיָה מָלֵא שֶׁמֶן הֲרֵי זוֹ מְקֻדֶּשֶׁת בְּמַה שֶּׁבְּתוֹכוֹ וְלֹא בּוֹ. לְפִיכָךְ אִם לֹא הָיָה בַּשֶּׁמֶן שְׁוֵה פְּרוּטָה הֲרֵי זוֹ מְקֻדֶּשֶׁת בְּסָפֵק. וְאִם הָיָה בַּשֶּׁמֶן שְׁוֵה פְּרוּטָה הֲרֵי זוֹ מְקֻדֶּשֶׁת וַדַּאי וְאֵין מַשְׁגִּיחִין עַל הַכּוֹס:"],"Mishneh Torah, Mourning 3":["כָּל כֹּהֵן שֶׁנִּטְמָא לְמֵת חוּץ מִשִּׁשָּׁה מֵתִים הַמְפֹרָשִׁים בַּתּוֹרָה אוֹ אִשְׁתּוֹ. בְּעֵדִים וְהַתְרָאָה. הֲרֵי זֶה לוֹקֶה שֶׁנֶּאֱמַר (ויקרא כא א) \"לְנֶפֶשׁ לֹא יִטַּמָּא בְּעַמָּיו\". וְאֶחָד הַנּוֹגֵעַ בְּמֵת אוֹ הַמַּאֲהִיל אוֹ הַנּוֹשֵׂא. וְאֶחָד הַמֵּת וְאֶחָד שְׁאָר הַטֻּמְאוֹת הַפּוֹרְשׁוֹת מִן הַמֵּת שֶׁנֶּאֱמַר לְנֶפֶשׁ לֹא יִטַּמָּא בְּעַמָּיו. וּכְבָר פֵּרַשְׁנוּ בְּהִלְכוֹת טֻמְאַת מֵת כָּל דְּבָרִים הַמְטַמְּאִין מִן הַמֵּת מִן הַתּוֹרָה אוֹ מִדִּבְרֵיהֶם:","וְכֵן אִם נָגַע הַכֹּהֵן בְּקֶבֶר לוֹקֶה. אֲבָל נוֹגֵעַ הוּא בִּבְגָדִים שֶׁנָּגְעוּ בְּמֵת אַף עַל פִּי שֶׁמִּטַּמֵּא בָּהֶן טֻמְאַת שִׁבְעָה:","וְכֵן אִם נִכְנַס לְאֹהֶל טָמֵא שֶׁנִּכְנְסָה לוֹ הַטֻּמְאָה לוֹקֶה. אַף עַל פִּי שֶׁעַצְמָהּ שֶׁל טֻמְאָה בְּבַיִת אַחֵר. וּכְבָר בֵּאַרְנוּ כָּל הָאֹהָלִים שֶׁתִּכָּנֵס לָהֶן הַטֻּמְאָה אוֹ שֶׁתֵּצֵא מֵהֶן וְדִין הַסְּכָכוֹת וְהַפְּרָעוֹת. וְכָל הַדְּבָרִים הַמְּבִיאִין אֶת הַטֻּמְאָה וְהַחוֹצְצִין בִּפְנֵי הַטֻּמְאָה. וְאֵי זֶה מֵהֶן דִּין תּוֹרָה וְאֵי זֶה מֵהֶן מִדִּבְרֵיהֶן. הַכּל בְּהִלְכוֹת טֻמְאַת מֵת. וְשָׁם בֵּאַרְנוּ שֶׁאֵין עַכּוּ\"ם מְטַמְּאִין בְּאֹהֶל וּלְפִיכָךְ קִבְרוֹתֵיהֶם טְהוֹרִים וּמֻתָּר לְכֹהֵן לִכָּנֵס לְשָׁם וְלִדְרֹךְ עַל קִבְרוֹתֵיהֶם. וְאֵינוֹ אָסוּר אֶלָּא שֶׁיִּגַּע בַּטֻּמְאָה אוֹ שֶׁיִּשָּׂאֶנָּה כְּמוֹ שֶׁבֵּאַרְנוּ שָׁם:","כֹּהֵן שֶׁנִּכְנַס לְאֹהֶל הַמֵּת אוֹ לְבֵית הַקְּבָרוֹת בִּשְׁגָגָה וְאַחַר שֶׁיָּדַע הִתְרוּ בּוֹ אִם קָפַץ וְיָצָא פָּטוּר. וְאִם יָשַׁב שָׁם כְּדֵי הִשְׁתַּחֲוָיָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּעִנְיַן טֻמְאַת מִקְדָּשׁ הֲרֵי זֶה לוֹקֶה. נִכְנַס וְיָצָא וְחָזַר וְנִכְנַס וְיָצָא אִם הִתְרוּ בּוֹ עַל כָּל פַּעַם וּפַעַם לוֹקֶה עַל כָּל כְּנִיסָה וּכְנִיסָה. וְכֵן אִם נָגַע בְּמֵת וְהִתְרוּ בּוֹ וּפֵרַשׁ וְחָזַר וְנָגַע וְהִתְרוּ בּוֹ אֲפִלּוּ מֵאָה פְּעָמִים לוֹקֶה עַל כָּל אַחַת וְאַחַת. הָיָה נוֹגֵעַ וְלֹא פֵּרַשׁ אוֹ שֶׁהָיָה עוֹמֵד בְּבֵית הַקְּבָרוֹת וְנָגַע בְּמֵתִים אֲחֵרִים. אַף עַל פִּי שֶׁהִתְרוּ בּוֹ כַּמָּה פְּעָמִים אֵינוֹ לוֹקֶה אֶלָּא אַחַת שֶׁהֲרֵי מְחֻלָּל וְעוֹמֵד כָּל זְמַן שֶׁלֹּא פֵּרַשׁ:","הַמְטַמֵּא אֶת הַכֹּהֵן. אִם הָיוּ שְׁנֵיהֶם מְזִידִין הֲרֵי הַכֹּהֵן לוֹקֶה וְזֶה שֶׁטִּמְּאוֹ עוֹבֵר עַל וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁל. הָיָה הַכֹּהֵן שׁוֹגֵג וְזֶה שֶׁטִּמְּאוֹ מֵזִיד הֲרֵי זֶה שֶׁטִּמְּאוֹ לוֹקֶה:","כֹּהֵן גָּדוֹל אֵינוֹ מִטַּמֵּא לִקְרוֹבִים שֶׁנֶּאֱמַר (ויקרא כא יא) \"לְאָבִיו וּלְאִמּוֹ לֹא יִטַּמָּא\". וְכֵן אֵינוֹ נִכְנָס עִם הַמֵּת בְּאֹהֶל אֲפִלּוּ קְרוֹבָיו. שֶׁנֶּאֱמַר (ויקרא כא יא) \"וְעַל כָּל נַפְשֹׁת מֵת לֹא יָבֹא\". הָא לָמַדְתָּ שֶׁהוּא חַיָּב בְּלֹא יָבֹא וְחַיָּב בְּלֹא יִטַּמָּא. כֵּיצַד. נָגַע אוֹ נָשָׂא לוֹקֶה אַחַת. נִכְנַס לְאֹהֶל וְיָשַׁב שָׁם עַד שֶׁמֵּת עָלָיו הַמֵּת. אוֹ שֶׁנִּכְנַס לְשִׁדָּה תֵּבָה וּמִגְדָּל וּבָא חֲבֵרוֹ וּפָרַע עָלָיו גַּג הַשִּׁדָּה שֶׁהֲרֵי טֻמְאָה וּבִיאָה בָּאִין כְּאֶחָד. הֲרֵי זֶה לוֹקֶה שְׁתַּיִם מִשּׁוּם לֹא יָבֹא וּמִשּׁוּם לֹא יִטַּמָּא:","נִטְמָא מִקֹּדֶם וְאַחַר כָּךְ נִכְנַס לְאֹהֶל אִם הִתְרוּ בּוֹ לוֹקֶה אַף עַל הַבִּיאָה:","כֹּהֵן שֶׁפָּגַע בְּמֵת מִצְוָה בַּדֶּרֶךְ הֲרֵי זֶה מִטַּמֵּא לוֹ. אֲפִלּוּ כֹּהֵן גָּדוֹל חַיָּב לְהִטַּמֵּא לוֹ וּלְקָבְרוֹ. וְאֵיזֶהוּ מֵת מִצְוָה. אֶחָד מִיִּשְׂרָאֵל שֶׁהָיָה מֻשְׁלָךְ בַּדֶּרֶךְ וְאֵין לוֹ קוֹבְרִין. דָּבָר זֶה הֲלָכָה מִפִּי הַקַּבָּלָה. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה הַכֹּהֵן לְבַדּוֹ וְאֵין עִמּוֹ אַחֵר וַאֲפִלּוּ קָרָא שֵׁם בַּדֶּרֶךְ וְאֵין לוֹ עוֹנֶה. אֲבָל אִם כְּשֶׁיִּקְרָא אֲחֵרִים עוֹנִים אוֹתוֹ אֵין זֶה מֵת מִצְוָה אֶלָּא יִקְרָא לַאֲחֵרִים וְיָבוֹאוּ וְיַעַסְקוּ בּוֹ:","הָיוּ כֹּהֵן וְנָזִיר מְהַלְּכִין בְּדֶרֶךְ וּפָגְעוּ בְּמֵת מִצְוָה. יִתְעַסֵּק בּוֹ הַנָּזִיר לְפִי שֶׁאֵין קְדֻשָּׁתוֹ קְדֻשַּׁת עוֹלָם וְאַל יִטָּמֵא בּוֹ הַכֹּהֵן אַף עַל פִּי שֶׁהוּא כֹּהֵן הֶדְיוֹט. הָיָה כֹּהֵן גָּדוֹל וְכֹהֵן הֶדְיוֹט יִטָּמֵא הַהֶדְיוֹט. וְכָל הַקּוֹדֵם אֶת חֲבֵרוֹ בְּמַעֲלָה מִתְאַחֵר בְּטֻמְאָה. וּסְגָן עִם מְשׁוּחַ מִלְחָמָה שֶׁפָּגְעוּ בְּמֵת מִצְוָה יִטָּמֵא מְשׁוּחַ מִלְחָמָה וְאַל יִטָּמֵא הַסְּגָן:","נָשִׂיא שֶׁמֵּת הַכּל מִטַּמְּאִין לוֹ אֲפִלּוּ כֹּהֲנִים. עֲשָׂאוּהוּ כְּמֵת מִצְוָה לַכּל מִפְּנֵי שֶׁהַכּל חַיָּבִין בִּכְבוֹדוֹ. וְכֵן הַכּל אוֹנְנִין עָלָיו:","בְּנוֹת אַהֲרֹן לֹא הֻזְהֲרוּ עַל טֻמְאַת מֵת שֶׁנֶּאֱמַר (ויקרא כא א) \"אֱמֹר אֶל הַכֹּהֲנִים בְּנֵי אַהֲרֹן\" וְלֹא בְּנוֹת אַהֲרֹן. וְכֵן הַחֲלָלִים מֻתָּרִין לְהִטַּמֵּא שֶׁנֶּאֱמַר בְּנֵי אַהֲרֹן עַד שֶׁיִּהְיוּ בְּכִהוּנָם:","כֹּהֵן קָטָן הֲרֵי הַגְּדוֹלִים מֻזְהָרִים שֶׁלֹּא יְטַמְּאוּהוּ. וְאִם בָּא לְהִטַּמֵּא מֵעַצְמוֹ אֵין בֵּית דִּין מְצֻוִּין עָלָיו לְהַפְרִישׁוֹ. אֲבָל אָבִיו צָרִיךְ לְחַנְּכוֹ בִּקְדֻשָּׁה:","מֵת תּוֹפֵשׂ אַרְבַּע אַמּוֹת שֶׁלּוֹ לְטֻמְאָה. וְכָל כֹּהֵן שֶׁנִּכְנַס לְתוֹךְ אַרְבַּע אַמּוֹת מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וְכֵן אִם נִכְנַס לְבֵית הַפְּרָס אוֹ יָצָא חוּצָה לָאָרֶץ. אוֹ שֶׁנִּטְמָא בְּדַם תְּבוּסָה. אוֹ בְּגוֹלֵל וּבְדוֹפֵק וְכַיּוֹצֵא בָּהֶן. מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. מִפְּנֵי שֶׁהֵן אָבוֹת שֶׁל דִּבְרֵיהֶם כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת טֻמְאַת מֵת. אֲבָל אִם נִכְנַס לְבֵית הַקְּבָרוֹת לוֹקֶה מִן הַתּוֹרָה:","מֻתָּר לְכֹהֵן לְהִטַּמֵּא בְּבֵית הַפְּרָס אוֹ בְּחוּצָה לָאָרֶץ לִדְבַר מִצְוָה בִּזְמַן שֶׁאֵין שָׁם דֶּרֶךְ אֶלָּא הִיא. כְּגוֹן שֶׁהָלַךְ לִשָּׂא אִשָּׁה אוֹ לִלְמֹד תּוֹרָה. אַף עַל פִּי שֶׁיֵּשׁ שָׁם מִי שֶׁיְּלַמְּדֶנּוּ בְּאֶרֶץ יִשְׂרָאֵל לֹא מִן הַכּל אָדָם זוֹכֶה לִלְמֹד. וְכֵן מִטַּמֵּא בְּטֻמְאָה מִדִּבְרֵיהֶם לִכְבוֹד הַבְּרִיּוֹת. כֵּיצַד. אָבֵל שֶׁהָלַךְ בְּבֵית הַפְּרָס הַכּל הוֹלְכִין אַחֲרָיו שָׁם לְנַחֲמוֹ. וְכֵן מְדַלְּגִין עַל גַּבֵּי אֲרוֹנוֹת שֶׁל מֵתִים לִקְרַאת מַלְכֵי יִשְׂרָאֵל וַאֲפִלּוּ מַלְכֵי עַכּוּ\"ם כְּדֵי לְהַבְחִין בֵּינָם לְבֵין מַלְכֵי יִשְׂרָאֵל כְּשֶׁיַּחְזֹר כְּבוֹדָן לִמְקוֹמָן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְכֵן מִטַּמֵּא בְּטֻמְאָה שֶׁל דִּבְרֵיהֶם לָדוּן עִם הָעַכּוּ\"ם וּלְעַרְעֵר עִמָּהֶן. מִפְּנֵי שֶׁהוּא מַצִּיל מִיָּדָם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Murderer and the Preservation of Life 2":["כָּל הַהוֹרֵג חֲבֵרוֹ בְּיָדוֹ כְּגוֹן שֶׁהִכָּהוּ בְּסַיִף אוֹ בְּאֶבֶן הַמְּמִיתָה. אוֹ שֶׁחֲנָקוֹ עַד שֶׁמֵּת. אוֹ שְׂרָפוֹ בְּאֵשׁ. הוֹאִיל וַהֲרָגוֹ מִכָּל מָקוֹם הוּא בְּעַצְמוֹ הֲרֵי זֶה נֶהֱרָג בְּבֵית דִּין:","אֲבָל הַשּׂוֹכֵר הוֹרֵג לַהֲרֹג אֶת חֲבֵרוֹ אוֹ שֶׁשָּׁלַח עֲבָדָיו וַהֲרָגוּהוּ. אוֹ שֶׁכְּפָתוֹ וְהִנִּיחוֹ לִפְנֵי הָאֲרִי וְכַיּוֹצֵא בּוֹ וַהֲרָגַתְהוּ חַיָּה. וְכֵן הַהוֹרֵג אֶת עַצְמוֹ. כָּל אֶחָד מֵאֵלּוּ שׁוֹפֵךְ דָּמִים הוּא. וַעֲוֹן הֲרִיגָה בְּיָדוֹ וְחַיָּב מִיתָה לַשָּׁמַיִם. וְאֵין בָּהֶן מִיתַת בֵּית דִּין:","וּמִנַּיִן שֶׁכֵּן הוּא הַדִּין. שֶׁנֶּאֱמַר (בראשית ט ו) \"שֹׁפֵךְ דַּם הָאָדָם בָּאָדָם דָּמוֹ יִשָּׁפֵךְ\" זֶה הַהוֹרֵג בְּעַצְמוֹ שֶׁלֹּא עַל יְדֵי שָׁלִיחַ. (בראשית ט ה) \"אֶת דִּמְכֶם לְנַפְשֹׁתֵיכֶם אֶדְרשׁ\" זֶה הוֹרֵג עַצְמוֹ. (בראשית ט ה) \"מִיַּד כָּל חַיָּה אֶדְרְשֶׁנּוּ\" זֶה הַמּוֹסֵר חֲבֵרוֹ לִפְנֵי חַיָּה לְטָרְפוֹ. (בראשית ט ה) \"מִיַּד הָאָדָם מִיַּד אִישׁ אָחִיו אֶדְרשׁ אֶת נֶפֶשׁ הָאָדָם\" זֶה הַשּׂוֹכֵר אֲחֵרִים לַהֲרֹג אֶת חֲבֵרוֹ. וּבְפֵרוּשׁ נֶאֱמַר בִּשְׁלָשְׁתָּן לְשׁוֹן דְּרִישָׁה הֲרֵי דִּינָם מָסוּר לַשָּׁמַיִם:","וְכָל אֵלּוּ הָרַצְחָנִים וְכַיּוֹצֵא בָּהֶן שֶׁאֵינָן מְחֻיָּבִין מִיתַת בֵּית דִּין. אִם רָצָה מֶלֶךְ יִשְׂרָאֵל לְהָרְגָם בְּדִין הַמַּלְכוּת וְתַקָּנַת הָעוֹלָם הָרְשׁוּת בְּיָדוֹ. וְכֵן אִם רָאוּ בֵּית דִּין לְהָרְגָם בְּהוֹרָאַת שָׁעָה אִם הָיְתָה הַשָּׁעָה צְרִיכָה לְכָךְ יֵשׁ לָהֶם רְשׁוּת כְּפִי מַה שֶּׁיִּרְאוּ:","הֲרֵי שֶׁלֹּא הֲרָגָם הַמֶּלֶךְ וְלֹא הָיְתָה הַשָּׁעָה צְרִיכָה לְכָךְ לְחַזֵּק הַדָּבָר הֲרֵי בֵּית דִּין חַיָּבִין מִכָּל מָקוֹם לְהַכּוֹתָם מַכָּה רַבָּה הַקְּרוֹבָה לְמִיתָה לְאָסְרָם בְּמָצוֹר וּבְמָצוֹק שָׁנִים רַבּוֹת וּלְצַעֲרָן בְּכָל מִינֵי צַעַר כְּדֵי לְהַפְחִיד וּלְאַיֵּם עַל שְׁאָר הָרְשָׁעִים שֶׁלֹּא יִהְיֶה הַדָּבָר לָהֶם לְפוּקָה וּלְמִכְשׁוֹל וְיֹאמַר הֲרֵינִי מְסַבֵּב לַהֲרֹג אוֹיְבַי כְּדֶרֶךְ שֶׁעָשָׂה פְּלוֹנִי וְאֶפָּטֵר:","אֶחָד הַהוֹרֵג אֶת הַגָּדוֹל אוֹ אֶת הַקָּטָן בֶּן יוֹמוֹ. בֵּין זָכָר בֵּין נְקֵבָה. הֲרֵי זֶה נֶהֱרָג עָלָיו אִם הָרַג בְּזָדוֹן. אוֹ גּוֹלֶה אִם הָרַג בִּשְׁגָגָה. וְהוּא שֶׁכָּלוּ לוֹ חֳדָשָׁיו. אֲבָל אִם נוֹלַד לְפָחוֹת מִתִּשְׁעָה חֳדָשִׁים הֲרֵי הוּא כְּנֵפֶל עַד שֶׁיִּשְׁהֶה שְׁלֹשִׁים יוֹם וְהַהוֹרְגוֹ בְּתוֹךְ שְׁלֹשִׁים יוֹם אֵינוֹ נֶהֱרָג עָלָיו:","אֶחָד הַהוֹרֵג אֶת הַבָּרִיא אוֹ אֶת הַחוֹלֶה הַנּוֹטֶה לָמוּת. וַאֲפִלּוּ הָרַג אֶת הַגּוֹסֵס נֶהֱרָג עָלָיו. וְאִם הָיָה גּוֹסֵס בִּידֵי אָדָם כְּגוֹן שֶׁהִכּוּהוּ עַד שֶׁנָּטָה לָמוּת וַהֲרֵי הוּא גּוֹסֵס. הַהוֹרְגוֹ אֵין בֵּית דִּין מְמִיתִין אוֹתוֹ:","הַהוֹרֵג אֶת הַטְּרֵפָה אַף עַל פִּי שֶׁאוֹכֵל וְשׁוֹתֶה וּמְהַלֵּךְ בַּשּׁוּק הֲרֵי זֶה פָּטוּר מִדִּינֵי אָדָם. וְכָל אָדָם בְּחֶזְקַת שָׁלֵם וְהַהוֹרְגוֹ נֶהֱרָג עַד שֶׁיִּוָּדַע בְּוַדַּאי שֶׁזֶּה טְרֵפָה וְיֹאמְרוּ הָרוֹפְאִים שֶׁמַּכָּה זוֹ אֵין לָהּ תְּעָלָה בָּאָדָם וּבָהּ יָמוּת אִם לֹא יְמִיתֶנּוּ דָּבָר אַחֵר:","אָדָם טְרֵפָה שֶׁהָרַג אֶת הַנֶּפֶשׁ נֶהֱרָג שֶׁנֶּאֱמַר (דברים יג ו) \"וּבִעַרְתָּ הָרָע מִקִּרְבֶּךָ\". וְהוּא שֶׁיַּהֲרֹג בִּפְנֵי בֵּית דִּין. אֲבָל בִּפְנֵי עֵדִים פָּטוּר שֶׁמָּא יָזֹמּוּ וְאִם הוּזַמּוּ אֵינָן נֶהֱרָגִין שֶׁהֲרֵי לֹא זָמְמוּ אֶלָּא לַהֲרֹג טְרֵפָה. וְכָל עֵדוּת שֶׁאֵינָהּ רְאוּיָה לַהֲזָמָה אֵינָהּ עֵדוּת בְּדִינֵי נְפָשׁוֹת:","אֶחָד הַהוֹרֵג אֶת יִשְׂרָאֵל אוֹ הַהוֹרֵג עֶבֶד כְּנַעֲנִי הֲרֵי זֶה נֶהֱרָג עָלָיו. וְאִם הָרַג בִּשְׁגָגָה גּוֹלֶה:","בָּרִאשׁוֹנָה מִי שֶׁהָרַג גֵּר תּוֹשָׁב אֵינוֹ נֶהֱרָג עָלָיו בְּבֵית דִּין שֶׁנֶּאֱמַר (שמות כא יד) \"וְכִי יָזִד אִישׁ עַל רֵעֵהוּ\". וְאֵין צָרִיךְ לוֹמַר שֶׁאֵינוֹ נֶהֱרָג עַל הָעַכּוּ\"ם. וְאֶחָד הַהוֹרֵג אֶת עֶבֶד אֲחֵרִים אוֹ הַהוֹרֵג עַבְדּוֹ הֲרֵי זֶה נֶהֱרָג עָלָיו שֶׁהָעֶבֶד קִבֵּל עָלָיו מִצְוֹת וְנוֹסַף עַל נַחֲלַת ה':","מַה בֵּין עַבְדּוֹ לְעֶבֶד אֲחֵרִים. שֶׁעַבְדּוֹ יֵשׁ לוֹ רְשׁוּת לְהַכּוֹתוֹ. לְפִיכָךְ אִם הִכָּהוּ הַכָּאָה שֶׁיֵּשׁ בָּהּ כְּדֵי לְהָמִית וְנָטָה לָמוּת וְעָמַד עֶשְׂרִים וְאַרְבַּע שָׁעוֹת וְאַחַר כָּךְ מֵת לֹא הָיָה נֶהֱרָג עָלָיו אַף עַל פִּי שֶׁמֵּת מֵחֲמַת הַמַּכָּה שֶׁנֶּאֱמַר (שמות כא כא) \"לֹא יֻקַּם כִּי כַסְפּוֹ הוּא\". וּמַהוּ (שמות כא כא) \"יוֹם אוֹ יוֹמָיִם\" יוֹם שֶׁהוּא כְּיוֹמַיִם שֶׁהוּא מֵעֵת לְעֵת:","אֲבָל הַמַּכֶּה עֶבֶד שֶׁאֵינוֹ שֶׁלּוֹ. אֲפִלּוּ מֵת לְאַחַר כַּמָּה יָמִים מֵחֲמַת הַמַּכָּה הוֹאִיל וְהִכָּהוּ כְּדֵי לְהָמִית הֲרֵי זֶה נֶהֱרָג עָלָיו כִּשְׁאָר בְּנֵי חוֹרִין:","יֵרָאֶה לִי שֶׁהַמַּכֶּה אֶת עַבְדּוֹ בְּסַכִּין וְסַיִף אוֹ בְּאֶבֶן וְאֶגְרוֹף וְכַיּוֹצֵא בָּהֶן וַאֲמָדוּהוּ לְמִיתָה וּמֵת אֵינוֹ בְּדִין (שמות כא כא) \"יוֹם אוֹ יוֹמַיִם\" אֶלָּא אֲפִלּוּ מֵת לְאַחַר שָׁנָה נֶהֱרָג עָלָיו. לְכָךְ נֶאֱמַר (שמות כא כ) \"בַּשֵּׁבֶט\" שֶׁלֹּא נָתְנָה תּוֹרָה רְשׁוּת לְהַכּוֹתוֹ אֶלָּא בְּשֵׁבֶט וּמַקֵּל וּרְצוּעָה וְכַיּוֹצֵא בָּהֶן וְלֹא בְּהַכָּאַת רְצִיחָה:","הַמּוֹכֵר עַבְדּוֹ וּפָסַק עִמּוֹ שֶׁיְּשַׁמְּשֵׁנוּ שְׁלֹשִׁים יוֹם וְהִכָּהוּ אֶחָד מֵהֶן בְּתוֹךְ הַשְּׁלֹשִׁים יוֹם וֶהֱמִיתוֹ. הֲרֵי זֶה נֶהֱרָג עָלָיו וְאֵינוֹ בְּדִין (שמות כא כא) \"יוֹם אוֹ יוֹמַיִם\". הָרִאשׁוֹן לְפִי שֶׁאֵינוֹ (שמות כא כא) \"כַּסְפּוֹ\" הַמְיֻחָד לוֹ. וְהַשֵּׁנִי לְפִי שֶׁאֵינוֹ עֲדַיִן תַּחְתָּיו:","וְכֵן מִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין וְעֶבֶד שֶׁל שְׁנֵי שֻׁתָּפִין אֵינוֹ בְּדִין (שמות כא כא) \"יוֹם אוֹ יוֹמַיִם\". שֶׁהֲרֵי אֵינָן לְאֶחָד מֵהֶן (שמות כא כא) \"כַּסְפּוֹ\" הַמְיֻחָד לוֹ. וּלְפִיכָךְ נֶהֱרָג עָלָיו כִּשְׁאָר הָעָם:"],"Mishneh Torah, Nazariteship 4":["הָאוֹמֵר הֲרֵינִי נָזִיר הֲרֵי זֶה מְגַלֵּחַ תִּגְלַחַת טָהֳרָה יוֹם אֶחָד וּשְׁלֹשִׁים. וְאִם גִּלֵּחַ בְּיוֹם שְׁלֹשִׁים יָצָא. אָמַר הֲרֵינִי נָזִיר שְׁלֹשִׁים יוֹם אֵינוֹ מְגַלֵּחַ אֶלָּא בְּיוֹם אֶחָד וּשְׁלֹשִׁים:","מִי שֶׁנָּזַר שְׁתֵּי נְזִירֻיּוֹת מְגַלֵּחַ אֶת הָרִאשׁוֹנָה בְּיוֹם אֶחָד וּשְׁלֹשִׁים. וְאֶת הַשְּׁנִיָּה בְּיוֹם אֶחָד וְשִׁשִּׁים. וְאִם גִּלֵּחַ אֶת הָרִאשׁוֹנָה יוֹם שְׁלֹשִׁים מְגַלֵּחַ אֶת הַשְּׁנִיָּה יוֹם שִׁשִּׁים. וְאִם גִּלֵּחַ יוֹם תִּשְׁעָה וַחֲמִשִּׁים יָצָא. שֶׁיּוֹם שְׁלֹשִׁים עוֹלֶה לוֹ אַף לְמִנְיַן נְזִירוּת שְׁנִיָּה:","האוֹמֵר הֲרֵינִי נָזִיר וְנָזִיר כְּשֶׁיִּהְיֶה לִי בֵּן. וְהִתְחִיל נְזִירוּת שֶׁלּוֹ וְאַחַר כָּךְ נוֹלַד לוֹ בֵּן. מַשְׁלִים אֶת שֶׁלּוֹ וְאַחַר כָּךְ מוֹנֶה אֶת שֶׁל בְּנוֹ. אָמַר הֲרֵינִי נָזִיר כְּשֶׁיִּהְיֶה לִי בֵּן וַהֲרֵינִי נָזִיר כָּךְ וְכָךְ יוֹם. וְהִתְחִיל בִּנְזִירוּת שֶׁלּוֹ וְאַחַר כָּךְ נוֹלַד לוֹ בֵּן. פּוֹסֵק נְזִירוּת שֶׁלּוֹ וּמוֹנֶה אֶת שֶׁל בְּנוֹ וְאַחַר כָּךְ חוֹזֵר וּמַשְׁלִים אֶת שֶׁלּוֹ וַהֲרֵי שְׁתֵּיהֶן כִּנְזִירוּת אַחַת. לְפִיכָךְ אִם נִטְמָא בְּתוֹךְ נְזִירוּת שֶׁל בְּנוֹ סוֹתֵר הַכּל. נִטְמָא אַחַר נְזִירוּת בְּנוֹ כְּשֶׁהִתְחִיל לְהַשְׁלִים נְזִירוּתוֹ אֵינוֹ סוֹתֵר אֶלָּא עַד נְזִירוּת בְּנוֹ. וּבְכַמָּה יָמִים מַשְׁלִים אֶת שֶׁלּוֹ. אִם נִשְׁאַר מִנְּזִירוּתוֹ כְּשֶׁנּוֹלַד הַבֵּן שְׁלֹשִׁים אוֹ יוֹתֵר מוֹנֶה נְזִירוּת בְּנוֹ וּמַשְׁלִים הַיָּמִים שֶׁנִּשְׁאֲרוּ מִנְּזִירוּתוֹ. וְאִם נִשְׁאֲרוּ מִנְּזִירוּתוֹ פָּחוֹת מִשְּׁלֹשִׁים מוֹנֶה שְׁלֹשִׁים אַחַר נְזִירוּת בְּנוֹ. שֶׁאֵין בֵּין תִּגְלַחַת לְתִגְלַחַת פָּחוֹת מִשְּׁלֹשִׁים יוֹם:","כֵּיצַד. הָאוֹמֵר הֲרֵינִי נָזִיר כְּשֶׁיִּהְיֶה לִי בֵּן וַהֲרֵינִי נָזִיר מֵאָה יוֹם. וְהִתְחִיל בִּנְזִירוּת שֶׁלּוֹ וְנוֹלַד לוֹ בֵּן. אִם נִשְׁאַר מִן הַמֵּאָה שֶׁנָּדַר שְׁלֹשִׁים יוֹם אוֹ יֶתֶר כְּשֶׁנּוֹלַד הַבֵּן לֹא הִפְסִיד כְּלוּם. שֶׁהֲרֵי פּוֹסֵק נְזִירוּת שֶׁלּוֹ וּמַתְחִיל וּמוֹנֶה שֶׁל בְּנוֹ וּמְגַלֵּחַ וּמֵבִיא קָרְבְּנוֹתָיו וּמַשְׁלִים הַשְּׁלֹשִׁים אוֹ יֶתֶר שֶׁנִּשְׁאֲרוּ מִנְּזִירוּתוֹ וּמְגַלֵּחַ לִנְזִירוּתוֹ. וְאִם נִשְׁאַר מִן הַמֵּאָה פָּחוֹת מִשְּׁלֹשִׁים סוֹתֵר עַד שִׁבְעִים:","כֵּיצַד. נוֹלַד הַבֵּן בְּיוֹם שְׁמוֹנִים מוֹנֶה שֶׁל בְּנוֹ וּמַשְׁלִים אֶת שֶׁל בְּנוֹ וּמְגַלֵּחַ. וּמַתְחִיל לִמְנוֹת מֵאַחַר הַתִּגְלַחַת שְׁלֹשִׁים יוֹם וְנִמְצָא מַפְסִיד מִקֹּדֶם הַוָּלָד עֲשָׂרָה יָמִים שֶׁהֵם מִיּוֹם שִׁבְעִים עַד הַוָּלָד. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָאוֹמֵר הֲרֵינִי נָזִיר לְאַחַר עֶשְׂרִים יוֹם. וְחָזַר וְאָמַר הֲרֵינִי נָזִיר מֵעָתָּה מֵאָה יוֹם. מוֹנֶה עֶשְׂרִים יוֹם וּפוֹסֵק וּמַתְחִיל לִמְנוֹת שְׁלֹשִׁים שֶׁהִיא הַנְּזִירוּת שֶׁנָּדַר לְאַחַר עֶשְׂרִים. וְאַחַר הַשְּׁלֹשִׁים מְגַלֵּחַ תִּגְלַחַת טָהֳרָה וּמֵבִיא קָרְבְּנוֹתָיו וְחוֹזֵר וּמוֹנֶה שְׁמוֹנִים יוֹם כְּדֵי לְהַשְׁלִים הַמֵּאָה שֶׁנָּדַר בַּסּוֹף וּמְגַלֵּחַ וּמֵבִיא קָרְבְּנוֹתָיו:","אָמַר הֲרֵינִי נָזִיר לְאַחַר עֶשְׂרִים יוֹם וַהֲרֵינִי נָזִיר מֵעַתָּה. מוֹנֶה שְׁלֹשִׁים יוֹם וּמְגַלֵּחַ תִּגְלַחַת טָהֳרָה וְחוֹזֵר וּמוֹנֶה שְׁלֹשִׁים יוֹם אֲחֵרִים וְהִיא הַנְּזִירוּת שֶׁנָּדַר לְאַחַר עֶשְׂרִים. שֶׁאִם תֹּאמַר מוֹנֶה עֶשְׂרִים וּפוֹסֵק מוֹנֶה שְׁלֹשִׁים וּמְגַלֵּחַ נִשְׁאֲרוּ מִנְּזִירוּת שֶׁהִתְחִיל בָּהּ עֲשָׂרָה יוֹם בִּלְבַד. וְאֵין בֵּין תִּגְלַחַת טָהֳרָה לְתִגְלַחַת טָהֳרָה לְעוֹלָם פָּחוֹת מִשְּׁלֹשִׁים יוֹם:","אָמַר הֲרֵינִי נָזִיר לְאַחַר עֶשְׂרִים יוֹם וְחָזַר וְאָמַר הֲרֵינִי נְזִיר עוֹלָם מֵעָתָּה לֹא חָלָה עָלָיו נְזִירוּת שֶׁנָּדַר בָּרִאשׁוֹנָה:","וְכֵן אִם אָמַר הֲרֵינִי נְזִיר שִׁמְשׁוֹן לְאַחַר עֶשְׂרִים יוֹם. וְחָזַר וְאָמַר הֲרֵינִי נָזִיר מֵעַתָּה. אֵינוֹ מְגַלֵּחַ לִנְזִירוּת זוֹ שֶׁנָּדַר בָּאַחֲרוֹנָה:","מִי שֶׁאָמַר הֲרֵי אֲנִי נָזִיר יוֹם אֶחָד לִפְנֵי מִיתָתִי. הֲרֵי זֶה אָסוּר לִשְׁתּוֹת יַיִן וּלְהִטָּמֵא וּלְגַלֵּחַ לְעוֹלָם:","הָאוֹמֵר הֲרֵינִי נָזִיר בַּיּוֹם שֶׁבֶּן דָּוִד בָּא בּוֹ. אִם בְּחל נָדַר הֲרֵי זֶה אָסוּר לְעוֹלָם. וְאִם בְּשַׁבָּת אוֹ בְּיוֹם טוֹב נָדַר אוֹתָהּ שַׁבָּת אוֹ אוֹתוֹ יוֹם טוֹב מֻתָּר. מִכָּאן וְאֵילָךְ אָסוּר לְעוֹלָם. שֶׁהַדָּבָר סָפֵק אִם יָבוֹא בְּשַׁבָּת אוֹ בְּיוֹם טוֹב אוֹ לֹא יָבוֹא. וְהוֹאִיל וְהוּא סָפֵק בַּיּוֹם שֶׁנָּדַר לֹא חָלָה עָלָיו נְזִירוּת שֶׁסְּפֵק נְזִירוּת לְהָקֵל. מִכָּאן וְאֵילָךְ חָלָה עָלָיו נְזִירוּת. וְשַׁבָּת הַבָּאָה שֶׁהִיא סָפֵק אֵינָהּ מַפְקַעַת נְזִירוּת שֶׁחָלָה עָלָיו:","נָזִיר שֶׁשָּׁלְמוּ יְמֵי נְזִירוּתוֹ וְלֹא גִּלֵּחַ תִּגְלַחַת טָהֳרָה הֲרֵי זֶה אָסוּר לְגַלֵּחַ וְלִשְׁתּוֹת יַיִן וּלְהִטָּמֵא לְמֵתִים כְּשֶׁהָיָה מִקֹּדֶם וְכָל דִּקְדּוּקֵי נְזִירוּת עָלָיו. וְאִם גִּלֵּחַ אוֹ שָׁתָה יַיִן אוֹ נִטְמָא לוֹקֶה:","מִי שֶׁנָּדַר בְּנָזִיר וְדִמָּה שֶׁאֵינוֹ נֵדֶר וְהָיָה נוֹהֵג הֶתֵּר בְּנִדְרוֹ וְשָׁתָה יַיִן. וּלְאַחַר זְמַן שָׁאַל לְחָכָם וְהוֹרָהוּ שֶׁהוּא נֵדֶר וְשֶׁהוּא חַיָּב בִּנְזִירוּת הֲרֵי זֶה מוֹנֶה מִשָּׁעָה שֶׁנָּדַר. וּמִדִּבְרֵי סוֹפְרִים שֶׁיִּנְהֹג אִסּוּר כַּיָּמִים שֶׁנָּהַג בָּהֶן הֶתֵּר:","כֵּיצַד. הֲרֵי שֶׁנָּדַר שְׁלֹשִׁים יוֹם וְנָהַג הֶתֵּר בְּנִדְרוֹ עֲשָׂרָה יָמִים וְנָהַג אִסּוּר עֶשְׂרִים יוֹם. וּלְאַחַר הַשְּׁלֹשִׁים שָׁאַל לְחָכָם וְאָסַר לוֹ. הֲרֵי זֶה מוֹנֶה עֲשָׂרָה יָמִים מִיּוֹם שֶׁשָּׁאַל כְּנֶגֶד הָעֲשָׂרָה שֶׁנָּהַג בָּהֶן הֶתֵּר. וְאִם שָׁתָה אוֹ גִּלֵּחַ אוֹ נִטְמָא בַּעֲשֶׂרֶת יָמִים הָאֵלּוּ מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּנְזִירוּת מוּעֶטֶת. אֲבָל בִּנְזִירוּת מְרֻבָּה דַּיּוֹ שֶׁיִּנְהֹג שְׁלֹשִׁים יוֹם בִּנְזִירוּת אַף עַל פִּי שֶׁעָבַר עַל נְזִירוּתוֹ הַמְרֻבָּה כָּל יָמָיו. וְאִם לֹא נָהַג אִסּוּר בְּעַצְמוֹ אֵין נִזְקָקִין לוֹ כְּלָל:","כָּל בֵּית דִּין שֶׁנִּזְקָקִין לָזֶה וְכַיּוֹצֵא בּוֹ וּמוֹדִיעִין לְאֵלּוּ שֶׁמְּזַלְזְלִין בִּנְדָרִים שֶׁאֵין חַיָּבִין מִן הַתּוֹרָה. אוֹ שֶׁיּוֹרוּ לָהֶן לְהָקֵל אוֹ שֶׁיִּפְתְּחוּ לָהֶן פֶּתַח. מְנַדִּין אוֹתוֹ בֵּית דִּין הַהֶדְיוֹט:","הָאִשָּׁה שֶׁנָּדְרָה בִּנְזִירוּת וְשָׁלְמוּ יְמֵי הַנְּזִירוּת וְהֵבִיאָה קָרְבְּנוֹתֶיהָ וְנִשְׁחֲטָה אַחַת מִן הַבְּהֵמוֹת וְנִזְרַק דָּמָהּ וְאַחַר כָּךְ שָׁמַע בַּעְלָהּ אַף עַל פִּי שֶׁעֲדַיִן לֹא גִּלְּחָה אֵינוֹ יָכוֹל לְהָפֵר. וְאִם קֹדֶם זְרִיקָה הֲרֵי זֶה יָפֵר. בַּמֶּה דְּבָרִים אֲמוּרִים בְּתִגְלַחַת טָהֳרָה. אֲבָל בְּתִגְלַחַת טֻמְאָה יָפֵר אַף עַל פִּי שֶׁקָּרְבוּ הַקָּרְבָּנוֹת שֶׁל תִּגְלַחַת טֻמְאָה. מִפְּנֵי שֶׁהִיא עֲדַיִן צְרִיכָה לִמְנוֹת נְזִירוּת אַחֶרֶת:"],"Mishneh Torah, Negative Mitzvot 104":["שלא ייתן שמן במנחת סוטה, שנאמר \"לא ייצוק עליו שמן\" (במדבר ה,טו)."],"Mishneh Torah, Negative Mitzvot 115":["שלא ישחוט הפסח והחמץ קיים, שנאמר \"לא תשחט על חמץ, דם זבחי\" (שמות לד,כה)."],"Mishneh Torah, Negative Mitzvot 126":["שלא להאכיל בשר הפסח לגר תושב, שנאמר \"תושב ושכיר, לא יאכל בו\" (שמות יב,מה)."],"Mishneh Torah, Negative Mitzvot 137":["שלא תאכל חללה קודש, לא תרומות ולא חזה ושוק, שנאמר \"ובת כוהן--כי תהיה, לאיש זר\" (ויקרא כב,יב)."],"Mishneh Torah, Negative Mitzvot 148":["שלא יאכל זר בשר קודשי קודשים, שנאמר \"וזר לא יאכל, כי קודש הם\" (שמות כט,לג)."],"Mishneh Torah, Negative Mitzvot 159":["שלא ייקח כוהן חללה, שנאמר \"וחללה לא ייקחו\" (ויקרא כא,ז)."],"Mishneh Torah, Negative Mitzvot 17":["שלא לאהוב המסית, שנאמר \"לא תאבה לו\" (דברים יג,ט)."],"Mishneh Torah, Negative Mitzvot 180":["שלא לאכול מתה, שנאמר \"לא תאכלו כל נבילה\" (דברים יד,כא)."],"Mishneh Torah, Negative Mitzvot 191":["שלא לאכול כרמל מתבואה חדשה, שנאמר \"וכרמל לא תאכלו\" (ויקרא כג,יד)."],"Mishneh Torah, Negative Mitzvot 201":["שלא יימצא חמץ, שנאמר \"שאור, לא יימצא בבתיכם\" (שמות יב,יט)."],"Mishneh Torah, Negative Mitzvot 212":["שלא לבצור עוללות הכרם, שנאמר \"וכרמך לא תעולל\" (ויקרא יט,י)."],"Mishneh Torah, Negative Mitzvot 223":["שלא לאסוף פירות האילן בשביעית כדרך שאוספין בכל שנה ושנה, שנאמר \"ואת עינבי נזיריך לא תבצור\" (ויקרא כה,ה)."],"Mishneh Torah, Negative Mitzvot 234":["שלא יתבע העני בחובו כשיידע שהוא עני, ולא יצר לו, שנאמר \"לא תהיה לו, כנושה\" (שמות כב,כד)."],"Mishneh Torah, Negative Mitzvot 245":["שלא לגזול, שנאמר \"לא תגזול\" (ויקרא יט,יג)."],"Mishneh Torah, Negative Mitzvot 256":["שלא לענות יתום ואלמנה, שנאמר \"כָּל אַלְמָנָה וְיָתוֹם לֹא תְעַנּוּן\" (שמות כב, כא)."],"Mishneh Torah, Negative Mitzvot 267":["שלא יאכל השכיר שלא בשעת גמר מלאכה מן המחובר שהוא עושה בו, שנאמר \"וְחֶרְמֵשׁ לֹא תָנִיף\" (דברים כג, כו)."],"Mishneh Torah, Negative Mitzvot 278":["שלא להטות משפט אדם חוטא, שנאמר \"לֹא תַטֶּה מִשְׁפַּט אֶבְיֹנְךָ\" (שמות כג, ו); למדו מפי השמועה, שזה אביון במצוות."],"Mishneh Torah, Negative Mitzvot 289":["שלא להרוג נקי, שנאמר \"לֹא תִּרְצָח\" (שמות כ, יב; דברים ה, טז)."],"Mishneh Torah, Negative Mitzvot 3":["שלא לעשות עבודה זרה ואפילו לאחרים, שנאמר \"ואלוהי מסכה, לא תעשו לכם\" (ויקרא יט,ד)."],"Mishneh Torah, Negative Mitzvot 31":["שלא לקסום, שנאמר \"לא יימצא בך . . . קוסם קסמים\" (דברים יח,י)."],"Mishneh Torah, Negative Mitzvot 320":["שלא לעשות מלאכה בשבת, שנאמר \"לא תעשה כל מלאכה\" (שמות כ,ט; דברים ה,יג)."],"Mishneh Torah, Negative Mitzvot 331":["שלא לגלות ערוות אשת אב, שנאמר \"ערוות אשת אביך, לא תגלה\" (ויקרא יח,ח)."],"Mishneh Torah, Negative Mitzvot 342":["שלא לגלות ערוות אשת אחי האב, שנאמר \"אל אשתו לא תקרב, דודתך היא\" (ויקרא יח,יד)."],"Mishneh Torah, Negative Mitzvot 353":["שלא ליקרב לעריות בדברים המביאין לידי גילוי ערווה, כגון חיבוק ונישוק ורמיזה וקפיצה, שנאמר \"אל כל שאר בשרו, לא תקרבו לגלות ערווה\" (ויקרא יח,ו); מפי השמועה למדו שזו אזהרה לקריבה המביאה לידי גילוי ערווה."],"Mishneh Torah, Negative Mitzvot 364":["שלא ירבה המלך נשים, שנאמר \"לא ירבה לו נשים\" (דברים יז,יז)."],"Mishneh Torah, Negative Mitzvot 46":["שלא לשכון בארץ מצריים לעולם, שנאמר \"לא תוסיפון לשוב בדרך הזה, עוד\" (דברים יז,טז)."],"Mishneh Torah, Negative Mitzvot 57":["שלא להשחית אילני מאכל, וכן כל שיש בו השחתה אסור, שנאמר \"לא תשחית את עצה\" (דברים כ,יט)."],"Mishneh Torah, Negative Mitzvot 68":["שלא יכנס כהן להיכל בכל עת, שנאמר \"וְאַל יָבֹא בְּכָל עֵת אֶל הַקֹדֶשׁ\" (ויקרא טז, ב)."],"Mishneh Torah, Negative Mitzvot 79":["שלא לבנות אבני מזבח גזית, שנאמר \"לֹא תִבְנֶה אֶתְהֶן גָּזִית\" (שמות כ, כא)."],"Mishneh Torah, Negative Mitzvot 9":["שלא לעשות מעשה יידעוני, שנאמר \"ואל היידעונים\" (ויקרא יט,לא)."],"Mishneh Torah, Neighbors 10":["מַרְחִיקִין אֶת הָאִילָן מִן הָעִיר עֶשְׂרִים וְחָמֵשׁ אַמָּה. וּבֶחָרוּב וּבַשִּׁקְמָה חֲמִשִּׁים אַמָּה. מִפְּנֵי נוֹיֵי הָעִיר. וְכָל אִילָן הַנִּמְצָא קָרוֹב לָעִיר פָּחוֹת מִזֶּה קוֹצְצִין אוֹתוֹ. וְאִם הָאִילָן קָדַם נוֹתְנִין לוֹ בְּנֵי הָעִיר דָּמָיו. וְאִם הָיָה הַדָּבָר סָפֵק וְלֹא נוֹדַע אֵי זֶה מֵהֶם קָדַם אֵין לְבַעַל הָאִילָן דָּמִים אֶלָּא נוֹטֵל עֵצָיו וְהוֹלֵךְ:","מַרְחִיקִין גֹּרֶן קָבוּעַ מִן הָעִיר חֲמִשִּׁים אַמָּה כְּדֵי שֶׁלֹּא יוֹלִיךְ הָרוּחַ הַתֶּבֶן בְּעֵת שֶׁזּוֹרֶה וְיַזִּיק לִבְנֵי הָעִיר. וְכֵן לֹא יַעֲשֶׂה אָדָם גֹּרֶן קָבוּעַ בְּתוֹךְ שֶׁלּוֹ אֶלָּא אִם כֵּן הָיָה לוֹ חֲמִשִּׁים אַמָּה לְכָל רוּחַ כְּדֵי שֶׁלֹּא יַזִּיק הַתֶּבֶן לִנְטִיעַת חֲבֵרוֹ אוֹ לְנִירוֹ:","מַרְחִיקִין אֶת הַנְּבֵלוֹת וְאֶת הַקְּבָרוֹת וְאֶת הַבּוּרְסְקִי מִן הָעִיר חֲמִשִּׁים אַמָּה:","וְאֵין עוֹשִׂין בּוּרְסְקִי אֶלָּא לְמִזְרַח הָעִיר מִפְּנֵי שֶׁרוּחַ מִזְרָחִית חַמָּה וּמְמַעֶטֶת הֶזֵּק רֵיחַ עִבּוּד הָעוֹרוֹת:","מִי שֶׁבָּא לַעֲשׂוֹת מִשְׁרָה שֶׁל פִּשְׁתָּן בְּצַד יָרָק שֶׁל חֲבֵרוֹ שֶׁהֲרֵי מֵי הַמִּשְׁרָה נִבְלָעִין בָּאָרֶץ וְהוֹלְכִין וּמַפְסִידִין אֶת הַיָּרָק. אוֹ שֶׁנָּטַע כְּרֵישִׁין קָרוֹב מִן הַבְּצָלִים שֶׁל חֲבֵרוֹ שֶׁהֵן מְפִיגִין טַעְמָן. אוֹ שֶׁנָּטַע חַרְדָּל בְּצַד כַּוֶּרֶת דְּבוֹרִים שֶׁהֲרֵי הַדְּבוֹרִים אוֹכְלִין הֶעָלִין וּמַפְסִידִין אֶת הַדְּבַשׁ וְכָל אֵלּוּ וְכַיּוֹצֵא בָּהֶן. אֵין צָרִיךְ לְהַרְחִיק בִּכְדֵי שֶׁלֹּא יַזִּיק וְעַל הַנִּזָּק לְהַרְחִיק אֶת עַצְמוֹ אִם יִרְצֶה עַד שֶׁלֹּא יַגִּיעַ לוֹ הַנֵּזֶק. שֶׁזֶּה בְּתוֹךְ שֶׁלּוֹ הוּא עוֹשֶׂה וְהַנֵּזֶק בָּא לַחֲבֵרוֹ מֵאֵלָיו. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאֵינוֹ מַרְחִיק כְּשֶׁהָיָה הַנֶּזֶק בָּא מֵאֵלָיו אַחַר שֶׁיִּפָּסְקוּ מַעֲשָׂיו שֶׁל מַזִּיק. אֲבָל אִם הָיוּ מַעֲשָׂיו שֶׁל זֶה שֶׁעוֹשֶׂה בִּרְשׁוּתוֹ מַזִּיקִין אֶת חֲבֵרוֹ בִּשְׁעַת עֲשִׂיָּתוֹ הֲרֵי זֶה כְּמִי שֶׁמַּזִּיק בְּיָדוֹ. הָא לְמָה זֶה דּוֹמֶה לְמִי שֶׁעוֹמֵד בִּרְשׁוּתוֹ וְיוֹרֶה חִצִּים לַחֲצַר חֲבֵרוֹ וְאָמַר בִּרְשׁוּתִי אֲנִי עוֹשֶׂה שֶׁמּוֹנְעִין אוֹתוֹ. וְכֵן כָּל הַרְחָקוֹת הָאֲמוּרוֹת לְמַעְלָה בְּעִנְיָן זֶה אִם לֹא הִרְחִיקוֹ הֲרֵי זֶה כְּמִי שֶׁהִזִּיק בְּחִצָּיו. לְפִיכָךְ צָרִיךְ שֶׁיַּרְחִיק מִשְׁרָה מִן הַיָּרָק וּכְרֵישִׁין מִן הַבְּצָלִים וְחַרְדָּל מִן הַדְּבוֹרִים שְׁלֹשָׁה טְפָחִים אוֹ יֶתֶר מְעַט כְּדֵי שֶׁלֹּא יִהְיֶה הֶזֵּק בַּיָּדַיִם. אֲבָל לְהַרְחִיק עַד שֶׁלֹּא יָבוֹא הַנֶּזֶק מֵאֵלָיו אֵין צָרִיךְ:","בַּעַל הָעֲלִיָּה שֶׁהָיָה שׁוֹפֵךְ מַיִם וְהֵן יוֹרְדִין עַל חֶדֶר לְמַטָּה. אִם הָיְתָה שָׁם מַעֲזִיבָה שֶׁהַמַּיִם כָּלִים בָּהּ בְּעֵת שְׁפִיכָה וְאַחַר שֶׁיַּפְסִיק עֶלְיוֹן מִלִּשְׁפֹּךְ יִתְבַּלַּע הַמַּיִם וְיֵרְדוּ וְיִנְטְפוּ עַל הַתַּחְתּוֹן צָרִיךְ הַתַּחְתּוֹן לְתַקֵּן וּלְהַרְחִיק מִן עַצְמוֹ הַנֵּזֶק. וְאִם אֵין שָׁם מַעֲזִיבָה אֶלָּא כְּשֶׁיִּשְׁפֹּךְ יֵרְדוּ הַמַּיִם מִיָּד הֲרֵי זֶה כְּמַזִּיק בְּחִצָּיו וְהָעֶלְיוֹן מְתַקֵּן אוֹ יִמָּנַע מִלִּשְׁפֹּךְ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁהָיָה לוֹ אִילָן בְּתוֹךְ שָׂדֵהוּ קָרוֹב לְבוֹר חֲבֵרוֹ אֵין בַּעַל הַבּוֹר יָכוֹל לְעַכֵּב עָלָיו וְלוֹמַר לוֹ הֲרֵי שָׁרְשֵׁי הָאִילָן נִכְנָסִים לַבּוֹר שֶׁלִּי וּמַפְסִידִין אוֹתוֹ שֶׁזֶּה נֵזֶק הַבָּא מֵאֵלָיו הוּא לְאַחַר זְמַן וּבְעֵת שֶׁנָּטַע אֵינוֹ מַזִּיקוֹ וּכְשֵׁם שֶׁזֶּה חוֹפֵר בְּתוֹךְ שֶׁלּוֹ כָּךְ זֶה נוֹטֵעַ בְּתוֹךְ שֶׁלּוֹ. וְכֵן רְאוּבֵן שֶׁחָפַר בּוֹר וְיָרַד וּמָצָא שָׁרְשֵׁי אִילָן שֶׁל שִׁמְעוֹן בְּתוֹךְ שָׂדֵהוּ קוֹצֵץ וְחוֹפֵר וְהָעֵצִים שֶׁלּוֹ. וְאִם הָיָה קָרוֹב לְאִילַן שִׁמְעוֹן בְּתוֹךְ שֵׁשׁ עֶשְׂרֵה אַמָּה הַשָּׁרָשִׁים שֶׁל שִׁמְעוֹן וְקוֹצְצָן וְנוֹתְנָן לוֹ. וְאִם אֵין צָרִיךְ לַחְפֹּר בּוֹר וְיָצְאוּ הַשָּׁרָשִׁים שֶׁל שִׁמְעוֹן בְּתוֹךְ שָׂדֵהוּ הֲרֵי הוּא מַעֲמִיק שְׁלֹשָׁה טְפָחִים כְּדֵי שֶׁלֹּא יְעַכֵּב הַמַּחֲרֵשָׁה וְכָל שֹׁרֶשׁ שֶׁמָּצָא בְּתוֹךְ שְׁלֹשָׁה טְפָחִים קוֹצְצוֹ וְאֵינוֹ חוֹשֵׁשׁ שֶׁמָּא יִבַשׁ הָאִילָן שֶׁל חֲבֵרוֹ שֶׁזֶּה בְּתוֹךְ שֶׁלּוֹ הוּא חוֹפֵר:","מִי שֶׁהָיְתָה שְׂדֵה חֲבֵרוֹ נְטוּעָה גְּפָנִים אוֹ שְׁאָר אִילָנוֹת וּבָא הוּא לִנְטֹעַ בְּתוֹךְ שָׂדֵהוּ גְּפָנִים בְּצַד גְּפָנִים אוֹ אִילָנוֹת בְּצַד אִילָנוֹת צָרִיךְ לְהַרְחִיק אַרְבַּע אַמּוֹת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּאֶרֶץ יִשְׂרָאֵל. אֲבָל בְּחוּצָה לָאָרֶץ מַרְחִיק בֵּין גְּפָנִים לִגְפָנִים שְׁתֵּי אַמּוֹת. וּבֵין גְּפָנִים לִשְׁאָר אִילָנוֹת אוֹ בֵּין אִילָנוֹת לְאִילָנוֹת אַרְבַּע אַמּוֹת בְּכָל מָקוֹם. הָיָה גָּדֵר בֵּינְתַיִם זֶה סוֹמֵךְ לַגָּדֵר וְזֶה סוֹמֵךְ לַגָּדֵר בְּכָל מָקוֹם. מִי שֶׁהָיָה אִילַן חֲבֵרוֹ נוֹטֶה לְתוֹךְ שָׂדֵהוּ קוֹצֵץ כִּמְלֹא מַרְדֵּעַ עַל גַּבֵּי הַמַּחֲרֵשָׁה. וּבְחָרוּב וּבְשִׁקְמָה קוֹצֵץ כָּל הַנּוֹטֶה עַד שֶׁיִּהְיֶה שָׁקוּל כְּנֶגֶד הַמֵּצַר. וְכֵן אִם הָיָה נוֹטֶה עַל בֵּית הַשְּׁלָחִין שֶׁל חֲבֵרוֹ אוֹ עַל בֵּית הָאִילָן קוֹצֵץ אֶת כָּל הַנּוֹטֶה עַד שֶׁיִּהְיֶה שָׁקוּל כְּנֶגֶד הַמֵּצַר:"],"Mishneh Torah, Neighbors 9":["לֹא יַחְפֹּר אָדָם בּוֹר וְלֹא שִׁיחַ וְלֹא מְעָרָה וְלֹא יָבִיא אַמַּת הַמַּיִם וְלֹא יַעֲשֶׂה בְּרֵכַת הַמַּיִם לִשְׁרוֹת בָּהּ בְּגָדִים לְכַבֵּס בְּצַד כָּתְלוֹ שֶׁל חֲבֵרוֹ אֶלָּא אִם כֵּן הִרְחִיק מִכֹּתֶל חֲבֵרוֹ שְׁלֹשָׁה טְפָחִים. וִיסַיֵּד בְּסִיד לְכֹתֶל בּוֹר זֶה אוֹ מִקְוֵה הַמַּיִם זֶה אוֹ כֹּתֶל הָאַמָּה מִצַּד חֲבֵרוֹ כְּדֵי שֶׁלֹּא יַבְלִיעוּ הַמַּיִם וְיַזִּיקוּ כֹּתֶל חֲבֵרוֹ:","מַרְחִיקִין אֶת הַגֶּפֶת וְאֶת הַזֶּפֶת וְאֶת הַמֶּלַח וְאֶת הַסִּיד וְאֶת הַסְּלָעִים מִכָּתְלוֹ שֶׁל חֲבֵרוֹ שְׁלֹשָׁה טְפָחִים אוֹ סָד בְּסִיד. וּמַרְחִיקִין אֶת הַזְּרָעִים וְאֶת הַחֲרִישָׁה וְאֶת הַגּוּמָא שֶׁמִּתְקַבֵּץ בָּהּ מֵימֵי רַגְלַיִם מִן הַכֹּתֶל שְׁלֹשָׁה טְפָחִים:","מַרְחִיקִין אֶת הָרֵחָיִם [מִן הַכֹּתֶל] שְׁלֹשָׁה טְפָחִים מִן הָרֵחָיִם הַתַּחְתּוֹנָה שֶׁהֵן אַרְבָּעָה מִן הָעֶלְיוֹנָה כְּדֵי שֶׁלֹּא יָנִיד אוֹתוֹ אוֹ כְּדֵי שֶׁלֹּא יְבַהֲלֶנּוּ בְּקוֹל הָרֵחָיִם:","מַרְחִיקִין אֶת הַתַּנּוּר מִן הַכֹּתֶל שְׁלֹשָׁה טְפָחִים מִקַּרְקָעִיתוֹ שֶׁהֵן אַרְבָּעָה מִשְּׂפָתוֹ כְּדֵי שֶׁלֹּא יֵחַם הַכֹּתֶל:","אֶבֶן שֶׁהַכּוֹבֵס מַכֶּה בְּגָדִים עָלֶיהָ עַד שֶׁיִּתְלַבְּנוּ צָרִיךְ לְהַרְחִיק אוֹתָהּ אַרְבַּע אַמּוֹת מִכֹּתֶל שֶׁל חֲבֵרוֹ שֶׁבְּעֵת שֶׁהַכּוֹבֵס מַכֶּה עָלֶיהָ הַמַּיִם נִתָּזִין וּמַזִּיקִין לַכֹּתֶל:","לֹא יַשְׁתִּין אָדָם מַיִם בְּצַד כָּתְלוֹ שֶׁל חֲבֵרוֹ אֶלָּא אִם כֵּן הִרְחִיק מִמֶּנּוּ שְׁלֹשָׁה טְפָחִים. בַּמֶּה דְּבָרִים אֲמוּרִים בְּכֹתֶל לְבֵנִים. אֲבָל בְּכֹתֶל אֲבָנִים יַרְחִיק טֶפַח. וְאִם הָיוּ הָאֲבָנִים צְחִיחַ סֶלַע מַשְׁתִּין בְּצִדּוֹ בְּלֹא הַרְחָקָה:","מַרְחִיקִין אֶת הַסֻּלָּם מֵהַשּׁוֹבָךְ אַרְבַּע אַמּוֹת כְּדֵי שֶׁלֹּא תִּקְפֹּץ הַנְּמִיָּה בְּעֵת שֶׁמֵּנִיחַ הַסֻּלָּם וְתַעֲלֶה לַשּׁוֹבָךְ וְתֹאכַל הַגּוֹזָלוֹת:","וּמַרְחִיקִין אֶת הַכֹּתֶל מִן הַמַּזְחֵילָה שֶׁל חֲבֵרוֹ אַרְבַּע אַמּוֹת כְּדֵי שֶׁיִּהְיֶה מָקוֹם לְבַעַל הַמַּזְחֵילָה לִזְקֹף סֻלָּם וּלְתַקֵּן מַזְחֵילָה שֶׁלּוֹ הוֹאִיל וְהֶחֱזִיק בָּהּ:","רְאוּבֵן שֶׁהָיָה כָּתְלוֹ סָמוּךְ לְכֹתֶל שִׁמְעוֹן כְּמִין גַּם וּבָא רְאוּבֵן לַעֲשׂוֹת כֹּתֶל שֵׁנִי כְּנֶגֶד כֹּתֶל שִׁמְעוֹן עַד שֶׁיַּעֲשֶׂה הַשְּׁלֹשָׁה כְּתָלִין כְּמִין בֵּי\"ת הֲרֵי שִׁמְעוֹן מְעַכֵּב עָלָיו עַד שֶׁיַּרְחִיק מִכְּנֶגְדּוֹ אַרְבַּע אַמּוֹת כְּדֵי שֶׁיִּהְיֶה הַמָּקוֹם בֵּין שְׁנֵי הַכְּתָלִים רָחָב כְּדֵי שֶׁיָּדוּשׁוּ בּוֹ רַבִּים וְתִתְחַזֵּק הָאָרֶץ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּכֹתֶל גִּנָּה אוֹ בְּכֹתֶל חָצֵר בְּעִיר חֲדָשָׁה. אֲבָל בְּעִיר יְשָׁנָה כְּבָר נִתְחַזְּקָה וּבוֹנֶה כְּנֶגְדּוֹ בְּלֹא הַרְחָקָה. וְכֵן אִם לֹא הָיָה בְּאֹרֶךְ כֹּתֶל שִׁמְעוֹן שֶׁבּוֹנֶה כְּנֶגְדּוֹ אַרְבַּע אַמּוֹת אֵינוֹ מַרְחִיק אַף עַל פִּי שֶׁמּוֹנֵעַ הָרֶגֶל מִלְּהַלֵּךְ שָׁם. שֶׁהַכֹּתֶל שֶׁהוּא פָּחוֹת מֵאַרְבַּע אַמּוֹת אֵינוֹ צָרִיךְ חִזּוּק הָאָרֶץ:","מִי שֶׁבָּא לַחְפֹּר בּוֹר בְּסוֹף שָׂדֵהוּ לִסְמֹךְ לְמֵצַר חֲבֵרוֹ אִם שְׂדֵה חֲבֵרוֹ אֵינוֹ עָשׂוּי לְבוֹרוֹת סוֹמֵךְ וְאֵינוֹ יָכוֹל לִמְחוֹת בְּיָדוֹ. וְאִם יִמָּלֵךְ חֲבֵרוֹ לַחְפֹּר בּוֹר בְּצִדּוֹ צָרִיךְ לְהַרְחִיק מִן כֹּתֶל הַבּוֹר שְׁלֹשָׁה טְפָחִים עַד שֶׁיְּהֵא בֵּין חֲלַל שְׁתֵּי הַבּוֹרוֹת שִׁשָּׁה טְפָחִים. וְאִם הָיְתָה שְׂדֵה חֲבֵרוֹ עֲשׂוּיָה לְבוֹרוֹת אֵינוֹ סוֹמֵךְ עַד שֶׁיַּרְחִיק מִן הַמֵּצַר שְׁלֹשָׁה טְפָחִים וְיַחְפֹּר. וּכְשֶׁיָּבוֹא חֲבֵרוֹ לַחְפֹּר יַרְחִיק גַּם הוּא שְׁלֹשָׁה טְפָחִים בְּתוֹךְ שָׂדֵהוּ וְיַחְפֹּר:","הַבַּיִת וְהָעֲלִיָּה שֶׁל שְׁנַיִם לֹא יַעֲשֶׂה בַּעַל הַבַּיִת תַּנּוּר בְּתוֹךְ בֵּיתוֹ אֶלָּא אִם כֵּן יֵשׁ לוֹ עַל גַּבָּיו גֹּבַהּ אַרְבַּע אַמּוֹת. וְכֵן לֹא יַעֲמִיד בַּעַל הָעֲלִיָּה תַּנּוּר עַד שֶׁיִּהְיוּ תַּחְתָּיו מַעֲזִיבָה שְׁלֹשָׁה טְפָחִים וּבְכִירָה טֶפַח. וְאִם תַּנּוּר שֶׁל נַחְתּוֹמִים הוּא צָרִיךְ שֶׁיְּהֵא תַּחְתָּיו אַרְבָּעָה טְפָחִים וּבְכִירָה שֶׁל נַחְתּוֹמִין שְׁלֹשָׁה טְפָחִים. וְאַף עַל פִּי שֶׁהִרְחִיק הַשִּׁעוּר אִם יָצָאת הָאֵשׁ וְהִזִּיקָה מְשַׁלֵּם מַה שֶּׁהִזִּיק כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","מִי שֶׁהָיְתָה לוֹ חֲנוּת תַּחַת אוֹצַר חֲבֵרוֹ לֹא יַעֲשֶׂה בָּהּ לֹא נַחְתּוֹם וְלֹא צַבָּע וְלֹא רֶפֶת בָּקָר וְלֹא יַכְנִיס שָׁם אַסְפַּסְתָּא וְכַיּוֹצֵא בָּהֶן מִדְּבָרִים שֶׁעוֹלֶה מֵהֶם הֶבֶל חַם הַרְבֵּה מִפְּנֵי שֶׁהַחֹם מַפְסִיד פֵּרוֹת הָאוֹצָר. לְפִיכָךְ אִם הָיָה אוֹצַר יַיִן בְּאֶרֶץ יִשְׂרָאֵל שֶׁאֵין הַחֹם מַפְסִידוֹ הֲרֵי זֶה עוֹשֶׂה בַּחֲנוּתוֹ כָּל מְלֶאכֶת אֵשׁ שֶׁיִּרְצֶה. אֲבָל לֹא יַעֲשֶׂה רֶפֶת בָּקָר מִפְּנֵי שֶׁמַּפְסִיד רֵיחַ הַיַּיִן. וְאִם הֻחְזְקָה הַחֲנוּת בַּתְּחִלָּה לְרֶפֶת אוֹ לְנַחְתּוֹם וְכַיּוֹצֵא בּוֹ וְאַחַר כָּךְ רָצָה בַּעַל הָעֲלִיָּה לַעֲשׂוֹת עֲלִיָּתוֹ אוֹצַר אֵינוֹ יָכוֹל לִמְחוֹת בְּיָדוֹ:","כִּבֵּד בַּעַל הַבַּיִת וְרִבֵּץ עֲלִיָּתוֹ אוֹ שֶׁרִבָּה בָּהּ חַלּוֹנוֹת כְּדֵי לַעֲשׂוֹת בּוֹ אוֹצָר וְקָדַם זֶה וְעָשָׂה תַּנּוּר קֹדֶם שֶׁיַּכְנִיס פֵּרוֹת לָאוֹצָר. אוֹ שֶׁהִתְחִיל לֶאֱצֹר שֻׁמְשְׁמִין אוֹ רִמּוֹנִים אוֹ תְּמָרִים וְכַיּוֹצֵא בָּהֶן וְקָדַם זֶה וְעָשָׂה הַתַּנּוּר קֹדֶם שֶׁאָצַר הַחִטִּין. אוֹ שֶׁעָשָׂה בַּעַל הַחֲנוּת מְחִילָה עַל גַּבָּהּ לְהַבְדִּיל בֵּין הַחֲנוּת וּבֵין הָאוֹצָר. בְּכָל אֵלּוּ בַּעַל הָאוֹצָר מְעַכֵּב עָלָיו. וְאִם עָבַר וְעָשָׂה תַּנּוּר וְכַיּוֹצֵא בּוֹ אֵין בַּעַל הָאוֹצָר יָכוֹל לְהָסִיר הַתַּנּוּר בְּכָל אֵלּוּ:"],"Mishneh Torah, Oaths 9":["הַתּוֹבֵעַ עֵדָיו לְהָעִיד לוֹ עֵדוּת שֶׁיִּתְחַיֵּב הַנִּתְבָּע בְּעֵדוּתָן לְבַדָּהּ לִתֵּן לְתוֹבֵעַ זֶה מָמוֹן הַמִּטַּלְטֵל. וְכָפְרוּ בְּעֵדוּתָן וְנִשְׁבְּעוּ. בֵּין שֶׁנִּשְׁבְּעוּ בְּבֵית דִּין בֵּין שֶׁנִּשְׁבְּעוּ חוּץ לְבֵית דִּין הֲרֵי אֵלּוּ חַיָּבִין מִשּׁוּם שְׁבוּעַת הָעֵדוּת. שֶׁהֲרֵי הִפְסִידוּהוּ מָמוֹן בִּכְפִירָתָם. וְכֵן אִם הִשְׁבִּיעָם הַתּוֹבֵעַ וְכָפְרוּ בּוֹ אַף עַל פִּי שֶׁלֹּא נִשְׁבְּעוּ הֵן וְלֹא עָנוּ אָמֵן אַחַר שְׁבוּעָתוֹ כֵּיוָן שֶׁכָּפְרוּ הֲרֵי אֵלּוּ חַיָּבִין. וְהוּא שֶׁיַּשְׁבִּיעֵם בְּבֵית דִּין:","אֵין הָעֵדִים חַיָּבִין בִּשְׁבוּעַת הָעֵדוּת עַד שֶׁיִּכְפְּרוּ בְּעֵדוּתָן בְּבֵית דִּין. בֵּין שֶׁנִּשְׁבְּעוּ אוֹ הִשְׁבִּיעָן בְּבֵית דִּין בֵּין שֶׁנִּשְׁבְּעוּ אוֹ הִשְׁבִּיעָן חוּץ לְבֵית דִּין. וְהַכְּפִירָה בְּבֵית דִּין בִּלְבַד. שֶׁנֶּאֱמַר (ויקרא ה א) \"אִם לֹא יַגִּיד וְנָשָׂא עֲוֹנוֹ\" מָקוֹם שֶׁיַּגִּיד וְיוֹעִיל הוּא שֶׁאִם לֹא יַגִּיד שָׁם יִתְחַיֵּב:","תְּבָעָן בְּעֵדוּת שֶׁאֵינָהּ מְחַיֶּבֶת מָמוֹן אוֹ בְּעֵדוּת קַרְקָעוֹת אוֹ עֲבָדִים אוֹ שְׁטָרוֹת וְכָפְרוּ וְנִשְׁבְּעוּ פְּטוּרִין מִשְּׁבוּעַת הָעֵדוּת. שֶׁאֵין חַיָּבִין אֶלָּא עַל כְּפִירַת עֵדוּת מָמוֹן שֶׁדּוֹמָה לְפִקָּדוֹן וּתְשׂוּמֶת יָד וְגֵזֶל וַאֲבֵדָה שֶׁפֵּרְטָן הַכָּתוּב בַּפָּרָשָׁה שֶׁהֵן מִטַּלְטְלִין שֶׁגּוּפָן מָמוֹן וּכְשֶׁיָּעִידוּ לָזֶה יִתֵּן זֶה:","וְכֵן הַמַּשְׁבִּיעַ עֵדֵי קְנָס וְכָפְרוּ פְּטוּרִין מִשְּׁבוּעַת הָעֵדוּת. מִפְּנֵי שֶׁאִם קָדַם הַנִּתְבָּע וְהוֹדָה בִּקְנָס יִפָּטֵר מִלְּשַׁלֵּם וְאַף עַל פִּי שֶׁבָּאוּ הָעֵדִים אַחַר כֵּן וְהֵעִידוּ. נִמְצְאוּ הָעֵדִים לֹא חִיְּבוּ זֶה בְּעֵדוּתָן לְבַדָּהּ אֶלָּא עֵדוּתָן עִם כְּפִירַת הַנִּתְבָּע הִיא הַמְחַיֶּבֶת אוֹתָן וְהוֹאִיל וְאִם הוֹדָה לֹא תּוֹעִיל עֵדוּתָן אִם כָּפְרוּ בָּהּ וְנִשְׁבְּעוּ פְּטוּרִין:","מַשְׁבִּיעֲכֶם אֲנִי שֶׁתָּבוֹאוּ וְתָעִידוּ לִי שֶׁיֵּשׁ לִי בְּיַד פְּלוֹנִי תַּשְׁלוּמֵי כֶּפֶל וְתַשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה וְכָפְרוּ. חַיָּבִין בִּשְׁבוּעַת הָעֵדוּת מִפְּנֵי הַקֶּרֶן שֶׁהוּא מָמוֹן לֹא מִפְּנֵי הַכֶּפֶל שֶׁהוּא קְנָס. וְכֵן אִם הִשְׁבִּיעָם שֶׁיָּעִידוּ לוֹ שֶׁאָנַס פְּלוֹנִי אוֹ פִּתָּה בִּתּוֹ וְכָפְרוּ חַיָּבִין בִּשְׁבוּעַת הָעֵדוּת מִפְּנֵי הַבֹּשֶׁת וְהַפְּגָם שֶׁאִם הוֹדָה בָּהֶם הַנִּתְבָּע מְשַׁלֵּם לֹא מִפְּנֵי הַקְּנָס. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֵין הָעֵדִים חַיָּבִין בִּשְׁבוּעַת הָעֵדוּת עַד שֶׁיִּכְפְּרוּ וְיִשָּׁבְעוּ אַחַר תְּבִיעַת בַּעַל דִּין עַצְמוֹ אוֹ שְׁלוּחוֹ. אֲבָל אִם קָדְמוּ וְנִשְׁבְּעוּ קֹדֶם שֶׁיִּתְבָּעֵם פְּטוּרִין מִשְּׁבוּעַת הָעֵדוּת:","כֵּיצַד. רָאוּ הַתּוֹבֵעַ הוֹלֵךְ אַחֲרֵיהֶן אָמְרוּ לוֹ לָמָּה אַתָּה בָּא אַחֲרֵינוּ שְׁבוּעָה שֶׁאֵין אָנוּ יוֹדְעִין לְךָ עֵדוּת הֲרֵי אֵלּוּ פְּטוּרִין מִשְּׁבוּעַת הָעֵדוּת מִפְּנֵי שֶׁלֹּא תְּבָעָן הַתּוֹבֵעַ אֶלָּא הֵם קָדְמוּ וְנִשְׁבְּעוּ בִּתְבִיעַת עַצְמָן. וְכֵן אִם הִשְׁבִּיעָם הַנִּתְבָּע שֶׁאִם תֵּדְעוּ לָזֶה שֶׁתּוֹבֵעַ אוֹתוֹ עֵדוּת שֶׁתָּבוֹאוּ וְתָעִידוּ לוֹ וְכָפְרוּ הֲרֵי אֵלּוּ פְּטוּרִין מִשְּׁבוּעַת הָעֵדוּת עַד שֶׁיַּשְׁבִּיעֵם הַתּוֹבֵעַ. וְאֵין צָרִיךְ לוֹמַר אִם הִשְׁבִּיעָם שֶׁיָּבוֹאוּ וְיָעִידוּ שֶׁיֵּשׁ לִפְלוֹנִי בְּיַד פְּלוֹנִי מָמוֹן וְכָפְרוּ שֶׁהֵן פְּטוּרִין שֶׁאֵין זֶה הַתּוֹבֵעַ בַּעַל דִּין עַצְמוֹ. וְכֵן אִם קָדְמָה שְׁבוּעָה לָעֵדוּת הֲרֵי אֵלּוּ פְּטוּרִין מִשְּׁבוּעַת הָעֵדוּת שֶׁנֶּאֱמַר (ויקרא ה א) \"וְשָׁמְעָה קוֹל אָלָה וְהוּא עֵד\". שֶׁקָּדְמָה עֵדוּת לִשְׁבוּעָה לֹא שֶׁקָּדְמָה שְׁבוּעָה לְעֵדוּת:","כֵּיצַד. מַשְׁבִּיעַ אֲנִי עֲלֵיכֶם כְּשֶׁתֵּדְעוּ לִי עֵדוּת שֶׁתָּבוֹאוּ וּתְעִידוּנִי וְאָמְרוּ אָמֵן וְיָדְעוּ לוֹ עֵדוּת אַחַר כֵּן וּתְבָעָם לְהָעִיד וְכָפְרוּ בּוֹ הֲרֵי אֵלּוּ פְּטוּרִין מִשְּׁבוּעַת הָעֵדוּת:","אֵין הָעֵדִים חַיָּבִים בִּשְׁבוּעַת הָעֵדוּת עַד שֶׁיְּיַחֵד אוֹתָם הַתּוֹבֵעַ וְיַשְׁבִּיעֵם אוֹ יִשָּׁבְעוּ. כֵּיצַד. עָמַד בְּבֵית הַכְּנֶסֶת וְאָמַר מַשְׁבִּיעַ אֲנִי כָּל מִי שֶׁיֵּדַע לִי עֵדוּת שֶׁיָּבוֹא וְיָעִיד לִי וְעָנוּ כֻּלָּם אָמֵן וְעֵדָיו בִּכְלָלָם וְאַחַר כָּךְ תָּבַע עֵדָיו וְכָפְרוּ בּוֹ הֲרֵי אֵלּוּ פְּטוּרִין מִשְּׁבוּעַת הָעֵדוּת. מִפְּנֵי שֶׁלֹּא יִחֵד עֵדָיו בִּשְׁבוּעָה בִּפְנֵי עַצְמָן. אֲבָל אִם אָמַר מַשְׁבִּיעַ אֲנִי כָּל הָעוֹמְדִים כָּאן שֶׁאִם יֵדְעוּ לִי עֵדוּת שֶׁיָּבוֹאוּ וְיָעִידוּ לִי וְהָיוּ עֵדָיו בִּכְלָלָם וְכָפְרוּ הֲרֵי אֵלּוּ חַיָּבִין בִּשְׁבוּעַת הָעֵדוּת שֶׁהֲרֵי יִחֲדָם בִּכְלַל אֲחֵרִים:","וְכֵן אִם אָמַר לָעֵדִים בּוֹאוּ וְהָעִידוּ לִי שֶׁיֵּשׁ לִי מָנֶה בְּיַד פְּלוֹנִי. וְאַחַר כָּךְ עָמַד בְּבֵית הַכְּנֶסֶת וְהִשְׁבִּיעַ כָּל מִי שֶׁיּוֹדֵעַ לוֹ עֵדוּת יָבוֹא וְיָעִיד וְלֹא בָּאוּ וְלֹא הֵעִידוּ הֲרֵי אֵלּוּ חַיָּבִין. שֶׁהֲרֵי תְּבָעָן תְּחִלָּה. וְהוּא שֶׁיִּהְיוּ אָז בְּבֵית הַכְּנֶסֶת וְיִהְיֶה שָׁם בֵּית דִּין. אֲבָל אִם לֹא הָיוּ בִּפְנֵי בֵּית דִּין אִם עָנוּ אָמֵן חַיָּבִין בִּשְׁבוּעַת הָעֵדוּת כְּשֶׁיִּכְפְּרוּ בְּעֵדוּתָן בְּבֵית דִּין וְאִם לֹא עָנוּ אָמֵן אֵינָן חַיָּבִין:","אֶחָד הַמַּשְׁבִּיעַ עֵדָיו בִּשְׁבוּעָה. אוֹ שֶׁאָמַר לָהֶן מְצַוֶּה אֲנִי עֲלֵיכֶם בִּשְׁבוּעָה אוֹסֶרְכֶם אֲנִי בִּשְׁבוּעָה הֲרֵי אֵלּוּ חַיָּבִין. וְהוּא שֶׁיַּשְׁבִּיעֵם בְּשֵׁם אוֹ בְּכִנּוּי מִן הַכִּנּוּיִים כְּמוֹ שֶׁבֵּאַרְנוּ:","וְאֵין הָעֵדִים חַיָּבִין עַד שֶׁיַּשְׁבִּיעֵם בְּלָשׁוֹן שֶׁהֵם מַכִּירִין אוֹתָהּ:","הִנֵּה לָמַדְתָּ שֶׁאֵין הָעֵדִים חַיָּבִין בִּשְׁבוּעַת הָעֵדוּת אֶלָּא עַל פִּי עֲשָׂרָה דְּבָרִים. וְאֵלּוּ הֵן. שֶׁיִּתְבָּעֵם הַתּוֹבֵעַ. וְשֶׁתִּהְיֶה עֵדוּת מָמוֹן. וְשֶׁיִּהְיֶה מָמוֹן הַמִּטַּלְטֵל. וְשֶׁיִּתְחַיֵּב הַנִּתְבָּע לְשַׁלֵּם בְּעֵדוּתָן לְבַד אִם הֵעִידוּ. וְשֶׁיִּכְפְּרוּ אַחַר שֶׁתְּבָעָן הַתּוֹבֵעַ. וְשֶׁיִּכְפְּרוּ בְּבֵית דִּין. וְשֶׁתִּהְיֶה שָׁם שְׁבוּעָה בְּשֵׁם אוֹ בְּכִנּוּי. וְשֶׁתִּקְדַּם יְדִיעַת הָעֵדוּת לַשְּׁבוּעָה. וְשֶׁיְּיַחֵד עֵדָיו בְּעֵת הַשְּׁבוּעָה אוֹ בְּעֵת הַתְּבִיעָה. וְשֶׁתִּהְיֶה הַשְּׁבוּעָה בְּלָשׁוֹן שֶׁהֵן מַכִּירִין אוֹתָהּ:","כָּל מָקוֹם שֶׁאָמַרְנוּ פָּטוּר. פָּטוּר מִשְּׁבוּעַת הָעֵדוּת אֲבָל חַיָּב בִּשְׁבוּעַת בִּטּוּי וְהוּא שֶׁנִּשְׁבַּע אוֹ שֶׁעָנָה אָמֵן אִם הִשְׁבִּיעוֹ אַחֵר שֶׁהֲרֵי נִשְׁבַּע עַל שֶׁקֶר. אֲבָל הַמְחֻיָּב בִּשְׁבוּעַת הָעֵדוּת אַף עַל פִּי שֶׁהוּא נִשְׁבַּע עַל שֶׁקֶר וְאַף עַל פִּי שֶׁהוּא מֵזִיד אֵינוֹ חַיָּב מִשּׁוּם שְׁבוּעַת בִּטּוּי אֶלָּא מִשּׁוּם שְׁבוּעַת הָעֵדוּת בִּלְבַד. שֶׁהֲרֵי הַכָּתוּב הוֹצִיא שְׁבוּעַת הָעֵדוּת מִכְּלַל שְׁבוּעַת בִּטּוּי לְחַיֵּב הַמֵּזִיד בָּהּ כְּשׁוֹגֵג בְּקָרְבָּן אֲבָל לֹא בְּמַלְקוֹת שֶׁנֶּאֱמַר (ויקרא ה ד ה) \"לְאַחַת מֵאֵלֶּה\". בְּמִין אֶחָד מִמִּינֵי שְׁבוּעוֹת אַתָּה מְחַיֵּב הַנִּשְׁבָּע וְאִי אַתָּה מְחַיְּבוֹ בִּשְׁנֵי מִינִין עַד שֶׁיִּהְיֶה חַיָּב בְּדִין שְׁבוּעַת הָעֵדוּת וּבְדִין שְׁבוּעַת בִּטּוּי:","מַשְׁבִּיעַ אֲנִי עֲלֵיכֶם אִם לֹא תָּבוֹאוּ וְתָעִידוּ לִי שֶׁיֵּשׁ לִי בְּיַד פְּלוֹנִי פִּקָּדוֹן וּתְשׂוּמֶת יָד גֵּזֶל וַאֲבֵדָה. שְׁבוּעָה שֶׁאֵין אָנוּ יוֹדְעִין לְךָ עֵדוּת אֵינָן חַיָּבִין אֶלָּא אַחַת. שְׁבוּעָה שֶׁאֵין אָנוּ יוֹדְעִין לְךָ עֵדוּת שֶׁיֵּשׁ לְךָ בְּיַד פְּלוֹנִי פִּקָּדוֹן וּתְשׂוּמֶת יָד גֵּזֶל וַאֲבֵדָה חַיָּבִין עַל כָּל אַחַת וְאַחַת:","מַשְׁבִּיעַ אֲנִי עֲלֵיכֶם אִם לֹא תָּבוֹאוּ וְתָעִידוּ לִי שֶׁיֵּשׁ לִי בְּיַד פְּלוֹנִי חִטִּים וּשְׂעוֹרִים וְכֻסְּמִין. שְׁבוּעָה שֶׁאֵין אָנוּ יוֹדְעִין לְךָ עֵדוּת אֵינָם חַיָּבִין אֶלָּא אַחַת. שְׁבוּעָה שֶׁאֵין אָנוּ יוֹדְעִים לְךָ עֵדוּת שֶׁיֵּשׁ לְךָ בְּיַד פְּלוֹנִי חִטִּים וּשְׂעוֹרִים וְכֻסְּמִין חַיָּבִין עַל כָּל אַחַת וְאַחַת:","וְכֵן אִם תָּבְעוּ אוֹתָן רַבִּים לְהָעִיד לָהֶם וְאָמְרוּ שְׁבוּעָה שֶׁאֵין אָנוּ יוֹדְעִין לָכֶם עֵדוּת אֵינָן חַיָּבִין אֶלָּא אַחַת. לֹא לְךָ וְלֹא לְךָ וְלֹא לְךָ חַיָּבִין עַל כָּל אַחַת וְאַחַת כְּדֶרֶךְ שֶׁבֵּאַרְנוּ בִּשְׁבוּעוֹת הַפִּקָּדוֹן:","הַנִּשְׁבָּע לַחֲבֵרוֹ שֶׁהוּא יוֹדֵעַ לוֹ עֵדוּת וְנִמְצָא שֶׁאֵינוֹ יוֹדֵעַ לוֹ עֵדוּת הֲרֵי זֶה פָּטוּר וְאֵין כָּאן לֹא שְׁבוּעַת הָעֵדוּת וְלֹא שְׁבוּעַת בִּטּוּי. מִפְּנֵי שֶׁשְּׁבוּעַת בִּטּוּי אֵינָהּ אֶלָּא בְּדָבָר שֶׁיֵּשׁ בּוֹ לָאו וְהֵן. וְאִם יֹאמַר שְׁבוּעָה שֶׁאֵינִי יוֹדֵעַ לְךָ עֵדוּת אֵין זֶה שְׁבוּעַת בִּטּוּי אֶלָּא שְׁבוּעַת הָעֵדוּת. הוֹאִיל וְלָאו זֶה שֶׁיֵּשׁ בָּהּ אֵינָהּ שְׁבוּעַת בִּטּוּי. כָּךְ הֵן שֶׁבָּהּ שֶׁהוּא הַנִּשְׁבָּע שֶׁיּוֹדֵעַ לוֹ עֵדוּת אֵינוֹ שְׁבוּעַת בִּטּוּי:","דָּבָר בָּרוּר הוּא שֶׁהַנִּשְׁבָּע לַחֲבֵרוֹ שֶׁהֵעִיד לוֹ וְהוּא לֹא הֵעִיד אוֹ שֶׁלֹּא הֵעִיד לוֹ וְהוּא הֵעִיד הֲרֵי זֶה חַיָּב מִשּׁוּם שְׁבוּעַת בִּטּוּי וְאֵין כָּאן שְׁבוּעַת עֵדוּת כְּלָל:"],"Mishneh Torah, Offerings for Unintentional Transgressions 15":["כְּבָר בֵּאַרְנוּ שֶׁכָּל שְׁגָגָה שֶׁהַהֶדְיוֹט מֵבִיא עָלֶיהָ חַטָּאת הַקְּבוּעָה כִּשְׂבָּה אוֹ שְׂעִירָה אִם שָׁגַג בָּהּ הַנָּשִׂיא מֵבִיא שָׂעִיר וְאִם שָׁגַג בָּהּ כֹּהֵן מָשִׁיחַ מֵבִיא פַּר. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁכֹּהֵן מָשִׁיחַ מֵבִיא פַּר עַל שִׁגְגָתוֹ כְּשֶׁטָּעָה בְּהוֹרָאַת עַצְמוֹ וְעָשָׂה מַעֲשֶׂה בְּשִׁגְגַת הוֹרָאָתוֹ לְבַדָּהּ וְהוּא שֶׁיִּהְיֶה חָכָם מֻפְלָא שֶׁנֶּאֱמַר (ויקרא ד ג) \"אִם הַכֹּהֵן הַמָּשִׁיחַ יֶחֱטָא לְאַשְׁמַת הָעָם\" הֲרֵי מָשִׁיחַ כְּצִבּוּר מָה הַצִּבּוּר שֶׁהֵן בֵּית דִּין אֵינָן חַיָּבִין בְּקָרְבָּן עַד שֶׁיִּהְיוּ חֲכָמִים רְאוּיִין לְהוֹרָאָה וְיִטְעוּ בְּהוֹרָאָה וְיַעֲשׂוּ הָעוֹשִׂים עַל פִּיהֶם וְיוֹרוּ לְבַטֵּל מִקְצָת וּלְקַיֵּם מִקְצָת כָּךְ הַמָּשִׁיחַ בְּכָל הַדְּרָכִים הָאֵלּוּ:","כֵּיצַד. כֹּהֵן מָשִׁיחַ שֶׁטָּעָה בְּהוֹרָאָה לְעַצְמוֹ. וְדִמָּה שֶׁהַזּוֹרֵק מֵרְשׁוּת לִרְשׁוּת בְּשַׁבָּת מֻתָּר וְזָרַק מֵרְשׁוּת לִרְשׁוּת וְהוּא תּוֹלֶה בְּהוֹרָאָתוֹ לְעַצְמוֹ. כְּשֶׁיִּוָּדַע לוֹ חֶטְאוֹ יָבִיא פַּר לְחַטָּאת. אֲבָל אִם לֹא תָּלָה בְּהוֹרָאָתוֹ אֶלָּא שָׁגַג וְזָרַק בִּשְׁגָגָה. אוֹ שֶׁתָּלָה בְּהוֹרָאָתוֹ וְלֹא הָיָה חָכָם מֻפְלָא. אוֹ שֶׁעָקַר כָּל הַגּוּף בְּהוֹרָאָתוֹ לְעַצְמוֹ. אוֹ שֶׁשָּׁגַג בְּהוֹרָאָתוֹ לְבַטֵּל מִקְצָת וְלֹא עָשָׂה וְהוּא סוֹמֵךְ עַל הוֹרָאָתוֹ אֶלָּא עָשָׂה בִּשְׁגָגָה אַחֶרֶת. אוֹ שֶׁהָיָה מֵזִיד בְּהוֹרָאָה וְשָׁגַג בְּמַעֲשֶׂה הֲרֵי זֶה פָּטוּר מִקָּרְבַּן כְּלָל שֶׁדִּינוֹ לְהוֹרָאַת עַצְמוֹ כְּדִין הַקָּהָל לְהוֹרָאַת בֵּית דִּין לְכָל דָּבָר. הוֹרָה לְעַצְמוֹ וְשָׁכַח מֵאֵי זֶה טַעַם הוֹרָה וּבִשְׁעַת מַעֲשֶׂה אָמַר הֲרֵינִי עוֹשֶׂה עַל דַּעַת הוֹרָאָתִי הֲרֵי זֶה מֵבִיא פַּר חַטָּאת:","הוֹרָה לְעַצְמוֹ לְבַטֵּל מִקְצָת וּלְקַיֵּם מִקְצָת בַּעֲבוֹדָה זָרָה וְעָשָׂה כְּפִי הוֹרָאָתוֹ. הֲרֵי זֶה מֵבִיא שְׂעִירָה כְּהֶדְיוֹט וְהוּא שֶׁיִּשְׁגֹּג בְּהוֹרָאָה כְּמוֹ שֶׁבֵּאַרְנוּ. שֶׁאֵין הַכֹּהֵן הַמָּשִׁיחַ חַיָּב קָרְבָּן אֶלָּא בְּהֶעְלֵם דָּבָר בְּהוֹרָאָה עִם שִׁגְגַת הַמַּעֲשֶׂה בְּצִבּוּר אֲבָל אִם שָׁגַג בְּמַעֲשֶׂה בִּלְבַד בְּלֹא הוֹרָאָה בֵּין בַּעֲבוֹדָה זָרָה בֵּין בִּשְׁאָר מִצְוֹת אֵינוֹ מֵבִיא קָרְבָּן כְּלָל:","הוֹרָה הַכֹּהֵן הַמָּשִׁיחַ עִם בֵּית דִּין וְשָׁגַג הוּא וְהֵם בְּהוֹרָאָה אַף עַל פִּי שֶׁעָשׂוּ עַל פִּי הַהוֹרָאָה הַזֹּאת שֶׁטָּעוּ בָּהּ. הוֹאִיל וְלֹא סָמַךְ בִּשְׁעַת מַעֲשֶׂה עַל הוֹרָאָתוֹ לְבַדָּהּ אֶלָּא עַל הוֹרָאָתוֹ עִם הוֹרָאַת בֵּית דִּין הֲרֵי זֶה פָּטוּר וְאֵין צָרִיךְ לְהָבִיא כַּפָּרָה בִּפְנֵי עַצְמוֹ. אֶלָּא אִם הָיוּ בֵּית דִּין מְבִיאִין קָרְבָּן מִתְכַּפֵּר לוֹ בִּכְלַל הַצִּבּוּר. וְאִם הָיוּ הָעוֹשִׂים הֵם הַמְּבִיאִים קָרְבָּן הוּא אֵינוֹ מֵבִיא קָרְבָּן שֶׁהֲרֵי אֵין צָרִיךְ כַּפָּרָה בִּפְנֵי עַצְמוֹ:","הוֹרָה עִם בֵּית דִּין בִּשְׁגָגָה וְשָׁגְגוּ הֵם בְּדָם וְהוּא בְּחֵלֶב. אֵינוֹ מִתְכַּפֵּר לוֹ עִם הַצִּבּוּר אֶלָּא מֵבִיא פַּר לְעַצְמוֹ:","כֹּהֵן מָשִׁיחַ שֶׁנִּסְתַּפֵּק לוֹ אִם שָׁגַג שְׁגָגָה זוֹ שֶׁהִיא שִׁגְגַת הוֹרָאָה עִם הַמַּעֲשֶׂה אוֹ לֹא שָׁגַג אוֹתָהּ. אֵינוֹ מֵבִיא אָשָׁם תָּלוּי מִפְּנֵי שֶׁהוּא בָּהּ כְּצִבּוּר שֶׁאֵינָן מְבִיאִין אָשָׁם תָּלוּי עַל לֹא הוֹדַע שֶׁל שִׁגְגַת הוֹרָאָה. אֲבָל הַנָּשִׂיא אִם נִסְתַּפֵּק לוֹ אִם חָטָא אוֹ לֹא חָטָא מֵבִיא אָשָׁם תָּלוּי כִּשְׁאָר הַהֶדְיוֹטוֹת. מִפְּנֵי שֶׁאֵין שִׁגְגָתוֹ תְּלוּיָה בְּהוֹרָאָתוֹ. אֵי זֶהוּ נָשִׂיא הָאָמוּר בַּתּוֹרָה זֶה מֶלֶךְ שֶׁאֵין עָלָיו רְשׁוּת מֵאָדָם מִיִּשְׂרָאֵל וְאֵין לְמַעְלָה מִמֶּנּוּ בְּמַלְכוּתוֹ אֶלָּא ה' אֱלֹהָיו. בֵּין שֶׁהָיָה מִבֵּית דָּוִד אוֹ מִשְּׁאָר שִׁבְטֵי יִשְׂרָאֵל. וְאִם הָיוּ מְלָכִים רַבִּים וְאֵין אֶחָד מֵהֶן עוֹבֵד אֶת חֲבֵרוֹ. כָּל אֶחָד וְאֶחָד מֵהֶן מֵבִיא שְׂעִיר עִזִּים עַל שִׁגְגָתוֹ. וְאֵי זֶהוּ כֹּהֵן מָשִׁיחַ זֶה כֹּהֵן גָּדוֹל שֶׁנִּמְשַׁח בְּשֶׁמֶן הַמִּשְׁחָה לֹא הַמְרֻבֶּה בִּבְגָדִים:","כֹּהֵן גָּדוֹל שֶׁנִּמְשַׁח בְּשֶׁמֶן הַמִּשְׁחָה וְעָבַר מֵעֲבוֹדָתוֹ מִפְּנֵי מוּם אוֹ זִקְנָה וְכַיּוֹצֵא בָּהֶן וְחָטָא בִּשְׁגָגָה זוֹ מֵבִיא פַּר עַל שִׁגְגָתוֹ. לְפִי שֶׁאֵין בֵּין כֹּהֵן מָשִׁיחַ הַמְשַׁמֵּשׁ לְכֹהֵן מָשִׁיחַ שֶׁעָבַר אֶלָּא פַּר יוֹם הַכִּפּוּרִים וַעֲשִׂירִית הָאֵיפָה שֶׁל כָּל יוֹם שֶׁאֵין מַקְרִיב אוֹתָן אֶלָּא כֹּהֵן הַמְשַׁמֵּשׁ בִּכְהוּנָה גְּדוֹלָה. אֲבָל פַּר הַבָּא עַל כָּל הַמִּצְווֹת שָׁוִים הֵם בּוֹ:","נָשִׂיא שֶׁעָשָׂה עִם הַצִּבּוּר בְּהוֹרָאַת בֵּית דִּין הֲרֵי זֶה מִתְכַּפֵּר לוֹ בִּכְלַל הָעָם. שֶׁאִם הָיוּ בֵּית דִּין הֵם שֶׁהִקְרִיבוּ עַל שִׁגְגָתָן כָּל הָעָם וְהַמֶּלֶךְ פְּטוּרִין מִן הַקָּרְבָּן כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם הָיוּ הָעוֹשִׂים עַל פִּי בֵּית דִּין הֵם שֶׁחַיָּבִין בְּקָרְבָּן וְהָיָה הַמֶּלֶךְ מִן הָעוֹשִׂים. הֲרֵי זֶה מֵבִיא שָׂעִיר שֶׁשְּׂעִיר נָשִׂיא בִּמְקוֹם כִּשְׂבָּה אוֹ שְׂעִירָה שֶׁל הֶדְיוֹט הוּא עוֹמֵד:","נָשִׂיא שֶׁנִּצְטָרֵעַ עָבַר מִנְּשִׂיאוּתוֹ וְנָשִׂיא שֶׁעָבַר מִנְּשִׂיאוּתוֹ הֲרֵי הוּא כְּהֶדְיוֹט. חָטָא כְּשֶׁהָיָה נָשִׂיא וְעָבַר מִגְּדֻלָּתוֹ הֲרֵי זֶה מֵבִיא שָׂעִיר שֶׁנֶּאֱמַר (ויקרא ד ג) \"עַל חַטָּאתוֹ אֲשֶׁר חָטָא\". כִּשְׁעַת חַטָּאתוֹ הוּא מֵבִיא:","כֹּהֵן מָשִׁיחַ אוֹ מֶלֶךְ שֶׁחָטְאוּ עַד שֶׁלֹּא נִתְמַנּוּ. אַף עַל פִּי שֶׁלֹּא נוֹדַע לָהֶם אֶלָּא אַחַר שֶׁנִּתְמַנּוּ הֲרֵי אֵלּוּ כְּהֶדְיוֹט. שֶׁנֶּאֱמַר (ויקרא ד כב) \"אֲשֶׁר נָשִׂיא יֶחֱטָא\". (ויקרא ד ג) \"אִם הַכֹּהֵן הַמָּשִׁיחַ יֶחֱטָא\". עַד שֶׁיֶּחְטָא כְּשֶׁהוּא נָשִׂיא וּכְשֶׁהוּא מָשִׁיחַ. לְפִיכָךְ אִם אָכַל סְפֵק חֵלֶב כְּשֶׁהוּא הֶדְיוֹט וְנוֹדַע לוֹ עַל סְפֵקוֹ אַחַר שֶׁנִּתְמַנָּה לִהְיוֹת כֹּהֵן גָּדוֹל הֲרֵי זֶה מֵבִיא אָשָׁם תָּלוּי. אָכַל חֲצִי זַיִת חֵלֶב כְּשֶׁהוּא הֶדְיוֹט וַחֲצִי זַיִת כְּשֶׁהוּא נָשִׂיא בְּהֶעְלֵם אַחַת אוֹ שֶׁאָכַל חֲצִי זַיִת כְּשֶׁהוּא נָשִׂיא וַחֲצִי זַיִת אַחַר שֶׁעָבַר אֵינוֹ מִצְטָרֵף וּפָטוּר. אָכַל חֲצִי זַיִת כְּשֶׁהוּא הֶדְיוֹט וְנִתְמַנָּה וְעָבַר וְאָכַל חֲצִי זַיִת כְּשֶׁהוּא הֶדְיוֹט. הֲרֵי זֶה סָפֵק אִם מִצְטָרֵף אוֹ כְּבָר הִפְסִיקָה הַנְּשִׂיאוּת:"],"Mishneh Torah, One Who Injures a Person or Property 4":["הַנּוֹגֵף אֶת הָאִשָּׁה וְיָצְאוּ יְלָדֶיהָ אַף עַל פִּי שֶׁלֹּא נִתְכַּוֵּן חַיָּב לְשַׁלֵּם דְּמֵי וְלָדוֹת לַבַּעַל וְנֵזֶק וְצַעַר לָאִשָּׁה:","וְכֵיצַד מְשַׁעֲרִין דְּמֵי וְלָדוֹת. שָׁמִין הָאִשָּׁה כַּמָּה הָיְתָה יָפָה עַד שֶׁלֹּא יָלְדָה וְכַמָּה הִיא יָפָה מִשֶּׁיָּלְדָה וְנוֹתְנִין לַבַּעַל. אִם מֵת הַבַּעַל נוֹתְנִין לְיוֹרְשָׁיו. וְאִם נִגְּפָה אַחַר מִיתַת הַבַּעַל נוֹתְנִין אַף דְּמֵי וְלָדוֹת לָאִשָּׁה:","הָיְתָה נְשׂוּאָה לְגֵר וְחָבַל בָּהּ בְּחַיֵּי הַגֵּר נוֹתֵן דְּמֵי וְלָדוֹת לַבַּעַל. מֵת הַגֵּר פָּטוּר. וְאִם חָבַל בָּהּ אַחַר מִיתַת הַגֵּר זָכְתָה הִיא בִּדְמֵי וְלָדוֹת:","הָיְתָה שִׁפְחָה אוֹ עַכּוּ\"ם בִּשְׁעַת הֵרָיוֹן וּבִשְׁעַת נְגִיפָה נִשְׁתַּחְרְרָה אוֹ נִתְגַּיְּרָה הֲרֵי דְּמֵי הַוְּלָדוֹת שֶׁלָּהּ:","הַנּוֹגֵף אֶת הָאִשָּׁה וְיָצְאוּ יְלָדֶיהָ וּמֵתָה אַף עַל פִּי שֶׁהָיָה שׁוֹגֵג הֲרֵי זֶה פָּטוּר מִן הַתַּשְׁלוּמִין וְאֵינוֹ מְשַׁלֵּם כְּלוּם. שֶׁנֶּאֱמַר (שמות כא כב) \"וְלֹא יִהְיֶה אָסוֹן עָנוֹשׁ יֵעָנֵשׁ\". לֹא חִלֵּק הַכָּתוּב בֵּין שׁוֹגֵג לְמֵזִיד בְּדָבָר שֶׁיֵּשׁ בּוֹ מִיתַת בֵּית דִּין לְפָטְרוֹ מִן הַתַּשְׁלוּמִין:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁנִּתְכַּוֵּן לָאִשָּׁה. אֲבָל אִם נִתְכַּוֵּן לַחֲבֵרוֹ וְנָגַף אֶת הָאִשָּׁה אַף עַל פִּי שֶׁמֵּתָה הוֹאִיל וֶהֱמִיתָהּ בְּלֹא כַּוָּנָה הֲרֵי זֶה כְּדָבָר שֶׁאֵין בּוֹ מִיתַת בֵּית דִּין וּמְשַׁלֵּם דְּמֵי וְלָדוֹת:","הַמַּכֶּה אָבִיו וְאִמּוֹ וְלֹא עָשָׂה בָּהֶן חַבּוּרָה חַיָּב בַּחֲמִשָּׁה דְּבָרִים. אֲבָל אִם עָשָׂה בָּהֶם חַבּוּרָה אוֹ שֶׁחָבַל בַּחֲבֵרוֹ בְּשַׁבָּת אֲפִלּוּ הָיָה שׁוֹגֵג פָּטוּר מִן הַתַּשְׁלוּמִין מִפְּנֵי שֶׁהוּא עֲוֹן מִיתַת בֵּית דִּין. וּכְבָר בֵּאַרְנוּ שֶׁלֹּא חִלֵּק הַכָּתוּב בְּדָבָר שֶׁיֵּשׁ בּוֹ מִיתַת בֵּית דִּין בֵּין שׁוֹגֵג לְמֵזִיד לְפָטְרוֹ מִן הַתַּשְׁלוּמִין:","וַהֲלֹא הַחוֹבֵל מְקַלְקֵל הוּא וְכָל הַמְקַלְקְלִין בְּשַׁבָּת פְּטוּרִין מִן הַמִּיתָה וְלָמָּה נַחְשֹׁב זֶה הַחוֹבֵל עָוֹן שֶׁיֵּשׁ בּוֹ מִיתַת בֵּית דִּין. הוֹאִיל וְעָשָׂה נַחַת רוּחַ לְיִצְרוֹ הָרַע בְּעֵת שֶׁחָבַל בַּחֲבֵרוֹ הֲרֵי הוּא כִּמְתַקֵּן וְנִמְצָא עֲוֹן מִיתָה לְפִיכָךְ פָּטוּר מִתַּשְׁלוּמִין:","הַחוֹבֵל בַּחֲבֵרוֹ בְּיוֹם הַכִּפּוּרִים אֲפִלּוּ בְּמֵזִיד חַיָּב בְּתַשְׁלוּמִין. אַף עַל פִּי שֶׁעָבַר עֲבֵרָה שֶׁהוּא חַיָּב עָלֶיהָ מַלְקוֹת. וַהֲלֹא כָּל הַמְחֻיָּב מַלְקוֹת וְתַשְׁלוּמִין לוֹקֶה וְאֵינוֹ מְשַׁלֵּם שֶׁאֵין אָדָם לוֹקֶה וּמְשַׁלֵּם. כָּךְ הֵם הַדְּבָרִים בַּכּל חוּץ מֵחוֹבֵל בַּחֲבֵרוֹ שֶׁהוּא מְשַׁלֵּם שֶׁהֲרֵי בְּפֵרוּשׁ רִבְּתָה תּוֹרָה חוֹבֵל בַּחֲבֵרוֹ לְתַשְׁלוּמִין שֶׁנֶּאֱמַר (שמות כא יט) \"רַק שִׁבְתּוֹ יִתֵּן\":","הַחוֹבֵל בְּעֶבֶד כְּנַעֲנִי שֶׁלּוֹ פָּטוּר. חָבַל בְּעֶבֶד עִבְרִי שֶׁלּוֹ חַיָּב בְּכֻלָּן חוּץ מִן הַשֶּׁבֶת. הַחוֹבֵל בְּעֶבֶד כְּנַעֲנִי שֶׁל חֲבֵרוֹ רַבּוֹ שֶׁל עֶבֶד נוֹטֵל חֲמִשָּׁה דְּבָרִים. וַאֲפִלּוּ צִעֲרוֹ בְּסַם וְנִתִרַפֵּא בִּמְהֵרָה הֲרֵי כָּל רְפוּאָתוֹ לְרַבּוֹ:","כָּל עֶבֶד שֶׁיָּצָא לְחֵרוּת וַעֲדַיִן לֹא הִגִּיעַ גֵּט שִׁחְרוּר לְיָדוֹ אֵין לוֹ קְנָס. וַאֲחֵרִים שֶׁחָבְלוּ בּוֹ אֵינוֹ יָכוֹל לְהוֹצִיא מֵהֶן לְעַצְמוֹ שֶׁעֲדַיִן לֹא גָּמַר שִׁחְרוּרוֹ. וְלֹא הָאָדוֹן יָכוֹל לְהוֹצִיא מֵהֶן שֶׁהֲרֵי לֹא נִשְׁאַר [לוֹ] בּוֹ קִנְיָן. לְפִיכָךְ הַמַּפִּיל שֵׁן עַבְדּוֹ וְאַחַר כָּךְ סִמֵּא עֵינוֹ יוֹצֵא בְּשִׁנּוֹ וְאֵינוֹ נוֹתֵן לוֹ דְּמֵי עֵינוֹ. וְאִם תָּפַשׂ אֵין מוֹצִיאִין מִיָּדוֹ:","מִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין שֶׁבִּיְּשׁוֹ אָדָם אוֹ צִעֲרוֹ אוֹ שֶׁנְּגָחוֹ שׁוֹר וְכַיּוֹצֵא בָּאֵלּוּ. אִם אֵרְעוֹ זֶה בַּיּוֹם שֶׁל רַבּוֹ לְרַבּוֹ. בַּיּוֹם שֶׁל עַצְמוֹ לְעַצְמוֹ:","הַחוֹבֵל בְּעֶבֶד עִבְרִי שֶׁל חֲבֵרוֹ חַיָּב בַּחֲמִשָּׁה דְּבָרִים וְיִלָּקַח בָּהֶן קַרְקַע וְרַבּוֹ אוֹכֵל פֵּרוֹתֶיהָ. וְלִכְשֶׁיֵּצֵא הָעֶבֶד לְחֵרוּת יֵצֵא הַשָּׂדֶה מִתַּחַת רַבּוֹ. הִזִּיקוֹ הֶזֵּק שֶׁאֵינוֹ מְעַכֵּב מְלָאכָה כְּלָל כְּגוֹן שֶׁקָּטַע רֹאשׁ אָזְנוֹ אוֹ רֹאשׁ חָטְמוֹ הַכּל לָעֶבֶד וְאֵין לְרַבּוֹ בָּהֶן פֵּרוֹת:","הַחוֹבֵל בְּבַת קְטַנָּה שֶׁל אֲחֵרִים אִם נֵזֶק הַפּוֹחֵת אוֹתָהּ מִכַּסְפָּהּ הוּא הֲרֵי הוּא שֶׁל אָב. וְכֵן שִׁבְתָּהּ שֶׁל אָב שֶׁהֲרֵי מַעֲשֵׂה יָדֶיהָ וְכֶסֶף מְכִירָתָהּ שֶׁל אָבִיהָ הוּא. אֲבָל צַעַר וּבשֶׁת וְרִפּוּי הֲרֵי הוּא שֶׁלָּהּ. וְכֵן נֵזֶק שֶׁאֵינוֹ פּוֹחֲתָהּ מִכַּסְפָּהּ הֲרֵי הוּא שֶׁלָּהּ. וְכֵן הַחוֹבֵל בְּבִתּוֹ מְשַׁלֵּם צַעַר וְרִפּוּי וּבשֶׁת:","הַחוֹבֵל בְּאֵשֶׁת אִישׁ הַשֶּׁבֶת וְהָרִפּוּי לְבַעֲלָהּ וְהַצַּעַר שֶׁלָּהּ. וְהַבּשֶׁת וְהַנֵּזֶק אִם בְּגָלוּי הוּא כְּגוֹן שֶׁחָבַל בְּפָנֶיהָ וּבְצַוָּארָהּ אוֹ בְּיָדֶיהָ וּזְרוֹעוֹתֶיהָ הַשְּׁלִישׁ שֶׁלָּהּ וּשְׁנֵי שְׁלִישִׁים לַבַּעַל. וְאִם בַּסֵּתֶר הוּא הַנֵּזֶק הַשְּׁלִישׁ לַבַּעַל וּשְׁנֵי שְׁלִישִׁים לָאִשָּׁה. שֶׁל בַּעַל נוֹתְנִין לוֹ מִיָּד וְשֶׁל אִשָּׁה יִלָּקַח בָּהֶן קַרְקַע וְהַבַּעַל אוֹכֵל פֵּרוֹת:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁחָבְלוּ בָּהּ אֲחֵרִים. אֲבָל הַבַּעַל שֶׁחָבַל בְּאִשְׁתּוֹ חַיָּב לְשַׁלֵּם לָהּ מִיָּד כָּל הַנֵּזֶק וְכָל הַבּשֶׁת וְהַצַּעַר וְהַכּל שֶׁלָּהּ וְאֵין לַבַּעַל בָּהֶן פֵּרוֹת. וְאִם רָצְתָה לִתֵּן הַדָּמִים לְאַחֵר נוֹתֶנֶת. וְכָזֶה הוֹרוּ הַגְּאוֹנִים. וְהַבַּעַל מְרַפֵּא אוֹתָהּ כְּדֶרֶךְ שֶׁמְּרַפֵּא כָּל חָלְיָהּ:","וְהַמַּזִּיק אִשְׁתּוֹ בְּתַשְׁמִישׁ הַמִּטָּה חַיָּב בִּנְזָקֶיהָ:","הָאִשָּׁה שֶׁחָבְלָה בְּבַעְלָהּ אִם הָיָה תּוֹסֶפֶת בִּכְתֻבָּתָהּ מְחַיְּבִין אוֹתָהּ לִמְכֹּר הַתּוֹסֶפֶת לְבַעֲלָהּ בְּטוֹבַת הֲנָאָה וְגוֹבֶה מִמֶּנָּה אִם רָצָה הַבַּעַל. וְאִם רָצָה לְגָרְשָׁהּ וְלִגְבּוֹת מִן הַכּל גּוֹבֶה. וְאִם לֹא הָיָה לָהּ תּוֹסֶפֶת אֵינָהּ יְכוֹלָה לִמְכֹּר לוֹ עִקַּר כְּתֻבָּתָהּ. שֶׁאָסוּר לוֹ לָאָדָם לַשְׁהוֹת אֶת אִשְׁתּוֹ שָׁעָה אַחַת בְּלֹא כְּתֻבָּה כְּדֵי שֶׁלֹּא תְּהֵא קַלָּה בְּעֵינָיו לְהוֹצִיאָהּ. אֶלָּא אִם רָצָה הַבַּעַל כּוֹתֵב עָלֶיהָ שְׁטָר בִּדְמֵי חֲבָלוֹ אוֹ מְגָרְשָׁהּ וְנוֹטֵל מִכְּתֻבָּתָהּ הָרָאוּי לוֹ:","הַחוֹבֵל בְּבָנָיו הַגְּדוֹלִים אִם אֵין סוֹמְכִין עַל שֻׁלְחָנוֹ נוֹתֵן לָהֶם מִיָּד. וְהַקְּטַנִּים יִלָּקַח בָּהֶן קַרְקַע בְּנִזְקָן וְהֵן אוֹכְלִין פֵּרוֹתָיו. וְכֵן הַדִּין בַּאֲחֵרִים שֶׁחָבְלוּ בָּהֶן. וְאִם הָיוּ סְמוּכִין עַל שֻׁלְחָנוֹ וְחָבַל בָּהֶן פָּטוּר בֵּין שֶׁהָיוּ גְּדוֹלִים בֵּין שֶׁהָיוּ קְטַנִּים. וְאִם חָבְלוּ בָּהֶן אֲחֵרִים בַּגְּדוֹלִים יִתֵּן לָהֶם מִיָּד וּבַקְּטַנִּים יִלָּקַח בָּהֶן קַרְקַע וְהֵן אוֹכְלִין פֵּרוֹתֶיהָ עַד שֶׁיַּגְדִּילוּ:","חֵרֵשׁ שׁוֹטֶה וְקָטָן פְּגִיעָתָן רָעָה. הַחוֹבֵל בָּהֶן חַיָּב וְהֵן שֶׁחָבְלוּ בַּאֲחֵרִים פְּטוּרִין. אַף עַל פִּי שֶׁנִּתְפַּתֵּחַ הַחֵרֵשׁ וְנִשְׁתַּפָּה הַשּׁוֹטֶה וְהִגְדִּיל הַקָּטָן אֵינָם חַיָּבִין לְשַׁלֵּם שֶׁבְּשָׁעָה שֶׁחָבְלוּ בָּהֶן לֹא הָיוּ בְּנֵי דַּעַת:","הָעֶבֶד וְהָאִשָּׁה פְּגִיעָתָן רָעָה הַחוֹבֵל בָּהֶן חַיָּב וְהֵן שֶׁחָבְלוּ בַּאֲחֵרִים פְּטוּרִין. אֲבָל מְשַׁלְּמִין לְאַחַר זְמַן אִם נִתְגָּרְשָׁה הָאִשָּׁה אוֹ מֵת בַּעְלָהּ אוֹ נִשְׁתַּחְרֵר הָעֶבֶד. שֶׁהֲרֵי בְּנֵי דֵּעָה הֵן וַהֲרֵי הֵן כְּבַעַל חוֹב שֶׁאֵין לוֹ מַה יִּגְבֶּה שֶׁאִם הֶעֱשִׁיר חַיָּב לְשַׁלֵּם:","עַבְדּוֹ שֶׁל אָדָם כְּגוּפוֹ וּבְהֶמְתּוֹ כְּמָמוֹנוֹ. כֵּיצַד. הֲרֵי שֶׁהִנִּיחַ גַּחֶלֶת עַל לֵב עַבְדּוֹ שֶׁל חֲבֵרוֹ וּמֵת אוֹ שֶׁדְּחָפוֹ לַיָּם אוֹ לָאֵשׁ וְהוּא יָכוֹל לַעֲלוֹת מִשָּׁם וְלֹא עָלָה וּמֵת פָּטוּר מִן הַתַּשְׁלוּמִין. וְאִם עָשָׂה כֵן לְבֶהֱמַת חֲבֵרוֹ כְּאִלּוּ הִנִּיחַ הַגַּחֶלֶת עַל בִּגְדוֹ וְנִשְׂרַף שֶׁהוּא חַיָּב לְשַׁלֵּם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Other Sources of Defilement 16":["מִפְּנֵּי מָה טִהֲרוּ חֲכָמִים סְפֵק טֻמְאָה בִּרְשׁוּת הָרַבִּים. שֶׁהֲרֵי הַצִּבּוּר עוֹשִׂין פֶּסַח בְּטֻמְאָה בִּזְמַן שֶׁהַטְּמֵאִים מְרֻבִּין. אִם טֻמְאָה וַדָּאִית נִדְחֵית מִפְּנֵיהֶן קַל וָחֹמֶר לִסְפֵק טֻמְאָה שֶׁאִסּוּר כָּל הַסְּפֵקוֹת מִדִּבְרֵיהֶן כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת בִּיאוֹת אֲסוּרוֹת. וּמִפְּנֵי מָה הֶחְמִירוּ בִּסְפֵק רְשׁוּת הַיָּחִיד. שֶׁהֲרֵי סוֹטָה שֶׁנִּסְתְּרָה אַף עַל פִּי שֶׁהַדָּבָר סָפֵק הֲרֵי הִיא טְמֵאָה לְבַעְלָהּ עַד שֶׁתִּשְׁתֶּה:","וּכְשֵׁם שֶׁהַסּוֹטָה וּבוֹעֲלָהּ שְׁנַיִם כָּךְ סְפֵק טֻמְאָה בִּשְׁנַיִם. אֲבָל אִם הָיוּ שְׁלֹשָׁה בִּרְשׁוּת הַיָּחִיד הֲרֵי סְפֵק טֻמְאָתָן שָׁם טָהוֹר כִּרְשׁוּת הָרַבִּים. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה זֶה שֶׁנִּטְמָא בְּסָפֵק יֵשׁ בּוֹ דַּעַת לְהִשָּׁאֵל וְלִדְרשׁ מִמֶּנּוּ מָה אֵרַע לוֹ כְּסוֹטָה. אֲבָל אִם הָיָה חֵרֵשׁ אוֹ שׁוֹטֶה אוֹ קָטָן שֶׁאֵינוֹ יוֹדֵעַ לְהָשִׁיב עַל הָעִנְיָן כְּשֶׁשּׁוֹאֲלִין אוֹתוֹ הֲרֵי סְפֵקוֹ טָהוֹר. כֵּיצַד. חֵרֵשׁ אוֹ שׁוֹטֶה אוֹ קָטָן שֶׁאֵין בּוֹ דַּעַת לְהִשָּׁאֵל שֶׁנִּמְצְאוּ בְּחָצֵר אוֹ בְּמָבוֹי שֶׁיֵּשׁ שָׁם טֻמְאָה וְסָפֵק נָגְעוּ וְסָפֵק לֹא נָגְעוּ הֲרֵי אֵלּוּ טְהוֹרִין. וְכֵן כָּל שֶׁאֵין בּוֹ דַּעַת לְהִשָּׁאֵל אַף עַל פִּי שֶׁנּוֹלַד לוֹ הַסָּפֵק בִּרְשׁוּת הַיָּחִיד סְפֵקוֹ טָהוֹר:","הַסּוּמָא וְהַיָּשֵׁן וְהַמְהַלֵּךְ בַּלַּיְלָה סְפֵקָן בִּרְשׁוּת הַיָּחִיד טָמֵא מִפְּנֵי שֶׁיֵּשׁ בּוֹ דַּעַת לְהִשָּׁאֵל. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁכָּל שֶׁאֵין בּוֹ דַּעַת לִשָּׁאֵל סְפֵקוֹ טָהוֹר בְּשֶׁהָיָה הַדָּבָר שָׁקוּל וְאֵין שָׁם חֲזָקָה. אֲבָל אִם הָיָה הַדָּבָר יָדוּעַ שֶׁחֶזְקָתוֹ שֶׁנִּטְמָא הֲרֵי זֶה טָמֵא. כֵּיצַד. תִּינוֹק טָמֵא שֶׁנִּמְצָא בְּצַד הָעִסָּה וְהַבָּצֵק בְּיָדוֹ הֲרֵי הָעִסָּה טְמֵאָה שֶׁדֶּרֶךְ הַתִּינוֹק לְטַפֵּחַ וּבְכָךְ הִיא חֶזְקָתוֹ. וְאֵין שׂוֹרְפִין עַל חֲזָקָה זוֹ:","הָיוּ מַשְׁקִין טְמֵאִין וּבָצֵק טָהוֹר וּבְהֵמָה אוֹ חַיָּה אוֹ עוֹפוֹת בַּבַּיִת וְנִמְצָא בַּבָּצֵק מְקוֹם נְשִׁיכָתָן. חֲזָקָה שֶׁשָּׁתוּ מַשְׁקִין וְנָשְׁכוּ בַּבָּצֵק וְטִמְּאוּהוּ. הָיְתָה שָׁם פָּרָה וּבֵין הַמַּשְׁקִין וְהַבָּצֵק כְּדֵי שֶׁתְּלַחֵךְ אֶת לְשׁוֹנָהּ הֲרֵי הַבָּצֵק טָהוֹר. וּבִשְׁאָר כָּל הַבְּהֵמָה כְּדֵי שֶׁתְּנַגֵּב אֶת פִּיהָ. פָּחוֹת מִזֶּה הַבָּצֵק טָמֵא. וְאִם הָיָה כֶּלֶב אֲפִלּוּ הָיוּ מַשְׁקִין בְּצַד הַבָּצֵק הֲרֵי זֶה טָהוֹר. שֶׁאֵין דַּרְכּוֹ שֶׁל כֶּלֶב לְהַנִּיחַ הַמָּזוֹן וְלֵילֵךְ לוֹ אֶל הַמַּיִם. נִמְצָא בַּבָּצֵק נְקִירַת הַתַּרְנְגוֹלִין אִם יֵשׁ בֵּין הַמַּשְׁקִין וְהַבָּצֵק כְּדֵי שֶׁיְּנַגְּבוּ אֶת פִּיהֶן בָּאָרֶץ הַבָּצֵק טָהוֹר. וְאִם לָאו טָמֵא שֶׁחֶזְקָתָן שֶׁשָּׁתוּ וְנִקְּרוּ בַּבָּצֵק בַּמַּשְׁקִין שֶׁבְּפִיהֶם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיוּ הַמַּשְׁקִין צְלוּלִין שֶׁבָּבוּאָה שֶׁל תִּינוֹק נִכֶּרֶת בָּהֶן. אֲבָל עֲכוּרִים הַבָּצֵק טָהוֹר. שֶׁאִלּוּ נִקְּרוּ בַּמַּשְׁקִין הָיָה מְקוֹם הַמַּשְׁקִין נִכָּר בַּבָּצֵק. אִם הָיוּ צְלוּלִין אַף עַל פִּי שֶׁהַבָּצֵק בְּחֶזְקַת טֻמְאָה אֵין שׂוֹרְפִין עַל חֲזָקָה זוֹ אֶלָּא תּוֹלִין:","אֵיזוֹ הִיא חֲזָקָה שֶׁשּׂוֹרְפִין עָלֶיהָ בִּרְשׁוּת הַיָּחִיד. עִסָּה בַּבַּיִת וּשְׁרָצִים וּצְפַרְדְּעִים מְטַפְּלִין שָׁם וְנִמְצְאוּ חֲתִיכוֹת מִבְּשָׂרָן בָּעִסָּה אִם רֹב הַמְטַפְּלִים שְׁרָצִים הָעִסָּה טְמֵאָה וְתִשָּׂרֵף. וְאִם הָרֹב צְפַרְדְּעִים טְהוֹרָה:","הָיוּ טֻמְאוֹת וְטָהֳרוֹת בְּצִדּוֹ אוֹ לְמַעְלָה מִמֶּנּוּ וְנִתְעַטֵּף בְּטַלִּיתוֹ וְסָפֵק נָגְעוּ סָפֵק לֹא נָגְעוּ בְּעֵת שֶׁנִּתְעַטֵּף אִם הָיוּ בִּרְשׁוּת הַיָּחִיד סְפֵקוֹ טָמֵא. שֶׁסְּפֵק טֻמְאָה הַבָּאָה בִּידֵי אָדָם נִשְׁאָלִין עָלֶיהָ אֲפִלּוּ בִּכְלִי הַמֻּנָּח עַל גַּבֵּי קַרְקַע הֲרֵי הוּא כְּמִי שֶׁיֵּשׁ בּוֹ דַּעַת לִשָּׁאֵל. וְאִם הָיוּ בִּרְשׁוּת הָרַבִּים סְפֵקוֹ טָהוֹר וְאִם אִי אֶפְשָׁר שֶׁלֹּא יִגַּע סְפֵקוֹ טָמֵא:","כִּכָּר שֶׁל תְּרוּמָה שֶׁנָּתוּן עַל גַּבֵּי הַדַּף וּמִדְרָס נָתוּן תַּחְתָּיו וְאִי אֶפְשָׁר לוֹ כְּשֶׁיִּפּל שֶׁלֹּא יִגַּע בַּמִּדְרָס. אַף עַל פִּי שֶׁהוּא בִּמְקוֹם מִדְרוֹן וּבָא וּמָצָא הַכִּכָּר בְּמָקוֹם אַחֵר הֲרֵי הוּא בְּטָהֳרָתוֹ שֶׁאֲנִי אוֹמֵר אָדָם בָּא וּנְטָלוֹ וּנְתָנוֹ בְּמָקוֹם זֶה. וְאִם אָמַר בָּרִי לִי שֶׁלֹּא בָּא אָדָם לְכָאן טָמֵא שֶׁוַּדַּאי נָפַל וְנָגַע בַּמִּדְרָס כְּשֶׁנָּפַל:","תִּינוֹק שֶׁנִּמְצָא בְּצַד בֵּית הַקְּבָרוֹת וְהַשּׁוֹשַׁנִּים בְּיָדוֹ אַף עַל פִּי שֶׁאֵין שָׁם שׁוֹשַׁנִּים אֶלָּא בִּמְקוֹם הַטֻּמְאָה סְפֵקוֹ טָהוֹר שֶׁמָּא אַחֵר לִקְּטָן וּנְתָנָם לוֹ. וְכֵן חֲמוֹר הָעוֹמֵד בְּבֵית הַקְּבָרוֹת כֵּלָיו טְהוֹרִין וְאֵין אוֹמְרִין שֶׁמָּא נִתְמַעֵךְ בָּהֶן וְנָגְעוּ בַּקֶּבֶר מִפְּנֵי שֶׁאֵין בּוֹ דַּעַת לִשָּׁאֵל וּכְשֶׁנִּמְצְאוּ לֹא נִמְצְאוּ נוֹגְעִין וְכָל הַטֻּמְאוֹת כִּשְׁעַת מְצִיאָתָן:","תִּינוֹק שֶׁהָיָה תּוֹפֵשׂ בְּיָדוֹ שֶׁל אָבִיו אוֹ שֶׁהָיָה רוֹכֵב עַל גַּבֵּי כְּתֵפוֹ שֶׁל אָבִיו סְפֵקוֹ בִּרְשׁוּת הַיָּחִיד טָמֵא מִפְּנֵי שֶׁאָבִיו נִשְׁאָל עָלָיו:","וְאַרְבָּעָה סְפֵקוֹת אָמְרוּ חֲכָמִים בְּתִינוֹק. תִּינוֹק שֶׁאֵינוֹ יָכוֹל לְהַלֵּךְ שֶׁהִנִּיחַתּוּ אִמּוֹ וּבָאָה וּמְצָאַתּוּ כְּמוֹ שֶׁהוּא בִּמְקוֹמוֹ טָהוֹר וְאֵין אוֹמְרִין שֶׁמָּא טֻמְאָה בָּאָה וּנְשָׁקַתּוּ וְגִפַּפְתּוֹ. הִתְחִיל הַתִּינוֹק לָצֵאת וּלְהַכְנִיס בְּגָדָיו טְהוֹרִין וְאֵינָן מִדְרָס כִּשְׁאָר בִּגְדֵי עַם הָאָרֶץ. וְאַף עַל פִּי שֶׁהֵן טְהוֹרִין אֵין עוֹשִׂין עַל גַּבֵּיהֶן טָהֳרוֹת. הִגְדִּיל עַד שֶׁיִּהְיֶה בּוֹ דַּעַת לִשָּׁאֵל סְפֵקוֹ טָמֵא בִּרְשׁוּת הַיָּחִיד. הִגְדִּיל עַד שֶׁיִּהְיֶה בּוֹ דַּעַת לִשְׁמֹר אֶת גּוּפוֹ אוֹכְלִין עַל גּוּפוֹ טָהֳרוֹת. יוֹדֵעַ לִשְׁמֹר אֶת יָדָיו אוֹכְלִין עַל גַּבָּן טָהֳרוֹת. כֵּיצַד בּוֹדְקִין אוֹתוֹ. מַטְבִּילִין אוֹתוֹ וְנוֹתְנִין לוֹ חֻלִּין לְשֵׁם תְּרוּמָה אִם יוֹדֵעַ לִשְׁמֹר אֶת גּוּפוֹ אוֹכְלִין אַגַּב גּוּפוֹ טָהֳרוֹת וְאִם יוֹדֵעַ לִשְׁמֹר אֶת יָדָיו אוֹכְלִים אַגַּב יָדוֹ טָהֳרוֹת:"],"Mishneh Torah, Other Sources of Defilement 9":["הַבָּא רֹאשׁוֹ וְרֻבּוֹ בְּמַיִם שְׁאוּבִין אוֹ שֶׁנָּפְלוּ עַל רֹאשׁוֹ וְעַל רֻבּוֹ שְׁלֹשָׁה לוֹגִין מַיִם שְׁאוּבִין הֲרֵי הוּא כְּשֵׁנִי לְטֻמְאָה עַד שֶׁיִּטְבּל. וְאִם נָגַע בָּאֳכָלִין עֲשָׂאָן שְׁלִישִׁי. וְאִם נָגַע בְּמַשְׁקִין טְמֵאִים עֲשָׂאָן תְּחִלָּה לְטַמֵּא אֳכָלִים וּמַשְׁקִין אֲחֵרִים אֲבָל לֹא לְטַמֵּא כֵּלִים. וּמִפְּנֵי מָה גָּזְרוּ טֻמְאָה עַל אָדָם זֶה. מִפְּנֵי שֶׁהָיוּ טְבוּלֵי יוֹם טוֹבְלִין בִּמְעָרוֹת שֶׁמֵּימֵיהֶן רָעִים וְאַחַר כָּךְ הָיוּ רוֹחֲצִין בְּמַיִם שְׁאוּבִים יָפִים דֶּרֶךְ נְקִיּוּת וּפָשַׁט הַמִּנְהָג כָּךְ עַד שֶׁהָיוּ רֹב הָעָם מְדַמִּים שֶׁמַּיִם שְׁאוּבִים שֶׁרוֹחֲצִין בָּהֶן בָּאַחֲרוֹנָה הֵן שֶׁמְּטַהֲרִין לֹא הַטְּבִילָה שֶׁבְּמֵי מִקְוֶה וְהָיוּ טוֹבְלִין בְּזִלְזוּל בְּלֹא כַּוָּנָה. וּלְפִיכָךְ גָּזְרוּ שֶׁכָּל שֶׁבָּא רֹאשׁוֹ וְרֻבּוֹ בְּמַיִם שְׁאוּבִים אוֹ שֶׁנָּפְלוּ עַל רֹאשׁוֹ וְרֻבּוֹ נִטְמָא וְנַעֲשָׂה כְּשֵׁנִי לְטֻמְאָה. אֲפִלּוּ טָהוֹר שֶׁאֵינוֹ טְבוּל יוֹם אִם נָפְלוּ עַל רֹאשׁוֹ וְרֻבּוֹ שְׁלֹשָׁה לוֹגִין מַיִם שְׁאוּבִין אוֹ שֶׁבָּא רֹאשׁוֹ וְרֻבּוֹ בְּמַיִם שְׁאוּבִין הֲרֵי זֶה כְּשֵׁנִי לְטֻמְאָה עַד שֶׁיִּטְבּל. טָבַל אֵינוֹ צָרִיךְ הַעֲרֵב שֶׁמֶשׁ מִפְּנֵי שֶׁעִקַּר טֻמְאָה זוֹ מִדִּבְרֵיהֶן. וְכֵן הָאוֹכֵל אֳכָלִין טְמֵאִים וְהַשּׁוֹתֶה מַשְׁקִין טְמֵאִין וְטָבַל אֵינוֹ צָרִיךְ הַעֲרֵב שֶׁמֶשׁ. וְכֵן כֵּלִים שֶׁנִּטְמְאוּ בְּמַשְׁקִין כֵּיוָן שֶׁמַּטְבִּילָן טִהֲרוּ וְאֵין צְרִיכִין הַעֲרֵב שֶׁמֶשׁ מִפְּנֵי שֶׁטֻּמְאוֹת אֵלּוּ עִקָּרָן מִדִּבְרֵיהֶן:","מִי שֶׁנָּפְלוּ עָלָיו שְׁלֹשָׁה לוֹגִין מַיִם שְׁאוּבִין מִשְּׁנֵי כֵּלִים אוֹ מִשְּׁלֹשָׁה אִם הִתְחִיל הַשֵּׁנִי עַד שֶׁלֹּא פָּסַק הָרִאשׁוֹן מִצְטָרְפִין וְאִם לָאו אֵין מִצְטָרְפִין. נָפְלוּ מֵאַרְבָּעָה כֵּלִים אֵין מִצְטָרְפִים וְאַף עַל פִּי שֶׁהִתְחִיל זֶה עַד שֶׁלֹּא פָּסַק זֶה הֲרֵי זֶה טָהוֹר. נָפְלוּ עַל רֹאשׁוֹ אֲבָל לֹא עַל רֻבּוֹ אוֹ שֶׁנָּפְלוּ עַל רֻבּוֹ וְלֹא עַל רֹאשׁוֹ אוֹ שֶׁנָּפְלוּ עַל רֹאשׁוֹ בִּלְבַד מִלְּמַעְלָה וְעַל רֻבּוֹ נָפְלוּ מִן הַצַּד אוֹ מִלְּמַטָּה הֲרֵי זֶה טָהוֹר עַד שֶׁיִּפְּלוּ עַל רֹאשׁוֹ וְעַל רֻבּוֹ הַסָּמוּךְ לְרֹאשׁוֹ כְּדַרְכּוֹ. וְכֵן אִם בָּא רֹאשׁוֹ בְּמַיִם שְׁאוּבִין וְלֹא בָּא רֻבּוֹ אוֹ בָּא רֻבּוֹ וְלֹא בָּא רֹאשׁוֹ אוֹ שֶׁבָּא רֹאשׁוֹ בִּלְבַד וּבָא מִשְּׁאָר גּוּפוֹ וְרֻבּוֹ בְּמַיִם שְׁאוּבִין מִלְּמַטָּה אוֹ מִן הַצַּד הֲרֵי זֶה טָהוֹר עַד שֶׁיָּבוֹא רֹאשׁוֹ וְרֻבּוֹ הַסָּמוּךְ לְרֹאשׁוֹ כְּדַרְכּוֹ:","הַבָּא מֵרֹאשׁוֹ וְרֻבּוֹ הַחֵצִי בְּמַיִם שְׁאוּבִין וְנָפְלוּ עַל הַחֵצִי הָאַחֵר מַיִם שְׁאוּבִין הוֹאִיל וְחֶצְיוֹ בִּנְפִילָה וְחֶצְיוֹ בְּבִיאָה טָהוֹר:","הָיוּ שְׁלֹשֶׁת הַלּוֹגִין שֶׁנָּפְלוּ עָלָיו אוֹ שֶׁבָּא בָּהֶן מִקְצָתָן שְׁאוּבִין וּמִקְצָתָן אֵינָן שְׁאוּבִין אוֹ שֶׁנִּתְעָרֵב בָּהֶן יַיִן דְּבַשׁ וְחָלָב הֲרֵי זֶה טָהוֹר עַד שֶׁיִּהְיוּ הַשְּׁלֹשָׁה כֻּלָּן מַיִם שְׁאוּבִין. שְׁלֹשֶׁת לוֹגִין אֵלּוּ שֶׁנָּפְלוּ עַל הַטָּהוֹר אוֹ שֶׁבָּא בָּהֶן וְטִמְּאוּהוּ כֵּיוָן שֶׁנַּעֲשָׂה כְּשֵׁנִי לְטֻמְאָה הֲרֵי הַמַּיִם הָאֵלּוּ טְמֵאִין שֶׁהֲרֵי נָגְעוּ בְּשֵׁנִי וַהֲרֵי אֵלּוּ הַמַּיִם אוֹמְרִין לָזֶה הַטָּהוֹר טִמֵּאנוּ אוֹתוֹ וְטִמְּאָנוּ:","בָּרִאשׁוֹנָה הָיוּ מַנִּיחִין כִּכָּרוֹת שֶׁל תְּרוּמָה בְּצַד הַסְּפָרִים וְאוֹמְרִים זֶה קֹדֶשׁ וְזֶה קֹדֶשׁ וּבָאִין הָעַכְבָּרִים וְקוֹרְעִין אֶת הַסְּפָרִים לְפִיכָךְ גָּזְרוּ שֶׁכָּל תְּרוּמָה שֶׁתִּגַּע בְּאֶחָד מִכִּתְבֵי הַקֹּדֶשׁ נִטְמֵאת וַהֲרֵי הִיא כִּשְׁלִישִׁי לְטֻמְאָה כְּאִלּוּ נָגְעוּ בְּשֵׁנִי וְנִמְצְאוּ כָּל כִּתְבֵי הַקֹּדֶשׁ פּוֹסְלִין אֶת הַתְּרוּמָה כְּשֵׁנִי. וְלֹא עוֹד אֶלָּא מִי שֶׁהָיוּ יָדָיו טְהוֹרוֹת וְנָגַע בְּאֶחָד מִכִּתְבֵי הַקֹּדֶשׁ נַעֲשׂוּ יָדָיו שְׁנִיּוֹת וּמְטַמְּאִין אֶת הַתְּרוּמָה וְאֶת הַמַּשְׁקִין וְאַף עַל פִּי שֶׁאֵין הַיָּדַיִם מִתְטַמְּאוֹת אֶלָּא מֵרִאשׁוֹן לְטֻמְאָה כְּמוֹ שֶׁבֵּאַרְנוּ הֵן מִתְטַמְּאוֹת מִן הַסֵּפֶר:","רְצוּעוֹת תְּפִלִּין עִם הַתְּפִלִּין וְגִלָּיוֹן שֶׁבַּסֵּפֶר שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה שֶׁבַּתְּחִלָּה וְשֶׁבַּסּוֹף כְּשֶׁהֵן מְחֻבָּרִין לְסֵפֶר. וְסֵפֶר שֶׁנִּמְחַק וְנִשְׁתַּיֵּר בּוֹ שְׁמוֹנִים וְחָמֵשׁ אוֹתִיּוֹת. וּמְגִלָּה שֶׁכָּתוּב בָּהּ מִן הַתּוֹרָה שְׁמוֹנִים וְחָמֵשׁ אוֹתִיּוֹת כְּפָרָשַׁת (במדבר י לה) \"וַיְהִי בִּנְסֹעַ הָאָרֹן\". הֲרֵי אֵלּוּ מְטַמְּאִין אֶת הַיָּדַיִם. וְלֹא דִּבְרֵי תּוֹרָה בִּלְבַד אֶלָּא כָּל כִּתְבֵי הַקֹּדֶשׁ אֲפִלּוּ שִׁיר הַשִּׁירִים וְקֹהֶלֶת שֶׁהֵן דִּבְרֵי חָכְמָה מְטַמְּאִין אֶת הַיָּדַיִם:","תַּרְגּוּם שֶׁבְּעֶזְרָא וְשֶׁבְּדָנִיֵּאל הֲרֵי הוּא מִכְּלַל כִּתְבֵי הַקֹּדֶשׁ. אֲבָל תַּרְגּוּם שֶׁכְּתָבוֹ עִבְרִית וְעִבְרִית שֶׁכְּתָבוֹ תַּרְגּוּם אוֹ שֶׁכָּתַב כִּתְבֵי הַקֹּדֶשׁ בִּכְתָב עִבְרִי אֵינָן מְטַמְּאִין אֶת הַיָּדַיִם עַד שֶׁיִּהְיוּ כְּתוּבִים אַשּׁוּרִית עַל הָעוֹר וּבִדְיוֹ:","הַכּוֹתֵב הַלֵּל וּשְׁמַע לְתִינוֹק לְהִתְלַמֵּד בּוֹ אַף עַל פִּי שֶׁאֵינוֹ רַשַּׁאי הֲרֵי אֵלּוּ מְטַמְּאִין אֶת הַיָּדַיִם:","הַמְּשִׁיחוֹת וְהָרְצוּעוֹת שֶׁתְּפָרָן לְסֵפֶר אַף עַל פִּי שֶׁאֵינוֹ רַשַּׁאי לְקַיְּמָן כָּל זְמַן שֶׁהֵן מְחֻבָּרִין לַסֵּפֶר מְטַמְּאִין אֶת הַיָּדַיִם:","תִּיק שֶׁל סֵפֶר וּמִטְפָּחוֹת סְפָרִים בִּזְמַן שֶׁהֵן תְּפוּרוֹת מְטַמְּאִין אֶת הַיָּדַיִם. אֲבָל הַבְּרָכוֹת אַף עַל פִּי שֶׁיֵּשׁ בָּהֶן מֵאוֹתִיּוֹת שֶׁל שֵׁם וּמֵעִנְיָנִים הַרְבֵּה שֶׁל תּוֹרָה אֵינָן מְטַמְּאִין אֶת הַיָּדַיִם:","סִפְרֵי הַמִּינִים אֵינָן מְטַמְּאִין אֶת הַיָּדַיִם. פָּרָשַׁת סוֹטָה הוֹאִיל וְלִמְחִיקָה עוֹמֶדֶת אֵינָהּ מְטַמְּאָה אֶת הַיָּדַיִם:"],"Mishneh Torah, Overview of Mishneh Torah Contents 7":["ספר זרעים","הלכותיו שבע, וזה הוא סידורן: הלכות כלאיים, הלכות מתנות עניים, הלכות תרומות, הלכות מעשרות, הלכות מעשר שני ונטע רבעי, הלכות ביכורים ושאר מתנות כהונה שבגבולין, הלכות שמיטה ויובל.","הלכות כלאיים. יש בכללן חמש מצוות לא תעשה; וזה הוא פרטן: (א) שלא לזרוע זרעים כלאיים; (ב) שלא לזרוע תבואה או ירק בכרם; (ג) שלא להרביע בהמה כלאיים; (ד) שלא לעשות מלאכה בכלאי בהמה כאחד; (ה) שלא ללבוש כלאיים.","הלכות מתנות עניים. יש בכללן שלוש עשרה מצוות – שבע מצוות עשה, ושש מצוות לא תעשה; וזה הוא פרטן: (א) להניח פיאה; (ב) שלא יכלה הפיאה; (ג) להניח לקט; (ד) שלא ילקט הלקט; (ה) לעזוב עוללות בכרם; (ו) שלא יעולל הכרם; (ז) לעזוב פרט הכרם; (ח) שלא ילקט פרט הכרם; (ט) להניח השכחה; (י) שלא ישוב לקחת השכחה; (יא) להפריש מעשר לעניים; (יב) ליתן צדקה כמיסת יד; (יג) שלא יאמץ לבבו על העני.","הלכות תרומות. יש בכללן שמונה מצוות – שתיים מצוות עשה, ושש מצוות לא תעשה; וזה הוא פרטן: (א) להפריש תרומה גדולה; (ב) להפריש תרומת מעשר; (ג) שלא יקדים תרומות ומעשרות זה לזה, אלא יפריש על הסדר; (ד) שלא יאכל זר תרומה; (ה) שלא יאכל אפילו תושב כוהן או שכירו תרומה; (ו) שלא יאכל ערל תרומה; (ז) שלא יאכל כוהן טמא תרומה; (ח) שלא תאכל חללה תרומה, ולא מורם מן הקודשים.","הלכות מעשר. מצות עשה אחת, והיא להפריש מעשר ראשון בכל שנה ושנה משני הזריעה וייתנו ללויים.","הלכות מעשר שני ונטע רבעי. יש בכללן תשע מצוות – שלוש מצוות עשה, ושש מצוות לא תעשה; וזה הוא פרטן: (א) להפריש מעשר שני; (ב) שלא להוציא דמיו בשאר צורכי האדם, חוץ מאכילה ושתייה וסיכה; (ג) שלא לאוכלו בטומאה; (ד) שלא לאוכלו באנינות; (ה) שלא לאכול מעשר שני של דגן חוץ לירושלים; (ו) שלא לאכול מעשר תירוש חוץ לירושלים; (ז) שלא לאכול מעשר יצהר חוץ לירושלים; (ח) להיות נטע רבעי כולו קודש, ודינו להיאכל בירושלים לבעליו כמעשר שני לכל דבר; (ט) להתוודות וידוי מעשר.","הלכות ביכורים עם שאר מתנות כהונה שבגבולין. יש בכללן תשע מצוות – שמונה מצוות עשה, ואחת מצות לא תעשה; וזה הוא פרטן: (א) להפריש ביכורים ולהעלותן למקדש; (ב) שלא יאכל הכוהן ביכורים חוץ לירושלים; (ג) לקרות עליהן; (ד) להפריש חלה לכוהן; (ה) לתת זרוע ולחיים וקיבה לכוהן; (ו) ליתן לו ראשית הגז; (ז) לפדות בכור הבן וליתן פדיונו לכוהן; (ח) לפדות פטר חמור וליתן פדיונו לכוהן; (ט) לערוף פטר חמור, אם לא רצה לפדותו.","הלכות שמיטה ויובל. יש בכללן שתיים ועשרים מצוות – תשע מצוות עשה, ושלוש עשרה מצוות לא תעשה; וזה הוא פרטן: (א) שתשבות הארץ ממלאכתה בשביעית; (ב) שלא יעבוד עבודת הארץ בשנה זו; (ג) שלא יעבוד עבודת האילן בשנה זו; (ד) שלא יקצור הספיח כנגד הקוצרים; (ה) שלא יבצור הנזירים כנגד הבוצרים; (ו) שישמיט מה שתוציא הארץ; (ז) שישמיט כל הלוואתו; (ח) שלא ייגוש ולא יתבע הלוואה; (ט) שלא יימנע מלהלוות קודם השמיטה כדי שלא יאבד ממונו; (י) לספור שנים שבע שבע; (יא) לקדש שנת החמישים; (יב) לתקוע בשופר בעשירי לתשרי כדי לצאת עבדים חופשיים; (יג) שלא תעבוד אדמה בשנה זו; (יד) שלא יקצור ספיחיה כנגד הקוצרים; (טו) שלא יבצור נזיריה כנגד הבוצרים; (טז) ליתן גאולה לארץ בשנה זו, והוא דין שדה אחוזה ושדה מקנה; (יז) שלא תימכר הארץ לצמיתות; (יח) דין בתי ערי חומה; (יט) שלא ינחל כל שבט לוי בארץ ישראל, אלא נותנים להם ערים מתנה לשבת בהם; (כ) שלא ייקח שבט לוי חלק בביזה; (כא) ליתן ללויים ערים לשבת ומגרשיהם; (כב) שלא יימכר מגרש עריהם, אלא גואלים לעולם בין לפני היובל בין לאחר היובל.","נמצאו כל המצוות הנכללות בספר זה, שבע ושישים – מהן שלושים מצוות עשה, ושבע ושלושים מצוות לא תעשה."],"Mishneh Torah, Ownerless Property and Gifts 7":["מִנְּהָג פָּשׁוּט בְּרֹב הַמְּדִינוֹת שֶׁבִּזְמַן שֶׁיִּשָּׂא אָדָם אִשָּׁה מְשַׁלְּחִין לוֹ רֵעָיו וּמְיֻדָּעָיו מָעוֹת כְּדֵי שֶׁיִּתְחַזֵּק בָּהֶן עַל הַהוֹצָאָה שֶׁמּוֹצִיא בְּאִשְׁתּוֹ. וּבָאִים אוֹתָן הָרֵעִים וְהַמְיֻדָּעִים שֶׁשָּׁלְחוּ לוֹ וְאוֹכְלִין וְשׁוֹתִין עִם הֶחָתָן בְּשִׁבְעַת יְמֵי הַמִּשְׁתֶּה אוֹ בְּמִקְצָתָן. הַכּל כְּמִנְהַג הַמְּדִינָה. וְאֵלּוּ הַמָּעוֹת שֶׁמְּשַׁלְּחִין נִקְרָאִין שׁוֹשְׁבִינוּת. וְאוֹתָם שֶׁשָּׁלְחוּ הַמָּעוֹת וְאוֹכְלִין וְשׁוֹתִין עִם הֶחָתָן נִקְרָאִים שׁוֹשְׁבִינִין:","הַשּׁוֹשְׁבִינוּת אֵינָהּ מַתָּנָה גְּמוּרָה. הַדְּבָרִים יְדוּעִים שֶׁלֹּא שָׁלַח זֶה עֲשָׂרָה דִּינָרִין בִּשְׁבִיל שֶׁיֹּאכַל וְיִשְׁתֶּה בָּזֶה וְלֹא שָׁלַח אֶלָּא מִפְּנֵי שֶׁבְּדַעְתּוֹ הָיָה שֶׁאִם יִשָּׂא הוּא אִשָּׁה יַחְזֹר וְיִשְׁלַח לוֹ כְּמוֹ שֶׁשָּׁלַח לוֹ. לְפִיכָךְ אִם נָשָׂא זֶה אִשָּׁה וְלֹא הֶחְזִיר לוֹ הַשּׁוֹשְׁבִינוּת הֲרֵי זֶה תּוֹבְעוֹ בְּדִין וּמוֹצִיא מִמֶּנּוּ:","וְאֵין יָכוֹל לְתָבְעוֹ עַד שֶׁיִּשָּׂא כְּדֶרֶךְ שֶׁנָּשָׂא הוּא. כֵּיצַד. רְאוּבֵן שֶׁנָּשָׂא בְּתוּלָה וְשָּׁלַח לוֹ שִׁמְעוֹן שׁוֹשְׁבִינוּת וְאַחַר כָּךְ נָשָׂא שִׁמְעוֹן אַלְמָנָה. אֵינוֹ יָכוֹל לִתְבֹּעַ לְהַחְזִיר לוֹ הַשּׁוֹשְׁבִינוּת שֶׁהֲרֵי אוֹמֵר לוֹ אֵינִי מַחְזִיר לְךָ אֶלָּא בִּבְתוּלָה כְּמוֹ שֶׁנָּתַתָּ לִי. וְכֵן אִם שָׁלַח לוֹ בְּנִשּׂוּאֵי אַלְמָנָה אֵינוֹ יָכוֹל לְתָבְעוֹ לְהַחְזִיר לוֹ בְּנִשּׂוּאֵי בְּתוּלָה:","עָשָׂה רְאוּבֵן מִשְׁתֶּה בְּגָלוּי וּבְפַרְהֶסְיָא וְעָשָׂה שִׁמְעוֹן בְּצִנְעָה. אוֹ שֶׁעָשָׂה רְאוּבֵן בְּצִנְעָה וְשִׁמְעוֹן בְּפַרְהֶסְיָא אֵינוֹ יָכוֹל לְתָבְעוֹ. שֶׁהֲרֵי אוֹמֵר לוֹ אֵינִי עוֹשֶׂה עִמְּךָ אֶלָּא כְּדֶרֶךְ שֶׁעָשִׂיתָ עִמִּי:","רְאוּבֵן שֶׁנָּשָׂא אִשָּׁה וְשָׁלַח לוֹ שִׁמְעוֹן שׁוֹשְׁבִינוּת וְאָכַל וְשָׁתָה עִמּוֹ וְאַחַר כָּךְ נָשָׂא שִׁמְעוֹן כְּנִשּׂוּאֵי רְאוּבֵן עַצְמָן וּבָא רְאוּבֵן וְאָכַל וְשָׁתָה עִמּוֹ. אוֹ שֶׁקָּרָא לוֹ שִׁמְעוֹן וְלֹא רָצָה לָבוֹא. אוֹ שֶׁהָיָה בַּמְּדִינָה וְשָׁמַע קוֹל טַבְלָא בְּמָקוֹם שֶׁאֵין דַּרְכָּן לִקְרוֹת אֶחָד אֶחָד אֶלָּא כָּל הַשּׁוֹמֵעַ יָבוֹא. וְשָׁמַע וְלֹא בָּא. חַיָּב לְהַחְזִיר לוֹ הַשּׁוֹשְׁבִינוּת כֻּלָּהּ. שֶׁהֲרֵי יָדַע וְלֹא בָּא אוֹ קָרָא לוֹ בְּמָקוֹם שֶׁדַּרְכָּן לִקְרוֹת אֶחָד אֶחָד וְלֹא בָּא:","לֹא הָיָה רְאוּבֵן בַּמְּדִינָה מְנַכִּין לוֹ דְּמֵי מַה שֶּׁאָכַל וְשָׁתָה שִׁמְעוֹן אֶצְלוֹ וּמַחֲזִיר לוֹ שְׁאָר הַשּׁוֹשְׁבִינוּת. וְכֵן אִם הָיָה בַּמְּדִינָה וְלֹא קְרָאָהוּ אוֹ לֹא הוֹדִיעוֹ מְנַכִּין לוֹ וְיֵשׁ לוֹ עָלָיו תַּרְעֹמֶת מִפְּנֵי שֶׁלֹּא הוֹדִיעוֹ:","וְכַמָּה מְנַכִּין. נָהֲגוּ בְּנִכּוּי אִם דִּינָר אֶחָד שָׁלַח לוֹ שִׁמְעוֹן אֵינוֹ מַחְזִיר לוֹ כְּלוּם שֶׁהֲרֵי זֶה דְּמֵי מַה שֶּׁאָכַל. וְאִם יִתֵּר עַל הַדִּינָר עַד סֶלַע מְנַכֶּה לוֹ מֶחֱצָה. מִסֶּלַע וּלְמַעְלָה אוֹמְדִין דַּעַת הַמְשַׁלֵּחַ:","וְשִׁעוּר הַשּׁוֹשְׁבִינוּת אִם אָדָם חָשׁוּב מְנַכֶּה לוֹ מֶחֱצָה. וְאִם צַר עַיִן וּמְדַקְדֵּק בְּהוֹצָאָתוֹ אֵינוֹ מְנַכֶּה לוֹ אֶלָּא שִׁעוּר מַה שֶּׁאָכַל וְשָׁתָה וּמְשַׁלֵּם לוֹ הַשְּׁאָר:","מֵת שִׁמְעוֹן קֹדֶם שֶׁיִּשָּׂא אִשָּׁה אוֹ שֶׁנָּשָׂא וּמֵת בְּתוֹךְ יְמֵי הַמִּשְׁתֶּה אֵין רְאוּבֵן חַיָּב לְהַחְזִיר לְיוֹרְשֵׁי שִׁמְעוֹן כְּלוּם שֶׁהֲרֵי אוֹמֵר לָהֶם תְּנוּ לִי שׁוֹשְׁבִינִי וְאֶשְׂמַח עִמּוֹ:","לְפִיכָךְ אִם שָׂמַח עִמּוֹ וְאַחַר כָּךְ מֵת שִׁמְעוֹן. אוֹ קָרָא לוֹ וְלֹא בָּא אוֹ שֶׁלֹּא הָיָה בַּמְּדִינָה אוֹ שֶׁלֹּא הוֹדִיעוֹ. הוֹאִיל וְשָׁלְמוּ יְמֵי הַמִּשְׁתֶּה וְאַחַר כָּךְ מֵת שִׁמְעוֹן. חַיָּב רְאוּבֵן לְהַחְזִיר הַשּׁוֹשְׁבִינוּת לְיוֹרְשָׁיו אוֹ כֻּלָּהּ אוֹ בְּנִכּוּי אִם לֹא הוֹדִיעוֹ אוֹ לֹא הָיָה עִמּוֹ בַּמְּדִינָה:","מֵת רְאוּבֵן וְאַחַר כָּךְ נָשָׂא שִׁמְעוֹן אִשָּׁה וְשָׁלְמוּ יְמֵי הַמִּשְׁתֶּה. מָקוֹם שֶׁנָּהֲגוּ לִגְבּוֹת הַשּׁוֹשְׁבִינוּת מִיּוֹרְשִׁין כּוֹפִין יוֹרְשֵׁי רְאוּבֵן לְהַחְזִיר בְּנִכּוּי. וּמָקוֹם שֶׁלֹּא נָהֲגוּ אֵין הַיּוֹרְשִׁין מְשַׁלְּמִין כְּלוּם:","מֵת רְאוּבֵן אַחַר שֶׁנָּשָׂא שִׁמְעוֹן אִשָּׁה וְשָׁלְמוּ יְמֵי הַמִּשְׁתֶּה. כּוֹפִין אֶת יוֹרְשָׁיו וּמְשַׁלְּמִין הַשּׁוֹשְׁבִינוּת בְּכָל מָקוֹם. שֶׁהֲרֵי נִתְחַיֵּב אֲבִיהֶן לְשַׁלֵּם. וְאִם כֻּלָּהּ הָיָה חַיָּב לְשַׁלֵּם מְשַׁלְּמִין כֻּלָּהּ. וְאִם בְּנִכּוּי מְשַׁלְּמִין בְּנִכּוּי:","חֲמִשָּׁה דְּבָרִים נֶאֶמְרוּ בַּשּׁוֹשְׁבִינוּת. נִגְבֵּית בְּבֵית דִּין שֶׁאֵינָהּ אֶלָּא כְּמוֹ מִלְוֶה. וְאֵינָהּ מִשְׁתַּלֶּמֶת אֶלָּא בְּעוֹנָתָהּ כְּעֵין נִשּׂוּאֵי רִאשׁוֹן. שֶׁזֶּה כְּמוֹ תְּנַאי הוּא אַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ שֶׁעַל דַּעַת זֶה שְׁלָחָהּ. וְאֵין בָּהּ מִשּׁוּם רִבִּית. אֲפִלּוּ שָׁלַח לוֹ דִּינָר וְהֶחְזִיר לוֹ עֲשָׂרָה מֻתָּר שֶׁלֹּא עַל מְנָת לְהוֹסִיף לוֹ שָׁלַח. וְאֵין הַשְּׁבִיעִית מְשַׁמַּטְתָּהּ שֶׁאֵינוֹ יָכוֹל לִגּשֹׁ אוֹתוֹ וּלְתָבְעוֹ עַד שֶׁיִּשָּׂא כְּדֶרֶךְ שֶׁנָּשָׂא הוּא. וְאֵין הַבְּכוֹר נוֹטֵל בָּהּ פִּי שְׁנַיִם כְּשֶׁתַּחְזֹר לַיּוֹרְשִׁין מִפְּנֵי שֶׁהוּא רָאוּי וְאֵין הַבְּכוֹר נוֹטֵל בָּרָאוּי כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","הַשּׁוֹלֵחַ תְּשׁוּרָה לַחֲבֵרוֹ. אוֹ שֶׁנָּתַן לוֹ מָעוֹת כְּשֶׁמָּטָה יָדוֹ וְהוּא מְמָאֵן לִקַּח. וְזֶה נִשְׁבָּע שֶׁאִי אֶפְשָׁר שֶׁלֹּא תִּקַּח וְהִפְצִיר בּוֹ עַד שֶׁלָּקַח. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן. אַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ הֲרֵי אֵלּוּ מַתָּנָה. וְאֵינוֹ יָכוֹל לַחְזֹר הוּא וְלִתְבֹּעַ עַד שֶׁיְּפָרֵשׁ שֶׁהוּא מִלְוֶה:","וְכֵן הַשּׁוֹלֵחַ לַחֲבֵרוֹ כַּדֵּי יַיִן וְכַדֵּי שֶׁמֶן וּפֵרוֹת בְּעֵת הַנִּשּׂוּאִין. אֵין נִגְבִּין בְּבֵית דִּין. מִפְּנֵי שֶׁהִיא גְּמִילוּת חֲסָדִים. וְלֹא נֶאֶמְרוּ דִּינֵי שׁוֹשְׁבִינוּת אֶלָּא בְּמָעוֹת בִּלְבַד:"],"Mishneh Torah, Paschal Offering 9":["כָּל הָאוֹכֵל מִן הַפֶּסַח אֵינוֹ אוֹכֵל אֶלָּא בַּחֲבוּרָה אַחַת וְאֵין מוֹצִיאִין מִמֶּנּוּ מִן הַחֲבוּרָה שֶׁיֹּאכַל בָּהּ. וְהַמּוֹצִיא מִמֶּנּוּ כְּזַיִת בָּשָׂר מֵחֲבוּרָה לַחֲבוּרָה בְּלֵיל חֲמִשָּׁה עָשָׂר לוֹקֶה שֶׁנֶּאֱמַר (שמות יב מו) \"לֹא תוֹצִיא מִן הַבַּיִת מִן הַבָּשָׂר חוּצָה\". וְהוּא שֶׁיַּנִּיחֵנוּ בַּחוּץ. שֶׁהוֹצָאָה כְּתוּבָה בּוֹ כְּשַׁבָּת לְפִיכָךְ צָרִיךְ עֲקִירָה וְהַנָּחָה כְּהוֹצָאַת שַׁבָּת. וְאֵין מוֹצִיא אַחַר מוֹצִיא בְּפֶסַח שֶׁכֵּיוָן שֶׁהוֹצִיאוֹ הָרִאשׁוֹן נִפְסַל. מִן הָאֲגַף וּלְפָנִים כִּלְפָנִים מִן הָאֲגַף וְלַחוּץ כְּלַחוּץ וְהָאֲגַף עַצְמוֹ שֶׁהוּא עֳבִי הַפֶּתַח כְּלַחוּץ. הַחַלּוֹנוֹת וָעֳבִי הַכְּתָלִים כִּלְפָנִים. הַגַּגִּים וְהָעֲלִיּוֹת אֵינָן בִּכְלַל הַבַּיִת:","בְּשַׂר הַפֶּסַח שֶׁיָּצָא חוּץ לַחֲבוּרָתוֹ בֵּין בְּזָדוֹן בֵּין בִּשְׁגָגָה נֶאֱסַר בַּאֲכִילָה וַהֲרֵי הוּא כִּבְשַׂר קָדְשֵׁי קָדָשִׁים שֶׁיָּצָא חוּץ לַעֲזָרָה אוֹ בְּשַׂר קָדָשִׁים קַלִּים שֶׁיָּצָא חוּץ לְחוֹמוֹת יְרוּשָׁלַיִם שֶׁהַכּל כִּטְרֵפָה. וְלוֹקִין עַל אֲכִילָתוֹ כְּמוֹ שֶׁבֵּאַרְנוּ בְּמַעֲשֵׂה הַקָּרְבָּנוֹת. אֵיבָר שֶׁיָּצָא מִקְצָתוֹ חוֹתֵךְ הַבָּשָׂר וְיוֹרֵד עַד שֶׁמַּגִּיעַ לָעֶצֶם וְקוֹלֵף אֶת הַבָּשָׂר כָּל שֶׁבִּפְנִים יֹאכַל וְכָל שֶׁבַּחוּץ יִשָּׂרֵף. כְּשֶׁהוּא מַגִּיעַ לָעֶצֶם חוֹתֵךְ בְּקוֹפִיץ אִם הָיָה שְׁאָר קָדָשִׁים. וְאִם הָיָה פֶּסַח שֶׁאָסוּר לִשְׁבֹּר בּוֹ עֶצֶם קוֹלֵף עַד הַפֶּרֶק וּמְפָרֵק הָאֵיבָר שֶׁיָּצָא מִקְצָתוֹ מִן הַפֶּרֶק וּמַשְׁלִיכוֹ לַחוּץ:","שְׁתֵּי חֲבוּרוֹת שֶׁהָיוּ אוֹכְלוֹת בְּבַיִת אֶחָד צְרִיכָה כָּל חֲבוּרָה מֵהֶן לַעֲשׂוֹת לָהּ הֶקֵּף שֶׁנֶּאֱמַר (שמות יב מו) \"מִן הַבָּשָׂר חוּצָה\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁצָּרִיךְ לִתֵּן לוֹ חוּצָה לִמְקוֹם אֲכִילָתוֹ. וְאֵלּוּ הוֹפְכִין אֶת פְּנֵיהֶן אֵילָךְ וְאוֹכְלִין וְאֵלּוּ הוֹפְכִין אֶת פְּנֵיהֶן אֵילָךְ וְאוֹכְלִין כְּדֵי שֶׁלֹּא יֵרָאוּ מְעֹרָבִים:","הָיוּ הַמַּיִם שֶׁמּוֹזְגִים בּוֹ יֵינָם בְּאֶמְצַע הַבַּיִת בֵּין שְׁתֵּי הַחֲבוּרוֹת. כְּשֶׁהַשַּׁמָּשׁ עוֹמֵד לִמְזֹג קוֹפֵץ אֶת פִּיו וּמַחֲזִיר אֶת פָּנָיו עַד שֶׁמַּגִּיעַ אֵצֶל חֲבוּרָתוֹ וְאַחַר כָּךְ אוֹכֵל מַה שֶּׁבְּפִיו. שֶׁאָסוּר לָאוֹכֵל לֶאֱכל בִּשְׁתֵּי חֲבוּרוֹת. וּמֻתָּר לְכַלָּה לְהַחְזִיר פָּנֶיהָ מִפְּנֵי חֲבוּרָתָהּ וְאוֹכֶלֶת מִפְּנֵי שֶׁהִיא בּוֹשָׁה לֶאֱכל בִּפְנֵיהֶם:","שְׁתֵּי חֲבוּרוֹת שֶׁנִּפְרְצָה מְחִצָּה מִבֵּינֵיהֶן אֵינָן אוֹכְלִין. וְכֵן אִם הָיְתָה חֲבוּרָה אַחַת וְנַעֲשֵׂית מְחִצָּה בֵּינֵיהֶן אֵינָן אוֹכְלִין עַד שֶׁתִּסְתַּלֵּק. שֶׁאֵין הַפֶּסַח נֶאֱכָל בִּשְׁתֵּי חֲבוּרוֹת וְאֵינָן נֶעֱקָרִין מֵחֲבוּרָה לַחֲבוּרָה:","בְּנֵי חֲבוּרָה שֶׁנִּכְנְסוּ שְׁלֹשָׁה מֵהֶן אוֹ יֶתֶר לֶאֱכל פִּסְחֵיהֶן וְלֹא בָּאוּ שְׁאָר בְּנֵי חֲבוּרָה. אִם נִכְנְסוּ בְּשָׁעָה שֶׁדֶּרֶךְ בְּנֵי אָדָם לֶאֱכל הַפְּסָחִים וְחָזַר הַמְעוֹרֵר לְכֻלָּן עַל הַשְּׁאָר וְלֹא בָּאוּ הֲרֵי אֵלּוּ שֶׁנִּכְנְסוּ אוֹכְלִין עַד שֶׁיִּשְׂבְּעוּ וְאֵין מַמְתִּינִים לַשְּׁאָר. וַאֲפִלּוּ בָּאוּ הַמִּתְאַחֲרִין אַחַר כָּךְ וּמָצְאוּ אֵלּוּ הַשְּׁלֹשָׁה שֶׁאָכְלוּ הַכּל אֵין מְשַׁלְּמִים לָהֶן כְּדֵי חֶלְקָם. אֲבָל אִם נִכְנְסוּ שְׁנַיִם בִּלְבַד הֲרֵי אֵלּוּ מַמְתִּינִים. בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁעַת כְּנִיסָתָן לֶאֱכל אֲבָל בְּעֵת שֶׁנִּפְטָרִין אֵין אָדָם צָרִיךְ לְהַמְתִּין לַחֲבֵרוֹ אֲפִלּוּ גָּמַר אֶחָד בִּלְבַד מִלֶּאֱכל יֵצֵא וְאֵינוֹ צָרִיךְ לְהַמְתִּין:","הַמַּאֲכִיל כְּזַיִת מִן הַפֶּסַח בֵּין מִפֶּסַח רִאשׁוֹן בֵּין מִפֶּסַח שֵׁנִי לְמוּמָר לַעֲבוֹדָה זָרָה אוֹ לְגֵר תּוֹשָׁב אוֹ לְשָׂכִיר. הֲרֵי זֶה עוֹבֵר בְּלֹא תַּעֲשֶׂה וְאֵינוֹ לוֹקֶה אֲבָל מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וּ (שמות יב מג) \"בֶן נֵכָר\" הָאָמוּר בַּתּוֹרָה זֶה הָעוֹבֵד אֵל נֵכָר. וְאֵין מַאֲכִילִין מִמֶּנּוּ לְנָכְרִי אֲפִלּוּ גֵּר תּוֹשָׁב אוֹ שָׂכִיר שֶׁנֶּאֱמַר (שמות יב מה) \"תּוֹשָׁב וְשָׂכִיר לֹא יֹאכַל בּוֹ\":","עָרֵל שֶׁאָכַל כְּזַיִת מִבְּשַׂר הַפֶּסַח לוֹקֶה שֶׁנֶּאֱמַר (שמות יב מח) \"כָּל עָרֵל לֹא יֹאכַל בּוֹ\". בּוֹ הוּא שֶׁאֵינוֹ אוֹכֵל אֲבָל אוֹכֵל הוּא מַצָּה וּמָרוֹר. וְכֵן מֻתָּר לְהַאֲכִיל מַצָּה וּמָרוֹר לְגֵר תּוֹשָׁב וּלְשָׂכִיר:","כְּשֵׁם שֶׁמִּילַת בָּנָיו וַעֲבָדָיו מְעַכַּבְתּוֹ מִלִּשְׁחֹט הַפֶּסַח כָּךְ מְעַכַּבְתּוֹ מִלֶּאֱכל שֶׁנֶּאֱמַר (שמות יב מד) \"וּמַלְתָּה אֹתוֹ אָז יֹאכַל בּוֹ\". כֵּיצַד. קָנָה עֶבֶד אַחַר שֶׁנִּשְׁחַט הַפֶּסַח. אוֹ שֶׁהָיָה לוֹ בֵּן שֶׁלֹּא הִגִּיעַ זְמַנּוֹ לְהִמּוֹל אֶלָּא אַחַר שְׁחִיטַת הַפֶּסַח. הֲרֵי זֶה אָסוּר לֶאֱכל עַד שֶׁיָּמוּל אוֹתָן. וְכֵיצַד יִהְיֶה הַבֵּן רָאוּי לְמִילָה אַחַר שְׁחִיטַת הַפֶּסַח וְלֹא יִהְיֶה רָאוּי קֹדֶם שְׁחִיטָה. כְּגוֹן שֶׁחֲלַצְתּוֹ חַמָּה שֶׁצָּרִיךְ שִׁבְעַת יָמִים מֵעֵת לְעֵת מִיּוֹם הַבְרָאָתוֹ. וּכְגוֹן שֶׁכָּאֲבָה עֵינוֹ וְנִרְפֵּאת אַחַר שְׁחִיטָה. אוֹ שֶׁהָיָה טֻמְטוּם וְנִקְרַע אַחַר שְׁחִיטַת הַפֶּסַח וְנִמְצָא זָכָר:"],"Mishneh Torah, Plaintiff and Defendant 5":["וְאֵלוּ דְּבָרִים שֶׁאֵין נִשְׁבָּעִין עֲלֵיהֶן מִן הַתּוֹרָה. הַקַּרְקָעוֹת וְהָעֲבָדִים וְהַשְּׁטָרוֹת וְהַהֶקְדֵּשׁוֹת. אַף עַל פִּי שֶׁהוֹדָה בְּמִקְצָת אוֹ שֶׁיֵּשׁ עָלָיו עֵד אֶחָד אוֹ שֶׁשָּׁמַר וְטָעַן טַעֲנַת הַשּׁוֹמְרִין הֲרֵי זֶה פָּטוּר. שֶׁנֶּאֱמַר (שמות כב ו) \"כִּי יִתֵּן אִישׁ אֶל רֵעֵהוּ\" פְּרָט לְהֶקְדֵּשׁ. כֶּסֶף אוֹ כֵּלִים פְּרָט לְקַרְקָעוֹת וְלַעֲבָדִים שֶׁהֻקְּשׁוּ לְקַרְקָעוֹת. וְכֵן יָצְאוּ שְׁטָרוֹת שֶׁאֵין גּוּפָן מָמוֹן כְּכֶסֶף וּכְכֵלִים וְאֵינָן אֶלָּא לָרְאָיָה שֶׁבָּהֶן. וְעַל כֻּלָּן נִשְׁבָּע שְׁבוּעַת הֶסֵּת אִם הָיְתָה שָׁם טַעֲנַת וַדַּאי. חוּץ מִן הַהֶקְדֵּשׁוֹת שֶׁאַף עַל פִּי שֶׁאֵינוֹ חַיָּב עֲלֵיהֶם שְׁבוּעָה מִן הַתּוֹרָה תִּקְּנוּ חֲכָמִים שֶׁיִּשָּׁבַע עֲלֵיהֶם כְּעֵין שֶׁל תּוֹרָה כְּדֵי שֶׁלֹּא יְזַלְזְלוּ בַּהֶקְדֵּשׁוֹת:","שְׁתֵּי שָׂדוֹת מָכַרְתָּ לִי לֹא מָכַרְתִּי לְךָ אֶלָּא אַחַת. שְׁנֵי עֲבָדִים אוֹ שְׁנֵי שְׁטָרוֹת יֵשׁ לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי אֶלָּא שְׁטָר אֶחָד אוֹ עֶבֶד אֶחָד. הֲרֵי זֶה נִשְׁבָּע הֶסֵּת. וְכֵן אִם טָעַן וְאָמַר חָצֵר זוֹ אוֹ עֶבֶד זֶה אוֹ שְׁטָר זֶה שֶׁיֵּשׁ לִי בְּיָדְךָ שֶׁלִּי הוּא וְאַתָּה מְכַרְתּוֹ לִי וְהַנִּטְעָן אוֹמֵר לֹא הָיוּ דְּבָרִים מֵעוֹלָם. בֵּין שֶׁהֵבִיא הַטּוֹעֵן עֵד אֶחָד בֵּין שֶׁלֹּא הֵבִיא. הֲרֵי זֶה נִשְׁבָּע הֶסֵּת וְנִפְטָר. וְכֵן הַחוֹפֵר בִּשְׂדֵה חֲבֵרוֹ בּוֹרוֹת שִׁיחִין וּמְעָרוֹת וְהִפְסידוּה והרי הוּא חיּב לְשַׁלֵּם בֵּין שֶׁטְּעָנוֹ שֶׁחָפַר וְהוּא אוֹמֵר לֹא חָפַרְתִּי אוֹ שֶׁטְּעָנוֹ שֶׁחָפַר שְׁתֵּי מְעָרוֹת וְהוּא אוֹמֵר לֹא חָפַרְתִּי אֶלָּא אַחַת אוֹ שֶׁהָיָה שָׁם עֵד אֶחָד שֶׁחָפַר וְהוּא אוֹמֵר לֹא חָפַרְתִּי כְּלוּם. הֲרֵי זֶה נִשְׁבָּע הֶסֵּת עַל הַכּל:","טְעָנוֹ כֵּלִים וְקַרְקָעוֹת בֵּין שֶׁהוֹדָה בְּכָל הַקַּרְקָעוֹת וְכָפַר בְּכָל הַכֵּלִים בֵּין שֶׁהוֹדָה בְּכָל הַכֵּלִים וְכָפַר בְּכָל הַקַּרְקָעוֹת בֵּין שֶׁהוֹדָה בְּמִקְצָת הַקַּרְקָעוֹת וְכָפַר בְּמִקְצָתָן עִם כָּל הַכֵּלִים. בְּכָל אֵלּוּ נִשְׁבָּע הֶסֵּת. אֲבָל אִם הוֹדָה בְּמִקְצָת כֵּלִים וְכָפַר בְּמִקְצָתָן עִם כָּל הַקַּרְקָעוֹת מִתּוֹךְ שֶׁהוּא חַיָּב שְׁבוּעָה עַל מִקְצָת הַכֵּלִים שֶׁכָּפַר בָּהֶן נִשְׁבָּע אַף עַל הַקַּרְקָעוֹת שֶׁטְּעָנוֹ עִמָּהֶן שֶׁהַכּל טַעֲנָה אַחַת. וְכֵן הַדִּין בִּטְעָנוֹ כֵּלִים וַעֲבָדִים אוֹ כֵּלִים וּשְׁטָרוֹת הַכּל דִּין אֶחָד הוּא:","טְעָנוֹ עֲנָבִים הָעוֹמְדוֹת לִבָּצֵר וּתְבוּאָה יְבֵשָׁה הָעוֹמֶדֶת לְהִקָּצֵר וְהוֹדָה בְּמִקְצָתָן וְכָפַר בְּמִקְצָתָן הֲרֵי זֶה נִשְׁבָּע עֲלֵיהֶם כִּשְׁאָר הַמִּטַּלְטְלִין. וְהוּא שֶׁאֵינָן צְרִיכִין לַקַּרְקַע שֶׁכָּל הָעוֹמֵד לְהִבָּצֵר הֲרֵי הוּא כְּבָצוּר לְעִנְיַן כְּפִירָה וְהוֹדָיָה. אֲבָל אִם הָיוּ צְרִיכִים לַקַּרְקַע הֲרֵי הֵן כְּקַרְקַע לְכָל דָּבָר וְאֵין נִשְׁבָּעִין עֲלֵיהֶן אֶלָּא הֶסֵּת:","הַטּוֹעֵן עַל חֲבֵרוֹ וְאָמַר לוֹ שְׁנֵי חֳדָשִׁים שָׁכַנְתָּ בַּחֲצֵרִי וְאַתָּה חַיָּב לִי שְׂכַר שְׁנֵי חֳדָשִׁים וְהוּא אוֹמֵר לֹא שָׁכַנְתִּי אֶלָּא חֹדֶשׁ אֶחָד הֲרֵי זֶה מוֹדֶה בְּמִקְצָת. וְאִם הָיָה שְׂכַר הַחֹדֶשׁ שֶׁכָּפַר בּוֹ שָׁוֶה שְׁנֵי כֶּסֶף נִשְׁבָּע שֶׁאֵין הַטַּעֲנָה בְּגוּף הַקַּרְקַע אֶלָּא בִּשְׂכָרָהּ שֶׁהוּא מִטַּלְטְלִין:","שְׁטָר מָסַרְתִּי לְךָ וַעֲשָׂרָה דִּינָרִין הָיוּ לִי בּוֹ רְאָיָה לֹא הָיוּ דְּבָרִים מֵעוֹלָם יִשָּׁבַע הֶסֵּת. הָפַךְ עָלָיו הֲרֵי זֶה נִשְׁבָּע הֶסֵּת שֶׁהָיְתָה בּוֹ רְאָיָה לַעֲשָׂרָה דִּינָרִים וְאָבְדוּ בַּאֲבֵדַת הַשְּׁטָר וְיִטּל. וְאִם אָמַר הַנִּתְבָּע אֱמֶת מָסַרְתָּ לִי וְאָבַד הֲרֵי זֶה פָּטוּר אַף מִשְּׁבוּעַת הֶסֵּת שֶׁאֲפִלּוּ פָּשַׁע בּוֹ וְאָבַד פָּטוּר כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת חוֹבֵל:","הָאוֹמֵר לַחֲבֵרוֹ שְׁטָר שֶׁיֵּשׁ לִי בְּיָדְךָ זְכוּת יֵשׁ לִי בּוֹ וְזֶה אוֹמֵר אֵינִי מוֹצֵא שְׁטָרִי אוֹ אֵינִי יוֹדֵעַ אִם יֵשׁ לְךָ בּוֹ רְאָיָה אוֹ לֹא כּוֹפִין אוֹתוֹ לְהוֹצִיאוֹ:","טָעַן שֶׁאָבַד הַשְּׁטָר מַחְרִימִין אוֹתוֹ חֵרֶם סְתָם. טָעַן זֶה שֶׁהוּא יוֹדֵעַ בְּוַדַּאי שֶׁהַשְּׁטָר שֶׁיֵּשׁ לוֹ בּוֹ זְכוּת אֶצְלוֹ הֲרֵי זֶה נִשְׁבָּע הֶסֵּת שֶׁאֵינוֹ אֶצְלוֹ וְשֶׁאָבַד מִמֶּנּוּ וְכָזֶה הוֹרוּ רַבּוֹתַי:","אֵין נִשְׁבָּעִין עַל טַעֲנַת חֵרֵשׁ שׁוֹטֶה וְקָטָן. אֶחָד הַבָּא בְּטַעֲנַת עַצְמוֹ אוֹ בְּטַעֲנַת אָבִיו. לְפִי שֶׁזֶּה הַמִּקְצָת שֶׁהוֹדָה בּוֹ לַקָּטָן אֵינוֹ אֶלָּא כְּמֵשִׁיב אֲבֵדָה. וְכֵן אִם כָּפַר בַּכּל וּבָא עֵד אֶחָד וְהֵעִיד לַקָּטָן אֵינוֹ נִשְׁבָּע. שֶׁזֶּה עֵד אֶחָד וְאֵין שָׁם תּוֹבֵעַ שֶׁתְּבִיעַת קָטָן אֵינָהּ תְּבִיעָה גְּמוּרָה. נִמְצֵאתָ אוֹמֵר קָטָן שֶׁאָמַר לְגָדוֹל מָנֶה לִי בְּיָדְךָ. אוֹ אַבָּא הָיָה לוֹ בְּיָדְךָ. וְהַלָּה אוֹמֵר אֵין לְךָ בְּיָדִי אֶלָּא חֲמִשִּׁים אוֹ אֵין לְךָ בְּיָדִי כְּלוּם. וְעֵד אֶחָד מְעִידוֹ שֶׁיֵּשׁ לוֹ הֲרֵי זֶה פָּטוּר מִשְּׁבוּעַת הַתּוֹרָה. אֲבָל אִם שָׁמַר לְקָטָן וְטָעַן שֶׁאָבַד הֲרֵי זֶה נִשְׁבָּע שְׁבוּעַת הַשּׁוֹמְרִין לְפִי שֶׁאֵינוֹ נִשְׁבָּע מֵחֲמַת טַעֲנָה. וְכֵן אִם הוֹדָה שֶׁהָיָה שֻׁתָּף לְקָטָן אוֹ אַפּוֹטְרוֹפּוֹס עָלָיו יַעֲמִידוּ בֵּית דִּין אַפּוֹטְרוֹפּוֹס לַקָּטָן וְיִשָּׁבַע הַשֻׁתָּף וְכַיּוֹצֵא בּוֹ בְּטַעֲנַת שֶׁמָּא:","הוֹרוּ רַבּוֹתַי שֶׁאֵין נִשְׁבָּעִין עַל טַעֲנַת קָטָן שְׁבוּעָה שֶׁל תּוֹרָה אֲבָל שְׁבוּעַת הֶסֵּת נִשְׁבָּעִין. וַאֲפִלּוּ הָיָה קָטָן שֶׁאֵינוֹ חָרִיף לְעִנְיַן מַשָּׂא וּמַתָּן נִשְׁבָּעִין הֶסֵּת עַל טַעֲנָתוֹ. שֶׁלֹּא יִהְיֶה זֶה נוֹטֵל מָמוֹנוֹ כְּשֶׁהוּא קָטָן וְיֵלֵךְ לוֹ בְּחִנָּם. וְלָזֶה דַּעְתִּי נוֹטָה וְתִקּוּן עוֹלָם הוּא. נִמְצֵאתָ לָמֵד שֶׁהַקָּטָן שֶׁטָּעַן עַל הַגָּדוֹל בֵּין שֶׁהוֹדָה בְּמִקְצָת בֵּין שֶׁכָּפַר בַּכּל בֵּין שֶׁהָיָה שָׁם עֵד בֵּין שֶׁלֹּא הָיָה שָׁם עֵד. הֲרֵי זֶה נִשְׁבָּע הֶסֵּת וְאֵינוֹ יָכוֹל לַהֲפֹךְ עַל הַקָּטָן שֶׁאֵין מַשְׁבִּיעִין אֶת הַקָּטָן כְּלָל. וַאֲפִלּוּ חֵרֶם סְתָם אֵינוֹ מְקַבֵּל לְפִי שֶׁאֵינוֹ יוֹדֵעַ עֹנֶשׁ הַשְּׁבוּעָה:","קָטָן שֶׁטְּעָנוֹ הַגָּדוֹל. אִם טְעָנוֹ בְּדָבָר שֶׁיֵּשׁ לוֹ הֲנָיָה לַקָּטָן כְּגוֹן עֵסֶק מַשָּׂא וּמַתָּן וְהוֹדָה הַקָּטָן נִפְרָעִין מִנְּכָסָיו. וְאִם אֵין לוֹ יַמְתִּין עַד שֶׁיִּהְיֶה לוֹ וִישַׁלֵּם. וְאִם כָּפַר הַקָּטָן מַמְתִּינִין עַד שֶׁיַּגְדִּיל וְיִשָּׁבַע הֶסֵּת. וְאִם טְעָנוֹ בְּדָבָר שֶׁאֵין לְקָטָן הֲנָיָה כְּגוֹן נְזָקִין וְחַבָּלוֹת אַף עַל פִּי שֶׁמּוֹדֶה וְאַף עַל פִּי שֶׁיֵּשׁ לוֹ מִמָּה יְשַׁלֵּם פָּטוּר וַאֲפִלּוּ לְאַחַר שֶׁהִגְדִּיל. וְאִם הָיָה הַתּוֹבֵעַ מִן הַנִּשְׁבָּעִין וְנוֹטְלִין כְּגוֹן הַשָּׂכִיר וְכַיּוֹצֵא בּוֹ שֶׁיֵּשׁ הֲנָיָה לַקָּטָן שֶׁיִּשְׂתַּכֵּר לוֹ שָׂכִיר הֲרֵי זֶה נִשְׁבָּע וְנוֹטֵל מִן הַקָּטָן. אֲבָל חֶנְוָנִי שֶׁנִּשְׁבָּע עַל פִּנְקָסוֹ אֵינוֹ נִשְׁבָּע וְנוֹטֵל מִן הַקָּטָן. שֶׁאֵין לַקָּטָן בָּזֶה הֲנָיָה שֶׁהֲרֵי חַיָּב לִתֵּן לְפוֹעֲלָיו וְנִשְׁבָּעִין וְנוֹטְלִין מִמֶּנּוּ. וְזֶה הַחֶנְוָנִי הִפְסִיד עַל נַפְשׁוֹ שֶׁנָּתַן מָמוֹנוֹ עַל פִּי קָטָן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַחֵרֵשׁ וְהַשּׁוֹטֶה אֵין נִזְקָקִין לָהֶן לְכָל טַעֲנָה לֹא לְטַעֲנָתָן עַל אֲחֵרִים וְלֹא לְטַעֲנַת אֲחֵרִים עֲלֵיהֶן. לֹא לִשְׁבוּעָה קַלָּה וְאֵין צָרִיךְ לוֹמַר שְׁבוּעָה חֲמוּרָה אוֹ תַּשְׁלוּמִין. אֲבָל הַסּוּמָא הֲרֵי הוּא כְּבָרִיא לְכָל דָּבָר בְּעִנְיָנִים אֵלּוּ וְנִשְׁבָּע כָּל מִינֵי שְׁבוּעוֹת וְנִשְׁבָּעִין עַל טַעֲנָתוֹ:"],"Mishneh Torah, Positive Mitzvot 105":["להיות שכבת זרע מטמאה."],"Mishneh Torah, Positive Mitzvot 116":["להיות מעריך ביתו נותן כערך הכהן, שנאמר: \"וְאִישׁ כִּי יַקְדִּישׁ\" (ויקרא כז, יד)."],"Mishneh Torah, Positive Mitzvot 127":["להפריש מעשר דגן ללוים, שנאמר: \"כָּל מַעְשַׂר הָאָרֶץ\" (ויקרא כז, ל)."],"Mishneh Torah, Positive Mitzvot 138":["ליתן גאולה לארץ בשנת היובל, שנאמר: \"ובכול, ארץ אחוזתכם, גאולה, תיתנו לארץ\" (ויקרא כה,כד)."],"Mishneh Torah, Positive Mitzvot 149":["לבדוק בסימני בהמה, שנאמר: \"זאת החיה אשר תאכלו\" (ויקרא יא,ב)."],"Mishneh Torah, Positive Mitzvot 16":["לְהַקְהִיל אֶת הָעָם לִשְׁמֹעַ תּוֹרָה בְּמוֹצָאֵי שְׁבִיעִית, שֶׁנֶּאֱמָר: \"הַקְהֵל אֶת הָעָם...\" (דברים לא, יב)."],"Mishneh Torah, Positive Mitzvot 170":["לשמוע קול שופר בראש השנה, שנאמר: \"יום תרועה, יהיה לכם\" (במדבר כט,א)."],"Mishneh Torah, Positive Mitzvot 181":["לערוף את העגלה כמצותה, שנאמר: \"וערפו שם את העגלה, בנחל\" (דברים כא,ד)."],"Mishneh Torah, Positive Mitzvot 192":["להתקין יד במחנה, שנאמר: \"ויד תהיה לך, מחוץ למחנה\" (דברים כג,יג)."],"Mishneh Torah, Positive Mitzvot 202":["לעזוב מעל חברו או מעל בהמתו, שנאמר: \"עזוב תעזוב, עימו\" (שמות כג,ה)."],"Mishneh Torah, Positive Mitzvot 213":["לבעול בקידושין, שנאמר: \"כי יקח איש אשה ובא אליה\" (דברים כב, יג) וראה דברים כד, א."],"Mishneh Torah, Positive Mitzvot 224":["להלקות הרשעים, שנאמר: \"והפילו השופט והכהו\" (דברים כה,ב)."],"Mishneh Torah, Positive Mitzvot 235":["לעבוד בעבד כנעני לעולם, שנאמר: \"לעולם, בהם תעבודו\" (ויקרא כה,מו)."],"Mishneh Torah, Positive Mitzvot 246":["לדון בדין טוען וכופר, שנאמר: \"על כל דבר פשע\" (שמות כב,ח)."],"Mishneh Torah, Positive Mitzvot 33":["להיות הכהנים לובשים לעבודה בגדי כהונה, שנאמר: \"וְעָשִׂיתָ בִגְדֵי קֹדֶשׁ...\" (שמות כח, ב)."],"Mishneh Torah, Positive Mitzvot 44":["להקריב מנחת העומר ממחרת יום ראשון של פסח עם כבש אחד, שנאמר: \"וַהֲבֵאתֶם אֵת עֹמֶר רֵאשִׁית קְצִירְכֶם אֶל הַכֹּהֵן\" (ויקרא כג, י)."],"Mishneh Torah, Positive Mitzvot 55":["לשחוט כבש הפסח, שנאמר: \"וְשָׁחֲטוּ אֹתוֹ כָּל קְהַל \" (שמות יב, ו)."],"Mishneh Torah, Positive Mitzvot 66":["מעשה זבח השלמים, שנאמר: \"וְזֹאת תּוֹרַת זֶבַח הַשְּׁלָמִים\" (ויקרא ז, יא)."],"Mishneh Torah, Positive Mitzvot 77":["להקריב המצורע קרבן אחר שיטהר, שנאמר: \"וביום השמיני ייקח\" (ויקרא יד,י)."],"Mishneh Torah, Positive Mitzvot 88":["לאכול שיירי מנחות, שנאמר: \"והנותרת ממנה, יאכלו אהרון ובניו\" (ויקרא ו,ט)."],"Mishneh Torah, Positive Mitzvot 99":["להיות הנידה טמאה ומטמאה לאחרים."],"Mishneh Torah, Prayer and the Priestly Blessing 6":["אָסוּר לוֹ לְאָדָם לַעֲבֹר אֲחוֹרֵי בֵּית הַכְּנֶסֶת בְּשָׁעָה שֶׁהַצִּבּוּר מִתְפַּלְּלִין אֶלָּא אִם כֵּן הָיָה נוֹשֵׂא מַשּׂאוֹי, אוֹ שֶׁהָיָה לְבֵית הַכְּנֶסֶת שְׁנֵי פְּתָחִים בִּשְׁנֵי רוּחוֹת, שֶׁהָרוֹאֶה אוֹמֵר שֶׁמָּא יֵלֵךְ וְיִכָּנֵס מִפֶּתַח הָאַחֵר. וְכֵן אִם הָיָה בָּעִיר שְׁנֵי בָּתֵּי כְּנֵסִיּוֹת יֹאמַר הָרוֹאֶה שֶׁמָּא יֵלֵךְ לְבֵית הַכְּנֶסֶת הָרָגִיל בּוֹ. וְאִם יֵשׁ לוֹ תְּפִלִּין בְּרֹאשׁוֹ מֻתָּר לוֹ לַעֲבֹר וְאַף עַל פִּי שֶׁאֵין שָׁם אֶחָד מִכָּל אֵלּוּ שֶׁהַתְּפִלִּין מוֹכִיחִין עָלָיו שֶׁהוּא רוֹדֵף אַחַר מִצְוֹת וְאֵינוֹ מִמְּבַטְּלֵי תְּפִלָּה:","הַמִּתְפַּלֵּל עִם הַצִּבּוּר לֹא יַאֲרִיךְ אֶת תְּפִלָּתוֹ יוֹתֵר מִדַּאי אֲבָל בֵּינוֹ לְבֵין עַצְמוֹ הָרְשׁוּת בְּיָדוֹ. וְאִם בָּא לוֹמַר אַחַר תְּפִלָּתוֹ אֲפִלּוּ כְּסֵדֶר וִדּוּי יוֹם הַכִּפּוּרִים אוֹמֵר. וְכֵן אִם רָצָה לְהוֹסִיף בְּכָל בְּרָכָה וּבְרָכָה מִן הָאֶמְצָעִיּוֹת מֵעֵין הַבְּרָכָה מוֹסִיף:","כֵּיצַד. הָיָה לוֹ חוֹלֶה מְבַקֵּשׁ עָלָיו רַחֲמִים בְּבִרְכַּת חוֹלִים כְּפִי צַחוּת לְשׁוֹנוֹ. הָיָה צָרִיךְ לְפַרְנָסָה מוֹסִיף תְּחִנָּה וּבַקָּשָׁה בְּבִרְכַּת הַשָּׁנִים. וְעַל דֶּרֶךְ זֶה בְּכָל אַחַת מֵהֶן. וְאִם רָצָה לִשְׁאֹל כָּל צְרָכָיו בְּשׁוֹמֵעַ תְּפִלָּה שׁוֹאֵל. אֲבָל לֹא יִשְׁאַל לֹא בְּשָׁלֹשׁ רִאשׁוֹנוֹת וְלֹא בְּשָׁלֹשׁ אַחֲרוֹנוֹת:","אָסוּר לוֹ לְאָדָם שֶׁיִּטְעֹם כְּלוּם אוֹ שֶׁיַּעֲשֶׂה מְלָאכָה מֵאַחַר שֶׁיַּעֲלֶה עַמּוּד הַשַּׁחַר עַד שֶׁיִּתְפַּלֵּל תְּפִלַּת שַׁחֲרִית. וְכֵן לֹא יַשְׁכִּים לְפֶתַח חֲבֵרוֹ לִשְׁאל בִּשְׁלוֹמוֹ קֹדֶם שֶׁיִּתְפַּלֵּל תְּפִלַּת שַׁחֲרִית. וְלֹא יֵצֵא בַּדֶּרֶךְ קֹדֶם שֶׁיִּתְפַּלֵּל. אֲבָל טוֹעֵם וְעוֹשֶׂה מְלָאכָה קֹדֶם שֶׁיִּתְפַּלֵּל מוּסָף וְקֹדֶם מִנְחָה. אֲבָל אֵינוֹ סוֹעֵד סָמוּךְ לַמִּנְחָה:","כֵּיוָן שֶׁהִגִּיעַ זְמַן מִנְחָה גְּדוֹלָה לֹא יִכָּנֵס לַמֶּרְחָץ אֲפִלּוּ לְהַזִּיעַ עַד שֶׁיִּתְפַּלֵּל שֶׁמָּא יִתְעַלֵּף וְיִבָּטֵל מִן הַתְּפִלָּה. וְלֹא לֶאֱכל אֲפִלּוּ אֲכִילַת עַרְאַי שֶׁמָּא יִמָּשֵׁךְ בַּאֲכִילָה. וְלֹא לָדוּן אֲפִלּוּ בִּגְמַר דִּין שֶׁמָּא יִסָּתֵר הַדִּין וְיִמָּשֵׁךְ וְיִבָּטֵל מִן הַתְּפִלָּה. וְכֵן לֹא יֵשֵׁב לִפְנֵי הַסַּפָּר לִסַפֵּר אֲפִלּוּ תִּסְפֹּרֶת הֶדְיוֹט עַד שֶׁיִּתְפַּלֵּל שֶׁמָּא יִשָּׁבֵר הַזּוּג. וְלֹא יִכָּנֵס לְבֻרְסְקִי סָמוּךְ לַמִּנְחָה עַד שֶׁיִּתְפַּלֵּל שֶׁמָּא יִרְאֶה הֶפְסֵד בִּמְלַאכְתּוֹ וְיִתְעַסֵּק בָּהּ וְיִתְעַכֵּב מִן הַתְּפִלָּה. וְאִם הִתְחִיל בְּאַחַת מֵאֵלּוּ לֹא יַפְסִיק אֶלָּא גּוֹמֵר וְאַחַר כָּךְ מִתְפַּלֵּל תְּפִלַּת מִנְחָה:","מֵאֵימָתַי הַתְחָלַת תִּסְפֹּרֶת מִשֶּׁיַּנִּיחַ מַעֲפֹרֶת שֶׁל סַפָּרִין עַל בִּרְכָּיו. וּמֵאֵימָתַי הַתְחָלַת מֶרְחָץ מִשֶּׁיִּפְשֹׁט הַבֶּגֶד הַסָּמוּךְ לִבְשָׂרוֹ. וּמֵאֵימָתַי הַתְחָלַת הַבֻּרְסְקִי מִשֶּׁיִּקְשֹׁר בֶּגֶד בֵּין כְּתֵפָיו כְּמוֹ שֶׁהָאֻמָּנִין עוֹשִׂין. וּמֵאֵימָתַי הַתְחָלַת אֲכִילָה, לִבְנֵי אֶרֶץ יִשְׂרָאֵל מִשֶּׁיִּטּל יָדָיו וְלִבְנֵי בָּבֶל מִשֶּׁיַּתִּיר חֲגוֹרוֹ. וּמֵאֵימָתַי הַתְחָלַת הַדִּין מִשֶּׁיִּתְעַטְּפוּ הַדַּיָּנִים וְיֵשְׁבוּ. וְאִם הָיוּ יוֹשְׁבִין מִשֶּׁיַּתְחִילוּ בַּעֲלֵי דִּינִין לִטְעֹן:","אַף עַל פִּי שֶׁתְּפִלַּת עַרְבִית רְשׁוּת לֹא יָבוֹא אָדָם מִמְּלַאכְתּוֹ וְיֹאמַר אֹכַל מְעַט וְאִישַׁן קִמְעָא וְאַחַר כָּךְ אֶתְפַּלֵּל, שֶׁמָּא תֶּאֱנֹס אוֹתוֹ שֵׁנָה וְנִמְצָא יָשֵׁן כָּל הַלַּיְלָה, אֶלָּא מִתְפַּלֵּל עַרְבִית וְאַחַר כָּךְ אוֹכֵל וְשׁוֹתֶה אוֹ יָשֵׁן. וּמֻתָּר לְהִסְתַּפֵּר וְלִכָּנֵס לַמֶּרְחָץ סָמוּךְ לְשַׁחֲרִית מִפְּנֵי שֶׁלֹּא גָּזְרוּ אֶלָּא סָמוּךְ לַמִּנְחָה שֶׁהוּא דָּבָר הַמָּצוּי שֶׁרֹב הָעָם נִכְנָסִין שָׁם בַּיּוֹם. אֲבָל בַּשַּׁחַר דָּבָר שֶׁאֵינוֹ מָצוּי לֹא גָּזְרוּ בּוֹ:","מִי שֶׁהָיָה עוֹסֵק בְּתַלְמוּד תּוֹרָה וְהִגִּיעַ זְמַן הַתְּפִלָּה פּוֹסֵק וּמִתְפַּלֵּל. וְאִם הָיְתָה תּוֹרָתוֹ אֻמָּנוּתוֹ וְאֵינוֹ עוֹשֶׂה מְלָאכָה כְּלָל וְהָיָה עוֹסֵק בַּתּוֹרָה בִּשְׁעַת תְּפִלָּתוֹ אֵינוֹ פּוֹסֵק, שֶׁמִּצְוַת תַּלְמוּד תּוֹרָה גְּדוֹלָה מִמִּצְוַת תְּפִלָּה. וְכָל הָעוֹסֵק בְּצָרְכֵי רַבִּים כְּעוֹסֵק בְּדִבְרֵי תּוֹרָה:","אֵין הַמִּתְפַּלֵּל מַפְסִיק תְּפִלָּתוֹ אֶלָּא מִפְּנֵי סַכָּנַת נְפָשׁוֹת בִּלְבַד. וַאֲפִלּוּ מֶלֶךְ יִשְׂרָאֵל שׁוֹאֵל בִּשְׁלוֹמוֹ לֹא יְשִׁיבֶנּוּ. אֲבָל פּוֹסֵק הוּא לְמֶלֶךְ עוֹבֵד כּוֹכָבִים שֶׁמָּא יַהַרְגֶּנּוּ. הָיָה עוֹמֵד בַּתְּפִלָּה וְרָאָה מֶלֶךְ עוֹבְדֵי כּוֹכָבִים אוֹ אַנָּס בָּא כְּנֶגְדּוֹ יְקַצֵּר וְאִם אֵינוֹ יָכוֹל יַפְסִיק. וְכֵן אִם רָאָה נְחָשִׁים וְעַקְרַבִּים בָּאִים כְּנֶגְדּוֹ אִם הִגִּיעוּ אֵלָיו וְהָיָה דַּרְכָּן בְּאוֹתָן הַמְּקוֹמוֹת שֶׁהֵן מְמִיתִין פּוֹסֵק וּבוֹרֵחַ. וְאִם לֹא הָיָה דַּרְכָּן לְהָמִית אֵינוֹ פּוֹסֵק:","נָשִׁים וַעֲבָדִים וּקְטַנִּים חַיָּבִים בִּתְפִלָּה. וְכָל אִישׁ שֶׁפָּטוּר מִקְּרִיאַת שְׁמַע פָּטוּר מִן הַתְּפִלָּה. וְכָל הַמְלַוִּין אֶת הַמֵּת אַף עַל פִּי שֶׁאֵין לַמִּטָּה צֹרֶךְ בָּהֶן פְּטוּרִין מִן הַתְּפִלָּה:"],"Mishneh Torah, Rebels 5":["הַמְקַלֵל אָבִיו וְאִמּוֹ נִסְקָל שֶׁנֶּאֱמַר (ויקרא כ ט) \"אָבִיו וְאִמּוֹ קִלֵּל דָּמָיו בּוֹ\". וְאֶחָד הַמְקַלֵּל בְּחַיֵּיהֶן אוֹ לְאַחַר מִיתָתָן הֲרֵי זֶה נִסְקָל. וְצָרִיךְ עֵדִים וְהַתְרָאָה כִּשְׁאָר כָּל מְחֻיָּבֵי מִיתוֹת בֵּית דִּין. וְאֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה וְכֵן הַטֻּמְטוּם וְהָאַנְדְּרוֹגִינוּס. וְהוּא שֶׁיִּהְיוּ גְּדוֹלִים שֶׁהִגִּיעוּ לִכְלַל הָעֳנָשִׁין:","אֵינוֹ חַיָּב סְקִילָה עַד שֶׁיְּקַלְּלֵם בְּשֵׁם מִן הַשֵּׁמוֹת הַמְּיֻחָדִין. אֲבָל אִם קִלְּלָם בְּכִנּוּי פָּטוּר מִן הַסְּקִילָה. וְלוֹקֶה כְּדֶרֶךְ שֶׁלּוֹקֶה עַל קִלְלַת כָּל אָדָם כָּשֵׁר מִיִּשְׂרָאֵל:","וְכֵן הַמְקַלֵּל אֲבִי אָבִיו וַאֲבִי אִמּוֹ הֲרֵי זֶה כִּמְקַלֵּל אֶחָד מִשְּׁאָר הַקָּהָל:","אַזְהָרָה שֶׁל מְקַלֵּל אָבִיו וְאִמּוֹ מִנַּיִן. עֹנֶשׁ שָׁמַעְנוּ בְּפֵרוּשׁ אֲבָל הָאַזְהָרָה הֲרֵי הִיא בִּכְלַל לֹא תְקַלֵּל חֵרֵשׁ. הוֹאִיל וְהוּא מֻזְהָר שֶׁלֹּא לְקַלֵּל אָדָם מִיִּשְׂרָאֵל הֲרֵי אָבִיו בִּכְלַל יִשְׂרָאֵל:","הַמַּכֶּה אָבִיו וְאִמּוֹ מִיתָתוֹ בְּחֶנֶק שֶׁנֶּאֱמַר (שמות כא טו) \"מַכֵּה אָבִיו וְאִמּוֹ מוֹת יוּמָת\". וְצָרִיךְ עֵדִים וְהַתְרָאָה כִּשְׁאָר כָּל מְחֻיָּבֵי מִיתַת בֵּית דִּין. וְאֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה וְכֵן הַטֻּמְטוּם וְאַנְדְּרוֹגִינוּס וְהוּא שֶׁיַּגִּיעוּ לִכְלַל עֳנָשִׁין. אֵינוֹ חַיָּב חֶנֶק עַד שֶׁיַּעֲשֶׂה בָּהֶן חַבּוּרָה אֲבָל אִם לֹא עָשָׂה בָּהֶן חַבּוּרָה הֲרֵי זֶה כְּמַכֶּה אֶחָד מִיִּשְׂרָאֵל. וְהַמַּכֶּה אוֹתָן לְאַחַר מִיתָה פָּטוּר:","מִי שֶׁהִכָּה אֶת אָבִיו עַל אָזְנוֹ וְחֵרְשׁוֹ חַיָּב וְנֶהֱרָג. שֶׁאִי אֶפְשָׁר שֶׁיֵּעָשֶׂה חֵרֵשׁ בְּלֹא חַבּוּרָה אֶלָּא יָצָאת טִפַּת דָּם בִּפְנִים בָּאֹזֶן וְנִתְחָרֵשׁ:","הַמַּקִּיז דָּם לְאָבִיו אוֹ שֶׁהָיָה רוֹפֵא וְחָתַךְ לוֹ בָּשָׂר אוֹ אֵבָר פָּטוּר. אַף עַל פִּי שֶׁהוּא פָּטוּר לְכַתְּחִלָּה לֹא יַעֲשֶׂה. אוֹ לְהוֹצִיא סִלּוֹן מִבְּשַׂר אָבִיו אוֹ אִמּוֹ לֹא יוֹצִיא שֶׁמָּא יַעֲשֶׂה חַבּוּרָה. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁיֵּשׁ שָׁם אַחֵר לַעֲשׂוֹת. אֲבָל אִם אֵין שָׁם מִי שֶׁיַּעֲשֶׂה אֶלָּא הוּא וַהֲרֵי הֵן מִצְטַעֲרִין הֲרֵי זֶה מַקִּיז וְחוֹתֵךְ כְּפִי מַה שֶּׁיַּרְשֵׁהוּ לַעֲשׂוֹת:","אַזְהָרָה שֶׁל מַכֵּה אָבִיו מִנַּיִן. עֹנֶשׁ שָׁמַעְנוּ אַזְהָרָה לֹא שָׁמַעְנוּ. הוֹאִיל וְהוּא מֻזְהָר שֶׁלֹּא לְהַכּוֹת אָדָם מִיִּשְׂרָאֵל הֲרֵי אָבִיו וְאִמּוֹ בִּכְלָל:","שְׁתוּקִי חַיָּב עַל אִמּוֹ וְאֵינוֹ חַיָּב עַל אָבִיו אַף עַל פִּי שֶׁנִּבְדְּקָה אִמּוֹ וְאָמְרָה בֶּן פְּלוֹנִי הוּא אֵינוֹ נִסְקָל אוֹ נֶחְנָק עַל פִּיהָ. אֲבָל בְּנוֹ מִן הַשִּׁפְחָה וּמִן הָעַכּוּ\"ם אֵינוֹ חַיָּב לֹא עַל אָבִיו וְלֹא עַל אִמּוֹ. וְכֵן גֵּר שֶׁהוֹרָתוֹ שֶׁלֹּא בִּקְדֻשָּׁה אַף עַל פִּי שֶׁלֵּדָתוֹ בִּקְדֻשָּׁה אֵינוֹ חַיָּב עַל מַכַּת אָבִיו וְקִלְלָתוֹ:","כְּשֵׁם שֶׁאֵינוֹ חַיָּב עַל אָבִיו כָּךְ אֵינוֹ חַיָּב עַל אִמּוֹ. שֶׁנֶּאֱמַר (שמות כא יז) \"וּמְקַלֵּל אָבִיו וְאִמּוֹ\" אֶת שֶׁהוּא חַיָּב עַל אָבִיו חַיָּב עַל אִמּוֹ וְזֶה שֶׁאֵינוֹ חַיָּב עַל אָבִיו אֵינוֹ חַיָּב עַל אִמּוֹ:","הַגֵּר אָסוּר לְקַלֵּל אָבִיו הָעַכּוּ\"ם וּלְהַכּוֹתוֹ. וְלֹא יְבַזֵּהוּ כְּדֵי שֶׁלֹּא יֹאמְרוּ בָּאוּ מִקְּדֻשָּׁה חֲמוּרָה לִקְדֻשָּׁה קַלָּה שֶׁהֲרֵי זֶה מְבַזֶּה אָבִיו. אֶלָּא נוֹהֵג בּוֹ מִקְצָת כָּבוֹד. אֲבָל הָעֶבֶד אֵין לוֹ יִחוּס אֶלָּא הֲרֵי אָבִיו כְּמִי שֶׁאֵינוֹ אָבִיו לְכָל דָּבָר אַף עַל פִּי שֶׁנִּשְׁתַּחְרְרוּ:","מִי שֶׁהָיוּ אָבִיו וְאִמּוֹ רְשָׁעִים גְּמוּרִים וְעוֹבְרֵי עֲבֵרוֹת. אֲפִלּוּ נִגְמַר דִּינָן לַהֲרִיגָה וְהֵם יוֹצְאִים לֵהָרֵג אָסוּר לְהַכּוֹתָן וּלְקַלְּלָם. וְאִם קִלֵּל אוֹ חָבַל בָּהֶן פָּטוּר. וְאִם עָשׂוּ תְּשׁוּבָה הֲרֵי זֶה חַיָּב וְנֶהֱרָג עֲלֵיהֶן אַף עַל פִּי שֶׁהֲרֵי הֵן יוֹצְאִין לְמִיתָה. בַּמֶּה דְּבָרִים אֲמוּרִים בִּבְנוֹ. אֲבָל אַחֵר שֶׁבָּא וְהִכָּהוּ וְקִלֵּל אַחַר שֶׁנִּגְמַר דִּינוֹ אַף עַל פִּי שֶׁעָשָׂה תְּשׁוּבָה הֲרֵי זֶה פָּטוּר הוֹאִיל וְהוּא הוֹלֵךְ לְמִיתָה. וְאִם בִּיְּשׁוֹ חַיָּב בִּקְנַס הַמְבַיֵּשׁ:","עָבַר אָבִיו וְאִמּוֹ עַל עֲבֵרָה שֶׁלּוֹקִין עָלֶיהָ וְהָיָה הוּא חַזָּן לִפְנֵי הַדַּיָּנִים לֹא יַכֶּה אוֹתָם. וְכֵן אִם נִתְחַיֵּב נִדּוּי לֹא יִהְיֶה שָׁלִיחַ לְנַדּוֹתָם. וְלֹא יִדְחֹף אוֹתָם וְלֹא יְבַזֶּה אוֹתָם בִּשְׁלִיחוּת בֵּית דִּין אַף עַל פִּי שֶׁהֵן רְאוּיִין לְכָךְ וְלֹא עָשׂוּ תְּשׁוּבָה:","לַכּל אֵין הַבֵּן נַעֲשֶׂה שָׁלִיחַ לְהַכּוֹתוֹ וּלְקַלְּלוֹ חוּץ מִמֵּסִית וּמַדִּיחַ. שֶׁהֲרֵי אָמְרָה תּוֹרָה (דברים יג ט) \"לֹא תַחְמל וְלֹא תְכַסֶּה עָלָיו\":","מִי שֶׁנִּתְחַיֵּב שְׁבוּעָה לִבְנוֹ כָּךְ רָאִינוּ בּוֹ תָּמִיד שֶׁאֵינוֹ מַשְׁבִּיעוֹ בִּשְׁבוּעַת הָאָלָה. שֶׁהֲרֵי זֶה בָּא לְקִלְלַת אָבִיו. אֶלָּא מַשְׁבִּיעוֹ שְׁבוּעָה שֶׁאֵין בָּהּ אָלָה. וּכְבָר בֵּאַרְנוּ שֶׁהָאָב שֶׁהָרַג אֶת בְּנוֹ אֵין אֶחָד מֵאֶחָיו שֶׁל נֶהֱרָג נַעֲשֶׂה גּוֹאֵל הַדָּם. וְלֹא עַל הַכָּאָה וְלֹא עַל הַקְּלָלָה בִּלְבַד הִקְפִּידָה תּוֹרָה אֶלָּא אַף עַל הַבִּזָּיוֹן. שֶׁכָּל הַמְבַזֶּה אָבִיו אוֹ אִמּוֹ אֲפִלּוּ בִּדְבָרִים וַאֲפִלּוּ בִּרְמִיזָה הֲרֵי זֶה אָרוּר מִפִּי הַגְּבוּרָה. שֶׁנֶּאֱמַר (דברים כז טז) \"אָרוּר מַקְלֶה אָבִיו וְאִמּוֹ\". וַהֲרֵי הוּא אוֹמֵר (משלי ל יז) \"עַיִן תִּלְעַג לְאָב וְתָבֻז לִיקְּהַת אֵם\" וְגוֹ'. וְיֵשׁ לְבֵית דִּין לְהַכּוֹת עַל זֶה מַכַּת מַרְדּוּת וְלַעֲנשׁ כְּפִי מַה שֶּׁיִּרְאוּ:"],"Mishneh Torah, Red Heifer 4":["אֵין שׁוֹחֲטִין שְׁתֵּי פָּרוֹת אֲדֻמּוֹת כְּאַחַת שֶׁנֶּאֱמַר (במדבר יט ג) \"וְשָׁחַט אֹתָהּ\":","לֹא רָצְתָה פָּרָה לָצֵאת אֵין מוֹצִיאִין עִמָּהּ שְׁחוֹרָה שֶׁלֹּא יֹאמְרוּ שְׁחוֹרָה שָׁחֲטוּ וְלֹא אֲדֻמָּה שֶׁלֹּא יֹאמְרוּ שְׁתַּיִם שָׁחֲטוּ:","פָּרָה שֶׁנִּשְׁחֲטָה שֶׁלֹּא לִשְׁמָהּ אוֹ שֶׁקִּבֵּל אוֹ שֶׁהִזָּה שֶׁלֹּא לִשְׁמָהּ אוֹ לִשְׁמָהּ וְשֶׁלֹּא לִשְׁמָהּ אוֹ שֶׁלֹּא לִשְׁמָהּ וְלִשְׁמָהּ אוֹ שֶׁנַּעֲשֵׂית שֶׁלֹּא בְּכֹהֵן אוֹ בִּמְחֻסַּר בְּגָדִים אוֹ שֶׁעֲשָׂאָהּ בְּבִגְדֵי זָהָב אוֹ בְּבִגְדֵי חֹל פְּסוּלָה. שְׁחָטָהּ עַל מְנָת לֶאֱכל מִבְּשָׂרָהּ אוֹ לִשְׁתּוֹת מִדָּמָהּ כְּשֵׁרָה לְפִי שֶׁלֹּא נֶאֱמַר בָּהּ רֵיחַ נִיחוֹחַ:","קִבֵּל דָּמָהּ בִּכְלִי פְּסוּלָה שֶׁנֶּאֱמַר (במדבר יט ד) \"וְלָקַח אֶלְעָזָר הַכֹּהֵן מִדָּמָהּ בְּאֶצְבָּעוֹ\" מִצְוָתָהּ מִצְוַת יָד וְלֹא מִצְוַת כְּלִי:","הִזָּה בִּכְלִי אֲפִלּוּ אַחַת מֵהֶן הַזָּאָתוֹ פְּסוּלָה. הִזָּה אַחַת מֵהֶן בִּשְׂמֹאלוֹ פְּסוּלָה. הִזּוּ שִׁבְעָה כֹּהֲנִים הַזָּיָתָן כְּאֶחָד הַזָּיָתָן פְּסוּלָה. זֶה אַחַר זֶה כְּשֵׁרָה. הִזָּה וְלֹא כִּוֵּן כְּנֶגֶד הַהֵיכָל פְּסוּלָה שֶׁנֶּאֱמַר (במדבר יט ד) \"אֶל נֹכַח פְּנֵי אֹהֶל מוֹעֵד\" עַד שֶׁיְּכַוֵּן כְּנֶגֶד הַהֵיכָל וְיִהְיֶה רוֹאֵהוּ. וְכֵן אִם שְׁחָטָהּ אוֹ שְׂרָפָהּ שֶׁלֹּא כְּנֶגֶד הַהֵיכָל פְּסוּלָה שֶׁנֶּאֱמַר (במדבר יט ג) \"וְשָׁחַט אֹתָהּ לְפָנָיו\":","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהִזָּה אוֹ שָׂרַף אוֹ שָׁחַט כְּנֶגֶד הַדָּרוֹם אוֹ כְּנֶגֶד צָפוֹן אוֹ שֶׁהָיָה אֲחוֹרָיו לַמִּקְדָּשׁ. אֲבָל אִם עָמַד בֵּין מִזְרָח וּמַעֲרָב וּפָנָיו כְּנֶגֶד הַהֵיכָל אַף עַל פִּי שֶׁלֹּא כִּוֵּן כְּנֶגֶד [הַהֵיכָל] בְּדִקְדּוּק כְּשֵׁרָה:","חִסֵּר אַחַת מִן הַמַּתָּנוֹת פְּסוּלָה. טָבַל שְׁתַּיִם וְהִזָּה אַחַת הַזָּאָתוֹ פְּסוּלָה. טָבַל אַחַת וְהִזָּה שְׁתַּיִם אַף עַל פִּי שֶׁלֹּא חָשַׁב הַזָּאָה שְׁנִיָּה אֶלָּא טָבַל וְהִזָּה אַחֶרֶת הַזָּיָתוֹ פְּסוּלָה. כֵּיצַד. טָבַל אֶצְבָּעוֹ טְבִילָה שִׁשִּׁית וְהִזָּה שֵׁשׁ וְשֶׁבַע אַף עַל פִּי שֶׁחָזַר וְטָבַל אֶצְבָּעוֹ וְהִזָּה שֶׁבַע הַזָּיָתוֹ פְּסוּלָה. הִזָּה מִטְּבִילָה שְׁבִיעִית [שְׁבִיעִית] וּשְׁמִינִית אֲפִלּוּ חָזַר וְטָבַל טְבִילָה שְׁמִינִית וְהִזָּה שְׁמִינִית כְּשֵׁרָה שֶׁכָּל שֶׁמּוֹסִיף עַל הַשֶּׁבַע אֵינוֹ כְּלוּם. וְהוּא שֶׁיִּהְיֶה זֶה שֶׁהוֹסִיף כֹּהֵן אַחֵר אֲבָל הַכֹּהֵן הַשּׂוֹרֵף אוֹתָהּ אִם הוֹסִיף פְּסוּלָה מִפְּנֵי שֶׁנִּתְעַסֵּק בְּדָבָר שֶׁאֵינוֹ צָרִיךְ בִּשְׁעַת שְׂרֵפָתָהּ:","הוֹצִיא אֶת הַדָּם חוּץ מִמַּעֲרַכְתָּהּ וְהִזָּה פְּסוּלָה:","הִזָּה מִדָּמָהּ בַּלַּיְלָה אֲפִלּוּ הִזָּה שֵׁשׁ הַזָּיוֹת בַּיּוֹם וְאַחַת בַּלַּיְלָה פְּסוּלָה:","שְׁחָטָהּ חוּץ מִמְּקוֹם שְׂרֵפָתָהּ אֲפִלּוּ שְׁחָטָהּ לְפָנִים מִן הַחוֹמָה פְּסוּלָה:","שְׂרָפָהּ חוּץ מִמַּעֲרָכָה שֶׁנִּשְׁחֲטָה עָלֶיהָ. אוֹ שֶׁחִלְּקָהּ לִשְׁנַיִם וּשְׂרָפָהּ בִּשְׁתֵּי מַעֲרָכוֹת. אוֹ שֶׁשָּׂרַף שְׁתַּיִם בְּמַעֲרָכָה אַחַת פְּסוּלָה. וְאִם אַחַר שֶׁנַּעֲשֵׂית אֵפֶר מֵבִיא אַחֶרֶת שׂוֹרֵף עַל גַּבָּהּ וְאֵינוֹ חוֹשֵׁשׁ:","הִפְשִׁיטָהּ וּנְתָחָהּ וְאַחַר כָּךְ שָׂרַף כֻּלָּהּ כְּשֵׁרָה. וְאִם חִסֵּר מִמֶּנָּה כְּלוּם אֲפִלּוּ מִפִּרְשָׁהּ פְּסוּלָה. פָּקַע מֵעוֹרָהּ אוֹ מִבְּשָׂרָהּ אֲפִלּוּ מִשְּׂעָרָהּ כְּזַיִת יַחְזִיר וְאִם לֹא הֶחְזִיר פְּסוּלָה. פָּקַע חוּץ לְמַעֲרַכְתָּהּ מַרְבֶּה עָלָיו וְשׂוֹרְפוֹ בִּמְקוֹמוֹ. פָּקַע מִקַּרְנֶיהָ מִטְּלָפֶיהָ אוֹ מִפִּרְשָׁהּ אֵינוֹ צָרִיךְ לְהַחְזִיר:","הַפָּרָה אֵינָהּ נִפְסֶלֶת בְּלִינָה לְפִיכָךְ אִם נִשְׁחֲטָה הַיּוֹם וְהִזָּה דָּמָהּ כְּהִלְכָתוֹ וְנִשְׂרְפָה לְמָחָר כְּשֵׁרָה:","שְׂרָפָהּ אוֹנֵן אוֹ מְחֻסַּר כַּפָּרָה כְּשֵׁרָה:","שְׂרָפָהּ שֶׁלֹּא בְּקִדּוּשׁ יָדַיִם וְרַגְלַיִם פְּסוּלָה מִפְּנֵי שֶׁמַּעֲשֶׂיהָ כְּעֵין עֲבוֹדָה. וְהֵיכָן מְקַדֵּשׁ יָדָיו וְרַגְלָיו בִּכְלִי שָׁרֵת בִּפְנִים וְאִם קִדֵּשׁ בַּחוּץ וּמִכְּלִי חֹל אֲפִלּוּ בִּמְקֵדָה שֶׁל חֶרֶס כָּשֵׁר הוֹאִיל וְכָל מַעֲשֶׂיהָ בַּחוּץ. וְכֵן כְּשֶׁמַּטְבִּילִין אֶת הַכֹּהֵן הַשּׂוֹרֵף אַחַר שֶׁמְּטַמְּאִין אוֹתוֹ כְּמוֹ שֶׁבֵּאַרְנוּ אֵינוֹ צָרִיךְ לַחְזֹר וּלְקַדֵּשׁ הוֹאִיל וְכָל מַעֲשֶׂיהָ בִּטְבוּלֵי יוֹם:","שְׂרָפָהּ שֶׁלֹּא בְּעֵצִים אוֹ בְּכָל עֵצִים אֲפִלּוּ בְּקַשׁ אוֹ בִּגְבָבָא כְּשֵׁרָה. וּמִצְוָתָהּ שֶׁלֹּא יְמַעֵט לָהּ עֵצִים מִן הָרָאוּי לָהּ אֲבָל מַרְבֶּה הוּא לָהּ חֲבִילֵי אֵזוֹב וְאֵזוֹב יוֹן בִּזְמַן שְׂרֵפָה כְּדֵי לְהַרְבּוֹת אֶת הָאֵפֶר. וְיֵשׁ לוֹ לְהַרְבּוֹת עֵצִים בִּשְׂרֵפָתָהּ עַד שֶׁתֵּעָשֶׂה אֵפֶר אֲבָל מִשֶּׁתֵּעָשֶׂה אֵפֶר אִם הוֹסִיף בָּהּ אֲפִלּוּ עֵץ אֶחָד הֲרֵי זֶה כִּמְעָרֵב אֵפֶר מַקְלֶה בְּאֵפֶר הַפָּרָה:","כָּל מַעֲשֵׂה הַפָּרָה מִתְּחִלָּה וְעַד סוֹף אֵינוֹ אֶלָּא בַּיּוֹם. וּבְזִכְרֵי כְּהֻנָּה. וְהַמְּלָאכָה פּוֹסֶלֶת בָּהּ עַד שֶׁתֵּעָשֶׂה אֵפֶר. אֲבָל מִשֶּׁתֵּעָשֶׂה אֵפֶר אִם כָּנַס אֶפְרָהּ בַּלַּיְלָה אוֹ שֶׁכְּנָסַתּוּ אִשָּׁה אוֹ שֶׁעָשָׂה מְלָאכָה אַחֶרֶת בִּשְׁעַת כְּנִיסָתוֹ הֲרֵי זוֹ כְּשֵׁרָה. וּמִנַּיִן שֶׁאֲסִיפַת הָאֵפֶר בְּכָל אָדָם מִיִּשְׂרָאֵל חוּץ מֵחֵרֵשׁ שׁוֹטֶה וְקָטָן שֶׁנֶּאֱמַר (במדבר יט ט) \"וְאָסַף אִישׁ טָהוֹר\" מִכְּלַל שֶׁאֵינָהּ צְרִיכָה כֹּהֵן וּכְאִלּוּ אָמַר אָדָם טָהוֹר בֵּין אִישׁ בֵּין אִשָּׁה. וּמִנַּיִן שֶׁהַמְּלָאכָה פּוֹסֶלֶת בָּהּ שֶׁנֶּאֱמַר (במדבר יט ג) \"וְשָׁחַט אֹתָהּ\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁלֹּא בָּא הַכָּתוּב אֶלָּא לְלַמֵּד שֶׁאִם נִתְעַסֵּק בְּדָבָר אַחֵר בִּשְׁעַת שְׁחִיטָתָהּ פְּסָלָהּ וְנֶאֱמַר (במדבר יט ה) \"וְשָׂרַף אֶת הַפָּרָה לְעֵינָיו\" שֶׁיִּהְיוּ עֵינָיו בָּהּ לְלַמֵּד שֶׁהַמְּלָאכָה פּוֹסֶלֶת בָּהּ מִשְּׁעַת שְׁחִיטָה עַד שֶׁתֵּעָשֶׂה אֵפֶר. וְכָל הָעוֹסֵק בִּשְׂרֵפָתָהּ וְעָשָׂה מְלָאכָה אַחֶרֶת פְּסָלָהּ עַד שֶׁתֵּעָשֶׂה אֵפֶר:","שָׁחַט אֶת הַפָּרָה וְנִשְׁחֲטָה בְּהֵמָה אַחֶרֶת עִמָּהּ אוֹ נֶחְתְכָה דְּלַעַת עִמָּהּ כְּשֵׁרָה שֶׁהֲרֵי לֹא נִתְכַּוֵּן לִמְלָאכָה אַף עַל פִּי שֶׁהַבְּהֵמָה שֶׁנִּשְׁחֲטָה עִמָּהּ כְּשֵׁרָה לַאֲכִילָה שֶׁאֵין שְׁחִיטַת הַחֻלִּין צְרִיכָה כַּוָּנָה. אֲבָל אִם נִתְכַּוֵּן לַחְתֹּךְ הַדְּלַעַת וְנֶחְתְכָה בִּשְׁעַת שְׁחִיטָה פְּסוּלָה שֶׁהֲרֵי עָשָׂה עִמָּהּ מְלָאכָה:"],"Mishneh Torah, Repentance 6":["פְּסוּקִים הַרְבֵּה יֵשׁ בַּתּוֹרָה וּבְדִבְרֵי נְבִיאִים שֶׁהֵן נִרְאִין כְּסוֹתְרִין עִקָּר זֶה וְנִכְשָׁלִין בָּהֶן רֹב הָאָדָם וְיַעֲלֶה עַל דַּעְתָּן מֵהֶן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוּא גּוֹזֵר עַל הָאָדָם לַעֲשׂוֹת רָעָה אוֹ טוֹבָה וְשֶׁאֵין לִבּוֹ שֶׁל אָדָם מָסוּר לוֹ לְהַטּוֹתוֹ לְכָל אֲשֶׁר יִרְצֶה. וַהֲרֵי אֲנִי מְבָאֵר עִקָּר גָּדוֹל שֶׁמִּמֶּנּוּ תֵּדַע פֵּרוּשׁ כָּל אוֹתָן הַפְּסוּקִים. בִּזְמַן שֶׁאָדָם אֶחָד אוֹ אַנְשֵׁי מְדִינָה חוֹטְאִים וְעוֹשֶׂה הַחוֹטֵא חֵטְא שֶׁעוֹשֶׂה מִדַּעְתּוֹ וּבִרְצוֹנוֹ כְּמוֹ שֶׁהוֹדַעְנוּ רָאוּי לְהִפָּרַע מִמֶּנּוּ וְהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹדֵעַ אֵיךְ יִפָּרַע. יֵשׁ חֵטְא שֶׁהַדִּין נוֹתֵן שֶׁנִּפְרָעִים מִמֶּנּוּ עַל חֶטְאוֹ בָּעוֹלָם הַזֶּה בְּגוּפוֹ אוֹ בְּמָמוֹנוֹ אוֹ בְּבָנָיו הַקְּטַנִּים שֶׁבָּנָיו שֶׁל אָדָם הַקְּטַנִּים שֶׁאֵין בָּהֶם דַּעַת וְלֹא הִגִּיעוּ לִכְלַל מִצְווֹת כְּקִנְיָנוֹ הֵן וּכְתִיב (דברים כד טז) \"אִישׁ בְּחֶטְאוֹ יָמוּת\" עַד שֶׁיֵּעָשֶׂה אִישׁ. וְיֵשׁ חֵטְא שֶׁהַדִּין נוֹתֵן שֶׁנִּפְרָעִין מִמֶּנּוּ לָעוֹלָם הַבָּא וְאֵין לָעוֹבֵר עָלָיו שׁוּם נֵזֶק בָּעוֹלָם הַזֶּה. וְיֵשׁ חֵטְא שֶׁנִּפְרָעִין מִמֶּנּוּ בָּעוֹלָם הַזֶּה וְלָעוֹלָם הַבָּא:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁלֹּא עָשָׂה תְּשׁוּבָה אֲבָל אִם עָשָׂה תְּשׁוּבָה הַתְּשׁוּבָה כִּתְרִיס לִפְנֵי הַפֻּרְעָנוּת. וּכְשֵׁם שֶׁהָאָדָם חוֹטֵא מִדַּעְתּוֹ וּבִרְצוֹנוֹ כָּךְ הוּא עוֹשֶׂה תְּשׁוּבָה מִדַּעְתּוֹ וּבִרְצוֹנוֹ:","וְאֶפְשָׁר שֶׁיֶּחְטָא אָדָם חֵטְא גָּדוֹל אוֹ חֲטָאִים רַבִּים עַד שֶׁיִּתֵּן הַדִּין לִפְנֵי דַּיַן הָאֱמֶת שֶׁיְּהֵא הַפֵּרָעוֹן מִזֶּה הַחוֹטֵא עַל חֲטָאִים אֵלּוּ שֶׁעָשָׂה בִּרְצוֹנוֹ וּמִדַּעְתּוֹ שֶׁמּוֹנְעִין מִמֶּנּוּ הַתְּשׁוּבָה וְאֵין מַנִּיחִין לוֹ רְשׁוּת לָשׁוּב מֵרִשְׁעוֹ כְּדֵי שֶׁיָּמוּת וְיֹאבַד בְּחֶטְאוֹ שֶׁעָשָׂה. הוּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר עַל יְדֵי יְשַׁעְיָהוּ (ישעיה ו י) \"הַשְׁמֵן לֵב הָעָם הַזֶּה\" וְגוֹ'. וְכֵן הוּא אוֹמֵר (דה\"ב לו טז) \"וַיִּהְיוּ מַלְעִבִים בְּמַלְאֲכֵי הָאֱלֹהִים וּבוֹזִים דְּבָרָיו וּמִתַּעְתְּעִים בִּנְבִאָיו עַד עֲלוֹת חֲמַת ה' בְּעַמּוֹ עַד לְאֵין מַרְפֵּא\". כְּלוֹמַר חָטְאוּ בִּרְצוֹנָם וְהִרְבּוּ לִפְשֹׁעַ עַד שֶׁנִּתְחַיְּבוּ לִמְנֹעַ מֵהֶן הַתְּשׁוּבָה שֶׁהִיא הַמַּרְפֵּא. לְפִיכָךְ כָּתוּב בַּתּוֹרָה (שמות ד כא) \"וַאֲנִי (אֲחַזֵּק) [אַקְשֶׁה] אֶת לֵב פַּרְעֹה\". לְפִי שֶׁחָטָא מֵעַצְמוֹ תְּחִלָּה וְהֵרֵעַ לְיִשְׂרָאֵל הַגָּרִים בְּאַרְצוֹ שֶׁנֶּאֱמַר (שמות א י) \"הָבָה נִתְחַכְּמָה לוֹ\". נָתַן הַדִּין לִמְנֹעַ הַתְּשׁוּבָה מִמֶּנּוּ עַד שֶׁנִּפְרַע מִמֶּנּוּ. לְפִיכָךְ חִזֵּק הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת לִבּוֹ. וְלָמָּה הָיָה שׁוֹלֵחַ לוֹ בְּיַד משֶׁה וְאוֹמֵר שְׁלַח וַעֲשֵׂה תְּשׁוּבָה וּכְבָר אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אֵין אַתָּה מְשַׁלֵּחַ שֶׁנֶּאֱמַר (שמות ט ל) \"וְאַתָּה וַעֲבָדֶיךָ יָדַעְתִּי\" וְגוֹ' (שמות ט טז) \"וְאוּלָם בַּעֲבוּר זֹאת הֶעֱמַדְתִּיךָ\". כְּדֵי לְהוֹדִיעַ לְבָאֵי הָעוֹלָם שֶׁבִּזְמַן שֶׁמּוֹנֵעַ הַקָּדוֹשׁ בָּרוּךְ הוּא הַתְּשׁוּבָה לַחוֹטֵא אֵינוֹ יָכוֹל לָשׁוּב אֶלָּא יָמוּת בְּרִשְׁעוֹ שֶׁעָשָׂה בִּתְחִלָּה בִּרְצוֹנוֹ. וְכֵן סִיחוֹן לְפִי עֲוֹנוֹת שֶׁהָיוּ לוֹ נִתְחַיֵּב לְמָנְעוֹ מִן הַתְּשׁוּבָה שֶׁנֶּאֱמַר (דברים ב ל) \"כִּי הִקְשָׁה ה' אֱלֹהֶיךָ אֶת רוּחוֹ וְאִמֵּץ אֶת לְבָבוֹ\". וְכֵן הַכְּנַעֲנִים לְפִי תּוֹעֲבוֹתֵיהֶן מָנַע מֵהֶן הַתְּשׁוּבָה עַד שֶׁעָשׂוּ מִלְחָמָה עִם יִשְׂרָאֵל. שֶׁנֶּאֱמַר (יהושע יא כ) \"כִּי מֵאֵת ה' הָיְתָה לְחַזֵּק אֶת לִבָּם לִקְרַאת הַמִּלְחָמָה עִם יִשְׂרָאֵל לְמַעַן הַחֲרִימָם\". וְכֵן יִשְׂרָאֵל בִּימֵי אֵלִיָּהוּ לְפִי שֶׁהִרְבּוּ לִפְשֹׁעַ מָנַע מֵאוֹתָן הַמַּרְבִּים לִפְשֹׁעַ תְּשׁוּבָה שֶׁנֶּאֱמַר (מלכים א יח לז) \"וְאַתָּה הֲסִבֹּתָ אֶת לִבָּם אֲחֹרַנִּית\" כְּלוֹמַר מָנַעְתָּ מֵהֶן הַתְּשׁוּבָה. נִמְצֵאתָ אוֹמֵר שֶׁלֹּא גָּזַר הָאֵל עַל פַּרְעֹה לְהָרַע לְיִשְׂרָאֵל. וְלֹא עַל סִיחוֹן לַחֲטֹא בְּאַרְצוֹ. וְלֹא עַל הַכְּנַעֲנִים לְהַתְעִיב. וְלֹא עַל יִשְׂרָאֵל לַעֲבֹד עֲבוֹדָה זָרָה. אֶלָּא כֻּלָּן חָטְאוּ מֵעַצְמָן וְכֻלָּן נִתְחַיְּבוּ לִמְנֹעַ מֵהֶן הַתְּשׁוּבָה:","וּכְעִנְיָן זֶה שׁוֹאֲלִין הַצַּדִּיקִים וְהַנְּבִיאִים בִּתְפִלָּתָם מֵאֵת ה' לְעָזְרָם עַל הָאֱמֶת. כְּמוֹ שֶׁאָמַר דָּוִד (תהילים כז יא) \"הוֹרֵנִי ה' דַּרְכֶּךָ\". כְּלוֹמַר אַל יִמְנָעוּנִי חֲטָאַי דֶּרֶךְ הָאֱמֶת שֶׁמִּמֶּנָּה אֵדַע דַּרְכְּךָ וְיִחוּד שְׁמֶךָ. וְכֵן זֶה שֶׁאָמַר (תהילים נא יד) \"וְרוּחַ נְדִיבָה תִסְמְכֵנִי\" כְּלוֹמַר תַּנִּיחַ רוּחִי לַעֲשׂוֹת חֶפְצְךָ וְאַל יִגְרְמוּ לִי חֲטָאַי לְמָנְעֵנִי מִתְּשׁוּבָה אֶלָּא תִּהְיֶה הָרְשׁוּת בְּיָדִי עַד שֶׁאֶחֱזֹר וְאָבִין וְאֵדַע דֶּרֶךְ הָאֱמֶת. וְעַל דֶּרֶךְ זוֹ כָּל הַדּוֹמֶה לִפְסוּקִים אֵלּוּ:","וּמַהוּ זֶה שֶׁאָמַר דָּוִד (תהילים כה ח) \"טוֹב וְיָשָׁר ה' עַל כֵּן יוֹרֶה חַטָּאִים בַּדָּרֶךְ\" (תהילים כה ט) \"יַדְרֵךְ עֲנָוִים\" וְגוֹ'. זֶה שֶׁשָּׁלַח נְבִיאִים לָהֶם מוֹדִיעִים דַּרְכֵי ה' וּמַחְזִירִין אוֹתָן בִּתְשׁוּבָה. וְעוֹד שֶׁנָּתַן בָּהֶם כֹּחַ לִלְמֹד וּלְהָבִין. שֶׁמִּדָּה זוֹ בְּכָל אָדָם שֶׁכָּל זְמַן שֶׁהוּא נִמְשָׁךְ בְּדַרְכֵי הַחָכְמָה וְהַצֶּדֶק מִתְאַוֶּה לָהֶן וְרוֹדֵף אוֹתָם. וְהוּא מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה בָּא לִטַּהֵר מְסַיְּעִין אוֹתוֹ כְּלוֹמַר יִמְצָא עַצְמוֹ נֶעֱזָר עַל הַדָּבָר. וַהֲלֹא כָּתוּב בַּתּוֹרָה (בראשית טו יג) \"וַעֲבָדוּם וְעִנּוּ אֹתָם\", הֲרֵי גָּזַר עַל הַמִּצְרִיִּים לַעֲשׂוֹת רַע. וּכְתִיב (דברים לא טז) \"וְקָם הָעָם הַזֶּה וְזָנָה אַחֲרֵי אֱלֹהֵי נֵכַר הָאָרֶץ\", הֲרֵי גָּזַר עַל יִשְׂרָאֵל לַעֲבֹד עֲבוֹדָה זָרָה. וְלָמָּה נִפְרַע מֵהֶן. לְפִי שֶׁלֹּא גָּזַר עַל אִישׁ פְּלוֹנִי הַיָּדוּעַ שֶׁיִּהְיֶה הוּא הַזּוֹנֶה אֶלָּא כָּל אֶחָד וְאֶחָד מֵאוֹתָן הַזּוֹנִים לַעֲבֹד עֲבוֹדָה זָרָה אִלּוּ לֹא רָצָה לַעֲבֹד לֹא הָיָה עוֹבֵד. וְלֹא הוֹדִיעוֹ הַבּוֹרֵא אֶלָּא מִנְהָגוֹ שֶׁל עוֹלָם. הָא לְמָה זֶה דּוֹמֶה לְאוֹמֵר הָעָם הַזֶּה יִהְיֶה בָּהֶן צַדִּיקִים וּרְשָׁעִים. לֹא מִפְּנֵי זֶה יֹאמַר הָרָשָׁע כְּבָר נִגְזַר עָלָיו שֶׁיִּהְיֶה רָשָׁע מִפְּנֵי שֶׁהוֹדִיעַ לְמשֶׁה שֶׁיִּהְיוּ רְשָׁעִים בְּיִשְׂרָאֵל. כָּעִנְיָן שֶׁנֶּאֱמַר (דברים טו יא) \"כִּי לֹא יֶחְדַּל אֶבְיוֹן מִקֶּרֶב הָאָרֶץ\". וְכֵן הַמִּצְרִיִּים כָּל אֶחָד וְאֶחָד מֵאוֹתָן הַמְּצֵרִים וְהַמֵּרֵעִים לְיִשְׂרָאֵל אִלּוּ לֹא רָצָה לְהָרַע לָהֶם הָרְשׁוּת בְּיָדוֹ. שֶׁלֹּא גָּזַר עַל אִישׁ יָדוּעַ אֶלָּא הוֹדִיעוֹ שֶׁסּוֹף זַרְעוֹ עָתִיד לְהִשְׁתַּעְבֵּד בְּאֶרֶץ לֹא לָהֶם. וּכְבָר אָמַרְנוּ שֶׁאֵין כֹּחַ בָּאָדָם לֵידַע הֵיאַךְ יֵדַע הַקָּדוֹשׁ בָּרוּךְ הוּא דְּבָרִים הָעֲתִידִין לִהְיוֹת:"],"Mishneh Torah, Rest on the Tenth of Tishrei 1":["מִצְוַת עֲשֵׂה לִשְׁבֹּת מִמְּלָאכָה בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי שֶׁנֶּאֱמַר (ויקרא כג לב) \"שַׁבַּת שַׁבָּתוֹן הוּא לָכֶם\". וְכָל הָעוֹשֶׂה בּוֹ מְלָאכָה בִּטֵּל מִצְוַת עֲשֵׂה וְעָבַר עַל לֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (במדבר כט ז) \"וּבֶעָשׂוֹר\" וְגוֹ' (במדבר כט ז) \"כָּל מְלָאכָה לֹא תַעֲשׂוּ\". וּמַה הוּא חַיָּב עַל עֲשִׂיַּת מְלָאכָה בְּיוֹם זֶה. אִם עָשָׂה בִּרְצוֹנוֹ בְּזָדוֹן חַיָּב כָּרֵת. וְאִם עָשָׂה בִּשְׁגָגָה חַיָּב קָרְבַּן חַטָּאת קְבוּעָה:","כָּל מְלָאכָה שֶׁחַיָּבִין עַל זְדוֹנָהּ בְּשַׁבָּת סְקִילָה חַיָּבִין עַל זְדוֹנָהּ בֶּעָשׂוֹר כָּרֵת. וְכָל שֶׁחַיָּבִין עָלָיו קָרְבַּן חַטָּאת בְּשַׁבָּת חַיָּבִין עָלָיו קָרְבַּן חַטָּאת בְּיוֹם הַכִּפּוּרִים. וְכָל דָּבָר שֶׁאָסוּר לַעֲשׂוֹתוֹ בְּשַׁבָּת אַף עַל פִּי שֶׁאֵינוֹ מְלָאכָה אָסוּר לַעֲשׂוֹתוֹ בְּיוֹם הַכִּפּוּרִים. וְאִם עָשָׂה מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת כְּדֶרֶךְ שֶׁמַּכִּין אוֹתוֹ עַל הַשַּׁבָּת. וְכָל שֶׁאָסוּר לְטַלְטְלוֹ בְּשַׁבָּת אָסוּר לְטַלְטְלוֹ בְּיוֹם הַכִּפּוּרִים. וְכָל שֶׁאָסוּר לְאָמְרוֹ אוֹ לַעֲשׂוֹתוֹ לְכַתְּחִלָּה בְּשַׁבָּת כָּךְ אָסוּר בְּיוֹם הַכִּפּוּרִים. כְּלָלוֹ שֶׁל דָּבָר אֵין בֵּין שַׁבָּת לְיוֹם הַכִּפּוּרִים בְּעִנְיָנִים אֵלּוּ אֶלָּא שֶׁזְּדוֹן מְלָאכָה בְּשַׁבָּת בִּסְקִילָה וּבְיוֹם הַכִּפּוּרִים בְּכָרֵת:","וּמֻתָּר לְקַנֵּב אֶת הָיָּרָק בְּיוֹם הַכִּפּוּרִים מִן הַמִּנְחָה וּלְמַעְלָה. וּמַהוּ הַקִּינוּב שֶׁיָּסִיר אֶת הֶעָלִים הַמְעֻפָּשׁוֹת וִיקַצֵּץ הַשְּׁאָר וִיתַקֵּן אוֹתוֹ לַאֲכִילָה. וְכֵן מְפַצְּעִין בֶּאֱגוֹזִין וּמְפָרְכִין בְּרִמּוֹנִים מִן הַמִּנְחָה וּלְמַעְלָה מִפְּנֵי עָגְמַת נֶפֶשׁ. וְיוֹם הַכִּפּוּרִים שֶׁחָל לִהְיוֹת בְּשַׁבָּת אָסוּר בִּקְנִיבַת יָרָק וּבִפְצִיעַת אֱגוֹזִים וּבִפְרִיכַת רִמּוֹנִים כָּל הַיּוֹם. וּכְבָר נָהֲגוּ הָעָם בְּשִׁנְעָר וּבַמַּעֲרָב שֶׁלֹּא יַעֲשׂוּ אַחַת מִכָּל אֵלּוּ בְּיוֹם הַצּוֹם אֶלָּא הֲרֵי הוּא כְּשַׁבָּת לְכָל דְּבָרָיו:","מִצְוַת עֲשֵׂה אַחֶרֶת יֵשׁ בְּיוֹם הַכִּפּוּרִים וְהִיא לִשְׁבֹּת בּוֹ מֵאֲכִילָה וּשְׁתִיָּה שֶׁנֶּאֱמַר (ויקרא טז כט) \"תְּעַנּוּ אֶת נַפְשֹׁתֵיכֶם\". מִפִּי הַשְּׁמוּעָה לָמְדוּ אֵי זֶה הוּא עִנּוּי שֶׁהוּא לַנֶּפֶשׁ זֶה הַצּוֹם. וְכָל הַצָּם בּוֹ קִיֵּם מִצְוַת עֲשֵׂה. וְכָל הָאוֹכֵל וְשׁוֹתֶה בּוֹ בִּטֵּל מִצְוַת עֲשֵׂה וְעָבַר עַל לֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (ויקרא כג כט) \"כִּי כָל הַנֶּפֶשׁ אֲשֶׁר לֹא תְעֻנֶּה בְּעֶצֶם הַיּוֹם הַזֶּה וְנִכְרְתָה\". מֵאַחַר שֶׁעָנַשׁ הַכָּתוּב כָּרֵת לְמִי שֶׁלֹּא נִתְעַנָּה לָמַדְנוּ שֶׁמֻּזְהָרִין אָנוּ בּוֹ עַל אֲכִילָה וּשְׁתִיָּה. וְכָל הָאוֹכֵל אוֹ הַשּׁוֹתֶה בּוֹ בְּשׁוֹגֵג חַיָּב קָרְבַּן חַטָּאת קְבוּעָה:","וְכֵן לָמַדְנוּ מִפִּי הַשְּׁמוּעָה שֶׁאָסוּר לִרְחֹץ בּוֹ אוֹ לָסוּךְ אוֹ לִנְעל אֶת הַסַּנְדָּל אוֹ לִבְעל. וּמִצְוָה לִשְׁבֹּת מִכָּל אֵלּוּ כְּדֶרֶךְ שֶׁשּׁוֹבֵת מַאֲכִילָה וּשְׁתִיָּה שֶׁנֶּאֱמַר (ויקרא טז לא) (ויקרא כג לב) שַׁבַּת שַׁבָּתוֹן שַׁבָּת לְעִנְיַן (אֲכִילָה) וְשַׁבָּתוֹן לְעִנְיָנִים אֵלּוּ. וְאֵין חַיָּבִין כָּרֵת אוֹ קָרְבָּן אֶלָּא עַל אֲכִילָה וּשְׁתִיָּה. אֲבָל אִם רָחַץ אוֹ סָךְ אוֹ נָעַל אוֹ בָּעַל מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","כְּשֵׁם שֶׁשְּׁבוּת מְלָאכָה בּוֹ בֵּין בַּיּוֹם וּבֵין בַּלַּיְלָה כָּךְ שְׁבוּת לְעִנּוּי בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה. וְצָרִיךְ לְהוֹסִיף מֵחֹל עַל הַקֹּדֶשׁ בִּכְנִיסָתוֹ וּבִיצִיאָתוֹ שֶׁנֶּאֱמַר (ויקרא כג לב) \"וְעִנִּיתֶם אֶת נַפְשֹׁתֵיכֶם בְּתִשְׁעָה לַחֹדֶשׁ בָּעֶרֶב\". כְּלוֹמַר הַתְחֵיל לָצוּם וּלְהִתְעַנּוֹת מֵעֶרֶב תִּשְׁעָה הַסָּמוּךְ לַעֲשִׂירִי. וְכֵן בַּיְצִיאָה שׁוֹהָה בְּעִנּוּיוֹ מְעַט מִלֵּיל אַחַד עָשָׂר סָמוּךְ לַעֲשִׂירִי שֶׁנֶּאֱמַר (ויקרא כג לב) \"מֵעֶרֶב וְעַד עֶרֶב תִּשְׁבְּתוּ שַׁבַּתְּכֶם\":","נָשִׁים שֶׁאוֹכְלוֹת וְשׁוֹתוֹת עַד שֶׁחֲשֵׁכָה וְהֵן אֵינָן יוֹדְעוֹת שֶׁמִּצְוָה לְהוֹסִיף מֵחֹל עַל הַקֹּדֶשׁ אֵין מְמַחִין בְּיָדָן שֶׁלֹּא יָבוֹאוּ לַעֲשׂוֹת בְּזָדוֹן. שֶׁהֲרֵי אִי אֶפְשָׁר שֶׁיִּהְיֶה שׁוֹטֵר בְּבֵית כָּל אֶחָד וְאֶחָד לְהַזְהִיר נָשָׁיו. וְהָנַח לָהֶן שֶׁיְּהוּ שׁוֹגְגִין וְאַל יְהוּ מְזִידִין. וְכֵן כָּל הַדּוֹמֶה לָזֶה:"],"Mishneh Torah, Ritual Slaughter 5":["כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת אִסּוּרֵי מַאֲכָלוֹת שֶׁהַטְּרֵפָה הָאֲמוּרָה בַּתּוֹרָה הִיא הַנּוֹטָה לָמוּת. וְלֹא נֶאֱמַר (שמות כב ל) \"טְרֵפָה\" אֶלָּא שֶׁדִּבֵּר הַכָּתוּב בָּהוֹוֶה כְּגוֹן שֶׁטְּרָפָהּ אֲרִי וְכַיּוֹצֵא בּוֹ וּשְׁבָרָהּ וַעֲדַיִן לֹא מֵתָה:","וְיֵשׁ שָׁם חֳלָאִים אֲחֵרִים אִם יֶאֶרְעוּ לָהּ תֵּחָשֵׁב טְרֵפָה וְהֵן הֲלָכָה לְמשֶׁה מִסִּינַי. וּשְׁמוֹנָה מִינֵי טְרֵפוֹת נֶאֶמְרוּ לוֹ לְמשֶׁה בְּסִינַי וְאֵלּוּ הֵן. דְּרוּסָה. נְקוּבָה. חֲסֵרָה. נְטוּלָה. פְּסוּקָה. קְרוּעָה. נְפוּלָה. וּשְׁבוּרָה:","אַף עַל פִּי שֶׁכֻּלָּן הֲלָכָה לְמשֶׁה מִסִּינַי הֵן. הוֹאִיל וְאֵין לְךָ בְּפֵרוּשׁ בַּתּוֹרָה אֶלָּא דְּרוּסָה הֶחְמִירוּ בָּהּ. וְכָל סָפֵק שֶׁיִּסְתַּפֵּק בִּדְרוּסָה אָסוּר. וּשְׁאָר שִׁבְעָה מִינֵי טְרֵפוֹת יֵשׁ בָּהֶן סְפֵקִין מֻתָּרִים כְּמוֹ שֶׁיִּתְבָּאֵר:","הַדְּרוּסָה הוּא שֶׁיִּטְרֹף הָאֲרִי וְכַיּוֹצֵא בּוֹ הַבְּהֵמָה וְיִדְרֹס עָלֶיהָ בְּיָדוֹ. אוֹ יִדְרֹס הַנֵּץ וְהַנֶּשֶׁר וְכַיּוֹצֵא בָּהֶן עַל הָעוֹף. וְאֵין דְּרִיסָה בִּבְהֵמָה גַּסָּה וּבְחַיָּה גַּסָּה אֶלָּא לַאֲרִי בִּלְבַד. וּבִבְהֵמָה דַּקָּה מִן הַזְּאֵב וּלְמַעְלָה. וּבִגְדָיִים וּטְלָאִים אֲפִלּוּ חָתוּל וְשׁוּעָל וּנְמִיָּה וְכַיּוֹצֵא בָּהֶן יֵשׁ לָהֶן דְּרִיסָה וְכָל שֶׁכֵּן בְּעוֹפוֹת:","וְהַנֵּץ יֵשׁ לוֹ דְּרִיסָה וַאֲפִלּוּ בְּעוֹף גָּדוֹל מִמֶּנּוּ. אֲבָל שְׁאָר עוֹפוֹת הַדּוֹרְסִים יֵשׁ לָהֶן דְּרִיסָה בְּעוֹף שֶׁכְּמוֹתָן. וְאֵין לָהֶן דְּרִיסָה בְּעוֹף שֶׁהוּא גָּדוֹל מֵהֶן:","וְיֵשׁ לְחֻלְדָּה דְּרִיסָה בְּעוֹפוֹת. וְכֶלֶב אֵין לוֹ דְּרִיסָה כָּל עִקָּר לֹא בְּעוֹף וְלֹא בִּבְהֵמָה וְחַיָּה. וְהַנֵּץ יֵשׁ לוֹ דְּרִיסָה בִּגְדָיִים וּטְלָאִים וְהוּא שֶׁיִּקֹּב בְּצִפָּרְנָיו לְבֵית הֶחָלָל:","אֵין דְּרִיסָה אֶלָּא בְּיַד הַטּוֹרֵף אֲבָל בְּרַגְלָיו אֵין חוֹשְׁשִׁין לָהּ. וְאֵין דְּרִיסָה אֶלָּא בְּצִפֹּרֶן אֲבָל בְּשֵׁן אֵין חוֹשְׁשִׁין לָהּ אֶלָּא אִם כֵּן נִקַּב עַד בֵּית הֶחָלָל בּוֹדְקִין שֶׁמָּא נִקַּב אֶחָד מִן הָאֵיבָרִים שֶׁנִּטְרֶפֶת בִּנְקִיבָתָן. וְאֵין דְּרִיסָה אֶלָּא בְּכַוָּנַת הַטּוֹרֵף. אֲבָל אִם נָפַל הַדּוֹרֵס וְנִשְׁתַּקְּעוּ צִפָּרְנָיו בַּנִּטְרַף אֵין זוֹ דְּרִיסָה. וְאֵין דְּרִיסָה אֶלָּא מֵחַיִּים. אֲבָל אִם דָּרַס וְנֶהֱרַג וַעֲדַיִן יָדוֹ בַּדְּרוּסָה וְלֹא שָׁמַט צִפָּרְנָיו מִמֶּנָּה אֶלָּא אַחַר מוֹתוֹ אֵין חוֹשְׁשִׁין לָהּ:","וְכֵיצַד דִּין הַדְּרוּסָה. כָּל מָקוֹם שֶׁאָמַרְנוּ חוֹשְׁשִׁין לָהּ שׁוֹחֲטִין אֶת הַנִּטְרָף וּבוֹדְקִין כָּל הֶחָלָל שֶׁלּוֹ מִכַּף הַיָּרֵךְ עַד הַקָּדְקֹד. אִם נִמְצֵאת כֻּלָּהּ שְׁלֵמָה מִכָּל מִינֵי טְרֵפוֹת וְלֹא נִמְצָא בָּהּ רשֶׁם הַדְּרִיסָה הֲרֵי זוֹ מֻתֶּרֶת. וְאִם נִמְצָא בָּהּ רשֶׁם הַדְּרִיסָה הֲרֵי זוֹ טְרֵפָה וַאֲסוּרָה מִן הַתּוֹרָה:","אֵי זֶה הוּא רשֶׁם הַדְּרִיסָה. שֶׁיַּאְדִּים הַבָּשָׂר כְּנֶגֶד בְּנֵי מֵעַיִם. וְאִם נִמֹּק הַבָּשָׂר כְּנֶגֶד בְּנֵי מֵעַיִם עַד שֶׁנַּעֲשָׂה כְּבָשָׂר שֶׁהָרוֹפֵא גּוֹרְרוֹ מִן הַחַבּוּרָה רוֹאִין אוֹתוֹ הַבָּשָׂר כְּאִלּוּ חָסֵר וּטְרֵפָה:","וְאִם דָּרַס בַּסִּימָנִין מִשֶּׁיַּאֲדִימוּ טְרֵפָה וּדְרִיסָתָן בְּמַשֶּׁהוּ כֵּיוָן שֶׁהֶאֱדִים בָּהֶן כָּל שֶׁהוּא מֵחֲמַת דְּרִיסָה טְרֵפָה:","סְפֵק דְּרוּסָה אֲסוּרָה עַד שֶׁתִּבָּדֵק כִּדְרוּסָה וַדָּאִית. כֵּיצַד. אֲרִי שֶׁנִּכְנַס לְבֵין שְׁוָרִים וְנִמְצָא צִפֹּרֶן בְּגַבּוֹ שֶׁל אֶחָד מֵהֶן חוֹשְׁשִׁין שֶׁמָּא אֲרִי דְּרָסוֹ. וְאֵין אוֹמְרִים שֶׁמָּא בַּכֹּתֶל נִתְחַכֵּךְ. וְכֵן שׁוּעָל אוֹ נְמִיָּה שֶׁנִּכְנַס לְבֵין הָעוֹפוֹת וְהוּא שׁוֹתֵק וְהֵן מְקַרְקְרִין חוֹשְׁשִׁין שֶׁמָּא דָּרַס. אֲבָל אִם הָיָה הוּא נוֹהֵם וְהֵם מְקַרְקְרִין מִיִּרְאָתוֹ וּמִנְּהִימָתוֹ הֵן מְקַרְקְרִין. וְכֵן אִם קָטַע רֹאשׁ אֶחָד מֵהֶן הִנֵּה נָח רָגְזוֹ. וְכֵן אִם שָׁתַק הוּא וְהֵם אֵין חוֹשְׁשִׁין שֶׁאִלּוּ הִזִּיק הָיוּ מְקַרְקְרִין:","סָפֵק שֶׁנִּכְנַס לְכָאן טוֹרֵף אוֹ לֹא נִכְנַס. אוֹ שֶׁרָאִינוּ וְלֹא נוֹדַע אִם זֶה מִן הַטּוֹרְפִין אוֹ אֵינוֹ מִן הַטּוֹרְפִין אֵין חוֹשְׁשִׁין. וְכֵן עוֹף שֶׁנִּכְנַס לְבֵין הָעֵצִים אוֹ לְבֵין הַקָּנִים וְיָצָא וְרֹאשׁוֹ מְנַטֵּף דָּם אוֹ צַוָּארוֹ אֵין חוֹשְׁשִׁין לוֹ שֶׁמָּא נִטְרַף אֶלָּא אוֹמְרִים שֶׁמָּא בָּעֵצִים נִזַּק:"],"Mishneh Torah, Robbery and Lost Property 16":["הַמּוֹצֵא מְחָטִים וְצִנּוֹרוֹת וּמַסְמְרִים וְכַיּוֹצא בָּהֶן אִם מְצָאָם אֶחָד אֶחָד הֲרֵי אֵלּוּ שֶׁלּוֹ. שְׁנַיִם שְׁנַיִם אוֹ יֶתֶר חַיָּב לְהַכְרִיז שֶׁמִּנְיָן סִימָן:","וְכֵן הַמּוֹצֵא מָעוֹת מְפֻזָּרִים הֲרֵי אֵלּוּ שֶׁלּוֹ. אֲפִלּוּ הָיוּ מִקְצָת מַטְבְּעוֹת זֶה עַל גַּבֵּי זֶה הֲרֵי הֵן כִּמְפֻזָּרִין. אֲבָל אִם מָצָא צִבּוּר מָעוֹת חַיָּב לְהַכְרִיז. מָצָא שְׁלֹשָׁה מַטְבְּעוֹת זֶה עַל גַּב זֶה וְהֵן עֲשׂוּיִין כְּמִגְדָּל. אוֹ שֶׁהָיוּ אֶחָד מִיכַּן וְאֶחָד מִיכַּן וְאֶחָד עַל גַּבֵּיהֶן. אוֹ שֶׁהָיוּ מִקְצָת זֶה עַל מִקְצָת זֶה כְּדֵי שֶׁאִם יַכְנִיס קֵיסָם בֵּינֵיהֶן יִנָּטְלוּ בְּבַת אַחַת חַיָּב לְהַכְרִיז. הָיוּ עֲשׂוּיִים כְּשִׁיר אוֹ כְּשׁוּרָה אוֹ כַּחֲצוּבָה אוֹ כְּסֻלָּם הֲרֵי זֶה סָפֵק וְלֹא יִטּל:","הַמּוֹצֵא מָעוֹת בַּכִּיס אוֹ כִּיס כְּמוֹת שֶׁהוּא חַיָּב לְהַכְרִיז. מָצָא כִּיס וּלְפָנָיו מָעוֹת מְפֻזָּרִים הֲרֵי אֵלּוּ שֶׁלּוֹ. וְאִם מַרְאִין הַדְּבָרִים שֶׁהַכִּיס וְהַמָּעוֹת שֶׁל אָדָם אֶחָד וּמִן הַכִּיס נָפְלוּ חַיָּב לְהַכְרִיז:","הַמּוֹצֵא מָעוֹת בַּחֲנוּת אִם הָיוּ בֵּין תֵּבָה לַחֶנְוָנִי הֲרֵי הֵן שֶׁל בַּעַל הַחֲנוּת. וְאִם מְצָאָן עַל הַתֵּבָה וְאֵין צָרִיךְ לוֹמַר מִתֵּבָה וְלַחוּץ הֲרֵי הֵן שֶׁל מוֹצְאָן. וְלָמָּה לֹא תִּקְנֶה הַחֲנוּת לִבְעָלֶיהָ לְפִי שֶׁאֵינָהּ חָצֵר הַמִּשְׁתַּמֶּרֶת. וְאַף עַל פִּי שֶׁבְּעָלֶיהָ בְּתוֹכָהּ צָרִיךְ לוֹמַר תִּקְנֶה לִי חֲנוּתִי כְּמוֹ שֶׁיִּתְבָּאֵר:","מָצָא מָעוֹת בַּחֲנוּת הַשֻּׁלְחָנִי בֵּין כִּסֵּא לַשֻּׁלְחָנִי הֲרֵי אֵלּוּ שֶׁל שֻׁלְחָנִי. מְצָאָן עַל הַכִּסֵּא לִפְנֵי הַשֻּׁלְחָנִי אֲפִלּוּ הָיוּ צְרוּרִין וּמֻנָּחִין עַל הַשֻּׁלְחָן הֲרֵי אֵלּוּ שֶׁל מוֹצְאָן. וְהוּא שֶׁיִּהְיוּ רֹב עַכּוּ\"ם כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל אִם הָיוּ רֹב יִשְׂרָאֵל חַיָּב לְהַכְרִיז. מִפְּנֵי שֶׁהֵן צְרוּרִים יֵשׁ לָהֶם סִימָן:","הַלּוֹקֵחַ פֵּרוֹת מֵחֲבֵרוֹ אוֹ שֶׁשָּׁלַח לוֹ חֲבֵרוֹ פֵּרוֹת וּמָצָא בְּתוֹכָן מָעוֹת צְרוּרוֹת נוֹטֵל וּמַכְרִיז. מְצָאָן מְפֻזָּרוֹת הֲרֵי אֵלּוּ שֶׁלּוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיוּ הַפֵּרוֹת מִן הַתַּגָּר אוֹ מִבַּעַל הַבַּיִת שֶׁלְּקָחָן מִן הַתַּגָּר. אֲבָל אִם בַּעַל הַבַּיִת דָּשׁ הַפֵּרוֹת לְעַצְמוֹ אוֹ עַל יְדֵי עֲבָדָיו וְשִׁפְחוֹתָיו הַכְּנַעֲנִים הֲרֵי זֶה חַיָּב לְהַחְזִיר:","הַמּוֹצֵא מַטְמוֹן בְּגַל אוֹ בְּכֹתֶל יָשָׁן הֲרֵי אֵלּוּ שֶׁלּוֹ שֶׁאֲנִי אוֹמֵר שֶׁל אֱמוֹרִיִּים הַקַּדְמוֹנִים הֵן. וְהוּא שֶׁיִּמְצָאֵם מַטָּה מַטָּה כְּדֶרֶךְ כָּל הַמַּטְמוֹנוֹת הַיְשָׁנוֹת. אֲבָל אִם מַרְאִין הַדְּבָרִים שֶׁהֵן מַטְמוֹן חָדָשׁ אֲפִלּוּ נִסְתַּפֵּק לוֹ הַדָּבָר הֲרֵי זֶה לֹא יִגַּע בָּהֶן שֶׁמָּא מֻנָּחִים הֵם שָׁם:","וְהוֹאִיל וַחֲצֵרוֹ שֶׁל אָדָם קוֹנָה לוֹ שֶׁלֹּא מִדַּעְתּוֹ כְּמוֹ שֶׁיִּתְבָּאֵר לָמָּה לֹא יִקְנֶה בַּעַל הֶחָצֵר זֶה הַמַּטְמוֹן שֶׁבְּתוֹךְ הַכֹּתֶל הַיָּשָׁן אַף עַל פִּי שֶׁהוּא שֶׁל אֱמוֹרִיִּים וְתִהְיֶה מְצִיאָה זוֹ לְבַעַל הֶחָצֵר. מִפְּנֵי שֶׁאֵינוֹ יָדוּעַ לוֹ וְלֹא לַאֲחֵרִים וַהֲרֵי זֶה הַמַּטְמוֹן אָבוּד מִמֶּנּוּ וּמִכָּל אָדָם וּלְפִיכָךְ הוּא שֶׁל מוֹצְאוֹ. וּמַה אֲבֵדָה שֶׁל אָדָם אָמְרָה תּוֹרָה (דברים כב ג) \"אֲשֶׁר תֹּאבַד מִמֶּנּוּ וּמְצָאתָהּ\" מִי שֶׁאֲבוּדָה מִמֶּנּוּ וּמְצוּיָה אֵצֶל כָּל אָדָם יָצָאת זוֹ שֶׁנָּפְלָה לַיָּם שֶׁאֲבוּדָה מִמֶּנּוּ וּמִכָּל אָדָם קַל וָחֹמֶר לְמַטְמוֹן קַדְמוֹנִי שֶׁלֹּא הָיָה שֶׁלּוֹ מֵעוֹלָם וְהוּא אָבוּד מִמֶּנּוּ וּמִכָּל אָדָם לְפִיכָךְ הוּא שֶׁל מוֹצְאוֹ:","מָצָא מַטְמוֹן בְּכֹתֶל חָדָשׁ אִם הַמַּטְמוֹן מוֹכִיחַ שֶׁהוּא לְבַעַל הַבַּיִת הֲרֵי הוּא שֶׁלּוֹ וְאִם מוֹכִיחַ שֶׁהוּא שֶׁל אַחֵר מִן הַשּׁוּק הֲרֵי הוּא שֶׁל מוֹצְאוֹ. כֵּיצַד. הַסַּכִּין הֲרֵי הַנִּצָּב שֶׁלּוֹ מוֹכִיחַ. וְהַכִּיס פִּיו מוֹכִיחַ. וְאִם נִמְצָא תּוֹךְ הַכֹּתֶל מָלֵא מֵהֶן חוֹלְקִין:","הָיוּ בְּתוֹךְ הַכֹּתֶל מָעוֹת אוֹ לְשׁוֹנוֹת שֶׁל זָהָב שֶׁאֵין שָׁם מוֹכִיחַ. מֵחֶצְיוֹ וְלַחוּץ שֶׁל מוֹצֵא. מֵחֶצְיוֹ וּלְפָנִים שֶׁל בַּעַל הַבַּיִת:","וְיֵרָאֶה לִי שֶׁאֵין הַדְּבָרִים אֲמוּרִים אֶלָּא כְּשֶׁטָּעַן בַּעַל הַבַּיִת שֶׁהַמַּטְמוֹן שֶׁלּוֹ. אוֹ שֶׁהָיָה יוֹרֵשׁ שֶׁאָנוּ טוֹעֲנִין לוֹ שֶׁמָּא שֶׁל אָבִיו הֵן. אֲבָל אִם הוֹדָה שֶׁהֵן מְצִיאָה הֲרֵי הֵן שֶׁל מוֹצֵא. לְפִיכָךְ אִם הָיָה מַשְׂכִּיר בֵּיתוֹ לַאֲחֵרִים הֲרֵי הֵן שֶׁל שׂוֹכֵר אַחֲרוֹן. וְאִם הִשְׂכִּירוֹ לִשְׁלֹשָׁה עַכּוּ\"ם כְּאֶחָד הֲרֵי עֲשָׂאָהוּ פֻּנְדָּק וְכָל הַנִּמְצָא בּוֹ אֲפִלּוּ בְּתוֹךְ הַבַּיִת הֲרֵי הוּא שֶׁל מוֹצְאָן מִפְּנֵי שֶׁאֵין אֶחָד יָכוֹל לִטְעֹן שֶׁהֵן שֶׁלּוֹ אוֹ שֶׁהוּא טָמַן שֶׁהֲרֵי עֲשָׂאָהוּ פֻּנְדָּק:"],"Mishneh Torah, Sabbath 10":["הַקוֹשֵׁר קֶשֶׁר שֶׁל קַיָּמָא וְהוּא מַעֲשֵׂה אֻמָּן חַיָּב. כְּגוֹן קֶשֶׁר הַגַּמָּלִין וְקֶשֶׁר הַסַּפָּנִין וְקִשְׁרֵי רְצוּעוֹת מִנְעָל וְסַנְדָּל שֶׁקּוֹשְׁרִין הָרַצְעָנִין בִּשְׁעַת עֲשִׂיָּתָן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. אֲבָל הַקּוֹשֵׁר קֶשֶׁר שֶׁל קַיָּמָא וְאֵינוֹ מַעֲשֵׂה אֻמָּן פָּטוּר. וְקֶשֶׁר שֶׁאֵינוֹ שֶׁל קַיָּמָא וְאֵינוֹ מַעֲשֵׂה אֻמָּן מֻתָּר לְקָשְׁרוֹ לְכַתְּחִלָּה:","כֵּיצַד. נִפְסְקָה לוֹ רְצוּעָה וּקְשָׁרָהּ, נִפְסַק הַחֶבֶל וּקְשָׁרוֹ, אוֹ שֶׁקָּשַׁר חֶבֶל בִּדְלִי אוֹ שֶׁקָּשַׁר רֶסֶן בְּהֵמָה הֲרֵי זֶה פָּטוּר. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ הַקְּשָׁרִים שֶׁהֵן מַעֲשֵׂה הֶדְיוֹט וְכָל אָדָם קוֹשֵׁר אוֹתָן לְקַיָּמָא. וְכָל קֶשֶׁר שֶׁאֵינוֹ שֶׁל קַיָּמָא אִם קְשָׁרוֹ קֶשֶׁר אֻמָּן הֲרֵי זֶה אָסוּר:","קוֹשֶׁרֶת אִשָּׁה מִפְתְּחֵי הֶחָלוּק אַף עַל פִּי שֶׁיֵּשׁ לוֹ שְׁנֵי פְּתָחִים, וְחוּטֵי סְבָכָה אַף עַל פִּי שֶׁהוּא רָפוּי בְּרֹאשָׁהּ, וּרְצוּעוֹת מִנְעָל וְסַנְדָּל שֶׁקּוֹשְׁרִין אוֹתָן עַל הָרֶגֶל בִּשְׁעַת מַלְבּוּשׁ, וְנוֹדוֹת יַיִן וְשֶׁמֶן אַף עַל פִּי שֶׁיֵּשׁ לוֹ שְׁתֵּי אָזְנַיִם, וּקְדֵרָה שֶׁל בָּשָׂר אַף עַל פִּי שֶׁיְּכוֹלָה לְהוֹצִיא הַבָּשָׂר וְלֹא תַּתִּיר הַקֶּשֶׁר. וְקוֹשְׁרִין דְּלִי בִּמְשִׁיחָה אוֹ בְּאַבְנֵט וְכַיּוֹצֵא בּוֹ אֲבָל לֹא בְּחֶבֶל. וְקוֹשְׁרִין לִפְנֵי הַבְּהֵמָה אוֹ בְּרַגְלָהּ בִּשְׁבִיל שֶׁלֹּא תֵּצֵא אַף עַל פִּי שֶׁיֵּשׁ לָהּ שְׁנֵי אִסָּרוֹת. וְחֶבֶל שֶׁהָיָה קָשׁוּר בַּפָּרָה קוֹשְׁרוֹ בָּאֵבוּס. הָיָה קָשׁוּר בָּאֵבוּס קוֹשְׁרוֹ בַּפָּרָה. אֲבָל לֹא יָבִיא חֶבֶל מִתּוֹךְ בֵּיתוֹ וְיִקְשֹׁר בַּפָּרָה וּבָאֵבוּס. וְאִם הָיָה חֶבֶל גַּרְדִּי שֶׁמֻּתָּר לְטַלְטְלוֹ הֲרֵי זֶה מֵבִיא וְקוֹשֵׁר בַּפָּרָה וּבָאֵבוּס. מִפְּנֵי שֶׁכָּל אֵלּוּ הַקְּשָׁרִים מַעֲשֵׂה הֶדְיוֹט הֵן וְאֵינָן שֶׁל קַיָּמָא אֶלָּא פַּעַם קוֹשֵׁר וּפַעַם מַתִּיר וּלְפִיכָךְ מֻתָּר לִקְשֹׁר אוֹתָן לְכַתְּחִלָּה. חוֹתָלוֹת שֶׁל תְּמָרִים וְשֶׁל גְּרוֹגָרוֹת מַתִּיר וּמַפְקִיעַ וְחוֹתֵךְ וְנוֹטֵל וְאוֹכֵל:","כָּל שֶׁרָאוּי לְמַאֲכַל בְּהֵמָה מֻתָּר לִקְשֹׁר אוֹתוֹ בְּשַׁבָּת. לְפִיכָךְ אִם נִפְסְקָה רְצוּעַת סַנְדָּלוֹ בְּכַרְמְלִית נוֹטֵל גֶּמִי לַח הָרָאוּי לְמַאֲכַל בְּהֵמָה וְכוֹרֵךְ עָלָיו וְקוֹשֵׁר הַגֶּמִי. נִשְׁמְטָה לוֹ רְצוּעַת מִנְעָל וְסַנְדָּל אוֹ שֶׁנִּשְׁמַט רֹב הָרֶגֶל מֻתָּר לְהַחֲזִיר הָרְצוּעוֹת לִמְקוֹמָן וּבִלְבַד שֶׁלֹּא יִקְשֹׁר:","הָעֲנִיבָה מֻתֶּרֶת לְפִי שֶׁאֵינָהּ מִתְחַלֶּפֶת בִּקְשִׁירָה. לְפִיכָךְ הַחֶבֶל שֶׁנִּפְסַק מְקַבֵּץ שְׁנֵי קְצוֹתָיו וְכוֹרֵךְ עָלָיו מְשִׁיחָה וְעוֹנֵב עֲנִיבָה:","מֻתָּר לִקְשֹׁר קֶשֶׁר שֶׁאֵינוֹ שֶׁל קַיָּמָא לִדְבַר מִצְוָה. כְּגוֹן שֶׁיִּקְשֹׁר לִמְדֹּד שִׁעוּר מִשִּׁעוּרֵי הַתּוֹרָה. נִימַת כִּנּוֹר שֶׁנִּפְסַק קוֹשְׁרִין אוֹתָהּ בַּמִּקְדָּשׁ אֲבָל לֹא בַּמְּדִינָה. וְלֹא יִקְשֹׁר נִימָא לְכַתְּחִלָּה אֲפִלּוּ בַּמִּקְדָּשׁ:","כָּל קֶשֶׁר שֶׁחַיָּבִין עַל קִשּׁוּרוֹ כָּךְ חַיָּבִין עַל הֶתֵּרוֹ. וְכָל קֶשֶׁר שֶׁהַקּוֹשֵׁר אוֹתוֹ פָּטוּר כָּךְ הַמַּתִּיר אוֹתוֹ פָּטוּר. וְכָל קֶשֶׁר שֶׁמֻּתָּר לְקָשְׁרוֹ כָּךְ מֻתָּר לְהַתִּירוֹ:","הַפּוֹתֵל חֲבָלִים מִן הַהוּצִין וּמִן הָחֶלֶף אוֹ מִחוּטֵי צֶמֶר אוֹ מִחוּטֵי פִּשְׁתָּן אוֹ חוּטֵי שֵׂעָר וְכַיּוֹצֵא בָּהֶן הֲרֵי זֶה תּוֹלֶדֶת קוֹשֵׁר וְחַיָּב. וְשִׁעוּרוֹ כְּדֵי שֶׁיַּעֲמֹד הַחֶבֶל בִּפְתִילָתוֹ בְּלֹא קְשִׁירָה שֶׁנִּמְצֵאת מְלַאכְתּוֹ מִתְקַיֶּמֶת. וְכֵן הַמַּפְרִיד אֶת הַפְּתִיל הֲרֵי זֶה תּוֹלֶדֶת מַתִּיר וְחַיָּב. וְהוּא שֶׁלֹּא יִתְכַּוֵּן לְקַלְקֵל בִּלְבַד. וְשִׁעוּרוֹ כְּשִׁעוּר הַפּוֹתֵל:","הַתּוֹפֵר שְׁתֵּי תְּפִירוֹת חַיָּב. וְהוּא שֶׁקָּשַׁר רָאשֵׁי הַחוּט מִכָּאן וּמִכָּאן כְּדֵי שֶׁתַּעֲמֹד הַתְּפִירָה וְלֹא תִּשָּׁמֵט. אֲבָל אִם תָּפַר יֶתֶר עַל שְׁתֵּי תְּפִירוֹת אַף עַל פִּי שֶׁלֹּא קָשַׁר חַיָּב שֶׁהֲרֵי מִתְקַיֶּמֶת הַתְּפִירָה. וְהַמּוֹתֵחַ חוּט שֶׁל תְּפִירָה בְּשַׁבָּת חַיָּב מִפְּנֵי שֶׁהוּא מִצָּרְכֵי הַתְּפִירָה:","הַקּוֹרֵעַ כְּדֵי לִתְפֹּר שְׁתֵּי תְּפִירוֹת עַל מְנָת לִתְפֹּר שְׁתֵּי תְּפִירוֹת חַיָּב. אֲבָל הַקּוֹרֵעַ לְהַפְסִידָהּ פָּטוּר מִפְּנֵי שֶׁהוּא מְקַלְקֵל. הַקּוֹרֵעַ בַּחֲמָתוֹ אוֹ עַל מֵת שֶׁהוּא חַיָּב לִקְרֹעַ עָלָיו חַיָּב מִפְּנֵי שֶׁמְּיַשֵּׁב אֶת דַּעְתּוֹ בְּדָבָר זֶה וְיָנוּחַ יִצְרוֹ וְהוֹאִיל וַחֲמָתוֹ שׁוֹכֶכֶת בְּדָבָר זֶה הֲרֵי הוּא כִּמְתַקֵּן וְחַיָּב. וְהַפּוֹתֵחַ בֵּית הַצַּוָּאר בְּשַׁבָּת חַיָּב:","הַמְדַבֵּק נְיָרוֹת אוֹ עוֹרוֹת בְּקוֹלָן שֶׁל סוֹפְרִים וְכַיּוֹצֵא בּוֹ הֲרֵי זֶה תּוֹלֶדֶת תּוֹפֵר וְחַיָּב. וְכֵן הַמְפָרֵק נְיָרוֹת דְּבוּקִין אוֹ עוֹרוֹת דְּבוּקִין וְלֹא נִתְכַּוֵּן לְקַלְקֵל בִּלְבַד הֲרֵי זֶה תּוֹלֶדֶת קוֹרֵעַ וְחַיָּב:","הַבּוֹנֶה כָּל שֶׁהוּא חַיָּב. הַמַּשְׁוֶה פְּנֵי הַקַּרְקַע בְּבַיִת כְּגוֹן שֶׁהִשְׁפִּיל תֵּל אוֹ מִלֵּא גּוּמָא אוֹ גַּיְא הֲרֵי זֶה בּוֹנֶה וְחַיָּב. אֶחָד נָתַן אֶת הָאֶבֶן וְאֶחָד נָתַן אֶת הַטִּיט הַנּוֹתֵן הַטִּיט חַיָּב. וּבַנִּדְבָּךְ הָעֶלְיוֹן אֲפִלּוּ הֶעֱלָה אֶת הָאֶבֶן וְהִנִּיחָהּ עַל גַּבֵּי הַטִּיט חַיָּב. שֶׁהֲרֵי אֵין מַנִּיחִין עָלֶיהָ טִיט אַחֵר. וְהַבּוֹנֶה עַל גַּבֵּי כֵּלִים פָּטוּר:","הָעוֹשֶׂה אֹהֶל קָבוּעַ הֲרֵי זֶה תּוֹלֶדֶת בּוֹנֶה וְחַיָּב. וְכֵן הָעוֹשֶׂה כְּלֵי אֲדָמָה כְּגוֹן תַּנּוּר וְחָבִית קֹדֶם שֶׁיִּשָּׂרְפוּ הֲרֵי זֶה תּוֹלֶדֶת בּוֹנֶה וְחַיָּב. וְכֵן הַמְגַבֵּן אֶת הַגְּבִינָה הֲרֵי זֶה תּוֹלֶדֶת בּוֹנֶה. וְאֵינוֹ חַיָּב עַד שֶׁיְּגַבֵּן כִּגְרוֹגֶרֶת. הַמַּכְנִיס יַד הַקַּרְדֹּם בְּתוֹךְ הָעֵץ שֶׁלּוֹ הֲרֵי זֶה תּוֹלֶדֶת בּוֹנֶה. וְכֵן כָּל כַּיּוֹצֵא בּוֹ. וְכֵן הַתּוֹקֵעַ עֵץ בְּעֵץ בֵּין שֶׁתָּקַע בְּמַסְמֵר בֵּין שֶׁתָּקַע בָּעֵץ עַצְמוֹ עַד שֶׁנִּתְאַחֵד הֲרֵי זֶה תּוֹלֶדֶת בּוֹנֶה וְחַיָּב:","הָעוֹשֶׂה נֶקֶב כָּל שֶׁהוּא בְּלוּל שֶׁל תַּרְנְגוֹלִים כְּדֵי שֶׁיִּכָּנֵס לָהֶן הָאוֹרָה חַיָּב מִשּׁוּם בּוֹנֶה. הַמַּחֲזִיר דֶּלֶת שֶׁל בּוֹר וְשֶׁל דּוּת וְשֶׁל יָצִיעַ חַיָּב מִשּׁוּם בּוֹנֶה:","הַסּוֹתֵר כָּל שֶׁהוּא חַיָּב. וְהוּא שֶׁיִּסְתֹּר עַל מְנָת לִבְנוֹת. אֲבָל אִם סָתַר דֶּרֶךְ הַשְׁחָתָה פָּטוּר. הַסּוֹתֵר אֹהֶל קָבוּעַ אוֹ שֶׁפֵּרֵק עֵץ תָּקוּעַ הֲרֵי זֶה תּוֹלֶדֶת סוֹתֵר וְחַיָּב וְהוּא שֶׁיִּתְכַּוֵּן לְתַקֵּן:","הַמַּכֶּה בְּפַטִּישׁ הַכָּאָה אַחַת חַיָּב. וְכָל הָעוֹשֶׂה דָּבָר שֶׁהוּא גְּמַר מְלָאכָה הֲרֵי זֶה תּוֹלֶדֶת מַכֶּה בְּפַטִּישׁ וְחַיָּב. כֵּיצַד. הַמְנַפֵּחַ בִּכְלֵי זְכוּכִית וְהַצָּר בַּכְּלִי צוּרָה אֲפִלּוּ מִקְצָת הַצּוּרָה וְהַמְגָרֵד כָּל שֶׁהוּא וְהָעוֹשֶׂה נֶקֶב כָּל שֶׁהוּא בֵּין בְּעֵץ בֵּין בְּמַתֶּכֶת בֵּין בְּבִנְיָן בֵּין בְּכֵלִים הֲרֵי זֶה תּוֹלֶדֶת מַכֶּה בְּפַטִּישׁ וְחַיָּב. וְכָל פֶּתַח שֶׁאֵינוֹ עָשׂוּי לְהַכְנִיס וּלְהוֹצִיא אֵין חַיָּבִין עַל עֲשִׂיָּתוֹ:","הַמֵּפִיס שְׁחִין בְּשַׁבָּת כְּדֵי לְהַרְחִיב פִּי הַמַּכָּה כְּדֶרֶךְ שֶׁהָרוֹפְאִין עוֹשִׂין שֶׁהֵן מִתְכַּוְּנִין בִּרְפוּאָה לְהַרְחִיב פִּי הַמַּכָּה הֲרֵי זֶה חַיָּב מִשּׁוּם מַכֶּה בְּפַטִּישׁ שֶׁזּוֹ הִיא מְלֶאכֶת הָרוֹפֵא. וְאִם הֵפִיסָה לְהוֹצִיא מִמֶּנָּה הַלֵּחָה שֶׁבָּהּ הֲרֵי זֶה מֻתָּר:","הַמְסַתֵּת אֶת הָאֶבֶן כָּל שֶׁהוּא חַיָּב מִשּׁוּם מַכֶּה בְּפַטִּישׁ. הַמְצַדֵּד אֶת הָאֶבֶן בִּיסוֹד הַבִּנְיָן וְתִקְּנָהּ בְּיָדוֹ וְהוֹשִׁיבָהּ בַּמָּקוֹם הָרָאוּי לָהּ חַיָּב מִשּׁוּם מַכֶּה בְּפַטִּישׁ. הַלּוֹקֵט יַבּוֹלֶת שֶׁעַל גַּבֵּי בְּגָדִים בְּיָדוֹ כְּגוֹן אֵלּוּ הַיַּבּוֹלוֹת שֶׁבִּכְלֵי צֶמֶר חַיָּב מִשּׁוּם מַכֶּה בְּפַטִּישׁ. וְהוּא שֶׁיַּקְפִּיד עֲלֵיהֶן. אֲבָל אִם הֱסִירָן דֶּרֶךְ עֵסֶק הֲרֵי זֶה פָּטוּר. הַמְנַעֵר טַלִּית חֲדָשָׁה שְׁחוֹרָה כְּדֵי לְנָאוֹתָהּ וּלְהָסִיר הַצֶּמֶר הַלָּבָן הַנִּתְלֶה בָּהּ כְּדֶרֶךְ שֶׁהָאֻמָּנִין עוֹשִׂין חַיָּב חַטָּאת. וְאִם אֵינוֹ מַקְפִּיד מֻתָּר:","הַצָּד דָּבָר שֶׁדֶּרֶךְ מִינוֹ לָצוּד אוֹתוֹ חַיָּב. כְּגוֹן חַיָּה וְעוֹפוֹת וְדָגִים. וְהוּא שֶׁיָּצוּד אוֹתָן לְמָקוֹם שֶׁאֵינוֹ מְחֻסַּר צֵידָה. כֵּיצַד. כְּגוֹן שֶׁרָדַף אַחֲרֵי צְבִי עַד שֶׁהִכְנִיסוֹ לְבַיִת אוֹ לְגִנָּה אוֹ לְחָצֵר וְנָעַל בְּפָנָיו. אוֹ שֶׁהִפְרִיחַ אֶת הָעוֹף עַד שֶׁהִכְנִיסוֹ לְמִגְדָּל וְנָעַל בְּפָנָיו. אוֹ שֶׁשָּׁלָה דָּגִים מִן הַיָּם בְּתוֹךְ סֵפֶל שֶׁל מַיִם הֲרֵי זֶה חַיָּב. אֲבָל אִם הִפְרִיחַ צִפּוֹר לְבַיִת וְנָעַל בְּפָנָיו. אוֹ שֶׁהִבְרִיחַ דָּג וַעֲקָרוֹ מִן הַיָּם לִבְרֵכָה שֶׁל מַיִם. אוֹ שֶׁרָדַף אַחַר צְבִי עַד שֶׁנִּכְנַס לִטְרַקְלִין רָחָב וְנָעַל בְּפָנָיו הֲרֵי זֶה פָּטוּר. שֶׁאֵין זוֹ צִידָה גְּמוּרָה שֶׁאִם יָבוֹא לְקַחְתּוֹ צָרִיךְ לִרְדֹּף אַחֲרָיו וְלָצוּד אוֹתוֹ מִשָּׁם. לְפִיכָךְ הַצָּד אֲרִי אֵינוֹ חַיָּב עַד שֶׁיַּכְנִיסֶנּוּ לַכִּפָּה שֶׁלּוֹ שֶׁהוּא נֶאֱסָר בָּהּ:","כָּל מָקוֹם שֶׁאִם יָרוּץ בּוֹ יַגִּיעַ לַחַיָּה בִּשְׁחִיָּה אַחַת. אוֹ שֶׁהָיוּ הַכְּתָלִים קְרוֹבִין זֶה לָזֶה עַד שֶׁיִּפּל צֵל שְׁנֵיהֶם לָאֶמְצַע כְּאֶחָד הֲרֵי זֶה מָקוֹם קָטָן. וְאִם הִבְרִיחַ הַצְּבִי וְכַיּוֹצֵא בּוֹ לְתוֹכוֹ חַיָּב. וּמָקוֹם שֶׁהוּא גָּדוֹל מִזֶּה הַמַּבְרִיחַ חַיָּה וָעוֹף לְתוֹכוֹ פָּטוּר:","אֶחָד שְׁמֹנָה שְׁרָצִים הָאֲמוּרִין בַּתּוֹרָה וְאֶחָד שְׁאָר שְׁקָצִים וּרְמָשִׂים שֶׁיֵּשׁ לְמִינָן צִידָה הַצָּד אֶחָד מִכֻּלָּן בֵּין לְצֹרֶךְ בֵּין שֶׁלֹּא לְצֹרֶךְ אוֹ לְשַׂחֵק בָּהֶן חַיָּב הוֹאִיל וְנִתְכַּוֵּן לָצוּד וְצָד. שֶׁמְּלָאכָה שֶׁאֵינָהּ צְרִיכָה לְגוּפָהּ חַיָּב עָלֶיהָ. הַצָּד אֶת הַיָּשֵׁן וְאֶת הַסּוּמָא חַיָּב:","הַמְשַׁלֵּחַ כְּלָבִים כְּדֵי שֶׁיָּצוּדוּ צְבָאִים וְאַרְנָבִים וְכַיּוֹצֵא בָּהֶן וּבָרַח הַצְּבִי מִפְּנֵי הַכֶּלֶב וְהָיָה הוּא רוֹדֵף אַחַר הַצְּבִי אוֹ שֶׁעָמַד בְּפָנָיו וְהִבְהִילוֹ עַד שֶׁהִגִּיעַ הַכֶּלֶב וּתְפָשׂוֹ הֲרֵי זֶה תּוֹלֶדֶת הַצָּד וְחַיָּב. וְכֵן הָעוֹשֶׂה כַּדֶּרֶךְ הַזּוֹ בְּעוֹפוֹת:","צְבִי שֶׁנִּכְנַס לְבַיִת וְנָעַל אֶחָד בְּפָנָיו חַיָּב. נְעָלוּהוּ שְׁנַיִם פְּטוּרִין. אִם אֵין אֶחָד יָכוֹל לִנְעל וּנְעָלוּהוּ שְׁנַיִם חַיָּבִין. יָשַׁב אֶחָד עַל הַפֶּתַח וְלֹא מִלְּאָהוּ וְיָשַׁב הַשֵּׁנִי וּמִלְּאָהוּ הַשֵּׁנִי חַיָּב. יָשַׁב הָרִאשׁוֹן וּמִלְּאָהוּ וּבָא הַשֵּׁנִי וְיָשַׁב בְּצִדּוֹ אַף עַל פִּי שֶׁעָמַד הָרִאשׁוֹן וְהָלַךְ לוֹ הָרִאשׁוֹן חַיָּב וְהַשֵּׁנִי לֹא עָשָׂה כְּלוּם וּמֻתָּר לוֹ לֵישֵׁב בִּמְקוֹמוֹ עַד הָעֶרֶב וְלוֹקֵחַ הַצְּבִי. לְמָה זֶה דּוֹמֶה לְנוֹעֵל בֵּיתוֹ לְשָׁמְרוֹ וְנִמְצָא צְבִי שָׁמוּר בְּתוֹכוֹ שֶׁלֹּא עָשָׂה כְּלוּם. נִכְנְסָה לוֹ צִפּוֹר תַּחַת כְּנָפָיו יוֹשֵׁב וּמְשַׁמְּרָהּ עַד שֶׁתֶּחְשַׁךְ וּמֻתָּר:","הַצָּד צְבִי זָקֵן אוֹ חִגֵּר אוֹ חוֹלֶה אוֹ קָטָן פָּטוּר. הַמְפָרֵק בְּהֵמָה חַיָּה וָעוֹף מִן הַמְּצוּדָה פָּטוּר. הַצָּד חַיָּה וָעוֹף שֶׁבִּרְשׁוּתוֹ כְּגוֹן אֲוָזִין וְתַרְנְגוֹלִין וְיוֹנֵי (עֲלִיָּה) פָּטוּר. הַצָּד דָּבָר שֶׁאֵין בְּמִינוֹ צִידָה כְּגוֹן חֲגָבִים הַגָּזִין צְרָעִין וְיַתּוּשִׁין וּפַרְעוֹשִׁין וְכַיּוֹצֵא בָּאֵלּוּ הֲרֵי זֶה פָּטוּר:","רְמָשִׂים הַמַּזִּיקִין כְּגוֹן נְחָשִׁים וְעַקְרַבִּים וְכַיּוֹצֵא בָּהֶן אַף עַל פִּי שֶׁאֵינָן מְמִיתִין הוֹאִיל וְנוֹשְׁכִין מֻתָּר לָצוּד אוֹתָם בְּשַׁבָּת. וְהוּא שֶׁיִּתְכַּוֵּן לְהִנָּצֵל מִנְּשִׁיכָתָן. כֵּיצַד הוּא עוֹשֶׂה. כּוֹפֶה כְּלִי עֲלֵיהֶן אוֹ מַקִּיף עֲלֵיהֶן אוֹ קוֹשְׁרָן כְּדֵי שֶׁלֹּא יַזִּיקוּ:"],"Mishneh Torah, Sabbath 21":["נֶּאֱמַר בַּתּוֹרָה (שמות כב יב) (שמות לד כא) \"תִּשְׁבֹּת\" אֲפִלּוּ מִדְּבָרִים שֶׁאֵינָן מְלָאכָה חַיָּב לִשְׁבֹּת מֵהֶן. וּדְבָרִים הַרְבֵּה הֵן שֶׁאָסְרוּ חֲכָמִים מִשּׁוּם שְׁבוּת. מֵהֶן דְּבָרִים אֲסוּרִים מִפְּנֵי שֶׁהֵן דּוֹמִים לִמְלָאכוֹת וּמֵהֶן דְּבָרִים אֲסוּרִים גְּזֵרָה שֶׁמָּא יָבוֹא מֵהֶן אִסּוּר סְקִילָה. וְאֵלּוּ הֵן:","כָּל הַמַּשְׁוֶה גֻּמּוֹת הֲרֵי זֶה חַיָּב מִשּׁוּם חוֹרֵשׁ. לְפִיכָךְ אָסוּר לְהִפָּנוֹת בִּשְׂדֵה הַנִּירָה בְּשַׁבָּת גְּזֵרָה שֶׁמָּא יַשְׁוֶה גֻּמּוֹת. הַמְפַנֶּה אֶת הָאוֹצָר בְּשַׁבָּת מִפְּנֵי שֶׁהוּא צָרִיךְ לוֹ לִדְבַר מִצְוָה כְּגוֹן שֶׁיַּכְנִיס בּוֹ אוֹרְחִים אוֹ יִקְבַּע בּוֹ מִדְרָשׁ לֹא יִגְמֹר אֶת כָּל הָאוֹצָר שֶׁמָּא יָבוֹא לְהַשְׁווֹת גֻּמּוֹת. טִיט שֶׁעַל גַּבֵּי רַגְלוֹ מְקַנְּחוֹ בַּכֹּתֶל אוֹ בְּקוֹרָה אֲבָל לֹא בַּקַּרְקַע שֶׁמָּא יָבֹא לְהַשְׁווֹת גֻּמּוֹת. לֹא יָרֹק בַּקַּרְקַע וְיָשׁוּף בְּרַגְלוֹ שֶׁמָּא יַשְׁוֶה גֻּמּוֹת. וּמֻתָּר לִדְרֹס הָרֹק שֶׁעַל גַּבֵּי קַרְקַע וְהוֹלֵךְ לְפִי תֻּמּוֹ:","נָשִׁים הַמְשַׂחֲקוֹת בֶּאֱגוֹזִים וּשְׁקֵדִים וְכַיּוֹצֵא בָּהֶן אֲסוּרוֹת לְשַׂחֵק בָּהֶן בְּשַׁבָּת שֶׁמָּא יָבֹאוּ לְהַשְׁווֹת גֻּמּוֹת. וְאָסוּר לְכַבֵּד אֶת הַקַּרְקַע שֶׁמָּא יַשְׁוֶה גֻּמּוֹת אֶלָּא אִם כֵּן הָיָה רָצוּף בַּאֲבָנִים. וּמֻתָּר לְזַלֵּף מַיִם עַל גַּבֵּי הַקַּרְקַע וְאֵינוֹ חוֹשֵׁשׁ שֶׁמָּא יַשְׁוֶה גֻּמּוֹת שֶׁהֲרֵי אֵינוֹ מִתְכַּוֵּן לְכָךְ. אֵין סָכִין אֶת הַקַּרְקַע וַאֲפִלּוּ הָיָה רָצוּף בַּאֲבָנִים וְאֵין נוֹפְחִין אוֹתוֹ וְאֵין מְדִיחִין אוֹתוֹ אֲפִלּוּ בְּיוֹם טוֹב כָּל שֶׁכֵּן בְּשַׁבָּת. שֶׁלֹּא יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל וְיָבֹא לְהַשְׁווֹת גֻּמּוֹת בִּזְמַן שֶׁהוּא עוֹשֶׂה כֵּן בְּמָקוֹם שֶׁאֵינוֹ רָצוּף:","חָצֵר שֶׁנִּתְקַלְקְלָה בְּמֵימֵי הַגְּשָׁמִים מֵבִיא תֶּבֶן וּמְרַדֶּה בָּהּ. וּכְשֶׁהוּא מְרַדֶּה לֹא יְרַדֶּה לֹא בְּסַל וְלֹא בְּקֻפָּה אֶלָּא בְּשׁוּלֵי הַקֻּפָּה שֶׁלֹּא יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל וְיָבֹא לְהַשְׁווֹת גֻּמּוֹת:","הַמַּשְׁקֶה אֶת הַזְּרָעִים חַיָּב מִשּׁוּם זוֹרֵעַ. לְפִיכָךְ אָסוּר לִשְׁאֹב מִן הַבּוֹר בְּגַלְגַּל גְּזֵרָה שֶׁמָּא יְמַלֵּא לְגִנָּתוֹ וּלְחֻרְבָּתוֹ. וּמִפְּנֵי זֶה אִם הָיָה הַבּוֹר שֶׁל גַּלְגַּל בֶּחָצֵר מֻתָּר לְמַלְּאוֹת מִמֶּנּוּ בַּגַּלְגַּל:","התּוֹלֵשׁ חַיָּב מִשּׁוּם קוֹצֵר. לְפִיכָךְ אָסוּר לִרְדּוֹת דְּבַשׁ מִכַּוֶּרֶת בְּשַׁבָּת מִפְּנֵי שֶׁהוּא כְּתוֹלֵשׁ. אֵין עוֹלִין בְּאִילָן בֵּין לַח בֵּין יָבֵשׁ וְאֵין נִתְלִין בְּאִילָן וְאֵין נִסְמָכִין בְּאִילָן. וְלֹא יַעֲלֶה מִבְּעוֹד יוֹם לֵישֵׁב שָׁם כָּל הַיּוֹם כֻּלּוֹ. וְאֵין מִשְׁתַּמְּשִׁין בִּמְחֻבָּר לַקַּרְקַע כְּלָל גְּזֵרָה שֶׁמָּא יִתְלֹשׁ:","פֵּרוֹת שֶׁנָּשְׁרוּ בְּשַׁבָּת אָסוּר לְאָכְלָן עַד מוֹצָאֵי שַׁבָּת גְּזֵרָה שֶׁמָּא יִתְלֹשׁ. הֲדַס הַמְחֻבָּר מֻתָּר לְהָרִיחַ בּוֹ שֶׁאֵין הֲנָיָתוֹ אֶלָּא לְהָרִיחַ בּוֹ וַהֲרֵי רֵיחוֹ מָצוּי. אֲבָל אֶתְרוֹג וְתַפּוּחַ וְכָל הָרָאוּי לַאֲכִילָה אָסוּר לְהָרִיחַ בּוֹ בִּמְחֻבָּר גְּזֵרָה שֶׁמָּא יָקֹץ אוֹתוֹ לְאָכְלוֹ:","אִילָן שֶׁהָיוּ שָׁרָשָׁיו גְּבוֹהִין מִן הָאָרֶץ שְׁלֹשָׁה טְפָחִים אָסוּר לֵישֵׁב עֲלֵיהֶן. וְאִם אֵינָן גְּבוֹהִין שְׁלֹשָׁה הֲרֵי הֵן כָּאָרֶץ. הָיוּ בָּאִין מִלְּמַעְלָה מִשְּׁלֹשָׁה לְתוֹךְ שְׁלֹשָׁה מֻתָּר לְהִשְׁתַּמֵּשׁ בָּהֶן. הָיוּ גְּבוֹהִין שְׁלֹשָׁה אַף עַל פִּי שֶׁצִּדָּן אֶחָד שָׁוֶה לָאָרֶץ אוֹ שֶׁיֵּשׁ חָלָל תַּחְתֵּיהֶן שְׁלֹשָׁה אָסוּר לֵישֵׁב עֲלֵיהֶן:","אֵין רוֹכְבִין עַל גַּבֵּי בְּהֵמָה בְּשַׁבָּת גְּזֵרָה שֶׁמָּא יַחְתֹּךְ זְמוֹרָה לְהַנְהִיגָהּ. וְאֵין נִתְלִין בִּבְהֵמָה וְלֹא יַעֲלֶה מִבְּעוֹד יוֹם לֵישֵׁב עָלֶיהָ בְּשַׁבָּת. וְאֵין נִסְמָכִין לְצִדֵּי בְּהֵמָה. וְצִדֵּי צְדָדִין מֻתָּרִין. עָלָה בָּאִילָן בְּשַׁבָּת בְּשׁוֹגֵג מֻתָּר לֵירֵד. בְּמֵזִיד אָסוּר לֵירֵד. וּבִבְהֵמָה אֲפִלּוּ בְּמֵזִיד יֵרֵד מִשּׁוּם צַעַר בַּעֲלֵי חַיִּים. וְכֵן פּוֹרְקִין הַמַּשּׂאוֹי מֵעַל הַבְּהֵמָה בְּשַׁבָּת מִשּׁוּם צַעַר בַּעֲלֵי חַיִּים:","כֵּיצַד. הָיְתָה בְּהֶמְתּוֹ טְעוּנָה שָׁלִיף שֶׁל תְּבוּאָה מַכְנִיס רֹאשׁוֹ תַּחְתָּיו וּמְסַלְּקוֹ לְצַד אַחֵר וְהוּא נוֹפֵל מֵאֵלָיו. הָיָה בָּא מִן הַדֶּרֶךְ בְּלֵיל שַׁבָּת וּבְהֶמְתּוֹ טְעוּנָה. כְּשֶׁיַּגִּיעַ לֶחָצֵר הַחִיצוֹנָה נוֹטֵל אֶת הַכֵּלִים הַנִּטָּלִין בְּשַׁבָּת וְשֶׁאֵינָן נִטָּלִין מַתִּיר הַחֲבָלִים וְהַשַּׂקִּין נוֹפְלִין. הָיוּ בַּשַּׂקִּין דְּבָרִים הַמִּשְׁתַּבְּרִין. אִם הָיוּ שַׂקִּין קְטַנִּים מֵבִיא כָּרִים וּכְסָתוֹת וּמַנִּיחַ תַּחְתֵּיהֶן וְהַשַּׂקִּין נוֹפְלִין עַל הַכָּרִים. שֶׁהֲרֵי אִם יִרְצֶה לִשְׁלֹף הַכַּר שׁוֹלֵף מִפְּנֵי שֶׁהַשַּׂקִּים קְטַנִּים וְקַלִּים וְנִמְצָא שֶׁלֹּא בָּטֵל הַכְּלִי מֵהֵיכָנוֹ. הָיְתָה טְעוּנָה עֲשָׁשִׁיּוֹת שֶׁל זְכוּכִית מַתִּיר הַשַּׂקִּים וְהֵן נוֹפְלִין שֶׁאַף עַל פִּי שֶׁיִּשָּׁבְרוּ אֵין בְּכָךְ הֶפְסֵד גָּדוֹל שֶׁהֲרֵי הַכּל לְהַתָּכָה עוֹמֵד וּלְהֶפְסֵד מֻעָט לֹא חָשְׁשׁוּ. הָיוּ הַשַּׂקִּים גְּדוֹלִים וּמְלֵאִים כְּלֵי זְכוּכִית וְכַיּוֹצֵא בָּהֶם פּוֹרֵק בְּנַחַת. וּמִכָּל מָקוֹם לֹא יַנִּיחָן שָׁם עַל גַּבֵּי בְּהֵמָה מִשּׁוּם צַעַר בַּעֲלֵי חַיִּים:","הַמְדַבֵּק פֵּרוֹת עַד שֶׁיֵּעָשׂוּ גּוּף אֶחָד חַיָּב מִשּׁוּם מְעַמֵּר. לְפִיכָךְ מִי שֶׁנִּתְפַּזְּרוּ לוֹ פֵּרוֹת בַּחֲצֵרוֹ מְלַקֵּט עַל יָד עַל יָד וְאוֹכֵל. אֲבָל לֹא יִתֵּן לֹא לְתוֹךְ הַסַּל וְלֹא לְתוֹךְ הַקֻּפָּה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל. שֶׁאִם יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל שֶׁמָּא יִכְבְּשֵׁם בְּיָדוֹ בְּתוֹךְ הַקֻּפָּה וְיָבֹא לִידֵי עִמּוּר. וְכֵן אֵין מְקַבְּצִין אֶת הַמֶּלַח וְכַיּוֹצֵא בּוֹ מִפְּנֵי שֶׁנִּרְאֶה כִּמְעַמֵּר:","מְפָרֵק חַיָּב מִשּׁוּם דָּשׁ. וְהַסּוֹחֵט זֵיתִים וַעֲנָבִים חַיָּב מִשּׁוּם מְפָרֵק. לְפִיכָךְ אָסוּר לִסְחֹט תּוּתִים וְרִמּוֹנִים הוֹאִיל וּמִקְצָת בְּנֵי אָדָם סוֹחֲטִים אוֹתָם כְּזֵיתִים וַעֲנָבִים שֶׁמָּא יָבוֹא לִסְחֹט זֵיתִים וַעֲנָבִים. אֲבָל שְׁאָר פֵּרוֹת כְּגוֹן פְּרִישִׁין וְתַפּוּחִים וְעוּזְרָדִין מֻתָּר לְסָחֳטָן בְּשַׁבָּת מִפְּנֵי שֶׁאֵינָן בְּנֵי סְחִיטָה:","כְּבָשִׁין וּשְׁלָקוֹת שֶׁסְּחָטָן. אִם לְרַכֵּךְ גּוּפָן מֻתָּר וְאִם לְהוֹצִיא מֵימֵיהֶן אָסוּר. וְאֵין מְרַסְּקִין אֶת הַשֶּׁלֶג שֶׁיָּזוּבוּ מֵימָיו. אֲבָל מְרַסֵּק הוּא לְתוֹךְ הַקְּעָרָה אוֹ לְתוֹךְ הַכּוֹס. הַשּׁוּם וְהַבֹּסֶר וְהַמְּלִילוֹת שֶׁרִסְּקָן מִבְּעוֹד יוֹם. אִם מְחֻסָּרִין דִּיכָה אָסוּר לוֹ לִגְמֹר דִּיכָתָן בְּשַׁבָּת. וְאִם מְחֻסָּרִין שְׁחִיקָה בַּיָּד מֻתָּר לוֹ לִגְמֹר שְׁחִיקָתָן בְּשַׁבָּת. לְפִיכָךְ מֻתָּר לִגְמֹר שְׁחִיקַת הָרִיפוֹת בָּעֵץ הַפָּרוּר בְּתוֹךְ הַקְּדֵרָה בְּשַׁבָּת אַחַר שֶׁמּוֹרִידִין אוֹתָהּ מֵעַל הָאֵשׁ:","הַמּוֹלֵל מְלִילוֹת מוֹלֵל בְּשִׁנּוּי כְּדֵי שֶׁלֹּא יֵרָאֶה כְּדָשׁ. הַיּוֹנֵק בְּפִיו פָּטוּר. וְאִם הָיָה גּוֹנֵחַ מֻתָּר לוֹ לִינֹק בְּפִיו מִפְּנֵי שֶׁהוּא מְפָרֵק כִּלְאַחַר יָד וּמִשּׁוּם צַעֲרוֹ לֹא גָּזְרוּ וְאַף עַל פִּי שֶׁאֵין שָׁם סַכָּנָה:","פֵּרוֹת שֶׁזָּבוּ מֵהֶן מַשְׁקִין בְּשַׁבָּת. אִם זֵיתִים וַעֲנָבִים הֵן אָסוּר לִשְׁתּוֹת אוֹתָן הַמַּשְׁקִין עַד מוֹצָאֵי שַׁבָּת גְּזֵרָה שֶׁמָּא יִתְכַּוֵּן וְיִסְחֹט אוֹתָן בְּשַׁבָּת. וְאִם תּוּתִים וְרִמּוֹנִים הֵן. אִם הִכְנִיסָן לַאֲכִילָה מַשְׁקִין שֶׁזָּבוּ מֵהֶן מֻתָּרִין. וְאִם הִכְנִיסָן לְדָרְכָן מַשְׁקִין שֶׁזָּבוּ מֵהֶן אֲסוּרִין עַד מוֹצָאֵי שַׁבָּת:","זֵיתִים וַעֲנָבִים שֶׁרִסְּקָן מֵעֶרֶב שַׁבָּת וְיָצְאוּ מֵהֶן מַשְׁקִין מֵעַצְמָן מֻתָּרִין. וְכֵן חַלּוֹת דְּבַשׁ שֶׁרִסְּקָן מֵעֶרֶב שַׁבָּת מַשְׁקִין הַיּוֹצְאִין מֵהֶן בְּשַׁבָּת מֻתָּרִין. שֶׁאֵין כָּאן מָקוֹם לִגְזֵרָה שֶׁכְּבָר רִסְּקָן מִבָּעֶרֶב:","זוֹרֶה וּבוֹרֵר מֵאֲבוֹת מְלָאכוֹת הֵן לְפִיכָךְ אַף עַל פִּי שֶׁמֻּתָּר לִמְלל מְלִילוֹת בְּרָאשֵׁי אֶצְבְּעוֹתָיו. כְּשֶׁהוּא מְנַפֵּחַ מְנַפֵּחַ בְּיָדוֹ אַחַת בְּכָל כֹּחוֹ. אֲבָל לֹא בְּקָנוֹן וְלֹא בְּתַמְחוּי גְּזֵרָה שֶׁמָּא יְנַפֶּה בְּנָפָה וּבִכְבָרָה שֶׁהוּא חַיָּב. והַמְשַׁמֵּר שְׁמָרִים תּוֹלֶדֶת בּוֹרֵר אוֹ מְרַקֵּד הוּא. לְפִיכָךְ אַף עַל פִּי שֶׁמֻּתָּר לְסַנֵּן יַיִן צָלוּל אוֹ מַיִם צְלוּלִין בְּסוּדָרִין אוֹ בִּכְפִיפָה מִצְרִית. לֹא יַעֲשֶׂה גּוּמָא בַּסּוּדָר שֶׁלֹּא יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל וְיָבֹא לְשַׁמֵּר בִּמְשַׁמֶּרֶת. וְכֵן אָסוּר לִתְלוֹת אֶת הַמְשַׁמֶּרֶת כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל שֶׁמָּא יָבֹא לְשַׁמֵּר. וְכֵן הַמְחַבֵּץ תּוֹלֶדֶת בּוֹרֵר הוּא. לְפִיכָךְ אַף עַל פִּי שֶׁנּוֹתְנִין שֻׁמְשְׁמִין וֶאֱגוֹזִים לִדְבַשׁ לֹא יַחְבְּצֵם בְּיָדוֹ:","הַמְחַתֵּךְ אֶת הָיָּרָק דַּק דַּק כְּדֵי לְבַשְּׁלוֹ הֲרֵי זֶה תּוֹלֶדֶת טוֹחֵן וְחַיָּב. לְפִיכָךְ אֵין מְרַסְּקִין לֹא אֶת הַשַּׁחַת וְלֹא אֶת הַחֲרוּבִין לִפְנֵי בְּהֵמָה בֵּין דַּקָּה בֵּין גַּסָּה מִפְּנֵי שֶׁנִּרְאֶה כְּטוֹחֵן. אֲבָל מְחַתְּכִין אֶת הַדְּלוּעִין לִפְנֵי הַבְּהֵמָה וְאֶת הַנְּבֵלָה לִפְנֵי הַכְּלָבִים שֶׁאֵין טְחִינָה בְּפֵרוֹת. וּמַתִּירִין אֲלֻמּוֹת שֶׁל עָמִיר לִפְנֵי בְּהֵמָה וּמְפַסְפֵס בְּיָדוֹ אֲלֻמּוֹת קְטַנּוֹת אֲבָל לֹא אֲלֻמּוֹת גְּדוֹלוֹת מִפְּנֵי הַטֹּרַח שֶׁבָּהֶן:","חֲבִילֵי פֵּאָה וְאֵזוֹב וְקוֹרָנִית וְכַיּוֹצֵא בָּהֶן שֶׁהִכְנִיסָן לְמַאֲכַל בְּהֵמָה מִסְתַּפֵּק מֵהֶן וְקוֹטֵם וְאוֹכֵל בְּרָאשֵׁי אֶצְבְּעוֹתָיו אֲבָל לֹא בְּיָדוֹ הַרְבֵּה שֶׁלֹּא יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל וְיָבֹא לָדוּק:","הַצָּרִיךְ לָדוּק פִּלְפְּלִים וְכַיּוֹצֵא בָּהֶן לִתֵּן לְתוֹךְ הַמַּאֲכָל בְּשַׁבָּת הֲרֵי זֶה כּוֹתֵשׁ בְּיַד הַסַּכִּין וּבַקְּעָרָה אֲבָל לֹא בְּמַכְתֶּשֶׁת מִפְּנֵי שֶׁהוּא טוֹחֵן. לְפִיכָךְ אָסוּר לַבָּרִיא לְהִתְרַפְּאוֹת בְּשַׁבָּת גְּזֵרָה שֶׁמָּא יִשְׁחֹק הַסַּמְמָנִין:","כֵּיצַד. לֹא יֹאכַל דְּבָרִים שֶׁאֵינָן מַאֲכַל בְּרִיאִים כְּגוֹן אֱזוֹבְיוֹן וּפֵיאָה. וְלֹא דְּבָרִים הַמְשַׁלְשְׁלִים כְּגוֹן לַעֲנָה וְכַיּוֹצֵא בָּהֶם. וְכֵן לֹא יִשְׁתֶּה דְּבָרִים שֶׁאֵין דֶּרֶךְ הַבְּרִיאִים לִשְׁתּוֹתָן כְּגוֹן מַיִם שֶׁבִּשְּׁלוּ בָּהֶן סַמְמָנִין וַעֲשָׂבִים:","אוֹכֵל אָדָם אֳכָלִין וּמַשְׁקִין שֶׁדֶּרֶךְ הַבְּרִיאִים לְאָכְלָן וְלִשְׁתּוֹתָן כְּגוֹן הַכֻּסְבָּרָא וְהַכְּשׁוּת וְהָאֵזוֹב אַף עַל פִּי שֶׁהֵן מְרַפְּאִין וְאוֹכְלָן כְּדֵי לְהִתְרַפְּאוֹת בָּהֶם מֻתָּר הוֹאִיל וְהֵם מַאֲכַל בְּרִיאִים. שָׁתָה חִלְתִּית מִקֹּדֶם הַשַּׁבָּת וַהֲרֵי הוּא שׁוֹתֶה וְהוֹלֵךְ מֻתָּר לִשְׁתּוֹתוֹ בְּשַׁבָּת [אֲפִלּוּ] בִּמְקוֹמוֹת [שֶׁלֹּא] נָהֲגוּ הַבְּרִיאִים לִשְׁתּוֹת הַחִלְתִּית. וְשׁוֹתִין זֵיתוֹם הַמִּצְרִי בְּכָל מָקוֹם:","וְכֵן שְׁמָנִים שֶׁדֶּרֶךְ הַבְּרִיאִים לָסוּךְ בָּהֶן מֻתָּר לָסוּךְ בָּהֶן בְּשַׁבָּת וְאַף עַל פִּי שֶׁנִּתְכַּוֵּן לִרְפוּאָה. וְשֶׁאֵין הַבְּרִיאִים סָכִין בָּהֶן אֲסוּרִין. הַחוֹשֵׁשׁ בְּמָתְנָיו לֹא יָסוּךְ יַיִן וְחֹמֶץ אֲבָל סָךְ הוּא אֶת הַשֶּׁמֶן. וְלֹא שֶׁמֶן וֶרֶד אֶלָּא בְּמָקוֹם שֶׁהַבְּרִיאִים סָכִין אוֹתוֹ. וּמֻתָּר לָסוּךְ שֶׁמֶן וּמֶלַח בְּכָל מָקוֹם. נִגְּפָה יָדוֹ אוֹ רַגְלוֹ צוֹמְתָהּ בְּיַיִן וְאֵינוֹ צוֹמְתָהּ בְּחֹמֶץ. וְאִם הָיָה עָנֹג אַף בְּיַיִן אָסוּר:","הַחוֹשֵׁשׁ בְּשִׁנָּיו לֹא יִגְמַע בָּהֶן אֶת הַחֹמֶץ וְיִפְלֹט אֲבָל מְגַמֵּעַ הוּא וּבוֹלֵעַ. הַחוֹשֵׁשׁ בִּגְרוֹנוֹ לֹא יְעַרְעֶנּוּ בְּשֶׁמֶן אֲבָל בּוֹלֵעַ הוּא שֶׁמֶן הַרְבֵּה וְאִם נִתְרַפֵּא נִתְרַפֵּא. אֵין לוֹעֲסִין אֶת הַמַּסְטְכִי וְאֵין שָׁפִין אֶת הַשִּׁנַּיִם בְּסַם בְּשַׁבָּת בִּזְמַן שֶׁנִּתְכַּוֵּן לִרְפוּאָה. וְאִם נִתְכַּוֵּן לְרֵיחַ הַפֶּה מֻתָּר:","אֵין נוֹתְנִין יַיִן לְתוֹךְ הָעַיִן אֲבָל נוֹתֵן הוּא עַל גַּב הָעַיִן. וְרֹק תָּפֵל אֲפִלּוּ עַל גַּב הָעַיִן אָסוּר. קִילוֹר שֶׁשָּׁרָה אוֹתוֹ מֵעֶרֶב שַׁבָּת מַעֲבִירוֹ עַל גַּב עֵינוֹ בְּשַׁבָּת וְאֵינוֹ חוֹשֵׁשׁ. מִי שֶׁלָּקָה בְּאֶצְבָּעוֹ לֹא יִכְרֹךְ עָלָיו גֶּמִי כְּדֵי לְרַפְּאוֹתוֹ וְלֹא יִדְחָקֶנּוּ בְּיָדוֹ כְּדֵי לְהוֹצִיא מִמֶּנּוּ דָּם:","אֵין נוֹתְנִין חַמִּין וְשֶׁמֶן עַל גַּבֵּי הַמַּכָּה. וְלֹא עַל גַּבֵּי מוֹךְ שֶׁעַל גַּבֵּי הַמַּכָּה. וְלֹא עַל גַּבֵּי מוֹךְ לִתְּנוֹ עַל הַמַּכָּה בְּשַׁבָּת. אֲבָל נוֹתֵן הוּא חוּץ לַמַּכָּה וְשׁוֹתֵת וְיוֹרֵד לַמַּכָּה. וְנוֹתְנִין מוֹךְ יָבֵשׁ עַל גַּבֵּי הַמַּכָּה. וְאִם הָיָה עַתִּיק אָסוּר מִפְּנֵי שֶׁהוּא כִּרְטִיָּה:","רְטִיָּה שֶׁפָּרְשָׁה עַל גַּבֵּי כְּלִי מַחְזִירִין אוֹתָהּ. וְאִם פָּרְשָׁה עַל גַּבֵּי קַרְקַע אָסוּר לְהַחֲזִירָהּ. וּמַנִּיחִין רְטִיָּה עַל גַּבֵּי הַמַּכָּה לְכַתְּחִלָּה בַּמִּקְדָּשׁ שֶׁאֵין אִסּוּר שְׁבוּת בַּמִּקְדָּשׁ. וּבְכָל מָקוֹם מְקַנְּחִין פִּי הַמַּכָּה וְאֵין מְקַנְּחִין אֶת הָרְטִיָּה שֶׁמָּא יְמָרֵחַ:","סָכִין וּמְמַשְׁמְשִׁין בִּבְנֵי מֵעַיִם בְּשַׁבָּת וְהוּא שֶׁיָּסוּךְ וִימַשְׁמֵשׁ בְּבַת אַחַת כְּדֵי שֶׁלֹּא יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל. וְאֵין מִתְעַמְּלִין בְּשַׁבָּת. אֵי זֶה הוּא מִתְעַמֵּל זֶה שֶׁדּוֹרְסִים עַל גּוּפוֹ בְּכֹחַ עַד שֶׁיִּיגַע וְיַזִּיעַ אוֹ שֶׁיְּהַלֵּךְ עַד שֶׁיִּיגַע וְיַזִּיעַ. שֶׁאָסוּר לְיַגֵּעַ אֶת עַצְמוֹ כְּדֵי שֶׁיַּזִּיעַ בְּשַׁבָּת מִפְּנֵי שֶׁהִיא רְפוּאָה. וְכֵן אָסוּר לַעֲמֹד בְּקַרְקַע דִּימוֹסִית שֶׁבְּאֶרֶץ יִשְׂרָאֵל מִפְּנֵי שֶׁמְּעַמֶּלֶת וּמְרַפֵּאת:","אֵין רוֹחֲצִין בְּמַיִם שֶׁמְּשַׁלְשְׁלִין וְלֹא בְּטִיט שֶׁטּוֹבְעִין בּוֹ וְלֹא בְּמֵי מִשְׁרָה הַבְּאוּשִׁים וְלֹא בְּיָם סְדוֹם וְלֹא בַּמַּיִם הָרָעִים שֶׁבַּיָּם הַגָּדוֹל מִפְּנֵי שֶׁכָּל אֵלּוּ צַעַר הֵן וְכָתוּב (ישעיה נח יג) \"וְקָרָאתָ לַשַּׁבָּת עֹנֶג\". לְפִיכָךְ אִם לֹא נִשְׁתַּהָה בָּהֶם אֶלָּא עָלָה מִיָּד אַף עַל פִּי שֶׁיֵּשׁ לוֹ חֲטָטִין בְּרֹאשׁוֹ מֻתָּר:","אֵין מִתְגָּרְדִּין בְּמִגְרֶדֶת וְאִם הָיוּ יָדָיו מְלֻכְלָכוֹת בְּצוֹאָה אוֹ בְּטִיט גּוֹרֵד כְּדַרְכּוֹ וְאֵינוֹ חוֹשֵׁשׁ. סָכִין וּמְפָרְכִין לְאָדָם לְעַנֵּג אֲבָל לֹא לִבְהֵמָה. וְאִם הָיָה לָהּ צַעַר מֻתָּר לְהָסִיר צַעֲרָהּ בְּסִיכָה וּפֵרוּךְ. בְּהֵמָה שֶׁאָכְלָה כַּרְשִׁינִין הַרְבֵּה מְרִיצִין אוֹתָהּ בֶּחָצֵר בִּשְׁבִיל שֶׁתִּתְרַפֵּא. וְאִם אָחֲזָהּ דָּם מַעֲמִידִין אוֹתָהּ בְּמַיִם בִּשְׁבִיל שֶׁתִּצְטַנֵּן וְאֵין חוֹשְׁשִׁין שֶׁמָּא יִשְׁחַק לָהּ סַמָּנִין:","אֵין מְקִיאִין אֶת הָאֹכֶל בְּשַׁבָּת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּסַם שֶׁמָּא יִשְׁחַק סַמָּנִין אֲבָל לְהַכְנִיס יָדוֹ לְתוֹךְ פִּיו וּלְהָקִיא מֻתָּר. וְאָסוּר לִדְחֹק כְּרֵסוֹ שֶׁל תִּינוֹק כְּדֵי לְהוֹצִיא הָרְעִי שֶׁלּוֹ שֶׁמָּא יָבֹא לְהַשְׁקוֹתוֹ סַמָּנִין הַמְשַׁלְשְׁלִין. וּמֻתָּר לִכְפּוֹת כּוֹס עַל הַטַּבּוּר בְּשַׁבָּת כְּדֵי לְהַעֲלוֹתוֹ. וְכֵן מֻתָּר לֵיחֲנֵק וּלְלַפֵּף אֶת הַקָּטָן וּלְהַעֲלוֹת אָזְנַיִם בֵּין בְּיָד בֵּין בִּכְלִי. וּלְהַעֲלוֹת אֻנְקְּלִי. שֶׁכָּל אֵלּוּ וְכַיּוֹצֵא בָּהֶן אֵין עוֹשִׂין אוֹתָן בְּסַמָּנִין כְּדֵי לָחוּשׁ לִשְׁחִיקָה וְיֵשׁ לוֹ צַעַר מֵהֶן:","הַמְרַקֵּד מֵאֲבוֹת מְלָאכוֹת. לְפִיכָךְ אֵין כּוֹבְרִין אֶת הַתֶּבֶן בִּכְבָרָה וְלֹא יַנִּיחַ הַכְּבָרָה שֶׁיֵּשׁ בָּהּ תֶּבֶן בְּמָקוֹם גָּבוֹהַּ בִּשְׁבִיל שֶׁיֵּרֵד הַמֹּץ מִפְּנֵי שֶׁהוּא כִּמְרַקֵּד. אֲבָל נוֹטֵל הַתֶּבֶן בַּכְּבָרָה וּמוֹלִיךְ לָאֵבוּס אַף עַל פִּי שֶׁיֵּרֵד הַמֹּץ בִּשְׁעַת הוֹלָכָה שֶׁהֲרֵי אֵינוֹ מִתְכַּוֵּן לְכָךְ:","מְגַבֵּל חַיָּב מִשּׁוּם לָשׁ. לְפִיכָךְ אֵין מְגַבְּלִין קֶמַח קָלִי הַרְבֵּה שֶׁמָּא יָבוֹא לָלוּשׁ קֶמַח שֶׁאֵינוֹ קָלִי. וּמֻתָּר לְגַבֵּל אֶת הַקָּלִי מְעַט מְעַט. אֲבָל תְּבוּאָה שֶׁלֹּא הֵבִיאָה שְׁלִישׁ שֶׁקָּלוּ אוֹתָהּ וְאַחַר כָּךְ טָחֲנוּ אוֹתָהּ טְחִינָה גַּסָּה שֶׁהֲרֵי הוּא כְּחוֹל וְהִיא הַנִּקְרֵאת שָׁתִית מֻתָּר לְגַבֵּל מִמֶּנָּה בְּחֹמֶץ וְכַיּוֹצֵא בּוֹ הַרְבֵּה בְּבַת אַחַת. וְהוּא שֶׁיִּהְיֶה רַךְ אֲבָל קָשֶׁה אָסוּר מִפְּנֵי שֶׁנִּרְאֶה כְּלָשׁ וְצָרִיךְ לְשַׁנּוֹת. כֵּיצַד. נוֹתֵן אֶת הַשָּׁתִית וְאַחַר כָּךְ נוֹתֵן אֶת הַחֹמֶץ:","הַמֻּרְסָן אַף עַל פִּי שֶׁאֵינוֹ רָאוּי לְגִבּוּל אֵין גּוֹבְלִין אוֹתוֹ שֶׁמָּא יָבוֹא לְגַבֵּל הֶעָפָר וְכַיּוֹצֵא בּוֹ. וְנוֹתְנִין מַיִם עַל גַּבֵּי מֻרְסָן וּמוֹלִיךְ בּוֹ הַתַּרְוָד שְׁתִי וָעֵרֶב. אֲבָל אֵינוֹ מְמָרֵס בְּיָדוֹ שֶׁלֹּא יֵרָאֶה כְּלָשׁ. אִם לֹא נִתְעָרֵב מְנַעֲרוֹ מִכְּלִי לִכְלִי עַד שֶׁיִּתְעָרֵב וְנוֹתֵן לִפְנֵי הַתַּרְנְגוֹלִין אוֹ לִפְנֵי הַשְּׁוָרִים. וּמֻתָּר לְעָרֵב הַמֻּרְסָן עַל דֶּרֶךְ זוֹ בִּכְלִי אֶחָד וּמְחַלֵּק אוֹתוֹ בְּכֵלִים הַרְבֵּה וְנוֹתֵן לִפְנֵי כָּל בְּהֵמָה וּבְהֵמָה וּמְעָרֵב בִּכְלִי אֶחָד אֲפִלּוּ כּוֹר וַאֲפִלּוּ כּוֹרָיִים:","אֵין מַאֲכִילִין בְּהֵמָה חַיָּה וְעוֹף בְּשַׁבָּת כְּדֶרֶךְ שֶׁהוּא מַאֲכִיל בְּחל שֶׁמָּא יָבוֹא לִידֵי כְּתִישַׁת קִטְנִיּוֹת אוֹ לִידֵי לִישַׁת קֶמַח וְכַיּוֹצֵא בּוֹ. כֵּיצַד. לֹא יַאֲכִיל הַגָּמָל בְּשַׁבָּת מַאֲכַל שְׁלֹשָׁה אוֹ אַרְבָּעָה יָמִים וְלֹא יַרְבִּיץ עֵגֶל וְכַיּוֹצֵא בּוֹ וְיִפְתַּח פִּיו וְיִתֵּן לְתוֹכוֹ כַּרְשִׁינִין וּמַיִם בְּבַת אַחַת. וְכֵן לֹא יִתֵּן לְתוֹךְ פִּי יוֹנִים וְתַרְנְגוֹלִים לְמָקוֹם שֶׁאֵינָן יְכוֹלִין לְהַחֲזִיר. אֲבָל מַאֲכִיל הוּא אֶת הַבְּהֵמָה מְעֵמָּד וּמַשְׁקֶה אוֹתָהּ מְעֻמָּד אוֹ נוֹתֵן לְתוֹךְ פִּיהָ מַיִם בִּפְנֵי עַצְמָן וְכַרְשִׁינִין בִּפְנֵי עַצְמָן בְּמָקוֹם שֶׁיְּכוֹלָה לְהַחֲזִיר. וְכֵן מַאֲכִיל הָעוֹף בְּיָדוֹ בְּמָקוֹם שֶׁיָּכוֹל לְהַחֲזִיר וְאֵין צָרִיךְ לוֹמַר שֶׁיִּתֵּן לִפְנֵיהֶן וְהֵן אוֹכְלִין:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּמִי שֶׁמְּזוֹנוֹתָיו עָלָיו כְּגוֹן בְּהֶמְתּוֹ וְחַיָּתוֹ וְיוֹנֵי הַבַּיִת וַאֲוָזִין וְתַרְנְגוֹלִין. אֲבָל מִי שֶׁאֵין מְזוֹנוֹתָיו עָלָיו כְּגוֹן חֲזִיר וְיוֹנֵי שׁוֹבָךְ וּדְבוֹרִים לֹא יִתֵּן לִפְנֵיהֶם לֹא מָזוֹן וְלֹא מַיִם. וּמֻתָּר לְאָדָם לְהַעֲמִיד בְּהֶמְתּוֹ עַל גַּבֵּי עֲשָׂבִים [מְחֻבָּרִים] וְהִיא אוֹכֶלֶת. אֲבָל לֹא יַעֲמִיד אוֹתָהּ עַל גַּבֵּי דָּבָר שֶׁהֻקְצָה אֲבָל עוֹמֵד בְּפָנֶיהָ כְּדֵי שֶׁתַּחֲזִיר פָּנֶיהָ לַדָּבָר הַמֻּקְצֶה וְתֹאכַל מִמֶּנּוּ. וְכֵן בְּיוֹם טוֹב:"],"Mishneh Torah, Sabbath 5":["הַדְלָ [קַ] ת נֵר בְּשַׁבָּת אֵינָהּ רְשׁוּת אִם רָצָה מַדְלִיק וְאִם רָצָה אֵינוֹ מַדְלִיק. וְלֹא מִצְוָה שֶׁאֵינוֹ חַיָּב לִרְדֹּף אַחֲרֶיהָ עַד שֶׁיַּעֲשֶׂנָה כְּגוֹן עֵרוּבֵי חֲצֵרוֹת אוֹ נְטִילַת יָדַיִם לַאֲכִילָה אֶלָּא זֶה חוֹבָה. וְאֶחָד אֲנָשִׁים וְאֶחָד נָשִׁים חַיָּבִין לִהְיוֹת בְּבָתֵּיהֶן נֵר דָּלוּק בְּשַׁבָּת. אֲפִלּוּ אֵין לוֹ מַה יֹּאכַל שׁוֹאֵל עַל הַפְּתָחִים וְלוֹקֵחַ שֶׁמֶן וּמַדְלִיק אֶת הַנֵּר שֶׁזֶּה בִּכְלַל עֹנֶג שַׁבָּת. וְחַיָּב לְבָרֵךְ קֹדֶם הַדְלָקָה בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהַדְלִיק נֵר שֶׁל שַׁבָּת. כְּדֶרֶךְ שֶׁמְּבָרֵךְ עַל כָּל הַדְּבָרִים שֶׁהוּא חַיָּב בָּהֶם מִדִּבְרֵי סוֹפְרִים:","מֻתָּר לְהִשְׁתַּמֵּשׁ בְּנֵר שֶׁל שַׁבָּת. וְהוּא שֶׁלֹּא יְהֵא הַדָּבָר צָרִיךְ עִיּוּן הַרְבֵּה. אֲבָל דָּבָר שֶׁצָּרִיךְ לְדַקְדֵּק בִּרְאִיָּתוֹ אָסוּר לְהַבְחִינוֹ לְאוֹר הַנֵּר גְּזֵרָה שֶׁמָּא יַטֶּה:","הַמַּדְלִיק צָרִיךְ לְהַדְלִיק מִבְּעוֹד יוֹם קֹדֶם שְׁקִיעַת הַחַמָּה. וְנָשִׁים מְצֻוּוֹת עַל דָּבָר זֶה יוֹתֵר מִן הָאֲנָשִׁים לְפִי שֶׁהֵן מְצוּיוֹת בַּבָּתִּים וְהֵן הָעֲסוּקוֹת בִּמְלֶאכֶת הַבַּיִת. וְאַף עַל פִּי כֵן צָרִיךְ הָאִישׁ לְהַזְהִירָן וְלִבְדֹּק אוֹתָן עַל כָּךְ וְלוֹמַר לָהֶן וּלְאַנְשֵׁי בֵּיתוֹ עֶרֶב שַׁבָּת קֹדֶם שֶׁתֶּחְשַׁךְ הַדְלִיקוּ אֶת הַנֵּר. סְפֵק חֲשֵׁכָה וְנִכְנַס הַשַּׁבָּת סָפֵק לֹא נִכְנַס אֵין מַדְלִיקִין:","מִשֶּׁתִּשְׁקַע הַחַמָּה עַד שֶׁיֵּרָאוּ שְׁלֹשָׁה כּוֹכָבִים בֵּינוֹנִים הוּא הַזְּמַן הַנִּקְרָא בֵּין הַשְּׁמָשׁוֹת בְּכָל מָקוֹם. וְהוּא סָפֵק מִן הַיּוֹם סָפֵק מִן הַלַּיְלָה וְדָנִין בּוֹ לְהַחֲמִיר בְּכָל מָקוֹם. וּלְפִיכָךְ אֵין מַדְלִיקִין בּוֹ. וְהָעוֹשֶׂה מְלָאכָה בֵּין הַשְּׁמָשׁוֹת בְּעֶרֶב שַׁבָּת וּבְמוֹצָאֵי שַׁבָּת בְּשׁוֹגֵג חַיָּב חַטָּאת מִכָּל מָקוֹם. וְכוֹכָבִים אֵלּוּ לֹא גְּדוֹלִים הַנִּרְאִים בַּיּוֹם וְלֹא קְטַנִּים שֶׁאֵין נִרְאִין אֶלָּא בַּלַּיְלָה אֶלָּא בֵּינוֹנִים. וּמִשֶׁיֵּרָאוּ שְׁלֹשָׁה כּוֹכָבִים אֵלּוּ הַבֵּינוֹנִים הֲרֵי זֶה לַיְלָה וַדַּאי:","פְּתִילָה שֶׁמַּדְלִיקִין בָּהּ לְשַׁבָּת אֵין עוֹשִׂין אוֹתָהּ מִדָּבָר שֶׁהָאוּר מְסַכְסֶכֶת בּוֹ כְּגוֹן צֶמֶר וְשֵׂעָר וּמֶשִׁי וְצֶמֶר הָאֶרֶז וּפִשְׁתָּן שֶׁלֹּא נֻפַּץ וְסִיב שֶׁל דֶּקֶל וּמִינֵי הָעֵץ הָרַכִּים וְכַיּוֹצֵא בָּהֶן. אֶלָּא מִדָּבָר שֶׁהָאוּר נִתְלֵית בּוֹ. כְּגוֹן פִּשְׁתָּה נְפוּצָה וּבִגְדֵי שֵׁשׁ וְצֶמֶר גֶּפֶן וְכַיּוֹצֵא בָּהֶן. וְהַמַּדְלִיק צָרִיךְ שֶׁיַּדְלִיק בְּרֹב הַיּוֹצֵא מִן הַפְּתִילָה:","הַכּוֹרֵךְ דָּבָר שֶׁמַּדְלִיקִין בּוֹ עַל גַּבֵּי דָּבָר שֶׁאֵין מַדְלִיקִין בּוֹ. אִם לְהַעֲבוֹת הַפְּתִילָה כְּדֵי לְהוֹסִיף אוֹרָהּ אָסוּר. וְאִם לְהַקְשׁוֹת הַפְּתִילָה כְּדֵי שֶׁתְּהֵא עוֹמֶדֶת וְלֹא תִּשְׁתַּלְשֵׁל לְמַטָּה מֻתָּר:","נוֹתְנִין גַּרְגִּיר שֶׁל מֶלַח וּגְרִיס שֶׁל פּוֹל עַל פִּי הַנֵּר בְּעֶרֶב שַׁבָּת שֶׁיִּהְיֶה דּוֹלֵק בְּלֵיל שַׁבָּת. וְכָל הַפְּתִילוֹת שֶׁאֵין מַדְלִיקִין בָּהֶן בְּשַׁבָּת עוֹשִׂין מֵהֶן מְדוּרָה בֵּין לְהִתְחַמֵּם כְּנֶגְדָּהּ בֵּין לְהִשְׁתַּמֵּשׁ לְאוֹרָהּ בֵּין עַל גַּבֵּי מְנוֹרָה בֵּין עַל גַּבֵּי קַרְקַע. וְלֹא אָסְרוּ אֶלָּא לַעֲשׂוֹתָן פְּתִילָה לְנֵר בִּלְבַד:","שֶׁמֶן שֶׁמַּדְלִיקִין בּוֹ לִשַׁבָּת צָרִיךְ שֶׁיְּהֵא נִמְשָׁךְ אַחַר הַפְּתִילָה אֲבָל שְׁמָנִין שֶׁאֵין נִמְשָׁכִין אַחַר הַפְּתִילָה כְּגוֹן זֶפֶת וְשַׁעֲוָה וְשֶׁמֶן קִיק וְאַלְיָה וְחֵלֶב אֵין מַדְלִיקִין בָּהֶן. וּמִפְּנֵי מָה אֵין מַדְלִיקִין בִּפְתִילוֹת שֶׁאֵין הָאוּר נִתְלֵית בָּהֶן וְלֹא בִּשְׁמָנִים שֶׁאֵין נִמְשָׁכִים אַחַר הַפְּתִילָה גְּזֵרָה שֶׁמָּא יִהְיֶה אוֹר הַנֵּר אָפֵל וְיַטֶּה אוֹתָהּ בְּשָׁעָה שֶׁיִּשְׁתַּמֵּשׁ לְאוֹרָהּ:","חֵלֶב שֶׁהִתִּיכוֹ וְקִרְבֵי דָּגִים שֶׁנִּמּוֹחוּ נוֹתֵן לְתוֹכָן שֶׁמֶן כָּל שֶׁהוּא וּמַדְלִיק. אֲבָל שְׁמָנִין שֶׁאֵין מַדְלִיקִין בָּהֶן אֲפִלּוּ עֵרְבָן בִּשְׁמָנִים שֶׁמַּדְלִיקִין בָּהֶן לֹא יַדְלִיק מִפְּנֵי שֶׁאֵין נִמְשָׁכִין:","אֵין מַדְלִיקִין בְּעִטְרָן מִפְּנֵי שֶׁרֵיחוֹ רַע שֶׁמָּא יַנִּיחֶנּוּ וְיֵצֵא וְחוֹבָה עָלָיו לֵישֵׁב לְאוֹר הַנֵּר. וְלֹא בָּצֳרִי מִפְּנֵי שֶׁרֵיחוֹ טוֹב שֶׁמָּא יִקַּח מִמֶּנּוּ מִן הַנֵּר וְעוֹד מִפְּנֵי שֶׁהוּא עָף. וְלֹא בְּנֵפְט לָבָן וַאֲפִלּוּ בְּחל מִפְּנֵי שֶׁהוּא עָף וְיָבוֹא לִידֵי סַכָּנָה:","מֻתָּר לְהַדְלִיק לְכַתְּחִלָּה בִּשְׁאָר שְׁמָנִים כְּגוֹן שֶׁמֶן צְנוֹן וְשֻׁמְשְׁמִין וְלֶפֶת וְכָל כַּיּוֹצֵא בָּהֶן. אֵין אָסוּר אֶלָּא אֵלּוּ שֶׁמָּנוּ חֲכָמִים בִּלְבַד:","לֹא יִתֵּן אָדָם כְּלִי מְנֻקָּב מָלֵא שֶׁמֶן עַל פִּי הַנֵּר בִּשְׁבִיל שֶׁיְּהֵא מְנַטֵּף. וְלֹא יְמַלֵּא קְעָרָה שֶׁמֶן וְיִתְּנֶנָּה בְּצַד הַנֵּר וְיִתֵּן רֹאשׁ הַפְּתִילָה לְתוֹכָהּ בִּשְׁבִיל שֶׁתְּהֵא שׁוֹאֶבֶת. גְּזֵרָה שֶׁמָּא יִקַּח מִן הַשֶּׁמֶן שֶׁבַּכְּלִי שֶׁהֲרֵי לֹא נִמְאַס בַּנֵּר. וְאָסוּר לֵהָנוֹת בְּשַׁבָּת מִן הַשֶּׁמֶן שֶׁהֻדְלַק בּוֹ וַאֲפִלּוּ כָּבְתָה הַנֵּר וַאֲפִלּוּ נָטַף מִן הַנֵּר מִפְּנֵי שֶׁהוּא מֻקְצֶה מֵחֲמַת אִסּוּר. וְאִם חִבֵּר הַכְּלִי שֶׁיֵּשׁ בּוֹ הַשֶּׁמֶן אֶל הַנֵּר בְּסִיד וּבְחַרְסִית וְכַיּוֹצֵא בָּהֶן מֻתָּר:","אֵין נוֹתְנִין כְּלִי תַּחַת הַנֵּר לְקַבֵּל בּוֹ שֶׁמֶן בְּשַׁבָּת שֶׁהֲרֵי מְבַטֵּל הַכְּלִי מֵהֵיכָנוֹ. וְאִם נְתָנוֹ מִבְּעוֹד יוֹם מֻתָּר. וְנוֹתְנִין כְּלִי תַּחַת הַנֵּר בְּשַׁבָּת לְקַבֵּל בּוֹ נִיצוֹצוֹת מִפְּנֵי שֶׁאֵין בָּהֶן מַמָּשׁ וַהֲרֵי לֹא בִּטְלוֹ מִלְּטַלְטְלוֹ. וְאָסוּר לִתֵּן לְתוֹכוֹ מַיִם וַאֲפִלּוּ מֵעֶרֶב שַׁבָּת מִפְּנֵי שֶׁהוּא מְקָרֵב כִּבּוּי הַנִּיצוֹצוֹת:","אֵין פּוֹלִין לְאוֹר הַנֵּר וְלֹא קוֹרִין לְאוֹר הַנֵּר וַאֲפִלּוּ גָּבוֹהַּ שְׁתֵּי קוֹמוֹת וַאֲפִלּוּ עֲשָׂרָה בָּתִּים זֶה עַל גַּב זֶה וְהַנֵּר בָּעֶלְיוֹנָה לֹא יִקְרָא וְלֹא יַפְלֶה לְאוֹרָהּ בַּתַּחְתּוֹנָה שֶׁמָּא יִשְׁכַּח וְיַטֶּה. וְאִם הָיוּ שְׁנַיִם קוֹרִין בְּעִנְיָן אֶחָד מֻתָּרִין לִקְרוֹת לִפְנֵי הַנֵּר שֶׁכָּל אֶחָד מֵהֶן מַזְכִּיר חֲבֵרוֹ אִם שָׁכַח. אֲבָל לֹא בִּשְׁנֵי עִנְיָנִים שֶׁכָּל אֶחָד מֵהֶן טָרוּד בְּעִנְיָנוֹ:","הַתִּינוֹקוֹת קוֹרִין לִפְנֵי רַבָּן לְאוֹר הַנֵּר מִפְּנֵי שֶׁהָרַב מְשַׁמְּרָן. אֲבָל הוּא לֹא יִקְרָא מִפְּנֵי שֶׁאֵין אֵימָתָן עָלָיו. וְיֵשׁ לוֹ לִרְאוֹת בַּסֵּפֶר לְאוֹר הַנֵּר עַד שֶׁיִּרְאֶה רֹאשׁ הַפָּרָשָׁה שֶׁהוּא צָרִיךְ לְהַקְרוֹתָן. וְאַחַר כָּךְ נוֹתֵן הַסֵּפֶר בְּיָדָן וְהֵם קוֹרְאִין לְפָנָיו:","כֵּלִים הַדּוֹמִים זֶה לָזֶה וְאֵינָן נִכָּרִין אֶלָּא בְּעִיּוּן הַרְבֵּה אָסוּר לְהַקְרִיבָן לְאוֹר הַנֵּר וּלְהַבְחִין בֵּינֵיהֶן שֶׁמָּא יִשְׁכַּח וְיַטֶּה. לְפִיכָךְ שַׁמָּשׁ שֶׁאֵינוֹ קָבוּעַ אָסוּר לוֹ לִבְדֹּק כּוֹסוֹת וּקְעָרוֹת לְאוֹר הַנֵּר מִפְּנֵי שֶׁאֵינוֹ מַכִּירָן. בֵּין בְּנֵר שֶׁל שֶׁמֶן זַיִת בֵּין בְּנֵר שֶׁל נֵפְט שֶׁאוֹרוֹ רַב. אֲבָל שַׁמָּשׁ קָבוּעַ מֻתָּר לוֹ לִבְדֹּק לְאוֹר הַנֵּר כּוֹסוֹת וּקְעָרוֹת מִפְּנֵי שֶׁאֵינוֹ צָרִיךְ עִיּוּן הַרְבֵּה. וְאִם הָיָה נֵר שֶׁל שֶׁמֶן זַיִת אֵין מוֹרִין לוֹ לִבְדֹּק וְאַף עַל פִּי שֶׁהוּא מֻתָּר, גְּזֵרָה שֶׁמָּא יִסְתַּפֵּק מִמֶּנּוּ:","נֵר שֶׁאֲחוֹרֵי הַדֶּלֶת אָסוּר לִפְתֹּחַ הַדֶּלֶת וְלִנְעל כְּדַרְכּוֹ מִפְּנֵי שֶׁהוּא מְכַבֵּהוּ אֶלָּא יִזָּהֵר בְּשָׁעָה שֶׁפּוֹתֵחַ וּבְשָׁעָה שֶׁנּוֹעֵל. וְאָסוּר לִפְתֹּחַ אֶת הַדֶּלֶת כְּנֶגֶד הַמְּדוּרָה בְּשַׁבָּת כְּדֵי שֶׁתְּהֵא הָרוּחַ מְנַשֶּׁבֶת בָּהּ וְאַף עַל פִּי שֶׁאֵין שָׁם אֶלָּא רוּחַ מְצוּיָה. וּמַנִּיחִין הַנֵּר שֶׁל שַׁבָּת עַל גַּבֵּי אִילָן הַמְחֻבָּר לַקַּרְקַע וְאֵינוֹ חוֹשֵׁשׁ:","כָּל מְדִינוֹת וַעֲיָרוֹת שֶׁל יִשְׂרָאֵל תּוֹקְעִין בָּהֶן שֵׁשׁ תְּקִיעוֹת בְּעֶרֶב שַׁבָּת. וּבְמָקוֹם גָּבוֹהַּ הָיוּ תּוֹקְעִין כְּדֵי לְהַשְׁמִיעַ כָּל אַנְשֵׁי הַמְּדִינָה וְכָל אַנְשֵׁי הַמִּגְרָשׁ שֶׁלָּהּ:","תְּקִיעָה רִאשׁוֹנָה נִמְנְעוּ הָעוֹמְדִים בַּשָּׂדוֹת מִלַּחֲרשׁ וּמִלַּעֲדֹר וּמִלַּעֲשׂוֹת מְלָאכָה שֶׁבַּשָּׂדֶה. וְאֵין הַקְּרוֹבִין רַשָּׁאִין לִכָּנֵס לָעִיר עַד שֶׁיָּבוֹאוּ רְחוֹקִים וְיִכָּנְסוּ כֻּלָּם בְּבַת אַחַת. וַעֲדַיִן הַחֲנֻיּוֹת פְּתוּחוֹת וְהַתְּרִיסִין מֻנָּחִין. הִתְחִיל לִתְקֹעַ שְׁנִיָּה נִסְתַּלְּקוּ הַתְּרִיסִין וְנִנְעֲלוּ הַחֲנֻיּוֹת. וַעֲדַיִן הַחַמִּין וְהַקְּדֵרוֹת מֻנָּחִין עַל גַּבֵּי כִּירָה. הִתְחִיל לִתְקֹעַ תְּקִיעָה שְׁלִישִׁית סִלֵּק הַמְסַלֵּק וְהִטְמִין הַמַּטְמִין וְהִדְלִיקוּ אֶת הַנֵּרוֹת וְשׁוֹהֶה כְּדֵי לִצְלוֹת דָּג קָטָן אוֹ כְּדֵי לְהַדְבִּיק פַּת בַּתַּנּוּר. וְתוֹקֵעַ וּמֵרִיעַ וְתוֹקֵעַ וְשׁוֹבֵת:","תְּקִיעָה רִאשׁוֹנָה תּוֹקֵעַ אוֹתָהּ בְּמִנְחָה. וְהַשְּׁלִישִׁית קָרוֹב לִשְׁקִיעַת הַחַמָּה. וְכֵן תּוֹקְעִין בְּמוֹצָאֵי שַׁבָּת אַחַר צֵאת הַכּוֹכָבִים לְהַתִּיר הָעָם לְמַעֲשֵׂיהֶן:","יוֹם הַכִּפּוּרִים שֶׁחָל לִהְיוֹת בְּעֶרֶב שַׁבָּת לֹא הָיוּ תּוֹקְעִין. חָל לִהְיוֹת בְּמוֹצָאֵי שַׁבָּת לֹא תּוֹקְעִין וְלֹא מַבְדִּילִין. יוֹם טוֹב שֶׁחָל לִהְיוֹת בְּעֶרֶב שַׁבָּת תּוֹקְעִין וְלֹא מַבְדִּילִין. חָל לִהְיוֹת לְאַחַר הַשַּׁבָּת מַבְדִּילִין וְלֹא תּוֹקְעִין:"],"Mishneh Torah, Sabbatical Year and the Jubilee 4":["כָּל שֶׁתּוֹצִיא הָאָרֶץ בְּשָׁנָה שְׁבִיעִית. בֵּין מִן הַזֶּרַע שֶׁנָּפַל בָּהּ מִקֹּדֶם שְׁבִיעִית. בֵּין מִן הָעִקָּרִים שֶׁנִּקְצְרוּ מִקֹּדֶם וְחָזְרוּ וְעָשׂוּ וּשְׁנֵיהֶם נִקְרְאוּ סָפִיחַ. בֵּין מִן הָעֲשָׂבִים וְהַיְרָקוֹת שֶׁעָלוּ מֵאֲלֵיהֶן וְאֵין לָהֶן זֶרַע. הַכּל מֻתָּר לְאָכְלוֹ מִן הַתּוֹרָה שֶׁנֶּאֱמַר (ויקרא כה ו) \"וְהָיְתָה שַׁבַּת הָאָרֶץ לָכֶם לְאָכְלָה\". וַאֲפִלּוּ שָׂדֶה שֶׁנִּטַּיְבָּה בַּשְּׁבִיעִית וְצָמְחָה פֵּרוֹתֶיהָ מֻתָּרִין בַּאֲכִילָה. וְזֶה שֶׁנֶּאֱמַר (ויקרא כה ה) \"אֵת סְפִיחַ קְצִירְךָ לֹא תִקְצוֹר\" שֶׁלֹּא יִקְצֹר כְּדֶרֶךְ שֶׁקּוֹצֵר בְּכָל שָׁנָה. וְאִם קָצַר כְּדֶרֶךְ הַקּוֹצְרִין לוֹקֶה. כְּגוֹן שֶׁקָּצַר כָּל הַשָּׂדֶה וְהֶעֱמִיד כְּרִי וְדָשׁ בַּבָּקָר. אוֹ שֶׁקָּצַר לַעֲבוֹדַת הָאָרֶץ כְּמוֹ שֶּׁבֵּאַרְנוּ. אֶלָּא קוֹצֵר מְעַט מְעַט וְחוֹבֵט וְאוֹכֵל:","וּמִדִּבְרֵי סוֹפְרִים שֶׁיִּהְיוּ כָּל הַסְּפִיחִים אֲסוּרִין בַּאֲכִילָה. וְלָמָּה גָּזְרוּ עֲלֵיהֶם מִפְּנֵי עוֹבְרֵי עֲבֵרָה. שֶׁלֹּא יֵלֵךְ וְיִזְרַע תְּבוּאָה וְקִטְנִיּוֹת וְזֵרְעוֹנֵי גִּנָּה בְּתוֹךְ שָׂדֵהוּ בַּסֵּתֶר. וּכְשֶׁיִּצְמַח יֹאכַל מֵהֶם וְיֹאמַר סְפִיחִים הֵן. לְפִיכָךְ אָסְרוּ כָּל הַסְּפִיחִים הַצּוֹמְחִים בַּשְּׁבִיעִית:","הָא לָמַדְתָּ שֶׁאֵין אוֹכְלִין מִפֵּרוֹת שְׁבִיעִית אֶלָּא פֵּרוֹת הָאִילָנוֹת וְהָעֲשָׂבִים שֶׁאֵין זוֹרְעִין אוֹתָם רֹב הָאָדָם כְּגוֹן הַפֵּיגַם וְהַיַּרְבּוּזִין הַשּׁוֹטִים וְכָל כַּיּוֹצֵא בָּהֶן. אֲבָל הַיְרָקוֹת שֶׁדֶּרֶךְ רֹב הָאָדָם לְזָרְעָם בַּגִּנּוֹת וּמִינֵי תְּבוּאָה וְקִטְנִיּוֹת כָּל הַצּוֹמֵחַ מֵהֶן אָסוּר מִדִּבְרֵיהֶם. וְהַמְלַקְּטָן מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","סְפִיחִים הָעוֹלִים בִּשְׂדֵה בּוּר וּבִשְׂדֵה נִיר וּבִשְׂדֵה כֶּרֶם וּבִשְׂדֵה זֶרַע מֻתָּרִין בַּאֲכִילָה. וּמִפְּנֵי מָה לֹא גָּזְרוּ עֲלֵיהֶם לְפִי שֶׁאֵין אָדָם זוֹרֵעַ מְקוֹמוֹת אֵלּוּ. שְׂדֵה בּוּר אֵין אָדָם נִפְנֶה לְשָׁם. וּשְׂדֵה נִיר רוֹצֶה הוּא בְּתִקּוּנָהּ. וּשְׂדֵה כֶּרֶם אֵינוֹ אוֹסֵר כַּרְמוֹ. וּשְׂדֵה זֶרַע הַסְּפִיחִין מַפְסִידִין אוֹתָהּ. וְכֵן הַתֶּבֶן שֶׁל שְׁבִיעִית מֻתָּר בְּכָל מָקוֹם וְלֹא גָּזְרוּ עָלָיו:","סְפִיחִין שֶׁל שְׁבִיעִית שֶׁיָּצְאוּ לְמוֹצָאֵי שְׁבִיעִית אֲסוּרִין בַּאֲכִילָה וְאֵין תּוֹלְשִׁין אוֹתָן בַּיָּד אֶלָּא חוֹרֵשׁ כְּדַרְכּוֹ. וּבְהֵמָה רוֹעָה כְּדַרְכָּהּ:","וְעַד מָתַי אֲסוּרִין סְפִיחֵי שְׁבִיעִית בְּמוֹצָאֵי שְׁבִיעִית מֵרֹאשׁ הַשָּׁנָה וְעַד חֲנֻכָּה וּמֵחֲנֻכָּה וְאֵילָךְ הֵן מֻתָּרִין. וְהַזּוֹרֵעַ סְפִיחֵי שְׁבִיעִית אַחַר שְׁבִיעִית הַגִּדּוּלִין מֻתָּרִין:","בְּצָלִים שֶׁיָּצְאוּ מִשְּׁבִיעִית לְמוֹצָאֵי שְׁבִיעִית אִם עָשׂוּ כַּיּוֹצֵא בָּהֶן מֻתָּרִין וְאִם לָאו אֲסוּרִין. וְכֵן שְׁאָר הַפֵּרוֹת אֵין לוֹקְחִים אוֹתָם בְּמוֹצָאֵי שְׁבִיעִית אֶלָּא מִשֶּׁיֵּעָשׂוּ כַּיּוֹצֵא בָּהֶן מִפֵּרוֹת מוֹצָאֵי שְׁבִיעִית. עָשָׂה הַבַּכִּיר הֻתָּר הָאֲפִיל וּמֻתָּר לִקַּח יָרָק בְּמוֹצָאֵי שְׁבִיעִית מִיָּד:","מֵאֵימָתַי מוֹתָר אָדָם לִיקַח לוּף בְּמוֹצָאֵי שְׁבִיעִית מְשֶׁיִּרְבֶּה הֶחָדָשׁ:","בְּאֶחָד בְּתִשְׁרֵי רֹאשׁ הַשָּׁנָה לִשְׁמִטִּין וּלְיוֹבְלוֹת. פֵּרוֹת שִׁשִּׁית שֶׁנִּכְנְסוּ לַשְּׁבִיעִית אִם הָיוּ תְּבוּאָה אוֹ קִטְנִיּוֹת אוֹ פֵּרוֹת הָאִילָן וְהִגִּיעוּ לְעוֹנַת הַמַּעַשְׂרוֹת קֹדֶם רֹאשׁ הַשָּׁנָה הֲרֵי אֵלּוּ מֻתָּרִין. וְאַף עַל פִּי שֶׁאוֹסֵף אוֹתָם בַּשְּׁבִיעִית הֲרֵי הֵן כְּפֵרוֹת שִׁשִּׁית לְכָל דָּבָר. וְאִם לֹא בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת אֶלָּא אַחַר רֹאשׁ הַשָּׁנָה הֲרֵי הֵן כְּפֵרוֹת שְׁבִיעִית:","הַתְּבוּאָה וְהַקִּטְנִיּוֹת אֲסוּרִין בַּאֲכִילָה מִשּׁוּם סְפִיחִים. וּפֵרוֹת הָאִילָן אוֹכְלִין אוֹתָן בִּקְדֻשַּׁת שְׁבִיעִית:","הָאֹרֶז וְהַדֹּחַן וְהַפְּרָגִים וְהַשֻּׁמְשְׁמִין וּפוֹל הַמִּצְרִי שֶׁזְּרָעוֹ לְזֶרַע הוֹלְכִין בָּהֶן אַחַר גְּמַר פְּרִי. אִם נִגְמַר פִּרְיָם קֹדֶם רֹאשׁ הַשָּׁנָה הֲרֵי אֵלּוּ מֻתָּרִין בַּשְּׁבִיעִית כְּפֵרוֹת שִׁשִּׁית. וְאִם נִגְמְרוּ אַחַר רֹאשׁ הַשָּׁנָה אַף עַל פִּי שֶׁהִשְׁרִישׁוּ קֹדֶם רֹאשׁ הַשָּׁנָה הֲרֵי אֵלּוּ אֲסוּרִים מִשּׁוּם סְפִיחִים:","הַיָּרָק בִּשְׁעַת לְקִיטָתוֹ. וְהָאֶתְרוֹג אֲפִלּוּ הָיָה כְּפוֹל קֹדֶם רֹאשׁ הַשָּׁנָה וְנַעֲשָׂה כְּכִכָּר בַּשְּׁבִיעִית חַיָּב בְּמַעַשְׂרוֹת כְּפֵרוֹת שִׁשִּׁית. וַאֲפִלּוּ הָיָה כְּכִכָּר בַּשִּׁשִּׁית הוֹאִיל וְנִלְקַט בַּשְּׁבִיעִית הֲרֵי הוּא כְּפֵרוֹת שְׁבִיעִית. וּמִתְעַשֵּׂר כְּפֵרוֹת שִׁשִּׁית לְהַחֲמִיר:","וְכֵן פֵּרוֹת שְׁבִיעִית שֶׁיָּצְאוּ לְמוֹצָאֵי שְׁבִיעִית בִּתְבוּאָה וְקִטְנִיּוֹת וְאִילָנוֹת הוֹלְכִין אַחַר עוֹנַת הַמַּעַשְׂרוֹת. והַפְּרָגִין וְהַשֻּׁמְשְׁמִין וְהָאֹרֶז וְהַדֹּחַן וּפוֹל הַמִּצְרִי שֶׁזְּרָעוֹ לְזֶרַע אַחַר גְּמַר הַפְּרִי. וְהַיָּרָק אַחַר לְקִיטָתוֹ:","פּוֹל הַמִּצְרִי שֶׁזְּרָעוֹ לְזֶרַע בַּשִּׁשִּׁית וְנִגְמַר פִּרְיוֹ קֹדֶם רֹאשׁ הַשָּׁנָה שֶׁל שְׁבִיעִית. בֵּין יָרָק שֶׁלּוֹ בֵּין זֶרַע שֶׁלּוֹ מֻתָּר בַּשְּׁבִיעִית. וְאִם זָרַע לְיָרָק וְנִכְנְסָה עָלָיו שְׁבִיעִית בֵּין יְרָקוֹ בֵּין זַרְעוֹ אָסוּר כִּסְפִיחֵי שְׁבִיעִית. וְכֵן אִם זְרָעוֹ לְזֶרַע וּלְיָרָק אָסוּר:","עָבַר וּזְרָעוֹ בַּשְּׁבִיעִית וְיָצָא לַשְּׁמִינִית אִם זְרָעוֹ לְזֶרַע בֵּין זַרְעוֹ בֵּין יְרָקוֹ אָסוּר בְּמוֹצָאֵי שְׁבִיעִית כִּשְׁאָר הַסְּפִיחִים. וְאִם זְרָעוֹ לְיָרָק הוֹאִיל וְנִלְקַט בַּשְּׁמִינִית בֵּין יְרָקוֹ בֵּין זַרְעוֹ מֻתָּר. זְרָעוֹ לְזֶרַע וּלְיָרָק זַרְעוֹ אָסוּר מִשּׁוּם סְפִיחִים וִירָקוֹ מֻתָּר:","בְּנוֹת שׁוּחַ הוֹאִיל וְהֵן נִגְמָרוֹת לְאַחַר שָׁלֹשׁ שָׁנִים אִם בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת קֹדֶם רֹאשׁ הַשָּׁנָה שֶׁל שְׁמִינִית הֲרֵי הֵן נֶאֱכָלוֹת בְּשָׁנָה שְׁנִיָּה מִן הַשָּׁבוּעַ בְּתוֹרַת שְׁבִיעִית:","הַבְּצָלִים הַסָּרִיסִים וּפוֹל הַמִּצְרִי שֶׁמָּנַע מֵהֶם מַיִם שְׁלֹשִׁים יוֹם קֹדֶם רֹאשׁ הַשָּׁנָה. וְשֶׁל בַּעַל שֶׁמָּנַע מֵהֶם שָׁלֹשׁ עוֹנוֹת לִפְנֵי רֹאשׁ הַשָּׁנָה הֲרֵי אֵלּוּ מִפֵּרוֹת שִׁשִּׁית. פָּחוֹת מִכֵּן הֲרֵי הֵם כִּסְפִיחֵי שְׁבִיעִית:","הַדְּלוּעִין שֶׁקִּיְּמָן לְזֶרַע אִם הֻקְשׁוּ לִפְנֵי רֹאשׁ הַשָּׁנָה וְנִפְסְלוּ מִלֶּאֱכל אָדָם מֻתָּר לְקַיְּמָן בַּשְּׁבִיעִית שֶׁהֵן מִפֵּרוֹת שִׁשִּׁית. וְאִם לָאו אֲסוּרִין כִּסְפִיחֵי שְׁבִיעִית. וְכֵן הַיְרָקוֹת כֻּלָּן שֶׁהֻקְשׁוּ לִפְנֵי רֹאשׁ הַשָּׁנָה מֻתָּר לְקַיְּמָן בַּשְּׁבִיעִית וְאִם הָיוּ רַכִּים אָסוּר לְקַיְּמָן מִשּׁוּם סְפִיחִים. אֵין מְחַיְּבִין אוֹתוֹ לְשָׁרֵשׁ אֶת הַלּוּף אֶלָּא מַנִּיחוֹ בָּאָרֶץ כְּמוֹת שֶׁהוּא. אִם צָמַח לְמוֹצָאֵי שְׁבִיעִית מֻתָּר. וְאֵין מְחַיְּבִין אוֹתוֹ לְשָׁרֵשׁ אֶת הַקֻּנְדָּס אֶלָּא גּוֹזֵז בֶּעָלִין וְאִם צָמַח לְמוֹצָאֵי שְׁבִיעִית מֻתָּר:","לוּף שֶׁל עֶרֶב שְׁבִיעִית וְכֵן בְּצָלִים שֶׁל עֶרֶב שְׁבִיעִית הַקִּיצוֹנִים וּפוּאָה שֶׁנִּגְמְרוּ לִפְנֵי שְׁבִיעִית מֻתָּר לְעָקְרָן בַּשְּׁבִיעִית בְּקַרְדֻּמּוֹת שֶׁל מַתֶּכֶת. וְאֵין בָּזֶה מִשּׁוּם עֲבוֹדַת הָאָרֶץ:","הַבְּצָלִים שֶׁיָּרְדוּ עֲלֵיהֶם גְּשָׁמִים בַּשְּׁבִיעִית וְצָמְחוּ כָּל זְמַן שֶׁהֶעָלִין שֶׁלָּהֶן יְרֻקִּין הֲרֵי אֵלּוּ מֻתָּרִין. וְאִם הִשְׁחִירוּ הֲרֵי הֵן כִּנְטוּעִין בָּאָרֶץ וְאוֹתָן הֶעָלִין אֲסוּרִין מִשּׁוּם סְפִיחִין. וּבֵין כָּךְ וּבֵין כָּךְ הַבְּצָלִים עַצְמָן בְּהֶתֵּרָן עוֹמְדִין:","בָּצָל שֶׁעֲקָרוֹ בַּשְּׁבִיעִית וּנְטָעוֹ בַּשְּׁמִינִית וְרַבּוּ גִּדּוּלָיו עַל עִקָּרוֹ הֶעֱלוּ גִּדּוּלָיו אֶת עִקָּרוֹ וְהֻתַּר הַכּל הוֹאִיל וּשְׁבִיעִית אֲסוּרָה עַל יְדֵי קַרְקַע כָּךְ נְטִילָתָהּ עַל יְדֵי קַרְקַע:","הַפֵּרוֹת שֶׁיּוֹצִיא הָאִילָן בַּשְּׁבִיעִית לֹא יַאַסְפֵם כְּדֶרֶךְ שֶׁאוֹסֵף בְּכָל שָׁנָה שֶׁנֶּאֱמַר (ויקרא כה ה) \"וְאֶת עִנְּבֵי נְזִירֶךָ לֹא תִבְצֹר\". וְאִם בָּצַר לַעֲבוֹדַת הָאִילָן אוֹ שֶׁבָּצַר כְּדֶרֶךְ הַבּוֹצְרִים לוֹקֶה:","וְכֵיצַד עוֹשֶׂה. תְּאֵנִים שֶׁל שְׁבִיעִית אֵין קוֹצִין אוֹתָן בְּמֻקְצֶה אֲבָל מְיַבְּשָׁן בֶּחָרָבָה. וְלֹא יִדְרֹךְ עֲנָבִים בַּגַּת אֲבָל דּוֹרֵךְ הוּא בַּעֲרֵבָה. וְלֹא יַעֲשֶׂה זֵיתִים בְּבַיִת הַבַּד. אֲבָל כּוֹתֵשׁ הוּא וּמַכְנִיס לְתוֹךְ בַּד קָטָן בְּיוֹתֵר וְטוֹחֵן בְּבֵית הַבַּד וּבַקֹּטֶב וּמַכְנִיס לְבַד קְטַנָּה. וְכֵן בִּשְׁאָר הַדְּבָרִים כָּל שֶׁיָּכוֹל לְשַׁנּוֹת מְשַׁנֶּה:","מִצְוַת עֲשֵׂה לְהַשְׁמִיט כָּל מַה שֶּׁתּוֹצִיא הָאָרֶץ בַּשְּׁבִיעִית שֶׁנֶּאֱמַר (שמות כג יא) \"וְהַשְּׁבִיעִת תִּשְׁמְטֶנָּה וּנְטַשְׁתָּהּ\". וְכָל הַנּוֹעֵל כַּרְמוֹ אוֹ סָג שָׂדֵהוּ בַּשְּׁבִיעִית בִּטֵּל מִצְוַת עֲשֵׂה. וְכֵן אִם אָסַף כָּל פֵּרוֹתָיו לְתוֹךְ בֵּיתוֹ. אֶלָּא יַפְקִיר הַכּל וְיַד הַכּל שָׁוִין בְּכָל מָקוֹם שֶׁנֶּאֱמַר (שמות כג יא) \"וְאָכְלוּ אֶבְיֹנֵי עַמֶּךָ\". וְיֵשׁ לוֹ לְהָבִיא לְתוֹךְ בֵּיתוֹ מְעַט כְּדֶרֶךְ שֶׁמְּבִיאִין מִן הַהֶפְקֵר. חָמֵשׁ כַּדֵּי שֶׁמֶן חֲמִשָּׁה עָשָׂר כַּדֵּי יַיִן. וְאִם הֵבִיא יֶתֶר מִזֶּה מֻתָּר:","אֵין שְׁבִיעִית נוֹהֶגֶת אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל בִּלְבַד שֶׁנֶּאֱמַר (ויקרא כה ב) \"כִּי תָבֹאוּ אֶל הָאָרֶץ\" וְגוֹ'. וְנוֹהֶגֶת בֵּין בִּפְנֵי הַבַּיִת בֵּין שֶׁלֹּא בִּפְנֵי הַבַּיִת:","כָּל שֶׁהֶחְזִיקוּ בּוֹ עוֹלֵי בָּבֶל עַד כְּזִיב אָסוּר בַּעֲבוֹדָה וְכָל הַסְּפִיחִין שֶׁצּוֹמְחִין בּוֹ אֲסוּרִין בַּאֲכִילָה. וְכָל שֶׁלֹּא הֶחֱזִיקוּ בּוֹ אֶלָּא עוֹלֵי מִצְרַיִם בִּלְבַד שֶׁהוּא מִכְּזִיב וְעַד הַנָּהָר וְעַד אָמְנָה. אַף עַל פִּי שֶׁהוּא אָסוּר בָּעֲבוֹדָה בַּשְּׁבִיעִית. הַסְּפִיחִין שֶׁצּוֹמְחִין בּוֹ מֻתָּרִים בַּאֲכִילָה. וּמֵהַנָּהָר וּמֵאֲמָנָה וָהָלְאָה מֻתָּר בָּעֲבוֹדָה בַּשְּׁבִיעִית:","סוּרְיָא אַף עַל פִּי שֶׁאֵין שְׁבִיעִית נוֹהֶגֶת בָּהּ מִן הַתּוֹרָה גָּזְרוּ עָלֶיהָ שֶׁתִּהְיֶה אֲסוּרָה בַּעֲבוֹדָה בַּשְּׁבִיעִית כְּאֶרֶץ יִשְׂרָאֵל. כְּדֵי שֶׁלֹּא יָנִיחוּ אֶרֶץ יִשְׂרָאֵל וְיֵלְכוּ וְיִשְׁתַּקְּעוּ שָׁם. אֲבָל עַמּוֹן וּמוֹאָב וּמִצְרַיִם וְשִׁנְעָר אַף עַל פִּי שֶׁהֵם חַיָּבוֹת בְּמַעַשְׂרוֹת מִדִּבְרֵיהֶם אֵין שְׁבִיעִית נוֹהֶגֶת בָּהֶן:","עֵבֶר הַיַּרְדֵּן שְׁבִיעִית נוֹהֶגֶת בָּהּ מִדִּבְרֵיהֶם. וּסְפִיחֵי סוּרְיָא וְעֵבֶר הַיַּרְדֵּן מֻתָּרִין בַּאֲכִילָה. לֹא יִהְיוּ אֲרָצוֹת אֵלּוּ חֲמוּרִין מֵאֶרֶץ יִשְׂרָאֵל שֶׁהֶחְזִיקוּ בָּהּ עוֹלֵי מִצְרַיִם:","עַכּוּ\"ם שֶׁקָּנָה קַרְקַע בָּאָרֶץ יִשְׂרָאֵל וּזְרָעָהּ בַּשְּׁבִיעִית פֵּרוֹתֶיהָ מֻתָּרִין. שֶׁלֹּא גָּזְרוּ עַל הַסְּפִיחִין אֶלָּא מִפְּנֵי עוֹבְרֵי עֲבֵרָה. וְהָעַכּוּ\"ם אֵינָן מְצֻוִּין עַל הַשְּׁבִיעִית כְּדֵי שֶׁנִּגְזֹר עֲלֵיהֶם:","עֲיָרוֹת אֶרֶץ יִשְׂרָאֵל הַסְּמוּכוֹת לַסְּפָר מוֹשִׁיבִים עֲלֵיהֶם נֶאֱמָן כְּדֵי שֶׁלֹּא יָפוּצוּ עַכּוּ\"ם וְיָבֹזּוּ פֵּרוֹת שְׁבִיעִית:"],"Mishneh Torah, Sacrifices Rendered Unfit 15":["כָּל הַזְּבָחִים שֶׁנִּשְׁחֲטוּ בְּמַחִשֶׁבֶת שִׁנּוּי הַשֵּׁם. בֵּין בְּקָרְבְּנוֹת יָחִיד בֵּין בְּקָרְבְּנוֹת צִבּוּר. כְּשֵׁרִים אֶלָּא שֶׁלֹּא עָלוּ לַבְּעָלִים לְשֵׁם חוֹבָה. חוּץ מִן הַחַטָּאת וְהַפֶּסַח שֶׁאִם נַעֲשׂוּ בְּמַחְשֶׁבֶת שִׁנּוּי הַשֵּׁם פְּסוּלִין. וְאֶחָד הַמְשַׁנֶּה שֵׁם הַזֶּבַח בִּשְׁעַת שְׁחִיטָה אוֹ בִּשְׁעַת קַבָּלָה אוֹ בִּשְׁעַת הוֹלָכָה אוֹ בִּזְרִיקָה כְּמוֹ שֶׁבֵּאַרְנוּ. כֵּיצַד לֹא עָלוּ לְשֵׁם חוֹבָה. כְּגוֹן שֶׁשָּׁחַט עוֹלָה לְשֵׁם שְׁלָמִים לֹא עָלְתָה לַבְּעָלִים לֹא מִשּׁוּם עוֹלָה שֶׁהֵם חַיָּבִין בָּהּ וְלֹא מִשּׁוּם שְׁלָמִים. אֶלָּא חַיָּבִין לְהָבִיא זֶבַח אַחֵר. וְכֵן אִם שָׁחַט עוֹלַת רְאוּבֵן לְשֵׁם שִׁמְעוֹן לֹא עָלְתָה לֹא לִרְאוּבֵן וְלֹא לְשִׁמְעוֹן. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁעָקַר שֵׁם הַזֶּבַח בְּזָדוֹן. אֲבָל אִם טָעָה וְדִמָּה שֶׁזּוֹ הָעוֹלָה שְׁלָמִים הִיא וְעָשָׂה כָּל עֲבוֹדוֹתֶיהָ לְשֵׁם שְׁלָמִים עָלְתָה לַבְּעָלִים לְשֵׁם חוֹבָה. וְכֵן הַחַטָּאת וְהַפֶּסַח שֶׁעֲשָׂאָן בְּמַחְשֶׁבֶת שִׁנּוּי הַשֵּׁם בְּטָעוּת כְּשֵׁרִים. שֶׁעֲקִירָה בְּטָעוּת אֵינָהּ עֲקִירָה. וְכֵן עוֹלַת הָעוֹף שֶׁמְּלָקָהּ אוֹ שֶׁמִּצָּה דָּמָהּ בְּמַחְשֶׁבֶת שִׁנּוּי הַשֵּׁם כְּשֵׁרָה וְלֹא עָלְתָה לַבְּעָלִים. וְחַטַּאת הָעוֹף פְּסוּלָה:","וְכֵן כָּל הַמְּנָחוֹת שֶׁנַּעֲשׂוּ בְּמַחְשֶׁבֶת שִׁנּוּי הַשֵּׁם כְּשֵׁרוֹת וְלֹא עָלוּ לַבְּעָלִים חוּץ מִמִּנְחַת חוֹטֵא וּמִנְחַת קְנָאוֹת שֶׁאִם חִשֵּׁב בְּאַחַת מֵאַרְבַּע עֲבוֹדוֹת שֶׁלָּהֶן מַחֲשֶׁבֶת שִׁנּוּי הַשֵּׁם פְּסוּלוֹת. שִׁנּוּי הַשֵּׁם בְּמִנְחָה כֵּיצַד. כְּגוֹן שֶׁקָּמַץ מִנְחַת נְדָבָה לְשֵׁם מִנְחַת חוֹטֵא. אוֹ מַרְחֶשֶׁת לְשֵׁם מַחֲבַת. אוֹ מַחֲבַת לְשֵׁם מַרְחֶשֶׁת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אָסוּר לְחַשֵּׁב בְּקָדָשִׁים מַחֲשָׁבָה שֶׁאֵינָהּ נְכוֹנָה כְּמוֹ שֶׁיִּתְבָּאֵר. לְפִיכָךְ זֶבַח שֶׁשְּׁחָטוֹ שֶׁלֹּא לִשְׁמוֹ. אוֹ מִנְחָה שֶׁקְּמָצָהּ שֶׁלֹּא לִשְׁמָהּ. בֵּין בְּזָדוֹן בֵּין בִּשְׁגָגָה. חַיָּב לְהַשְׁלִים שְׁאָר עֲבוֹדוֹת לִשְׁמָן. אֲפִלּוּ שָׁחַט וְקִבֵּל וְהוֹלִיךְ בְּמַחְשֶׁבֶת שִׁנּוּי הַשֵּׁם חַיָּב לִזְרֹק בְּמַחְשָׁבָה נְכוֹנָה. וּמִפְּנֵי מָה נִשְׁתַּנָּה דִּין הַחַטָּאת וְהַפֶּסַח מִכָּל הַזְּבָחִים. וְדִין מִנְחַת חוֹטֵא וּמִנְחַת קְנָאוֹת מִכָּל הַמְּנָחוֹת. מִפְּנֵי שֶׁעִיֵּן עֲלֵיהֶם הַכָּתוּב. הֲרֵי הוּא אוֹמֵר בְּחַטָּאת (ויקרא ד לג) \"וְשָׁחַט אוֹתָהּ לְחַטָּאת\". שֶׁתִּהְיֶה שְׁחִיטָה לְשֵׁם חַטָּאת. וְכֵן שְׁאָר עֲבוֹדוֹתֶיהָ לִשְׁמָהּ. וְנֶאֱמַר (ויקרא ד לה) \"עַל חַטָּאתוֹ\" שֶׁתֵּעָשֶׂה לְשֵׁם אוֹתוֹ הַחֵטְא. וְנֶאֱמַר (ויקרא ד לה) \"וְכִפֶּר עָלָיו\" שֶׁתִּהְיֶה לְשֵׁם בְּעָלֶיהָ. וְנֶאֱמַר בְּפֶסַח (דברים טז א) \"וְעָשִׂיתָ פֶּסַח לַה' אֱלֹהֶיךָ\" שֶׁתִּהְיֶה כָּל עֲשִׂיָּתוֹ לְשֵׁם פֶּסַח. וְנֶאֱמַר (שמות יב כז) \"וַאֲמַרְתֶּם זֶבַח פֶּסַח הוּא לַה'\" שֶׁתִּהְיֶה זְבִיחָתוֹ לְשֵׁם פֶּסַח. הָא אִם שִׁנָּה שְׁמוֹ אוֹ שֵׁם בְּעָלָיו פָּסוּל. וּבְמִנְחַת חוֹטֵא הוּא אוֹמֵר מִנְחָה הִיא. וּבְמִנְחַת סוֹטָה נֶאֱמַר (במדבר ה טו) \"כִּי מִנְחַת קְנָאוֹת הִיא\". שֶׁיִּהְיוּ כָּל מַעֲשֶׂיהָ לִשְׁמָן:","חַטָּאת שֶׁשְּׁחָטָהּ לְשֵׁם זֶבַח אַחֵר כְּגוֹן שֶׁשְּׁחָטָהּ לְשֵׁם עוֹלָה אוֹ לְשֵׁם אָשָׁם אוֹ לְשֵׁם שְׁלָמִים. פְּסוּלָה כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל אִם שְׁחָטָהּ לְשֵׁם חֻלִּין. הֲרֵי זוֹ כְּשֵׁרָה וְלֹא עָלְתָה לַבְּעָלִים:","מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁהַקָּדָשִׁים מְחַלְּלִין קָדָשִׁים וְאֵין הַחֻלִּין מְחַלְּלִין קָדָשִׁים:","שְׁחָטָהּ לְשֵׁם חֵטְא אַחֵר כְּגוֹן שֶׁבָּאָה עַל אֲכִילַת חֵלֶב וּשְׁחָטָהּ עַל אֲכִילַת דָּם פְּסוּלָה:","שְׁחָטָהּ לְשֵׁם אָדָם אַחֵר שֶׁהוּא מְחֻיָּב חַטָּאת. אֲפִלּוּ חַטָּאת שֶׁאֵינָהּ קְבוּעָה הֲרֵי זוֹ פְּסוּלָה:","אֲבָל אִם שְׁחָטָהּ לְשֵׁם אֶחָד שֶׁהוּא מְחֻיָּב עוֹלָה הֲרֵי זוֹ כְּשֵׁרָה וְלֹא עָלְתָה לַבְּעָלִים. (ויקרא ד לא) (ויקרא ד לה) \"וְכִפֶּר עָלָיו\" וְלֹא עַל חֲבֵרוֹ שֶׁהוּא מְחֻיָּב חַטָּאת כְּמוֹתוֹ:","שְׁחָטָהּ לְשֵׁם מֵת כְּשֵׁרָה וְלֹא עָלְתָה לַבְּעָלִים שֶׁאֵין כַּפָּרָה לַמֵּתִים. שְׁחָטָהּ לְשֵׁם מִי שֶׁאֵינוֹ מְחֻיָּב קָרְבָּן כְּלָל לֹא חַטָּאת וְלֹא עוֹלָה וְלֹא שְׁאָר קָרְבָּנוֹת. הֲרֵי זוֹ פְּסוּלָה. שֶׁמָּא מְחֻיָּב הוּא וְאֵינוֹ יוֹדֵעַ:","שְׁחָטָהּ לִשְׁמָהּ וְחִשֵּׁב בִּשְׁעַת הַשְּׁחִיטָה לִזְרֹק דָּמָהּ שֶׁלֹּא לִשְׁמָהּ הֲרֵי זוֹ פְּסוּלָה. לְפִי שֶׁמְּחַשְּׁבִין מֵעֲבוֹדָה לַעֲבוֹדָה. וְזֹאת הַמַּחְשָׁבָה שֶׁחִשֵּׁב בִּשְׁעַת הַשְּׁחִיטָה כְּאִלּוּ חִשְּׁבָהּ בִּשְׁעַת זְרִיקָה וּלְפִיכָךְ פְּסוּלָה:","הַפֶּסַח שֶׁשְּׁחָטוֹ בְּמַחְשֶׁבֶת שִׁנּוּי הַשֵּׁם. בֵּין שֶׁשִּׁנָּה שְׁמוֹ לְשֵׁם זֶבַח אַחֵר בֵּין שֶׁשִּׁנָּהוּ לְשֵׁם חֻלִּין פָּסוּל שֶׁנֶּאֱמַר (שמות יב כז) \"וַאֲמַרְתֶּם זֶבַח פֶּסַח הוּא לַה'\". בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁשְּׁחָטוֹ בִּזְמַנּוֹ שֶׁהוּא יוֹם אַרְבָּעָה עָשָׂר בְּנִיסָן אֲפִלּוּ שְׁחָטוֹ בְּשַׁחֲרִית בְּמַחְשֶׁבֶת שִׁנּוּי הַשֵּׁם פָּסוּל. אֲבָל אִם שְׁחָטוֹ שֶׁלֹּא בִּזְמַנּוֹ בְּמַחְשָׁבָה שֶׁלֹּא לִשְׁמוֹ כָּשֵׁר. שֶׁלֹּא לְשֵׁם בְּעָלָיו נַעֲשָׂה כְּמִי שֶׁאֵין לוֹ בְּעָלִים בִּזְמַנּוֹ וּפָסוּל:","פֶּסַח שֶׁשְּׁחָטוֹ לִשְׁמוֹ בְּאַרְבָּעָה עָשָׂר קֹדֶם חֲצוֹת פָּסוּל לְפִי שֶׁאֵינוֹ זְמַנּוֹ. עָבְרָה שְׁנָתוֹ וְשָׁחַט בִּזְמַנּוֹ לְשֵׁם פֶּסַח וְכֵן הַשּׁוֹחֵט שְׁאָר זְבָחִים לְשֵׁם פֶּסַח אֲפִלּוּ שְׁחָטָן אַחַר חֲצוֹת הֲרֵי אֵלּוּ כְּשֵׁרִים וְלֹא עָלוּ לַבְּעָלִים לְשֵׁם חוֹבָה:","תּוֹדָה שֶׁשְּׁחָטָהּ לְשֵׁם שְׁלָמִים עָלְתָה לַבְּעָלִים. וּשְׁלָמִים שֶׁשְּׁחָטָן לְשֵׁם תּוֹדָה לֹא עָלוּ לַבְּעָלִים. לְפִי שֶׁהַתּוֹדָה נִקְרֵאת שְׁלָמִים וּשְׁלָמִים לֹא נִקְרְאוּ תּוֹדָה:","עוֹלָה שֶׁשְּׁחָטָהּ עַל מִי שֶׁאֵינוֹ מְחֻיָּב קָרְבָּן כְּלָל לֹא עָלְתָה לַבְּעָלִים. שֶׁהֲרֵי שְׁחָטָהּ שֶׁלֹּא לְשֵׁם בְּעָלֶיהָ. וְאַף עַל פִּי שֶׁזֶּה שֶׁשְּׁחָטָהּ לִשְׁמוֹ אֵינוֹ מְחֻיָּב כְּלוּם בְּעִנְיָנוֹ. אִי אֶפְשָׁר שֶׁלֹּא יִהְיֶה חַיָּב כַּפָּרָה לַשָּׁמַיִם שֶׁאֵין לְךָ אָדָם בְּיִשְׂרָאֵל שֶׁלֹּא עָבַר מֵעוֹלָם עַל מִצְוַת עֲשֵׂה:","עוֹלָה הַבָּאָה לְאַחַר מִיתָה שֶׁעֲשָׂאָהּ שֶׁלֹּא לְשֵׁם בְּעָלֶיהָ עָלְתָה לַבְּעָלִים לְשֵׁם חוֹבָה. שֶׁאֵין בְּעָלִים לְאַחַר מִיתָה:","שְׁנֵי כִּבְשֵׂי עֲצֶרֶת שֶׁשְּׁחָטָן לְשֵׁם אֵילִים לֹא עָלוּ לַצִּבּוּר לְשֵׁם חוֹבָה. וְאִם דִּמָּה שֶׁהֵן אֵילִים וּשְׁחָטָן לְשֵׁם אֵילִים עָלוּ לָהֶן. מִפְּנֵי שֶׁהִיא עֲקִירָה בְּטָעוּת:","אֲשַׁם מְצֹרָע שֶׁשְּׁחָטוֹ שֶׁלֹּא לִשְׁמוֹ. אוֹ שֶׁלֹּא נָתַן מִדָּמוֹ עַל גַּבֵּי בְּהוֹנוֹת. טָעוּן נְסָכִים. שֶׁאִם יִקָּרֵב בְּלֹא נְסָכִים נִמְצָא כְּמַקְרִיב נְדָבָה וְאֵין הָאָשָׁם בָּא נְדָבָה:","כֶּבֶשׂ הַבָּא עִם הָעֹמֶר שֶׁשְּׁחָטוֹ שֶׁלֹּא לִשְׁמוֹ. לֹא יָבִיא מִנְחַת נְסָכִים שֶׁלּוֹ שְׁנֵי עֶשְׂרוֹנִים אֶלָּא עִשָּׂרוֹן אֶחָד כִּשְׁאָר הַנְּדָבוֹת. שֶׁהֲרֵי לֹא עָלָה לְשֵׁם חוֹבָתוֹ. וְכֵן תָּמִיד שֶׁשְּׁחָטוֹ שֶׁלֹּא לִשְׁמוֹ לֹא יַעֲלֶה עִמּוֹ שְׁנֵי גִּזְרֵי עֵצִים כִּשְׁאָר הַתְּמִידִים. שֶׁהֲרֵי לֹא עָלָה לְחוֹבַת הַתָּמִיד אֶלָּא הֲרֵי הוּא כְּכָל הַנְּדָבוֹת:","שְׁנֵי כִּבְשֵׂי עֲצֶרֶת שֶׁשְּׁחָטָן שֶׁלֹּא לִשְׁמָן. אוֹ שֶׁשְּׁחָטָן בֵּין לִפְנֵי זְמַנָּן בֵּין לְאַחַר זְמַנָּן. הַדָּם יִזָּרֵק וְהַבָּשָׂר יֵאָכֵל אַף עַל פִּי שֶׁלֹּא עָלוּ לַצִּבּוּר לְשֵׁם חוֹבָה. וְאִם הָיְתָה שַׁבָּת לֹא יִזְרֹק. וְאִם זָרַק הֻרְצָה לְהַקְטִיר אֵימוּרִין לָעֶרֶב:","וְכֵן שַׁלְמֵי נָזִיר שֶׁשְּׁחָטָן שֶׁלֹּא לִשְׁמָן אַף עַל פִּי שֶׁלֹּא עָלוּ לַבְּעָלִים הֲרֵי הֵן נֶאֱכָלִין לְיוֹם וְלַיְלָה וְאֵינָן טְעוּנִין לֶחֶם. וְכֵן אֲשַׁם נָזִיר וַאֲשַׁם מְצֹרָע שֶׁשְּׁחָטָן שֶׁלֹּא לִשְׁמָן אַף עַל פִּי שֶׁלֹּא עָלוּ לַבְּעָלִים הֲרֵי הֵן נֶאֱכָלִים:"],"Mishneh Torah, Sacrifices Rendered Unfit 9":["קֵן סְתוּמָה שֶׁפָּרַח מִמֶּנָּה גּוֹזָל לָאֲוִיר. אוֹ שֶׁפָּרַח לְבֵין הָעוֹפוֹת שֶׁיָּמוּתוּ כֻּלָּן. אוֹ שֶׁמֵּת גּוֹזָל אֶחָד. יִקַּח זוּג לַשֵּׁנִי:","פָּרַח לְבֵין הַקְּרֵבוֹת. פָּסוּל וּפוֹסֵל אֶחָד כְּנֶגְדּוֹ. שֶׁהַגּוֹזָל הַפּוֹרֵחַ מִקֵּן סָתוּם לְבֵין הַקְּרֵבוֹת פָּסוּל וּפוֹסֵל אֶחָד כְּנֶגְדּוֹ. כֵּיצַד. פָּרַח גּוֹזָל מִן הַסָּתוּם לַעֲשָׂרָה עוֹפוֹת סְתוּמוֹת. אִם עָשָׂה חֲמִשָּׁה לְמַטָּה וְשִׁשָּׁה לְמַעְלָה. הֲרֵי חָמֵשׁ עוֹלוֹת כְּשֵׁרוֹת מֵהַשִּׁשָּׁה שֶׁל מַעְלָה וְאַרְבַּע חַטָּאוֹת כְּשֵׁרוֹת מֵהַחֲמִשָּׁה עוֹפוֹת שֶׁנַּעֲשׂוּ לְמַטָּה. שֶׁאֲנִי אוֹמֵר שֶׁמָּא הַגּוֹזָל הַפּוֹרֵחַ הוּא אֶחָד מֵחֲמִשָּׁה שֶׁל מַטָּה. וְכֵן אִם עָשָׂה מֵהֶם שִׁשָּׁה לְמַטָּה וַחֲמִשָּׁה לְמַעְלָה נִמְצֵאת הַכָּשֵׁר חָמֵשׁ חַטָּאוֹת וְאַרְבַּע עוֹלוֹת. שֶׁאֲנִי אוֹמֵר שֶׁמָּא הַגּוֹזָל מֵחֲמִשָּׁה שֶׁל מַעְלָה. נִמְצֵאת הַכָּשֵׁר מֵהָעֲשָׂרָה תִּשְׁעָה הֲרֵי פָּסַל אֶחָד:","אַרְבָּעָה עוֹפוֹת סְתוּמוֹת וְאַרְבָּעָה עוֹפוֹת שְׁנִיּוֹת סְתוּמוֹת. פָּרַח אֶחָד מִן הָרִאשׁוֹנוֹת לַשְּׁנִיּוֹת פָּסַל אֶחָד מִן הַשְּׁנִיּוֹת. אַחַר שֶׁנִּתְעָרְבוּ חָזַר אֶחָד מִן הַשְּׁנִיּוֹת וּפָרַח לָרִאשׁוֹנוֹת פָּסַל אֶחָד מִן הָרִאשׁוֹנוֹת. וְנִמְצָא הַכָּשֵׁר מִן הָרִאשׁוֹנוֹת שְׁתַּיִם בִּלְבַד:","חָזַר אֶחָד וּפָרַח מִן הָרִאשׁוֹנוֹת לַשְּׁנִיּוֹת אֲפִלּוּ כָּל הַיּוֹם אֵינוֹ מוֹסִיף לְהַפְסִיד יֶתֶר עַל זֶה שֶׁאֲפִלּוּ הֵן מְעוֹרָבוֹת כֻּלָּן זוֹ בָּזוֹ מֶחֱצָה כָּשֵׁר וּמֶחֱצָה פָּסוּל כְּמוֹ שֶׁבֵּאַרְנוּ:","צִבּוּר אֶחָד יֵשׁ בּוֹ שְׁנֵי עוֹפוֹת. וּבַשֵּׁנִי אַרְבָּעָה. וּבַשְּׁלִישִׁי שִׁשָּׁה. וּבָרְבִיעִי שְׁמוֹנָה. וּבַחֲמִישִׁי עֲשָׂרָה. וּבַשִּׁשִּׁי שְׁנֵים עָשָׂר. וּבַשְּׁבִיעִי אַרְבָּעָה עָשָׂר. וּפָרַח גּוֹזָל מִן הָרִאשׁוֹנָה לַשְּׁנִיָּה. וְאֶחָד מִן הַשְּׁנִיָּה לַשְּׁלִישִׁית. וּמִשְּׁלִישִׁית לִרְבִיעִית. מֵרְבִיעִית לַחֲמִישִׁית. וּמֵחֲמִישִׁית לַשִּׁשִּׁית. וּמִשִּׁשִׁית לִשְׁבִיעִית. וְחָזַר אֶחָד וּפָרַח מִצִּבּוּר לְצִבּוּר עַד שֶׁחָזַר לָרִאשׁוֹנָה שֶׁפָּרַח מִמֶּנָּה רִאשׁוֹנָה. פּוֹסֵל אֶחָד בַּהֲלִיכָתוֹ וְאֶחָד בַּחֲזִירָתוֹ. הָרִאשׁוֹנָה וְהַשְּׁנִיָּה אֵין לָהֶם כְּלוּם. וְהַשְּׁלִישִׁית יֵשׁ לָהּ שְׁנֵי עוֹפוֹת. וְהָרְבִיעִית יֵשׁ לָהּ אַרְבָּעָה. וְהַחֲמִישִׁית יֵשׁ לָהּ שִׁשָּׁה. וְהַשִּׁשִּׁית יֵשׁ לָהּ שְׁמוֹנָה. וְהַשְּׁבִיעִית יֵשׁ לָהּ שְׁנֵים עָשָׂר. חָזַר אֶחָד וּפָרַח פַּעַם שְׁנִיָּה מִזּוֹ לָזוֹ וְחָזַר אֶחָד וּפָרַח מִן הָאַחֲרוֹנָה לְשֶׁלְּמַעְלָה מִמֶּנָּה עַד שֶׁחָזַר לָרִאשׁוֹנָה. פּוֹסֵל אֶחָד בַּהֲלִיכָתוֹ וְאֶחָד בַּחֲזִירָתוֹ. הַשְּׁלִישִׁית וְהָרְבִיעִית אֵין לָהֶם כְּלוּם. וְהַחֲמִישִׁית יֵשׁ לָהּ שְׁנֵי עוֹפוֹת כְּשֵׁרִים. וְהַשִּׁשִּׁית יֵשׁ לָהּ אַרְבָּעָה. הַשְּׁבִיעִית יֵשׁ לָהּ עֲשָׂרָה. פָּרַח פַּעַם שְׁלִישִׁית גּוֹזָל מִזּוֹ לָזוֹ. וְחָזַר פַּעַם רְבִיעִית מִזּוֹ לָזוֹ. פּוֹסֵל אֶחָד בַּהֲלִיכָתוֹ וְאֶחָד בַּחֲזִירָתוֹ. וְהַחֲמִישִׁית וְהַשִּׁשִּׁית נִפְסְלוּ כֻּלָּן. וְהַשְּׁבִיעִית נִשְׁאֲרוּ לָהּ שְׁמוֹנָה עוֹפוֹת כְּשֵׁרִין. כְּשֶׁיַּעֲשֶׂה אַרְבָּעָה עָשָׂר שֶׁבַע לְמַעְלָה וְשֶׁבַע לְמַטָּה יִהְיוּ שְׁמוֹנָה מֵהֶן כְּשֵׁרִין וְהַשִּׁשָּׁה פְּסוּלִין מִפְּנֵי תַּעֲרֹבֶת גּוֹזָלוֹת אֵלּוּ שֶׁפָּרְחוּ בַּהֲלִיכָה וּבַחֲזָרָה:","קֵן סְתוּמָה וְקֵן מְפֹרֶשֶׁת. פָּרַח מִן הַסְּתוּמָה לַמְּפֹרֶשֶׁת. יִקַּח זוּג לְשֵׁנִי. חָזַר אוֹ שֶׁפָּרַח אֶחָד מִן הַמְפֹרֶשֶׁת לַסְּתוּמָה. וְלֹא יָדַע זֶה שֶׁפָּרַח אִם הָיָה עוֹלָה אוֹ חַטָּאת. יָמוּתוּ כָּל הָעוֹפוֹת שֶׁבַּסְּתוּמָה. שֶׁאִם נִתְעָרְבָה בָּהֶן עוֹלָה כָּל הַחַטָּאוֹת שֶׁבָּהּ פְּסוּלוֹת. וְאִם חַטָּאת נִתְעָרְבָה כָּל הָעוֹלוֹת שֶׁבָּהּ פְּסוּלוֹת לְפִיכָךְ יָמוּתוּ כֻּלָּן:","חַטָּאת מִכָּאן וְעוֹלָה מִכָּאן וּסְתוּמָה בָּאֶמְצַע. פָּרַח מִן הָאֶמְצַע לַצְּדָדִין אֵילָךְ אֶחָד וְאֵילָךְ אֶחָד. לֹא הִפְסִיד כְּלוּם. אֶלָּא יֹאמַר זֶה שֶׁהָלַךְ אֵצֶל הַחַטָּאוֹת חַטָּאת וְזֶה שֶׁהָלַךְ אֵצֶל הָעוֹלוֹת עוֹלָה. חָזַר אַחַר שֶׁנִּתְעָרְבוּ וּפָרַח אֶחָד מִכָּאן וְאֶחָד מִכָּאן לָאֶמְצַע. הַשְּׁנַיִם הָאֶמְצָעִיִּים יָמוּתוּ שֶׁהֲרֵי הֵן חַטָּאת וְעוֹלָה מְעֹרָבִין. וְהַצְּדָדִין אֵלּוּ יִקָּרְבוּ חַטָּאת וְאֵלּוּ יִקָּרְבוּ עוֹלָה כְּשֶׁהָיוּ. פָּרַח מִן הָאֶמְצָעִית לַצְּדָדִין כֻּלָּן יָמוּתוּ. שֶׁמָּא עוֹלָה נִתְעָרְבָה בַּחַטָּאוֹת וְחַטָּאת בָּעוֹלוֹת:"],"Mishneh Torah, Sacrificial Procedure 2":["הַיַּיִן וְהַסּלֶת שֶׁמְּבִיאִין עִם הַקָּרְבָּן הֵם הַנִּקְרָאִין נְסָכִים. וְהַסּלֶת לְבַדָּהּ נִקְרֵאת מִנְחַת נְסָכִים. וּמִנְחַת נְסָכִים אֵינָהּ טְעוּנָה לֹא תְּנוּפָה וְלֹא הַגָּשָׁה וְלֹא לְבוֹנָה. אֲבָל טְעוּנָה מֶלַח. וְכֻלָּהּ נִשְׂרֶפֶת עַל מִזְבֵּחַ הַחִיצוֹן. וְיִתְנַסֵּךְ הַיַּיִן עַל הַמִּזְבֵּחַ. וְאֵין נוֹתְנִין אוֹתוֹ עַל הָאֵשׁ אֶלָּא מַגְבִּיהַּ יָדוֹ וְיוֹצֵק עַל הַיְסוֹד וְהוּא יוֹרֵד לַשִּׁיתִין:","אֵין טָעוּן נְסָכִין אֶלָּא עוֹלַת בְּהֵמָה וּשְׁלָמִים בִּלְבַד בֵּין הָיוּ קָרְבַּן צִבּוּר אוֹ קָרְבַּן יָחִיד אוֹ כֶּבֶשׂ יוֹלֶדֶת וְאֵילוֹ שֶׁל כֹּהֵן גָּדוֹל הוֹאִיל וְהֵן עוֹלוֹת טְעוּנִים נְסָכִים. אֲבָל הָעוֹף וְהָאֲשָׁמוֹת וְהַחַטָּאוֹת אֵין מְבִיאִין עִמָּהֶם נְסָכִים. חוּץ מֵחַטַּאת מְצֹרָע וַאֲשָׁמוֹ שֶׁנִּתְפָּרְשׁוּ נִסְכֵּיהֶם בַּתּוֹרָה:","וּמִנַּיִן שֶׁאֵין מְבִיאִין נְסָכִים עִם הַחַטָּאת וְהָאָשָׁם שֶׁנֶּאֱמַר (במדבר טו ג) \"לְפַלֵּא נֶדֶר אוֹ נְדָבָה\" דָּבָר הַבָּא בְּנֵדֶר וּנְדָבָה יָצְאוּ חַטָּאת וְאָשָׁם וּבְכוֹר וּמַעֲשֵׂר וּפֶסַח הוֹאִיל וְאֵינָן בָּאִין בְּנֵדֶר וּנְדָבָה אֵין טְעוּנִין נְסָכִים. וּמִנַּיִן לְהָבִיא שַׁלְמֵי חֲגִיגָה וְעוֹלַת רְאִיָּה לִנְסָכִים שֶׁנֶּאֱמַר (במדבר טו ג) \"אוֹ בְּמֹעֲדֵיכֶם\":","כַּמָּה הוּא שִׁעוּר נְסָכִים. נִסְכֵּי כֶּבֶשׂ אוֹ כַּבְשָׂה עִשָּׂרוֹן סלֶת בָּלוּל בִּרְבִיעִית הַהִין שֶׁמֶן וְיַיִן לַנֶּסֶךְ רְבִיעִית הַהִין. וְכֵן נִסְכֵּי הָעֵז בֵּין קָטָן בֵּין גָּדוֹל בֵּין זָכָר בֵּין נְקֵבָה אוֹ נִסְכֵּי רָחֵל אַף עַל פִּי שֶׁהִיא גְּדוֹלָה. אֲבָל נִסְכֵּי אַיִל הֵן שְׁנֵי עֶשְׂרוֹנִים סלֶת בָּלוּל בִּשְׁלִישִׁית הַהִין שֶׁמֶן וְיַיִן לַנֶּסֶךְ שְׁלִישִׁית הַהִין. וְנִסְכֵּי הַפָּר אוֹ הָעֵגֶל בֵּין זְכָרִים בֵּין נְקֵבוֹת שְׁלֹשָׁה עֶשְׂרוֹנִים סלֶת בָּלוּל בַּחֲצִי הַהִין שֶׁמֶן וְיַיִן לַנֶּסֶךְ חֲצִי הַהִין:","אֵלּוּ הֵן הַנְּסָכִים בֵּין לָעוֹלָה בֵּין לַשְּׁלָמִים כַּשִּׁעוּר הַזֶּה לְכָל אֶחָד וְאֶחָד שֶׁנֶּאֱמַר (במדבר טו יב) \"כַּמִּסְפָּר אֲשֶׁר תַּעֲשׂוּ כָּכָה תַּעֲשׂוּ לָאֶחָד כְּמִסְפָּרָם\". אֵין מוֹסִיפִין עַל הַשִּׁעוּרִין הָאֵלּוּ וְאֵין גּוֹרְעִין מֵהֶן. וְאִם גָּרַע אוֹ הוֹסִיף כָּל שֶׁהוּא פָּסוּל. חוּץ מִכֶּבֶשׂ הָעוֹלָה שֶׁמַּקְרִיבִין בְּיוֹם הֲנָפַת הָעֹמֶר שֶׁהַנְּסָכִים שֶׁלּוֹ שְׁנֵי עֶשְׂרוֹנִים בָּלוּל בִּשְׁלִישִׁית הַהִין שֶׁמֶן. אַף עַל פִּי שֶׁנִּכְפְּלָה סָלְתּוֹ לֹא נִכְפְּלוּ יֵינוֹ [וְשַׁמְנוֹ] אֶלָּא יַיִן לַנֶּסֶךְ רְבִיעִית הַהִין:","הַמְצֹרָע מֵבִיא עִם שְׁלֹשָׁה כְּבָשִׂים שֶׁלּוֹ שֶׁהֵן חַטָּאת וְאָשָׁם וְעוֹלָה שְׁלֹשָׁה עֶשְׂרוֹנִים. וּמִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁהֵן בָּאִין בִּכְלַל הַזְּבָחִים שֶׁלּוֹ עִשָּׂרוֹן עִם כָּל כֶּבֶשׂ בָּלוּל בִּרְבִיעִית הַהִין שֶׁמֶן. וּרְבִיעִית יַיִן עִם כָּל עִשָּׂרוֹן מִשְּׁלָשְׁתָּן כִּשְׁאָר נִסְכֵּי הַכְּבָשִׂים. וְהַמַּקְרִיב אֶת הַפִּלְגָּס מֵבִיא עִמּוֹ נִסְכֵּי אַיִל וְלֹא עוֹלֶה לוֹ זִבְחוֹ:","הַהִין הוּא שְׁנֵים עָשָׂר לוֹג. וּכְבָר הוֹדַעְנוּ שִׁעוּר הַלּוֹג עִם מִדּוֹת אֲחֵרוֹת בְּהִלְכוֹת עֵרוּבִין. וְהָעִשָּׂרוֹן הוּא הָעֹמֶר שֶׁהוּא שִׁעוּר חַלָּה וּכְבָר בֵּאַרְנוּ שִׁעוּרוֹ בְּעִנְיַן חַלָּה:","כְּשֶׁמּוֹדְדִין הַנְּסָכִים אוֹ הַמְּנָחוֹת בֵּין מִנְחַת יָחִיד בֵּין מִנְחַת צִבּוּר אֵין מוֹדְדִין אוֹתוֹ בְּמִדָּה שֶׁל שְׁלֹשָׁה עֶשְׂרוֹנִים לַפָּר אוֹ שֶׁל שְׁנַיִם לָאַיִל אֶלָּא מוֹדֵד הַכּל בְּעִשָּׂרוֹן אֶחָד שֶׁהָיָה בַּמִּקְדָּשׁ. וְכֵן הַשֶּׁמֶן שֶׁל נְסָכִים מוֹדְדִין אוֹתוֹ בְּמִדָּתוֹ שֶׁבַּמִּקְדָּשׁ. וְשֶׁמֶן שֶׁל מִנְחוֹת הַיָּחִיד בְּלוֹג שֶׁבַּמִּקְדָּשׁ. כְּמִנְיַן הָעֶשְׂרוֹנוֹת כָּךְ מִנְיַן הַלּוֹגִין:","בֵּירוּצֵי הַמִּדּוֹת שֶׁל סלֶת חֹל שֶׁאֵין גַּב הָעִשָּׂרוֹן קֹדֶשׁ. וּבֵירוּצֵי הַיַּיִן וְהַשֶּׁמֶן קֹדֶשׁ לְפִי שֶׁהוּא יוֹרֵד עַל גַּב הַכְּלִי. וּכְלֵי הַלַּח נִמְשְׁחוּ מִבִּפְנִים וּמִבַּחוּץ. וְלָמָּה יִתְקַדְּשׁוּ הַבֵּירוּצִין אַף עַל פִּי שֶׁאֵין כַּוָּנַת הַמּוֹדֵד אֶלָּא לְמַה שֶּׁבַּכְּלִי בִּלְבַד כְּדֵי שֶׁלֹּא יֹאמְרוּ מוֹצִיאִין מִכְּלֵי שָׁרֵת לְחל:","מַה הָיוּ עוֹשִׂין בַּבֵּירוּצִין. אִם יֵשׁ שָׁם זֶבַח אַחֵר יַקְרִיבוּ עִמּוֹ. וְאִם לָנוּ יִפָּסְלוּ בְּלִינָה. וְאִם לָאו מְקַיְּצִין בָּהֶן הַמִּזְבֵּחַ:","כֵּיצַד לוֹקְחִין בָּהֶם עוֹלוֹת. הַבָּשָׂר לַשֵּׁם וְהָעוֹרוֹת לַכֹּהֲנִים:","הַסּלֶת עִם הַשֶּׁמֶן שֶׁל נְסָכִים אֵינָן מְעַכְּבִין אֶת הַיַּיִן וְלֹא הַיַּיִן מְעַכְּבָן. וְלֹא הַנְּסָכִים מְעַכְּבִין אֶת הַזֶּבַח אֶלָּא מֵבִיא אָדָם קָרְבָּנוֹ הַיּוֹם וּנְסָכָיו אַחַר עֲשָׂרָה יָמִים אֶחָד יָחִיד וְאֶחָד צִבּוּר. וְהוּא שֶׁלֹּא קָדְשׁוּ הַנְּסָכִים בִּכְלִי שָׁרֵת אֲבָל אִם נְתָנָן לִכְלִי שָׁרֵת אִם לָנוּ יִפָּסְלוּ בְּלִינָה:","אֵין מְבִיאִין נְסָכִים אֶלָּא מִן הַחֻלִּין. לֹא יְבִיאֵם לֹא מִן הַתְּרוּמָה וְלֹא מִמַּעֲשֵׂר שֵׁנִי וְלֹא מִן הַבִּכּוּרִים. וַאֲפִלּוּ תּוֹדָה שֶׁמֵּבִיא לַחְמָהּ מִן הַמַּעֲשֵׂר לֹא יְבִיאוֹ נְסָכִים אֶלָּא מִן הַחֻלִּין:","כָּל שִׁעוּרֵי הַנְּסָכִים הָאֵמוּרִין בְּסֵפֶר יְחֶזְקֵאל וּמִנְיַן אוֹתָן הַקָּרְבָּנוֹת וְסִדְרֵי הָעֲבוֹדָה הַכְּתוּבִים שָׁם כֻּלָּם מִלּוּאִים הֵן וְאֵין נוֹהֲגִין לְדוֹרוֹת אֶלָּא הַנָּבִיא צִוָּה וּפֵרֵשׁ כֵּיצַד יִהְיוּ מַקְרִיבִין הַמִּלּוּאִין עִם חֲנֻכַּת הַמִּזְבֵּחַ בִּימֵי הַמֶּלֶךְ הַמָּשִׁיחַ כְּשֶׁיִּבָּנֶה בַּיִת שְׁלִישִׁי:","וּכְשֵׁם שֶׁהִקְרִיבוּ הַנְּשִׂיאִים בַּחֲנֻכַּת הַמִּזְבֵּחַ דְּבָרִים שֶׁאֵין כְּמוֹתָן לְדוֹרוֹת וְהִקְרִיבוּ בְּשַׁבָּת כָּךְ הַנָּשִׂיא מַקְרִיב חֲנֻכָּתוֹ בְּשַׁבָּת לֶעָתִיד כַּאֲשֶׁר מְפֹרָשׁ שָׁם. וְכֵן קָרְבָּנוֹת שֶׁהִקְרִיבוּ בִּימֵי עֶזְרָא הַבָּאִים מֵהַשְּׁבִי מִלּוּאִים הָיוּ וְאֵינָן נוֹהֲגִין לְדוֹרוֹת. אֲבָל דְּבָרִים הַנּוֹהֲגִים לְדוֹרוֹת הֵם דִּבְרֵי תּוֹרָה שֶׁפֵּרַשְׁנוּ כְּמוֹ שֶׁהֶעֱתִיקוּם מִפִּי משֶׁה רַבֵּנוּ אֵין לְהוֹסִיף עֲלֵיהֶם וְאֵין לִגְרֹעַ:"],"Mishneh Torah, Sales 13":["הַמַּחְלִיף כֵּלִים בְּכֵלִים אוֹ בְּהֵמָה בִּבְהֵמָה אֲפִלּוּ מַחַט בְּשִׁירַיִם אוֹ טָלֶה בְּסוּס אֵין לוֹ הוֹנָיָה. שֶׁזֶּה רוֹצֶה בְּמַחַט יוֹתֵר מִן הַשִּׁירַיִם. אֲבָל הַמַּחְלִיף פֵּרוֹת בְּפֵרוֹת בֵּין שֶׁשָּׁמוּ אוֹתָם קֹדֶם הַמְּכִירָה בֵּין שֶׁשָּׁמוּ אוֹתָם אַחַר מְכִירָה יֵשׁ לָהֶן הוֹנָיָה:","הַלּוֹקֵחַ בְּדָמִים אַכְסָרָה כְּגוֹן שֶׁחָפַן מִמָּעוֹת וְאָמַר לוֹ מְכֹר לִי פָּרָתְךָ בְּאֵלּוּ. אַף עַל פִּי שֶׁקּוֹנֶה בַּחֲלִיפִין קָנָה וּמַחֲזִיר הוֹנָאָה כְּמוֹ שֶׁבֵּאַרְנוּ. וְהוּא הַדִּין לְלוֹקֵחַ פֵּרוֹת אַכְסָרָה בְּסֶלַע אוֹ בִּשְׁתַּיִם שֶׁקָּנָה וּמַחֲזִיר אוֹנָאָה. בַּעַל הַבַּיִת שֶׁמָּכַר כְּלֵי תַּשְׁמִישׁוֹ אֵין לוֹ הוֹנָיָה. שֶׁאִלּוּלֵי לֹא הִרְבּוּ לוֹ הַדָּמִים לֹא הָיָה מוֹכֵר לוֹ כְּלֵי תַּשְׁמִישׁוֹ:","הָאוֹמֵר לַחֲבֵרוֹ עַל מְנָת שֶׁאֵין לְךָ עָלַי אוֹנָיָה יֵשׁ לוֹ עָלָיו הוֹנָיָה. בַּמֶּה דְּבָרִים אֲמוּרִים בִּסְתָם שֶׁאֵין יוֹדֵעַ כַּמָּה הוֹנָיָה יֵשׁ בּוֹ כְּדֵי שֶׁיִּמְחל. וְאֵין צָרִיךְ לוֹמַר אִם אָמַר לוֹ עַל מְנָת שֶׁאֵין בּוֹ הוֹנָיָה שֶׁהֲרֵי יֵשׁ בּוֹ. אֲבָל בִּמְפָרֵשׁ אֵין לוֹ הוֹנָיָה שֶׁכָּל תְּנַאי שֶׁבַּמָּמוֹן קַיָּם:","כֵּיצַד. מוֹכֵר שֶׁאָמַר לַלּוֹקֵחַ חֵפֶץ זֶה שֶׁאֲנִי נוֹתֵן בְּמָאתַיִם יוֹדֵעַ אֲנִי שֶׁאֵינוֹ שָׁוֶה אֶלָּא מָנֶה עַל מְנָת שֶׁאֵין לְךָ הוֹנָיָה אֲנִי מוֹכֵר לְךָ אֵין לוֹ עָלָיו הוֹנָיָה. וְכֵן לוֹקֵחַ שֶׁאָמַר לַמּוֹכֵר חֵפֶץ זֶה שֶׁאֲנִי לוֹקֵחַ מִמְּךָ בְּמָנֶה יוֹדֵעַ אֲנִי שֶׁשָּׁוֶה מָאתַיִם עַל מְנָת שֶׁאֵין לְךָ עָלַי הוֹנָיָה אֲנִי לוֹקֵחַ מִמְּךָ. אֵין לוֹ עָלָיו הוֹנָיָה:","הַנּוֹשֵׂא וְהַנּוֹתֵן בֶּאֱמוּנָה אֵין לוֹ עָלָיו אוֹנָיָה. כֵּיצַד. חֵפֶץ זֶה בְּכָךְ וְכָךְ לְקַחְתִּיו כָּךְ וְכָךְ אֲנִי מִשְׂתַּכֵּר בּוֹ. אֵין לוֹ עָלָיו הוֹנָיָה:","והַנּוֹשֵׂא וְהַנּוֹתֵן בֶּאֱמוּנָה אִם לָקַח כֵּלִים רַבִּים אוֹ בְּגָדִים בְּמִמְכָּר אֶחָד. לֹא יַחְשֹׁב אֶת הָרַע בֶּאֱמוּנָה וְאֶת הַיָּפֶה בְּשָׁוֶה אֶלָּא זֶה וְזֶה בֶּאֱמוּנָה אוֹ זֶה וְזֶה בְּשָׁוִין. וְיֵשׁ לוֹ לְהַעֲלוֹת עַל הַמִּקָּח שְׂכַר הַכַּתָּף. וּשְׂכַר הַחַמָּר. וּשְׂכַר פֻּנְדָּק. אֲבָל שְׂכַר עַצְמוֹ מִפְּנֵי שֶׁהוּא כְּפוֹעֵל אֵינוֹ מוֹסִיף אוֹתוֹ עַל הַמִּקָּח. אֶלָּא מְפָרֵשׁ וְאוֹמֵר לוֹ כָּךְ וְכָךְ אֲנִי מִשְׂתַּכֵּר:","הָעַכּוּ\"ם אֵין לוֹ הוֹנָיָה שֶׁנֶּאֱמַר (ויקרא כה יד) \"אִישׁ אֶת אָחִיו\". וְעַכּוּ\"ם שֶׁהוֹנָה אֶת יִשְׂרָאֵל מַחְזִיר הוֹנָיָה בְּדִינִין שֶׁלָּנוּ. לֹא יִהְיֶה זֶה חָמוּר מִיִּשְׂרָאֵל:","אֵלּוּ דְּבָרִים שֶׁאֵין לָהֶם הוֹנָיָה. הַקַּרְקָעוֹת וְהָעֲבָדִים וְהַשְּׁטָרוֹת וְהַהֶקְדֵּשׁוֹת. אֲפִלּוּ מָכַר שְׁוֵה אֶלֶף בְּדִינָר אוֹ שְׁוֵה דִּינָר בְּאֶלֶף אֵין בָּהֶן הוֹנָיָה. שֶׁנֶּאֱמַר (ויקרא כה יד) \"אוֹ קָנֹה מִיַּד עֲמִיתֶךָ\". דָּבָר הַנִּקְנֶה מִיָּד לְיָד. יָצְאוּ הַקַּרְקָעוֹת וְיָצְאוּ עֲבָדִים שֶׁהֻקְּשׁוּ לְקַרְקָעוֹת. וְיָצְאוּ שְׁטָרוֹת שֶׁאֵין גּוּפָן קָנוּי אֶלָּא לִרְאָיָה שֶׁבָּהֶן. עֲמִיתְךָ וְלֹא הֶקְדֵּשׁ:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּמוֹכֵר נִכְסֵי עַצְמוֹ. אֲבָל הַשָּׁלִיחַ שֶׁטָּעָה בְּכָל שֶׁהוּא בֵּין בְּמִטַּלְטְלִין בֵּין בְּקַרְקָעוֹת חוֹזֵר. וְנִרְאֶה לִי שֶׁכֵּן הַדִּין בְּאַפּוֹטְרוֹפּוֹס שֶׁטָּעָה בְּכָל שֶׁהוּא. בֵּין בְּמִטַּלְטְלִין בֵּין בְּקַרְקָעוֹת חוֹזֵר. וְאֵינוֹ דּוֹמֶה לְבֵית דִּין מִפְּנֵי שֶׁהוּא יָחִיד:","בֵּית דִּין שֶׁמָּכְרוּ נִכְסֵי יְתוֹמִים וְטָעוּ בֵּין בְּקַרְקָעוֹת בֵּין בְּמִטַּלְטְלִין. אִם טָעוּ בְּפָחוֹת מִשְּׁתוּת הֲרֵי זוֹ מְחִילָה כְּהֶדְיוֹט. טָעוּ בִּשְׁתוּת בָּטֵל הַמִּקָּח. וְאִם רָצוּ שֶׁלֹּא לְבַטֵּל הַמִּמְכָּר וְיַחְזִירוּ הַהוֹנָיָה מַחֲזִירִין. לֹא יִהְיֶה כֹּחַ הֶדְיוֹט חָמוּר מֵהֶן:","נִרְאֶה לִי שֶׁבֵּית דִּין שֶׁמָּכְרוּ קַרְקַע אוֹ עֲבָדִים שֶׁל יְתוֹמִים שְׁוֵה מָנֶה בְּמָאתַיִם. אֵין הַלּוֹקֵחַ יָכוֹל לַחְזֹר בָּהֶן. לֹא יִהְיֶה כֹּחַ הֶדְיוֹט חָמוּר מִכֹּחַ הַיְתוֹמִים. וְכֵן הַדִּין בְּאַפּוֹטְרוֹפּוֹס שֶׁמָּכַר קַרְקַע וַעֲבָדִים שֶׁאֵין הַלּוֹקֵחַ יָכוֹל לַחְזֹר בְּהוֹנָיָה כְּדִין הַהֶדְיוֹט:","הָאַחִין וְהַשֻּׁתָּפִין שֶׁחָלְקוּ הַמִּטַּלְטְלִין הֲרֵי הֵן כְּלָקוֹחוֹת. פָּחוֹת מִשְּׁתוּת נִקְנֶה מִקָּח וְאֵין מַחְזִיר כְּלוּם. יֶתֶר עַל שְׁתוּת בָּטֵל מִקָּח. שְׁתוּת קָנָה וּמַחֲזִיר אוֹנָאָה. וְאִם הִתְנוּ בֵּינֵיהֶם שֶׁיַּחְלְקוּ בְּשׁוּם הַדַּיָּנִין וְטָעוּ בִּשְׁתוּת בָּטְלָה חֲלוּקָה. שֶׁהַדַּיָּנִין שֶׁשָּׁמוּ וּפָחֲתוּ שְׁתוּת אוֹ הוֹתִירוּ שְׁתוּת מִכְרָן בָּטֵל:","הַבְּהֵמָה וְהַמַּרְגָּלִית וְהַסַּיִף. וְסֵפֶר תּוֹרָה הֲרֵי הֵן כִּשְׁאָר מִטַּלְטְלִין וְיֵשׁ בָּהֶן הוֹנָיָה. אֵין לְךָ דָּבָר שֶׁאֵין בּוֹ הוֹנָיָה חוּץ מֵאַרְבָּעָה דְּבָרִים שֶׁמָּנוּ חֲכָמִים. וְהוּא שֶׁיִּהְיֶה מוֹכֵר קוֹנֶה בְּנִכְסֵי עַצְמוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","כְּשֵׁם שֶׁאֵין לְקַרְקְעוֹת הוֹנָיָה כָּךְ שְׂכִירוּת קַרְקַע אֵין לוֹ הוֹנָיָה. אֲפִלּוּ שָׂכַר טְרַקְלִין גָּדוֹל בְּדִינָר בְּשָׁנָה אוֹ רֶפֶת קְטַנָּה בְּדִינָר בְּכָל יוֹם אֵין לוֹ הוֹנָיָה:","הַשּׂוֹכֵר אֶת הַפּוֹעֵל לַעֲשׂוֹת עִמּוֹ בֵּין בְּקַרְקַע בֵּין בְּמִטַּלְטְלִין אֵין לוֹ הוֹנָיָה. מִפְּנֵי שֶׁהוּא כְּקוֹנֶה אוֹתוֹ לִזְמַן. וַעֲבָדִים אֵין בָּהֶם הוֹנָיָה:","שְׂכָרוֹ לִזְרֹעַ לוֹ קַרְקַע וְאָמַר זָרַעְתִּי בָּהּ זְרִיעָה הָרָאוּי בָּהּ וּבָאוּ עֵדִים שֶׁזָּרַע בָּהּ פָּחוֹת מִן הָרָאוּי לָהּ. הֲרֵי זֶה סָפֵק אִם יֵשׁ לוֹ הוֹנָיָה מִפְּנֵי הַזֶּרַע אוֹ אֵין לוֹ הוֹנָיָה מִפְּנֵי הַקַּרְקַע. לְפִיכָךְ אֵין מוֹצִיאִין מִיַּד נִתְבָּע. וְכֵן אֵין מַשְׁבִּיעִין אוֹתוֹ אֶלָּא שְׁבוּעַת הֶסֵּת מִפְּנֵי צַד הַקַּרְקַע שֶׁיֵּשׁ כָּאן:","הַשּׂוֹכֵר אֶת הַכֵּלִים אוֹ אֶת הַבְּהֵמָה יֵשׁ לָהֶם אוֹנָיָה. שֶׁהַשְּׂכִירוּת מְכִירָה בַּת יוֹמָהּ הִיא. וְאִם יֵשׁ בָּהּ הוֹנָיָה שְׁתוּת אוֹ יוֹתֵר. בֵּין שֶׁנִּתְאַנָּה שׂוֹכֵר בֵּין שֶׁנִּתְאַנָּה מַשְׂכִּיר. הֲרֵי זֶה מַחְזִיר הוֹנָיָה וַאֲפִלּוּ לְאַחַר זְמַן מְרֻבֶּה:","נִרְאֶה לִי שֶׁהַקַּבְּלָן יֵשׁ לוֹ הוֹנָאָה. כֵּיצַד. כְּגוֹן שֶׁקִּבֵּל עָלָיו לֶאֱרֹג בֶּגֶד זֶה בַּעֲשָׂרָה זוּזִים. אוֹ לִתְפֹּר חָלוּק זֶה בִּשְׁנֵי זוּזִים. הֲרֵי זֶה יֵשׁ לוֹ הוֹנָיָה. וְכָל אֶחָד מִשְּׁנֵיהֶם בֵּין קַבְּלָן בֵּין בַּעַל הַבֶּגֶד חוֹזֵר לְעוֹלָם כְּמוֹכֵר:"],"Mishneh Torah, Sales 24":["הַמּוֹכֵר שְׁלֹשָׁה אִילָנוֹת בְּתוֹךְ שָׂדהוּ וַאֲפִלּוּ הָיוּ שָׁלֹשׁ נְטִיעוֹת קְטַנּוֹת אוֹ שְׁלֹשָׁה בַּדֵּי אִילָן. הֲרֵי יֵשׁ לַלּוֹקֵחַ קַרְקַע הָרָאוּי לָהֶם. וַאֲפִלּוּ יָבְשׁוּ הָאִילָנוֹת אוֹ נִקְצְצוּ יֵשׁ לוֹ קַרְקַע הָרָאוּי לָהֶם וְקָנָה כָּל הָאִילָנוֹת שֶׁבֵּינֵיהֶם:","וְכַמָּה הִיא הַקַּרְקַע הָרָאוּי לָהֶם. תַּחְתֵּיהֶם וּבֵינֵיהֶם וְחוּצָה לָהֶם כִּמְלֹא הָאוֹרֶה וְסַלּוֹ. וְזֶה הַמָּקוֹם שֶׁהוּא מְלֹא הָאוֹרֶה וְסַלּוֹ אֵין אֶחָד מִשְּׁנֵיהֶם יָכוֹל לְזַרְעוֹ אֶלָּא מִדַּעַת חֲבֵרוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ שְׁלֹשָׁה הָאִילָנוֹת עוֹמְדִין כְּמוֹ שְׁלֹשָׁה פִּטְפּוּטֵי כִּירָה שֶׁשּׁוֹפְתִין עֲלֵיהֶן אֶת הַקְּדֵרָה. שֶׁהֲרֵי הֵן שְׁנַיִם זֶה כְּנֶגֶד זֶה וְהַשְּׁלִישִׁי מְכֻוָּן בֵּינֵיהֶן וּמְרֻחָק מֵהֶן. וְהוּא שֶׁיִּהְיוּ בֵּין כָּל אִילָן וְאִילָן מֵאַרְבַּע אַמּוֹת וְעַד שֵׁשׁ עֶשְׂרֵה:","וּמֵהֵיכָן הוּא מוֹדֵד מִן הָעִקָּר הָרָחָב שֶׁל אִילָנוֹת. אֲבָל אִם לֹא הָיוּ עוֹמְדִין כַּצּוּרָה הַזֹּאת. אוֹ שֶׁהָיוּ מְקֹרָבִים פָּחוֹת מֵאַרְבַּע אַמּוֹת אוֹ מְרֻחָקִין יוֹתֵר מִשֵּׁשׁ עֶשְׂרֵה אַמָּה. אוֹ שֶׁלְּקָחָן זֶה אַחַר זֶה. אוֹ שֶׁמָּכַר לוֹ שְׁנַיִם בְּתוֹךְ שָׂדֵהוּ וְאֶחָד עַל הַמֵּצַר. אוֹ שְׁנַיִם בְּתוֹךְ שֶׁלּוֹ וְאֶחָד בְּתוֹךְ שֶׁל חֲבֵרוֹ. אוֹ שֶׁהִפְסִיק בּוֹר אוֹ אַמַּת הַמַּיִם אוֹ רְשׁוּת הָרַבִּים בֵּינֵיהֶם. הֲרֵי זֶה אֵין לוֹ קַרְקַע. לְפִיכָךְ לֹא קָנָה הָאִילָנוֹת שֶׁבֵּינֵיהֶם. וְאִם יָבַשׁ הָאִילָן אוֹ נִקְצַץ יֵלֵךְ לוֹ:","כָּל מִי שֶׁקּוֹנֶה שְׁלֹשָׁה אִילָנוֹת וְיֵשׁ לוֹ קַרְקַע. אִם הִגְדִּילוּ וְהוֹצִיאוּ חֹטֶר יָקֹץ כְּדֵי שֶׁלֹּא יְמַעֵט הַדֶּרֶךְ עַל בַּעַל הַשָּׂדֶה. וְכָל הַשָּׂרִיגִין וְהָאֲמִירִים הַיּוֹצְאִים מֵהֶם וַאֲפִלּוּ מִן הַשָּׁרָשִׁים הֲרֵי הֵן שֶׁל בַּעַל הָאִילָנוֹת שֶׁהֲרֵי יֵשׁ לוֹ קַרְקַע:","הַקּוֹנֶה שְׁנֵי אִילָנוֹת בְּתוֹךְ שְׂדֵה חֲבֵרוֹ אֵין לוֹ קַרְקַע. לְפִיכָךְ אִם מֵת הָאִילָן אוֹ נִקְצַץ אֵין לוֹ כְּלוּם. הִגְדִּילוּ שְׁנֵי הָאִילָנוֹת וְהוֹצִיאוּ שָׂרִיגִים וַאֲמִירִים יָקֹץ שֶׁמָּא יִצְמְחוּ בָּאָרֶץ וְיֹאמַר לַמּוֹכֵר שְׁלֹשָׁה אִילָנוֹת מָכַרְתָּ לִי וְיֵשׁ לִי קַרְקַע:","כָּל הָעֵצִים שֶׁקּוֹצֵץ בַּעַל שְׁנֵי הָאִילָנוֹת מֵהֶן. הָעוֹלֶה מִן הַגְּזָעִים וְהוּא הָרוֹאֶה פְּנֵי הַחַמָּה הֲרֵי הוּא שֶׁל בַּעַל הָאִילָנוֹת. וְהָעוֹלֶה מִן הַשָּׁרָשִׁים וְהוּא שֶׁאֵינוֹ רוֹאֶה פְּנֵי הַחַמָּה הֲרֵי הוּא שֶׁל בַּעַל הַשָּׂדֶה. וּבִדְקָלִים אֵין לְבַעַל הַדֶּקֶל מִן הָעוֹלֶה כְּלוּם לְפִי שֶׁאֵין לוֹ גֶּזַע:","הַמּוֹכֵר קַרְקַע וְשִׁיֵּר אִילָנוֹת הֲרֵי יֵשׁ לוֹ חֲצִי הַקַּרְקַע כֻּלָּהּ שֶׁאִלּוּ לֹא שִׁיֵּר בַּקַּרְקַע הֲרֵי אוֹמֵר לוֹ הַלּוֹקֵחַ עֲקֹר אִילָנְךָ. וְכֵן אִם שִׁיֵּר שְׁנֵי הָאִילָנוֹת בִּלְבַד יֵשׁ לוֹ קַרְקַע הָרָאוּי לָהֶם. שֶׁאִלּוּ לֹא שִׁיֵּר הַקַּרְקַע הָיָה הַלּוֹקֵחַ אוֹמֵר לוֹ עֲקֹר אִילָנְךָ וְלֵךְ:","הַמּוֹכֵר אֶת הָאִילָנוֹת וְשִׁיֵּר אֶת הַקַּרְקַע. יֵשׁ לְבַעַל הָאִילָנוֹת קַרְקַע הָרָאוּי לָהֶם כְּמוֹ שֶׁבֵּאַרְנוּ. מָכַר אֶת הַקַּרְקַע לְאֶחָד וְאֶת הָאִילָנוֹת לְאַחֵר וְהֶחֱזִיק זֶה בָּאִילָנוֹת וְהֶחֱזִיק זֶה בַּקַּרְקַע. זֶה קָנָה הָאִילָנוֹת עִם חֲצִי הַקַּרְקַע וְזֶה שֶׁהֶחְזִיק בַּקַּרְקַע קָנָה חֲצִי הַקַּרְקַע בִּלְבַד:","הָאַחִין שֶׁחָלְקוּ אֶחָד נָטַל פַּרְדֵּס וְאֶחָד נָטַל שְׂדֵה לָבָן. יֵשׁ לְבַעַל הַפַּרְדֵּס אַרְבַּע אַמּוֹת בְּתוֹךְ שְׂדֵה לָבָן סְמוּכוֹת לְסוֹף הָאִילָנוֹת שֶׁל פַּרְדֵּס שֶׁעַל מְנָת כֵּן חָלְקוּ. וְאֵין צָרִיךְ לְפָרֵשׁ דָּבָר זֶה מִפְּנֵי שֶׁהוּא דָּבָר יָדוּעַ:","הַמּוֹכֵר שָׂדֶה לַחֲבֵרוֹ וְהָיוּ בָּהּ דְּקָלִים וְאָמַר לוֹ חוּץ מִדֶּקֶל פְּלוֹנִי. אִם דֶּקֶל טוֹב וּמְשֻׁבָּח הוּא אוֹתוֹ הַדֶּקֶל לְבַדּוֹ הוּא שֶׁשִּׁיֵּר וְהַשְּׁאָר לַלּוֹקֵחַ. וְאִם דֶּקֶל רַע הוּא שֶׁשִּׁיֵּר כָּל שֶׁכֵּן שֶׁשִּׁיֵּר הַשְּׁאָר] לֹא קָנָה מִן הַדְּקָלִים כְּלוּם:","מָכַר לוֹ שָׂדֶה וְאָמַר לוֹ חוּץ מִן הָאִילָנוֹת. אִם יֵשׁ בּוֹ דְּקָלִים בִּלְבַד שִׁיֵּר הַדְּקָלִים. וְאִם יֵשׁ בּוֹ גְּפָנִים בִּלְבַד שִׁיֵּר הַגְּפָנִים. וְכֵן שְׁאָר הָאִילָנוֹת. הָיוּ בָּהּ גְּפָנִים וּדְקָלִים לֹא שִׁיֵּר אֶלָּא הַגְּפָנִים. אִילָנוֹת וּגְפָנִים לֹא שִׁיֵּר אֶלָּא אִילָנוֹת. וְכֵן אִילָנוֹת וּדְקָלִים שִׁיֵּר אִילָנוֹת שֶׁהַמּוֹכֵר בְּעַיִן יָפָה הוּא מוֹכֵר. וְאִם הַדְּקָלִים שִׁיֵּר לֹא שִׁיֵּר אֶלָּא כָּל דֶּקֶל גָּבוֹהַּ שֶׁעוֹלִים לוֹ בַּחֶבֶל וְהַשְּׁאָר הֲרֵי הוּא שֶׁל לוֹקֵחַ. וְאִם שְׁאָר הָאִילָנוֹת הוּא שֶׁשִּׁיֵּר לֹא שִׁיֵּר בָּהֶם אֶלָּא כָּל שֶׁאֵין הָעל כּוֹבְשׁוֹ. וְכָל שֶׁהָעל כּוֹבְשׁוֹ הֲרֵי הוּא שֶׁל לוֹקֵחַ וּבִכְלַל הַשָּׂדֶה נֶחְשָׁב:","הָאוֹמֵר לַחֲבֵרוֹ קַרְקַע וּדְקָלִים אֲנִי מוֹכֵר לְךָ. אֲפִלּוּ לֹא הָיוּ לוֹ דְּקָלִים אִם רָצָה לִקְנוֹת לוֹ שְׁנֵי דְּקָלִים הֲרֵי זֶה נִקְנָה הַמִּקָּח. וְאֵין הַלּוֹקֵחַ יָכוֹל לוֹמַר לוֹ אֵינִי לוֹקֵחַ אֶלָּא קַרְקַע שֶׁיֵּשׁ בּוֹ דְּקָלִים. וְאִם אָמַר קַרְקַע בִּדְקָלִים אֲנִי מוֹכֵר לְךָ. אִם הָיוּ בּוֹ שְׁנֵי דְּקָלִים קָנָה וְאִם לָאו מֶקַח טָעוּת הוּא וְחוֹזֵר. וְאִם אָמַר לוֹ קַרְקַע שֶׁל דְּקָלִים אֲנִי מוֹכֵר לְךָ אֵין לוֹ דְּקָלִים. שֶׁאֵין בַּלָּשׁוֹן הַזֶּה אֶלָּא קַרְקַע הָרָאוּי לִדְקָלִים:","הַמּוֹכֵר פַּרְדֵּס לַחֲבֵרוֹ צָרִיךְ שֶׁיִּכְתֹּב לוֹ קְנֵה לְךָ דְּקָלִים וּתְמָרִים וְהוּצִין. וְאַף עַל פִּי שֶׁקָּנָה כָּל אֵלּוּ אַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ אוֹתָם נוֹיֵי הַשְּׁטָר הֵם. וְכֵן הַמּוֹכֵר קַרְקַע לַחֲבֵרוֹ צָרִיךְ לִכְתֹּב לוֹ וְלֹא הִנַּחְתִּי לְפָנַי בְּמֶכֶר זֶה כְּלוּם כְּדֵי לְהִסְתַּלֵּק מִן הַדִּינִין וְהַטְּעָנוֹת:","הַמּוֹכֵר בַּיִת לַחֲבֵרוֹ אַף עַל פִּי שֶׁכָּתַב לוֹ וְהִקְנֵיתִי לְךָ עָמְקוֹ וְרוּמוֹ צָרִיךְ לִכְתֹּב לוֹ קְנֵה לְךָ מֵהַקַּרְקַע הַתְּהוֹם עַד רוּם רָקִיעַ. שֶׁהָעֹמֶק וְהָרוּם אֵינוֹ נִקְנֶה בִּסְתָם. וְכֵיוָן שֶׁקָּנָה הָעֹמֶק וְהָרוּם קָנָה הָרוּם שֶׁהוּא הָאֲוִיר בִּלְבַד וְהָעֹמֶק שֶׁהוּא עֳבִי הָאָרֶץ. אֲבָל לֹא קָנָה הַבֵּינוֹנִית שֶׁבַּמַּעֲמַקִּים וְשֶׁבָּאֲוִיר. וְכֵיוָן שֶׁכָּתַב לוֹ מִקַּרְקַע הַתְּהוֹם עַד רוּם הָרָקִיעַ קָנָה הַבּוֹר וְהַדּוּת שֶׁבָּעֳבִי הַקַּרְקַע וְהַמַּעֲזִיבוֹת וְהַמְּחִלּוֹת שֶׁבֵּין הַמַּעֲזִיבוֹת לְמַעְלָה:","הַמּוֹכֵר בַּיִת לַחֲבֵרוֹ עַל מְנָת שֶׁדְּיוֹטָא עֶלְיוֹנָה שֶׁלִּי הֲרֵי זוֹ שֶׁלּוֹ. וְאִם רָצָה לְהוֹצִיא בָּהּ זִיזִין מוֹצִיא. וְאִם נָפְלָה חוֹזֵר וּבוֹנֶה אוֹתָהּ. וְאִם רָצָה לִבְנוֹת עַל גַּבָּהּ בּוֹנֶה כְּשֶׁהָיָה מִקֹּדֶם:","הַמּוֹכֵר קִבְרוֹ אוֹ דֶּרֶךְ קִבְרוֹ אוֹ מְקוֹם מַעֲמָדוֹ אוֹ בֵּית הֶסְפֵּדוֹ. בָּאִין בְּנֵי מִשְׁפָּחָה וְקוֹבְרִים שָׁם בְּעַל כָּרְחוֹ מִשּׁוּם פְּגַם מִשְׁפָּחָה. וְנוֹתְנִין דְּמֵי הַקֶּבֶר שֶׁקָּבְרוּ בּוֹ לַלּוֹקֵחַ אַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ:"],"Mishneh Torah, Sales 8":["הַמּוֹכֵר שָׂדֶה לַחֲבֵרוֹ בְּאֶלֶף זוּז וְנָתַן לוֹ מִקְצָת הַדָּמִים וְהָיָה יוֹצֵא וְנִכְנָס וְתוֹבֵעַ שְׁאָר הַדָּמִים אֲפִלּוּ לֹא נִשְׁאַר לוֹ אֶלָּא זוּז אֶחָד לֹא קָנָה הַלּוֹקֵחַ אֶת כֻּלָּהּ אַף עַל פִּי שֶׁכָּתַב הַשְּׁטָר אוֹ הֶחֱזִיק:","חָזַר בּוֹ הַלּוֹקֵחַ. יַד הַמּוֹכֵר עַל הָעֶלְיוֹנָה. רָצָה אוֹמֵר לוֹ הֵילָךְ מְעוֹתֶיךָ אוֹ קְנֵה מִן הַקַּרְקַע כְּנֶגֶד הַמָּעוֹת שֶׁנָּתַתָּ לִי וְנוֹתֵן לוֹ מִן הַזִּבּוּרִית שֶׁבָּהּ. וְאִם חָזַר הַמּוֹכֵר יַד הַלּוֹקֵחַ עַל הָעֶלְיוֹנָה רָצָה אוֹמֵר לוֹ תֵּן לִי מְעוֹתַי אוֹ תֵּן לִי קַרְקַע כְּנֶגֶד מְעוֹתַי וְנוֹטֵל מִן הַיָּפֶה שֶׁבָּהּ. וְאִם לֹא הָיָה יוֹצֵא וְנִכְנָס וְתוֹבֵעַ קָנָה הַלּוֹקֵחַ אֶת כֻּלָּהּ וְאֵין אֶחָד מֵהֶן יָכוֹל לַחְזֹר בּוֹ. וּשְׁאָר הַדָּמִים עָלָיו כִּשְׁאָר הַחוֹבוֹת:","מָכַר שָׂדֵהוּ מִפְּנֵי רָעָתָהּ. אַף עַל פִּי שֶׁהוּא יוֹצֵא וְנִכְנָס וְתוֹבֵעַ שְׁאָר הַדָּמִים קָנָה הַכּל. וְאֵין הַלּוֹקֵחַ יָכוֹל לַחְזֹר בּוֹ. שֶׁזֶּה שֶׁתּוֹבֵעַ וְרוֹדֵף לֹא מִפְּנֵי שֶׁעֲדַיִן לֹא גָּמַר וְהִקְנָה. אֶלָּא כְּדֵי שֶׁלֹּא יַחְזֹר בּוֹ הַלּוֹקֵחַ:","וְכֵן הַדִּין בְּמוֹכֵר מִטַּלְטְלִין אַף עַל פִּי שֶׁמָּשַׁךְ הַלּוֹקֵחַ הַפֵּרוֹת וְהוֹצִיאָן לִרְשׁוּתוֹ וְהַמּוֹכֵר נִכְנָס וְיוֹצֵא עַל שְׁאָר הַדָּמִים לֹא קָנָה. וְיַד הַחוֹזֵר בּוֹ עַל הַתַּחְתּוֹנָה כְּמוֹ שֶׁבֵּאַרְנוּ אֶלָּא אִם כֵּן מָכַר מִפְּנֵי רָעַת מִמְכָּרוֹ וַהֲרֵי זֶה קָנָה הַכּל:","לָקַח שְׁוֵה מֵאָה בְּמָאתַיִם וְהַמּוֹכֵר יוֹצֵא וְנִכְנָס לִתְבֹּעַ שְׁאָר הַדָּמִים. הֲרֵי זֶה סָפֵק אִם הוּא כְּמוֹכֵר שָׂדֵהוּ מִפְּנֵי רָעָתָהּ וְאֵינוֹ תּוֹבֵעַ אֶלָּא מִפְּנֵי שֶׁמָּכַר בְּיוֹתֵר. אוֹ אֵינוֹ כְּמוֹכֵר שָׂדֵהוּ מִפְּנֵי רָעָתָהּ וְזֶה שֶׁתּוֹבֵעַ מִפְּנֵי שֶׁעֲדַיִן לֹא גָּמַר לְהַקְנוֹתוֹ עַד שֶׁיִּקַּח כָּל הַדָּמִים. לְפִיכָךְ הָרוֹצֶה לַחְזֹר מִשְּׁנֵיהֶם אֵינוֹ יָכוֹל לַחְזֹר. וְאִם תָּפַס הַמּוֹכֵר מִמִּקָּח שֶׁמָּכַר כְּנֶגֶד הַמָּעוֹת שֶׁנִּשְׁאֲרוּ לוֹ אֵין מוֹצִיאִין מִיָּדוֹ:","הַקּוֹנֶה דָּבָר מֵחֲבֵרוֹ וְנָתַן לוֹ הַדָּמִים וְטָעָה בְּמִנְיַן הַמָּעוֹת. וּלְאַחַר זְמַן תְּבָעוֹ הַמּוֹכֵר וְאָמַר לוֹ מֵאָה שֶׁנָּתַתָּ לִי אֵינָם אֶלָּא תִּשְׁעִים. נִקְנָה הַמִּקָּח וּמַחֲזִיר לוֹ הָעֲשָׂרָה אֲפִלּוּ אַחַר כַּמָּה שָׁנִים. בֵּין בְּקַרְקַע בֵּין בְּמִטַּלְטְלִין:","הָאוֹמֵר לַחֲבֵרוֹ כְּשֶׁאֶמְכֹּר שָׂדֶה זוֹ הֲרֵי הִיא מְכוּרָה לְךָ מֵעַכְשָׁו בְּמֵאָה זוּז וְקָנָה מִיָּדוֹ עַל כָּךְ וּלְאַחַר זְמַן מְכָרָהּ לְאַחֵר בְּמֵאָה. קָנָה הָרִאשׁוֹן. מְכָרָהּ בְּיוֹתֵר עַל מָנֶה קָנָה אַחֲרוֹן. שֶׁלֹּא אָמַר לוֹ אֶלָּא כְּשֶׁאֶמְכֹּר שֶׁיִּהְיֶה מוֹכֵר מִדַּעְתּוֹ תְּחִלָּה וְזֶה לֹא הָיָה רוֹצֶה לִמְכֹּר וְלֹא מָכַר אֶלָּא מִפְּנֵי הַתּוֹסֶפֶת שֶׁהוֹסִיף זֶה עַל שָׁוְיוֹ. וְנִמְצָא כְּמִי שֶׁנֶּאֱנַס וּמָכַר:","אָמַר לוֹ כְּשֶׁאֶמְכְּרֶנָּה הֲרֵי הִיא קְנוּיָה לְךָ מֵעַכְשָׁו כְּמָה שֶׁיָּשׁוּמוּ אוֹתָהּ בֵּית דִּין שֶׁל שְׁלֹשָׁה. אֲפִלּוּ עַל פִּי שְׁנַיִם מִן הַשְּׁלֹשָׁה. אָמַר לוֹ כְּמוֹ שֶׁיֹּאמְרוּ שְׁלֹשָׁה עַד שֶׁיֹּאמְרוּ הַשְּׁלֹשָׁה. וְכֵן אִם אָמַר לוֹ כְּמוֹ שֶׁיָּשׁוּמוּ אוֹתָהּ בֵּית דִּין שֶׁל אַרְבָּעָה עַד שֶׁיָּשׁוּמוּ הָאַרְבָּעָה כֻּלָּן וְיַסְכִּימוּ וְיִמְכֹּר לְאַחֵר כְּמוֹ שֶׁיַּסְכִּימוּ. וְאַחַר כָּךְ יִקְנֶה הָרִאשׁוֹן. שָׁמוּ אוֹתָהּ שְׁלֹשָׁה אוֹ אַרְבָּעָה וְאָמַר הַמּוֹכֵר עַד שֶׁיָּבוֹאוּ שְׁלֹשָׁה אֲחֵרִים אוֹ אַרְבָּעָה וְיָשׁוּמוּ אֵין שׁוֹמְעִין לוֹ שֶׁהֲרֵי קָנוּ מִיָּדוֹ תְּחִלָּה שֶׁמָּכַר מֵעַכְשָׁו:"],"Mishneh Torah, Sanctification of the New Month 19":["לְפִי שֶׁאָמְרוּ חֲכָמִים שֶׁבּכְלַל דִּבָרִים שֶׁהָיוּ בּוֹדְקִין בָּהֶן אֶת הָעֵדִים אוֹמְרִין לָהֶן לְהֵיכָן הָיָה הַיָּרֵחַ נוֹטֶה. כָּשֵׁר בְּעֵינַי לְהוֹדִיעַ דֶּרֶךְ חֶשְׁבּוֹן דָּבָר זֶה. וְאֵין אֲנִי מְדַקְדֵּק בּוֹ לְפִי שֶׁאֵינוֹ מוֹעִיל בִּרְאִיָּה כְּלָל. וּתְחִלַּת חֶשְׁבּוֹן זֶה לֵידַע נְטִיַּת הַמַּזָּלוֹת תְּחִלָּה:","הָעֲגֻלָּה שֶׁהִיא עוֹבֶרֶת בְּמַחֲצִית הַמַּזָּלוֹת שֶׁבָּהּ מַהֲלָךְ הַשֶּׁמֶשׁ. אֵינָהּ עוֹבֶרֶת בְּאֶמְצַע הָעוֹלָם מֵחֲצִי הַמִּזְרָח לַחֲצִי הַמַּעֲרָב. אֶלָּא נוֹטָה הִיא מֵעַל הַקַּו הַשָּׁוֶה הַמְסַבֵּב בְּאֶמְצַע הָעוֹלָם כְּנֶגֶד צָפוֹן וְדָרוֹם. חֶצְיָהּ נוֹטֶה לַצָּפוֹן וְחֶצְיָהּ נוֹטֶה לַדָּרוֹם:","וּשְׁתֵּי נְקֻדּוֹת יֵשׁ בָּהּ שֶׁפּוֹגַעַת בָּהֶן בַּעֲגֻלַּת הַקַּו הַשָּׁוֶה הַמְסַבֵּב בְּאֶמְצַע הָעוֹלָם. הַנְּקֻדָּה הָאַחַת רֹאשׁ מַזַּל טָלֶה. הַנְּקֻדָּה הַשְּׁנִיָּה שֶׁכְּנֶגְדָּהּ רֹאשׁ מַזַּל מֹאזְנַיִם. וְנִמְצְאוּ שִׁשָּׁה מַזָּלוֹת נוֹטוֹת לַצָּפוֹן מִתְּחִלַּת טָלֶה עַד סוֹף בְּתוּלָה. וְשִׁשָּׁה נוֹטוֹת לַדָּרוֹם מִתְּחִלַּת מַזַּל מֹאזְנַיִם עַד סוֹף מַזַּל דָּגִים:","וּמֵרֹאשׁ מַזַּל טָלֶה יַתְחִילוּ הַמַּזָּלוֹת לִנְטוֹת מְעַט מְעַט וּלְהִתְרַחֵק מֵעַל הַקַּו הַשָּׁוֶה כְּנֶגֶד הַצָּפוֹן עַד רֹאשׁ סַרְטָן. וְיִהְיֶה רֹאשׁ סַרְטָן רָחוֹק מֵעַל הַקַּו הַשָּׁוֶה לְרוּחַ הַצָּפוֹן שָׁלֹשׁ וְעֶשְׂרִים מַעֲלוֹת וַחֲצִי מַעֲלָה בְּקֵרוּב. וְיַחְזְרוּ הַמַּזָּלוֹת לְהִתְקָרֵב לַקַּו הַשָּׁוֶה מְעַט מְעַט עַד רֹאשׁ מֹאזְנַיִם שֶׁהוּא עַל הַקַּו הַשָּׁוֶה. וּמֵרֹאשׁ מֹאזְנַיִם יַתְחִילוּ לִנְטוֹת וּלְהִתְרַחֵק כְּנֶגֶד רוּחַ דָּרוֹם עַד רֹאשׁ גְּדִי. וְיִהְיֶה רֹאשׁ גְּדִי רָחוֹק מֵעַל הַקַּו הַשָּׁוֶה לְרוּחַ דָּרוֹם שָׁלֹשׁ וְעֶשְׂרִים מַעֲלוֹת וַחֲצִי מַעֲלָה. וְיַחְזְרוּ הַמַּזָּלוֹת לְהִתְקָרֵב מְעַט מְעַט כְּנֶגֶד הַקַּו הַשָּׁוֶה עַד רֹאשׁ טָלֶה:","נִמְצָא רֹאשׁ טָלֶה וְרֹאשׁ מֹאזְנַיִם מְסַבֵּב עַל הַקַּו הַשָּׁוֶה. וּלְפִיכָךְ כְּשֶׁתִּהְיֶה הַשֶּׁמֶשׁ בִּשְׁנֵי רָאשִׁים אֵלּוּ לֹא תִּהְיֶה נוֹטָה לֹא לַצָּפוֹן וְלֹא לַדָּרוֹם. וְתִזְרַח בַּחֲצִי מִזְרָח וְתִשְׁקַע בַּחֲצִי מַעֲרָב. וְיִהְיֶה הַיּוֹם וְהַלַּיְלָה שָׁוִין בְּכָל הַיִּשּׁוּב:","הֲרֵי נִתְבָּרֵר לְךָ שֶׁכָּל מַעֲלָה וּמַעֲלָה מִמַּעֲלוֹת הַמַּזָּלוֹת נוֹטָה לַצָּפוֹן אוֹ לַדָּרוֹם וְיֵשׁ לִנְטִיָּתָהּ שִׁעוּר. (וְרֹב) [וְרֹחַב] הַנְּטִיָּה לֹא תִּהְיֶה יוֹתֵר עַל שָׁלֹשׁ וְעֶשְׂרִים מַעֲלוֹת וַחֲצִי בְּקֵרוּב:","וְאֵלּוּ הֵם הַשִּׁעוּרִים שֶׁל נְטִיּוֹת לְפִי מִנְיַן הַמַּעֲלוֹת שֶׁל מַזָּלוֹת. וְהַתְחָלָה מַתְחֶלֶת מַזַּל טָלֶה. י' מַעֲלוֹת נְטִיָּתָם ד' מַעֲלוֹת. כ' מַעֲלוֹת נְטִיָּתָם ח' מַעֲלוֹת. ל' מַעֲלוֹת נְטִיָּתָם י\"א מַעֲלוֹת וּמֶחֱצָה. וּמ' מַעֲלוֹת נְטִיָּתָם ט\"ו מַעֲלוֹת. נ' מַעֲלוֹת נְטִיָּתָם י\"ח מַעֲלוֹת. ס' מַעֲלוֹת נְטִיָּתָם כ' מַעֲלוֹת. ע' מַעֲלוֹת נְטִיָּתָם כ\"ב מַעֲלוֹת. פ' מַעֲלוֹת נְטִיָּתָם כ\"ג מַעֲלוֹת. צ' מַעֲלוֹת נְטִיָּתָם כ\"ג מַעֲלוֹת וַחֲצִי מַעֲלָה:","וְאִם יִהְיוּ אֲחָדִים בְּמִנְיָן תִּקַּח לָהֶם מְנָתָם מִבֵּין שְׁתֵּי הַנְּטִיּוֹת כְּמוֹ שֶׁבֵּאַרְנוּ בַּשֶּׁמֶשׁ וּבַיָּרֵחַ. כֵּיצַד. חָמֵשׁ מַעֲלוֹת נְטִיָּתָם שְׁתֵּי מַעֲלוֹת. וְאִם הָיָה מִנְיַן הַמַּעֲלוֹת כ\"ג נְטִיָּתָם ט' מַעֲלוֹת. וְעַל דֶּרֶךְ זוֹ בְּכָל הָאֲחָדִים שֶׁהֵן עִם הָעֲשָׂרוֹת:","וּמֵאַחַר שֶׁתֵּדַע הַנְּטִיָּה שֶׁל מַעֲלוֹת מֵאַחַת עַד צ'. תֵּדַע נְטִיָּתָם כֻּלָּן כְּדֶרֶךְ שֶׁהוֹדַעְנוּךָ בְּרֹחַב הַיָּרֵחַ. שֶׁאִם הָיָה הַמִּנְיָן יֶתֶר עַל צ' עַד ק\"פ תִּגְרַע אוֹתוֹ מִק\"פ. וְאִם הָיָה יוֹתֵר עַל ק\"פ עַד ר\"ע תִּגְרַע מִמֶּנּוּ ק\"פ. וְאִם הָיָה יוֹתֵר עַל ר\"ע עַד ש\"ס תִּגְרַע אוֹתוֹ מִש\"ס. וְהַנִּשְׁאָר תֵּדַע נְטִיָּתוֹ וְהוּא נְטִיַּת אוֹתוֹ הַמִּנְיָן שֶׁבְּיָדְךָ בְּלֹא גֵּרָעוֹן וְלֹא תּוֹסֶפֶת:","אִם תִּרְצֶה לֵידַע כַּמָּה מַעֲלוֹת הוּא הַיָּרֵחַ נוֹטֶה מֵעַל הַקַּו הַשָּׁוֶה כְּנֶגֶד צְפוֹן הָעוֹלָם אוֹ כְּנֶגֶד דְּרוֹם הָעוֹלָם. תֵּדַע תְּחִלָּה כַּמָּה נְטִיַּת הַמַּעֲלָה שֶׁהִיא מְקוֹם הַיָּרֵחַ הָאֲמִתִּי וּלְאֵי זֶה רוּחַ הִיא נוֹטָה לַצָּפוֹן אוֹ לַדָּרוֹם. וְתַחֲזֹר וְתַחְשֹׁב וְתוֹצִיא רֹחַב הַיָּרֵחַ הָרִאשׁוֹן וְתִרְאֶה אִם הוּא צְפוֹנִי אוֹ דְּרוֹמִי. אִם נִמְצְאוּ רֹחַב הַיָּרֵחַ וּנְטִיַּת מַעֲלָתוֹ בְּרוּחַ אַחַת כְּגוֹן שֶׁהָיוּ שְׁנֵיהֶם צְפוֹנִים אוֹ דְּרוֹמִיִּים תְּקַבֵּץ שְׁנֵיהֶם. וְאִם נִמְצְאוּ בִּשְׁתֵּי רוּחוֹת כְּגוֹן שֶׁהָיָה הָאֶחָד דְּרוֹמִי וְהָאֶחָד צְפוֹנִי. תִּגְרַע הַמְּעַט מִשְּׁנֵיהֶם מִן הָרַב וְהַנִּשְׁאָר הוּא מֶרְחַק הַיָּרֵחַ מֵעַל הַקַּו הַשָּׁוֶה בְּאוֹתָהּ הָרוּחַ שֶׁהָיָה בָּהּ הָרַב בִּשְׁנֵיהֶם:","כֵּיצַד בָּאנוּ לֵידַע כַּמָּה הַיָּרֵחַ נוֹטֶה מֵעַל הַקַּו הַשָּׁוֶה בְּלֵיל הָרְאִיָּה שֶׁהוּא שֵׁנִי לְחֹדֶשׁ אִיָּר מִשָּׁנָה זוֹ. וּכְבָר יָדַעְתָּ שֶׁמַּעֲלַת הַיָּרֵחַ הָיְתָה י\"ט מִמַּזַּל שׁוֹר. נְטִיָּתָהּ בַּצָּפוֹן כְּמוֹ י\"ח מַעֲלוֹת. וְרֹחַב הַיָּרֵחַ הָיָה בַּדָּרוֹם כְּמוֹ ד' מַעֲלוֹת. תִּגְרַע הַמְּעַט מִן הָרַב יִשָּׁאֵר י\"ד מַעֲלוֹת. וְנִמְצָא הַיָּרֵחַ רָחוֹק מֵעַל הַקַּו הַשָּׁוֶה י\"ד מַעֲלוֹת לְרוּחַ צָפוֹן. שֶׁהֲרֵי הַמִּנְיָן הָרַב שֶׁהוּא שְׁמוֹנֶה עֶשְׂרֵה מַעֲלוֹת הָיָה צְפוֹנִי. וְכָל חֶשְׁבּוֹן זֶה בְּקֵרוּב בְּלֹא דִּקְדּוּק לְפִי שֶׁאֵינוֹ מוֹעִיל בִּרְאִיָּה:","אִם תִּרְצֶה לֵידַע לְאֵי זוֹ רוּחַ מֵרוּחוֹת הָעוֹלָם יֵרָאֶה הַיָּרֵחַ נוֹטֶה. תַּחְשֹׁב וְתֵדַע מֶרְחַקּוֹ מֵעַל הַקַּו הַשָּׁוֶה. אִם יִהְיֶה עַל הַקַּו הַשָּׁוֶה אוֹ קָרוֹב מִמֶּנּוּ בִּשְׁתַּיִם אוֹ שָׁלֹשׁ מַעֲלוֹת בַּצָּפוֹן אוֹ בַּדָּרוֹם. יֵרָאֶה מְכֻוָּן כְּנֶגֶד אֶמְצַע מַעֲרָב וְתֵרָאֶה פְּגִימָתוֹ מְכֻוֶּנֶת כְּנֶגֶד מִזְרַח הָעוֹלָם בְּשָׁוֶה:","וְאִם יִהְיֶה רָחוֹק מֵעַל הַקַּו הַשָּׁוֶה לִצְפוֹן הָעוֹלָם. יֵרָאֶה בֵּין מַעֲרַב הָעוֹלָם וּבֵין צְפוֹנוֹ. וְתֵרָאֶה פְּגִימָתוֹ נוֹטָה מִכְּנֶגֶד מִזְרַח הָעוֹלָם כְּנֶגֶד דְּרוֹם הָעוֹלָם:","וְאִם הָיָה רָחוֹק מֵעַל הַקַּו הַשָּׁוֶה לִדְרוֹם הָעוֹלָם. יֵרָאֶה בֵּין מַעֲרַב הָעוֹלָם וּבֵין דְּרוֹמוֹ. וְתֵרָאֶה פְּגִימָתוֹ נוֹטָה מִכְּנֶגֶד מִזְרַח הָעוֹלָם כְּנֶגֶד צְפוֹן הָעוֹלָם. וּלְפִי רֹב הַמֶּרְחָק וּלְפִי רֹב הַנְּטִיָּה:","וּמֵחֲקִירַת הָעֵדִים שֶׁאוֹמְרִין לָהֶם כַּמָּה הָיָה גָּבוֹהַּ. וְדָבָר זֶה יִוָּדַע מִקֶּשֶׁת הָרְאִיָּה. שֶׁבִּזְמַן שֶׁתִּהְיֶה קֶשֶׁת הָרְאִיָּה קְצָרָה יֵרָאֶה הַיָּרֵחַ כְּאִלּוּ הוּא קָרוֹב מִן הָאָרֶץ. וּבִזְמַן שֶׁתִּהְיֶה אֲרֻכָּה יֵרָאֶה גָּבוֹהַּ מֵעַל הָאָרֶץ. וּלְפִי אֹרֶךְ קֶשֶׁת הָרְאִיָּה לְפִי גָּבְהוֹ מֵעַל הָאָרֶץ בִּרְאִיַּת הָעֵינַיִם:","הֲרֵי בֵּאַרְנוּ חֶשְׁבּוֹנוֹת כָּל הַדְּרָכִים שֶׁצְּרִיכִין לָהֶם בִּידִיעַת הָרְאִיָּה וּבַחֲקִירַת הָעֵדִים. כְּדֵי שֶׁיִּהְיֶה הַכּל יָדוּעַ לַמְּבִינִים וְלֹא יֶחְסְרוּ דֶּרֶךְ מִדַּרְכֵי הַתּוֹרָה וְלֹא יְשׁוֹטְטוּ לְבַקֵּשׁ אַחֲרֶיהָ בִּסְפָרִים אֲחֵרִים. (ישעיה לד טז) \"דִּרְשׁוּ מֵעַל סֵפֶר ה'\" וְקִרְאוּ, אַחַת מֵהֵנָּה לֹא נֶעְדָּרָה: סָלִיק הִלְכוֹת קִדּוּשׁ הַחֹדֶשׁ"],"Mishneh Torah, Scroll of Esther and Hanukkah 4":["כַּמָּה נֵרוֹת הוּא מַדְלִיק בַּחֲנֻכָּה. מִצְוָתָהּ שֶׁיִּהְיֶה כָּל בַּיִת וּבַיִת מַדְלִיק נֵר אֶחָד בֵּין שֶׁהָיוּ אַנְשֵׁי הַבַּיִת מְרֻבִּין בֵּין שֶׁלֹּא הָיָה בּוֹ אֶלָּא אָדָם אֶחָד. וְהַמְהַדֵּר אֶת הַמִּצְוָה מַדְלִיק נֵרוֹת כְּמִנְיַן אַנְשֵׁי הַבַּיִת נֵר לְכָל אֶחָד וְאֶחָד בֵּין אֲנָשִׁים בֵּין נָשִׁים. וְהַמְהַדֵּר יוֹתֵר עַל זֶה וְעוֹשֶׂה מִצְוָה מִן הַמֻּבְחָר מַדְלִיק נֵר לְכָל אֶחָד בַּלַּיְלָה הָרִאשׁוֹן וּמוֹסִיף וְהוֹלֵךְ בְּכָל לַיְלָה וְלַיְלָה נֵר אֶחָד:","כֵּיצַד. הֲרֵי שֶׁהָיוּ אַנְשֵׁי הַבַּיִת עֲשָׂרָה. בַּלַּיְלָה הָרִאשׁוֹן מַדְלִיק עֲשָׂרָה נֵרוֹת וּבְלֵיל שֵׁנִי עֶשְׂרִים וּבְלֵיל שְׁלִישִׁי שְׁלֹשִׁים עַד שֶׁנִּמְצָא מַדְלִיק בְּלֵיל שְׁמִינִי שְׁמוֹנִים נֵרוֹת:","מִנְהָג פָּשׁוּט בְּכָל עָרֵינוּ בִּסְפָרַד שֶׁיִּהְיוּ כָּל אַנְשֵׁי הַבַּיִת מַדְלִיקִין נֵר אֶחָד בַּלַּיְלָה הָרִאשׁוֹן וּמוֹסִיפִין וְהוֹלְכִין נֵר בְּכָל לַיְלָה עַד שֶׁנִּמְצָא מַדְלִיק בְּלֵיל שְׁמִינִי שְׁמוֹנָה נֵרוֹת בֵּין שֶׁהָיוּ אַנְשֵׁי הַבַּיִת מְרֻבִּים בֵּין שֶׁהָיָה אָדָם אֶחָד:","נֵר שֶׁיֵּשׁ לוֹ שְׁתֵּי פִּיּוֹת עוֹלֶה לִשְׁנֵי בְּנֵי אָדָם. מִלֵּא קְעָרָה שֶׁמֶן וְהִקִּיפָהּ פְּתִילוֹת. אִם כָּפָה עָלֶיהָ כְּלִי כָּל פְּתִילָה וּפְתִילָה נֶחְשֶׁבֶת כְּנֵר אֶחָד. לֹא כָּפָה עָלֶיהָ כְּלִי נַעֲשֵׂית כִּמְדוּרָה וַאֲפִלּוּ כְּנֵר אֶחָד אֵינָהּ נֶחְשֶׁבֶת:","אֵין מַדְלִיקִין נֵרוֹת חֲנֻכָּה קֹדֶם שֶׁתִּשְׁקַע הַחַמָּה אֶלָּא עִם שְׁקִיעָתָהּ לֹא מְאַחֲרִין וְלֹא מַקְדִּימִין. שָׁכַח אוֹ הֵזִיד וְלֹא הִדְלִיק עִם שְׁקִיעַת הַחַמָּה מַדְלִיק וְהוֹלֵךְ עַד שֶׁתִּכְלֶה רֶגֶל מִן הַשּׁוּק. וְכַמָּה הוּא זְמַן זֶה כְּמוֹ חֲצִי שָׁעָה אוֹ יֶתֶר. עָבַר זְמַן זֶה אֵינוֹ מַדְלִיק. וְצָרִיךְ שֶׁיִּתֵּן שֶׁמֶן בַּנֵּר כְּדֵי שֶׁתִּהְיֶה דּוֹלֶקֶת וְהוֹלֶכֶת עַד שֶׁתִּכְלֶה רֶגֶל מִן הַשּׁוּק. הִדְלִיקָהּ וְכָבְתָה אֵינוֹ זָקוּק לְהַדְלִיקָהּ פַּעַם אַחֶרֶת. נִשְׁאֲרָה דּוֹלֶקֶת אַחַר שֶׁכָּלְתָה רֶגֶל מִן הַשּׁוּק אִם רָצָה לְכַבּוֹתָהּ אוֹ לְסַלְּקָהּ עוֹשֶׂה:","כָּל הַשְּׁמָנִים וְכָל הַפְּתִילוֹת כְּשֵׁרוֹת לְנֵר חֲנֻכָּה וְאַף עַל פִּי שֶׁאֵין הַשְּׁמָנִים נִמְשָׁכִים אַחַר הַפְּתִילָה וְאֵין הָאוּר נִתְלֵית יָפֶה בְּאוֹתָן הַפְּתִילוֹת. וַאֲפִלּוּ בְּלֵילֵי שַׁבָּת שֶׁבְּתוֹךְ יְמֵי חֲנֻכָּה מֻתָּר לְהַדְלִיק הַשְּׁמָנִים וְהַפְּתִילוֹת שֶׁאָסוּר לְהַדְלִיק בָּהֶן נֵר שַׁבָּת. לְפִי שֶׁאָסוּר לְהִשְׁתַּמֵּשׁ לְנֵר חֲנֻכָּה בֵּין בְּשַׁבָּת בֵּין בְּחל וַאֲפִלּוּ לִבְדֹּק מָעוֹת אוֹ לִמְנוֹתָן לְאוֹרָהּ אָסוּר:","נֵר חֲנֻכָּה מִצְוָה לְהַנִּיחוֹ עַל פֶּתַח בֵּיתוֹ מִבַּחוּץ בַּטֶּפַח הַסָּמוּךְ לַפֶּתַח עַל שְׂמֹאל הַנִּכְנָס לַבַּיִת כְּדֵי שֶׁתִּהְיֶה מְזוּזָה מִיָּמִין וְנֵר חֲנֻכָּה מִשְּׂמֹאל. וְאִם הָיָה דָּר בַּעֲלִיָּה מַנִּיחוֹ בַּחַלּוֹן הַסְּמוּכָה לִרְשׁוּת הָרַבִּים. וְנֵר חֲנֻכָּה שֶׁהִנִּיחוֹ לְמַעְלָה מֵעֶשְׂרִים אַמָּה לֹא עָשָׂה כְּלוּם לְפִי שֶׁאֵינוֹ נִכָּר:","בִּימֵי הַסַּכָּנָה מַנִּיחַ אָדָם נֵר חֲנֻכָּה בְּתוֹךְ בֵּיתוֹ מִבִּפְנִים וַאֲפִלּוּ הִנִּיחוֹ עַל שֻׁלְחָנוֹ דַּיּוֹ. וְצָרִיךְ לִהְיוֹת בְּתוֹךְ הַבַּיִת נֵר אַחֵר לְהִשְׁתַּמֵּשׁ לְאוֹרוֹ. וְאִם הָיְתָה שָׁם מְדוּרָה אֵינוֹ צָרִיךְ נֵר אַחֵר. וְאִם אָדָם חָשׁוּב הוּא שֶׁאֵין דַּרְכּוֹ לְהִשְׁתַּמֵּשׁ לִמְדוּרָה צָרִיךְ נֵר אַחֵר:","נֵר חֲנֻכָּה שֶׁהִדְלִיקוֹ חֵרֵשׁ שׁוֹטֶה וְקָטָן אוֹ עַכּוּ\"ם לֹא עָשָׂה כְּלוּם עַד שֶׁיַּדְלִיקֶנּוּ מִי שֶׁהוּא חַיָּב בַּהַדְלָקָה. הִדְלִיקוֹ מִבִּפְנִים וְהוֹצִיאוֹ דָּלוּק וְהִנִּיחוֹ עַל פֶּתַח בֵּיתוֹ לֹא עָשָׂה כְּלוּם עַד שֶׁיַּדְלִיקֶנּוּ בִּמְקוֹמוֹ. אָחַז הַנֵּר בְּיָדוֹ וְעָמַד לֹא עָשָׂה כְּלוּם שֶׁהָרוֹאֶה אוֹמֵר לְצָרְכּוֹ הוּא עוֹמֵד. עֲשָׁשִׁית שֶׁהָיְתָה דּוֹלֶקֶת כָּל הַיּוֹם כֻּלּוֹ לְמוֹצָאֵי שַׁבָּת מְכַבֶּה וּמְבָרֵךְ וּמַדְלִיקָהּ שֶׁהַהַדְלָקָה הִיא הַמִּצְוָה וְלֹא הַהַנָּחָה. וּמֻתָּר לְהַדְלִיק נֵר חֲנֻכָּה מִנֵּר חֲנֻכָּה:","חָצֵר שֶׁיֵּשׁ לָהּ שְׁנֵי פְּתָחִים בִּשְׁתֵּי רוּחוֹת צְרִיכָה שְׁתֵּי נֵרוֹת. שֶׁמָּא יֹאמְרוּ הָעוֹבְרִים בְּרוּחַ זוֹ לֹא הִנִּיחַ נֵר חֲנֻכָּה. אֲבָל אִם הָיוּ בְּרוּחַ אַחַת מַדְלִיק בְּאֶחָד מֵהֶן:","אוֹרֵחַ שֶׁמַּדְלִיקִין עָלָיו בְּתוֹךְ בֵּיתוֹ אֵינוֹ צָרִיךְ לְהַדְלִיק עָלָיו בְּמָקוֹם שֶׁנִּתְאָרֵחַ בּוֹ. אֵין לוֹ בַּיִת לְהַדְלִיק עָלָיו בּוֹ צָרִיךְ לְהַדְלִיק בַּמָּקוֹם שֶׁנִּתְאָרֵחַ בּוֹ. וּמִשְׁתַּתֵּף עִמָּהֶן בַּשֶּׁמֶן. וְאִם הָיָה לוֹ בַּיִת בִּפְנֵי עַצְמוֹ אַף עַל פִּי שֶׁמַּדְלִיקִין עָלָיו בְּתוֹךְ בֵּיתוֹ צָרִיךְ לְהַדְלִיק בַּבַּיִת שֶׁהוּא בּוֹ מִפְּנֵי הָעוֹבְרִין:","מִצְוַת נֵר חֲנֻכָּה מִצְוָה חֲבִיבָה הִיא עַד מְאֹד וְצָרִיךְ אָדָם לְהִזָּהֵר בָּהּ כְּדֵי לְהוֹדִיעַ הַנֵּס וּלְהוֹסִיף בְּשֶׁבַח הָאֵל וְהוֹדָיָה לוֹ עַל הַנִּסִּים שֶׁעָשָׂה לָנוּ. אֲפִלּוּ אֵין לוֹ מַה יֹּאכַל אֶלָּא מִן הַצְּדָקָה שׁוֹאֵל אוֹ מוֹכֵר כְּסוּתוֹ וְלוֹקֵחַ שֶׁמֶן וְנֵרוֹת וּמַדְלִיק:","הֲרֵי שֶׁאֵין לוֹ אֶלָּא פְּרוּטָה אַחַת וּלְפָנָיו קִדּוּשׁ הַיּוֹם וְהַדְלָקַת נֵר חֲנֻכָּה מַקְדִּים לִקְנוֹת שֶׁמֶן לְהַדְלִיק נֵר חֲנֻכָּה עַל הַיַּיִן לְקִדּוּשׁ הַיּוֹם. הוֹאִיל וּשְׁנֵיהֶם מִדִּבְרֵי סוֹפְרִים מוּטָב לְהַקְדִּים נֵר חֲנֻכָּה שֶׁיֵּשׁ בּוֹ זִכְרוֹן הַנֵּס:","הָיָה לְפָנָיו נֵר בֵּיתוֹ וְנֵר חֲנֻכָּה אוֹ נֵר בֵּיתוֹ וְקִדּוּשׁ הַיּוֹם נֵר בֵּיתוֹ קוֹדֵם מִשּׁוּם שְׁלוֹם בֵּיתוֹ שֶׁהֲרֵי הַשֵּׁם נִמְחָק לַעֲשׂוֹת שָׁלוֹם בֵּין אִישׁ לְאִשְׁתּוֹ. גָּדוֹל הַשָּׁלוֹם שֶׁכָּל הַתּוֹרָה נִתְּנָה לַעֲשׂוֹת שָׁלוֹם בָּעוֹלָם שֶׁנֶּאֱמַר (משלי ג יז) \"דְּרָכֶיהָ דַרְכֵי נֹעַם וְכָל נְתִיבֹתֶיהָ שָׁלוֹם\":"],"Mishneh Torah, Service on the Day of Atonement 1":["בְיוֹם הַצּוֹם מַקְרִיבִין תָּמִיד בַּשַּׁחַר וְתָמִיד בֵּין הָעַרְבַּיִם כְּסֵדֶר כָּל יוֹם וְיוֹם. וּמַקְרִיבִין מוּסַף הַיּוֹם פַּר וְאַיִל וְשִׁבְעָה כְּבָשִׂים כֻּלָּם עוֹלוֹת. וְשָׂעִיר חַטָּאת נַעֲשֶׂה בַּחוּץ וְהוּא נֶאֱכָל לָעֶרֶב. וְעוֹד מַקְרִיבִין יֶתֶר עַל מוּסָף זֶה. פַּר בֶּן בָּקָר לְחַטָּאת וְהוּא נִשְׂרָף. וְאַיִל לְעוֹלָה. וּשְׁנֵיהֶם מִשֶּׁל כֹּהֵן גָּדוֹל. וְאַיִל הַבָּא מִשֶּׁל צִבּוּר הָאָמוּר בְּפָרָשַׁת (ויקרא טז א) \"אַחֲרֵי מוֹת\". וְהוּא הָאַיִל הָאָמוּר בְּחֻמַּשׁ הַפְּקוּדִים בִּכְלַל הַמּוּסָף. וְהוּא הַנִּקְרָא אֵיל הָעָם. וְעוֹד מְבִיאִין מִשֶּׁל צִבּוּר שְׁנֵי שְׂעִירֵי עִזִּים. אֶחָד קָרֵב חַטָּאת וְהוּא נִשְׂרָף. וְהַשֵּׁנִי שָׂעִיר הַמִּשְׁתַּלֵּחַ. נִמְצְאוּ כָּל הַבְּהֵמוֹת הַקְּרֵבִים בְּיוֹם זֶה חֲמֵשׁ עֶשְׂרֵה. שְׁנֵי תְּמִידִין. וּפַר. וּשְׁנֵי אֵילִים וְשִׁבְעָה כְּבָשִׂים כֻּלָּם עוֹלוֹת. וּשְׁנֵי שְׂעִירִים חַטָּאת אֶחָד נַעֲשֶׂה בַּחוּץ וְנֶאֱכַל לָעֶרֶב וְהַשֵּׁנִי נַעֲשֶׂה בִּפְנִים וְנִשְׂרָף. וּפַר כֹּהֵן גָּדוֹל לְחַטָּאת וְהוּא נִשְׂרָף:","עֲבוֹדַת כָּל חֲמֵשׁ עֶשְׂרֵה בְּהֵמוֹת אֵלּוּ הַקְּרֵבִין בְּיוֹם זֶה אֵינָהּ אֶלָּא בְּכֹהֵן גָּדוֹל בִּלְבַד. אֶחָד כֹּהֵן הַמָּשׁוּחַ בְּשֶׁמֶן הַמִּשְׁחָה אוֹ הַמְרֻבֶּה בִּבְגָדִים. וְאִם הָיְתָה שַׁבָּת אַף מוּסַף שַׁבָּת אֵין מַקְרִיב אוֹתוֹ אֶלָּא כֹּהֵן גָּדוֹל. וְכֵן שְׁאָר הָעֲבוֹדוֹת שֶׁל יוֹם זֶה כְּגוֹן הַקְטָרַת הַקְּטֹרֶת שֶׁל כָּל יוֹם וַהֲטָבַת הַנֵּרוֹת הַכּל עָשׂוּי בְּכֹהֵן גָּדוֹל נָשׂוּי שֶׁנֶּאֱמַר (ויקרא טז ו) (ויקרא טז יא) (ויקרא טז יז) \"וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ\". בֵּיתוֹ זוֹ אִשְׁתּוֹ:","שִׁבְעַת יָמִים קֹדֶם לְיוֹם הַכִּפּוּרִים מַפְרִישִׁין כֹּהֵן גָּדוֹל מִבֵּיתוֹ לְלִשְׁכָּתוֹ שֶׁבַּמִּקְדָּשׁ וְדָבָר זֶה קַבָּלָה מִמּשֶׁה רַבֵּנוּ. וּמַפְרִישִׁין אוֹתוֹ מֵאִשְׁתּוֹ כָּל שִׁבְעַת יָמִים אֵלּוּ שֶׁמָּא תִּמָּצֵא אִשְׁתּוֹ נִדָּה וְנִמְצָא טָמֵא שִׁבְעַת יָמִים וְאֵינוֹ יָכוֹל לַעֲבֹד. וּמַתְקִינִין לוֹ כֹּהֵן גָּדוֹל אַחֵר שֶׁאִם יֶאֱרַע בְּזֶה פִּסּוּל יַעֲבֹד הָאַחֵר תַּחְתָּיו. בֵּין שֶׁאֵרַע בּוֹ פִּסּוּל קֹדֶם תָּמִיד שֶׁל שַׁחַר בֵּין שֶׁאֵרַע בּוֹ פִּסּוּל אַחַר שֶׁהִקְרִיב קָרְבָּנוֹ זֶה שֶׁנִּכְנַס תַּחְתָּיו אֵינוֹ צָרִיךְ חִנּוּךְ אֶלָּא עֲבוֹדָתוֹ מְחַנַּכְתּוֹ וּמַתְחִיל מֵעֲבוֹדָה שֶׁפָּסַק בָּהּ הָרִאשׁוֹן. עָבַר יוֹם הַכִּפּוּרִים הֲרֵי הָרִאשׁוֹן חוֹזֵר לַעֲבוֹדָתוֹ וְהַשֵּׁנִי עוֹבֵר וְכָל מִצְוֹת כְּהֻנָּה גְּדוֹלָה עָלָיו אֶלָּא שֶׁאֵינוֹ עוֹבֵד כְּכֹהֵן גָּדוֹל וְאִם עָבַד עֲבוֹדָתוֹ כְּשֵׁרָה. וְאִם מֵת הָרִאשׁוֹן זֶה הַשֵּׁנִי מִתְמַנֶּה תַּחְתָּיו:","בְּשִׁבְעַת יָמִים אֵלּוּ מַזִּין עָלָיו מֵאֵפֶר הַפָּרָה בַּשְּׁלִישִׁי לְהַפְרָשָׁתוֹ וּבַשְּׁבִיעִי שֶׁהוּא עֶרֶב יוֹם הַכִּפּוּרִים שֶׁמָּא נִטְמָא בְּמֵת וְלֹא יָדַע. וְאִם חָל יוֹם שַׁבָּת בַּשְּׁלִישִׁי אוֹ בַּשְּׁבִיעִי שֶׁלּוֹ דּוֹחִין אֶת הַהַזָּיָה:","כָּל שִׁבְעַת הַיָּמִים מַרְגִּילִין אוֹתוֹ בַּעֲבוֹדוֹת. זוֹרֵק אֶת הַדָּם וּמַקְטִיר אֶת הַקְּטֹרֶת וּמֵיטִיב אֶת הַנֵּרוֹת וּמַקְטִיר אֵיבְרֵי תָּמִיד עַל הַמִּזְבֵּחַ כְּדֵי שֶׁיִּהְיֶה רָגִיל בַּעֲבוֹדָה בְּיוֹם הַכִּפּוּרִים. וּמוֹסְרִין לוֹ זְקֵנִים מִזִּקְנֵי בֵּית דִּין וְקוֹרְאִים לְפָנָיו וּמְלַמְּדִין אוֹתוֹ עֲבוֹדַת הַיּוֹם וְסִדּוּרָהּ וְאוֹמְרִין לוֹ אִישִׁי כֹּהֵן גָּדוֹל קְרָא אַתָּה בְּפִיךָ שֶׁמָּא שָׁכַחְתָּ אוֹ שֶׁמָּא לֹא לָמַדְתָּ דָּבָר זֶה. וְעֶרֶב יוֹם הַכִּפּוּרִים בְּשַׁחֲרִית הָיוּ מַעֲמִידִין אוֹתוֹ בְּשַׁעֲרֵי הַמִּזְרָח וּמַעֲבִירִין לְפָנָיו פָּרִים וְאֵילִים וּכְבָשִׂים כְּדֵי שֶׁיִּהְיֶה מַכִּיר וְרָגִיל בַּעֲבוֹדָה:","כָּל שִׁבְעַת הַיָּמִים לֹא הָיוּ מוֹנְעִין מִמֶּנּוּ מַאֲכָל וּמַשְׁקֶה. עֶרֶב יוֹם הַכִּפּוּרִים עִם חֲשֵׁכָה לֹא הָיוּ מַנִּיחִין אוֹתוֹ לֶאֱכל הַרְבֵּה שֶׁהַמַּאֲכָל מֵבִיא אֶת הַשֵּׁנָה. וְלֹא הָיוּ מַנִּיחִין אוֹתוֹ לִישֹׁן שֶׁמָּא יִרְאֶה קֶרִי. וְלֹא הָיוּ מַאֲכִילִין אוֹתוֹ דְּבָרִים הַמַּרְגִּילִין לְשִׁכְבַת זֶרַע כְּגוֹן בֵּיצִים וְחָלָב חַם וְכַיּוֹצֵא בָּהֶן:","בִּימֵי בַּיִת שֵׁנִי צָץ הַמִּינוּת בְּיִשְׂרָאֵל. וְיָצְאוּ הַצְּדוֹקִין מְהֵרָה יֹאבֵדוּ שֶׁאֵינָן מַאֲמִינִין בַּתּוֹרָה שֶׁבְּעַל פֶּה. וְהָיוּ אוֹמְרִין שֶׁקְּטֹרֶת שֶׁל יוֹם הַכִּפּוּרִים מַנִּיחִין אוֹתָהּ עַל הָאֵשׁ בַּהֵיכָל חוּץ לַפָּרֹכֶת וּכְשֶׁיַּעֲלֶה עֲשָׁנָהּ מַכְנִיס אוֹתָהּ לְפָנִים לְקֹדֶשׁ הַקָּדָשִׁים. הַטַּעַם. זֶה שֶׁכָּתוּב בַּתּוֹרָה (ויקרא טז ב) \"כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת\" אָמְרוּ כִּי הוּא עֲנַן הַקְּטֹרֶת. וּמִפִּי הַשְּׁמוּעָה לָמְדוּ חֲכָמִים שֶׁאֵין נוֹתֵן הַקְּטֹרֶת אֶלָּא בְּקֹדֶשׁ הַקָּדָשִׁים לִפְנֵי הָאָרוֹן. שֶׁנֶּאֱמַר (ויקרא טז יג) \"וְנָתַן הַקְּטֹרֶת עַל הָאֵשׁ לִפְנֵי ה'\". וּלְפִי שֶׁהָיוּ חוֹשְׁשִׁין בְּבַיִת שֵׁנִי שֶׁמָּא כֹּהֵן גָּדוֹל זֶה נוֹטֶה לְצַד מִינוּת. הָיוּ מַשְׁבִּיעִין אוֹתוֹ עֶרֶב יוֹם הַכִּפּוּרִים וְאוֹמְרִים לוֹ אִישִׁי כֹּהֵן גָּדוֹל אָנוּ שְׁלוּחֵי בֵּית דִּין וְאַתָּה שְׁלוּחֵנוּ וּשְׁלִיחַ בֵּית דִּין. מַשְׁבִּיעִין אָנוּ עָלֶיךָ בְּמִי שֶׁשִּׁכֵּן אֶת שְׁמוֹ בַּבַּיִת הַזֶּה שֶׁלֹּא תְּשַׁנֶּה דָּבָר שֶׁאָמַרְנוּ לְךָ. וְהוּא פּוֹרֵשׁ וּבוֹכֶה עַל שֶׁחֲשָׁדוּהוּ בְּמִינוּת. וְהֵן פּוֹרְשִׁין וּבוֹכִין לְפִי שֶׁחָשְׁדוּ לְמִי שֶׁמַּעֲשָׂיו סְתוּמִין שֶׁמָּא אֵין בְּלִבּוֹ כְּלוּם:","כָּל לֵילֵי יוֹם הַכִּפּוּרִים כֹּהֵן גָּדוֹל יוֹשֵׁב וְדוֹרֵשׁ אִם הָיָה חָכָם. וְאִם הָיָה תַּלְמִיד דּוֹרְשִׁים לְפָנָיו. אִם הָיָה רָגִיל לִקְרֹא קוֹרֵא וְאִם לָאו קוֹרִין לְפָנָיו. כְּדֵי שֶׁלֹּא יִישַׁן. וּבַמֶּה קוֹרִין לְפָנָיו. בְּכִתְבֵי הַקֹּדֶשׁ. בִּקֵּשׁ לְהִתְנַמְנֵם פִּרְחֵי לְוִיָּה מַכִּין לְפָנָיו בְּאֶצְבַּע צְרֵדָה. וְאוֹמְרִים לוֹ אִישִׁי כֹּהֵן גָּדוֹל עֲמֹד וְהִצְטַנֵּן מְעַט עַל הָרִצְפָּה כְּדֵי שֶׁלֹּא תִּישַׁן. וּמִתְעַסְּקִין עִמּוֹ עַד שֶׁמַּגִּיעַ זְמַן שְׁחִיטָה. וְלֹא הָיוּ שׁוֹחֲטִין עַד שֶׁמַּכִּירִין שֶׁעָלָה עַמּוּד הַשַּׁחַר בְּוַדַּאי שֶׁמָּא יִשְׁחֲטוּ בַּלַּיְלָה:"],"Mishneh Torah, Shofar, Sukkah and Lulav 4":["שִׁעוּר הַסֻּכָּה גָּבְהָהּ אֵין פָּחוֹת מֵעֲשָׂרָה טְפָחִים וְלֹא יָתֵר עַל עֶשְׂרִים אַמָּה. וְרָחְבָּהּ אֵין פָּחוֹת מִשִּׁבְעָה טְפָחִים עַל שִׁבְעָה טְפָחִים. וְיֵשׁ לוֹ לְהוֹסִיף בְּרָחְבָּהּ אֲפִלּוּ כַּמָּה מִילִין. הָיְתָה פְּחוּתָה מֵעֲשָׂרָה אוֹ מִשִּׁבְעָה עַל שִׁבְעָה אוֹ גְּבוֹהָה מֵעֶשְׂרִים אַמָּה כָּל שֶׁהוּא הֲרֵי זוֹ פְּסוּלָה:","סֻכָּה שֶׁאֵין לָהּ שָׁלֹשׁ דְּפָנוֹת פְּסוּלָה. הָיוּ לָהּ שְׁתֵּי דְּפָנוֹת גְּמוּרוֹת זוֹ בְּצַד זוֹ כְּמִין גַּ\"ם עוֹשֶׂה דֹּפֶן שֶׁיֵּשׁ בְּרָחְבּוֹ יֶתֶר עַל טֶפַח וּמַעֲמִידוֹ בְּפָחוֹת מִשְּׁלֹשָׁה סָמוּךְ לְאֶחָד מִשְּׁתֵּי הַדְּפָנוֹת וְדַיּוֹ. וְצָרִיךְ לַעֲשׂוֹת לָהּ צוּרַת פֶּתַח מִפְּנֵי שֶׁאֵין לָהּ שָׁלֹשׁ דָּפְנוֹת גְּמוּרוֹת. וּכְבָר בֵּאַרְנוּ בְּהִלְכוֹת שַׁבָּת שֶׁצּוּרַת פֶּתַח הָאָמוּר בְּכָל מָקוֹם אֲפִלּוּ קָנֶה מִכָּאן וְקָנֶה מִכָּאן וְקָנֶה עַל גַּבֵּיהֶן אַף עַל פִּי שֶׁאֵינוֹ מַגִּיעַ לָהֶן:","הָיוּ לָהּ שְׁתֵּי דְּפָנוֹת זוֹ כְּנֶגֶד זוֹ וּבֵינֵיהֶן מְפֻלָּשׁ. עוֹשֶׂה דֹּפֶן שֶׁיֵּשׁ בְּרָחְבּוֹ אַרְבָּעָה טְפָחִים וּמַשֶּׁהוּ וּמַעֲמִידוֹ בְּפָחוֹת מִשְּׁלֹשָׁה סָמוּךְ לְאַחַת מִשְּׁתֵּי הַדְּפָנוֹת וּכְשֵׁרָה. וְצָרִיךְ לַעֲשׂוֹת לָהּ צוּרַת פֶּתַח. קָנִים הַיּוֹצְאִים מִסְּכַךְ הַסֻּכָּה לִפְנֵי הַסֻּכָּה וְדֹפֶן אַחַת נִמְשֶׁכֶת עִמָּהֶן הֲרֵי הֵן כְּסֻכָּה:","דְּפָנוֹת שֶׁהָיוּ דְּבוּקוֹת בְּגַג הַסֻּכָּה וְלֹא הָיוּ מַגִּיעוֹת לָאָרֶץ אִם הָיוּ גְּבוֹהוֹת מִן הָאָרֶץ שְׁלֹשָׁה טְפָחִים פְּסוּלָה. פָּחוֹת מִכֵּן כְּשֵׁרָה. הָיוּ הַדְּפָנוֹת דְּבוּקוֹת לָאָרֶץ וְלֹא הָיוּ מַגִּיעוֹת לַסְּכָךְ אִם גְּבוֹהוֹת עֲשָׂרָה טְפָחִים אַף עַל פִּי שֶׁהֵן רְחוֹקִין מִן הַגַּג כַּמָּה אַמּוֹת כְּשֵׁרָה וּבִלְבַד שֶׁיִּהְיוּ הַדְּפָנוֹת מְכֻוָּנוֹת תַּחַת שְׂפַת הַגַּג. הִרְחִיק אֶת הַגַּג מִן הַדֹּפֶן שְׁלֹשָׁה טְפָחִים פְּסוּלָה. פָּחוֹת מִכֵּן כְּשֵׁרָה. תָּלָה מְחִצָּה שֶׁגְּבוֹהָה אַרְבָּעָה וּמַשֶּׁהוּ בְּאֶמְצַע בְּפָחוֹת מִשְּׁלֹשָׁה סָמוּךְ לָאָרֶץ וּבְפָחוֹת מִשְּׁלֹשָׁה סָמוּךְ לַגַּג הֲרֵי זוֹ כְּשֵׁרָה:","הָעוֹשֶׂה סֻכָּתוֹ בֵּין הָאִילָנוֹת וְהָאִילָנוֹת דְּפָנוֹת לָהּ. אִם הָיוּ חֲזָקִים אוֹ שֶׁקָּשַׁר אוֹתָם וְחִזֵּק אוֹתָם עַד שֶׁלֹּא תִּהְיֶה הָרוּחַ הַמְּצוּיָה מְנִידָה אוֹתָם תָּמִיד וּמִלֵּא בֵּין הָאֲמִירִים בְּתֶבֶן וּבְקַשׁ כְּדֵי שֶׁלֹּא תָּנִיד אוֹתָם הָרוּחַ וְקָשַׁר אוֹתָם הֲרֵי זוֹ כְּשֵׁרָה. שֶׁכָּל מְחִצָּה שֶׁאֵינָהּ יְכוֹלָה לַעֲמֹד בְּרוּחַ מְצוּיָה שֶׁל יַבָּשָׁה אֵינָהּ מְחִצָּה:","הָעוֹשֶׂה סֻכָּתוֹ בְּרֹאשׁ הָעֲגָלָה אוֹ בְּרֹאשׁ הַסְּפִינָה כְּשֵׁרָה וְעוֹלִין לָהּ בְּיוֹם טוֹב. בְּרֹאשׁ הָאִילָן אוֹ עַל גַּבֵּי הַגָּמָל כְּשֵׁרָה וְאֵין עוֹלִין לָהּ בְּיוֹם טוֹב. לְפִי שֶׁאָסוּר לַעֲלוֹת בְּיוֹם טוֹב בָּאִילָן אוֹ עַל גַּבֵּי בְּהֵמָה. הָיוּ מִקְצָת הַדְּפָנוֹת עֲשׂוּיוֹת בִּידֵי אָדָם וּמִקְצָתָן אִילָנוֹת רוֹאִין כָּל שֶׁאִלּוּ נִטְּלוּ הָאִילָנוֹת הִיא יְכוֹלָה לַעֲמֹד בַּדְּפָנוֹת שֶׁבִּידֵי אָדָם עוֹלִין לָהּ בְּיוֹם טוֹב:","סֻכָּה שֶׁאֵין לָהּ גַּג פְּסוּלָה. כֵּיצַד. כְּגוֹן שֶׁהָיוּ רָאשֵׁי הַדְּפָנוֹת דְּבוּקוֹת זוֹ בָּזוֹ כְּמִין צְרִיף. אוֹ שֶׁסָּמַךְ רֹאשׁ הַדֹּפֶן שֶׁל סֻכָּה לַכֹּתֶל. אִם הָיָה לָהּ גַּג אֲפִלּוּ טֶפַח. אוֹ שֶׁהִגְבִּיהַּ הַדֹּפֶן הַסָּמוּךְ לַכֹּתֶל מִן הַקַּרְקַע טֶפַח הֲרֵי זוֹ כְּשֵׁרָה. סֻכָּה עֲגֻלָּה אִם יֵשׁ בְּהֶקֵּפָהּ כְּדֵי לְרַבֵּעַ בָּהּ שִׁבְעָה טְפָחִים עַל שִׁבְעָה טְפָחִים אַף עַל פִּי שֶׁאֵין לָהּ זָוִיּוֹת הֲרֵי זוֹ כְּשֵׁרָה:","סִכֵּךְ עַל גַּבֵּי אַכְסַדְרָה שֶׁיֵּשׁ לָהּ פְּצִימִין בֵּין שֶׁהָיוּ נִרְאִין מִבִּפְנִים וְאֵין נִרְאִין מִבַּחוּץ בֵּין שֶׁהָיוּ נִרְאִין מִבַּחוּץ וְאֵין נִרְאִין מִבִּפְנִים כְּשֵׁרָה:","לֹא הָיוּ לָהּ פְּצִימִין פְּסוּלָה מִפְּנֵי שֶׁהִיא סֻכָּה הָעֲשׂוּיָה כְּמָבוֹי שֶׁהֲרֵי אֵין לָהּ אֶלָּא שְׁנֵי צִדֵּי הָאַכְסַדְרָה וְאֶמְצַע הָאַכְסַדְרָה אֵין בּוֹ כֹּתֶל וְשֶׁכְּנֶגְדּוֹ אֵין בּוֹ פְּצִימִין:","סִכֵּךְ עַל גַּבֵּי מָבוֹי שֶׁיֵּשׁ לוֹ לֶחִי אוֹ עַל גַּבֵּי בְּאֵר שֶׁיֵּשׁ לָהּ פַּסִּין הֲרֵי זוֹ סֻכָּה כְּשֵׁרָה לְאוֹתָהּ שַׁבָּת שֶׁבְּתוֹךְ הֶחָג בִּלְבַד. מִתּוֹךְ שֶׁלֶּחִי זֶה וּפַסִּין אֵלּוּ מְחִצּוֹת לְעִנְיַן שַׁבָּת נַחְשֹׁב אוֹתָן כִּמְחִצּוֹת לְעִנְיַן סֻכָּה:","נָעַץ אַרְבָּעָה קֻנְדִּיסִין עַל אַרְבַּע זָוִיּוֹת הַגַּג וְסִכֵּךְ עַל גַּבָּן הוֹאִיל וְהַסִּכּוּךְ עַל שְׂפַת הַגַּג כָּשֵׁר וְרוֹאִין אֶת הַמְּחִצּוֹת הַתַּחְתּוֹנוֹת כְּאִלּוּ הֵן עוֹלוֹת לְמַעְלָה עַל שְׂפַת הַסִּכּוּךְ:","סֻכָּה שֶׁיֵּשׁ לָהּ פְּתָחִים רַבִּים וְיֵשׁ בִּכְתָלֶיהָ חַלּוֹנוֹת הַרְבֵּה הֲרֵי זוֹ כְּשֵׁרָה. וְאַף עַל פִּי שֶׁפָּרוּץ מְרֻבֶּה עַל הָעוֹמֵד. וּבִלְבַד שֶׁלֹּא יִהְיֶה שָׁם פֶּתַח יֶתֶר עַל עֶשֶׂר. אֲבָל אִם הָיָה שָׁם פֶּתַח יֶתֶר עַל עֶשֶׂר אַף עַל פִּי שֶׁיֵּשׁ לָהּ צוּרַת פֶּתַח צָרִיךְ שֶׁלֹּא יִהְיֶה הַפָּרוּץ מְרֻבֶּה עַל הָעוֹמֵד:","סֻכָּה שֶׁאֲוִירָהּ גָּבוֹהַּ מֵעֶשְׂרִים אַמָּה וּמִעֲטָהּ בְּכָרִים וּכְסָתוֹת אֵינוֹ מִעוּט וַאֲפִלּוּ בִּטְּלָם. מִעֲטָהּ בְּתֶבֶן וּבִטְּלוֹ הֲרֵי זֶה מִעוּט. וְאֵין צָרִיךְ לוֹמַר עָפָר וּבִטְּלוֹ. אֲבָל בֶּעָפָר סְתָם אֵינוֹ מִעוּט. הָיְתָה גְּבוֹהָה מֵעֶשְׂרִים אַמָּה וְהוּצִין יוֹרְדִין לְתוֹךְ עֶשְׂרִים אִם הָיְתָה צִלָּתָן מְרֻבָּה מֵחֲמָתָן יֵחָשְׁבוּ כְּגַג עָבֶה וּכְשֵׁרָה:","בָּנָה אִצְטַבָּה בָּהּ כְּנֶגֶד דֹּפֶן הָאֶמְצָעִית עַל פְּנֵי כֻּלָּהּ אִם יֵשׁ בָּאִצְטַבָּה שִׁעוּר רֹחַב הַסֻּכָּה כְּשֵׁרָה. בָּנָה אִצְטַבָּה כְּנֶגֶד דֹּפֶן הָאֶמְצָעִית מִן הַצַּד אִם יֵשׁ מִשְּׂפַת אִצְטַבָּה וְלַכֹּתֶל אַרְבַּע אַמּוֹת פְּסוּלָה פָּחוֹת מֵאַרְבַּע אַמּוֹת כְּשֵׁרָה. בָּנָה אִצְטַבָּה בְּאֶמְצָעָהּ אִם יֵשׁ מִשְּׂפַת אִצְטַבָּה וְלַכֹּתֶל אַרְבַּע אַמּוֹת לְכָל רוּחַ פְּסוּלָה. פָּחוֹת מֵאַרְבַּע אַמּוֹת כְּשֵׁרָה. וּכְאִלּוּ הַמְּחִצּוֹת נוֹגְעוֹת בָּאִצְטַבָּה וַהֲרֵי מִן הָאִצְטַבָּה וְעַד הַסִּכּוּךְ פָּחוֹת מֵעֶשְׂרִים אַמָּה. בָּנָה בָּהּ עַמּוּד וְיֵשׁ בּוֹ הֶכְשֵׁר סֻכָּה פְּסוּלָה. שֶׁאֵין אֵלּוּ מְחִצּוֹת הַנִּכָּרוֹת וְנִמְצָא עַל גַּב הָעַמּוּד סְכָךְ כָּשֵׁר בְּלֹא דְּפָנוֹת:","הָיְתָה פְּחוּתָה מֵעֲשָׂרָה וְחָקַק בָּהּ לְהַשְׁלִימָהּ לַעֲשָׂרָה. אִם יֵשׁ מִשְּׂפַת חֲקָק וְלַכֹּתֶל שְׁלֹשָׁה טְפָחִים פְּסוּלָה. פָּחוֹת מִכֵּן כְּשֵׁרָה. שֶׁכָּל פָּחוֹת מִשְּׁלֹשָׁה הֲרֵי הוּא כְּדָבוּק כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת שַׁבָּת:","דָּפְנֵי סֻכָּה כְּשֵׁרִין מִן הַכּל שֶׁאֵין אָנוּ צְרִיכִין אֶלָּא מְחִצָּה מִכָּל מָקוֹם וַאֲפִלּוּ מִבַּעֲלֵי חַיִּים. וְעוֹשֶׂה אָדָם אֶת חֲבֵרוֹ דֹּפֶן בְּיוֹם טוֹב כְּדֵי שֶׁיֹּאכַל וְיִשְׁתֶּה וְיִישַׁן בְּסֻכָּה כְּשֵׁרָה שֶׁחֲבֵרוֹ דֹּפֶן לָהּ. וְהוּא שֶׁיַּעֲשֶׂה אוֹתוֹ שֶׁלֹּא לְדַעַת זֶה שֶׁנַּעֲשָׂה דֹּפֶן. אֲבָל אִם עֲשָׂהוּ לְדַעַת אָסוּר בְּיוֹם טוֹב וּמֻתָּר בִּשְׁאָר יְמֵי הֶחָג. וְכֵן עוֹשֶׂה בְּכֵלִים דֹּפֶן רְבִיעִית בְּיוֹם טוֹב. אֲבָל דֹּפֶן שְׁלִישִׁית לֹא יַעֲשֶׂה אוֹתָהּ בְּכֵלִים בְּיוֹם טוֹב לְפִי שֶׁהוּא מַכְשִׁיר הַסֻּכָּה וְאֵין עוֹשִׂין אֹהֶל עֲרַאי בְּיוֹם טוֹב:"],"Mishneh Torah, Slaves 8":["הַמּוֹכֵר אֶת עַבְדּוֹ לְעַכּוּ\"ם יֵצֵא בֶּן חוֹרִין וְכוֹפִין אֶת רַבּוֹ לַחְזֹר וְלִקְנוֹתוֹ מִן הָעַכּוּ\"ם עַד עֲשָׂרָה בְּדָמָיו וְכוֹתֵב לוֹ גֵּט שִׁחְרוּר וְיוֹצֵא. וְאִם לֹא רָצָה הָעַכּוּ\"ם לְמָכְרוֹ אֲפִלּוּ בַּעֲשָׂרָה בְּדָמָיו אֵין מְחַיְּבִין אוֹתוֹ יֶתֶר. וּקְנָס זֶה אֵין גּוֹבִין אוֹתוֹ וְדָנִין אוֹתוֹ אֶלָּא בְּבֵית דִּין מֻמְחִין. וְאִם מֵת הַמּוֹכֵר אֵין קוֹנְסִין אֶת הַיּוֹרֵשׁ לְהַחְזִיר אֶת הָעֶבֶד לְשִׁחְרוּר:","לָוָה עַל עַבְדּוֹ מִן הָעַכּוּ\"ם אִם קָבַע לוֹ זְמַן וְאָמַר לוֹ אִם הִגִּיעַ זְמַן פְּלוֹנִי וְלֹא אֲשַׁלֵּם לְךָ תִּקְנֶה גּוּף עֶבֶד זֶה הֲרֵי זֶה יֵצֵא לְחֵרוּת מִיָּד. וְאִם אָמַר לוֹ תִּקְנֶה מַעֲשֵׂה יָדָיו לֹא יֵצֵא לְחֵרוּת. גְּבָאוֹ עַכּוּ\"ם בְּחוֹבוֹ אוֹ שֶׁבָּאוּ עַל הָאָדוֹן מְצֵרִים וּבִקְּשׁוּ לְהָרְגוֹ וּפָדָה עַצְמוֹ מִיָּדָן בְּעַבְדּוֹ לֹא יָצָא לְחֵרוּת מִפְּנֵי שֶׁנִּלְקַח מִמֶּנּוּ שֶׁלֹּא בִּרְצוֹנוֹ:","מָכַר עַבְדּוֹ לְאֶחָד מֵעַבְדֵי הַמֶּלֶךְ אוֹ מִגְּדוֹלָיו אַף עַל פִּי שֶׁהוּא מִתְיָרֵא מֵהֶם יָצָא הָעֶבֶד לְחֵרוּת מִפְּנֵי שֶׁהָיָה יָכוֹל לְפַיְּסוֹ בְּמָמוֹן אַחֵר:","מְכָרוֹ לְעַכּוּ\"ם לִשְׁלֹשִׁים יוֹם. מְכָרוֹ חוּץ מִמְּלַאכְתּוֹ. חוּץ מִן הַמִּצְוֹת. חוּץ מִשַּׁבָּתוֹת וְיָמִים טוֹבִים. הֲרֵי זֶה סָפֵק אִם נִשְׁתַּחְרֵר אוֹ לֹא נִשְׁתַּחְרֵר. לְפִיכָךְ אִם תָּפַס הָעֶבֶד כְּדֵי דָּמָיו לְרַבּוֹ כְּדֵי שֶׁיֵּצֵא בָּהֶן לְחֵרוּת מִיַּד עַכּוּ\"ם אֵין מוֹצִיאִין מִיָּדוֹ:","אֶחָד מוֹכֵר עַבְדּוֹ לְעַכּוּ\"ם עוֹבֵד עֲבוֹדָה זָרָה אוֹ שֶׁמְּכָרוֹ לְגֵר תּוֹשָׁב אֲפִלּוּ לְכוּתִי הֲרֵי זֶה יֵצֵא לְחֵרוּת. מְכָרוֹ לְיִשְׂרָאֵל מוּמָר הֲרֵי זֶה סָפֵק לְפִיכָךְ אִם תָּפַס כְּדֵי דָּמָיו מֵרַבּוֹ רִאשׁוֹן כְּדֵי לָצֵאת בָּהֶן מִיַּד הַמּוּמָר אֵין מוֹצִיאִין מִיָּדוֹ:","הַמּוֹכֵר עַבְדּוֹ לְחוּצָה לָאָרֶץ יָצָא בֶּן חוֹרִין וְכוֹפִין אֶת רַבּוֹ הַשֵּׁנִי לִכְתֹּב לוֹ גֵּט שִׁחְרוּר וְאָבְדוּ הַדָּמִים. וּמִפְּנֵי מָה קָנְסוּ כָּאן הַלּוֹקֵחַ לְבַדּוֹ שֶׁאִלּוּ לֹא לָקַח זֶה לֹא יָצָא הָעֶבֶד לְחוּצָה לָאָרֶץ. הַמּוֹכֵר עַבְדּוֹ לְסוּרְיָא וַאֲפִלּוּ לְעַכּוֹ כְּמוֹכֵר לְחוּצָה לָאָרֶץ:","בֶּן בָּבֶל שֶׁנָּשָׂא אִשָּׁה בְּאֶרֶץ יִשְׂרָאֵל וְדַעְתּוֹ לַחְזֹר וְהִכְנִיסָה לוֹ אִשְׁתּוֹ עֲבָדִים וּשְׁפָחוֹת הֲרֵי אֵלּוּ סָפֵק אִם הֵם כְּמִי שֶׁמָּכְרָה אוֹתָם לְחוּצָה לָאָרֶץ הוֹאִיל וְיֵשׁ לוֹ הַפֵּרוֹת אוֹ אֵינָן כִּמְכוּרִין לוֹ שֶׁהֲרֵי הַגּוּף שֶׁלָּהּ:","עֶבֶד שֶׁיָּצָא אַחַר רַבּוֹ לְסוּרְיָא וּמְכָרוֹ שָׁם אִבֵּד אֶת זְכוּתוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁיָּצָא רַבּוֹ עַל מְנָת שֶׁלֹּא לַחְזֹר לְאֶרֶץ יִשְׂרָאֵל. אֲבָל אִם דַּעַת רַבּוֹ לַחְזֹר וְיָצָא אַחֲרָיו וּמְכָרוֹ שָׁם יָצָא לְחֵרוּת וְכוֹפִין אֶת הַלּוֹקֵחַ לְשַׁחְרְרוֹ:","עֶבֶד שֶׁאָמַר לַעֲלוֹת לְאֶרֶץ יִשְׂרָאֵל כּוֹפִין אֶת רַבּוֹ לַעֲלוֹת עִמּוֹ אוֹ יִמְכֹּר אוֹתוֹ לְמִי שֶׁיַּעֲלוּהוּ לְשָׁם. רָצָה הָאָדוֹן לָצֵאת לְחוּצָה לָאָרֶץ אֵינוֹ יָכוֹל לְהוֹצִיא אֶת עַבְדּוֹ עַד שֶׁיִּרְצֶה. וְדִין זֶה בְּכָל זְמַן אֲפִלּוּ בַּזְּמַן הַזֶּה שֶׁהָאָרֶץ בְּיַד עַכּוּ\"ם:","עֶבֶד שֶׁבָּרַח מִחוּצָה לָאָרֶץ לָאָרֶץ אֵין מַחֲזִירִין לוֹ לְעַבְדוּת וְעָלָיו נֶאֱמַר (דברים כג טז) \"לֹא תַסְגִּיר עֶבֶד אֶל אֲדֹנָיו\". וְאוֹמֵר לְרַבּוֹ שֶׁיִּכְתֹּב לוֹ גֵּט שִׁחְרוּר וְיִכְתֹּב לוֹ שְׁטַר חוֹב בְּדָמָיו עַד שֶׁתַּשִּׂיג יָדוֹ וְיִתֵּן לוֹ. וְאִם לֹא רָצָה הָאָדוֹן לְשַׁחְרְרוֹ מַפְקִיעִין בֵּית דִּין שִׁעְבּוּדוֹ מֵעָלָיו וְיֵלֵךְ לוֹ:","עֶבֶד זֶה שֶׁבָּרַח לָאָרֶץ הֲרֵי הוּא גֵּר צֶדֶק וְהוֹסִיף לוֹ הַכָּתוּב אַזְהָרָה אַחֶרֶת לְמִי שֶׁמְּאַנֶּה אוֹתוֹ מִפְּנֵי שֶׁהוּא שְׁפַל רוּחַ יוֹתֵר מִן הַגֵּר וְצִוָּה עָלָיו הַכָּתוּב שֶׁנֶּאֱמַר (דברים כג יז) \"עִמְּךָ יֵשֵׁב בְּקִרְבְּךָ\" (דברים כג יז) \"בְּאַחַד שְׁעָרֶיךָ\" (דברים כג יז) \"בַּטּוֹב לוֹ לֹא תּוֹנֶנּוּ\". זוֹ אַף הוֹנָיַת דְּבָרִים. נִמְצֵאתָ לָמֵד שֶׁהַמְאַנֶּה אֶת הַגֵּר הַזֶּה עוֹבֵר בִּשְׁלֹשָׁה לָאוִין מִשּׁוּם (ויקרא כה יז) \"וְלֹא תוֹנוּ אִישׁ אֶת עֲמִיתוֹ\" וּמִשּׁוּם (שמות כב כ) \"וְגֵר לֹא תוֹנֶה\" וּמִשּׁוּם לֹא תּוֹנֶנּוּ. וְכֵן עוֹבֵר מִשּׁוּם (שמות כב כ) \"וְלֹא תִלְחָצֶנּוּ\" כְּמוֹ שֶׁבֵּאַרְנוּ בְּעִנְיַן הוֹנָיָה:","הַקּוֹנֶה עֶבֶד מִן הָעַכּוּ\"ם סְתָם וְלֹא רָצָה לָמוּל וּלְקַבֵּל מִצְוֹת הָעֲבָדִים מְגַלְגְּלִין עִמּוֹ כָּל שְׁנֵים עָשָׂר חֹדֶשׁ וְאִם לֹא רָצָה חוֹזֵר וּמוֹכְרוֹ לְעַכּוּ\"ם אוֹ לְחוּצָה לָאָרֶץ. וְאִם הִתְנָה הָעֶבֶד עָלָיו תְּחִלָּה שֶׁלֹּא יָמוּל הֲרֵי זֶה מֻתָּר לְקַיְּמוֹ כָּל זְמַן שֶׁיִּרְצֶה בְּגֵיוּתוֹ וּמוֹכְרוֹ לְעַכּוּ\"ם אוֹ לְחוּצָה לָאָרֶץ. וְכֵן עֶבֶד שֶׁמָּל וְטָבַל לְשֵׁם עַבְדוּת וְאַחַר כָּךְ הִפִּיל עַצְמוֹ לִגְיָסוֹת וְאֵין רַבּוֹ יָכוֹל לְהוֹצִיאוֹ לֹא בְּדִינֵי יִשְׂרָאֵל וְלֹא בְּדִינֵי אֻמּוֹת הָעוֹלָם הֲרֵי זֶה מֻתָּר לוֹ לִטּל דָּמָיו מִן הָעַכּוּ\"ם וְכוֹתֵב וּמַעֲלֶה בְּעַרְכָּאוֹת שֶׁל עַכּוּ\"ם מִפְּנֵי שֶׁהוּא כְּמַצִּיל מִיָּדָם:","הַמַּפְקִיר עַבְדּוֹ יָצָא לְחֵרוּת וְצָרִיךְ גֵּט שִׁחְרוּר. וְאִם מֵת הָאָדוֹן שֶׁהִפְקִירוֹ הַיּוֹרֵשׁ כּוֹתֵב לוֹ גֵּט שִׁחְרוּר:","עֶבֶד שֶׁבָּרַח מִבֵּית הָאֲסוּרִין אִם נִתְיָאֵשׁ מִמֶּנּוּ רַבּוֹ יָצָא לְחֵרוּת וְכוֹפִין אֶת רַבּוֹ וְכוֹתֵב לוֹ גֵּט שִׁחְרוּר:","עֶבֶד שֶׁנִּשְׁבָּה אִם נִתְיָאֵשׁ מִמֶּנּוּ רַבּוֹ רִאשׁוֹן כָּל הַפּוֹדֶה אוֹתוֹ לְשֵׁם עֶבֶד יִשְׁתַּעְבֵּד בּוֹ וַהֲרֵי הוּא שֶׁלּוֹ. וְאִם פָּדָהוּ לְשֵׁם בֶּן חוֹרִין הֲרֵי זֶה בֶּן חוֹרִין. וְאִם לֹא נִתְיָאֵשׁ מִמֶּנּוּ רַבּוֹ רִאשׁוֹן הַפּוֹדֶה אוֹתוֹ לְשֵׁם עֶבֶד נוֹטֵל פִּדְיוֹנוֹ מֵרַבּוֹ וְחוֹזֵר לְרַבּוֹ. וְאִם פָּדָהוּ לְשֵׁם בֶּן חוֹרִין חוֹזֵר לְרַבּוֹ הָרִאשׁוֹן בְּלֹא כְּלוּם:","עֶבֶד שֶׁעֲשָׂאוֹ רַבּוֹ אַפּוֹתֵיקֵי לְבַעַל חוֹבוֹ וְשִׁחְרְרוֹ הֲרֵי זֶה מְשֻׁחְרָר וְכוֹפִין אֶת בַּעַל חוֹבוֹ לְשַׁחְרְרוֹ. גַּם זֶה מִפְּנֵי תִּקּוּן הָעוֹלָם שֶׁלֹּא יִפְגַּע בּוֹ לְאַחַר זְמַן וְיֹאמַר לוֹ עַבְדִּי אַתָּה:","עֶבֶד שֶׁהִשִּׂיאוֹ רַבּוֹ בַּת חוֹרִין אוֹ שֶׁהִנִּיחַ לוֹ רַבּוֹ תְּפִלִּין בְּרֹאשׁוֹ אוֹ שֶׁאָמַר לוֹ רַבּוֹ לִקְרוֹת שְׁלֹשָׁה פְּסוּקִין בְּסֵפֶר תּוֹרָה בִּפְנֵי צִבּוּר. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ הַדְּבָרִים שֶׁאֵינוֹ חַיָּב בָּהֶן אֶלָּא בֶּן חוֹרִין יֵצֵא לְחֵרוּת וְכוֹפִין אֶת רַבּוֹ לִכְתֹּב לוֹ גֵּט שִׁחְרוּר. וְכֵן אִם נָדַר נֵדֶר שֶׁכּוֹפִין עָלָיו אֶת הָעֲבָדִים כְּמוֹ שֶׁבֵּאַרְנוּ בִּנְדָרִים וְאָמַר לוֹ רַבּוֹ מוּפָר לְךָ יֵצֵא לְחֵרוּת שֶׁכֵּיוָן שֶׁלֹּא כָּפָה אוֹתוֹ בְּמָקוֹם שֶׁיֵּשׁ לוֹ לִכְפּוֹתוֹ גִּלָּה דַּעְתּוֹ שֶׁהִפְקִיעַ שִׁעְבּוּדוֹ. מִכָּאן אֲנִי אוֹמֵר שֶׁהַמְשַׁחְרֵר עַבְדּוֹ בְּכָל לָשׁוֹן וְהוֹצִיא דְּבָרִים מִפִּיו שֶׁמַּשְׁמָעָן שֶׁלֹּא נִשְׁאַר לוֹ עָלָיו שִׁעְבּוּד כְּלָל וְשֶׁגָּמַר בְּלִבּוֹ לְדָבָר זֶה שֶׁאֵינוֹ יָכוֹל לַחְזֹר בּוֹ כּוֹפִין אוֹתוֹ לִכְתֹּב לוֹ גֵּט שִׁחְרוּר אַף עַל פִּי שֶׁעֲדַיִן לֹא כָּתַב. אֲבָל אִם לָוָה מֵעַבְדּוֹ אוֹ שֶׁעָשָׂהוּ אַפּוֹטְרוֹפּוֹס אוֹ שֶׁהִנִּיחַ תְּפִלִּין בִּפְנֵי רַבּוֹ אוֹ שֶׁקָּרָא שְׁלֹשָׁה פְּסוּקִים בְּבֵית הַכְּנֶסֶת בִּפְנֵי רַבּוֹ וְלֹא מִחָה בּוֹ לֹא יֵצֵא לְחֵרוּת:","וְאָסוּר לְאָדָם לְלַמֵּד אֶת עַבְדּוֹ תּוֹרָה וְאִם לִמְּדוֹ לֹא יָצָא לְחֵרוּת:","הַלּוֹקֵחַ עֶבֶד מִן הָעַכּוּ\"ם וְקָדַם הָעֶבֶד וְטָבַל בִּפְנֵי רַבּוֹ לְשֵׁם בֶּן חוֹרִין יָצָא לְחֵרוּת. שֶׁלֹּא בִּפְנֵי רַבּוֹ צָרִיךְ לְפָרֵשׁ לְפִיכָךְ צָרִיךְ רַבּוֹ לְתָקְפּוֹ בַּמַּיִם:","יִשְׂרָאֵל שֶׁתָּקַף עַכּוּ\"ם קָטָן אוֹ מָצָא תִּינוֹק עַכּוּ\"ם וְהִטְבִּילוֹ לְשֵׁם גֵּר הֲרֵי זֶה גֵּר. לְשֵׁם עֶבֶד הֲרֵי זֶה עֶבֶד. לְשֵׁם בֶּן חוֹרִין הֲרֵי זֶה בֶּן חוֹרִין:","גֵּר שֶׁקָּדְמוּ עֲבָדָיו וְשִׁפְחוֹתָיו וְטָבְלוּ לְפָנָיו קָנוּ עַצְמָן בְּנֵי חוֹרִין:"],"Mishneh Torah, Tefillin, Mezuzah and the Torah Scroll 6":["עֲשָׂרָה תְּנָאִין יֵשׁ בַּבַּיִת וְאַחַר כָּךְ יִתְחַיֵּב הַדָּר בּוֹ לַעֲשׂוֹת לוֹ מְזוּזָה. וְאִם חָסֵר תְּנַאי אֶחָד מֵהֶן פָּטוּר מִן הַמְּזוּזָה. וְאֵלּוּ הֵן. שֶׁיִּהְיֶה בּוֹ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת אוֹ יָתֵר. וְשֶׁתִּהְיֶינָה לוֹ שְׁתֵּי מְזוּזוֹת. וְיִהְיֶה לוֹ מַשְׁקוֹף. וְתִהְיֶה לוֹ תִּקְרָה. וְיִהְיוּ לוֹ דְּלָתוֹת. וְיִהְיֶה הַשַּׁעַר גָּבוֹהַּ עֲשָׂרָה טְפָחִים אוֹ יוֹתֵר. וְיִהְיֶה הַבַּיִת חֹל. וְיִהְיֶה עָשׂוּי לְדִירַת אָדָם. וְעָשׂוּי לְדִירַת כָּבוֹד. וְעָשׂוּי לְדִירַת קֶבַע:","בַּיִת שֶׁאֵין לוֹ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת פָּטוּר מִן הַמְּזוּזָה. וְאִם יֵשׁ בּוֹ כְּדֵי לְרַבֵּעַ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת בְּשָׁוֶה אַף עַל פִּי שֶׁהוּא עָגל אוֹ בַּעַל חָמֵשׁ זָוִיּוֹת וְאֵין צָרִיךְ לוֹמַר שֶׁאִם הָיָה אָרְכּוֹ יָתֵר עַל רָחְבּוֹ הוֹאִיל וְיֵשׁ בּוֹ לְרַבֵּעַ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת חַיָּב בִּמְזוּזָה:","אַכְסַדְרָה וְהוּא הַמָּקוֹם שֶׁיֵּשׁ לוֹ שְׁלֹשָׁה כְּתָלִים וְתִקְרָה אַף עַל פִּי שֶׁיֵּשׁ לָהּ שְׁנֵי פַּצִּימִין בְּרוּחַ רְבִיעִית פְּטוּרָה מִן הַמְּזוּזָה. מִפְּנֵי שֶׁהַפַּצִּימִין לְהַעֲמִיד הַתִּקְרָה הֵם עֲשׂוּיִים וְלֹא מִשּׁוּם מְזוּזוֹת נַעֲשׂוּ. וְכֵן הַתִּקְרָה שֶׁאֵין לָהּ כְּתָלִים אֶלָּא עוֹמֶדֶת עַל עַמּוּדִים מִכָּאן וּמִכָּאן אַף עַל פִּי שֶׁהִיא כְּתַבְנִית בַּיִת פְּטוּרָה לְפִי שֶׁאֵין לָהּ מְזוּזוֹת. שֶׁאֵלּוּ הָעַמּוּדִים לְהַעֲמִיד הַתִּקְרָה הֵן עֲשׂוּיִין:","בַּיִת שֶׁיֵּשׁ לוֹ מְזוּזָה מִכָּאן וּמִכָּאן וְכִפָּה כְּמִין קֶשֶׁת עַל שְׁתֵּי הַמְּזוּזוֹת בִּמְקוֹם הַמַּשְׁקוֹף. אִם יֵשׁ בְּגֹבַהּ הַמְּזוּזוֹת עֲשָׂרָה טְפָחִים אוֹ יָתֵר חַיָּב בִּמְזוּזָה. וְאִם אֵין בָּהֶן עֲשָׂרָה טְפָחִים פְּטוּרִין מִפְּנֵי שֶׁאֵין לוֹ מַשְׁקוֹף:","בַּיִת שֶׁאֵין לוֹ תִּקְרָה פָּטוּר מִן הַמְּזוּזָה. הָיָה מִקְצָתוֹ מְקֹרֶה וּמִקְצָתוֹ אֵינוֹ מְקֹרֶה יֵרָאֶה לִי שֶׁאִם הָיָה הַקֵּרוּי כְּנֶגֶד הַפֶּתַח שֶׁהוּא חַיָּב בִּמְזוּזָה וּמַעֲמִידִין הַדְּלָתוֹת וְאַחַר כָּךְ קוֹבְעִין אֶת הַמְּזוּזָה:","הַר הַבַּיִת הַלְּשָׁכוֹת וְהָעֲזָרוֹת וּבָתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת שֶׁאֵין בָּהֶן בֵּית דִּירָה פְּטוּרִין לְפִי שֶׁהֵן קֹדֶשׁ. בֵּית הַכְּנֶסֶת שֶׁל כְּפָרִים שֶׁהָאוֹרְחִין דָּרִין בּוֹ חַיָּב בִּמְזוּזָה. וְכֵן בֵּית הַכְּנֶסֶת שֶׁל כְּרַכִּין אִם הָיָה בּוֹ בֵּית דִּירָה חַיָּב. כָּל הַשְּׁעָרִים שֶׁהָיוּ בַּמִּקְדָּשׁ לֹא הָיָה לָהֶם מְזוּזוֹת חוּץ מִשַּׁעַר נִקָּנוֹר וְשֶׁלְּפָנִים מִמֶּנּוּ. וְשֶׁל לִשְׁכַּת פַּרְהֶדְרִין מִפְּנֵי שֶׁהַלִּשְׁכָּה הַזֹּאת הָיְתָה בֵּית דִּירָה לְכֹהֵן גָּדוֹל בְּשִׁבְעַת יְמֵי הַהַפְרָשָׁה:","בֵּית הַתֶּבֶן בֵּית הַבָּקָר בֵּית הָעֵצִים בֵּית אוֹצָרוֹת פְּטוּרִין מִן הַמְּזוּזָה, שֶׁנֶּאֱמַר בֵּיתֶךָ, בֵּיתְךָ הַמְיֻחָד לְךָ, פְּרַט לְאֵלּוּ וְכַיּוֹצֵא בָּהֶן. לְפִיכָךְ רֶפֶת הַבָּקָר שֶׁהַנָּשִׁים יוֹשְׁבוֹת בָּהּ וּמִתִקַשִּׁטוֹת בָּהּ חַיָּבוֹת בִּמִזוּזָה שֵׁהֲרֵי יֵשׁ בָּהּ יִחוּד לְדִירַת אָדָם. בֵּית שַׁעַר אַכְסַדְרָה וּמִרְפֶּסֶת וְהַגִּנָּה וְהַדִּיר פְּטוּרִין מִן הַמְּזוּזָה מִפְּנֵי שֶׁאֵינָם עֲשׂוּיִין לְדִירָה. אִם הָיוּ בָּתִּים הַחַיָּבִין בִּמְזוּזָה פְּתוּחִין לִמְקוֹמוֹת אֵלּוּ חַיָּבִין בִּמְזוּזָה:","לְפִיכָךְ אֶחָד שַׁעֲרֵי חֲצֵרוֹת וְאֶחָד שַׁעֲרֵי מְבוֹאוֹת וְאֶחָד שַׁעֲרֵי מְדִינוֹת וַעֲיָרוֹת הַכּל חַיָּבִים בִּמְזוּזָה שֶׁהֲרֵי הַבָּתִּים הַחַיָּבִין בִּמְזוּזָה פְּתוּחִין לְתוֹכָן. אֲפִלּוּ עֲשָׂרָה בָּתִּים זֶה פָּתוּחַ לְזֶה וְזֶה פָּתוּחַ לְזֶה הוֹאִיל וְהַפְּנִימִי חַיָּב בִּמְזוּזָה כֻּלָּן חַיָּבִין. וּמִפְּנֵי זֶה אָמְרוּ שַׁעַר הַפָּתוּחַ מִן הַגִּנָּה לֶחָצֵר חַיָּב בִּמְזוּזָה:","בֵּית הַכִּסֵּא וּבֵית הַמֶּרְחָץ וּבֵית הַטְּבִילָה וּבֵית הַבֻּרְסְקִי וְכַיּוֹצֵא בָּהֶם פְּטוּרִין מִן הַמְּזוּזָה לְפִי שֶׁאֵינָן עֲשׂוּיִין לְדִירַת כָּבוֹד. סֻכַּת חַג בֶּחָג וּבַיִת שֶׁבַּסְּפִינָה פְּטוּרִין מִן הַמְּזוּזָה לְפִי שֶׁאֵינָן עֲשׂוּיִין לְדִירַת קֶבַע. שְׁתֵּי סֻכּוֹת שֶׁל יוֹצְרִים זוֹ לְפָנִים מִזּוֹ הַחִיצוֹנָה פְּטוּרָה מִן הַמְּזוּזָה לְפִי שֶׁאֵינָהּ קְבוּעָה. הַחֲנֻיּוֹת שֶׁבַּשְּׁוָקִים פְּטוּרִין מִפְּנֵי שֶׁאֵינָן קְבוּעִים לְדִירָה:","בַּיִת שֶׁיֵּשׁ לוֹ פְּתָחִים הַרְבֵּה אַף עַל פִּי שֶׁאֵינוֹ רָגִיל לָצֵאת וְלָבוֹא אֶלָּא בְּאַחַת מֵהֶן חַיָּב לַעֲשׂוֹת מְזוּזָה בְּכָל פֶּתַח וּפֶתַח. פֶּתַח קָטָן שֶׁבֵּין בַּיִת לַעֲלִיָּה חַיָּב בִּמְזוּזָה. חֶדֶר שֶׁבַּבַּיִת אֲפִלּוּ חֶדֶר בְּחֶדֶר חַיָּב לַעֲשׂוֹת מְזוּזָה עַל שַׁעַר הַחֶדֶר הַפְּנִימִי וְעַל שַׁעַר הַחֶדֶר הַחִיצוֹן וְעַל שַׁעַר הַבַּיִת שֶׁכֻּלָּן עֲשׂוּיִין לְדִירָה וּקְבוּעִין:","פֶּתַח שֶׁבֵּין בֵּית הַמִּדְרָשׁ אוֹ בֵּין בֵּית הַכְּנֶסֶת וּבֵיתוֹ אִם רָגִיל לָצֵאת וְלָבוֹא בְּאוֹתוֹ הַפֶּתַח חַיָּב בִּמְזוּזָה. פֶּתַח שֶׁבֵּין שְׁנֵי בָּתִּים הוֹלְכִין אַחַר הַצִּיר שֶׁל דֶּלֶת, מָקוֹם שֶׁהַצִּיר נִרְאֶה עִמּוֹ שָׁם קוֹבְעִים אֶת הַמְּזוּזָה:","וְהֵיכָן קוֹבְעִים אֶת הַמְּזוּזָה. בְּתוֹךְ חָלָל שֶׁל פָּתַח בַּטֶּפַח הַסָּמוּךְ לַחוּץ בִּתְחִלַּת שְׁלִישׁ הָעֶלְיוֹן שֶׁל גֹּבַהּ הַשַּׁעַר. וְאִם קְבָעָהּ לְמַעְלָה מִזֶּה כְּשֵׁרָה. וְהוּא שֶׁיַּרְחִיקֶנָּה מִן הַמַּשְׁקוֹף טֶפַח. וְצָרִיךְ לְקָבְעָהּ עַל יְמִין הַנִּכְנָס לַבַּיִת וְאִם קְבָעָהּ מִשְּׂמֹאל פְּסוּלָה. וּבַיִת שֶׁל שֻׁתָּפִין חַיָּב בִּמְזוּזָה:","חַיָּב אָדָם לְהִזָּהֵר בִּמְזוּזָה מִפְּנֵי שֶׁהִיא חוֹבַת הַכּל תָּמִיד. וְכָל זְמַן שֶׁיִּכָּנֵס וְיֵצֵא יִפְגַּע בְּיִחוּד הַשֵּׁם שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְיִזְכֹּר אַהֲבָתוֹ וְיֵעוֹר מִשְּׁנָתוֹ וְשִׁגְיוֹתָיו בְּהַבְלֵי הַזְּמַן. וְיֵדַע שֶׁאֵין דָּבָר הָעוֹמֵד לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים אֶלָּא יְדִיעַת צוּר הָעוֹלָם. וּמִיָּד הוּא חוֹזֵר לְדַעְתּוֹ וְהוֹלֵךְ בְּדַרְכֵי מֵישָׁרִים. אָמְרוּ חֲכָמִים הָרִאשׁוֹנִים כָּל מִי שֶׁיֵּשׁ לוֹ תְּפִלִּין בְּרֹאשׁוֹ וּבִזְרוֹעוֹ וְצִיצִית בְּבִגְדוֹ וּמְזוּזָה בְּפִתְחוֹ מֻחְזָק הוּא שֶׁלֹּא יֶחֱטָא שֶׁהֲרֵי יֵשׁ לוֹ מַזְכִּירִין רַבִּים וְהֵן הֵם הַמַּלְאָכִים שֶׁמַּצִּילִין אוֹתוֹ מִלַּחֲטֹא שֶׁנֶּאֱמַר (תהילים לד ח) ״חֹנֶה מַלְאַךְ יְיָ׳‎ סָבִיב לִירֵאָיו וַיְחַלְּצֵם״:"],"Mishneh Torah, Testimony 17":["מִי שֶׁהֵעִידוּ לוֹ אֲנָשִׁים רַבִּים וּגְדוֹלִים בְּחָכְמָה וּבְיִרְאָה שֶׁהֵם אוֹמְרִים שֶׁרָאוּ פְּלוֹנִי שֶׁעָבַר עֲבֵרָה פְּלוֹנִית. אוֹ שֶׁלָּוָה מִפְּלוֹנִי. אַף עַל פִּי שֶׁהוּא מַאֲמִין הַדָּבָר בְּלִבּוֹ כְּאִלּוּ רָאָהוּ לֹא יָעִיד עַד שֶׁיִּרְאֶה הַדָּבָר בְּעֵינָיו אוֹ יוֹדֶה לוֹ הַלּוֶֹה מִפִּיו וְיֹאמַר לוֹ הֱיֵה עָלַי עֵד שֶׁפְּלוֹנִי הִלְוָה לִי מָנֶה. שֶׁנֶּאֱמַר (ויקרא ה א) \"וְהוּא עֵד אוֹ רָאָה אוֹ יָדָע\". וְאֵין לְךָ עֵדוּת שֶׁמִּתְקַיֶּמֶת בִּרְאִיָּה אוֹ בִּידִיעָה אֶלָּא עֵדוּת מָמוֹן. וְכָל הַמֵּעִיד מִפִּי אֲחֵרִים הֲרֵי זֶה עֵד שֶׁקֶר וְעוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (שמות כ יג) \"לֹא תַעֲנֶה בְרֵעֲךָ עֵד שָׁקֶר\":","לְפִיכָךְ מְאַיְּמִין אַף עַל עֵדֵי הַמָּמוֹן. וְכֵיצַד מְאַיְּמִין עֲלֵיהֶן. [מְאַיְּמִין עֲלֵיהֶם] בִּפְנֵי הַכּל. וּמוֹדִיעִין אוֹתָן כֹּחַ עֵדוּת שֶׁקֶר וּבֹשֶׁת הַמֵּעִיד בָּהּ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וְאַחַר כָּךְ מוֹצִיאִין אֶת כָּל הָאָדָם לַחוּץ וּמְשַׁיְּרִין אֶת הַגָּדוֹל שֶׁבָּעֵדִים וְאוֹמֵר לוֹ אֱמֹר הֵיאַךְ אַתָּה יוֹדֵעַ שֶׁזֶּה חַיָּב לָזֶה. אִם אָמַר שֶׁהוּא אָמַר לִי חַיָּב אֲנִי לוֹ אוֹ אִישׁ פְּלוֹנִי אָמַר לִי שֶׁהוּא חַיָּב לוֹ לֹא אָמַר כְּלוּם עַד שֶׁיֹּאמַר בְּפָנֵינוּ הוֹדָה לוֹ שֶׁהוּא חַיָּב לוֹ. וְהָיוּ מַכְנִיסִין אֶת הָעֵד הַשֵּׁנִי וּבוֹדְקִין אוֹתוֹ כָּךְ. נִמְצְאוּ דִּבְרֵיהֶן מְכֻוָּנִין נוֹשְׂאִין וְנוֹתְנִין בַּדָּבָר וְגוֹמְרִין הַדִּין:","הַמַּטְמִין עֵדִים לַחֲבֵרוֹ וְהוֹדָה לוֹ בֵּינוֹ לְבֵין עַצְמוֹ וְהָעֵדִים רוֹאִין וְשׁוֹמְעִין שֶׁהוּא אוֹמֵר לוֹ וַדַּאי יֵשׁ לְךָ אֶצְלִי כָּךְ וְכָךְ אֲבָל מִתְיָרֵא אֲנִי שֶׁמָּא תְּכוּפֵנִי בְּדִין לְמָחָר הֲרֵי זוֹ אֵינָהּ עֵדוּת עַד שֶׁיּוֹדֶה בִּפְנֵי עֵדִים:","אֶחָד הַמּוֹדֶה בִּפְנֵי עֵדִים. וְאָמַר דֶּרֶךְ הוֹדָאָה זֶה יֵשׁ לוֹ אֶצְלִי כָּךְ וְכָךְ. אוֹ שֶׁאָמַר אַתֶּם עֵדַי אוֹ שֶׁאָמַר הֱיוּ עָלַי עֵדִים. בֵּין שֶׁאָמַר הַלּוֶֹה בֵּין שֶׁאָמַר הַמַּלְוֶה וְשָׁתַק הַלּוֶֹה דֶּרֶךְ מַאֲמִין לִדְבָרָיו. הֲרֵי אֵלּוּ עֵדִים. וְאֵין צָרִיךְ לוֹמַר אִם קָנוּ מִיָּדוֹ אוֹ שֶׁאָמַר לָהֶם כִּתְבוּ עָלַי שְׁטָר שֶׁיֵּשׁ לָזֶה אֶצְלִי כָּךְ וְכָךְ וְכָל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ הֲרֵי הֵם הוֹדָאָה וּמְעִידִין עַל פִּיו:","תַּלְמִיד שֶׁאָמַר לוֹ רַבּוֹ יוֹדֵעַ אַתָּה שֶׁאִם נוֹתְנִין לִי כָּל מָמוֹן הָעוֹלָם אֵינִי מְשַׁקֵּר מָנֶה יֵשׁ לִי אֵצֶל פְּלוֹנִי וְיֵשׁ לִי עָלָיו עֵד אֶחָד לֵךְ וְהִצְטָרֵף עִמּוֹ. אִם נִצְטָרֵף הֲרֵי זֶה עֵד שֶׁקֶר:","אָמַר לוֹ בּוֹא וַעֲמֹד עִם הָעֵד וְלֹא תָּעִיד כְּדֵי שֶׁיִּרְאֶה הַלּוֶֹה וִיפַחֵד וְיַעֲלֶה עַל דַּעְתּוֹ שֶׁאַתֶּם שְׁנֵי עֵדִים וְיוֹדֶה מֵעַצְמוֹ הֲרֵי זֶה אָסוּר לַעֲמֹד וּלְהַרְאוֹת שֶׁהוּא עֵד אַף עַל פִּי שֶׁאֵינוֹ מֵעִיד. וְעַל זֶה וְכַיּוֹצֵא בּוֹ נֶאֱמַר (שמות כג ז) \"מִדְּבַר שֶׁקֶר תִּרְחָק\":","הַשּׂוֹכֵר עֵדֵי שֶׁקֶר לְהָעִיד לַחֲבֵרוֹ פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. וְכֵן עֵד אֶחָד שֶׁכָּבַשׁ עֵדוּתוֹ וְלֹא הֵעִיד פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם:"],"Mishneh Torah, Testimony 8":["מִי שֶׁחָתַם עַל הַשְּׁטָר וּבָא לְהָעִיד עַל כְּתַב יָדוֹ בְּבֵית דִּין וְהִכִּיר כְּתַב יָדוֹ שֶׁזֶּהוּ בְּוַדַּאי אֲבָל אֵינוֹ זוֹכֵר הָעֵדוּת כְּלָל וְלֹא יִמָּצֵא בְּלִבּוֹ זִכָּרוֹן כְּלָל שֶׁזֶּה לָוָה מִזֶּה לְעוֹלָם. הֲרֵי זֶה אָסוּר לְהָעִיד עַל כְּתַב יָדוֹ שֶׁהוּא זֶה בְּבֵית דִּין. שֶׁאֵין אָדָם מֵעִיד עַל כְּתַב יָדוֹ שֶׁהוּא זֶה אֶלָּא עַל הַמָּמוֹן שֶׁבַּשְּׁטָר הוּא מֵעִיד שֶׁזֶּה חַיָּב לָזֶה. וּכְתַב יָדוֹ הוּא כְּדֵי לְהַזְכִּירוֹ הַדָּבָר אֲבָל אִם לֹא נִזְכַּר לֹא יָעִיד:","אֶחָד הַזּוֹכֵר אֶת הָעֵדוּת וְאֶחָד שֶׁרָאָה כְּתַב יָדוֹ אוֹ שֶׁהִזְכִּירוּהוּ אֲחֵרִים וְנִזְכַּר. אֲפִלּוּ הִזְכִּירוֹ הָעֵד הַשֵּׁנִי שֶׁהֵעִיד אִם נִזְכַּר הֲרֵי זֶה מֵעִיד. אֲבָל אִם הִזְכִּיר אוֹתוֹ הַתּוֹבֵעַ עַצְמוֹ אַף עַל פִּי שֶׁנִּזְכַּר אֵינוֹ מֵעִיד מִפְּנֵי שֶׁזֶּה דּוֹמֶה בְּעֵינֵי בַּעַל דִּין כְּאִלּוּ הֵעִיד שֶׁקֶר בְּדָבָר שֶׁלֹּא יָדַע:","לְפִיכָךְ אִם הָיָה הַתּוֹבֵעַ תַּלְמִיד חָכָם וְהִזְכִּיר הַתּוֹבֵעַ הַזֶּה אֶת הָעֵד וְנִזְכַּר הֲרֵי זֶה יָעִיד לוֹ שֶׁתַּלְמִיד חָכָם יוֹדֵעַ שֶׁאִלּוּ לֹא זָכָר הַדָּבָר לֹא הָיָה מֵעִיד. וְקַל הוּא שֶׁהֵקֵלּוּ בְּדִינֵי מָמוֹנוֹת שֶׁאַף עַל פִּי שֶׁשָּׁכַח הַדָּבָר מִכַּמָּה שָׁנִים וְהַכְּתָב הוּא שֶׁהִזְכִּירוֹ הֲרֵי זֶה מֵעִיד:","הוֹאִיל וְהַדָּבָר כֵּן שְׁטָר שֶׁיָּצָא לְבֵית דִּין וּבָאוּ עֵדִים וְאָמְרוּ כְּתַב יָדֵינוּ הוּא זֶה אֲבָל מֵעוֹלָם לֹא יָדַעְנוּ עֵדוּת זוֹ וְאֵין אָנוּ זוֹכְרִים שֶׁזֶּה לָוָה מִזֶּה אוֹ מָכַר לוֹ. לֹא נִתְקַיֵּם הַשְּׁטָר וַהֲרֵי הֵן כְּחֵרְשִׁים עַד שֶׁיִּזְכְּרוּ עֵדוּתָן. וְכָל מִי שֶׁאֵינוֹ דָּן כֵּן לֹא יָדַע בְּדִינֵי מָמוֹנוֹת בֵּין יְמִינוֹ לִשְׂמֹאלוֹ. אֲבָל אִם הָיָה כְּתַב יָדָן יוֹצֵא מִמָּקוֹם אַחֵר אוֹ שֶׁהָיוּ שָׁם עֵדִים שֶׁזֶּה כְּתַב יָדָן. מְקַיְּמִין אֶת הַשְּׁטָר וְאֵין מַשְׁגִּיחִין עַל דִּבְרֵיהֶן שֶׁאוֹמְרִין אֵין אָנוּ זוֹכְרִין עֵדוּת זוֹ שֶׁמָּא חָזְרוּ בָּהֶן. וְזֶה שֶׁאָמְרוּ אֵין אָנוּ זוֹכְרִין כְּדֵי לְבַטֵּל הַשְּׁטָר וּכְאִלּוּ אָמְרוּ קְטַנִּים הָיִינוּ פְּסוּלֵי עֵדוּת הָיִינוּ שֶׁאֵינָן נֶאֱמָנִים הוֹאִיל וּמִתְקַיֵּם הַשְּׁטָר שֶׁלֹּא עַל פִּיהֶם. וּמִפְּנֵי טַעַם זֶה מְקַיְּמִין כָּל הַשְּׁטָרוֹת. וְאֵין אָנוּ צְרִיכִין לְהָבִיא עֵדִים וְלִשְׁאל אוֹתָם אִם הֵם זוֹכְרִים עֵדוּת זוֹ אוֹ אֵינָם זוֹכְרִים אוֹתָהּ. שֶׁאֲפִלּוּ בָּאוּ וְאָמְרוּ אֵין אָנוּ זוֹכְרִים אוֹתָהּ אֵין שׁוֹמְעִין לָהֶן הוֹאִיל וְאֶפְשָׁר לְקַיְּמוֹ שֶׁלֹּא מִפִּיהֶן:","אֶחָד הַכּוֹתֵב עֵדוּתוֹ עַל הַשְּׁטָר. אוֹ שֶׁנִּמְצָא אֶצְלוֹ כָּתוּב בְּפִנְקָסוֹ בִּכְתַב יָדוֹ פְּלוֹנִי הֵעִיד אוֹתִי עָלָיו בְּיוֹם פְּלוֹנִי בְּכָךְ וְכָךְ. אִם זָכַר מֵעַצְמוֹ אוֹ הִזְכִּירוּהוּ אֲחֵרִים וְנִזְכַּר מֵעִיד וְאִם לָאו אָסוּר לְהָעִיד. שֶׁאֵין זֶה דּוֹמֶה אֶלָּא לְמִי שֶׁאָמַר לוֹ אָדָם נֶאֱמָן פְּלוֹנִי יֵשׁ לוֹ אֵצֶל פְּלוֹנִי כָּךְ וְכָךְ וְהֵעִיד הוּא שֶׁיֵּשׁ לָזֶה אֵצֶל זֶה וְהוּא אֵינוֹ יוֹדֵעַ מִן הַדָּבָר כְּלוּם אֶלָּא מִפִּי הָאַחֵר שָׁמַע וְהֵעִיד:"],"Mishneh Torah, The Order of Prayer 3":["וזהו נסח כל הברכות האמצעיות","בְּרָכָה אֶמְצָעִית שֶׁל לֵילֵי שַׁבָּת אַתָּה קִדַּשְׁתָּ אֶת יוֹם הַשְּׁבִיעִי לִשְׁמֶךָ תַּכְלִית מַעֲשֵׂה שָׁמַיִם וָאָרֶץ וּבֵרַכְתּוֹ מִכָּל הַיָּמִים וְקִדַּשְׁתּוֹ מִכָּל הַזְּמַנִּים כָּאָמוּר וַיְבָרֶךְ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי וַיְקַדֵּשׁ אוֹתוֹ וְגוֹ׳‎. אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ רְצֵה נָא בִמְנוּחָתֵנוּ וְכוּ׳‎. בְּרָכָה אֶמְצָעִית שֶׁל יוֹצֵר יִשְׂמַח משֶׁה בְּמַתְּנַת חֶלְקוֹ כִּי עֶבֶד נֶאֱמָן קָרָאתָ לוֹ כְּלִיל תִּפְאֶרֶת בְּרֹאשׁוֹ נָתַתָּ בְּעָמְדוֹ לְפָנֶיךָ עַל הַר סִינַי הוֹרִיד בְּיָדוֹ שְׁנֵי לֻחוֹת אֲבָנִים וְכָתוּב בָּהֶן שְׁמִירַת שַׁבָּת וְכֵן כָּתוּב בְּתוֹרָתֶךָ וְשָׁמְרוּ בְנֵי יִשְׂרָאֵל וְכוּ׳‎. יִשְׂמְחוּ בְּמַלְכוּתְךָ שׁוֹמְרֵי שַׁבָּת קוֹרְאֵי עֹנֶג עַם מְקַדְּשֵׁי שְׁבִיעִי. אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ רְצֵה נָא בִמְנוּחָתֵנוּ כוּ׳‎ עַד בָּרוּךְ אַתָּה יְיָ׳‎ מְקַדֵּשׁ הַשַּׁבָּת.","בְּרָכָה אֶמְצָעִית שֶׁל מוּסַף שַׁבָּת. לְמשֶׁה צִוִּיתָ עַל הַר סִינַי מִצְוַת שַׁבָּת שָׁמוֹר וְזָכוֹר וּבוֹ צִוִּיתָנוּ יְיָ׳‎ אֱלֹהֵינוּ לְהַקְרִיב לְךָ קָרְבַּן מוּסָף כָּרָאוּי. יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהֵינוּ שֶׁתַּעֲלֵנוּ לְאַרְצֵנוּ וְכוּ׳‎ וְאֶת מוּסַף יוֹם הַמָּנוֹחַ הַזֶּה נַעֲשֶׂה וְנַקְרִיב כוּ׳‎ עַד עַל יְדֵי משֶׁה עַבְדֶּךָ. וְלֹא נְתַתּוֹ מַלְכֵּנוּ לְגוֹיֵי הָאֲרָצוֹת וְלֹא הִנְחַלְתּוֹ מַלְכֵּנוּ לְעוֹבְדֵי אֱלִילִים גַּם בִּמְנוּחָתוֹ לֹא יִשְׁכְּנוּ עֲרֵלִים לְבֵית יִשְׂרָאֵל נְתַתּוֹ זֶרַע יְשֻׁרוּן אֲשֶׁר בָּם בָּחָרְתָּ חֶמְדַּת יָמִים אוֹתוֹ קָרָאתָ. אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ רְצֵה נָא בִמְנוּחָתֵנוּ כוּ׳‎ עַד בָּרוּךְ אַתָּה יְיָ׳‎ מְקַדֵּשׁ הַשַּׁבָּת. בְּרָכָה אֶמְצָעִית שֶׁל מִנְחַת שַׁבָּת אַתָּה אֶחָד וְשִׁמְךָ אֶחָד וּמִי כְּעַמְּךָ יִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ עֲטֶרֶת תְּהִלָּה וַעֲטֶרֶת יְשׁוּעָה לְעַמְּךָ נָתָתָּ אַבְרָהָם יָגֵל יִצְחָק יְרַנֵּן יַעֲקֹב וּבָנָיו יָנוּחוּ בוֹ מְנוּחָה שְׁלֵמָה שָׁאַתָּה רוֹצֶה בָּהּ יַכִּירוּ בָנֶיךָ וְיֵדְעוּ כִּי מֵאִתְּךָ הִיא מְנוּחָתָם תַּנְחִילֵנוּ אָבִינוּ וְאַל תְּהִי צָרָה וְיָגוֹן בְּיוֹם מְנוּחָתֵנוּ. אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ וְכוּ׳‎.","בְּרָכָה אֶמְצָעִית שֶׁל מוּסַף רֹאשׁ חֹדֶשׁ. רָאשֵׁי חֳדָשִׁים לְעַמְּךָ נָתָתָּ זְמַן כַּפָּרָה לְכָל תּוֹלְדוֹתָם לִהְיוֹתָם מַקְרִיבִים לְפָנֶיךָ זִבְחֵי רָצוֹן וּשְׂעִירֵי חַטָּאת לְכַפֵּר בַּעֲדָם. זִכָּרוֹן לְכֻלָּם יִהְיוּ תְּשׁוּעַת נַפְשָׁם מִיַּד שׂוֹנֵא. מִזְבֵּחַ חָדָשׁ בְּצִיּוֹן תָּכִין וְעוֹלַת רֹאשׁ חֹדֶשׁ נַעֲלֶה עָלָיו. שִׁירֵי דָּוִד נִשְׁמַע בְּעִירֶךָ הָאֲמוּרִים לִפְנֵי מִזְבְּחֶךָ. אַהֲבַת עוֹלָם תָּבִיא לָהֶם וּבְרִית אָבוֹת לַבָּנִים תִּזְכֹּר. אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ מִפְּנֵי חֲטָאֵינוּ גָּלִינוּ מֵאַרְצֵנוּ וְנִתְרַחַקְנוּ מֵעַל אַדְמָתֵנוּ יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהֵינוּ שֶׁתַּעֲלֵנוּ לְאַרְצֵנוּ וְאֶת מוּסַף יוֹם רֹאשׁ הַחֹדֶשׁ הַזֶּה כוּ׳‎ עַד עַל יְדֵי משֶׁה עַבְדֶּךָ. יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהֵינוּ וִאלֹהֵי אֲבוֹתֵינוּ שֶׁתְּחַדֵּשׁ עָלֵינוּ אֶת רֹאשׁ הַחֹדֶשׁ הַזֶּה לְטוֹבָה וְלִבְרָכָה לְחֵן וּלְחֶסֶד וּלְרַחֲמִים לְחַיִּים וּלְשָׁלוֹם וִיהִי רֹאשׁ הַחֹדֶשׁ הַזֶּה קֵץ וְסוֹף לְכָל חַטֹּאתֵינוּ וְצָרוֹתֵינוּ תְּחִלָּה וָרֹאשׁ לִפְדוּת נַפְשֵׁנוּ כִּי בְעַמְּךָ יִשְׂרָאֵל מִכָּל הָאֻמּוֹת בָּחַרְתָּ וְרָאשֵׁי חֳדָשִׁים לָהֶם נָתָתָּ. בָּרוּךְ אַתָּה יְיָ׳‎ מְקַדֵּשׁ יִשְׂרָאֵל וְרָאשֵׁי חֳדָשִׁים. בְּרָכָה אֶמְצָעִית מִמּוּסַף רֹאשׁ חֹדֶשׁ שֶׁחָל לִהְיוֹת בְּשַׁבָּת. אַתָּה יָצַרְתָּ עוֹלָמְךָ מִקֶּדֶם כִּלִּיתָ מְלַאכְתְּךָ בַּיּוֹם הַשְּׁבִיעִי בָּחַרְתָּ בָּנוּ מִכָּל הָעַמִּים וְרָצִיתָ בָּנוּ מִכָּל הַלְּשׁוֹנוֹת וְקִדַּשְׁתָּנוּ בְּמִצְוֹתֶיךָ וְקֵרַבְתָּנוּ מַלְכֵּנוּ לַעֲבוֹדָתֶךָ וְשִׁמְךָ הַגָּדוֹל וְהַקָּדוֹשׁ עָלֵינוּ קָרָאתָ וַתִּתֶּן לָנוּ יְיָ׳‎ אֱלֹהֵינוּ שַׁבָּתוֹת לִמְנוּחָה וְיוֹם רֹאשׁ חֹדֶשׁ הַזֶּה לְכַפֵּר בַּעֲדֵנוּ שֶׁחָטָאנוּ לְפָנֶיךָ. וּמִפְּנֵי חֲטָאֵינוּ וְכוּ׳‎ עַד וּמוּסָפִים כְּהִלְכָתָן וְאֶת מוּסְפֵי יוֹם הַמָּנוֹחַ הַזֶּה וְיוֹם רֹאשׁ הַחֹדֶשׁ הַזֶּה נַעֲשֶׂה וְנַקְרִיב אֶת קָרְבְּנוֹת חוֹבוֹתֵינוּ תְּמִידִין כְּסִדְרָן כְּמִצְוַת רְצוֹנֶךָ כְּמוֹ שֶׁכָּתַבְתָּ עָלֵינוּ בְּתוֹרָתֶךָ עַל יְדֵי משֶׁה עַבְדֶּךָ. יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהֵינוּ וִאלֹהֵי אֲבוֹתֵינוּ שֶׁתְּחַדֵּשׁ וְכוּ׳‎ עַד לִפְדוּת נַפְשֵׁנוּ. רְצֵה נָא בִמְנוּחָתֵנוּ וְקַדְּשֵׁנוּ בְּמִצְוֹתֶיךָ כוּ׳‎ עַד וְיָנוּחוּ בָם כָּל יִשְׂרָאֵל אוֹהֲבֵי שְׁמֶךָ. בָּרוּךְ אַתָּה יְיָ׳‎ מְקַדֵּשׁ הַשַּׁבָּת וְיִשְׂרָאֵל וְרָאשֵׁי חֳדָשִׁים.","בְּרָכָה אֶמְצָעִית שֶׁל יוֹם טוֹב שֶׁל פֶּסַח עַרְבִית שַׁחֲרִית וּמִנְחָה. אַתָּה בְחַרְתָּנוּ מִכָּל הָעַמִּים אָהַבְתָּ אוֹתָנוּ וְרָצִיתָ בָּנוּ מִכָּל הַלְּשׁוֹנוֹת וְקִדַּשְׁתָּנוּ בְּמִצְוֹתֶיךָ וְקֵרַבְתָּנוּ מַלְכֵּנוּ לַעֲבוֹדָתֶךָ וְשִׁמְךָ הַגָּדוֹל וְהַקָּדוֹשׁ עָלֵינוּ קָרָאתָ וַתִּתֶּן לָנוּ יְיָ׳‎ אֱלֹהֵינוּ מוֹעֲדִים לְשִׂמְחָה חַגִּים וּזְמַנִּים לְשָׂשוֹן אֶת יוֹם טוֹב מִקְרָא קֹדֶשׁ הַזֶּה אֶת יוֹם חַג הַמַּצּוֹת הַזֶּה זְמַן חֵרוּתֵנוּ בְּאַהֲבָה זֵכֶר לִיצִיאַת מִצְרָיִם. אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ יַעֲלֶה וְיָבוֹא כוּ׳‎. וְהַשִּׂיאֵנוּ יְיָ׳‎ אֱלֹהֵינוּ אֶת בִּרְכַּת מוֹעֲדֶיךָ לְחַיִּים וּלְשָׁלוֹם כַּאֲשֶׁר אָמַרְתָּ וְרָצִיתָ לְבָרְכֵנוּ כֵּן תְּבָרְכֵנוּ סֶלָה וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ וְשַׂמַּח נַפְשֵׁנוּ בִּישׁוּעָתֶךָ וְכוּ׳‎. בָּרוּךְ אַתָּה יְיָ׳‎ מְקַדֵּשׁ יִשְׂרָאֵל וְהַזְּמַנִּים.","בְּרָכָה אֶמְצָעִית מִמּוּסַף הַפֶּסַח. אַתָּה בְחַרְתָּנוּ מִכָּל הָעַמִּים כוּ׳‎ עַד זֵכֶר לִיצִיאַת מִצְרָיִם. וּמִפְּנֵי חֲטָאֵינוּ גָּלִינוּ מֵאַרְצֵנוּ וְנִתְרַחַקְנוּ מֵעַל אַדְמָתֵנוּ וְאֵין אָנוּ יְכוֹלִין לַעֲלוֹת לְהֵרָאוֹת וּלְהִשְׁתַּחֲווֹת לְפָנֶיךָ בְּבֵית בְּחִירָתֶךָ בִּנְוֵה הַדֶּרֶךְ בַּבַּיִת הַגָּדוֹל וְהַקָּדוֹשׁ שֶׁנִּקְרָא שִׁמְךָ עָלָיו מִפְּנֵי הַיָּד שֶׁנִּשְׁתַּלְּחָה בְּמִקְדָּשֶׁךָ. יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהֵינוּ שֶׁתָּשׁוּב וּתְרַחֵם עָלָיו וְעָלֵינוּ בְּרַחֲמֶיךָ הָרַבִּים וּתְקַבֵּץ פְּזוּרֵינוּ מִבֵּין הַגּוֹיִם וּנְפוּצוֹתֵינוּ כַּנֵּס מִיַּרְכְּתֵי אָרֶץ וַהֲבִיאֵנוּ לְצִיּוֹן עִירְךָ בְּרִנָּה וְלִירוּשָׁלַיִם בֵּית מִקְדָּשְׁךָ בְּשִׂמְחַת עוֹלָם וְשָׁם נַעֲשֶׂה לְפָנֶיךָ אֶת קָרְבְּנוֹת חוֹבוֹתֵינוּ תְּמִידִין כְּסִדְרָן וּמוּסָפִין כְּהִלְכָתָן וְאֶת מוּסַף יוֹם טוֹב מִקְרָא קֹדֶשׁ הַזֶּה יוֹם חַג הַמַּצּוֹת הַזֶּה נַעֲשֶׂה וְנַקְרִיב לְפָנֶיךָ כְּמִצְוַת רְצוֹנֶךָ כְּמוֹ שֶׁכָּתַבְתָּ עָלֵינוּ בְּתוֹרָתֶךָ עַל יְדֵי משֶׁה עַבְדֶּךָ. מֶלֶךְ רַחֲמָן רַחֵם עָלֵינוּ וְכוּ׳‎. וְהַשִּׂיאֵנוּ וְכוּ׳‎. בָּרוּךְ אַתָּה יְיָ׳‎ מְקַדֵּשׁ יִשְׂרָאֵל וְהַזְּמַנִּים. וּבַנֹּסַח הַזֶּה הוּא מִתְפַּלֵּל בְּחַג שָׁבוּעוֹת וּבְחַג הַסֻּכּוֹת בְּלֹא חֶסְרוֹן וּבְלֹא יָתֵר. אֶלָּא שֶׁבְּחַג הַשָּׁבוּעוֹת הוּא אוֹמֵר אֶת יוֹם טוֹב מִקְרָא קֹדֶשׁ הַזֶּה אֶת יוֹם חַג הַשָּׁבוּעוֹת הַזֶּה זְמַן מַתַּן תּוֹרָתֵנוּ בְּאַהֲבָה זֵכֶר לִיצִיאַת מִצְרָיִם. וּבְמוּסָף הוּא אוֹמֵר וְאֶת מוּסַף יוֹם טוֹב מִקְרָא קֹדֶשׁ הַזֶּה יוֹם חַג הַשָּׁבוּעוֹת הַזֶּה. וְכֵן בְּסֻכּוֹת הוּא אוֹמֵר אֶת יוֹם טוֹב מִקְרָא קֹדֶשׁ הַזֶּה יוֹם חַג הַסֻּכּוֹת הַזֶּה זְמַן שִׂמְחָתֵנוּ בְּאַהֲבָה וְכוּ׳‎. וּבִשְׁמִינִי עֲצֶרֶת אוֹמֵר אֶת יוֹם טוֹב מִקְרָא קֹדֶשׁ הַזֶּה אֶת יוֹם חַג שְׁמִינִי עֲצֶרֶת הַזֶּה זְמַן שִׂמְחָתֵנוּ כוּ׳‎. וְכֵן בְּמוּסָף אוֹמֵר וְאֶת מוּסַף יוֹם טוֹב מִקְרָא קֹדֶשׁ הַזֶּה יוֹם חַג שְׁמִינִי כוּ׳‎.","וְאִם חָל יוֹם טוֹב לִהְיוֹת בְּשַׁבָּת אוֹמֵר אַתָּה בְחַרְתָּנוּ כוּ׳‎ עַד וַתִּתֶּן לָנוּ יְיָ׳‎ אֱלֹהֵינוּ שַׁבָּתוֹת לִמְנוּחָה מוֹעֲדִים לְשִׂמְחָה חַגִּים וּזְמַנִּים לְשָׂשוֹן אֶת יוֹם הַמָּנוֹחַ הַזֶּה וְאֶת יוֹם טוֹב מִקְרָא קֹדֶשׁ הַזֶּה אֶת יוֹם פְּלוֹנִי כוּ׳‎. וְכֵן בְּמוּסָף אוֹמֵר וְאֶת מוּסְפֵי יוֹם הַמָּנוֹחַ הַזֶּה כוּ׳‎. וְעַל דֶּרֶךְ זוֹ הוּא מַזְכִּיר הַשַּׁבָּת בְּרֹאשׁ הַשָּׁנָה וּבְיוֹם הַכִּפּוּרִים אִם חָלוּ לִהְיוֹת בְּשַׁבָּת בֵּין בִּשְׁאָר תְּפִלּוֹת בֵּין בְּמוּסָף. וְחוֹתֵם בְּכָל הַתְּפִלּוֹת שֶׁל שָׁלֹשׁ רְגָלִים מְקַדֵּשׁ הַשַּׁבָּת וְיִשְׂרָאֵל וְהַזְּמַנִּים. וּבְרֹאשׁ הַשָּׁנָה חוֹתֵם מֶלֶךְ עַל כָּל הָאָרֶץ מְקַדֵּשׁ הַשַּׁבָּת וְיִשְׂרָאֵל וְיוֹם הַזִּכָּרוֹן. וּבְיוֹם הַכִּפּוּרִים מֶלֶךְ עַל כָּל הָאָרֶץ מְקַדֵּשׁ הַשַּׁבָּת וְיִשְׂרָאֵל וְיוֹם הַכִּפּוּרִים.","רֹאשׁ הַשָּׁנָה. נָהֲגוּ רֹב הָעָם מֵרֹאשׁ הַשָּׁנָה וְעַד יוֹם הַכִּפּוּרִים לְהוֹסִיף בְּכָל תְּפִלָּה בַּעֲשֶׂרֶת הַיָּמִים. בִּבְרָכָה רִאשׁוֹנָה מוֹסִיפִים זָכְרֵנוּ לְחַיִּים כוּ׳‎ בָּרוּךְ אַתָּה יְיָ׳‎ מָגֵן אַבְרָהָם. וּמוֹסִיפִין בִּבְרָכָה שְׁנִיָּה מִי כָמוֹךָ אַב הָרַחֲמִים זוֹכֵר יְצוּרָיו בְּרַחֲמִים בָּרוּךְ אַתָּה יְיָ׳‎ מְחַיֵּה הַמֵּתִים. וּמוֹסִיפִין בְּבִרְכַּת י״ח זְכוֹר רַחֲמֶיךָ וְכוּ׳‎. וּבִבְרָכָה אַחֲרוֹנָה מוֹסִיפִין וּבְסֵפֶר חַיִּים וְכוּ׳‎. וּבִתְפִלַּת נְעִילָה שֶׁל יוֹם הַצּוֹם אוֹמֵר בִּבְרָכָה זָכְרֵנוּ לְחַיִּים חָתְמֵנוּ וְכָל אֵלּוּ הַתּוֹסָפוֹת מִנְהַג מְקוֹמוֹת. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ שֶׁלֹּא יוֹסִיפוּ דָּבָר. מִנְהָג פָּשׁוּט שֶׁמְּבָרְכִין בְּרָכָה שְׁלִישִׁית בְּנֹסַח זֶה בִּשְׁנֵי יָמִים שֶׁל רֹאשׁ הַשָּׁנָה בְּכָל תְּפִלָּה וּתְפִלָּה מֵאַרְבַּע הַתְּפִלּוֹת וְכֵן נָהֲגוּ מִקְצָת לְבָרֵךְ אוֹתָהּ בְּאוֹתוֹ הַנֹּסַח בְּכָל תְּפִלָּה וּתְפִלָּה מֵחָמֵשׁ תְּפִלּוֹת שֶׁל יוֹם הַכִּפּוּרִים וְזֶהוּ נֻסְחָהּ. אַתָּה קָדוֹשׁ וְשִׁמְךָ קָדוֹשׁ וּקְדוֹשִׁים בְּכָל יוֹם יְהַלְלוּךָ סֶּלָה. וּבְכֵן תֵּן פַּחְדְּךָ יְיָ׳‎ אֱלֹהֵינוּ עַל כָּל מַעֲשֶׂיךָ וְאֵימָתְךָ עַל כָּל מַה שֶּׁבָּרָאתָ וְיִירָאוּךָ כָּל הַמַּעֲשִׂים וְיִשְׁתַּחֲווּ לְפָנֶיךָ כָּל הַבְּרוּאִים וְיֵעָשׂוּ כֻלָּם אֲגֻדָּה אֶחָת לַעֲשׂוֹת רְצוֹנְךָ בְּלֵבָב שָׁלֵם כוּ׳‎. וּבְכֵן תֵּן כָּבוֹד לְעַמֶּךָ תְּהִלָּה לִירֵאֶיךָ וְתִקְוָה טוֹבָה לְדוֹרְשֶׁיךָ וּפִתְחוֹן פֶּה לַמְיַחֲלִים לָךְ שִׂמְחָה לְאַרְצֶךָ שָׂשׂוֹן לְעִירֶךָ וּצְמִיחַת קֶרֶן לְדָוִד עַבְדֶּךָ וַעֲרִיכַת נֵר לְבֶן יִשַׁי מְשִׁיחֶךָ בִּמְהֵרָה בְיָמֵינוּ. וְאָז צַדִּיקִים יִרְאוּ וְיִשְׂמָחוּ וִישָׁרִים יַעֲלֹזוּ וַחֲסִידִים כוּ׳‎ כַּכָּתוּב בְּדִבְרֵי קָדְשֶׁךָ יִמְלֹךְ יְיָ׳‎ לְעוֹלָם אֱלֹהַיִךְ צִיּוֹן לְדוֹר וָדוֹר הַלְלוּיָהּ וְכָתוּב וַיִּגְבַּהּ יְיָ׳‎ וְגוֹ׳‎ בָּרוּךְ אַתָּה יְיָ׳‎ הַמֶּלֶךְ הַקָּדוֹשׁ. בְּרָכָה אֶמְצָעִית שֶׁל רֹאשׁ הַשָּׁנָה עַרְבִית שַׁחֲרִית וּמִנְחָה. אַתָּה בְחַרְתָּנוּ מִכָּל הָעַמִּים כוּ׳‎. וַתִּתֶּן לָנוּ יְיָ׳‎ אֱלֹהֵינוּ אֶת יוֹם טוֹב מִקְרָא קֹדֶשׁ הַזֶּה זִכְרוֹן תְּרוּעָה בְּאַהֲבָה זֵכֶר לִיצִיאַת מִצְרָיִם. אֱלֹהֵינוּ וִאלֹהֵי אֲבוֹתֵינוּ יַעֲלֶה וְיָבוֹא כוּ׳‎. אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ מְלוֹךְ עַל כָּל הָעוֹלָם כֻּלּוֹ בִּכְבוֹדֶךָ וְהִנָּשֵׂא עַל כָּל הָאָרֶץ בִּיקָרֶךָ וְהוֹפַע בַּהֲדַר גְּאוֹן עֻזֶּךָ עַל כָּל יוֹשְׁבֵי תֵבֵל אַרְצֶךָ וְיֵדַע כָּל פָּעוּל כִּי אַתָּה פְעַלְתּוֹ וְיָבִין כָּל יְצוּר כִּי אַתָּה יְצַרְתּוֹ וְיֹאמַר כּל אֲשֶׁר רוּחַ וּנְשָׁמָה בְאַפּוֹ יְיָ׳‎ וְכוּ׳‎. קַדְּשֵׁנוּ כוּ׳‎. בָּרוּךְ אַתָּה יְיָ׳‎ מֶלֶךְ עַל כָּל הָאָרֶץ מְקַדֵּשׁ יִשְׂרָאֵל וְיוֹם הַזִּכָּרוֹן.","בְּרָכָה רִאשׁוֹנָה מִשָּׁלֹשׁ בְּרָכוֹת אֶמְצָעִיּוֹת שֶׁל מוּסַף רֹאשׁ הַשָּׁנָה. אַתָּה בְחַרְתָּנוּ. וּמִפְּנֵי חֲטָאֵינוּ כוּ׳‎. וְאֶת מוּסְפֵי כוּ׳‎ כְּמוֹ שֶׁכָּתוּב. עָלֵינוּ לְשַׁבֵּחַ לַאֲדוֹן הַכּל לָתֵת גְּדֻלָּה לְיוֹצֵר בְּרֵאשִׁית שֶׁלֹּא עָשָׂנוּ כְּגוֹיֵי הָאֲרָצוֹת וְכוּ׳‎. אוֹחִילָה לָאֵל אֲחַלֶּה פָנָיו אֶשְׁאֲלָה מִמֶּנּוּ מַעֲנֵה לָשׁוֹן אֲשֶׁר בִּקְהַל עָם אָשִׁירָה עֻזּוֹ אַבִּיעָה רְנָנוֹת בְּעַד מִפְעָלָיו כוּ׳‎. בָּרוּךְ אַתָּה יְיָ׳‎ לַמְּדֵנִי חֻקֶּיךָ. עַל כֵּן נְקַוֶּה לְךָ יְיָ׳‎ אֱלֹהֵינוּ לִרְאוֹת מְהֵרָה בְּתִפְאֶרֶת עֵזֶּךָ וְכוּ׳‎. אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ מְלוֹךְ כוּ׳‎. בָּרוּךְ אַתָּה יְיָ׳‎ מֶלֶךְ עַל כָּל הָאָרֶץ מְקַדֵּשׁ יִשְׂרָאֵל וְיוֹם הַזִּכָּרוֹן. הַיּוֹם הֲרַת עוֹלָם הַיּוֹם יַעֲמִיד בַּמִּשְׁפָּט כָּל יְצוּרֵי עוֹלָם אִם כְּבָנִים אִם כַּעֲבָדִים אִם כְּבָנִים רַחֲמֵנוּ כְּרַחֵם אָב עַל בָּנִים אִם כַּעֲבָדִים עֵינֵינוּ לְךָ תְלוּיוֹת וְכוּ׳‎. בְּרָכָה שְׁנִיָּה אַתָּה זוֹכֵר מַעֲשֵׂה עוֹלָם וּפוֹקֵד כָּל יְצוּרֵי קֶדֶם כוּ׳‎ כִּי זוֹכֵר הַנִּשְׁכָּחוֹת אַתָּה הוּא מֵעוֹלָם וְאֵין שִׁכְחָה לִפְנֵי כִסֵּא כְבוֹדֶךָ וַעֲקֵדַת יִצְחָק לְזַרְעוֹ תִּזְכֹּר וְכוּ׳‎. הַיּוֹם הֲרַת עוֹלָם הַיּוֹם יַעֲמִיד בַּמִּשְׁפָּט כָּל יְצוּרֵי עוֹלָם אִם כְּבָנִים אִם כַּעֲבָדִים אִם כְּבָנִים רַחֲמֵנוּ כְּרַחֵם אָב עַל בָּנִים כוּ׳‎. בְּרָכָה שְׁלִישִׁית אַתָּה נִגְלֵיתָ בַּעֲנַן כְּבוֹדֶךָ עַל עַם קָדְשְׁךָ לְדַבֵּר עִמָּם מִן הַשָּׁמַיִם הִשְׁמַעְתָּם קוֹלֶךָ כוּ׳‎ כִּי אַתָּה שׁוֹמֵעַ כוּ׳‎ בָּרוּךְ אַתָּה יְיָ׳‎ שׁוֹמֵעַ תְּרוּעָה. הַיּוֹם הֲרַת עוֹלָם כוּ׳‎ כַּכָּתוּב לְמַעְלָה.","בְּרָכָה אֶמְצָעִית שֶׁל צוֹם יוֹם הַכִּפּוּרִים בְּעַרְבִית וְשַׁחֲרִית וּמִנְחָה וּנְעִילָה אַתָּה בְחַרְתָּנוּ כוּ׳‎. וַתִּתֶּן לָנוּ יְיָ׳‎ אֱלֹהֵינוּ אֶת יוֹם הַכִּפּוּרִים הַזֶּה וְאֶת יוֹם מִקְרָא קֹדֶשׁ הַזֶּה לִמְחִילָה וְכוּ׳‎. אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ יַעֲלֶה וְיָבוֹא יַגִּיעַ יֵרָאֶה וְיֵרָצֶה יִשָּׁמַע וְיִפָּקֵד וְיִזָּכֵר לְפָנֶיךָ זִכְרוֹנֵנוּ זִכְרוֹן אֲבוֹתֵינוּ זִכְרוֹן יְרוּשָׁלַיִם עִירֶךָ וְזִכְרוֹן מָשִׁיחַ בֶּן דָּוִד וְכוּ׳‎. אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ מְחל לַעֲוֹנוֹתֵינוּ וְכוּ׳‎. אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ מְלוֹךְ כוּ׳‎. קַדְּשֵׁנוּ כוּ׳‎. וּדְבָרְךָ אֱמֶת וְקַיָּם כוּ׳‎ בָּרוּךְ אַתָּה יְיָ׳‎ מֶלֶךְ עַל כָּל הָאָרֶץ מֶלֶךְ מוֹחֵל וְסוֹלֵחַ וְכוּ׳‎. בְּרָכָה אֶמְצָעִית שֶׁל מוּסָף אַתָּה בְחַרְתָּנוּ וּמִפְּנֵי חֲטָאֵינוּ וְאֶת מוּסְפֵי יוֹם מִקְרָא קֹדֶשׁ הַזֶּה נַעֲשֶׂה וְנַקְרִיב לְפָנֶיךָ כְּמִצְוַת רְצוֹנֶךָ כוּ׳‎. אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ מְחל לַעֲוֹנוֹתֵינוּ בְּיוֹם צוֹם הַכִּפּוּרִים הַזֶּה מְחֵה וְהַעֲבֵר פְּשָׁעֵינוּ כוּ׳‎ עַד וּמִבַּלְעָדֶיךָ אֵין לָנוּ מֶלֶךְ מוֹחֵל וְסוֹלֵחַ וְכוּ׳‎. אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ מְלוֹךְ עַל כָּל הָעוֹלָם כֻּלּוֹ בִּכְבוֹדֶךָ וְהִנָּשֵׂא עַל כָּל הָאָרֶץ בִּיקָרֶךָ וְהוֹפַע בַּהֲדַר גְּאוֹן עֵזֶּךָ וְכוּ׳‎ עַד וּמַלְכוּתוֹ בַּכּל מָשָׁלָה. קַדְּשֵׁנוּ בְּמִצְוֹתֶיךָ וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ וְשַׂבְּעֵנוּ מִטּוּבֶךָ וְשַׂמְּחֵנוּ בִּישׁוּעָתֶךָ וְטַהֵר לִבֵּנוּ לְעָבְדְּךָ בֶּאֱמֶת וּדְבָרְךָ כוּ׳‎ עַד בָּרוּךְ אַתָּה יְיָ׳‎ מְקַדֵּשׁ יִשְׂרָאֵל וְיוֹם הַכִּפּוּרִים. נָהֲגוּ הָעָם בְּכָל תְּפִלּוֹת הַמּוּסָפִין כְּשֶׁהוּא אוֹמֵר כְּמוֹ שֶׁכָּתַבְתָּ עָלֵינוּ בְּתוֹרָתֶךָ עַל יְדֵי משֶׁה עַבְדֶּךָ מַזְכִּיר קָרְבְּנוֹת אוֹתוֹ הַיּוֹם כְּמוֹ שֶׁהֵם כְּתוּבִים בַּתּוֹרָה וְקוֹרֵא אוֹתָם הַפְּסוּקִים. וְאִם לֹא הִזְכִּיר כֵּיוָן שֶׁאָמַר כְּמוֹ שֶׁכָּתַבְתָּ עָלֵינוּ בְּתוֹרָתֶךָ שׁוּב אֵינוֹ צָרִיךְ:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 18":["אֵלוּ הֵן הַלּוֹקִין. כָּל הָעוֹבֵר עַל לֹא תַּעֲשֶׂה שֶׁחַיָּבִין עָלָיו כָּרֵת וְאֵין בּוֹ מִיתַת בֵּית דִּין כְּגוֹן אוֹכֵל חֵלֶב וְדָם וְחָמֵץ בְּפֶסַח. וְכֵן כָּל הָעוֹבֵר עַל לֹא תַּעֲשֶׂה שֶׁחַיָּבִין עָלָיו מִיתָה בִּידֵי שָׁמַיִם כְּגוֹן אוֹכֵל טֶבֶל וְכֹהֵן טָמֵא שֶׁאָכַל תְּרוּמָה טְהוֹרָה. וְכֵן כָּל הָעוֹבֵר עַל לָאו שֶׁיֵּשׁ בּוֹ מַעֲשֶׂה כְּגוֹן אוֹכֵל בָּשָׂר בְּחָלָב אוֹ לוֹבֵשׁ שַׁעַטְנֵז. אֲבָל לָאו שֶׁאֵין בּוֹ מַעֲשֶׂה כְּגוֹן הוֹלֵךְ רָכִיל וְנוֹקֵם וְנוֹטֵר וְנוֹשֵׂא שֵׁמַע שָׁוְא אֵינוֹ לוֹקֶה:","כָּל לָאו שֶׁאֵין בּוֹ מַעֲשֶׂה אֵין לוֹקִין עָלָיו חוּץ מִנִּשְׁבָּע וּמֵימֵר וּמְקַלֵּל אֶת חֲבֵרוֹ בְּשֵׁם. וְכָל לָאו שֶׁנִּתָּן לְאַזְהָרַת מִיתַת בֵּית דִּין כְּגוֹן לֹא תִנְאָף לֹא תַּעֲשֶׂה מְלָאכָה בְּשַׁבָּת אֵין לוֹקִין עָלָיו. וְכָל לָאו שֶׁנִּתָּן לְתַשְׁלוּמִין כְּגוֹן לֹא תִּגְזל וְלֹא תִגְנֹב אֵין לוֹקִין עָלָיו. וְכָל לָאו שֶׁנִּתַּק לַעֲשֵׂה כְּגוֹן לֹא תִקַּח הָאֵם עַל הַבָּנִים לֹא תְכַלֶּה פְּאַת שָׂדְךָ אֵין לוֹקִין עָלָיו אֶלָּא אִם לֹא קִיֵּם עֲשֵׂה שֶׁבָּהֶן. וְכָל לָאו שֶׁבִּכְלָלוֹת אֵין לוֹקִין עָלָיו. וּשְׁאָר כָּל הַלָּאוִין שֶׁבַּתּוֹרָה לוֹקִין עֲלֵיהֶן:","אֵי זֶהוּ לָאו שֶׁבִּכְלָלוֹת זֶה לָאו אֶחָד שֶׁכּוֹלֵל עִנְיָנִים הַרְבֵּה כְּגוֹן לֹא תֹאכְלוּ עַל הַדָּם וְכֵן אִם נֶאֱמַר לֹא תַּעֲשֶׂה דָּבָר פְּלוֹנִי וּפְלוֹנִי הוֹאִיל וְלֹא יִחֵד לוֹ לָאו לְכָל אֶחָד וְאֶחָד מֵהֶן אֵין לוֹקִין עַל כָּל אֶחָד וְאֶחָד אֶלָּא אִם כֵּן חָלַק אוֹתָהּ בְּלָאוִין אֲחֵרִים אוֹ נֶאֱמַר מִפִּי הַשְּׁמוּעָה שֶׁנֶּחְלְקוּ. כֵּיצַד. כְּגוֹן זֶה שֶׁנֶּאֱמַר (שמות יב ט) \"אַל תֹּאכְלוּ מִמֶּנּוּ נָא וּבָשֵׁל מְבֻשָּׁל\" אֵינוֹ לוֹקֶה עַל הַנָּא וְהַמְבֻשָּׁל שְׁתַּיִם אֶלָּא אַחַת. וּבְחָדָשׁ הוּא אוֹמֵר (ויקרא כג יד) \"וְלֶחֶם וְקָלִי וְכַרְמֶל לֹא תֹאכְלוּ\" וְחַיָּב עַל שְׁלָשְׁתָּן שָׁלֹשׁ מַלְקִיּוֹת מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה לְחַלֵּק. הֲרֵי נֶאֱמַר (דברים יח י) \"לֹא יִמָּצֵא בְךָ מַעֲבִיר בְּנוֹ וּבִתּוֹ בָּאֵשׁ קֹסֵם קְסָמִים\" וְאַף עַל פִּי שֶׁכָּלַל כָּל הָעִנְיָנִים בְּלָאו אֶחָד הֲרֵי חָלַק אוֹתָם בְּלָאוִין אֲחֵרִים וְאָמַר (ויקרא יט כו) \"לֹא תְנַחֲשׁוּ וְלֹא תְעוֹנֵנוּ\" מְלַמֵּד שֶׁכָּל אֶחָד מֵהֶן בְּלָאו בִּפְנֵי עַצְמוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁלָּקָה בְּבֵית דִּין עַל אִסּוּר כָּרֵת וְלָקָה פַּעַם שְׁנִיָּה עַל אוֹתוֹ כָּרֵת עַצְמוֹ כְּגוֹן שֶׁאָכַל חֵלֶב וְלָקָה עָלָיו וְאָכַל חֵלֶב פַּעַם שְׁנִיָּה וְלָקָה עָלָיו אִם אָכַל פַּעַם שְׁלִישִׁית אֵין מַלְקִין אוֹתוֹ אֶלָּא מַכְנִיסִין אוֹתוֹ לְכִפָּה וְהוּא מָקוֹם צַר כְּפִי קוֹמָתוֹ וְאֵינוֹ יָכוֹל לִשְׁכַּב בּוֹ. וְנוֹתְנִין לוֹ לֶחֶם צַר וּמַיִם לַחַץ עַד שֶׁיָּצֵרוּ מֵעָיו וְיִכְלֶה. וְאַחַר כָּךְ מַאֲכִילִין אוֹתוֹ שְׂעוֹרִים עַד שֶׁכְּרֵסוֹ נִבְקַעַת:","מִי שֶׁעָבַר עַל אִסּוּר כָּרֵת אוֹ מִיתַת בֵּית דִּין וְהִתְרוּ בּוֹ וְהִרְכִּין בְּרֹאשׁוֹ אוֹ שָׁתַק וְלֹא קִבֵּל עָלָיו הַתְרָאָה. אֵין הוֹרְגִין אוֹתוֹ כְּמוֹ שֶׁבֵּאַרְנוּ וְאֵין מַלְקִין אוֹתוֹ. חָזַר וְעָשָׂה כָּךְ וְהִתְרוּ בּוֹ וְהִרְכִּין בְּרֹאשׁוֹ אוֹ שָׁתַק אֵין מְמִיתִין אוֹתוֹ וְאֵין מַלְקִין אוֹתוֹ. חָזַר פַּעַם שְׁלִישִׁית וְעָבַר וְהִתְרוּ בּוֹ אַף עַל פִּי שֶׁהִרְכִּין בְּרֹאשׁוֹ אוֹ שָׁתַק כּוֹנְסִין אוֹתוֹ לְכִפָּה עַד שֶׁיָּמוּת. וְכָל אֵלּוּ שֶׁלֹּא קִבְּלוּ עֲלֵיהֶן הַהַתְרָאָה מַכִּין אוֹתָן מַכַּת מַרְדּוּת הוֹאִיל וְחָטְאוּ מִכָּל מָקוֹם אֲפִלּוּ עַל אִסּוּר שֶׁל דִּבְרֵי סוֹפְרִים מַכִּין אוֹתָן מַכַּת מַרְדּוּת:","הַגּוֹנֵב כְּלֵי שָׁרֵת מִן הַמִּקְדָּשׁ וְהַמְקַלֵּל בְּקוֹסֵם וְהַבּוֹעֵל אֲרַמִּית אֵין בֵּית דִּין נִזְקָקִין לָהֶן. אֶלָּא הַקַּנָּאִין פּוֹגְעִין בָּהֶן וְכָל שֶׁהוֹרְגָן זָכָה. וְכֵן כֹּהֵן שֶׁשִּׁמֵּשׁ בְּטֻמְאָה לֹא הָיוּ אֶחָיו הַכֹּהֲנִים מְבִיאִין אוֹתוֹ לְבֵית דִּין אֶלָּא פִּרְחֵי כְּהֻנָּה הָיוּ מוֹצִיאִין אוֹתוֹ חוּץ לָעֲזָרָה וּפוֹצְעִין אֶת מֹחוֹ בִּגְזִירִין. גְּזֵרַת הַכָּתוּב הִיא שֶׁאֵין מְמִיתִין בֵּית דִּין וְלֹא מַלְקִין אֶת הָאָדָם בְּהוֹדָאַת פִּיו אֶלָּא עַל פִּי שְׁנַיִם עֵדִים. וְזֶה שֶׁהָרַג יְהוֹשֻׁעַ עָכָן וְדָוִד לְגֵר עֲמָלֵקִי בְּהוֹדָאַת פִּיהֶם הוֹרָאַת שָׁעָה הָיְתָה אוֹ דִּין מַלְכוּת הָיָה. אֲבָל הַסַּנְהֶדְרִין אֵין מְמִיתִין וְלֹא מַלְקִין הַמּוֹדֶה בַּעֲבֵרָה שֶׁמָּא נִטְרְפָה דַּעְתּוֹ בְּדָבָר זֶה. שֶׁמָּא מִן הָעֲמֵלִין מָרֵי נֶפֶשׁ הוּא הַמְחַכִּים לָמוּת שֶׁתּוֹקְעִין הַחֲרָבוֹת בְּבִטְנָם וּמַשְׁלִיכִין עַצְמָן מֵעַל הַגַּגּוֹת שֶׁמָּא כָּךְ זֶה יָבוֹא וְיֹאמַר דָּבָר שֶׁלֹּא עָשָׂה כְּדֵי שֶׁיֵּהָרֵג וּכְלָלוֹ שֶׁל דָּבָר גְּזֵרַת מֶלֶךְ הִיא:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 5":["אֵין מַעֲמִידִין מֶלֶךְ אֶלָּא עַל פִּי בֵּית דִּין שֶׁל שִׁבְעִים וְאֶחָד. וְאֵין עוֹשִׂין סַנְהֶדְרִי קְטַנָּה לְכָל שֵׁבֶט וְשֵׁבֶט וּלְכָל עִיר וְעִיר אֶלָּא עַל פִּי בֵּית דִּין שֶׁל שִׁבְעִים וְאֶחָד. וְאֵין דָּנִין לֹא אֶת הַשֵּׁבֶט שֶׁהֻדַּח כֻּלּוֹ וְלֹא אֶת נְבִיא הַשֶּׁקֶר וְלֹא אֶת כֹּהֵן גָּדוֹל בְּדִינֵי נְפָשׁוֹת אֶלָּא בְּבֵית דִּין הַגָּדוֹל. אֲבָל דִּינֵי מָמוֹנוֹת [שֶׁל כֹּהֵן גָּדוֹל] בִּשְׁלֹשָׁה. וְכֵן אֵין עוֹשִׂין זָקֵן מַמְרֵא וְלֹא עוֹשִׂין עִיר הַנִּדַּחַת וְלֹא מַשְׁקִין אֶת הַסּוֹטָה אֶלָּא בְּבֵית דִּין הַגָּדוֹל. וְאֵין מוֹסִיפִין עַל הָעִיר וְעַל הָעֲזָרוֹת וְלֹא מוֹצִיאִין לְמִלְחֶמֶת הָרְשׁוּת וְלִמְדִידַת הֶחָלָל אֶלָּא עַל פִּי בֵּית דִּין הַגָּדוֹל. שֶׁנֶּאֱמַר (שמות יח כב) \"כָּל הַדָּבָר הַגָּדל יָבִיאוּ אֵלֶיךָ\":","אֵין דָּנִין דִּינֵי נְפָשׁוֹת בְּפָחוֹת מֵעֶשְׂרִים וּשְׁלֹשָׁה שֶׁהֵן סַנְהֶדְרִי קְטַנָּה בֵּין דִּינֵי נְפָשׁוֹת שֶׁל אָדָם בֵּין דִּינֵי נְפָשׁוֹת שֶׁל בְּהֵמָה. לְפִיכָךְ אֵין דָּנִין שׁוֹר הַנִּסְקָל וְלֹא הַבְּהֵמָה הַנִּרְבַּעַת אוֹ הָרוֹבֵעַ אֶלָּא בְּבֵית דִּין שֶׁל עֶשְׂרִים וּשְׁלֹשָׁה. אֲפִלּוּ אֲרִי וְדֹב וּבַרְדְּלָס שֶׁהֵן בְּנֵי תַּרְבּוּת וְיֵשׁ לָהֶן בְּעָלִים שֶׁהֵמִיתוּ מִיתָתָן בְּעֶשְׂרִים וּשְׁלֹשָׁה. אֲבָל נָחָשׁ שֶׁהֵמִית אֶחָד הוֹרֵג אוֹתוֹ:","הַמּוֹצִיא שֵׁם רַע אֵין דָּנִין אוֹתוֹ תְּחִלָּה אֶלָּא בְּבֵית דִּין שֶׁל עֶשְׂרִים וּשְׁלֹשָׁה מִפְּנֵי שֶׁיֵּשׁ בְּדִינוֹ צַד דִּינֵי נְפָשׁוֹת שֶׁמָּא יִהְיֶה הַדָּבָר אֱמֶת וְתִסָּקֵל הַבַּת. לֹא נֶאֶמְנוּ דִּבְרֵי הַבַּעַל וּבָא הָאָב לְתָבְעוֹ בִּקְנָס דִּינוֹ בִּשְׁלֹשָׁה. וּמִנַּיִן שֶׁאֵין דָּנִין דִּינֵי נְפָשׁוֹת אֶלָּא בְּעֶשְׂרִים וּשְׁלֹשָׁה. אַף עַל פִּי שֶׁדִּבְרֵי קַבָּלָה הֵן הֲרֵי הוּא אוֹמֵר (במדבר לה כד) \"וְשָׁפְטוּ הָעֵדָה\" (במדבר לה כה) \"וְהִצִּילוּ הָעֵדָה\" עֵדָה שׁוֹפֶטֶת וְעֵדָה מַצֶּלֶת. עֵדָה שׁוֹפֶטֶת וְהֵן הַמְחַיְּבִין. וְעֵדָה מַצֶּלֶת וְהֵן הַמְזַכִּין. וְאֵין עֵדָה פָּחוֹת מֵעֲשָׂרָה הֲרֵי עֶשְׂרִים. וּמוֹסִיפִין שְׁלֹשָׁה כְּדֵי שֶׁלֹּא יְהֵא בֵּית דִּין שָׁקוּל וְיִהְיֶה בּוֹ אַחֲרֵי רַבִּים לְהַטֹּת:","מַכּוֹת בִּשְׁלֹשָׁה וְאַף עַל פִּי שֶׁאֶפְשָׁר שֶׁיָּמוּת כְּשֶׁמַּלְקִין אוֹתוֹ:","עֲרִיפַת הָעֶגְלָה בַּחֲמִשָּׁה:","עִבּוּר הַחֹדֶשׁ בִּשְׁלֹשָׁה:","עִבּוּר הַשָּׁנָה בְּשִׁבְעָה. וְכָל אֵלּוּ סְמוּכִין כְּמוֹ שֶׁבֵּאַרְנוּ:","דִּינֵי קְנָסוֹת כְּגוֹן גְּזֵלוֹת וְחַבָּלוֹת וְתַשְׁלוּמֵי כֶּפֶל וְתַשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה וְהָאוֹנֵס וְהַמְפַתֶּה וְכַיּוֹצֵא בָּהֶן אֵין דָּנִין אוֹתָם אֶלָּא שְׁלֹשָׁה מֻמְחִים וְהֵם הַסְּמוּכִין בְּאֶרֶץ יִשְׂרָאֵל. אֲבָל שְׁאָר דִּינֵי מָמוֹנוֹת כְּגוֹן הוֹדָאוֹת וְהַלְוָאוֹת אֵינָן צְרִיכִין מֻמְחֶה אֶלָּא אֲפִלּוּ שְׁלֹשָׁה הֶדְיוֹטוֹת וַאֲפִלּוּ אֶחָד מֻמְחֶה דָּן אוֹתָן. לְפִיכָךְ דָּנִין בְּהוֹדָאוֹת וְהַלְוָאוֹת וְכַיּוֹצֵא בָּהֶן בְּחוּצָה לָאָרֶץ. אַף עַל פִּי שֶׁאֵין בֵּית דִּין שֶׁל חוּצָה לָאָרֶץ אֱלֹהִים שְׁלִיחוּת בֵּית דִּין שֶׁל אֶרֶץ יִשְׂרָאֵל עוֹשִׂין. וְאֵין לָהֶן רְשׁוּת לָדוּן דִּינֵי קְנָסוֹת בִּשְׁלִיחוּתָן:","אֵין דָּנִין בֵּית דִּין שֶׁל חוּצָה לָאָרֶץ אֶלָּא דְּבָרִים הַמְּצוּיִין תָּמִיד וְיֵשׁ בָּהֶן חֶסְרוֹן כִּיס. כְּגוֹן הוֹדָאוֹת וְהַלְוָאוֹת וּמַזִּיק מָמוֹן חֲבֵרוֹ. אֲבָל דְּבָרִים שֶׁאֵין מְצוּיִין אַף עַל פִּי שֶׁיֵּשׁ בָּהֶן חֶסְרוֹן כִּיס כְּגוֹן בְּהֵמָה שֶׁחָבְלָה בַּחֲבֶרְתָּהּ. אוֹ דְּבָרִים הַמְּצוּיִין אֲבָל אֵין בָּהֶן חֶסְרוֹן כִּיס כְּגוֹן תַּשְׁלוּמֵי כֶּפֶל. אֵין דָּנִין אוֹתָן דַּיָּנֵי חוּצָה לָאָרֶץ. וְכֵן כָּל הַקְּנָסוֹת שֶׁקָּנְסוּ חֲכָמִים בְּתוֹקֵעַ לַחֲבֵרוֹ וּבְסוֹטֵר אֶת חֲבֵרוֹ וְכַיּוֹצֵא בָּהֶן אֵין גּוֹבִין אוֹתָן דַּיָּנֵי חוּצָה לָאָרֶץ. וְכָל הַמְשַׁלֵּם חֲצִי נֵזֶק אֵין גּוֹבִין אוֹתוֹ דַּיָּנֵי חוּצָה לָאָרֶץ חוּץ מֵחֲצִי נֵזֶק צְרוֹרוֹת מִפְּנֵי שֶׁהוּא מָמוֹן וְאֵינוֹ קְנָס:","כָּל הַנִּשּׁוֹם כְּעֶבֶד אֵין גּוֹבִין אוֹתוֹ דַּיָּנֵי חוּצָה לָאָרֶץ. לְפִיכָךְ אָדָם שֶׁחָבַל בַּחֲבֵרוֹ אֵין גּוֹבִין הַנֵּזֶק וְהַצַּעַר וְהַבּשֶׁת שֶׁהוּא חַיָּב בָּהֶן דַּיָּנֵי חוּצָה לָאָרֶץ. אֲבָל שֶׁבֶת וְרִפּוּי גּוֹבִין מִפְּנֵי שֶׁיֵּשׁ בָּהֶן חֶסְרוֹן כִּיס. וְכֵן הוֹרוּ הַגְּאוֹנִים וְאָמְרוּ שֶׁמַּעֲשִׂים בְּכָל יוֹם לִגְבּוֹת שֶׁבֶת וְרִפּוּי בְּבָבֶל:","בְּהֵמָה שֶׁהִזִּיקָה אֶת הָאָדָם אֵין גּוֹבִין נִזְקוֹ דַּיָּנֵי חוּצָה לָאָרֶץ מִפְּנֵי שֶׁהוּא דָּבָר שֶׁאֵינוֹ מָצוּי. אֲבָל אָדָם שֶׁהִזִּיק בֶּהֱמַת חֲבֵרוֹ מְשַׁלֵּם נֵזֶק שָׁלֵם בְּכָל מָקוֹם כְּמִי שֶׁקָּרַע כְּסוּתוֹ אוֹ שָׁבַר כֵּלָיו אוֹ קִצֵּץ נְטִיעוֹתָיו. וְכֵן בְּהֵמָה שֶׁהִזִּיקָה בְּשֵׁן וְרֶגֶל הוֹאִיל וְהִיא מוּעֶדֶת לָהֶן מִתְּחִלָּתָהּ הֲרֵי זֶה דָּבָר מָצוּי וְגוֹבִין אוֹתוֹ דַּיָּנֵי חוּצָה לָאָרֶץ. בֵּין שֶׁהִזִּיקָה בְּהֵמָה אַחֶרֶת כְּגוֹן שֶׁנִּתְחַכְּכָה בָּהּ אוֹ אָכְלָה פֵּרוֹת שֶׁדַּרְכָּהּ לְאָכְלָן וְכַיּוֹצֵא בָּזֶה. בֵּין שֶׁהִזִּיקָה אֳכָלִין וְכֵלִים שֶׁהִיא חַיֶּבֶת עֲלֵיהֶן נֵזֶק שָׁלֵם הַכּל גּוֹבִין דַּיָּנֵי חוּצָה לָאָרֶץ. אֲבָל אִם הָיְתָה תַּמָּה וְהוּעֲדָה וְהִזִּיקָה כְּגוֹן שֶׁנָּשְׁכָה אוֹ נָגְפָה אוֹ רָבְצָה אוֹ בָּעֲטָה אוֹ נָגְחָה אֵין גּוֹבִין הַנֵּזֶק הַזֶּה הַשָּׁלֵם דַּיָּנֵי חוּצָה לָאָרֶץ שֶׁאֵין מוּעָד בְּחוּצָה לָאָרֶץ. וַאֲפִלּוּ הוּעַד בָּאָרֶץ וְיָצָא לְחוּצָה לָאָרֶץ וְהִזִּיק אֵין גּוֹבִין נִזְקוֹ מִפְּנֵי שֶׁאֵינוֹ דָּבָר מָצוּי:","מִפְּנֵי מָה אֵין מוּעָד בְּחוּצָה לָאָרֶץ. לְפִי שֶׁצָּרִיךְ לְהָעִיד בּוֹ בִּפְנֵי בֵּית דִּין וְאֵין שָׁם בֵּית דִּין אֶלָּא הַסְּמוּכִין בָּאָרֶץ. לְפִיכָךְ אִם הָיוּ בֵּית דִּין בְּחוּצָה לָאָרֶץ כְּשֵׁם שֶׁהֵן דָּנִים דִּינֵי קְנָסוֹת בְּחוּצָה לָאָרֶץ כָּךְ מְעִידִים אֶת הַבְּהֵמָה בִּפְנֵיהֶם בְּחוּצָה לָאָרֶץ:","מִי שֶׁגָּנַב אוֹ גָּזַל גּוֹבִין מִמֶּנּוּ הַקֶּרֶן דַּיָּנֵי חוּצָה לָאָרֶץ אֲבָל אֵין גּוֹבִין אֶת הַכֶּפֶל:","וְלֹא כָּל הַמְשַׁלֵּם עַל פִּי עַצְמוֹ גּוֹבִין מִמֶּנּוּ דַּיָּנֵי חוּצָה לָאָרֶץ שֶׁהֲרֵי הַפְּגָם וְהַבּשֶׁת וְהַכֹּפֶר מְשַׁלֵּם אָדָם עַל פִּי עַצְמוֹ כְּגוֹן שֶׁאָמַר פִּתִּיתִי בִּתּוֹ שֶׁל פְּלוֹנִי וְהֵמִית שׁוֹרִי אֶת פְּלוֹנִי וְאֵין גּוֹבִין אוֹתוֹ דַּיָּנֵי חוּצָה לָאָרֶץ:","דִּינֵי גְּרָמוֹת אֵינָן כִּקְנָסוֹת וְגוֹבִין אוֹתָן וְדָנִין בָּהֶן בְּחוּצָה לָאָרֶץ:","וְכֵן דִּין הַמּוֹסֵר מָמוֹן חֲבֵרוֹ אַף עַל פִּי שֶׁלֹּא עָשָׂה מַעֲשֶׂה גּוֹבִין אוֹתוֹ דַּיָּנֵי חוּצָה לָאָרֶץ:","מִנְהַג הַיְשִׁיבוֹת בְּחוּצָה לָאָרֶץ אַף עַל פִּי שֶׁאֵין גּוֹבִין שָׁם קְנָס מְנַדִּין אוֹתוֹ עַד שֶׁיְּפַיֵּס לְבַעַל דִּינוֹ אוֹ יַעֲלֶה עִמּוֹ לְדִין לְאֶרֶץ יִשְׂרָאֵל. וְכֵיוָן שֶׁיִּתֵּן לוֹ שִׁעוּר הָרָאוּי לוֹ מַתִּירִין נִדּוּיוֹ בֵּין שֶׁנִּתְפַּיֵּס בַּעַל דִּינוֹ בֵּין שֶׁלֹּא נִתְפַּיֵּס. וְכֵן אִם תָּפַשׂ הַנִּזָּק שִׁעוּר מַה שֶּׁרָאוּי לוֹ לִטּל אֵין מוֹצִיאִין אוֹתוֹ מִיָּדוֹ:","יָחִיד שֶׁהוּא מֻמְחֶה לָרַבִּים אַף עַל פִּי שֶׁהוּא דָּן דִּינֵי מָמוֹנוֹת יְחִידִי אֵין הַהוֹדָאָה בְּפָנָיו הוֹדָאָה בְּבֵית דִּין וַאֲפִלּוּ הָיָה סָמוּךְ. אֲבָל הַשְּׁלֹשָׁה אַף עַל פִּי שֶׁאֵינָן סְמוּכִין וַהֲרֵי הֵן הֶדְיוֹטוֹת וְאֵין אֲנִי קוֹרֵא בָּהֶם אֱלֹהִים הֲרֵי הַהוֹדָאָה בִּפְנֵיהֶם הוֹדָאָה בְּבֵית דִּין. וְכֵן הַכּוֹפֵר בִּפְנֵיהֶם וְאַחַר כָּךְ בָּאוּ עֵדִים הֻחְזַק כַּפְרָן וְאֵינוֹ יָכוֹל לַחְזֹר וְלִטְעֹן כְּמוֹ שֶׁבֵּאַרְנוּ. כְּלָלוֹ שֶׁל דָּבָר הֲרֵי הֵן לְעִנְיַן הוֹדָאוֹת וְהַלְוָאוֹת וְכַיּוֹצֵא בָּהֶן כְּבֵית דִּין הַסָּמוּךְ לְכָל הַדְּבָרִים:"],"Mishneh Torah, Theft 8":["מִצְוַת עֲשֵׂה לְצַדֵּק הַמֹּאזְנַיִם וְהַמִּשְׁקָלוֹת וְהַמִּדּוֹת יָפֶה יָפֶה וּלְדַקְדֵּק בְּחֶשְׁבּוֹנָן בִּשְׁעַת עֲשִׂיָּתָן שֶׁנֶּאֱמַר (ויקרא יט לו) \"מֹאזְנֵי צֶדֶק\" וְגוֹ'. וְכֵן בְּמִדַּת הַקַּרְקַע צָרִיךְ לְדַקְדֵּק בְּחֶשְׁבּוֹן מְשִׁיחַת הַקַּרְקַע עַל פִּי הָעִקָּרִים הַמִּתְבָּאֲרִים בְּכִתְבֵי הַגִּימָטְרִיָּא. שֶׁאֲפִילוּ מְלוֹא אֶצְבַּע מִן הַקַּרְקַע רוֹאִין אוֹתָהּ כְּאִלּוּ הִיא מְלֵאָה כַּרְכּוֹם:","אַרְבַּע אַמּוֹת הַסְּמוּכִין לֶחָרִיץ מְזַלְזְלִין בִּמְשִׁיחָתָן וְהַסְּמוּכִים לִשְׂפַת הַנָּהָר אֵין מוֹשְׁחִין אוֹתָן כְּלָל מִפְּנֵי שֶׁהֵן שֶׁל בְּנֵי רְשׁוּת הָרַבִּים:","וְהַמּוֹדֵד אֶת הַקַּרְקַע לֹא יָמֹד לְאֶחָד בִּימוֹת הַחַמָּה וּלְאֶחָד בִּימוֹת הַגְּשָׁמִים מִפְּנֵי שֶׁהַחֶבֶל מִתְקַצֵּר בִּימוֹת הַחַמָּה. לְפִיכָךְ אִם מָדַד בְּקָנֶה אוֹ בְּשַׁלְשֶׁלֶת שֶׁל בַּרְזֶל וְכַיּוֹצֵא בָּהֶם אֵין בְּכָךְ כְּלוּם:","אֵין עוֹשִׂין מִשְׁקָלוֹת לֹא שֶׁל בַּרְזֶל וְלֹא שֶׁל עוֹפֶרֶת וְלֹא שֶׁל שְׁאָר מִינֵי מַתָּכוֹת כָּאֵלּוּ מִפְּנֵי שֶׁמַּעֲלִין חֲלוּדָה וּמִתְחַסְּרִין. אֲבָל עוֹשִׂין שֶׁל צְחִיחַ סֶלַע וְשֶׁל זְכוּכִית וְשֶׁל אֶבֶן שֹׁהַם וְכַיּוֹצֵא בָּהֶן:","אֵין עוֹשִׂין אֶת הַמַּחַק לֹא שֶׁל דְּלַעַת מִפְּנֵי שֶׁהוּא מֵקֵל וְלֹא שֶׁל מַתֶּכֶת מִפְּנֵי שֶׁהוּא מַכְבִּיד. אֲבָל עוֹשֵׂהוּ שֶׁל זַיִת וְשֶׁל אֱגוֹזִים וְשֶׁל שִׁקְמָה וְשֶׁל אֶשְׁכְּרוֹעַ וְכַיּוֹצֵא בָּהֶן:","אֵין עוֹשִׂין אֶת הַמַּחַק צִדּוֹ אֶחָד קָצָר וְצִדּוֹ אֶחָד עָבֶה. וְלֹא יִמְחֹק מְעַט מְעַט מִפְּנֵי שֶׁמַּפְחִיתוֹ לַמּוֹכֵר. וְלֹא יִמְחֹק בְּבַת אַחַת מִפְּנֵי שֶׁמַּפְחִיתוֹ לַלּוֹקֵחַ:","אֵין טוֹמְנִין אֶת הַמִּשְׁקָלוֹת בְּמֶלַח כְּדֵי שֶׁיִּפְחֲתוּ. וְלֹא יַרְתִּיחַ בְּמִדַּת הַלַּח בְּעֵת שֶׁמּוֹדֵד. וַאֲפִלּוּ הָיְתָה הַמִּדָּה קְטַנָּה בְּיוֹתֵר. שֶׁהֲרֵי הַתּוֹרָה הִקְפִּידָה עַל הַמִּדּוֹת בְּכָל שֶׁהוּא שֶׁנֶּאֱמַר (ויקרא יט לה) \"וּבַמְּשׂוּרָה\" וְהִיא מִדָּה אַחַת קְטַנָּה מִשְּׁלֹשִׁים וּשְׁלֹשָׁה בְּלוֹג:","מוֹכְרֵי עֲשָׁשִׁיּוֹת שֶׁל בַּרְזֶל וְכַיּוֹצֵא בָּהֶן צָרִיךְ לִהְיוֹת חוּטֵי הַמֹּאזְנַיִם שֶׁאוֹחֵז הַשּׁוֹקֵל בְּיָדוֹ תָּלוּי בַּאֲוִיר שְׁלֹשָׁה טְפָחִים וּגְבוֹהִין מִן הָאָרֶץ שְׁלֹשָׁה טְפָחִים וְאֹרֶךְ קְנֵי הַמֹּאזְנַיִם וְאֹרֶךְ הַחוּטִים שְׁנֵים עָשָׂר טֶפַח:","מֹאזְנַיִם שֶׁל מוֹכְרֵי צֶמֶר וְשֶׁל מוֹכְרֵי זְכוּכִית יִהְיֶה אֹרֶךְ הַחוּטִים שֶׁהֵן תְּלוּיִין בּוֹ שְׁנֵי טְפָחִים וּגְבוֹהִין מִן הָאָרֶץ שְׁנֵי טְפָחִים וְהַקָּנֶה וְהַחוּטִין אָרְכָּן תִּשְׁעָה טְפָחִים:","מֹאזְנַיִם שֶׁל חֶנְוָנִי וְשֶׁל בַּעַל הַבַּיִת יִהְיֶה אֹרֶךְ הַחוּט שֶׁהֵן תְּלוּיִים בּוֹ טֶפַח וּגְבוֹהִין מִן הָאָרֶץ טֶפַח וְהַקָּנֶה וְהַחוּטִין אָרְכָּן שִׁשָּׁה טְפָחִים:","הַחוּט שֶׁתּוֹלִין בּוֹ הַפֶּלֶס וְכֵן חוּט מֹאזְנַיִם שֶׁל זָהָב וְשֶׁל מוֹכְרֵי אַרְגָּמָן טוֹב אָרְכּוֹ שָׁלֹשׁ אֶצְבָּעוֹת וּגְבוֹהִין מִן הָאָרֶץ שָׁלֹשׁ אֶצְבָּעוֹת וְאֹרֶךְ הַפֶּלֶס וְאֹרֶךְ הַשַּׁלְשְׁלָאוֹת שֶׁלּוֹ כְּפִי מַה שֶּׁהוּא רוֹצֶה:","מִנַּיִן שֶׁחַיָּב הַמּוֹכֵר לְהַכְרִיעַ לַלּוֹקֵחַ בְּעֵת שֶׁשּׁוֹקֵל לוֹ שֶׁנֶּאֱמַר (דברים כה טו) \"אֶבֶן שְׁלֵמָה וָצֶדֶק יִהְיֶה לָּךְ\" אָמְרָה תּוֹרָה צַדֵּק מִשֶּׁלְּךָ וְתֵן לוֹ:","וְכַמָּה בְּלַח אֶחָד לְמֵאָה וּבְיָבֵשׁ אֶחָד לְאַרְבַּע מֵאוֹת. כֵּיצַד. מָכַר לוֹ עֶשֶׂר לִיטְרָא לַח נוֹתֵן לוֹ גֵּירוּמִין אֶחָד מֵעֲשָׂרָה בְּלִיטְרָא. וְאִם מָכַר לוֹ עֶשְׂרִים לִיטְרִין יָבֵשׁ נוֹתֵן לוֹ גֵּירוּמָיו אֶחָד מֵעֶשְׂרִים בְּלִיטְרָא. וְכֵן לְפִי חֶשְׁבּוֹן זֶה בֵּין רַב בֵּין מְעַט:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּמָקוֹם שֶׁנָּהֲגוּ לִמְכֹּר עַיִן בְּעַיִן. אֲבָל בְּמָקוֹם שֶׁנָּהֲגוּ לְהַכְרִיעַ חַיָּב לְהַכְרִיעַ לוֹ טֶפַח:","הָיָה שׁוֹקֵל לוֹ עֶשֶׂר לִיטְרִין לֹא יֹאמַר לוֹ שְׁקל אַחַת אַחַת וְהַכְרַע אֶלָּא שׁוֹקֵל לוֹ עֲשָׂרָה בְּבַת אַחַת וְהֶכְרֵעַ אֶחָד לְכֻלָּן:","מָקוֹם שֶׁנָּהֲגוּ לָמֹד בְּדַקָּה לֹא יָמֹד בְּגַסָּה. בְּגַסָּה לֹא יָמֹד בְּדַקָּה. לִמְחֹק לֹא יִגְדּשׁ וְיוֹסִיף בְּדָמִים. וְכֵן אִם נָהֲגוּ לִגְדּשׁ לֹא יִמְחֹק וְיִפְחֹת מִן הַדָּמִים. אֶלָּא מוֹדֵד כְּמִנְהַג הַמְּדִינָה:","בְּנֵי מְדִינָה שֶׁרָצוּ לְהוֹסִיף עַל הַמִּדּוֹת אוֹ עַל הַמִּשְׁקָלוֹת לֹא יוֹסִיפוּ יֶתֶר עַל שְׁתוּת. שֶׁאִם הָיָה הַקַּב מֵכִיל חֲמִשָּׁה וַעֲשָׂאוּהוּ מֵכִיל שִׁשָּׁה הָרְשׁוּת בְּיָדָן. יֶתֶר עַל שִׁשָּׁה לֹא יַעֲשׂוּ:","הַסִּיטוֹן מְקַנֵּחַ אֶת מִדּוֹתָיו אַחַת לִשְׁלֹשִׁים יוֹם. וּבַעַל הַבַּיִת אַחַת לִשְׁנֵים עָשָׂר חֹדֶשׁ. וְהַחֶנְוָנִי מְקַנְּחָן פַּעֲמַיִם בְּשַׁבָּת. וּמְמַחֶה מִשְׁקְלוֹתָיו פַּעַם אַחַת בְּשַׁבָּת וּמְקַנֵּחַ מֹאזְנַיִם עַל כָּל מִשְׁקָל וּמִשְׁקָל כְּדֵי שֶׁלֹּא יַחְלִידוּ:","הַמְבַקֵּשׁ לִשְׁקל שְׁלֹשָׁה רְבִיעֵי לִיטְרָא נוֹתֵן לִיטְרָא בְּכַף מֹאזְנַיִם וְהַבָּשָׂר וּרְבִיעַ לִיטְרָא בְּכַף שְׁנִיָּה שֶׁאִם אַתָּה אוֹמֵר נוֹתֵן חֲצִי לִיטְרָא וּרְבִיעַ לִיטְרָא בְּכַף אַחַת שֶׁמָּא יִפּל רְבִיעַ הַלִּיטְרָא וְאֵין הַלּוֹקֵחַ רוֹאֵהוּ:","חַיָּבִין בֵּית דִּין לְהַעֲמִיד שׁוֹטְרִים בְּכָל מְדִינָה וּמְדִינָה וּבְכָל פֶּלֶךְ וּפֶלֶךְ שֶׁיִּהְיוּ מְחַזְּרִין עַל הַחֲנֻיּוֹת וּמְצַדְּקִין אֶת הַמֹּאזְנַיִם וְאֶת הַמִּדּוֹת וּפוֹסְקִין הַשְּׁעָרִים. וְכָל מִי שֶׁנִּמְצָא עִמּוֹ מִשְׁקָל חָסֵר אוֹ מִדָּה חֲסֵרָה אוֹ מֹאזְנַיִם מְקֻלְקָלִין יֵשׁ לָהֶם רְשׁוּת לְהַכּוֹתוֹ כְּפִי כֹּחוֹ וּלְקָנְסוֹ כְּפִי רְאוֹת בֵּית דִּין לְחַזֵּק הַדָּבָר. וְכָל מִי שֶׁמַּפְקִיעַ אֶת הַשַּׁעַר וּמוֹכֵר בְּיֹקֶר מַכִּין אוֹתוֹ וְכוֹפִין אוֹתוֹ וּמוֹכֵר כְּשַׁעַר הַשּׁוּק:"],"Mishneh Torah, Those Who Defile Bed or Seat 12":["הַמַּפְקִיד כֵּלִים אֵצֶל עַם הָאָרֶץ אוֹ שֶׁנָּתַן כְּלִי לְאֻמָּן עַם הָאָרֶץ הֲרֵי אֵלּוּ טְמֵאִים טְמֵא מֵת וּטְמֵאִין מִדְרָס. וְאִם מַכִּירוֹ שֶׁהוּא אוֹכֵל בִּתְרוּמָה טְהוֹרִים מִטְּמֵא מֵת אֲבָל טְמֵאִים מִדְרָס מִפְּנֵי שֶׁאִשְׁתּוֹ נִדָּה יוֹשֶׁבֶת עֲלֵיהֶם שֶׁלֹּא מִדַּעְתּוֹ שֶׁהֲרֵי אֵין נִזְהָרִין מִן הַטֻּמְאוֹת בְּבָתֵּי עַמֵּי הָאָרֶץ:","הַמַּנִּיחַ כֵּלָיו בִּפְנֵי עַם הָאָרֶץ וְאָמַר לוֹ שְׁמֹר לִי אֶת אֵלּוּ הֲרֵי אֵלּוּ טְמֵאִין מִדְרָס וּטְהוֹרִין מִטְּמֵא מֵת. הִנִּיחָן עַל כְּתֵפוֹ טְמֵאִין מִדְרָס וּטְמֵא מֵת. שָׁכַח כֵּלָיו בְּבֵית הַכְּנֶסֶת הֲרֵי הֵן טְהוֹרִין שֶׁאֵינוֹ רְשׁוּת עַם הָאָרֶץ גְּמוּרָה. הִנִּיחַ כֵּלָיו בַּמֶּרְחָץ וּבָא וּמְצָאָן כְּמוֹת שֶׁהֵן טְהוֹרִין. וּמְלַמְּדִין אוֹתוֹ שֶׁלֹּא יַעֲשֶׂה כֵן. הִנִּיחַ גִּתּוֹ וּבוֹרוֹ אַף עַל פִּי שֶׁנִּכְנַס לָעִיר וּבָא וּמָצָא עַם הָאָרֶץ בְּצִדּוֹ טְהוֹרִין מִפְּנֵי שֶׁאֵין לוֹ רְשׁוּת שֶׁיִּכָּנֵס:","הַמּוֹסֵר מַפְתֵּחַ בֵּיתוֹ לְעַם הָאָרֶץ כָּל שֶׁבַּבַּיִת טָהוֹר שֶׁלֹּא מָסַר לוֹ אֶלָּא שְׁמִירַת הַמַּפְתֵּחַ:","הַמַּנִּיחַ כֵּלָיו בְּחַלּוֹנוֹת שֶׁל מֶרְחָץ וְנָעַל עֲלֵיהֶם אַף עַל פִּי שֶׁנָּתַן הַמַּפְתֵּחַ לְעַם הָאָרֶץ כֵּלָיו טְהוֹרִין. וְכֵן אִם חָתַם עַל הַחַלּוֹן אוֹ עָשָׂה לוֹ סִימָן אֲפִלּוּ מָצָא הַחוֹתָם מְקֻלְקָל הֲרֵי כָּל אֵלּוּ טְהוֹרִין:","הַמַּנִּיחַ עַם הָאָרֶץ בְּתוֹךְ בֵּיתוֹ לְשָׁמְרוֹ וְיָשַׁב הוּא מֵרָחוֹק בִּזְמַן שֶׁהוּא רוֹאֶה אֶת הַנִּכְנָסִין וְאֶת הַיּוֹצְאִין הֲרֵי כָּל שֶׁבַּבַּיִת מִן הָאֳכָלִין וְהַמַּשְׁקִין וּכְלִי חֶרֶס שֶׁאֵינוֹ מֻקָּף צָמִיד פָּתִיל טְמֵאִין אֲבָל הַמִּשְׁכָּבוֹת וְהַמֶּרְכָּבוֹת וּכְלִי חֶרֶס הַמֻּקָּף צָמִיד פָּתִיל טְהוֹרִין. וְאִם אֵינוֹ רוֹאֶה לֹא אֶת הַנִּכְנָסִין וְלֹא אֶת הַיּוֹצְאִין כָּל שֶׁבַּבַּיִת טָמֵא אֲפִלּוּ הָיָה כָּפוּת אוֹ כְּרוּת יָדַיִם וְרַגְלַיִם הַכּל טָמֵא מִפְּנֵי שֶׁהֵן בִּרְשׁוּת עַם הָאָרֶץ:","חָבֵר שֶׁהָיָה יָשֵׁן בְּבֵיתוֹ שֶׁל עַם הָאָרֶץ וְהָיוּ כֵּלִים מְקֻפָּלִים וּמֻנָּחִין תַּחַת רֹאשׁוֹ וְסַנְדָּלוֹ וְחָבִיתוֹ לְפָנָיו הֲרֵי אֵלּוּ טְהוֹרִין מִפְּנֵי שֶׁהֵן בְּחֶזְקַת שְׁמִירַת בַּעֲלֵיהֶן וְלֹא יִגַּע בָּהֶן עַם הָאָרֶץ שֶׁהֲרֵי הוּא אוֹמֵר עַתָּה יֵעוֹר וְיַבִּיט בִּי:","עַם הָאָרֶץ שֶׁשָּׁאַל מֵחָבֵר מִטָּה שֶׁיָּשֵׁן עָלֶיהָ וְיָשַׁן עָלֶיהָ בְּתוֹךְ בֵּיתוֹ שֶׁל חָבֵר אֵין טָמֵא אֶלָּא אוֹתָהּ הַמִּטָּה וְעַד מָקוֹם שֶׁהוּא יָכוֹל לִפְשֹׁט אֶת יָדוֹ מֵאוֹתָהּ הַמִּטָּה וְלִגַּע:","חָבֵר שֶׁאָמַר לְעַם הָאָרֶץ שְׁמֹר לִי פָּרָה זוֹ שֶׁלֹּא תִּכָּנֵס לַבַּיִת אוֹ שֶׁלֹּא תְּשַׁבֵּר אֶת הַכֵּלִים הֲרֵי הַבַּיִת וְהַכֵּלִים טְהוֹרִים. שֶׁלֹּא מָסַר לוֹ אֶלָּא שְׁמִירַת הַפָּרָה. אֲבָל אִם אָמַר לוֹ שְׁמֹר לִי בַּיִת זֶה שֶׁלֹּא תִּכָּנֵס בּוֹ הַפָּרָה וְכֵלִים אֵלּוּ שֶׁלֹּא תְּשַׁבְּרֵם הֲרֵי הֵן טְמֵאִין:","הַמַּנִּיחַ עַם הָאָרֶץ בְּתוֹךְ בֵּיתוֹ וְיָצָא הִנִּיחוֹ עֵר וּמְצָאוֹ עֵר יָשֵׁן וּמְצָאוֹ יָשֵׁן אוֹ שֶׁהִנִּיחוֹ עֵר וּמְצָאוֹ יָשֵׁן כָּל שֶׁבַּבַּיִת טָהוֹר. הִנִּיחוֹ יָשֵׁן וּמְצָאוֹ עֵר כָּל מָקוֹם הַקָּרוֹב מִמֶּנּוּ שֶׁהוּא יָכוֹל לִפְשֹׁט אֶת יָדוֹ וְלִגַּע בּוֹ טָמֵא. וְכֵן הַמַּנִּיחַ אֻמָּנִין בְּתוֹךְ בֵּיתוֹ אֵין טָמֵא אֶלָּא עַד מָקוֹם שֶׁיְּכוֹלִין לִפְשֹׁט אֶת יְדֵיהֶן וְלִגַּע. וְאֵין אוֹמְרִים שֶׁמָּא עָלוּ עַל גַּבֵּי כִּסֵּא אוֹ עַל סֻלָּם וְנָגְעוּ בַּכְּלִי אוֹ בָּאֳכָלִין הַתְּלוּיִין לְמַעְלָה בַּכֹּתֶל:","אֵשֶׁת חָבֵר שֶׁהִנִּיחָה אֵשֶׁת עַם הָאָרֶץ טוֹחֶנֶת בְּתוֹךְ בֵּיתָה. אֲפִלּוּ פָּסְקָה הָרֵחַיִם וַאֲפִלּוּ הָיוּ שְׁתַּיִם אֵין טָמֵא אֶלָּא מָקוֹם שֶׁיְּכוֹלִין לִפְשֹׁט אֶת יָדָן וְלִגַּע. וְאֵין אוֹמְרִין שֶׁמָּא הָאַחַת טוֹחֶנֶת וְהַשְּׁנִיָּה בָּלְשָׁה כָּל שֶׁבַּבַּיִת וְשֶׁמָּא נִיתְלֵת וְעָלְתָה בַּמְּקוֹמוֹת הַגְּבוֹהוֹת:","הָאִשָּׁה שֶׁנִּכְנְסָה לְהוֹצִיא פַּת לֶעָנִי יָצָאת וּמְצָאַתּוּ עוֹמֵד בְּצַד כִּכָּרוֹת אֲפִלּוּ תְּרוּמָה הֲרֵי הֵן טְהוֹרוֹת שֶׁאֵין חֶזְקָתוֹ לִגַּע שֶׁלֹּא בִּרְשׁוּת. וְכֵן הָאִשָּׁה שֶׁיָּצְאָה וּמָצְאָה אֵשֶׁת עַם הָאָרֶץ חוֹתָה גֶּחָלִים מִתַּחַת הַקְּדֵרָה הֲרֵי הַקְּדֵרָה טְהוֹרָה:","גַּבָּאֵי מַלְכוּת שֶׁנִּכְנְסוּ לְתוֹךְ הַבַּיִת לְמַשְׁכֵּן כָּל שֶׁבַּבַּיִת טָמֵא. אִם יֵשׁ עִמָּהֶם עַכּוּ\"ם נֶאֱמָנִים לוֹמַר לֹא נָגַעְנוּ מִפְּנֵי שֶׁאֵימַת הָעַכּוּ\"ם עֲלֵיהֶן. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁיֵּשׁ שָׁם עֵדִים שֶׁנִּכְנְסוּ אוֹ שֶׁהָיָה הַמַּשְׁכּוֹן בְּיָדָם. אֲבָל אִם אָמְרוּ הֵן מֵעַצְמָן נִכְנַסְנוּ אֲבָל לֹא נָגַעְנוּ נֶאֱמָנִין שֶׁהַפֶּה שֶׁאָסַר הוּא הַפֶּה שֶׁהִתִּיר:","הַגַּנָּבִים שֶׁנִּכְנְסוּ לְתוֹךְ הַבַּיִת אֵין טָמֵא אֶלָּא מְקוֹם רַגְלֵי הַגַּנָּבִים. מִפְּנֵי שֶׁהֵן מְפַחֲדִין מִלִּבְלֹשׁ אֶלָּא (דָּבָר) שֶׁנּוֹטְלִין בִּמְזֻמָּן. וּמַה הֵן מְטַמְּאִין בִּמְקוֹם הֲלִיכָתָן הָאֳכָלִין וְהַמַּשְׁקִין וּכְלֵי חֶרֶס הַפְּתוּחִים אֲבָל הַמִּשְׁכָּבוֹת וְהַמֶּרְכָּבוֹת וּכְלֵי חֶרֶס הַמֻּקָּפִין צָמִיד פָּתִיל טְהוֹרִין. וְאִם יֵשׁ עִמָּהֶן עַכּוּ\"ם אוֹ אִשָּׁה הַכּל טָמֵא:","הַגַּבָּאִים וְהַגַּנָּבִים שֶׁעָשׂוּ תְּשׁוּבָה וְהֶחֱזִירוּ מֵעַצְמָן לֹא מֵחֲמַת יִרְאָה וְאָמְרוּ לֹא נָגַעְנוּ בְּכָל מַה שֶּׁהָיָה בַּבַּיִת כְּשֶׁנִּכְנַסְנוּ הֲרֵי אֵלּוּ נֶאֱמָנִים וַאֲפִלּוּ עַל מְקוֹם רַגְלֵיהֶן:","הַמַּנִּיחַ אֶת בֵּיתוֹ פָּתוּחַ וּמְצָאוֹ פָּתוּחַ אוֹ שֶׁמְּצָאוֹ נָעוּל. אֲפִלּוּ הִנִּיחוֹ נָעוּל וּמְצָאוֹ פָּתוּחַ וְלֹא נִגְנַב מִמֶּנּוּ כְּלוּם כָּל שֶׁבַּבַּיִת טָהוֹר. שֶׁאֲנִי אוֹמֵר הַגַּנָּבִים פְּתָחוּהוּ וְנִמְלְכוּ וְהָלְכוּ לָהֶם וְלֹא נִכְנְסוּ:","קוֹרְדוֹם שֶׁאָבַד בַּבַּיִת אוֹ שֶׁהִנִּיחוֹ בְּזָוִית זוֹ וּבָא וּמְצָאוֹ בְּזָוִית אַחֶרֶת הַבַּיִת טָמֵא שֶׁאֲנִי אוֹמֵר אָדָם טָמֵא נִכְנַס לְשָׁם וּנְטָלוֹ:","הַדָּר עִם עַם הָאָרֶץ בֶּחָצֵר וְשָׁכַח כֵּלִים בֶּחָצֵר אֲפִלּוּ חָבִיּוֹת מֻקָּפוֹת צָמִיד פָּתִיל אוֹ תַּנּוּר מֻקָּף צָמִיד פָּתִיל הֲרֵי אֵלּוּ טְמֵאִין עַד שֶׁיַּעֲשֶׂה לַתַּנּוּר מְחִצָּה גְּבוֹהָה עֲשָׂרָה טְפָחִים כְּדֵי שֶׁלֹּא יְהֵא בִּרְשׁוּת עַם הָאָרֶץ:","חָבֵר שֶׁהָיְתָה לוֹ מְחִצָּה אוֹ סֻכָּה לִפְנֵי פִּתְחוֹ שֶׁל עַם הָאָרֶץ. אוֹ שֶׁהָיְתָה מְחִצָּה אוֹ סֻכָּה שֶׁל עַם הָאָרֶץ לִפְנֵי פִּתְחוֹ שֶׁל חָבֵר. כֵּלִים שֶׁבְּתוֹכָהּ אוֹ כֵּלִים שֶׁבַּמְּחִצָּה טְמֵאִים. מִפְּנֵי שֶׁיֵּשׁ לְעַם הָאָרֶץ בְּסֻכָּה זוֹ אוֹ בִּמְחִצָּה זוֹ רְשׁוּת:","חָבֵר שֶׁהָיָה גַּגּוֹ לְמַעְלָה מִגַּגּוֹ שֶׁל עַם הָאָרֶץ הֲרֵי זֶה שׁוֹטֵחַ שָׁם כֵּלִים וּמַנִּיחַ טָהֳרוֹת וְהֵן בְּחֶזְקָתָן. אַף עַל פִּי שֶׁעַם הָאָרֶץ יָכוֹל לִפְשֹׁט יָדוֹ וְלִגַּע. וְכֵן בְּעַכּוּ\"ם אֵינוֹ חוֹשֵׁשׁ לֹא מִשּׁוּם טֻמְאָה וְלֹא מִשּׁוּם יֵין נֶסֶךְ. הָיוּ הַגַּגּוֹת זֶה בְּצַד זֶה אוֹ שֶׁהָיָה גַּגּוֹ שֶׁל עַם הָאָרֶץ לְמַעְלָה וְשָׁטַח הֶחָבֵר כֵּלִים אוֹ הִנִּיחַ טָהֳרוֹת בְּגַגּוֹ. הֲרֵי כָּל מָקוֹם שֶׁיָּכוֹל עַם הָאָרֶץ לִפְשֹׁט אֶת יָדוֹ וְלִגַּע בְּחֶזְקַת טֻמְאָה:","שְׁתֵּי חֲצֵרוֹת זוֹ לְפָנִים מִזּוֹ הַפְּנִימִית שֶׁל חָבֵר וְהַחִיצוֹנָה שֶׁל עַם הָאָרֶץ. חָבֵר מַנִּיחַ שָׁם כֵּלִים וְשׁוֹטֵחַ שָׁם פֵּרוֹת אַף עַל פִּי שֶׁיַּד עַם הָאָרֶץ מַגַּעַת לְשָׁם. מִפְּנֵי שֶׁנִּתְפַּשׂ עָלָיו כְּגַנָּב:","חָצֵר הַחֲלוּקָה בִּמְסִיפַס וְחָבֵר בְּצַד זֶה וְעַם הָאָרֶץ בְּצַד זֶה טָהֳרוֹתָיו טְהוֹרוֹת אַף עַל פִּי שֶׁיַּד עַם הָאָרֶץ מַגַּעַת. מִפְּנֵי שֶׁהֵם בִּרְשׁוּת הֶחָבֵר:","חָבֵר שֶׁנָּפַל דִּלְיוֹ לְתוֹךְ בּוֹרוֹ שֶׁל עַם הָאָרֶץ וְהָלַךְ לְהָבִיא בְּמָה יַעֲלֶנּוּ הֲרֵי זֶה טָמֵא. מִפְּנֵי שֶׁהֻנַּח בִּרְשׁוּת עַם הָאָרֶץ שָׁעָה אַחַת:","אֵשֶׁת עַם הָאָרֶץ שֶׁנִּכְנְסָה לְתוֹךְ בֵּיתוֹ שֶׁל חָבֵר לְהוֹצִיא בְּנוֹ אוֹ בִּתּוֹ אוֹ בְּהֶמְתּוֹ שֶׁל חָבֵר כָּל שֶׁבַּבַּיִת טָהוֹר. מִפְּנֵי שֶׁנִּכְנְסָה שֶׁלֹּא בִּרְשׁוּת. קַדָּר חָבֵר שֶׁהִכְנִיס קְדֵרוֹתָיו לִמְכֹּר וְיָרַד לִשְׁתּוֹת הֲרֵי הַפְּנִימִיּוֹת טְהוֹרוֹת וְהַחִיצוֹנוֹת טְמֵאוֹת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהִנִּיחָן סָמוּךְ לִרְשׁוּת הָרַבִּים מִפְּנֵי שֶׁהָעוֹבְרִים וְהַשָּׁבִין נוֹגְעִים בַּחִיצוֹנוֹת בִּשְׁעַת הֲלִיכָה. אֲבָל הָיוּ רְחוֹקוֹת מֵרְשׁוּת הָרַבִּים אִם הָיוּ כְּלֵי אֻמָּנוּתוֹ בְּיָדָיו הַכּל טְמֵאוֹת מִפְּנֵי שֶׁכֵּלָיו מוֹכִיחִין שֶׁהֻנְּחוּ לִמְכֹּר וְיַד הַכּל מְמַשְׁמְשׁוֹת בָּהֶן. אֵין כְּלֵי אֻמָּנוּתוֹ בְּיָדוֹ הַכּל טְהוֹרוֹת חֶזְקָתָן שֶׁלֹּא נָגַע בָּהֶן אָדָם. חָבֵר שֶׁהִנִּיחַ אֳכָלִין וּמַשְׁקִין עַל פֶּתַח חֲנוּתוֹ וְנִכְנַס הֲרֵי אֵלּוּ טְמֵאִים מִפְּנֵי שֶׁהָעוֹבְרִים וְהַשָּׁבִים מְמַשְׁמְשִׁין בָּהֶן:"],"Mishneh Torah, Tithes 11":["אָסוּר לִמְכֹּר אֶת הַדְּמאי לְעַם הָאָרֶץ אוֹ לִשְׁלֹחַ לוֹ דְּמַאי מִפְּנֵי שֶׁהוּא מְסַיֵּעַ לָזֶה לֶאֱכל דָּבָר הָאָסוּר. אֲבָל מוֹכְרִין וּמְשַׁלְּחִין אוֹתוֹ לְתַלְמִידֵי חֲכָמִים שֶׁאֵין תַּלְמִיד חָכָם אוֹכֵל עַד שֶׁיְּעַשֵּׂר אוֹ עַד שֶׁיּוֹדִיעוֹ אָדָם נֶאֱמָן שֶׁזֶּה מְעֻשָּׂר:","כָּל הַמַּשְׁפִּיעִין בְּמִדָּה גַּסָּה כְּגוֹן הַסִּיטוֹנוֹת וּמוֹכְרֵי תְּבוּאָה מֻתָּרִין לִמְכֹּר אֶת הַדְּמַאי וּלְשַׁלְּחוֹ. מִפְּנֵי שֶׁהֵן מוֹסִיפִין עַל הַמִּדָּה הִתְקִינוּ חֲכָמִים שֶׁיִּהְיֶה הַלּוֹקֵחַ אוֹ זֶה שֶׁנִּשְׁתַּלְּחוּ לוֹ הוּא הַמַּפְרִישׁ מַעֲשֵׂר דְּמַאי. אֲבָל הַמּוֹדְדִין בְּמִדָּה דַּקָּה הוֹאִיל וְהַמּוֹכֵר מִשְׂתַּכֵּר הוּא מַפְרִישׁ וְלֹא יִמְכֹּר וְלֹא יִשְׁלַח אֶלָּא מְתֻקָּן:","וְכַמָּה הִיא מִדָּה גַּסָּה. בְּיָבֵשׁ חֲצִי סְאָה וּבְלַח מִדָּה שֶׁמַּחְזֶקֶת שְׁוֵה דִּינָר מֵאוֹתוֹ דָּבָר הַלַּח:","סַלֵּי זֵיתִים וַעֲנָבִים וְקֻפּוֹת שֶׁל יָרָק אַף עַל פִּי שֶׁהוּא מוֹכְרָן אַכְסָרָה אָסוּר לְמָכְרָן דְּמַאי:","אָמַר אֶחָד מֵהֶן בּוֹא וּנְתַקֵּן הַפֵּרוֹת הָאֵלּוּ בֵּין שֶׁהָיָה מוֹכֵר בְּדַקָּה אוֹ בְּגַסָּה הַמּוֹכֵר מַפְרִישׁ תְּרוּמַת מַעֲשֵׂר וְהַלּוֹקֵחַ מַפְרִישׁ מַעֲשֵׂר שֵׁנִי וְדָבָר זֶה תְּנַאי בֵּית דִּין הוּא:","חָבֵר וְעַם הָאָרֶץ שֶׁיָּרְשׁוּ אֶת אֲבִיהֶן עַם הָאָרֶץ יָכוֹל הוּא לוֹמַר טֹל אַתָּה חִטִּים שֶׁבְּמָקוֹם פְּלוֹנִי וַאֲנִי חִטִּים שֶׁבְּמָקוֹם פְּלוֹנִי. אַתָּה יַיִן שֶׁבְּמָקוֹם פְּלוֹנִי וַאֲנִי יַיִן שֶׁבְּמָקוֹם פְּלוֹנִי. אֲבָל לֹא יֹאמַר טֹל אַתָּה חִטִּים וַאֲנִי שְׂעוֹרִים. טֹל אַתָּה הַלַּח וַאֲנִי הַיָּבֵשׁ. מִפְּנֵי שֶׁזֶּה מוֹכֵר דְּמַאי:","מִי שֶׁהָיָה נוֹשֵׂא יָרָק וְכָבֵד עָלָיו מַשָּׂאוֹ וְרָצָה לְהַשְׁלִיךְ מִמֶּנּוּ עַל הַדֶּרֶךְ כְּדֵי לְהָקֵל מִמַּשָּׂאוֹ. לֹא יַשְׁלִיךְ עַד שֶׁיְּעַשֵּׂר. כְּדֵי שֶׁלֹּא תְּהֵא תַּקָּלָה לְעַמֵּי הָאָרֶץ שֶׁאוֹכְלִין אוֹתוֹ בִּדְמַאי:","הַלּוֹקֵחַ יָרָק מִן הַשּׁוּק וּמָשַׁךְ אַף עַל פִּי שֶׁלֹּא שָׁקַל וְלֹא מָדַד וְלֹא נָתַן דָּמִים וְנִמְלַךְ לְהַחֲזִיר לְבַעַל הַחֲנוּת לֹא יַחֲזִיר עַד שֶׁיְּעַשֵּׂר:","הַמּוֹצֵא פֵּרוֹת בַּדֶּרֶךְ. אִם רֹב מַכְנִיסִין לְבָתֵּיהֶן פָּטוּר מִלְּעַשֵּׂר שֶׁעֲדַיִן לֹא נִקְבַּע לְמַעֲשֵׂר. וְאִם רֹב מַכְנִיסִין לִמְכֹּר בַּשּׁוּק הֲרֵי אֵלּוּ דְּמַאי. וּמֶחֱצָה לְמֶחֱצָה דְּמַאי:","נְטָלָן לְאָכְלָן וְנִמְלַךְ לְהַצְנִיעַ לֹא יַשְׁהֶא אוֹתָן עַד שֶׁיְּעַשֵּׂר כְּדֵי שֶׁלֹּא יִהְיֶה תַּקָּלָה לַאֲחֵרִים. וְאִם נְטָלָם מִתְּחִלָּה שֶׁלֹּא יֹאבְדוּ הֲרֵי זֶה מֻתָּר לַשְׁהוֹתָן אֶצְלוֹ עַד שֶׁיִּרְצֶה לְאָכְלָן אוֹ לְשָׁלְחָן אוֹ לְמָכְרָן וִיעַשֵּׂר אוֹתָן דְּמַאי:","קְנִיבַת יָרָק הַנִּמְצֵאת בַּגִּנָּה הֲרֵי זוֹ פְּטוּרָה מִן הַדְּמַאי. וְשֶׁל בַּעַל הַבַּיִת הַנִּמְצֵאת בַּבַּיִת חַיֶּבֶת. שֶׁעַל גַּבֵּי הָאַשְׁפָּה בְּכָל מָקוֹם מֻתֶּרֶת:","הַנּוֹתֵן לְפֻנְדָּקִית לְבַשֵּׁל לוֹ וְלֶאֱפוֹת לוֹ מְעַשֵּׂר אֶת שֶׁהוּא נוֹתֵן לָהּ כְּדֵי שֶׁלֹּא יִהְיֶה תַּקָּלָה לַאֲחֵרִים. וּמְעַשֵּׂר אֶת שֶׁהוּא נוֹטֵל מִמֶּנָּה מִפְּנֵי שֶׁהִיא חֲשׁוּדָה לְהַחֲלִיף שֶׁל זֶה [בָּזֶה]. אֲבָל הַנּוֹתֵן לַחֲמוֹתוֹ בֵּין שֶׁנָּשָׂא בִּתָּהּ בֵּין שֶׁאֵרְסָהּ אוֹ לִשְׁכֶנְתּוֹ פַּת לֶאֱפוֹת וְתַבְשִׁיל לְבַשֵּׁל אֵינוֹ חוֹשֵׁשׁ לֹא מִשּׁוּם מַעֲשֵׂר וְלֹא מִשּׁוּם שְׁבִיעִית מִפְּנֵי שֶׁאֵינָהּ חֲשׁוּדָה לְהַחֲלִיף. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁנָּתַן לָהּ שְׂאוֹר לְעִיסָה וְתַבְלִין לִקְדֵרָה. אֲבָל אִם לֹא נָתַן חוֹשֵׁשׁ מִשּׁוּם מַעַשְׂרוֹת וְחוֹשֵׁשׁ מִשּׁוּם שְׁבִיעִית. וּלְפִיכָךְ אִם הָיְתָה שְׁנַת שְׁמִטָּה אָסוּר שֶׁמָּא הַשְּׂאוֹר מִסְּפִיחֵי שְׁבִיעִית הוּא:","הַמּוֹלִיךְ חִטָּיו לְטוֹחֵן עַם הָאָרֶץ הֲרֵי הֵן בְּחֶזְקָתָן שֶׁאֵינוֹ חָשׁוּד לְהַחֲלִיף. הוֹלִיכָן לְטוֹחֵן עַכּוּ\"ם הֲרֵי הֵם דְּמַאי שֶׁמָּא הֶחֱלִיפָן בְּחִטִּים שֶׁל עַם הָאָרֶץ. וְכֵן הַמַּפְקִיד אֵצֶל עַם הָאָרֶץ הֲרֵי הֵן בְּחֶזְקָתָן שֶׁאֵינוֹ חָשׁוּד לְהַחֲלִיף הַפִּקָּדוֹן:","עַם הָאָרֶץ שֶׁהָיָה מִשְׁתַּמֵּשׁ בַּחֲנוּתוֹ שֶׁל חָבֵר אַף עַל פִּי שֶׁהֶחָבֵר יוֹצֵא וְנִכְנָס הֲרֵי זֶה מֻתָּר וְאֵינוֹ חוֹשֵׁשׁ שֶׁמָּא הֶחֱלִיף:","הַמַּפְקִיד פֵּרוֹתָיו אֵצֶל הָעַכּוּ\"ם הֲרֵי הֵן כְּפֵרוֹתָיו שֶׁל עַכּוּ\"ם שֶׁחֶזְקָתוֹ לְהַחֲלִיף הַפִּקָּדוֹן. וְהֵיאַךְ דִּינָם. אִם הָיוּ פֵּרוֹת שֶׁעֲדַיִן לֹא נִגְמְרָה מְלַאכְתָּן וְנִגְמְרוּ בְּיַד יִשְׂרָאֵל אַחַר שֶׁלָּקַח הַפִּקָּדוֹן מַפְרִישׁ מַעַשְׂרוֹתָיו כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם הָיוּ פֵּרוֹת שֶׁהִפְקִיד טְבָלִים וְנִגְמְרָה מְלַאכְתָּן חַיָּב לְהַפְרִישׁ שֶׁמָּא לֹא הֶחֱלִיף הָעַכּוּ\"ם. וּלְפִיכָךְ יֵרָאֶה לִי שֶׁהַמַּעַשְׂרוֹת שֶׁיַּפְרִישׁ סָפֵק. אֲבָל אִם הִפְקִיד חֻלִּין מְתֻקָּנִין אֵינוֹ צָרִיךְ לְהַפְרִישׁ כְּלוּם שֶׁאֲפִלּוּ הֶחֱלִיף הָעַכּוּ\"ם פְּטוּרִין כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת תְּרוּמוֹת (דברים יח ד) \"דְּגָנְךָ\" וְלֹא דְּגַן עַכּוּ\"ם:"],"Mishneh Torah, Torah Study 1":["נָשִׁים וַעֲבָדִים וּקְטַנִּים פְּטוּרִים מִתַּלְמוּד תּוֹרָה. אֲבָל קָטָן אָבִיו חַיָּב לְלַמְּדוֹ תּוֹרָה שֶׁנֶּאֱמַר (דברים יא יט) \"וְלִמַּדְתֶּם אֹתָם אֶת בְּנֵיכֶם לְדַבֵּר בָּם\". וְאֵין הָאִשָּׁה חַיֶּבֶת לְלַמֵּד אֶת בְּנָהּ. שֶׁכָּל הַחַיָּב לִלְמֹד חַיָּב לְלַמֵּד:","כְּשֵׁם שֶׁחַיָּב אָדָם לְלַמֵּד אֶת בְּנוֹ כָּךְ הוּא חַיָּב לְלַמֵּד אֶת בֶּן בְּנוֹ שֶׁנֶּאֱמַר (דברים ד ט) \"וְהוֹדַעְתָּם לְבָנֶיךָ וְלִבְנֵי בָנֶיךָ\". וְלֹא בְּנוֹ וּבֶן בְּנוֹ בִּלְבַד אֶלָּא מִצְוָה עַל כָּל חָכָם וְחָכָם מִיִּשְׂרָאֵל לְלַמֵּד אֶת כָּל הַתַּלְמִידִים אַף עַל פִּי שֶׁאֵינָן בָּנָיו. שֶׁנֶּאֱמַר (דברים ו ז) \"וְשִׁנַּנְתָּם לְבָנֶיךָ\" מִפִּי הַשְּׁמוּעָה לָמְדוּ בָּנֶיךָ אֵלּוּ תַּלְמִידֶיךָ שֶׁהַתַּלְמִידִים קְרוּיִין בָּנִים שֶׁנֶּאֱמַר (מלכים ב ב ג) \"וַיֵּצְאוּ בְנֵי הַנְּבִיאִים\". אִם כֵּן לָמָּה נִצְטַוָּה עַל בְּנוֹ וְעַל בֶּן בְּנוֹ. לְהַקְדִּים בְּנוֹ לְבֶן בְּנוֹ וּבֶן בְּנוֹ לְבֶן חֲבֵרוֹ:","וְחַיָּב לִשְׂכֹּר מְלַמֵּד לִבְנוֹ לְלַמְּדוֹ. וְאֵינוֹ חַיָּב לְלַמֵּד בֶּן חֲבֵרוֹ אֶלָּא בְּחִנָּם. מִי שֶׁלֹּא לִמְּדוֹ אָבִיו חַיָּב לְלַמֵּד אֶת עַצְמוֹ כְּשֶׁיַּכִּיר שֶׁנֶּאֱמַר (דברים ה א) \"וּלְמַדְתֶּם אֹתָם וּשְׁמַרְתֶּם לַעֲשֹׂתָם\". וְכֵן אַתָּה מוֹצֵא בְּכָל מָקוֹם שֶׁהַתַּלְמוּד קוֹדֵם לַמַּעֲשֶׂה מִפְּנֵי שֶׁהַתַּלְמוּד מֵבִיא לִידֵי מַעֲשֶׂה וְאֵין הַמַּעֲשֶׂה מֵבִיא לִידֵי תַּלְמוּד:","הָיָה הוּא רוֹצֶה לִלְמֹד תּוֹרָה וְיֵשׁ לוֹ בֵּן לִלְמֹד תּוֹרָה הוּא קוֹדֵם לִבְנוֹ. וְאִם הָיָה בְּנוֹ נָבוֹן וּמַשְׂכִּיל לְהָבִין מַה שֶּׁיִּלְמֹד יוֹתֵר מִמֶּנּוּ בְּנוֹ קוֹדֵם. וְאַף עַל פִּי שֶׁבְּנוֹ קוֹדֵם לֹא יִבָּטֵל הוּא. שֶׁכְּשֵׁם שֶׁמִּצְוָה עָלָיו לְלַמֵּד אֶת בְּנוֹ כָּךְ הוּא מְצֻוֶּה לְלַמֵּד עַצְמוֹ:","לְעוֹלָם יִלְמֹד אָדָם תּוֹרָה וְאַחַר כָּךְ יִשָּׂא אִשָּׁה שֶׁאִם נָשָׂא אִשָּׁה תְּחִלָּה אֵין דַּעְתּוֹ פְּנוּיָה לִלְמֹד. וְאִם הָיָה יִצְרוֹ מִתְגַּבֵּר עָלָיו עַד שֶׁנִּמְצָא שֶׁאֵין לִבּוֹ פָּנוּי יִשָּׂא וְאַחַר כָּךְ יִלְמֹד תּוֹרָה:","מֵאֵימָתַי אָבִיו חַיָּב לְלַמְּדוֹ תּוֹרָה. מִשֶּׁיַּתְחִיל לְדַבֵּר מְלַמְּדוֹ (דברים לג ד) \"תּוֹרָה צִוָּה לָנוּ משֶׁה\" וּ(דברים ו ד) \"שְׁמַע יִשְׂרָאֵל\", וְאַחַר כָּךְ מְלַמְּדוֹ מְעַט מְעַט פְּסוּקִים פְּסוּקִים עַד שֶׁיִּהְיֶה בֶּן שֵׁשׁ אוֹ בֶּן שֶׁבַע הַכּל לְפִי בֻּרְיוֹ. וּמוֹלִיכוֹ אֵצֶל מְלַמֵּד הַתִּינוֹקוֹת:","הָיָה מִנְהַג הַמְּדִינָה לִקַּח מְלַמֵּד הַתִּינוֹקוֹת שָׂכָר נוֹתֵן לוֹ שְׂכָרוֹ. וְחַיָּב לְלַמְּדוֹ בְּשָׂכָר עַד שֶׁיִּקְרָא תּוֹרָה שֶׁבִּכְתָב כֻּלָּהּ. מָקוֹם שֶׁנָּהֲגוּ לְלַמֵּד תּוֹרָה שֶׁבִּכְתָב בְּשָׂכָר מֻתָּר לְלַמֵּד בְּשָׂכָר. אֲבָל תּוֹרָה שֶׁבְּעַל פֶּה אָסוּר לְלַמְּדָהּ בְּשָׂכָר שֶׁנֶּאֱמַר (דברים ד ה) \"רְאֵה לִמַּדְתִּי אֶתְכֶם חֻקִּים וּמִשְׁפָּטִים כַּאֲשֶׁר צִוַּנִי ה'\" וְגוֹ' מָה אֲנִי בְּחִנָּם לָמַדְתִּי אַף אַתֶּם לְמַדְתֶּם בְּחִנָּם מִמֶּנִּי וְכֵן כְּשֶׁתְּלַמְּדוּ לְדוֹרוֹת לַמְּדוּ בְּחִנָּם כְּמוֹ שֶׁלְּמַדְתֶּם מִמֶּנִּי. לֹא מָצָא מִי שֶׁיְּלַמְּדוֹ בְּחִנָּם יְלַמְּדוֹ בְּשָׂכָר שֶׁנֶּאֱמַר אֱמֶת קְנֵה. יָכוֹל יְלַמֵּד לַאֲחֵרִים בְּשָׂכָר. תַּלְמוּד לוֹמַר (משלי כג כג) \"וְאַל תִּמְכֹּר\". הָא לָמַדְתָּ שֶׁאָסוּר לוֹ לְלַמֵּד בְּשָׂכָר אַף עַל פִּי שֶׁלִּמְּדוֹ רַבּוֹ בְּשָׂכָר:","כָּל אִישׁ מִיִּשְׂרָאֵל חַיָּב בְּתַלְמוּד תּוֹרָה בֵּין עָנִי בֵּין עָשִׁיר בֵּין שָׁלֵם בְּגוּפוֹ בֵּין בַּעַל יִסּוּרִין בֵּין בָּחוּר בֵּין שֶׁהָיָה זָקֵן גָּדוֹל שֶׁתָּשַׁשׁ כֹּחוֹ אֲפִלּוּ הָיָה עָנִי הַמִּתְפַּרְנֵס מִן הַצְּדָקָה וּמְחַזֵּר עַל הַפְּתָחִים וַאֲפִלּוּ בַּעַל אִשָּׁה וּבָנִים חַיָּב לִקְבֹּעַ לוֹ זְמַן לְתַלְמוּד תּוֹרָה בַּיּוֹם וּבַלַּיְלָה שֶׁנֶּאֱמַר (יהושע א ח) \"וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה\":","גְּדוֹלֵי חַכְמֵי יִשְׂרָאֵל הָיוּ מֵהֶן חוֹטְבֵי עֵצִים וּמֵהֶן שׁוֹאֲבֵי מַיִם וּמֵהֶן סוּמִים וְאַף עַל פִּי כֵן הָיוּ עוֹסְקִין בְּתַלְמוּד תּוֹרָה בַּיּוֹם וּבַלַּיְלָה וְהֵם מִכְּלַל מַעְתִּיקֵי הַשְּׁמוּעָה אִישׁ מִפִּי אִישׁ מִפִּי משֶׁה רַבֵּנוּ:","עַד אֵימָתַי חַיָּב לִלְמֹד תּוֹרָה עַד יוֹם מוֹתוֹ שֶׁנֶּאֱמַר (דברים ד ט) \"וּפֶן יָסוּרוּ מִלְּבָבְךָ כּל יְמֵי חַיֶּיךָ\". וְכָל זְמַן שֶׁלֹּא יַעֲסֹק בְּלִמּוּד הוּא שׁוֹכֵחַ:","וְחַיָּב לְשַׁלֵּשׁ אֶת זְמַן לְמִידָתוֹ. שְׁלִישׁ בַּתּוֹרָה שֶׁבִּכְתָב. וּשְׁלִישׁ בַּתּוֹרָה שֶׁבְּעַל פֶּה. וּשְׁלִישׁ יָבִין וְיַשְׂכִּיל אַחֲרִית דָּבָר מֵרֵאשִׁיתוֹ וְיוֹצִיא דָּבָר מִדָּבָר וִידַמֶּה דָּבָר לְדָבָר וְיָבִין בַּמִּדּוֹת שֶׁהַתּוֹרָה נִדְרֶשֶׁת בָּהֶן עַד שֶׁיֵּדַע הֵיאַךְ הוּא עִקַּר הַמִּדּוֹת וְהֵיאַךְ יוֹצִיא הָאָסוּר וְהַמֻּתָּר וְכַיּוֹצֵא בָּהֶן מִדְּבָרִים שֶׁלָּמַד מִפִּי הַשְּׁמוּעָה. וְעִנְיָן זֶה הוּא הַנִּקְרָא גְּמָרָא:","כֵּיצַד. הָיָה בַּעַל אֻמָּנוּת וְהָיָה עוֹסֵק בִּמְלַאכְתּוֹ שָׁלֹשׁ שָׁעוֹת בַּיּוֹם וּבַתּוֹרָה תֵּשַׁע. אוֹתָן הַתֵּשַׁע קוֹרֵא בְּשָׁלֹשׁ מֵהֶן בַּתּוֹרָה שֶׁבִּכְתָב וּבְשָׁלֹשׁ בַּתּוֹרָה שֶׁבְּעַל פֶּה וּבְשָׁלֹשׁ אֲחֵרוֹת מִתְבּוֹנֵן בְּדַעְתּוֹ לְהָבִין דָּבָר מִדָּבָר. וְדִבְרֵי קַבָּלָה בִּכְלַל תּוֹרָה שֶׁבִּכְתָב הֵן וּפֵרוּשָׁן בִּכְלַל תּוֹרָה שֶׁבְּעַל פֶּה. וְהָעִנְיָנִים הַנִּקְרָאִים פַּרְדֵּס בִּכְלַל הַגְּמָרָא הֵן. בַּמֶּה דְּבָרִים אֲמוּרִים בִּתְחִלַּת תַּלְמוּדוֹ שֶׁל אָדָם אֲבָל כְּשֶׁיַּגְדִּיל בְּחָכְמָה וְלֹא יְהֵא צָרִיךְ לֹא לִלְמֹד תּוֹרָה שֶׁבִּכְתָב וְלֹא לַעֲסֹק תָּמִיד בַּתּוֹרָה שֶׁבְּעַל פֶּה יִקְרָא בְּעִתִּים מְזֻמָּנִים תּוֹרָה שֶׁבִּכְתָב וְדִבְרֵי הַשְּׁמוּעָה כְּדֵי שֶׁלֹּא יִשְׁכַּח דָּבָר מִדִּבְרֵי דִּינֵי תּוֹרָה וְיִפְנֶה כָּל יָמָיו לַגְּמָרָא בִּלְבַד לְפִי רֹחַב שֶׁיֵּשׁ בְּלִבּוֹ וְיִשּׁוּב דַּעְתּוֹ:","אִשָּׁה שֶׁלָּמְדָה תּוֹרָה יֵשׁ לָהּ שָׂכָר אֲבָל אֵינוֹ כִּשְׂכַר הָאִישׁ. מִפְּנֵי שֶׁלֹּא נִצְטַוֵּית. וְכָל הָעוֹשֶׂה דָּבָר שֶׁאֵינוֹ מְצֻוֶּה עָלָיו לַעֲשׂוֹתוֹ אֵין שְׂכָרוֹ כִּשְׂכַר הַמְצֻוֶּה שֶׁעָשָׂה אֶלָּא פָּחוֹת מִמֶּנּוּ. וְאַף עַל פִּי שֶׁיֵּשׁ לָהּ שָׂכָר צִוּוּ חֲכָמִים שֶׁלֹּא יְלַמֵּד אָדָם אֶת בִּתּוֹ תּוֹרָה. מִפְּנֵי שֶׁרֹב הַנָּשִׁים אֵין דַּעְתָּם מְכֻוֶּנֶת לְהִתְלַמֵּד אֶלָּא הֵן מוֹצִיאוֹת דִּבְרֵי תּוֹרָה לְדִבְרֵי הֲבַאי לְפִי עֲנִיּוּת דַּעְתָּן. אָמְרוּ חֲכָמִים כָּל הַמְלַמֵּד אֶת בִּתּוֹ תּוֹרָה כְּאִלּוּ לִמְּדָהּ תִּפְלוּת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּתוֹרָה שֶׁבְּעַל פֶּה אֲבָל תּוֹרָה שֶׁבִּכְתָב לֹא יְלַמֵּד אוֹתָהּ לְכַתְּחִלָּה וְאִם לִמְּדָהּ אֵינוֹ כִּמְלַמְּדָהּ תִּפְלוּת:"],"Mishneh Torah, Transmission of the Oral Law 14":["וְהוּא קִבַּץ כָּל הַשְּׁמוּעוֹת וְכָל הַדִּינִין וְכָל הַבֵּאוּרִין וְהַפֵּרוּשִׁין שֶׁשָּׁמְעוּ מִמֹּשֶׁה רַבֵּנוּ, וְשֶׁלִּמְּדוּ בֵּית דִּין שֶׁלְּכָל דּוֹר וָדוֹר, בְּכָל הַתּוֹרָה כֻּלָּהּ; וְחִבַּר מֵהַכֹּל סֵפֶר הַמִּשְׁנָה. וְשִׁנְּנוֹ בָּרַבִּים, וְנִגְלָה לְכָל יִשְׂרָאֵל; וּכְתָבוּהוּ כֻּלָּם, וְרִבְּצוּ בְּכָל מָקוֹם, כְּדֵי שֶׁלֹּא תִשְׁתַּכַּח תּוֹרָה שֶׁבְּעַל פֶּה מִיִּשְׂרָאֵל."],"Mishneh Torah, Transmission of the Oral Law 25":["גַּם יִתְבָּאַר מֵהֶם דְּבָרִים שֶׁגָּזְרוּ חֲכָמִים וּנְבִיאִים שֶׁבְּכָל דּוֹר וָדוֹר, לַעֲשׂוֹת סְיָג לַתּוֹרָה, כְּמוֹ שֶׁשָּׁמְעוּ מִמֹּשֶׁה בְּפֵרוּשׁ \"וּשְׁמַרְתֶּם אֶת־מִשְׁמַרְתִּי\" (ויקרא יח, ל), שֶׁאָמַר עֲשׂוּ מִשְׁמֶרֶת לְמִשְׁמַרְתִּי."],"Mishneh Torah, Transmission of the Oral Law 36":["כָּל הַחֲכָמִים שֶׁעָמְדוּ אַחַר חִבּוּר הַתַּלְמוּד וּבָנוּ בּוֹ, וְיָצָא לָהֶם שֵׁם בְּחָכְמָתָם – הֶם הַנִּקְרָאִים גְּאוֹנִים. וְכָל אֵלּוּ הַגְּאוֹנִים שֶׁעָמְדוּ בְּאֶרֶץ יִשְׂרָאֵל וּבְאֶרֶץ שִׁנְעָר וּבִסְפָרַד וּבְצָרְפַת לִמְּדוּ דֶּרֶךְ הַתַּלְמוּד וְהוֹצִיאוּ לָאוֹר תַּעֲלוּמוֹתָיו וּבֵאֲרוּ עִנְיָנָיו, לְפִי שֶׁדֶּרֶךְ עֲמוּקָה דַּרְכּוֹ עַד לִמְאוֹד. וְעוֹד שְׁהוּא בִּלְשׁוֹן אֲרַמִּי מְעֹרָב עִם לְשׁוֹנוֹת אֲחֵרוֹת, לְפִי שֶׁאוֹתָהּ הַלָּשׁוֹן הָיְתָה בְּרוּרָה לַכֹּל בְּשִׁנְעָר בָּעֵת שֶׁחֻבַּר הַתַּלְמוּד; אֲבָל בִּשְׁאָר הַמְּקוֹמוֹת וְכֵן בְּשִׁנְעָר בִּימֵי הַגְּאוֹנִים, אֵין אָדָם מַכִּיר אוֹתָהּ לָשׁוֹן עַד שֶׁמְּלַמְּדִים אוֹתוֹ."],"Mishneh Torah, Transmission of the Oral Law 6":["אֵלִיָּהוּ קִבַּל מֵאֲחִיָּה הַשִּׁילוֹנִי וּבֵית דִּינוֹ, וֶאֱלִישָׁע קִבַּל מֵאֵלִיָּהוּ וּבֵית דִּינוֹ, וִיהוֹיָדָע הַכּוֹהֵן קִבַּל מֵאֱלִישָׁע וּבֵית דִּינוֹ, וּזְכַרְיָהוּ קִבַּל מִיְּהוֹיָדָע וּבֵית דִּינוֹ, וְהוֹשֵׁעַ קִבַּל מִזְּכַרְיָה וּבֵית דִּינוֹ, וְעָמוֹס קִבַּל מֵהוֹשֵׁעַ וּבֵית דִּינוֹ, וִישַׁעְיָהוּ קִבַּל מֵעָמוֹס וּבֵית דִּינוֹ, וּמִיכָה קִבַּל מִיְּשַׁעְיָה וּבֵית דִּינוֹ, וְיוֹאֵל קִבַּל מִמִּיכָה וּבֵית דִּינוֹ, וְנַחוּם קִבַּל מִיּוֹאֵל וּבֵית דִּינוֹ, וַחֲבַקּוּק קִבַּל מִנַּחוּם וּבֵית דִּינוֹ, וּצְפַנְיָה קִבַּל מֵחֲבַקּוּק וּבֵית דִּינוֹ, וְיִרְמְיָה קִבַּל מִצְּפַנְיָה וּבֵית דִּינוֹ, וּבָרוּךְ בֶּן נֵרִיָּה קִבַּל מִיִּרְמְיָה וּבֵית דִּינוֹ, וְעֶזְרָא וּבֵית דִּינוֹ קִבְּלוּ מִבָּרוּךְ וּבֵית דִּינוֹ."],"Mishneh Torah, Vessels 1":["שִׁבְעָה מִינֵי כֵּלִים הֵן שֶׁמְּקַבְּלִין טֻמְאָה מִן הַתּוֹרָה וְאֵלּוּ הֵן. הַבְּגָדִים. וְהַשַּׂקִּין. וּכְלֵי עוֹר. וּכְלֵי עֶצֶם. וּכְלֵי מַתָּכוֹת. וּכְלֵי עֵץ. וּכְלֵי חֶרֶשׂ. הֲרֵי הוּא אוֹמֵר (ויקרא יא לב) \"מִכָּל כְּלִי עֵץ אוֹ בֶגֶד אוֹ עוֹר אוֹ שָׂק\". וּבִכְלֵי מַתָּכוֹת נֶאֱמַר (במדבר לא כב) \"אַךְ אֶת הַזָּהָב וְאֶת הַכָּסֶף\". וּבִכְלֵי חֶרֶשׂ נֶאֱמַר \"וּכְלִי חֶרֶשׂ אֲשֶׁר יִפּל מֵהֶם אֶל תּוֹכוֹ כּל אֲשֶׁר בְּתוֹכוֹ יִטְמָא וְאֹתוֹ תִשְׁבֹּרוּ\":","מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזֶּה שֶׁנֶּאֱמַר בַּתּוֹרָה (במדבר לא כ) \"וְכָל מַעֲשֵׂה עִזִּים\" לְרַבּוֹת כֵּלִים הָעֲשׂוּיִין מִן הַקַּרְנַיִם וּמִן הַטְּלָפַיִם וּמִן הָעֲצָמוֹת שֶׁל עִזִּים וְהוּא הַדִּין לִשְׁאָר מִינֵי בְּהֵמָה וְחַיָּה. אֲבָל כֵּלִים הָעֲשׂוּיִין מֵעַצְמוֹת הָעוֹף אֵינָן מְקַבְּלִין טֻמְאָה חוּץ מִכֵּלִים הָעֲשׂוּיִין מִכְּנַף הָעָזְנִיָּה בִּלְבַד וּבֵיצַת הַנַּעֲמִית הַמְצֻפָּה הוֹאִיל וְהֵן דּוֹמִין לְעֶצֶם מְקַבְּלִין טֻמְאָה כִּכְלֵי עֶצֶם. וְקָרוֹב בְּעֵינַי שֶׁטֻּמְאָתָן מִדִּבְרֵי סוֹפְרִים:","כֵּלִים הָעֲשׂוּיִין מֵעַצְמוֹת חַיָּה שֶׁבַּיָּם וּמֵעוֹרָהּ טְהוֹרִים. כָּל שֶׁבַּיָּם טָהוֹר וְאֵינוֹ מְקַבֵּל טֻמְאָה מִן הַטֻּמְאוֹת וְלֹא טֻמְאַת מִדְרָס. אַף הָאוֹרֵג בֶּגֶד מִצֶּמֶר הַגָּדֵל בַּיָּם אֵינוֹ מְקַבֵּל טֻמְאָה שֶׁנֶּאֱמַר (ויקרא יא לב) \"אוֹ בֶגֶד אוֹ עוֹר\" מִפִּי הַשְּׁמוּעָה לָמְדוּ מַה בֶּגֶד מִן הַגָּדֵל בָּאָרֶץ אַף עוֹר מִן הַגָּדֵל בָּאָרֶץ. חִבֵּר מִן הַגָּדֵל בַּיָּם עִם הַגָּדֵל בָּאָרֶץ אֲפִלּוּ חוּט אוֹ מְשִׁיחָה אִם חִבְּרוֹ חִבּוּר עַד שֶׁמֵּשִׂים אֶת שְׁנֵיהֶן כְּאִלּוּ הֵן אֶחָד לְטֻמְאָה שֶׁאִם נִטְמָא זֶה יִטְמָא זֶה הַכּל מְקַבֵּל טֻמְאָה:","יֵרָאֶה לִי שֶׁהַכֵּלִים הָעֲשׂוּיִים מֵעוֹר הָעוֹף אֵין מְקַבְּלִין טֻמְאָה כְּמוֹ עַצְמוֹתָיו. וְאִם תֹּאמַר וַהֲרֵי הוּא כָּשֵׁר לִכְתֹּב עָלָיו תְּפִלִּין כְּעוֹר בְּהֵמָה וְחַיָּה. הִנֵּה עוֹר הַדָּג אֵינוֹ מְקַבֵּל טֻמְאָה וְלוּלֵא זֻהֲמָתוֹ שֶׁאֵינָהּ פּוֹסֶקֶת הָיָה כָּשֵׁר לַתְּפִלִּין הִנֵּה לָמַדְתָּ שֶׁאַף דָּבָר שֶׁאֵינוֹ מְקַבֵּל טֻמְאָה כָּשֵׁר לִתְפִלִּין אִם אֵין לוֹ זֻהֲמָא:","כְּלֵי זְכוּכִית אֵינָן מְקַבְּלִין טֻמְאָה מִדִּבְרֵי תּוֹרָה וַחֲכָמִים גָּזְרוּ עֲלֵיהֶן שֶׁיְּקַבְּלוּ טֻמְאָה הוֹאִיל וּתְחִלַּת בְּרִיָּתָן מִן הַחוֹל כִּכְלֵי חֶרֶס הֲרֵי הֵן כִּכְלֵי חֶרֶס. וּמִפְּנֵי שֶׁתּוֹכָן נִרְאֶה כְּבָרָן לֹא גָּזְרוּ עֲלֵיהֶן שֶׁיִּטַּמְּאוּ מֵאֲוִירָן אֶלָּא עַד שֶׁתִּגַּע הַטֻּמְאָה בָּהֶן בֵּין מִתּוֹכָן בֵּין מִגַּבָּן כִּכְלֵי מַתָּכוֹת. וְלֹא גָּזְרוּ טֻמְאָה עַל פְּשׁוּטֵיהֶן אֶלָּא עַל מְקַבְּלֵיהֶן. וְאֵין לָהֶם טָהֳרָה בְּמִקְוֶה. וְאֵין שׂוֹרְפִין עֲלֵיהֶן תְּרוּמָה וְקָדָשִׁים שֶׁלֹּא גָּזְרוּ עֲלֵיהֶן אֶלָּא לִתְלוֹת:","כְּלֵי גְּלָלִים וּכְלֵי אֲבָנִים וּכְלֵי אֲדָמָה לְעוֹלָם טְהוֹרִין. וְאֵין מְקַבְּלִין טֻמְאָה מִן הַטֻּמְאוֹת וְלֹא טֻמְאַת מִדְרָס לֹא מִן הַתּוֹרָה וְלֹא מִדִּבְרֵי סוֹפְרִים בֵּין פְּשׁוּטֵיהֶן בֵּין מְקַבְּלֵיהֶן:","פִּיל שֶׁבָּלַע הוּצִין וֶהֱקִיאָן דֶּרֶךְ הָרְעִי הָעוֹשֶׂה מֵהֶן כֵּלִים הֲרֵי הֵן סָפֵק אִם הֵם כִּכְלֵי גְּלָלִים אוֹ כְּלֵי עֵץ כְּשֶׁהָיוּ. אֲבָל כְּפִיפָה שֶׁנִּטְמֵאת וּבְלָעָהּ פִּיל וֶהֱקִיאָהּ דֶּרֶךְ בֵּית הָרְעִי הֲרֵי הִיא בְּטֻמְאָתָהּ:","פְּשׁוּטֵי כְּלֵי חֶרֶס כְּגוֹן מְנוֹרָה וְכִסֵּא וְשֻׁלְחָן שֶׁל חֶרֶס וְכַיּוֹצֵא בָּהֶן אֵין מְקַבְּלִין טֻמְאָה מִן הַטֻּמְאוֹת וְלֹא טֻמְאַת מִדְרָס לֹא מִן הַתּוֹרָה וְלֹא מִדִּבְרֵי סוֹפְרִים שֶׁנֶּאֱמַר (ויקרא יא לג) \"אֲשֶׁר יִפּל מֵהֶם אֶל תּוֹכוֹ\" (ויקרא יא לג) \"יִטְמָא\" כָּל שֶׁיֵּשׁ לוֹ תּוֹךְ בִּכְלִי חֶרֶס מְקַבֵּל טֻמְאָה וְשֶׁאֵין לוֹ תּוֹךְ טָהוֹר:","כְּלֵי מַתָּכוֹת אֶחָד פְּשׁוּטֵיהֶן כְּגוֹן הַסַּכִּינִים וְהַמִּסְפָּרַיִם אוֹ מְקַבְּלֵיהֶן כְּגוֹן הַיּוֹרוֹת וְהַקּוּמְקוּמוֹסִין הַכּל מְקַבְּלִין טֻמְאָה שֶׁנֶּאֱמַר (במדבר לא כג) \"כָּל דָּבָר אֲשֶׁר יָבֹא בָאֵשׁ\" בֵּין מְקַבֵּל בֵּין פָּשׁוּט. אֲפִלּוּ תֵּבָה אוֹ מִגְדָּל וְכַיּוֹצֵא בָּהֶן שֶׁל מַתֶּכֶת שֶׁהֵן מְקַבְּלִין אַרְבָּעִים סְאָה בְּלַח אוֹ יֶתֶר מְקַבְּלִין טֻמְאָה שֶׁנֶּאֱמַר כָּל דָּבָר אֲשֶׁר יָבֹא בָאֵשׁ:","כְּלֵי עֵץ וּכְלֵי עוֹר וּכְלֵי עֶצֶם מְקַבְּלֵיהֶן כְּגוֹן הָעֲרֵבָה וְהַחֵמֶת וְכַיּוֹצֵא בָּהֶן מְקַבְּלִין טֻמְאָה מִדִּבְרֵי תּוֹרָה. אֲבָל פְּשׁוּטֵיהֶן כְּגוֹן הַלּוּחוֹת וְהַכִּסֵּא וְהָעוֹר שֶׁאוֹכְלִין עָלָיו וְכַיּוֹצֵא בָּהֶן אֵינָן מְקַבְּלִין טֻמְאָה אֶלָּא מִדִּבְרֵי סוֹפְרִים שֶׁנֶּאֱמַר (ויקרא יא לב) \"מִכָּל כְּלִי עֵץ\" מִפִּי הַשְּׁמוּעָה לָמְדוּ מָה שַׂק שֶׁיֵּשׁ לוֹ בֵּית קִבּוּל אַף כָּל שֶׁיֵּשׁ לוֹ בֵּית קִבּוּל. וּכְלֵי עֶצֶם כִּכְלֵי עֵץ לְכָל דָּבָר. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁטֻּמְאַת פְּשׁוּטֵיהֶן מִדִּבְרֵי סוֹפְרִים בִּשְׁאָר טֻמְאוֹת חוּץ מִטֻּמְאַת מִדְרָס. אֲבָל בְּמִדְרַס הַזָּב וַחֲבֵרָיו מִתְטַמְּאִין מִן הַתּוֹרָה שֶׁנֶּאֱמַר (ויקרא טו ד) \"כָּל הַמִּשְׁכָּב אֲשֶׁר יִשְׁכַּב\" כָּל הֶעָשׂוּי לְמִשְׁכָּב אוֹ לְמֶרְכָּב כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן כְּלִי זְכוּכִית הֶעָשׂוּי לְמִשְׁכָּב מִתְטַמֵּא בְּמִדְרָס מִדִּבְרֵיהֶן:","כָּל שֶׁהוּא אָרוּג בֵּין מִצֶּמֶר וּפִשְׁתִּים בֵּין מִקַּנְבּוֹס אוֹ מִמֶּשִׁי אוֹ מִשְּׁאָר דְּבָרִים הַגְּדֵלִים בַּיַּבָּשָׁה הוּא הַנִּקְרָא בֶּגֶד לְעִנְיַן טֻמְאָה. וְהַלְּבָדִים כִּבְגָדִים לְכָל דָּבָר:","הַשַּׂק הוּא חוּטֵי שֵׂעָר הַגְּדֻלִין כְּשַׁלְשֶׁלֶת אוֹ הָאֲרוּגִין כִּבְגָדִים אֶחָד הֶעָשׂוּי מִן הָעִזִּים אוֹ מִצֶּמֶר גְּמַלִּים אוֹ מִזְּנַב הַסּוּס וְהַפָּרָה וְכַיּוֹצֵא בָּהֶן וְאֶחָד הָאָרִיג מֵהֶן כְּמוֹ הַמַּרְצוּפִין אוֹ הַגָּדֻל כְּמוֹ חֶבֶק שֶׁל חֲמוֹר וְכַיּוֹצֵא בּוֹ. אֲבָל הַחֲבָלִים וְהַמְּשִׁיחוֹת הַשְּׁזוּרִין בֵּין מִן הַשֵּׂעָר בֵּין מִצֶּמֶר וּפִשְׁתִּים אֵינָן מְקַבְּלִין טֻמְאָה בִּפְנֵי עַצְמָן:","כָּל הַכֵּלִים הָעֲשׂוּיִין מִן הַגֹּמֶא וּמִן הָעֲרָבָה וּמִן הַקָּנִים וּמִכַּפּוֹת תְּמָרִים וּמִן הֶעָלִים וְהַשָּׂרִיגִין וּקְלִפֵּי אִילָנוֹת וּמִן הַחֶלֶף כְּגוֹן הַכְּפִיפוֹת וְהַטְּרַסְקְלִין וְהַמַּחֲלָצוֹת וְהַמַּפָּצוֹת הַכּל בִּכְלַל כְּלֵי הָעֵץ שֶׁהַכּל גָּדֵל מִן הָאָרֶץ כְּעֵץ. אֶחָד כְּלִי חֶרֶס וְאֶחָד כְּלִי נֶתֶר לְכָל דָּבָר. כָּל כְּלִי הֶעָשׂוּי מֵהֶעָפָר מִן הָעֲפָרוֹת וְאַחַר כָּךְ שׂוֹרְפִין אוֹתָן בְּכִבְשָׁן הֲרֵי זֶה כְּלִי חֶרֶס. וְהַתַּנּוּר וְהַכִּירַיִם וְהַכֻּפָּח וְכַיּוֹצֵא בָּהֶן מִשְּׁאָר הַבִּנְיָנוֹת שֶׁאוֹפִין בָּהֶן אוֹ מְבַשְּׁלִין בָּהֶן הַכּל מְקַבְּלִין טֻמְאָה דִּין תּוֹרָה וְטֻמְאָתָן וְטֻמְאַת כְּלִי חֶרֶס שָׁוָה:"],"Mishneh Torah, Vessels 20":["כְּבָר בֵּאַרְנוּ שֶׁכָּל יַד הַכֵּלִים שֶׁהַכְּלִי צָרִיךְ לָהּ בִּשְׁעַת תַּשְׁמִישׁוֹ הֲרֵי הִיא חֲשׁוּבָה כְּגוּף הַכְּלִי לְהִתְטַמֵּא וּלְטַמֵּא. לְפִיכָךְ הַטּוֹפֵל כְּלִי חֶרֶס הַבָּרִיא אִם נִטְמָא הַכְּלִי הֲרֵי אוֹכְלִין וּמַשְׁקִין הַנּוֹגְעִין בַּטְּפֵלָה טְהוֹרִין שֶׁאֵין הַכְּלִי צָרִיךְ לִטְפֵלָה זוֹ. אֲבָל הַטּוֹפֵל אֶת כְּלִי חֶרֶס הָרָעוּעַ הֲרֵי הַטְּפֵלָה חֲשׁוּבָה כְּגוּף הַכְּלִי. וְכֵן הַמְהַדֵּק אֶת הַקֵּרוּיָה שֶׁל חֶרֶס הַדּוֹלִין בָּהּ הַמַּיִם אִם חִפָּה אוֹתָהּ בְּעוֹר אוֹ בִּקְלָף וְכַיּוֹצֵא בָּהֶן אִם הָיְתָה רְעוּעָה הֲרֵי הֵן כְּגוּפָהּ:","הַטּוֹפֵל כְּלִי חֶרֶס לִהְיוֹת מְבַשֵּׁל בּוֹ אֵינוֹ חִבּוּר. טָפַל כֵּלִים לִהְיוֹת זוֹפֵת בָּהֶן חִבּוּר:","חָבִית שֶׁנִּקְּבָה וַעֲשָׂאָהּ בְּזֶפֶת בְּבַעַץ וְגָפְרִית בְּסִיד וּבִגְפָסִים אֵינָן חִבּוּר וּשְׁאָר כָּל הַדְּבָרִים חִבּוּר:","דְּבָרִים הַלַּחִין הַמְּשׁוּכִין שֶׁטּוֹפְלִין בָּהֶן הַפִּטָסִין שֶׁל מַיִם כְּדֵי שֶׁלֹּא יִדְלֹף הַכְּלִי הֲרֵי הֵן כְּגוּפוֹ שֶׁל כְּלִי שֶׁאֲפִלּוּ נִטְמָא הַכְּלִי מֵאֲוִירוֹ אֳכָלִין וּמַשְׁקִין הַנּוֹגְעִין בַּטְּפֵלָה טְמֵאִין. וְכֵן טְפֵלוֹ שֶׁל תַּנּוּר הֲרֵי הוּא כְּחֶרֶס הַתַּנּוּר וְהוּא שֶׁיִּהְיֶה בָּעֳבִי הַטְּפֵלָה עַד טֶפַח שֶׁהוּא צָרְכּוֹ שֶׁל תַּנּוּר אֲבָל יֶתֶר עַל טֶפַח אֵינוֹ מִצֹּרֶךְ הַתַּנּוּר וְהַנּוֹגְעִין בְּיֶתֶר עַל טֶפַח מֵעָבְיוֹ טְהוֹרִים. טְפֵלַת הַכִּירָה עָבְיוֹ שָׁלֹשׁ אֶצְבָּעוֹת:","חָבִית שֶׁנִּקְּבָה וּסְתָמָהּ בְּזֶפֶת יוֹתֵר מִצָּרְכָּהּ הַנּוֹגֵעַ בְּצָרְכָּהּ טָמֵא וּבְיֶתֶר מִצָּרְכָּהּ טָהוֹר. זֶפֶת שֶׁנָּטְפָה עַל חָבִית הַנּוֹגֵעַ בָּהּ טָהוֹר:","מֵחַם שֶׁטְּפָלוֹ בְּחֵמָר וּבְחַרְסִית וְנִטְמָא הַנּוֹגֵעַ בַּחֵמָר טָמֵא וְהַנּוֹגֵעַ בַּחַרְסִית טָהוֹר שֶׁאֵין הַחַרְסִית מִתְחַבֵּר לַכְּלִי:","מְגוּפַת הֶחָבִית שֶׁטָּפַל בְּטִיט עָלֶיהָ וְעַל הֶחָבִית אֵינָהּ חִבּוּר לָהּ וְאִם נָגְעוּ מַשְׁקִין טְמֵאִין בָּחָבִית לֹא נִטְמֵאת הַמְּגוּפָה וְאִם נָגְעוּ בַּמְּגוּפָה לֹא נִטְמְאוּ אֲחוֹרֵי הֶחָבִית:","כְּלֵי נְחשֶׁת שֶׁזְּפָתָן אֵין הַזֶּפֶת חִבּוּר וְאִם לְיַיִן הֲרֵי זֶה כְּגוּף הַכְּלִי:","בָּצֵק שֶׁבְּסִדְקֵי הָעֲרֵבָה שֶׁנָּגַע בּוֹ שֶׁרֶץ אִם בְּפֶסַח הוֹאִיל וְאִסּוּרוֹ חָשׁוּב חוֹצֵץ וְלֹא נִטְמֵאת הָעֲרֵבָה. וְאִם בִּשְׁאָר יְמוֹת הַשָּׁנָה אִם הָיָה מַקְפִּיד עָלָיו הָעֲרֵבָה טְהוֹרָה וְאִם רוֹצֶה בְּקִיּוּמוֹ הֲרֵי הוּא כַּעֲרֵבָה וְנִטְמֵאת הָעֲרֵבָה:","הַמְּשִׁיחוֹת וְהָרְצוּעוֹת שֶׁבְּמִטְפְּחוֹת הַסְּפָרִים וְשֶׁבְּמִטְפְּחוֹת הַתִּינוֹקוֹת תְּפוּרוֹת חִבּוּר וּקְשׁוּרוֹת אֵינָן חִבּוּר. וְכֵן רְצוּעוֹת שֶׁבַּמַּעְדֵּר וְשֶׁבַּשַּׂק וְשֶׁבַּקֻפָּה אֲבָל שֶׁבְּאָזְנֵי כְּלֵי חֶרֶס אֲפִלּוּ תְּפוּרוֹת אֵינָן חִבּוּר שֶׁאֵין חִבּוּרִין לִכְלֵי חֶרֶס:","יַד קוֹרְדוֹם הַיּוֹצֵא מֵאַחֲרָיו שָׁלֹשׁ אֶצְבָּעוֹת חִבּוּר וְהַיֶּתֶר עַל שָׁלֹשׁ הַנּוֹגֵעַ בּוֹ טָהוֹר. יַד קוֹרְדוֹם מִלְּפָנָיו טֶפַח הַסָּמוּךְ לַבַּרְזֶל חִבּוּר יֶתֶר עַל כֵּן הַנּוֹגֵעַ בּוֹ טָהוֹר:","שְׁיָרֵי הַפַּרְגָּל טֶפַח. וְיַד מַקֶּבֶת שֶׁל מְפַתְּחֵי אֲבָנִים טֶפַח. יַד קֻרְנָס שֶׁל זֶהָבִים טְפָחַיִם וְשֶׁל חָרָשִׁים שְׁלֹשָׁה. שְׁיָרֵי מַלְמַד הַבָּקָר אַרְבָּעָה טְפָחִים סָמוּךְ לַדָּרְבָן. יַד קוֹרְדוֹם שֶׁחוֹפְרִין בּוֹ בְּדִידִין שֶׁל מַיִם אַרְבָּעָה טְפָחִים. וְיַד קוֹרְדוֹם שֶׁל נִכּוּשׁ חֲמִשָּׁה. וְיַד בֶּן פַּטִּישׁ חֲמִשָּׁה. וְשֶׁל פַּטִּישׁ שִׁשָּׁה. וְכֵן יַד קוֹרְדוֹם שֶׁל בִּקּוּעַ וְשֶׁל עָדִיר שִׁשָּׁה. יַד מַקֶּבֶת שֶׁל סַתָּתִין שִׁשָּׁה. שְׁיָרֵי הַמַּרְדֵּעַ הַסָּמוּךְ לְחַרְחוּר שֶׁל מַתֶּכֶת שֶׁבְּרֹאשׁ הַמַּרְדֵּעַ שִׁבְעָה טְפָחִים. יַד הַמַּגְרֵפָה שֶׁל בַּעֲלֵי בָּתִּים שְׁמוֹנָה טְפָחִים. וְשֶׁל סַיָּדִין עֲשָׂרָה. וְכָל הַיֶּתֶר עַל זֶה אִם רָצָה לְקַיְּמוֹ טָמֵא. יַד כָּל מְשַׁמְּשֵׁי הָאוּר כְּגוֹן הַשִּׁפּוּדִין וְהָאַסְכְּלָאוֹת אֲפִלּוּ אֲרֻכִּין כָּל שֶׁהֵן טְמֵאִין:","מַקֵּל שֶׁעֲשָׂאָהוּ יָד לְקוֹרְדוֹם הֲרֵי הוּא חִבּוּר לַטֻּמְאָה בִּשְׁעַת מְלָאכָה וְאִם נָגְעָה טֻמְאָה בַּמַּקֵּל כְּשֶׁהוּא חוֹרֵשׁ אוֹ מְבַקֵּעַ בּוֹ נִטְמָא הַקּוֹרְדוֹם וְאִם נָגְעָה בַּקּוֹרְדוֹם נִטְמָא הַמַּקֵּל. וְכֵן הַדְּיוּסְטָר שֶׁהֵן כִּשְׁנֵי כֵּלִים וְהַמַּסְמֵר מְחַבְּרָן לִהְיוֹת מֵסֵךְ עֲלֵיהֶן הֲרֵי הֵן חִבּוּר בִּשְׁעַת מְלָאכָה. קְבָעוֹ בְּקוֹרָה הֲרֵי זֶה מְקַבֵּל טֻמְאָה וְאֵין הַקּוֹרָה חִבּוּר לוֹ. עָשָׂה קְצָת הַקּוֹרָה דְּיוּסְטָר כָּל שֶׁהוּא מִן הַקּוֹרָה לְצֹרֶךְ הַדְּיוּסְטָר חִבּוּר לַדְּיוּסְטָר. וְהַנּוֹגֵעַ בִּשְׁאָר הַקּוֹרָה טָהוֹר שֶׁאֵין כָּל הַקּוֹרָה חִבּוּר:","עֲגָלָה שֶׁנִּטְמֵאת הַנּוֹגֵעַ בָּעל וּבַקַּטְרָב וּבָעֵץ וּבֶעָבוֹת אֲפִלּוּ בִּשְׁעַת מְלָאכָה טָהוֹר. וְהַנּוֹגֵעַ בַּחֶרֶב וּבַבֹּרֶךְ וּבַיְּצוּל וּבַעַיִן שֶׁל מַתֶּכֶת וּבַלְּחָיַיִם וּבַעִירָאִין טָמֵא. וְכֵן מְגֵרָה שֶׁנִּטְמֵאת הַנּוֹגֵעַ בְּיָדָהּ מִכָּאן וּמִכָּאן טָמֵא. וְהַנּוֹגֵעַ בַּחוּט וּבַמְּשִׁיחָה וּבָאַמָּה וּבַסְּנִיפִין שֶׁלָּהּ טָהוֹר שֶׁאֵין אֵלּוּ חִבּוּר לָהּ. אֲבָל הַנּוֹגֵעַ בַּמַּלְבֵּן שֶׁל מַסָּר הַגָּדוֹל טָמֵא:","מַכְבֵּשׁ שֶׁל חָרָשׁ שֶׁנִּטְמָא הָרֹמַח שֶׁבּוֹ הַנּוֹגֵעַ בַּמַּכְבֵּשׁ טָהוֹר. מְגֵרָה שֶׁנִּטְמָא הַנּוֹגֵעַ בַּקַּשְׁטָנִית שֶׁהִיא לְפוּפָה עָלָיו טָהוֹר שֶׁאֵינָהּ חִבּוּר. קֶשֶׁת שֶׁהָיְתָה מְתוּחָה וְהַחֵץ מָשׁוּךְ עִמָּהּ וְנִטְמָא הַחֵץ הַנּוֹגֵעַ בַּיֶּתֶר וּבַקֶּשֶׁת טָהוֹר וַאֲפִלּוּ כְּשֶׁהִיא מְתוּחָה. וְכֵן מְצוּדַת הָאִישׁוּת שֶׁנִּטְמָא הַחֵץ שֶׁלָּהּ לֹא נִטְמֵאת הַמְּצוּדָה אֲפִלּוּ כְּשֶׁהִיא מְתוּחָה. וְכֵן מַסֶּכֶת נְסוּכָה שֶׁנִּטְמֵאת בִּשְׁעַת הָאָרִיג הַנּוֹגֵעַ בַּכֹּבֶד הָעֶלְיוֹן וְהַתַּחְתּוֹן וּבַנִּירִים וּבַקֵּירוֹס וּבַחוּט שֶׁהֶעֱבִירוֹ עַל גַּבֵּי אַרְגָּמָן וּבָעִירָה שֶׁאֵינָהּ עָתִיד לְהַחְזִירָהּ טָהוֹר שֶׁכָּל אֵלּוּ אֵינָן חִבּוּר לְבֶגֶד. אֲבָל הַנּוֹגֵעַ בְּנֶפֶשׁ הַמַּסֶּכֶת וּבַשְּׁתִי הָעוֹמֵד וּבַכֶּפֶל שֶׁהֶעֱבִירוֹ עַל גַּבֵּי אַרְגָּמָן וּבָעִירָה שֶׁהוּא לְהַחְזִירָהּ טָמֵא שֶׁכָּל אֵלּוּ חִבּוּרִין לְבֶגֶד:","הַנּוֹגֵעַ בַּצֶּמֶר שֶׁעַל הָאִימָה וּבָאַשְׁוָיָה טָהוֹר. הַנּוֹגֵעַ בַּפִּיקָה עַד שֶׁלֹּא פְּרָעָהּ טָמֵא מִשֶּׁפְּרָעָהּ טָהוֹר:","הַחוּט שֶׁהִשִּׁילוֹ לְמַחַט אֲפִלּוּ קָשׁוּר מִשְּׁנֵי צְדָדִין אֵינוֹ חִבּוּר. הִכְנִיסוֹ לְבֶגֶד הַחוּט חִבּוּר לַבֶּגֶד וְאֵין הַמַּחַט חִבּוּר לַבֶּגֶד. וְאֵין הַחוּט כֻּלּוֹ חִבּוּר לַבֶּגֶד אֶלָּא כָּל שֶׁהוּא לְצֹרֶךְ הַתְּפִירָה חִבּוּר שֶׁאֵינוֹ לְצֹרֶךְ הַתְּפִירָה אֵינוֹ חִבּוּר. הַחוּט שֶׁפֵּרֵשׁ מִן הַבֶּגֶד אֲפִלּוּ מֵאָה אַמָּה כֻּלּוֹ חִבּוּר. חֶבֶל שֶׁקָּשׁוּר בְּחֶרֶס אֲפִלּוּ מֵאָה אַמָּה כֻּלּוֹ חִבּוּר. קָשַׁר בּוֹ חֶבֶל אֶחָד מִן הַקֶּשֶׁר וּלְפָנִים חִבּוּר מִן הַקֶּשֶׁר וְלַחוּץ אֵינוֹ חִבּוּר. הַחֶבֶל שֶׁהוּא קָשׁוּר בְּקֻפָּה אֵינוֹ חִבּוּר אֶלָּא אִם כֵּן תָּפַר:"],"Mishneh Torah, Vessels 6":["כָּל כְּלִי שֶׁנִּטְמָא וְנִשְׁבַּר אַחַר שֶׁנִּטְמָא וְנִפְסְדָה צוּרָתוֹ וְתַשְׁמִישׁוֹ טָהוֹר בִּשְׁבִירָתוֹ. וְכֵן כֵּלִים שֶׁנִּשְׁבְּרוּ כְּשֶׁהֵן טְהוֹרִין שִׁבְרֵיהֶן אֵינָן מְקַבְּלִין טֻמְאָה:","כַּמָּה שִׁעוּר הַשֶּׁבֶר שֶׁיִּשָּׁבֵר בִּכְלִי עֵץ אוֹ כְּלִי עֶצֶם וְיִהְיֶה טָהוֹר. כָּל כְּלֵי בַּעֲלֵי בָּתִּים שִׁעוּרָן בְּרִמּוֹנִים. כֵּיצַד. מִשֶּׁיִּנָּקֵב הַכְּלִי בְּמוֹצִיא רִמּוֹן טָהוֹר. וְהָרִמּוֹן שֶׁאָמְרוּ בֵּינוֹנִי לֹא גָּדוֹל וְלֹא קָטָן, לְפִי דַּעַת הָרוֹאֶה. וְיִהְיוּ בַּכְּלִי שְׁלֹשָׁה רִמּוֹנִים אֲחוּזִים זֶה בָּזֶה. נִקַּב הַכְּלִי בְּמוֹצִיא זַיִת וּסְתָמוֹ וְחָזַר וְנִקַּב בְּמוֹצִיא זַיִת וּסְתָמוֹ [עַד שֶׁהִשְׁלִימוֹ לְמוֹצִיא] רִמּוֹן אַף עַל פִּי שֶׁהוּא סָתוּם טָהוֹר שֶׁהֲרֵי נַעֲשׂוּ לוֹ פָּנִים חֲדָשׁוֹת:","כֵּלִים שֶׁעֲשָׂאָן מִתְּחִלָּה נְקוּבִין בְּמוֹצִיא רִמּוֹן כְּגוֹן הַסַּל וְהַפֻּחְלָץ שֶׁל גְמַלִּים וְהָאַפִּיפְיָרוֹת מְקַבְּלִין טֻמְאָה עַד שֶׁיִּקָּרַע רֻבָּן:","אֲפִּיפְיָרוֹת שֶׁעָשָׂה לָהֶן קָנִים לְמַעְלָה וּלְמַטָּה לְחַזֵּק טְהוֹרוֹת. עָשָׂה לָהֶן גַּפַּיִם כָּל שֶׁהֵן אַף עַל פִּי שֶׁכֻּלָּהּ נְקוּבָה כְּמוֹצִיא רִמּוֹן מְקַבֶּלֶת טֻמְאָה:","כָּל הַכֵּלִים שֶׁאֵינָן יְכוֹלִין לְקַבֵּל רִמּוֹנִים כְּגוֹן הָרֹבַע וַחֲצִי רֹבַע וְהַקְּנוֹנִים הַקְּטַנִּים שִׁעוּרָן בְּמוֹצִיא זַיִת. נִגְמְמוּ שִׂפְתוֹתֵיהֶן אִם נִשְׁאַר בָּהֶן כְּדֵי לְקַבֵּל כָּל שֶׁהוּא טְמֵאִין:","הַסַּלִּין שֶׁל פַּת שִׁעוּרָן כְּכִכָּרוֹת שֶׁל פַּת:","קֻפַּת הַגַּנָּנִים מִשֶּׁתּוֹצִיא אֲגֻדּוֹת שֶׁל יָרָק טְהוֹרָה. וְשֶׁל בַּעֲלֵי בָּתִּים בְּמוֹצִיא תֶּבֶן. שֶׁל בַּלָּנִין בִּגְבָבָא:","בֵּית קְעָרוֹת שֶׁאֵינוֹ מְקַבֵּל קְעָרוֹת הוֹאִיל וּמְקַבֵּל הַתַּמְחוּיִין הֲרֵי זֶה מְקַבֵּל טֻמְאָה. וְכֵן בֵּית הָרְעִי שֶׁאֵינוֹ מְקַבֵּל מַשְׁקִין הוֹאִיל וּמְקַבֵּל אֶת הָרְעִי הֲרֵי זֶה מְקַבֵּל טֻמְאָה:","כָּל כְּלִי עֵץ שֶׁנֶּחְלַק לִשְׁנַיִם טָהוֹר וְאַף עַל פִּי שֶׁמְּקַבְּלִין עַל דָּפְנוֹתֵיהֶן בְּאִלְפָּסִין. חוּץ מִכֵּלִים שֶׁל עֵץ שֶׁחֶצְיָן אוֹ מִקְצָתָן כְּלִי בִּפְנֵי עַצְמוֹ מִתְּחִלַּת עֲשִׂיָּתָן כְּגוֹן הַשֻּׁלְחָן הַכָּפוּל שֶׁמִּתְחִלָּה נַעֲשָׂה שְׁנֵי חֲלָקִים וַהֲרֵי הוּא נִכְפָּל וְנִפְשָׁט. וּכְגוֹן הַתַּמְחוּי הַמִּזְנוֹן שֶׁהוּא קְעָרוֹת קְעָרוֹת וַהֲרֵי בְּכָל חֵלֶק מֵחֲלָקָיו קְעָרוֹת שְׁלֵמוֹת. וּכְגוֹן הַכִּסֵּא הַכָּפוּל וְכָל כַּיּוֹצֵא בְּאֵלּוּ. וְכֵן בֵּית לָגִינִין וּבֵית הַכּוֹסוֹת שֶׁל עֵץ שֶׁנִּפְחַת אֶחָד מֵהֶן זֶה שֶׁנִּפְחַת טָהוֹר וְאֵינוֹ חִבּוּר לִשְׁאָר הַבָּתִּים. נִפְחַת הַשֵּׁנִי טָהוֹר וְאֵינוֹ חִבּוּר לוֹ. נִפְחֲתוּ שְׁלָשְׁתָּן כֻּלָּן טְהוֹרִין. וְכֵן כָּל כַּיּוֹצֵא בְּכֵלִים כָּאֵלּוּ:","מַשְׁפֶּלֶת שֶׁאֶמְצָעִיתָהּ גְּבוֹהָה וְזָוִיּוֹתֶיהָ יוֹרְדוֹת וְנִפְחֲתָה מִצַּד אֶחָד טְמֵאָה מִפְּנֵי שֶׁהִיא מְקַבֶּלֶת מִצַּד הַשֵּׁנִי. נִפְחֲתָה מִצַּד הַשֵּׁנִי טְהוֹרָה. הַשֻּׁלְחָן וְהַדֻּלְפְּקִי שֶׁנִּפְחֲתוּ מְקַבְּלִין טֻמְאָה עַד שֶׁיֵּחָלְקוּ וְיִבָּדֵל כָּל חֵלֶק מֵחֲבֵרוֹ. נִטְּלָה אַחַת מֵרַגְלֵיהֶן טְהוֹרָה. וְכֵן אִם נִטְּלָה הַשְּׁנִיָּה. נִטְּלָה הַשְּׁלִישִׁית אִם חִשֵּׁב עֲלֵיהֶם שֶׁיֹּאכַל עַל שֻׁלְחָן זֶה אוֹ עַל דֻּלְפְּקִי זוֹ כְּמוֹ אוֹכֵל בְּטַבְלָא מְקַבְּלִין טֻמְאָה וְאִם לָאו טְהוֹרִין:","כְּלֵי נְסָרִים שֶׁנָּפְלוּ שִׂפְתוֹתֵיהֶן טְהוֹרִין. וְאִם נִשְׁאַר מַחְסוֹם שִׂפְתוֹתֵיהֶן כָּל שֶׁהוּא מְקַבְּלִין טֻמְאָה:","טַבְלָא שֶׁמִּלְּאָהּ עֵצִים וּתְקָעָהּ טְהוֹרָה. חִפָּהּ בִּנְסָרִים מְקַבֶּלֶת טֻמְאָה:","סַפְסָל שֶׁנִּתְפָּרֵק טָהוֹר. סִרְגְּלוֹ בִּמְשִׁיחוֹת אוֹ בַּחֲבָלִים מְקַבֵּל טֻמְאָה:","הַסַּלִּים שֶׁל גְּמַלִּים הִתִּירָן טְהוֹרִין חָזַר וּקְשָׁרָן מְקַבְּלִין טֻמְאָה. נִמְצְאוּ מִתְטַמְּאִין וּמִתְטַהֲרִין אֲפִלּוּ עֶשֶׂר פְּעָמִים בְּיוֹם:","הַשֻּׁלְחָן אוֹ הַדֻּלְפְּקִי שֶׁחִפָּן בְּשַׁיִשׁ וְשִׁיֵּר בָּהֶם מְקוֹם הַנָּחַת הַכּוֹסוֹת מְקַבְּלִין טֻמְאָה וְאִם חִפָּה הַכּל טָהוֹר. בֵּין בְּצִפּוּי עוֹמֵד בֵּין בְּצִפּוּי שֶׁאֵינוֹ עוֹמֵד בֵּין שֶׁחִפָּה אֶת לְבַזְבְּזָיו בֵּין שֶׁלֹּא חִפָּן בֵּין שֶׁהָיוּ שֶׁל עֵצִים חֲשׁוּבִים כְּגוֹן אֶשְׁכְּרוֹעַ וְכַיּוֹצֵא בּוֹ בֵּין שֶׁהָיוּ שֶׁל שְׁאָר עֵצִים הוֹאִיל וְחִפָּן כֻּלָּן טְהוֹרִין כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Vessels of the Sanctuary and Those Who Serve Therein 8":["בִגְדֵי כְּהֻנָּה שְׁלֹשָׁה מִינִים. בִּגְדֵי כֹּהֵן הֶדְיוֹט. וּבִגְדֵי זָהָב. וּבִגְדֵי לָבָן. בִּגְדֵי כֹּהֵן הֶדְיוֹט הֵם אַרְבָּעָה כֵּלִים כֻּתֹּנֶת וּמִכְנָסָיִם וּמִגְבָּעוֹת וְאַבְנֵט. וְאַרְבָּעָתָן שֶׁל פִּשְׁתָּן לְבָנִים וְחוּטָן כָּפוּל שִׁשָּׁה. וְהָאַבְנֵט לְבַדּוֹ רָקוּם בְּצֶמֶר:","בִּגְדֵי זָהָב הֵן בִּגְדֵי כֹּהֵן גָּדוֹל וְהֵם שְׁמֹנָה כֵּלִים. הָאַרְבָּעָה שֶׁל כָּל כֹּהֵן. וּמְעִיל וְאֵפוֹד וְחשֶׁן וְצִיץ. וְאַבְנֵטוֹ שֶׁל כֹּהֵן גָּדוֹל מַעֲשֶׂה רֹקֵם הוּא וְהוּא דּוֹמֶה בְּמַעֲשָׂיו לְאַבְנֵט כֹּהֵן הֶדְיוֹט. וּמִצְנֶפֶת הָאֲמוּרָה בְּאַהֲרֹן הִיא הַמִּגְבַּעַת הָאֲמוּרָה בְּבָנָיו. אֶלָּא שֶׁכֹּהֵן גָּדוֹל צוֹנֵף בָּהּ כְּמִי שֶׁלּוֹפֵף עַל הַשֶּׁבֶר. וּבָנָיו צוֹנְפִין בָּהּ כְּכוֹבַע וּלְפִיכָךְ נִקְרֵאת מִגְבַּעַת:","בִּגְדֵי לָבָן הֵם אַרְבָּעָה כֵּלִים שֶׁמְּשַׁמֵּשׁ בָּהֶן כֹּהֵן גָּדוֹל בְּיוֹם הַכִּפּוּרִים. כֻּתֹּנֶת. וּמִכְנָסָיִם. וְאַבְנֵט. וּמִצְנֶפֶת. וְאַרְבָּעָתָן לְבָנִים וְחוּטָן כָּפוּל שִׁשָּׁה וּמִן הַפִּשְׁתָּן לְבַדּוֹ הֵם. וּשְׁתֵּי כֻּתָּנוֹת אֲחֵרוֹת הָיוּ לוֹ לְכֹהֵן גָּדוֹל בְּיוֹם הַכִּפּוּרִים. אַחַת לֹבְשָׁהּ בַּשַּׁחַר וְאַחַת בֵּין הָעַרְבָּיִם. וּשְׁתֵּיהֶם בִּשְׁלֹשִׁים מָנֶה מִשֶּׁל הֶקְדֵּשׁ. וְאִם רָצָה לְהוֹסִיף מוֹסִיף מִשֶּׁלּוֹ וּמַקְדִּישׁ הַתּוֹסֶפֶת וְאַחַר כָּךְ עוֹשֶׂה בָּהּ הַכֻּתֹּנֶת:","בִּגְדֵי כְּהֻנָּה מִצְוָתָן שֶׁיִּהְיוּ חֲדָשִׁים נָאִים וּמְשֻׁלְּשָׁלִים כְּדֶרֶךְ בִּגְדֵי הַגְּדוֹלִים שֶׁנֶּאֱמַר (שמות כח ב) (שמות כח מ) \"לְכָבוֹד וּלְתִפְאָרֶת\". הָיוּ מְטֻשְׁטָּשִׁין אוֹ מְקֹרָעִין אוֹ אֲרֻכִּין יֶתֶר עַל מִדָּתוֹ אוֹ קְצָרִים פָּחוֹת מִמִּדָּתוֹ אוֹ שֶׁסִּלְקָּן בָּאַבְנֵט וְעָבַד עֲבוֹדָתוֹ פְּסוּלָה. הָיוּ מְשֹׁחָקִין אוֹ שֶׁהָיוּ אֲרֻכִּים וְסִלְקָּן בָּאַבְנֵט עַד שֶׁנַּעֲשׂוּ כְּמִדָּתוֹ וְעָבַד עֲבוֹדָתוֹ כְּשֵׁרָה:","כָּל בֶּגֶד מִבִּגְדֵי כְּהֻנָּה שֶׁנַּעֲשׂוּ צוֹאִין אֵין מְלַבְּנִין אוֹתָן וְאֵין מְכַבְּסִין אוֹתָן אֶלָּא מַנִּיחָן לִפְתִילוֹת וְלוֹבֵשׁ חֲדָשִׁים. וּבִגְדֵי כֹּהֵן גָּדוֹל שֶׁבָּלוּ גּוֹנְזִין אוֹתָן. וּבִגְדֵי לָבָן שֶׁעוֹבֵד בָּהֶם בְּיוֹם הַצּוֹם אֵינוֹ עוֹבֵד בָּהֶם פַּעַם שְׁנִיָּה לְעוֹלָם אֶלָּא נִגְנָּזִין בַּמָּקוֹם שֶׁיִּפְשֹׁט אוֹתָם שָׁם שֶׁנֶּאֱמַר (ויקרא טז כג) \"וְהִנִּיחָם שָׁם\" וְהֵם אֲסוּרִין בַּהֲנָאָה:","מִכְנְסֵי כֹּהֲנִים הֶדְיוֹטִים שֶׁבָּלוּ וְאַבְנֵטֵיהֶם הָיוּ עוֹשִׂין מֵהֶן פְּתִילוֹת וּמַדְלִיקִין בָּהֶן בַּמִּקְדָּשׁ בְּשִׂמְחַת בֵּית הַשּׁוֹאֵבָה. וְכֻתְּנוֹת כֹּהֲנִים הֶדְיוֹטִים שֶׁבָּלוּ הָיוּ עוֹשִׂין מֵהֶן פְּתִילוֹת לִמְנוֹרַת תָּמִיד:","כָּל בִּגְדֵי הַכֹּהֲנִים אֵינָן בָּאִים אֶלָּא מִשֶּׁל צִבּוּר. וְיָחִיד שֶׁהִתְנַדֵּב בֶּגֶד מִבִּגְדֵי כְּהֻנָּה מוֹסְרוֹ לַצִּבּוּר וּמֻתָּר. וְכֵן כָּל כְּלֵי הַשָּׁרֵת וַעֲצֵי הַמַּעֲרָכָה שֶׁמְּסָרָן יָחִיד לַצִּבּוּר הֲרֵי הֵן כְּשֵׁרִין. אַף כָּל קָרְבְּנוֹת הַצִּבּוּר שֶׁהִתְנַדֵּב אוֹתָן יָחִיד מִשֶּׁלּוֹ כְּשֵׁרִים וּבִלְבָד שֶׁיִּמְסְרֵם לַצִּבּוּר:","בִּגְדֵי כֹּהֲנִים הֶדְיוֹטִים הָיוּ עוֹשִׂין מֵהֶן מַחֲלָצוֹת רַבּוֹת. וְשִׁשָּׁה וְתִשְׁעִים חַלּוֹן הָיוּ בַּמִּקְדָּשׁ לְהָנִיחַ בָּהֶן הַבְּגָדִים אַרְבָּעָה חַלּוֹנוֹת לְכָל מִשְׁמָר. וְשֵׁם כָּל מִשְׁמָר כָּתוּב עַל חַלּוֹנוֹתָיו. וְכֻלָּן סְתוּמוֹת. וּכְשֶׁיִּכָּנְסוּ אַנְשֵׁי מִשְׁמָר לַעֲבוֹדָה בַּשַּׁבָּת שֶׁלָּהֶן פּוֹתְחִין חַלּוֹנוֹתֵיהֶן כָּל יְמֵי שַׁבָּתָן וְנוֹטְלִין הַכֵּלִים. וּכְשֶׁיֵּצְאוּ מַחֲזִירִין הַבְּגָדִים לְחַלּוֹנוֹתֵיהֶן וְסוֹתְמִין:","וְלָמָּה עָשׂוּ אַרְבָּעָה חַלּוֹנוֹת לְכָל מִשְׁמָר. לְפִי שֶׁלֹּא יִהְיוּ הַכֵּלִים מְעֹרָבִין. אֶלָּא כָּל הַמִּכְנָסָיִם בְּחַלּוֹן אֶחָד וְכָתוּב עָלָיו מִכְנְסַיִם. וְכל הָאַבְנֵטִים בְּחַלּוֹן אֶחָד וְכָתוּב עָלָיו אַבְנֵט. וְכֵן הַמִּצְנָפוֹת כֻּלָּן בְּחַלּוֹן אֶחָד. וְהַכֻּתָּנוֹת כֻּלָּן בְּחַלּוֹן אֶחָד:","כֹּהֵן גָּדוֹל מַנִּיחַ בִּגְדֵי זָהָב בַּלִּשְׁכָּה שֶׁלּוֹ בַּלַּיְלָה אוֹ בְּעֵת שֶׁיֵּצֵא מִן הַמִּקְדָּשׁ:","בִּגְדֵי כְּהֻנָּה מֻתָּר לֵהָנוֹת בָּהֶן. לְפִיכָךְ לֹבְשָׁם בְּיוֹם עֲבוֹדָתוֹ וַאֲפִלּוּ שֶׁלֹּא בִּשְׁעַת עֲבוֹדָה חוּץ מִן הָאַבְנֵט מִפְּנֵי שֶׁהוּא שַׁעַטְנֵז:","אָסוּר לְכֹהֵן הֶדְיוֹט לְלֹבְשׁוֹ אֶלָּא בִּשְׁעַת עֲבוֹדָה. אֵין הַכֹּהֲנִים לוֹבְשִׁין לַעֲבוֹדָה אֶלָּא צֶמֶר וּפִשְׁתִּים בִּלְבָד:","וְכָל מָקוֹם שֶׁנֶּאֱמַר בַּתּוֹרָה שֵׁשׁ אוֹ בַּד הוּא הַפִּשְׁתִּים וְהוּא הַבּוּץ. וּתְכֵלֶת הָאֲמוּרָה בְּכָל מָקוֹם הִיא הַצֶּמֶר הַצָּבוּעַ כְּעֶצֶם שָׁמַיִם שֶׁהוּא פָּתוּךְ מִן הַכֹּחַל. הָאַרְגָּמָן הוּא הַצֶּמֶר הַצָּבוּעַ אָדוֹם. וְתוֹלַעַת הַשָּׁנִי הוּא הַצֶּמֶר הַצָּבוּעַ בְּתוֹלַעַת:","כָּל מָקוֹם שֶׁנֶּאֱמַר בַּתּוֹרָה שֵׁשׁ אוֹ שֵׁשׁ מָשְׁזָר צָרִיךְ שֶׁיִּהְיֶה הַחוּט כָּפוּל שִׁשָּׁה. וּמָקוֹם שֶׁנֶּאֱמַר בַּד אִם הָיָה חוּט אֶחָד לְבַדּוֹ כָּשֵׁר. וּמִצְוָה מִן הַמֻּבְחָר שֶׁיִּהְיֶה כָּפוּל שִׁשָּׁה. וּמָקוֹם שֶׁנֶּאֱמַר בּוֹ מָשְׁזָר בִּלְבָד צָרִיךְ שֶׁיִּהְיֶה חוּטָן כָּפוּל שְׁמֹנֶה:","כָּל מָקוֹם שֶׁנֶּאֱמַר בַּתּוֹרָה מַעֲשֶׂה רֹקֵם הוּא שֶׁתִּהְיֶינָה הַצּוּרוֹת הַנַּעֲשׂוֹת בַּאֲרִיגָה נִרְאוֹת מִצַּד אֶחָד בִּפְנֵי הָאָרִיג. וּמַעֲשֶׂה חשֵׁב הוּא שֶׁתִּהְיֶה הַצּוּרָה נִרְאֵית מִשְּׁנֵי צְדָדִין פָּנִים וְאָחוֹר:","וְכֵיצַד מַעֲשֶׂה הַבְּגָדִים. הַכֻּתֹּנֶת בֵּין שֶׁל כֹּהֵן גָּדוֹל בֵּין שֶׁל כֹּהֵן הֶדְיוֹט מִשְׁבְּצֹת הָיְתָה שֶׁהִיא בָּתִּים בָּתִּים בַּאֲרִיגָתָהּ כְּמוֹ בֵּית הַכּוֹסוֹת כְּדֶרֶךְ שֶׁעוֹשִׂין הָאוֹרְגִין בַּבְּגָדִים הַקָּשִׁים. וּבֵית יָד שֶׁלָהּ נֶאֱרָג בִּפְנֵי עַצְמוֹ וּמְחַבְּרִין אוֹתוֹ עִם גּוּף הַכֻּתֹּנֶת בִּתְפִירָה:","אֹרֶךָ הַכֻּתֹּנֶת עַד לְמַעְלָה מִן הֶעָקֵב. וְאֹרֶךְ בֵּית יָד שֶׁלָהּ עַד פַּס יָדוֹ. וְרָחְבּוֹ כְּרֹחַב הַיָּד:","הַמִּכְנָסָיִם בֵּין שֶׁל כֹּהֵן גָּדוֹל בֵּין שֶׁל כֹּהֵן הֶדְיוֹט הֵם מִמָּתְנַיִם עַד יְרֵכַיִם שֶׁהוּא לְמַעְלָה מִן הַטִּבּוּר קָרוֹב מִן הַלֵּב עַד סוֹף הַיָּרֵךְ שֶׁהוּא הָאַרְכּוּבָה. וּשְׁנָצִים יֵשׁ לָהֶם. וְאֵין לָהֶם לֹא בֵּית הַנֶּקֶב וְלֹא בֵּית הָעֶרְוָה אֶלָּא מֻקָּפִין כְּמִין כִּיס:","הַמִּצְנֶפֶת שֶׁל כֹּהֵן גָּדוֹל אוֹ הֶדְיוֹט אָרְכּוֹ שֵׁשׁ עֶשְׂרֵה אַמּוֹת. וְהָאַבְנֵט רָחְבּוֹ כְּמוֹ שָׁלֹשׁ אֶצְבָּעוֹת וְאָרְכּוֹ שְׁנַיִם וּשְׁלֹשִׁים אַמָּה. מַקִּיפוֹ וּמַחֲזִירוֹ כֶּרֶךְ עַל גַּבֵּי כֶּרֶךְ. וּבִגְדֵי כְּהֻנָּה כֻּלָּן אֵין עוֹשִׂין אוֹתָן מַעֲשֶׂה מַחַט אֶלָּא מַעֲשֶׂה אוֹרֵג שֶׁנֶּאֱמַר (שמות כח לב) (שמות לט כב) (שמות לט כז) \"מַעֲשֶׂה אוֹרֵג\":"],"Mishneh Torah, Vows 4":["נִּדְרֵי אֳנָסִין וְנִדְרֵי שְׁגָגוֹת וְנִדְרֵי הֲבַאי הֲרֵי אֵלּוּ מֻתָּרִים כְּדֶרֶךְ שֶׁבֵּאַרְנוּ בִּשְׁבוּעוֹת. הֲרֵי שֶׁהִדִּירוּהוּ הָאַנָּסִין וְהַמּוֹכְסִין וְאָמְרוּ לוֹ נְדֹר לָנוּ שֶׁהַבָּשָׂר אָסוּר עָלֶיךָ אִם יֵשׁ עִמְּךָ דָּבָר שֶׁחַיָּב בְּמֶכֶס. וְנָדַר וְאָמַר הֲרֵי הַפַּת וְהַבָּשָׂר וְהַיַּיִן אֲסוּרִין עָלַי הֲרֵי זֶה מֻתָּר בַּכּל וְאַף עַל פִּי שֶׁהוֹסִיף עַל מַה שֶּׁבִּקְּשׁוּ מִמֶּנּוּ. וְכֵן אִם בִּקְּשׁוּ מִמֶּנּוּ שֶׁיִּדֹּר שֶׁלֹּא תֵּהָנֶה אִשְׁתּוֹ לוֹ וְנָדַר שֶׁלֹּא תֵּהָנֶה לוֹ אִשְׁתּוֹ וּבָנָיו וְאֶחָיו כֻּלָּן מֻתָּרִין. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","וּבְכָל הַנְּדָרִים הָאֵלּוּ צָרִיךְ שֶׁיִּתְכַּוֵּן בְּלִבּוֹ לְדָבָר הַמֻּתָּר. כְּגוֹן שֶׁיָּשִׂים בְּלִבּוֹ שֶׁיִּהְיוּ אֲסוּרִין עָלָיו אוֹתוֹ הַיּוֹם בִּלְבַד אוֹ אוֹתָהּ שָׁעָה וְכֵן כַּיּוֹצֵא בָּזֶה וְסוֹמֵךְ עַל דְּבָרִים שֶׁבְּלִבּוֹ הוֹאִיל וְהוּא אָנוּס וְאֵינוֹ יָכוֹל לְהוֹצִיא בִּשְׂפָתָיו וְנִמְצָא בְּשָׁעָה שֶׁיִּדֹּר לָהֶן אֵין פִּיו וְלִבּוֹ שָׁוִין כְּמוֹ שֶׁבֵּאַרְנוּ בִּשְׁבוּעוֹת:","וְכֵן נִדְרֵי זֵרוּזִין מֻתָּרִין. כֵּיצַד. כְּגוֹן שֶׁהִדִּיר חֲבֵרוֹ שֶׁיֹּאכַל אֶצְלוֹ וְנָדַר זֶה שֶׁלֹּא יֹאכַל מִפְּנֵי שֶׁאֵינוֹ רוֹצֶה לְהַטְרִיחַ עָלָיו. בֵּין אָכַל בֵּין לֹא אָכַל שְׁנֵיהֶן פְּטוּרִין. וְכֵן הַמּוֹכֵר שֶׁנָּדַר שֶׁלֹּא יִמְכֹּר חֵפֶץ זֶה אֶלָּא בְּסֶלַע וְהַלּוֹקֵחַ נָדַר שֶׁלֹּא יִקָּחֶנּוּ אֶלָּא בְּשֶׁקֶל וְרָצוּ בִּשְׁלֹשָׁה דִּינָרִין שְׁנֵיהֶן פְּטוּרִין. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. לְפִי שֶׁכָּל אֶחָד מֵהֶם לֹא גָּמַר בְּלִבּוֹ וְלֹא נָדַר אֶלָּא כְּדֵי לְזָרֵז אֶת חֲבֵרוֹ וְלֹא גָּמַר בְּלִבּוֹ:","וּמִנַּיִן שֶׁאֲפִילוּ אַרְבָּעָה מִינֵי נְדָרִים אֵלּוּ שֶׁהֵן מֻתָּרִים שֶׁאָסוּר לוֹ לְאָדָם לִהְיוֹת נוֹדֵר בָּהֶן עַל מְנָת לְבַטְּלָן. תַּלְמוּד לוֹמַר (במדבר ל ג) \"לֹא יַחֵל דְּבָרוֹ\" לֹא יַעֲשֶׂה דְּבָרָיו חֻלִּין:","מִי שֶׁנָּדַר וְנִחַם עַל נִדְרוֹ הֲרֵי זֶה נִשְׁאָל לְחָכָם וּמַתִּירוֹ. וְדִין הֶתֵּר נְדָרִים כְּדִין הֶתֵּר שְׁבוּעוֹת שֶׁאֵין מַתִּיר אֶלָּא חָכָם מֻבְהָק אוֹ שְׁלֹשָׁה הֶדְיוֹטוֹת בְּמָקוֹם שֶׁאֵין חָכָם. וּבְלָשׁוֹן שֶׁמַּתִּירִין הַשְּׁבוּעָה מַתִּירִין הַנֵּדֶר. וְכֵן שְׁאָר הָעִנְיָנוֹת שֶׁפֵּרַשְׁנוּ בִּשְׁבוּעוֹת כֻּלָּן בִּנְדָרִים כְּדֶרֶךְ שֶׁהֵן בִּשְׁבוּעוֹת:","וְאֵין מַתִּירִין הַנֵּדֶר עַד שֶׁיָּחוּל כִּשְׁבוּעָה:","וּכְשֵׁם שֶׁנִּשְׁאָלִים עַל נִדְרֵי הָאִסָּר וּמַתִּירִין אוֹתוֹ. כָּךְ נִשְׁאָלִים עַל נִדְרֵי הֶקְדֵּשׁ וּמַתִּירִין אוֹתוֹ. בֵּין נִדְרֵי קָדְשֵׁי בֶּדֶק הַבַּיִת בֵּין קָדְשֵׁי מִזְבֵּחַ. וְאֵין נִשְׁאָלִין עַל הַתְּמוּרָה:","וּכְשֵׁם שֶׁהָאָב אוֹ הַבַּעַל מֵפֵר נִדְרֵי אִסָּר כָּךְ מֵפֵר נִדְרֵי הֶקְדֵּשׁוֹת הַדּוֹמִין לְנִדְרֵי הָאִסָּר:","מִי שֶׁנָּדַר וְשָׁמַע חֲבֵרוֹ וְאָמַר וַאֲנִי וְשָׁמַע שְׁלִישִׁי וְאָמַר וַאֲנִי וְנִשְׁאַל הָרִאשׁוֹן עַל נִדְרוֹ וְהֻתַּר הֻתְּרוּ כֻּלָּן. נִשְׁאַל הָאַחֲרוֹן וְהֻתַּר הָאַחֲרוֹן מֻתָּר וְכֻלָּן אֲסוּרִין. נִשְׁאַל הַשֵּׁנִי וְהֻתַּר הַשֵּׁנִי וְשֶׁל אַחֲרָיו מֻתָּרִין וְהָרִאשׁוֹן אָסוּר:","וְכֵן הַמַּתְפִּיס דְּבָרִים הַרְבֵּה בְּנֵדֶר כְּגוֹן שֶׁנָּדַר עַל הַפַּת וְהִתְפִּיס הַבָּשָׂר וְנִשְׁאַל עַל הַפַּת וְהֻתַּר בָּהּ הֻתַּר הַבָּשָׂר. נִשְׁאַל עַל הַבָּשָׂר וְהֻתַּר בּוֹ לֹא הֻתַּר הַפַּת:","הַנִּשְׁבָּע אוֹ הַנּוֹדֵר שֶׁאֵינִי נֶהֱנֶה לְכֻלְּכֶם וְנִשְׁאַל עַל נִדְרוֹ אוֹ עַל שְׁבוּעָתוֹ עַל אֶחָד מֵהֶם וְהִתִּירוֹ הֻתְּרוּ כֻּלָּם. שֶׁהַנֵּדֶר שֶׁהֻתַּר מִכְּלָלוֹ הֻתַּר כֻּלּוֹ. אָמַר שֶׁאֵינִי נֶהֱנֶה לָזֶה וְלָזֶה וְלָזֶה הֻתַּר הָרִאשׁוֹן הֻתְּרוּ כֻּלָּן. הֻתַּר אַחֲרוֹן הָאַחֲרוֹן מֻתָּר וְכֻלָּן אֲסוּרִין. שֶׁאֵינִי נֶהֱנֶה לָזֶה לָזֶה לָזֶה צְרִיכִין פֶּתַח לְכָל אֶחָד וְאֶחָד. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","נָדַר בְּנָזִיר וּבְקָרְבָּן וּבִשְׁבוּעָה אוֹ שֶׁנָּדַר וְאֵין יָדוּעַ בְּאֵי זֶה מֵהֶן נָדַר פֶּתַח אֶחָד לְכֻלָּן:","הַנּוֹדֵר מֵאַנְשֵׁי הָעִיר וְנִשְׁאַל לֶחָכָם שֶׁבָּעִיר. אוֹ שֶׁנָּדַר מִיִּשְׂרָאֵל וַהֲרֵי הוּא נִשְׁאַל לְחָכָם שֶׁבְּיִשְׂרָאֵל הֲרֵי נִדְרוֹ מֻתָּר:","הָאוֹמֵר פֵּרוֹת אֵלּוּ אֲסוּרִין עָלַי הַיּוֹם אִם אֵלֵךְ לְמָחָר לְמָקוֹם פְּלוֹנִי. הֲרֵי זֶה אָסוּר לְאָכְלָם הַיּוֹם גְּזֵרָה שֶׁמָּא יֵלֵךְ לְמָחָר לְאוֹתוֹ מָקוֹם. וְאִם עָבַר וַאֲכָלָן הַיּוֹם וְהָלַךְ לְמָחָר לוֹקֶה וְאִם לֹא הָלַךְ אֵינוֹ לוֹקֶה:","אָמַר הֲרֵי הֵן אֲסוּרִין לְמָחָר אִם אֵלֶךְ הַיּוֹם לְמָקוֹם פְּלוֹנִי הֲרֵי זֶה מֻתָּר לֵילֵךְ הַיּוֹם לְאוֹתוֹ הַמָּקוֹם וְיֵאָסְרוּ עָלָיו אוֹתָן הַפֵּרוֹת לְמָחָר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. מִפְּנֵי שֶׁאָדָם זָהִיר בְּדָבָר הָאָסוּר שֶׁלֹּא לַעֲשׂוֹתוֹ וְאֵינוֹ זָהִיר בִּתְנַאי שֶׁגּוֹרֵם לֶאֱסֹר דָּבָר הַמֻּתָּר:","הַנּוֹדֵר לָצוּם עֲשָׂרָה יָמִים בְּאֵי זֶה יוֹם שֶׁיִּרְצֶה וְהָיָה מִתְעַנֶּה בְּיוֹם אֶחָד מֵהֶם וְהֻצְרַךְ לִדְבַר מִצְוָה אוֹ מִפְּנֵי כְּבוֹד אָדָם גָּדוֹל הֲרֵי זֶה אוֹכֵל וּפוֹרֵעַ יוֹם אַחֵר שֶׁהֲרֵי לֹא קָבַע הַיָּמִים בִּתְחִלַּת הַנֵּדֶר. נָדַר שֶׁיָּצוּם הַיּוֹם וְשָׁכַח וְאָכַל מַשְׁלִים לָצוּם. נָדַר שֶׁיָּצוּם יוֹם אֶחָד אוֹ שְׁנַיִם וּכְשֶׁהִתְחִיל לָצוּם שָׁכַח וְאָכַל אִבֵּד תַּעֲנִיתוֹ וְחַיָּב לָצוּם יוֹם אַחֵר:"]} as Record<string, string[]>;
